/******************************************************************************/
/***                            Tables and Views                            ***/
/******************************************************************************/

CREATE TABLE APDEPOS0_JUR (
    NUMBER DMDOCNUMBER NOT NULL,
    DEPOSITNO DMDOCNUMBER,
    DOCUMENT DMDOCUMENT,
    OPENDATE DMDATEEDIT,
    STATUS DMSTATUSGL,
    SUPPLIER DMSUPPLIER,
    ACCOUNT DMACCOUNT,
    DEPT DMDEPT DEFAULT '0000',
    COST DMCOST DEFAULT '0000',
    PROJECT DMPROJECT,
    NOTE DMFONOTE,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    FOREX_DB DMDBCR,
    FOREX_CR DMDBCR,
    CURRENCY DMCURRENCY,
    EXCHANGE DMDBCR DEFAULT 1,
    DB DMDBCR,
    CR DMDBCR,
    SOURCE DMCODE4 DEFAULT 'M',
    SOURCENUMBER DMDOCNUMBER);


CREATE TABLE AR_CARD (
    CREDITCARD DMCREDITCARD NOT NULL,
    NAME DMNAME,
    BANK DMBANK,
    FEE DMPERSENT,
    CREATEUSER DMUSER,
    CREATEDATE DMDATEEDIT,
    EDITUSER DMUSER,
    EDITDATE DMDATEEDIT,
    GL_AR_ACCOUNT DMACCOUNT,
    GL_AR_DEPT DMDEPT,
    GL_AR_COST DMCOST,
    GL_FEE_ACCOUNT DMACCOUNT,
    GL_FEE_DEPT DMDEPT,
    GL_FEE_COST DMCOST,
    RELATION_DOCTYPE DMLINE);


CREATE TABLE AR_CARD_BATCH (
    BANK DMBANK NOT NULL,
    OUTLET DMCODE4 NOT NULL,
    BATCH DMDOCNUMBER NOT NULL,
    OPENDATE DMDATEEDIT,
    REMARK DMNAME,
    AMOUNT DMDBCR,
    STATUS DMSTATUSGL,
    PAY_REF DMDOCUMENT,
    PAY_DATE DMDATEEDIT,
    PAY_FEE DMDBCR,
    PAY_TOTAL DMDBCR,
    CREATEUSER DMUSER,
    CREATEDATE DMDATEEDIT,
    EDITUSER DMUSER,
    EDITDATE DMDATEEDIT,
    AMOUNT_FEE DMDBCR,
    CALC_AMOUNT_NET COMPUTED BY (AMOUNT-AMOUNT_FEE),
    NUMBER DMDOCNUMBER,
    RECONCILEDATE DMDATEEDIT,
    DOCUMENT DMDOCUMENT);


CREATE TABLE AR_CARD_JUR (
    NUMBER DMDOCNUMBER NOT NULL,
    BATCH DMDOCNUMBER,
    TRACENO DMDOCNUMBER,
    CREDITCARD DMCREDITCARD,
    OUTLET DMCODE4,
    CARDNUMBER DMNAME,
    REMARK DMNAMEFULL,
    STATUS DMSTATUSGL,
    TOTAL DMDBCR,
    OPENDATE DMDATEEDIT,
    CREATEDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITDATE DMDATEEDIT,
    EDITUSER DMUSER,
    SOURCE DMCODE1 DEFAULT 'M',
    CARD_FEE DMPERSENT DEFAULT 0,
    CALC_FEE COMPUTED BY (total*card_fee/100),
    CALC_NET COMPUTED BY (total-calc_fee),
    BANK DMBANK,
    FO_FOLIO DMFOFOLIO,
    FO_TRANS_ID DMFOJUR_TRANSID,
    PAY_DATE DMDATEEDIT,
    BATCH_NUMBER DMDOCNUMBER,
    GL_ACCOUNT DMACCOUNT,
    GL_DEPT DMDEPT,
    GL_COST DMCOST,
    GLSTATUS DMCODE1);


CREATE TABLE AR_CARD_OUTLET (
    OUTLET DMCODE4 NOT NULL,
    NAME DMNAME,
    CREATEDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITDATE DMDATEEDIT,
    EDITUSER DMUSER);


CREATE TABLE AR_OVERLIMIT (
    FODATE DMFODATE,
    CUSTOMER DMCUSTOMER COLLATE WIN1251,
    NAME DMNAME COLLATE WIN1251,
    LIMIT DMFOGUESTBALANCE,
    DUE DMFOGUESTBALANCE,
    OVERDUE COMPUTED BY (DUE-LIMIT));


CREATE TABLE AR_SUMMARY (
    ARDATE DMDATEEDIT NOT NULL,
    OPENING DMDBCR,
    INVOICE DMDBCR,
    PAYMENT DMDBCR,
    ADJUSTMENT DMDBCR,
    ADJUSTMENT_FO DMDBCR,
    LOSS_GAIN DMDBCR,
    ENDING COMPUTED BY (OPENING+INVOICE-PAYMENT+ADJUSTMENT+ADJUSTMENT_FO),
    PAYMENT_RECEIVED DMDBCR,
    STATUS DMCODE1 DEFAULT 'O',
    LASTUPDATE DMDATEEDIT);


CREATE TABLE AR_ZHIST_AGE (
    ARDATE DMDATEEDIT NOT NULL,
    CUSTOMER DMCUSTOMER NOT NULL COLLATE WIN1251,
    NAME DMNAME COLLATE WIN1251,
    CURR DMFOGUESTBALANCE,
    OVER30 DMFOGUESTBALANCE,
    OVER60 DMFOGUESTBALANCE,
    OVER90 DMFOGUESTBALANCE,
    TOTAL COMPUTED BY (CURR+OVER30+OVER60+OVER90),
    CREDITCARD DMLOGICAL);


CREATE TABLE AR_ZHIST_MUTATION (
    PYEAR INTEGER,
    PMONTH SMALLINT,
    CUSTOMER DMCUSTOMER COLLATE WIN1251,
    NAME DMNAME COLLATE WIN1251,
    CREDITCARD DMLOGICAL,
    OPENING DMDBCR,
    VOUCHER DMDBCR,
    CASH DMDBCR,
    ADJUST DMDBCR,
    DEPOSIT DMDBCR,
    ENDING COMPUTED BY (OPENING+VOUCHER-CASH+ADJUST-DEPOSIT));


CREATE TABLE ARADJ (
    NUMBER DMDOCNUMBER DEFAULT 0 NOT NULL,
    VOUCHERNO DMDOCNUMBER,
    DOCUMENT DMDOCUMENT,
    OPENDATE DMDATEEDIT,
    STATUS DMSTATUSGL,
    CUSTOMER DMCUSTOMER,
    ACCOUNT DMACCOUNT,
    DEPT DMDEPT DEFAULT '0000',
    COST DMCOST DEFAULT '0000',
    PROJECT DMPROJECT,
    NOTE DMFONOTE,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    FOREX_DB DMDBCR,
    FOREX_CR DMDBCR,
    CURRENCY DMCURRENCY,
    EXCHANGE DMDBCR DEFAULT 1,
    DB DMDBCR,
    CR DMDBCR,
    SOURCE DMCODE2,
    SOURCENUMBER DMDOCNUMBER);


CREATE TABLE ARCASH0 (
    NUMBER DMDOCNUMBER NOT NULL,
    DOCUMENT DMDOCUMENT DEFAULT '',
    CHECK_NUMBER DMDOCUMENT DEFAULT '',
    CUSTOMER DMCUSTOMER,
    TOTALCASH DMDBCR,
    TOTAL DMDBCR,
    OPENDATE DMDATEEDIT,
    DUEDATE DMDATEEDIT,
    STATUS DMSTATUSTRANS,
    BANK DMBANK DEFAULT '',
    BBGIRO_APNO DMDOCNUMBER,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    BATCHNO DMDOCNUMBER DEFAULT 0,
    RECONCILEDATE DMDATEEDIT,
    NOTE DMNOTE,
    RECEIVED_DATE DMDATEEDIT,
    CURRENCY DMCURRENCY COLLATE WIN1251,
    EXCHANGE DMDBCR DEFAULT 1,
    FOREX_TOTAL COMPUTED BY (TOTAL/EXCHANGE),
    BB_NUMBER DMDOCNUMBER,
    FOREX_GAINLOSS DMDBCR,
    CREDITCARD DMCREDITCARD,
    CARDNUMBER DMNAME,
    CARDOUTLET DMCODE4,
    ADJ_GL_ACCOUNT DMACCOUNT,
    ADJ_GL_DEPT DMDEPT,
    ADJ_GL_COST DMCOST,
    ADJ_TOTAL DMDBCR DEFAULT 0,
    ADJ_FOREX_TOTAL COMPUTED BY (ADJ_TOTAL/EXCHANGE));


CREATE TABLE ARCASH1 (
    NUMBER DMDOCNUMBER NOT NULL,
    CUSTOMER DMCUSTOMER,
    VOUCHERNO DMDOCNUMBER NOT NULL,
    TEXT1 DMNAME DEFAULT '',
    CURRENCY DMCURRENCY COLLATE WIN1251,
    EXCHANGE DMDBCR DEFAULT 1,
    FOREX_TOTAL DMDBCR,
    TOTAL COMPUTED BY (FOREX_TOTAL*EXCHANGE),
    VCH_EXCHANGE DMDBCR,
    VCH_TOTAL COMPUTED BY (VCH_EXCHANGE*FOREX_TOTAL),
    VCH_GAINLOSS COMPUTED BY (FOREX_TOTAL*(EXCHANGE-VCH_EXCHANGE)));


CREATE TABLE ARCASHBATCH (
    NUMBER DMDOCNUMBER NOT NULL,
    TEXT1 DMNAME,
    COUNTER INTEGER DEFAULT 0,
    TOTALCHECK DMDBCR DEFAULT 0,
    STATUS DMSTATUSGL,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    STARTDATE DMDATEEDIT,
    ENDDATE DMDATEEDIT);


CREATE TABLE ARDEPOS0 (
    NUMBER DMDOCNUMBER NOT NULL,
    OPENDATE DMDATEEDIT,
    DOCUMENT DMDOCUMENT,
    STATUS DMSTATUSGL,
    TOTAL DMDBCR DEFAULT 0,
    APPLIED DMDBCR DEFAULT 0,
    CUSTOMER DMCUSTOMER,
    BANK DMBANK,
    BBGIRO_ARDEPOS DMDOCNUMBER,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
