    EXCHANGE DMFOCHARGE,
    CALC_TOTAL COMPUTED BY (AMOUNT*EXCHANGE),
    CREATEUSER DMUSER,
    CREATEDATE DMDATEEDIT,
    EDITUSER DMUSER,
    EDITDATE DMDATEEDIT,
    STATUS DMCODE1,
    FO_TRANS_ID DMFOJUR_TRANSID,
    FO_FOLIO DMFOFOLIO,
    BUY_AMOUNT COMPUTED BY (CASE BUY_SALE WHEN 'B' THEN AMOUNT ELSE 0 END),
    SALE_AMOUNT COMPUTED BY (CASE BUY_SALE WHEN 'S' THEN AMOUNT ELSE 0 END),
    BUY_TOTAL COMPUTED BY (CASE BUY_SALE WHEN 'B' THEN CALC_TOTAL ELSE 0 END),
    SALE_TOTAL COMPUTED BY (CASE BUY_SALE WHEN 'S' THEN CALC_TOTAL ELSE 0 END),
    SALE_EXCHANGE COMPUTED BY (CASE BUY_SALE WHEN 'S' THEN EXCHANGE ELSE 0 END),
    BUY_EXCHANGE COMPUTED BY (CASE BUY_SALE WHEN 'B' THEN EXCHANGE ELSE 0 END));


