CREATE TABLE FOGUEST_JUR_CASHIER (
    CASHIER_BATCH_ID DMFOJUR_TRANSID NOT NULL,
    USR DMUSER COLLATE WIN1251,
    STATUS DMFOCODE1 COLLATE WIN1251,
    DEBIT DMFOGUESTBALANCE,
    CREDIT DMFOGUESTBALANCE,
    COUNTER DMFOTOTALCOUNT,
    TIMEEND DMFODATE,
    TIMESTART DMFODATE,
    LASTPOST DMFODATE,
    CORRECTION DMFOGUESTBALANCE,
    CORRECTION_COUNT DMFOTOTALCOUNT,
    NEGATIVE DMFOGUESTBALANCE,
    NEGATIVE_COUNT DMFOTOTALCOUNT,
    OPENDEPOSIT DMFOGUESTBALANCE,
    TOTAL_TRANSACTION COMPUTED BY (DEBIT-CREDIT+CORRECTION+NEGATIVE),
    TOTAL_COUNTER COMPUTED BY (COUNTER+CORRECTION_COUNT+NEGATIVE_COUNT),
    DATESTART DMFODATE,
    DATEEND DMFODATE,
    TRANSFER_DB DMFOGUESTBALANCE,
    TRANSFER_CR DMFOGUESTBALANCE,
    TRANSFER_COUNT DMFOTOTALCOUNT,
    CASH_ACTUAL DMFOGUESTBALANCE,
    CASH_CREDIT DMFOGUESTBALANCE,
    CASH_DEBIT DMFOGUESTBALANCE,
    CASH_DB_COUNTER DMFOTOTALCOUNT,
    CASH_CR_COUNTER DMFOTOTALCOUNT,
    CASH_ENDING COMPUTED BY (OPENDEPOSIT+CASH_CREDIT-CASH_DEBIT),
    CASH_COUNTER COMPUTED BY (CASH_DB_COUNTER+CASH_CR_COUNTER),
    CLOSE_BY DMUSER COLLATE WIN1251,
    CLOSE_REMARK DMNOTE,
    CLOSE_DATE DMFODATE,
    CASH_OVERSHORT COMPUTED BY (CASH_ACTUAL-CASH_ENDING));


