    GUESTNAME DMMB_FULLNAME COLLATE WIN1251,
    STATUS DMMB_STATUS COLLATE WIN1251,
    TOTAL_TAX1 DMMB_PRICE DEFAULT 0,
    TOTAL_TAX2 DMMB_PRICE DEFAULT 0,
    TOTAL_TAX3 DMMB_PRICE DEFAULT 0,
    TOTAL_TAX4 DMMB_PRICE DEFAULT 0,
    CALC_TOTAL COMPUTED BY (TOTAL+TOTAL_TAX1+TOTAL_TAX2+TOTAL_TAX3+TOTAL_TAX4),
    FOLIO DMFOFOLIO,
    CALC_YEAR COMPUTED BY (EXTRACT(YEAR FROM MBDATE)),
    CALC_MONTH COMPUTED BY (EXTRACT(MONTH FROM MBDATE)));


CREATE TABLE MB_TRANS_DET (
    NUMBER DMMB_NUMBER NOT NULL,
    ITEM DMMB_ITEM NOT NULL COLLATE WIN1251,
    QTY DMMB_QTY,
    PRICE DMMB_PRICE,
    CALC_PRICE COMPUTED BY (QTY*PRICE),
    TAX_1 DMMB_PERCENT DEFAULT 0,
    TAX_2 DMMB_PERCENT DEFAULT 0,
    TAX_3 DMMB_PERCENT DEFAULT 0,
    TAX_4 DMMB_PERCENT DEFAULT 0,
    CALC_TAX1 COMPUTED BY (CALC_PRICE*TAX_1/100),
    CALC_TAX2 COMPUTED BY (CALC_PRICE*TAX_2/100),
    CALC_TAX3 COMPUTED BY (CALC_PRICE*TAX_3/100),
    CALC_TAX4 COMPUTED BY (CALC_PRICE*TAX_4/100));


