  NEW.NUMBER = GEN_ID(GEN_AR_CARD_BATCH,1);
END
^

CREATE TRIGGER AR_CARD_BATCH_BU FOR AR_CARD_BATCH
ACTIVE BEFORE UPDATE POSITION 3
as
begin
  IF ((OLD.BANK <> NEW.BANK) OR (OLD.BATCH <> NEW.BATCH) OR
      (OLD.OUTLET <> NEW.OUTLET) OR (OLD.OPENDATE <> NEW.OPENDATE)) THEN
  BEGIN
     IF (EXISTS (SELECT * FROM AR_CARD_JUR where batch = old.batch
                  and bank = old.bank and outlet = old.outlet)) THEN
     EXCEPTION AR_CREDIT_CARD_BATCH_DELETE;
  END
  
  /* ---------------------------------------------------------------- */
  /* 24 JULY 2008                                                     */
  /* PAYMENT DATE HARUS >= OPENDATW                                   */
  /* ---------------------------------------------------------------- */
  IF (NEW.STATUS IN ('R','C','L')) THEN
  BEGIN
     IF (NEW.PAY_DATE < NEW.OPENDATE) THEN
        EXCEPTION ALL_DATE_ERROR;
  END
  /* ---------------------------------------------------------------- */
  /* END OF 24 JULY 2008                                              */
  /* ---------------------------------------------------------------- */
end
^

CREATE TRIGGER AR_CARD_BATCH_BU_DOCUMENT FOR AR_CARD_BATCH
ACTIVE BEFORE UPDATE POSITION 3
as
DECLARE VARIABLE DOCTYPE INTEGER;
DECLARE VARIABLE FLAG_DOCTYPE_ACTIVE INTEGER;
begin
  SELECT FLAG_DOCTYPE_ACTIVE FROM FOSYSPARAM
  INTO FLAG_DOCTYPE_ACTIVE;
  
  IF ((FLAG_DOCTYPE_ACTIVE = 1) AND (NEW.STATUS <> 'O') AND (OLD.STATUS = 'R')) THEN
  BEGIN
     SELECT RELATION_DOCTYPE FROM SYSBANK
     WHERE BANK = NEW.BANK INTO DOCTYPE;
     IF (DOCTYPE IS NULL) THEN DOCTYPE = 0;
  
     EXECUTE PROCEDURE SP_DOCUMENT_NUMBER('AR','BREV',DOCTYPE, NEW.OPENDATE,1)
     RETURNING_VALUES NEW.DOCUMENT;
  END

end
^

CREATE TRIGGER AR_CARD_BATCH_BU_RECALC FOR AR_CARD_BATCH
ACTIVE BEFORE UPDATE POSITION 0
AS
DECLARE VARIABLE JUR_DATE DATE;
BEGIN
  IF (NEW.AMOUNT_FEE = -1) THEN
  BEGIN
     /* ---------------------------------------------------------------- */
     /* 6 AGUSTUS 2007                                                   */
     /* RECONSTRUCT BATCH_NUMBER & PAID DATE                             */
     /* OPEN DATE                                                        */
     /* ---------------------------------------------------------------- */
     
     SELECT MAX(OPENDATE) FROM AR_CARD_JUR
     WHERE BANK = OLD.BANK AND BATCH = OLD.BATCH AND OUTLET = OLD.OUTLET
     INTO JUR_DATE;
     
     IF (JUR_DATE IS NOT NULL) THEN
        IF (NEW.OPENDATE < JUR_DATE) THEN NEW.OPENDATE = JUR_DATE;
     
     IF (NEW.PAY_DATE < NEW.OPENDATE) THEN NEW.PAY_DATE = NEW.OPENDATE;

     /* ---------------------------------------------------------------- */
     /* UPDATE BATCH_NUMBER & PAID_DATE                                  */
     /* ---------------------------------------------------------------- */
     

     UPDATE AR_CARD_JUR SET BATCH_NUMBER = NEW.NUMBER, PAY_DATE = NEW.PAY_DATE
     WHERE BANK = OLD.BANK AND BATCH = OLD.BATCH AND OUTLET = OLD.OUTLET;


     /* ---------------------------------------------------------------- */
     /* END OF 6 AGUSTUS 2007                                            */
     /* ---------------------------------------------------------------- */
     

     SELECT SUM(TOTAL), SUM(CALC_FEE) FROM AR_CARD_JUR
     WHERE BANK = OLD.BANK AND BATCH = OLD.BATCH AND OUTLET = OLD.OUTLET
     INTO NEW.AMOUNT, NEW.AMOUNT_FEE;
     IF (NEW.AMOUNT IS NULL) THEN
     BEGIN
        NEW.AMOUNT = 0;
        NEW.AMOUNT_FEE = 0;
     END
  END
END
^

CREATE TRIGGER AR_CARD_BATCH_RELEASE FOR AR_CARD_BATCH
ACTIVE AFTER UPDATE POSITION 0
as
DECLARE VARIABLE ID INTEGER;
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE NOTE VARCHAR(40);
DECLARE VARIABLE REFF VARCHAR(20);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
DECLARE VARIABLE RELATION_CODE VARCHAR(6);
DECLARE VARIABLE RELATION_DOCTYPE INTEGER;
/* 20 SEPTEMBER 2005 */
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE CREDITCARD VARCHAR(6);
/* 8/15/2011 READY FOR MULTI CURRENCY */
DECLARE VARIABLE CURRENCY VARCHAR(4);
begin
  if ((new.status = 'R') and (old.status = 'O')) then begin

     update ar_card_jur set status = 'C', PAY_DATE = NEW.PAY_DATE
     where batch = old.batch
     and bank = old.bank
     and outlet = old.outlet;

     FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, REF, DEBIT, CREDIT, RELATION_CODE, RELATION_DOCTYPE
         FROM AR_GLBUFFER_CC_BATCH_RELEASE(NEW.NUMBER)
         INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
              NOTE, REFF, DB, CR, RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
        values ('AR','CCPY', old.number, :ID, old.opendate,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :NOTE, :REFF,
                :DB, :CR,
                'now', NEW.EDITUSER, :RELATION_CODE, :RELATION_DOCTYPE);
     END

  end
  /* ------------------------------------------------------------------------ */
  /* RECONCILE                                                                */
  /* ------------------------------------------------------------------------ */
  if ((new.status = 'C') and (old.status = 'L')) then begin
     select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare from sysbank
     where bank = old.bank
     into GL_ACCOUNT, GL_DEPT, GL_COST;
     /* --------------------------------------------------------------------- */
     /* 10 SEPTEMBER 2005                                                     */
     /* --------------------------------------------------------------------- */
     NOTE = '';
     I = 0;
     FOR SELECT CREDITCARD FROM AR_CARD_JUR
         where batch = old.batch
         and bank = old.bank
         and outlet = old.outlet
         GROUP BY CREDITCARD
         INTO CREDITCARD
     DO BEGIN
        IF (I = 0) THEN NOTE = CREDITCARD;
        ELSE IF (I < 5) THEN NOTE = NOTE || ', ' || CREDITCARD;
        I = I + 1;
     END
     /* --------------------------------------------------------------------- */
     /* HAPUS TRANSAKSI YANG PERNAH DI EXPORT                                 */
     /* --------------------------------------------------------------------- */
     DELETE FROM BBJUR WHERE APPLICATION = 'AR' AND SOURCE = 'CREC'
            AND SOURCENUMBER = NEW.NUMBER;

     SELECT CURRENCY FROM SYSBANK WHERE BANK = NEW.BANK INTO CURRENCY; /* 8/15/2011 READY FOR MULTI CURRENCY */

     INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
     VALUES           (0, NEW.BANK, new.RECONCILEDATE, 0, 'T', NEW.PAY_REF,
                       'AR', :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        0, old.CALC_AMOUNT_NET,
                        :NOTE, new.pay_ref,
                        :CURRENCY, 1,
                        'AR', 'CREC', NEW.NUMBER, 0,
                        NEW.EDITUSER, 'NOW', NEW.EDITUSER, 'NOW');
  end
   /* 23 JANUARY 2006 */
   IF ((NEW.STATUS = 'L') AND (OLD.STATUS <> 'L') AND (NEW.OPENDATE > NEW.RECONCILEDATE )) THEN
      EXCEPTION ALL_DATE_ERROR;
end
^

