CREATE TRIGGER AR_CARD_JUR_BI_CCARD FOR AR_CARD_JUR
ACTIVE BEFORE INSERT POSITION 9
AS
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE CURRENCY VARCHAR(4);
BEGIN
  IF (NEW.SOURCE = 'V') THEN
  BEGIN
     IF (NOT EXISTS (SELECT * FROM ARVCH WHERE NUMBER = NEW.FO_FOLIO)) THEN
        EXCEPTION AR_VCHR_NOT_EXIST;
        
     SELECT GL_AR_ACCOUNT, GL_AR_DEPT, GL_AR_COST FROM AR_CARD
     WHERE CREDITCARD = NEW.CREDITCARD
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;
     
     SELECT CUSTOMER, CURRENCY FROM ARVCH WHERE NUMBER = NEW.FO_FOLIO INTO CUSTOMER, CURRENCY;
     
     INSERT INTO ARADJ
     (VOUCHERNO, DOCUMENT, OPENDATE, STATUS, CUSTOMER,
      ACCOUNT, DEPT, COST, PROJECT, NOTE,
      CREATEDATE, EDITDATE, CREATEUSER, EDITUSER,
      FOREX_DB, FOREX_CR, CURRENCY, EXCHANGE,
      SOURCE, SOURCENUMBER)
     VALUES
     (NEW.FO_FOLIO, NEW.CREDITCARD, NEW.OPENDATE, 'O', :CUSTOMER,
      :GL_ACCOUNT, :GL_DEPT, :GL_COST, '', 'Paid by Credit Card',
      'NOW', 'NOW', NEW.CREATEUSER, NEW.CREATEUSER,
      0, NEW.TOTAL, :CURRENCY, 1,
      'CC', NEW.NUMBER);
  END
  
END
^

CREATE TRIGGER AR_CARD_JUR_BU FOR AR_CARD_JUR
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vRow INTEGER;
begin
  if (old.status <> 'O') then /* 9 Des 2009 */
  begin
     IF ((NEW.OPENDATE <> OLD.OPENDATE) OR 
         (NEW.TOTAL <> OLD.TOTAL) OR
         (NEW.OUTLET <> OLD.OUTLET) OR
         (NEW.BATCH <> OLD.BATCH) OR
         (NEW.CREDITCARD <> OLD.CREDITCARD) OR
         (NEW.CARD_FEE <> OLD.CARD_FEE)) THEN
        exception all_doc_status_not_open;
  end

  if ((old.creditcard <> new.creditcard) and (old.batch <> 0)) then
     exception AR_CREDIT_CARD_CHANGE;
     
  select fee, bank from ar_card
  where creditcard = new.creditcard
  into new.card_fee, new.bank;
  if (not ((new.status = 'C') and (old.status = 'O'))) then
  if (new.batch <> old.batch) then
  begin
     if  (new.batch = 0) then /* REMOVE FROM BATCH */
     begin
         NEW.BATCH_NUMBER = 0;
         update ar_card_batch set amount = amount - old.total,
                amount_fee = amount_fee-old.calc_fee
         where bank = old.bank and batch = old.batch and outlet = old.outlet;
     end
     else
     begin /* LOAD INTO BATCH */
        IF (NOT EXISTS(select * from ar_card_batch
                where bank = new.bank and batch = new.batch and outlet = new.outlet)) THEN
        exception ar_credit_card_batch_not_exist;

        select fee from ar_card where creditcard = new.creditcard into new.card_fee;

        SELECT NUMBER FROM AR_CARD_BATCH
        where bank = new.bank and batch = new.batch and outlet = new.outlet
        INTO NEW.BATCH_NUMBER;
                 
        update ar_card_batch set amount = amount + new.total,
               amount_fee = amount_fee+new.calc_fee
        where bank = new.bank and batch = new.batch and outlet = new.outlet;
     end
  end
  else
  begin
    IF (OLD.BATCH <> 0) THEN /* CREDIT CARD CHANGE WHEN ALREDY IN THE BATCH */
    BEGIN
      IF ((new.total <> old.total) OR (new.calc_fee <> old.calc_fee)) THEN
         update ar_card_batch set amount = amount + new.total-old.total,
               amount_fee = amount_fee+new.calc_fee-old.calc_fee
         where bank = new.bank and batch = new.batch and outlet = new.outlet;
    END
  end
end
^

