CREATE TRIGGER AR_CARD_JUR_BU_SPLIT FOR AR_CARD_JUR
ACTIVE BEFORE UPDATE POSITION 3
as
DECLARE VARIABLE REMARK VARCHAR(80);
begin
  IF ((NEW.TOTAL < OLD.TOTAL) AND (OLD.BATCH = 0) AND (NEW.STATUS = 'Z') AND (OLD.STATUS = 'O')) THEN
  BEGIN
     REMARK = SUBSTR(NEW.REMARK, 1,60) || ' Splited from No ' || OLD.NUMBER;
     NEW.STATUS = 'O';
     INSERT INTO AR_CARD_JUR (BATCH, TRACENO, CREDITCARD, OUTLET, CARDNUMBER,
                 REMARK, STATUS, TOTAL, OPENDATE,
                 CREATEDATE,CREATEUSER, EDITDATE,EDITUSER,
                 SOURCE, CARD_FEE, BANK,
                 FO_FOLIO, FO_TRANS_ID,
                 GL_ACCOUNT, GL_DEPT, GL_COST, GLSTATUS)
     VALUES (NEW.BATCH, NEW.TRACENO, NEW.CREDITCARD, NEW.OUTLET, NEW.CARDNUMBER,
             :REMARK, NEW.STATUS, OLD.TOTAL- NEW.TOTAL,
             NEW.OPENDATE, 'NOW', NEW.EDITUSER, 'NOW',
             NEW.EDITUSER, NEW.SOURCE, NEW.CARD_FEE, NEW.BANK,
             NEW.FO_FOLIO, NEW.FO_TRANS_ID,
             NEW.GL_ACCOUNT, NEW.GL_DEPT, NEW.GL_COST, NEW.GLSTATUS);
  END
  IF ((NEW.STATUS NOT IN ('O','C')) AND (NEW.GLSTATUS = OLD.GLSTATUS)) THEN /* 9 Des 2009 */
     EXCEPTION AR_CARD_JUR_INVALID_STATUS;
end
^

