CREATE TRIGGER AR_ZHIST_MUTATION_AI FOR AR_ZHIST_MUTATION
ACTIVE AFTER INSERT POSITION 0
as
declare variable VYEAR INTEGER;
declare variable VMONTH INTEGER;
begin
  VMONTH = NEW.PMONTH+1;
  VYEAR = NEW.PYEAR;
  if (VMONTH > 12) then BEGIN
     VMONTH = 1;
     VYEAR = VYEAR+1;
  END
  UPDATE AR_ZHIST_MUTATION
  SET OPENING = NEW.ENDING
  where pyear = :vyear
  and pmonth = :vmonth
  and customer = new.customer;
end
^

