CREATE TRIGGER AR_ZHIST_MUTATION_BI FOR AR_ZHIST_MUTATION
ACTIVE BEFORE INSERT POSITION 0
as
declare variable VYEAR INTEGER;
declare variable VMONTH INTEGER;
begin
  VMONTH = NEW.PMONTH-1;
  VYEAR = NEW.PYEAR;
  if (VMONTH < 1) then BEGIN
     VMONTH = 12;
     VYEAR = VYEAR-1;
  END
  select ending from AR_ZHIST_MUTATION
  where pyear = :vyear
  and pmonth = :vmonth
  and customer = new.customer
  into new.opening;
  
  if (new.opening is null) then
     new.opening = 0;
end
