CREATE TRIGGER ARADJ_BDELETE FOR ARADJ
ACTIVE BEFORE DELETE POSITION 0
as
DECLARE VARIABLE CC_BATCH INTEGER;
begin
  if (old.status <> 'D') then
  begin
     if (old.status <> 'O') then EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
        
     /* 8 OCTOBER 2005 */
     IF (OLD.SOURCE = 'CC') THEN
     BEGIN
        IF (NOT EXISTS(SELECT * FROM AR_CARD_JUR WHERE NUMBER = OLD.SOURCENUMBER )) THEN
           EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
           
        SELECT BATCH FROM AR_CARD_JUR WHERE NUMBER = OLD.SOURCENUMBER INTO CC_BATCH;
        IF ((CC_BATCH IS NULL) OR (CC_BATCH <> 0)) THEN EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
        
        DELETE FROM AR_CARD_JUR WHERE NUMBER = OLD.SOURCENUMBER;
     END
     /* 8 OCTOBE 2005 */
     
     /* ---------------------------------------------------------------- */
     /* 4 MARET 2008                                                     */
     /* GAIN & LOSS CURRENCY PADA AKHIR BULAN                            */
     /* ---------------------------------------------------------------- */
     IF (OLD.SOURCE = 'RE') THEN
     BEGIN
        UPDATE ARVCH SET FOREX_GAINLOSS = FOREX_GAINLOSS - (OLD.DB-OLD.CR)
        WHERE NUMBER = OLD.VOUCHERNO;
     END
     ELSE
     BEGIN
        UPDATE ARVCH SET ADJUST = ADJUST - (OLD.DB-OLD.CR),
               FOREX_ADJUST = FOREX_ADJUST - (OLD.FOREX_DB-OLD.FOREX_CR)
        WHERE NUMBER = OLD.VOUCHERNO;
     END
     /* ---------------------------------------------------------------- */
     /* END OF 4 MARET 2008                                              */
     /* ---------------------------------------------------------------- */
  end
  else
     insert into ARPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT,
                          OPENDATE, DUEDATE, SOURCENUMBER, TOTAL,
                          CUSTOMER, NOTE, DELETEDATE, DELETEUSER)
     values
       (old.voucherno, old.number, 'ADJ', old.document,
       old.opendate, old.opendate, 0, old.db-old.cr,
       old.CUSTOMER, old.NOTE, 'now', user);
end
^

CREATE TRIGGER ARADJ_BINSERT FOR ARADJ
ACTIVE BEFORE INSERT POSITION 0
as

declare variable vSysDate date;
declare variable VchDate DATE;
/* 11 AGUSTUS 2005 */
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_DEPT VARCHAR(4);
declare variable GL_COST VARCHAR(4);
begin
  new.status = 'O';
  select arsysdate from fosysparam into :vSysDate;
  if (new.opendate < :vSysDate) then
     exception all_date_error;

  select V.CUSTOMER, V.opendate, V.CURRENCY, T.GLACCOUNT, T.GLDEPT, T.GLCOST from ARVCH V
    left join SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
    left join syscustomertype t on t.customertype = C.CUSTTYPE
   where V.number = new.voucherno
   into NEW.CUSTOMER, :VchDate, NEW.CURRENCY, GL_ACCOUNT, GL_DEPT, GL_COST;
  /* 11 AGUSTUS 2005 */
   IF ((NEW.ACCOUNT = GL_ACCOUNT) AND (NEW.DEPT = GL_DEPT) AND (NEW.COST = GL_COST)) THEN
      EXCEPTION AR_ADJUSTMENT_ITSELF;
   /* END OF 11 AGUSTUS 2005 */
  IF ((NEW.EXCHANGE < 1) OR (NEW.EXCHANGE IS NULL)) THEN /* 14 JUN 2005 */
      SELECT EXCHANGE_NOW FROM ARVCH /* 20 SEP 2008, DIUBAH SETELAH ADA REVALUATION*/
      WHERE NUMBER = NEW.VOUCHERNO INTO NEW.EXCHANGE;
  IF ((NEW.EXCHANGE < 1) OR (NEW.EXCHANGE IS NULL)) THEN
      SELECT EXCHANGE FROM ARVCH /* 20 SEP 2008, DIUBAH SETELAH ADA REVALUATION*/
      WHERE NUMBER = NEW.VOUCHERNO INTO NEW.EXCHANGE;
   
  if (new.opendate < :VchDate ) then
      exception ar_date_less_than_voucher;
      
  if (new.number = 0) then
  begin
     select Max(number) from ARADJ into new.number;
     if (new.number is null) then new.number = 1;
     else
     new.number = new.number+1;
  end

  /* ---------------------------------------------------------------- */
  /* 4 MARET 2008                                                     */
  /* EXCHANGE RATE LOSS & GAIN AT THE END OF MONTH                    */
  /* ---------------------------------------------------------------- */
  IF (NEW.SOURCE = 'RE') THEN
  BEGIN
     NEW.FOREX_DB = 0;
     NEW.FOREX_CR = 0;
     NEW.EXCHANGE = 1;
     
     UPDATE ARVCH SET
       FOREX_GAINLOSS  = FOREX_GAINLOSS  + (NEW.DB-NEW.CR)
     WHERE NUMBER = NEW.VOUCHERNO;
  END
  ELSE
  BEGIN
     NEW.DB = NEW.FOREX_DB * NEW.EXCHANGE;
     NEW.CR = NEW.FOREX_CR * NEW.EXCHANGE;
     
     UPDATE ARVCH SET
       ADJUST = ADJUST  + (NEW.DB-NEW.CR),
       FOREX_ADJUST = FOREX_ADJUST  + (NEW.FOREX_DB-NEW.FOREX_CR)
     WHERE NUMBER = NEW.VOUCHERNO;
  END
  /* ---------------------------------------------------------------- */
  NEW.CREATEDATE = 'NOW';

end
^

CREATE TRIGGER ARADJ_BU_CREDITCARD FOR ARADJ
ACTIVE BEFORE UPDATE POSITION 0
AS
DECLARE VARIABLE CREDITCARD VARCHAR(6);
