^

CREATE TRIGGER ARADJ_BUPDATE FOR ARADJ
ACTIVE BEFORE UPDATE POSITION 1
as

declare variable vSysDate date;
declare variable VchDate DATE;
/* 11 AGUSTUS 2005 */
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_DEPT VARCHAR(4);
declare variable GL_COST VARCHAR(4);
begin
  /* -------------------------------------------------------------------- */
  /* 6/11/2011                                                            */
  /* -------------------------------------------------------------------- */
  IF (NOT EXISTS(SELECT * FROM ARVCH WHERE NUMBER = NEW.VOUCHERNO AND CUSTOMER = NEW.CUSTOMER)) THEN
     EXCEPTION AR_CUSTOMER_NOT_MATCH 'Invoice''s #'||NEW.VOUCHERNO||' Customer IS NOT "'||NEW.CUSTOMER||'"';
  /* -------------------------------------------------------------------- */
     
  IF (old.Status = 'O' and new.status = 'O') THEN
  begin

    select arsysdate from fosysparam into :vSysDate;
    if (new.opendate < :vSysDate) then exception all_date_error;
    
  select V.CUSTOMER, V.opendate, V.CURRENCY, T.GLACCOUNT, T.GLDEPT, T.GLCOST from ARVCH V
    left join SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
    left join syscustomertype t on t.customertype = C.CUSTTYPE
   where V.number = new.voucherno
   into NEW.CUSTOMER, :VchDate, NEW.CURRENCY, GL_ACCOUNT, GL_DEPT, GL_COST;
   /* 11 AGUSTUS 2005 */
   IF ((NEW.ACCOUNT = GL_ACCOUNT) AND (NEW.DEPT = GL_DEPT) AND (NEW.COST = GL_COST)) THEN
      EXCEPTION AR_ADJUSTMENT_ITSELF;
   /* END OF 11 AGUSTUS 2005 */
  IF ((NEW.EXCHANGE < 1) OR (NEW.EXCHANGE IS NULL)) THEN /* 14 JUN 2005 */
      SELECT EXCHANGE_NOW FROM ARVCH /* 20 SEP 2008, DIUBAH SETELAH ADA REVALUATION*/
      WHERE NUMBER = NEW.VOUCHERNO INTO NEW.EXCHANGE;
  IF ((NEW.EXCHANGE < 1) OR (NEW.EXCHANGE IS NULL)) THEN
      SELECT EXCHANGE FROM ARVCH /* 20 SEP 2008, DIUBAH SETELAH ADA REVALUATION*/
      WHERE NUMBER = NEW.VOUCHERNO INTO NEW.EXCHANGE;
   

    if (new.opendate < :VchDate) then exception ar_date_less_than_voucher;
    
    /* ---------------------------------------------------------------- */
    /* 4 MARET 2008                                                     */
    /* EXCHANGE RATE LOSS & GAIN AT THE END OF MONTH                    */
    /* ---------------------------------------------------------------- */
    IF (NEW.SOURCE = 'RE') THEN
    BEGIN
       NEW.FOREX_DB = 0;
       NEW.FOREX_CR = 0;
       NEW.EXCHANGE = 1;

       UPDATE ARVCH SET FOREX_GAINLOSS = FOREX_GAINLOSS  + (NEW.DB-NEW.CR) - (OLD.DB-OLD.CR)
       WHERE NUMBER = NEW.VOUCHERNO;
    END
    ELSE
    BEGIN
       NEW.DB = NEW.FOREX_DB * NEW.EXCHANGE;
       NEW.CR = NEW.FOREX_CR * NEW.EXCHANGE;

       UPDATE ARVCH SET ADJUST = ADJUST  + (NEW.DB-NEW.CR) - (OLD.DB-OLD.CR),
              FOREX_ADJUST = FOREX_ADJUST  + (NEW.FOREX_DB-NEW.FOREX_CR) - (OLD.FOREX_DB-OLD.FOREX_CR)
       WHERE NUMBER = NEW.VOUCHERNO;
    END
    /* ---------------------------------------------------------------- */
  end
  ELSE
     /* jika "STATUS" bukan "O" -> "R" (release)
                            "R" -> "C" (end of day)
     */
     if (not ((old.status IN ('C', 'R', 'O')) and (new.status = 'D'))) then
     begin
       IF (NOT ((old.status = 'O' AND new.status = 'R')  OR
                (old.status = 'O' AND new.status = 'C')  OR
                (old.status = 'R' AND new.status = 'C'))) THEN
          EXCEPTION DOCUMENT_IS_NOT_OPEN 'A/R Adjustment #'||NEW.NUMBER||''' Status is not Open ('||NEW.STATUS||')';
     end
end
^

CREATE TRIGGER ARADJ_POST_GL FOR ARADJ
ACTIVE AFTER UPDATE POSITION 0
as
DECLARE VARIABLE ID INTEGER;
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE NOTE VARCHAR(40);
DECLARE VARIABLE REFF VARCHAR(20);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
DECLARE VARIABLE RELATION_CODE VARCHAR(6);
DECLARE VARIABLE RELATION_DOCTYPE INTEGER;
begin
  if ((old.status <> 'R') AND (new.status = 'R')) then
  begin
     FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, REF, DEBIT, CREDIT, RELATION_CODE, RELATION_DOCTYPE
         FROM AR_GLBUFFER_ADJ_RELEASE(NEW.NUMBER)
         INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
              NOTE, REFF, DB, CR, RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
        values ('AR','ADJ', old.number, :ID, old.opendate,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :NOTE, :REFF,
                :DB, :CR,
                'now', NEW.EDITUSER, :RELATION_CODE, :RELATION_DOCTYPE);
     END
  end
end
^

