CREATE TRIGGER ARCASH0_BU_CHECK_BANK_OR_CARD FOR ARCASH0
ACTIVE BEFORE UPDATE POSITION 1
AS
BEGIN
  /* ----------------------------------------------------------------*/
  /* 9 OCTOBER 2005                                                  */
  /* ----------------------------------------------------------------*/
  IF (NEW.BANK IS NULL) THEN NEW.BANK = '';
  IF (NEW.CREDITCARD IS NULL) THEN NEW.CREDITCARD = '';
  IF (NEW.BANK <> '') THEN
  BEGIN
     NEW.CREDITCARD = '';
     IF (NOT EXISTS(SELECT * FROM SYSBANK WHERE BANK = NEW.BANK)) THEN
        EXCEPTION AR_BANK_NOT_DEFINE;
  END
  ELSE
  BEGIN
     NEW.BANK = '';
     IF (NOT EXISTS(SELECT * FROM AR_CARD WHERE CREDITCARD = NEW.CREDITCARD)) THEN
        EXCEPTION AR_CREDIT_CARD_NOT_EXISTS;

     SELECT B.CURRENCY FROM AR_CARD C
     LEFT JOIN SYSBANK B ON B.BANK = C.BANK
     WHERE C.CREDITCARD = NEW.CREDITCARD
     INTO NEW.CURRENCY;
     NEW.EXCHANGE = 1;
  END
  IF (OLD.STATUS <> 'O') THEN
  BEGIN
     NEW.OPENDATE = OLD.OPENDATE;
     NEW.BANK = OLD.BANK;
     NEW.CREDITCARD = OLD.CREDITCARD;
     NEW.CARDNUMBER = OLD.CARDNUMBER;
     NEW.CARDOUTLET = OLD.CARDOUTLET;
     NEW.CURRENCY = OLD.CURRENCY;
     NEW.EXCHANGE = OLD.EXCHANGE;
     NEW.DOCUMENT = OLD.DOCUMENT;
     NEW.CUSTOMER = OLD.CUSTOMER;
  END
END
