DECLARE VARIABLE FLAG_DOCTYPE_ACTIVE INTEGER;
begin
  SELECT FLAG_DOCTYPE_ACTIVE FROM FOSYSPARAM
  INTO FLAG_DOCTYPE_ACTIVE;
  
  IF ((FLAG_DOCTYPE_ACTIVE = 1) AND (NEW.STATUS <> 'O') AND (OLD.STATUS = 'R')) THEN
  BEGIN
     SELECT RELATION_DOCTYPE FROM SYSCUSTOMER
     WHERE CUSTOMER = NEW.CUSTOMER INTO DOCTYPE;
     IF (DOCTYPE IS NULL) THEN DOCTYPE = 0;
  
