CREATE TRIGGER ARCASH0_BU_RECALC FOR ARCASH0
ACTIVE BEFORE UPDATE POSITION 10
AS
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE GAINLOSS DOUBLE PRECISION;
BEGIN

  IF (NEW.ADJ_TOTAL IS NULL) THEN NEW.ADJ_TOTAL = 0; /* 9/21/2011 */
  /* 31-OCT-2003*/
  IF (NEW.TOTAL = -1) THEN
  BEGIN
     SELECT SUM(TOTAL), SUM(VCH_GAINLOSS) FROM ARCASH1
     WHERE NUMBER = NEW.NUMBER
     INTO TOTAL, GAINLOSS;

     IF (TOTAL IS NULL) THEN
     BEGIN
        TOTAL = 0;
        GAINLOSS = 0;
     END
     IF (NEW.TOTAL <> TOTAL) THEN NEW.TOTAL = NEW.ADJ_TOTAL + TOTAL; /* 9/21/2011 TAMBAH ADJUSMTNET*/
     IF (NEW.FOREX_GAINLOSS <> GAINLOSS) THEN NEW.FOREX_GAINLOSS = GAINLOSS;
  END
END
