CREATE TRIGGER ARCASH0_BU_RELEASE_CREDITCARD FOR ARCASH0
ACTIVE BEFORE UPDATE POSITION 11
AS
DECLARE VARIABLE BANK VARCHAR(4);
/* 25 AUG 2010 */
DECLARE VARIABLE GL_ACCOUNT VARCHAR (20);
DECLARE VARIABLE GL_DEPT VARCHAR (4);
DECLARE VARIABLE GL_COST VARCHAR (4);
BEGIN
  IF ((OLD.STATUS = 'O') AND (NEW.STATUS IN ('R','C')) AND (NEW.CREDITCARD <>'')) THEN
  BEGIN
    SELECT BANK FROM AR_CARD WHERE CREDITCARD = NEW.CREDITCARD INTO BANK;
    /* -------------------------------------------------------------------- */
    /* 25 AUG 2010                                                          */
    /* -------------------------------------------------------------------- */
    SELECT T.GLACCOUNT, T.GLDEPT, T.GLCOST
    FROM SYSCUSTOMER C
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE=C.CUSTTYPE
    WHERE C.CUSTOMER = NEW.CUSTOMER
    INTO GL_ACCOUNT, GL_DEPT, GL_COST;
    /* -------------------------------------------------------------------- */
    
    INSERT INTO AR_CARD_JUR (
             CREDITCARD,
             CARDNUMBER,
             REMARK,
             STATUS,
             TOTAL,
             OPENDATE,
             CREATEDATE,
             CREATEUSER,
             EDITDATE,
             EDITUSER,
             SOURCE,
             FO_FOLIO,
             BANK,
             OUTLET,
             GLSTATUS, GL_ACCOUNT, GL_DEPT, GL_COST) /* 25 AUG 2010 */
      VALUES (
             NEW.CREDITCARD,
             NEW.CARDNUMBER,
             'A/R Cash by Credit Card',
             'O',
             NEW.TOTAL,
             NEW.OPENDATE,
             'NOW',
             NEW.EDITUSER,
             'NOW',
             NEW.EDITUSER,
             'C',
             NEW.NUMBER,
             :BANK,
             NEW.CARDOUTLET,
             'O', :GL_ACCOUNT, :GL_DEPT, :GL_COST); /* 25 AUG 2010 */
  END
END
