CREATE TRIGGER ARCASH0_BUPDATE FOR ARCASH0
ACTIVE BEFORE UPDATE POSITION 9
as
declare variable vSysDate date;
declare variable vRow integer;
declare variable vVoucherNo INTEGER;
declare variable vTotal DOUBLE PRECISION;
declare variable vForex_Total DOUBLE PRECISION;
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable vARBANK_TRANSIENT_ACTIVE integer;
declare variable D INTEGER;
declare variable M INTEGER;
declare variable Y INTEGER;
declare variable VOUCHER_DATE DATE;
DECLARE VARIABLE VOUCHER_CURRENCY VARCHAR(4);
DECLARE VARIABLE FLAG_ARCASH_DUE_EQ_OPEN INTEGER;
begin
  NEW.EDITDATE = 'NOW';
  select ARBANK_TRANSIENT_ACTIVE,arsysdate, FLAG_ARCASH_DUE_EQ_OPEN from fosysparam
  into :vARBANK_TRANSIENT_ACTIVE, :vSysDate, FLAG_ARCASH_DUE_EQ_OPEN;
  /* -------------------------------------------------------------------- */
  IF (NEW.BANK IS NULL) THEN NEW.BANK = ''; /* 12 Aug 2010 */

  IF ((NEW.BANK <> OLD.BANK) OR (NEW.BANK <> ''))  THEN /* TADINYA "AND" diubah jadi "OR" */
  BEGIN
     IF (NOT EXISTS(select * from SYSBANK where bank = new.bank)) THEN
        EXCEPTION AR_BANK_NOT_DEFINE;
     NEW.CREDITCARD = '';
     NEW.CARDNUMBER = '';
     NEW.CARDOUTLET = '';
  END
  ELSE /* 12 Aug 2010 */
  BEGIN
     IF (NOT EXISTS(select * from AR_CARD where CREDITCARD = new.CREDITCARD)) THEN
        EXCEPTION AR_CREDIT_CARD_NOT_EXISTS;

     IF (NEW.CARDOUTLET IS NULL) THEN NEW.CARDOUTLET = '';
     IF (NOT EXISTS(SELECT * FROM AR_CARD_OUTLET WHERE OUTLET = NEW.CARDOUTLET)) THEN
        EXCEPTION AR_CREDIT_CARD_NOT_EXISTS 'Access denied, Credit Card Outlet "'|| NEW.CARDOUTLET ||'" does not exists.';
     NEW.DUEDATE = NEW.OPENDATE;
     
  END /* 12 Aug 2010 */
  /* -------------------------------------------------------------------- */
  SELECT CURRENCY FROM SYSBANK WHERE BANK = NEW.BANK INTO NEW.CURRENCY;
  
  if ((new.customer <> old.customer) or (new.currency <> old.currency)) then begin
     IF (EXISTS(select * from ARCASH1 where number = new.number)) THEN
        EXCEPTION AR_VOUCHER_DETAIL_EXIST;
  end
  IF (old.Status = 'O' and new.status = 'O') THEN
  begin
    if ((new.opendate < :vSysDate) and (new.status = 'O') AND (NEW.TOTAL <> -1)) then /* TOTAL <> -1 UNTUK RECALCULATE */
       exception all_date_error;
    if ((old.total <> new.total) or (old.batchno <> new.batchno)) then
    begin
     if (new.status <> 'O') then
        exception all_doc_status_not_open;
     update ARCAshbatch set totalcheck = totalcheck - old.total
      where number = old.batchno;
     update ARCAshbatch set totalcheck = totalcheck + new.total
      where number = new.batchno;
    end
    /* JIKA DATA SUDAH DIAMBIL DARI BUKU GIRO */
/*    if (new.bbgiro_apno <> 0) then new.status = 'R';*/
    
    
    if (old.exchange <> new.exchange) then /* 17-April-2002 */
    begin
       /*  select exchange from foforex where currency = new.currency
           into new.exchange;
       */
       update arcash1 set exchange = new.exchange
       where number = new.number;
    end
  end
  ELSE BEGIN
     if ((old.status = 'R') AND (NEW.STATUS = 'L')) then /* mau reconcile */
     begin
        execute procedure sp_decodedate(NEW.RECONCILEDATE) returning_values(y,m,d);
        new.reconciledate = d||'.'||m||'.'||y;
             
        IF (NOT EXISTS(select * from SYSBANK where bank = new.bank)) THEN
           EXCEPTION AR_BANK_NOT_DEFINE;
     end
     /* jika "STATUS" bukan "O" -> "R" (Received  ) [MANUAL] : CHECK DITERIMA
                            "R" -> "L" (reconcile ) [MANUAL] : CHECK CAIR
                            "R" -> "C" (end of day) [EOD]
                            "R" -> "O" (Re-Open)    [MANUAL] : Kalau ada kesalahan
     */
     /* REOPEN - 5 JULY 05 */
     IF ((NEW.STATUS = 'O') AND (OLD.STATUS = 'R')) THEN
     BEGIN
        IF (EXISTS(SELECT * FROM GLBUFFER WHERE APPLICATION = 'AR' AND
                   SOURCE = 'CASH' AND NUMBER = OLD.NUMBER AND STATUS = 'C')) THEN
         /*  EXCEPTION E_GLBUFFER_ALREDY_IMPORTED;   <- ROBY TUTUP UNTUK BISA REOPEN
     END  */
     /* END OF 5 JULY 05 */
     if ((new.total <>-1) and ((new.total <> old.total) or
         (new.customer <> old.customer) or
         (new.opendate <> old.opendate) or
         (new.duedate <> old.duedate)
        )) then
     if (not ((old.status IN ('C', 'R', 'O')) and (new.status = 'D'))) then
     begin
       IF (NOT ((old.status = 'O' AND new.status = 'R')  OR
                (old.status = 'R' AND new.status = 'L')  OR
                (old.status = 'L' AND new.status = 'L')  OR
                (old.status = 'L' AND new.status = 'R')  OR
                (old.status = 'R' AND new.status = 'O')  OR /* RE-OPEN 5 JULY 2005 */
                (old.status = 'L' AND new.status = 'C'))) THEN
         EXCEPTION DOCUMENT_IS_NOT_OPEN;
     end
     /* ----------------------------------------------------------------------- */
     /* UBAH MENJADI PAID DI VOUCHER PADA SAAT CHECK DITERIMA                   */
     /* ----------------------------------------------------------------------- */
     if ((NEW.STATUS = 'R') AND (OLD.STATUS ='O')) then BEGIN
        SELECT ARSYSDATE FROM FOSYSPARAM INTO NEW.RECEIVED_DATE;
     END
  END
  /* ----------------------------------------------------------------------- */
  /* 24 APRIL 2005, TOLAK JIKA UBAH TANGGAL LEBIH KECIL DARI VOUCHER         */
  /* ----------------------------------------------------------------------- */
  if (NEW.OPENDATE <> OLD.OPENDATE) then
  BEGIN
    FOR SELECT V.OPENDATE FROM ARCASH1 D
        LEFT JOIN ARVCH V ON V.NUMBER = D.VOUCHERNO
        WHERE D.NUMBER = NEW.NUMBER
        INTO VOUCHER_DATE DO
    BEGIN
       if (VOUCHER_DATE > NEW.OPENDATE) then exception ar_date_less_than_voucher;
    END
     
    FOR SELECT A.OPENDATE FROM ARCASH1 D
        LEFT JOIN ARADJ A ON A.VOUCHERNO = D.VOUCHERNO
        WHERE D.NUMBER = NEW.NUMBER
        INTO VOUCHER_DATE DO
    BEGIN
       if (VOUCHER_DATE > NEW.OPENDATE) then exception AR_ADJUST_DATE_GREATER;
    END
  END
  /* ----------------------------------------------------------------------- */
  /* 18 JUNI 2005, TOTAK JIKA CURRENCY DIUBAH DAN VOUCHER <> CASH            */
  /* ----------------------------------------------------------------------- */
  if (NEW.CURRENCY <> OLD.CURRENCY) then
  BEGIN
    FOR SELECT V.CURRENCY FROM ARCASH1 D
        LEFT JOIN ARVCH V ON V.NUMBER = D.VOUCHERNO
        WHERE D.NUMBER = NEW.NUMBER
        INTO VOUCHER_CURRENCY DO
    BEGIN
       if (VOUCHER_CURRENCY <> NEW.CURRENCY) then
          exception AR_CASH_BANK_VCH_CURRENCY;
    END
  END
  end
  IF (FLAG_ARCASH_DUE_EQ_OPEN = 1) THEN /* 13 AUG 2010 */
     NEW.DUEDATE = NEW.OPENDATE;  /* 10 JAN 2006 */
end

^

CREATE TRIGGER ARCASH0_POST_GL FOR ARCASH0
ACTIVE AFTER UPDATE POSITION 0
as
DECLARE VARIABLE ID INTEGER;
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE NOTE VARCHAR(40);
DECLARE VARIABLE REFF VARCHAR(20);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
DECLARE VARIABLE RELATION_CODE VARCHAR(6);
DECLARE VARIABLE RELATION_DOCTYPE INTEGER;
/* 5 JULY 2005 */
declare variable vVoucherNo INTEGER;
declare variable vTotal DOUBLE PRECISION;
declare variable vForex_Total DOUBLE PRECISION;
begin
  /* ------------------------------------------------------------------------ */
  /* STATUS ->   Prepare (O) ==> Released (R)                                 */
  /* ------------------------------------------------------------------------ */
  if ((old.status = 'O') AND (new.status = 'R') AND (new.total <> 0)) then
  begin
     /* UPDATE DETAIL STATUS */
     for select voucherno, total, forex_total from arcash1
         where number = old.number
         into :vVoucherNo, :vTotal, :vForex_Total do
     begin
         update arvch set paidprepare = paidprepare - :vTotal,
                          forex_paidprepare = forex_paidprepare - :vForex_Total,
                          paid = paid + :vTotal,
                          forex_paid = forex_paid + :vForex_Total
                where number = :vVoucherNo;
     end
     /* ---------------------------------------------------------------- */
     /* create journal                                                   */
     /* ---------------------------------------------------------------- */
     FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, REF, DEBIT, CREDIT, RELATION_CODE, RELATION_DOCTYPE
         FROM AR_GLBUFFER_CASH_RELEASE(NEW.NUMBER)
         INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
              NOTE, REFF, DB, CR, RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
        values ('AR','CASH', old.number, :ID, OLD.DUEDATE, /* 22 NOV 2008, TADINYA OPENDATE */
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :NOTE, :REFF,
                :DB, :CR,
                'now', NEW.EDITUSER, :RELATION_CODE, :RELATION_DOCTYPE);
     END
 
  end
  /* ------------------------------------------------------ */
  /* CHECK SUDAH CAIR (TELAH DIRECONCILE) STATUS "L" -> "C" */
  /* PROSES PERUBAHAN DILAKUKAN PADA EOD                    */
  /* ------------------------------------------------------ */
  if ((old.status = 'L') AND (new.status = 'C') AND (new.total <> 0) and (new.bank <> '')) then
  begin
     /* --------------------------------------------------------------------- */
     /* EXPORT TO BANK BOOK                                                   */
     /* --------------------------------------------------------------------- */
     IF (NOT EXISTS(SELECT * from sysbank where bank = old.bank)) THEN
        exception AR_BANK_NOT_DEFINE;


     select name from sysCUSTOMER where CUSTOMER = old.CUSTOMER
     into :NOTE;
     
     select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare from sysbank
     where bank = old.bank
     into :GL_ACCOUNT, :GL_DEPT, :GL_COST;
     
     INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
     VALUES           (0, NEW.BANK, old.RECONCILEDATE, 0, 'O', NEW.DOCUMENT,
                       'AR', :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        0, old.forex_total,
                        :NOTE, NEW.CHECK_NUMBER,
                        OLD.CURRENCY, OLD.EXCHANGE,
                        'AR', 'REC', NEW.NUMBER, 0,
                        NEW.EDITUSER, 'NOW', NEW.EDITUSER, 'NOW');            
   end
   /* 23 JANUARY 2006
   IF ((NEW.STATUS = 'L') AND (OLD.STATUS <> 'L') AND (NEW.OPENDATE > NEW.RECONCILEDATE )) THEN
      EXCEPTION ALL_DATE_ERROR;  */
end
^

CREATE TRIGGER ARCASH1_BDELETE FOR ARCASH1
ACTIVE BEFORE DELETE POSITION 0
as
declare variable vStatus CHAR(1);
declare variable vCheck_Number varchar(20);
declare variable vOpenDate date;
declare variable vDueDate date;
begin
  select Status, Check_Number, OpenDate, DueDate from ARCAsh0
    where number = old.number
    into :vStatus, vCheck_Number, vOpenDate, vDueDate;
  if (vStatus <> 'D') then
  begin
    if (vStatus <> 'O') then exception all_doc_status_not_open;

    /* hapus prepare payment */
    update ARVCH set paidprepare = paidprepare - old.total,
     forex_paidprepare = forex_paidprepare - old.forex_total,
     forex_gainloss = forex_gainloss - old.vch_gainloss /* 19 sep 2002 */
     where number = old.voucherno;
     
    update ARCAsh0 set total = total - old.total,
           forex_gainloss = forex_gainloss - old.vch_gainloss /* 19 sep 2002 */
     where number = old.number;
  end

/*
  else
    insert into ARPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT,
                         OPENDATE, DUEDATE, SOURCENUMBER, TOTAL, FOREX_TOTAL,
                         CUSTOMER, NOTE, DELETEDATE, DELETEUSER)
     values
       (old.voucherno, old.number, 'CASH', :vCheck_Number,
        :vOpenDate, :vDueDate, 0, old.total, old.forex_total,
        old.CUSTOMER, old.text1, 'now', user);
*/
end
^

CREATE TRIGGER ARCASH1_BINSERT FOR ARCASH1
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vStatus CHAR(1);
declare variable vCashDate DATE;
declare variable vVoucherDate DATE;
declare variable vVoucherCUSTOMER VARCHAR(6);
declare variable vCUSTOMER VARCHAR(6);
declare variable vVCHCurrency VARCHAR(4);
begin
  SELECT STATUS, OPENDATE, CUSTOMER, CURRENCY, EXCHANGE /* 17 APRIL 2002 */
  FROM ARCASH0 WHERE NUMBER = NEW.NUMBER
  INTO :VSTATUS, :VCASHDATE, :VCUSTOMER,
  NEW.CURRENCY, NEW.EXCHANGE; /* 17 APRIL 2002 */
    
  SELECT OPENDATE, CUSTOMER, CURRENCY /* 17 APRIL 2002 */
  FROM ARVCH WHERE NUMBER = NEW.VOUCHERNO
  INTO :VVOUCHERDATE, :VVOUCHERCUSTOMER, VVCHCURRENCY; /* 17 APRIL 2002 */
    
  if (vVoucherCUSTOMER is null) then exception ar_vchr_not_exist;
  if (vVoucherCUSTOMER <> vCUSTOMER) then exception ar_CUSTOMER_not_match;
  if (vVoucherDate > vCashDate) then exception ar_date_less_than_voucher;
  if (vVCHCurrency <> new.currency) then exception AR_DIFFRENT_CURRENCY; /* 17 APRIL 2002 */
  

  if (exists(SELECT * FROM ARADJ WHERE VOUCHERNO = NEW.VOUCHERNO AND OPENDATE > :vCashDate)) then
     EXCEPTION AR_ADJUST_DATE_GREATER; /* 25 APRIL 2005, ADJUSMENT DATE GREATER THAN CASH */
     
  if (exists(SELECT * FROM ARADJ WHERE VOUCHERNO = NEW.VOUCHERNO AND STATUS = 'O')) then
   /*  EXCEPTION AR_ADJUSTMENT_RELEASE; */ /* 25 APRIL 2005, PLEASE RELEASE ADJUSTMENT BEFORE CASH ENTRY */
  IF (EXISTS(SELECT * FROM ARVCH_DETAIL WHERE NUMBER = NEW.NUMBER AND SOURCE = 'A' AND STATUS = 'O')) THEN
     EXCEPTION AR_ADJUSTMENT_NOT_RELEASE; /* 9 october 2005 */
  /* -> START <- 19 SEP 2002 */
  SELECT EXCHANGE_NOW FROM ARVCH /* 20 SEP 208, DIUBAH SETELAH ADA REVALUATION*/
  WHERE NUMBER = NEW.VOUCHERNO INTO NEW.VCH_EXCHANGE;
  IF ((NEW.VCH_EXCHANGE IS NULL) OR (NEW.VCH_EXCHANGE = 0)) THEN
      SELECT EXCHANGE FROM ARVCH /* 20 SEP 208, DIUBAH SETELAH ADA REVALUATION*/
      WHERE NUMBER = NEW.VOUCHERNO INTO NEW.VCH_EXCHANGE;
  /* -> END <- 19 SEP 2002 */
  
  UPDATE ARCASH0 SET TOTAL = TOTAL + NEW.TOTAL,
         FOREX_GAINLOSS = FOREX_GAINLOSS + NEW.VCH_GAINLOSS /* 19 SEP 2002 */
   WHERE NUMBER = NEW.NUMBER;

  UPDATE ARVCH SET PAIDPREPARE = PAIDPREPARE + NEW.TOTAL,
                   FOREX_PAIDPREPARE = FOREX_PAIDPREPARE + NEW.FOREX_TOTAL, /* 17 APRIL 2002 */
                   FOREX_GAINLOSS = FOREX_GAINLOSS + NEW.VCH_GAINLOSS /* 19 SEP 2002 */
   WHERE NUMBER = NEW.VOUCHERNO;
end
^

CREATE TRIGGER ARCASH1_BUPDATE FOR ARCASH1
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vStatus CHAR(1);
declare variable vCashDate DATE;
declare variable vVoucherDate DATE;
declare variable vCUSTOMER VARCHAR(6);
declare variable vVoucherCUSTOMER VARCHAR(6);
declare variable vVCHCurrency VARCHAR(4);
begin
  if (old.number <> new.number) then
     exception all_detail_number_change;
     
  select Status, OpenDate, CUSTOMER, currency, exchange /* 17 APRIL 2002 */
    from ARCAsh0
    where number = new.number
    into :vStatus, :vCashDate, :vCUSTOMER, new.currency, new.exchange; /* 17 APRIL 2002 */
    
  if (vStatus <> 'O') then
     exception all_doc_status_not_open;
     
  select OpenDate, CUSTOMER, currency from ARVCH
   where number = new.voucherno
    into :vVoucherDate, :vVoucherCUSTOMER,vVCHCurrency; /* 17 APRIL 2002 */
    
  if (vVoucherCUSTOMER is null) then exception ar_vchr_not_exist;
  if (vVoucherCUSTOMER <> vCUSTOMER) then exception ar_CUSTOMER_not_match;
  if (vVoucherDate > vCashDate) then exception ar_date_less_than_voucher;
     
  if (new.currency <> vVCHCurrency) then exception ar_diffrent_currency; /* 17 APRIL 2002 */


  if (exists(SELECT * FROM ARADJ WHERE VOUCHERNO = NEW.VOUCHERNO AND OPENDATE > :vCashDate)) then
     EXCEPTION AR_ADJUST_DATE_GREATER; /* 25 APRIL 2005, ADJUSMENT DATE GREATER THAN CASH */
     
  if (exists(SELECT * FROM ARADJ WHERE VOUCHERNO = NEW.VOUCHERNO AND STATUS = 'O')) then
     EXCEPTION AR_ADJUSTMENT_RELEASE; /* 25 APRIL 2005, PLEASE RELEASE ADJUSTMENT BEFORE CASH ENTRY */


  /* -> START <- 19 SEP 2002 */
  SELECT EXCHANGE_NOW FROM ARVCH /* 20 SEP 208, DIUBAH SETELAH ADA REVALUATION*/
  WHERE NUMBER = NEW.VOUCHERNO INTO NEW.VCH_EXCHANGE;
  IF ((NEW.VCH_EXCHANGE IS NULL) OR (NEW.VCH_EXCHANGE = 0)) THEN
      SELECT EXCHANGE FROM ARVCH /* 20 SEP 208, DIUBAH SETELAH ADA REVALUATION*/
      WHERE NUMBER = NEW.VOUCHERNO INTO NEW.VCH_EXCHANGE;
  /* -> END <- 19 SEP 2002 */


  UPDATE ARCASH0 SET TOTAL = TOTAL - OLD.TOTAL,
         FOREX_GAINLOSS = FOREX_GAINLOSS - OLD.VCH_GAINLOSS /* 19 SEP 2002 */
   WHERE NUMBER = OLD.NUMBER;

  UPDATE ARCASH0 SET TOTAL = TOTAL + NEW.TOTAL,
         FOREX_GAINLOSS = FOREX_GAINLOSS + NEW.VCH_GAINLOSS /* 19 SEP 2002 */
   WHERE NUMBER = NEW.NUMBER;


  /* CHECK PREPARATION */
  UPDATE ARVCH SET PAIDPREPARE = PAIDPREPARE - OLD.TOTAL,
        FOREX_PAIDPREPARE = FOREX_PAIDPREPARE - OLD.FOREX_TOTAL,
        FOREX_GAINLOSS = FOREX_GAINLOSS - OLD.VCH_GAINLOSS /* 19 SEP 2002 */
  WHERE NUMBER = OLD.VOUCHERNO;

  UPDATE ARVCH SET PAIDPREPARE = PAIDPREPARE + NEW.TOTAL,
         FOREX_PAIDPREPARE = FOREX_PAIDPREPARE + NEW.FOREX_TOTAL,
         FOREX_GAINLOSS = FOREX_GAINLOSS + NEW.VCH_GAINLOSS /* 19 SEP 2002 */
  WHERE NUMBER = NEW.VOUCHERNO;

end
^

