CREATE TRIGGER ARDEPOS_BINSERT FOR ARDEPOS0
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vSysDate date;
declare variable vRow INTEGER;
begin
  /* start 20-sep-2002 */
  select currency from sysbank
  where bank = new.bank
  into NEW.Currency;
  
  select count(*) from FOFOREX_LOG
  where fodate = new.opendate
  and currency = new.currency
  into vRow;
  if (vRow > 0) then
  begin
     select exchange from FOFOREX_LOG
     where fodate = new.opendate
     and currency = new.currency
     into new.exchange;
  end
  else
     select exchange from foforex
     where currency = new.currency
     into new.exchange;
  /* end 20-sep-2002 */
    
  select arsysdate from fosysparam into :vSysDate;
  if (new.opendate < :vSysDate) then
    exception all_date_error;
  if (new.number = 0) then
  begin
     select Max(number) from ARDEpos0 into new.number;
     if (new.number is null) then new.number = 1;
     else
     new.number = new.number+1;
     
     
  end
  new.createdate = 'now';
  new.total = new.forex_total * new.exchange;
end
^

CREATE TRIGGER ARDEPOS0_BI_CHECK_BANK_OR_CARD FOR ARDEPOS0
ACTIVE BEFORE INSERT POSITION 1
AS
BEGIN
  /* ----------------------------------------------------------------*/
  /* 9 OCTOBER 2005                                                  */
  /* ----------------------------------------------------------------*/
  IF (NEW.BANK IS NULL) THEN NEW.BANK = '';
  IF (NEW.CREDITCARD IS NULL) THEN NEW.CREDITCARD = '';
  IF (NEW.BANK <> '') THEN
  BEGIN
     NEW.CREDITCARD = '';
     IF (NOT EXISTS(SELECT * FROM SYSBANK WHERE BANK = NEW.BANK)) THEN
        EXCEPTION AR_BANK_NOT_DEFINE;
  END
  ELSE
  BEGIN
     NEW.BANK = '';
     IF (NOT EXISTS(SELECT * FROM AR_CARD WHERE CREDITCARD = NEW.CREDITCARD)) THEN
        EXCEPTION AR_CREDIT_CARD_NOT_EXISTS;

     SELECT B.CURRENCY FROM AR_CARD C
     LEFT JOIN SYSBANK B ON B.BANK = C.BANK
     WHERE C.CREDITCARD = NEW.CREDITCARD
     INTO NEW.CURRENCY;
     NEW.EXCHANGE = 1;
  END

END
^

