    DELETE FROM AR_CARD_JUR WHERE SOURCE='D' AND FO_FOLIO=NEW.NUMBER; /* 11/30/2011 */
    INSERT INTO AR_CARD_JUR (
             CREDITCARD,
             CARDNUMBER,
             REMARK,
