CREATE TRIGGER ARDEPOS0_BUPDATE FOR ARDEPOS0
ACTIVE BEFORE UPDATE POSITION 2
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
DECLARE VARIABLE VROW INTEGER;
DECLARE VARIABLE VCURRENCY VARCHAR(4);
/* 30 OCT 0227  */
DECLARE VARIABLE ADJUST DOUBLE PRECISION;
DECLARE VARIABLE FOREX_ADJUST DOUBLE PRECISION;
/* 26 MARET 2007 */
DECLARE VARIABLE GAIN_LOSS DOUBLE PRECISION;
BEGIN
  IF (NEW.FOREX_GAINLOSS = -1) THEN /* 25 MARET 2008, TADINYA EXCHANGE <= 1*/
  BEGIN
     SELECT SUM(TOTAL), SUM(FOREX_TOTAL), SUM(-VCH_GAINLOSS)
     FROM ARDEPOS1 WHERE NUMBER = NEW.NUMBER
     INTO NEW.APPLIED, NEW.FOREX_APPLIED, NEW.FOREX_GAINLOSS;

     IF (NEW.APPLIED IS NULL) THEN NEW.APPLIED = 0;
     IF (NEW.FOREX_APPLIED IS NULL) THEN NEW.FOREX_APPLIED = 0;
     IF (NEW.FOREX_GAINLOSS IS NULL) THEN NEW.FOREX_GAINLOSS = 0;
     /* ---------------------------------------------------------------- */
     /* 30 OCT 2007                                                      */
     /* ---------------------------------------------------------------- */
     SELECT SUM(CR-DB), SUM(FOREX_CR-FOREX_DB)
     FROM ARDEPOS0_JUR WHERE DEPOSITNO = NEW.NUMBER
     AND SOURCE <> 'RE' /* 26 MARET 2008, BUKAN REVALUATION */
     INTO ADJUST, FOREX_ADJUST;

     IF (ADJUST IS NULL) THEN ADJUST = 0;
     IF (FOREX_ADJUST IS NULL) THEN FOREX_ADJUST = 0;

     NEW.FOREX_APPLIED = NEW.FOREX_APPLIED + FOREX_ADJUST;
     NEW.APPLIED = NEW.APPLIED + ADJUST;
     /* ---------------------------------------------------------------- */
     /* 26 MARET 2008                                                    */
     /* ---------------------------------------------------------------- */
     SELECT SUM(DB-CR)
     FROM ARDEPOS0_JUR WHERE DEPOSITNO = NEW.NUMBER
     AND SOURCE = 'RE'
     INTO GAIN_LOSS;
     IF (GAIN_LOSS IS NULL) THEN GAIN_LOSS = 0;
     NEW.FOREX_GAINLOSS = NEW.FOREX_GAINLOSS + GAIN_LOSS;

  END

  /* START 20-SEP-2002 */
  IF (OLD.STATUS = 'O') THEN
  BEGIN
    IF (NEW.EXCHANGE IS NULL)  THEN
    BEGIN
       SELECT CURRENCY FROM SYSBANK
       WHERE BANK = NEW.BANK
       INTO VCURRENCY;

       IF (VCURRENCY IS NOT NULL) THEN
          NEW.CURRENCY = VCURRENCY;

       SELECT COUNT(*) FROM FOFOREX_LOG
       WHERE FODATE = NEW.OPENDATE
       AND CURRENCY = NEW.CURRENCY
       INTO VROW;
       IF (VROW > 0) THEN
       BEGIN
          SELECT EXCHANGE FROM FOFOREX_LOG
          WHERE FODATE = NEW.OPENDATE
          AND CURRENCY = NEW.CURRENCY
          INTO NEW.EXCHANGE;
       END
       ELSE
          SELECT EXCHANGE FROM FOFOREX
          WHERE CURRENCY = NEW.CURRENCY
          INTO NEW.EXCHANGE;
    END
    /* END 20-SEP-2002 */
  END

  IF (OLD.APPLIED <> NEW.APPLIED) THEN
     IF (OLD.STATUS = 'O') THEN
        EXCEPTION AR_DEPOSIT_OPEN;
  IF ((OLD.STATUS = 'R') AND
      ((NEW.FOREX_TOTAL <> OLD.FOREX_TOTAL) OR
       (NEW.CURRENCY <> OLD.CURRENCY) OR
       (NEW.EXCHANGE <> OLD.EXCHANGE))) THEN
      EXCEPTION ALL_DOC_STATUS_NOT_OPEN;

  NEW.TOTAL = NEW.FOREX_TOTAL * NEW.EXCHANGE;
  
  /* ---------------------------------------------------------------- */
  /* 25 MARET 2008                                                    */
  /* ---------------------------------------------------------------- */
  IF (NEW.FOREX_BALANCE <> 0) THEN
     NEW.EXCHANGE_NOW = NEW.BALANCE/NEW.FOREX_BALANCE;
END
^

CREATE TRIGGER ARDEPOS0_JUR_BD FOR ARDEPOS0_JUR
ACTIVE BEFORE DELETE POSITION 0
as
begin
  IF (old.status = 'O') then
  begin
     /* ---------------------------------------------------------------- */
     /* 26 MARET 2008                                                    */
     /* ---------------------------------------------------------------- */
     IF (OLD.SOURCE <> 'RE') THEN
     BEGIN
        /* ORIGINAL CALCULATION */
        update ARDEPOS0 set
          APPLIED = APPLIED - (OLD.CR - OLD.DB),
          FOREX_APPLIED = FOREX_APPLIED  - (old.forex_cr-old.forex_db)
        where NUMBER = OLD.DEPOSITNO;
     END
     ELSE
     BEGIN
        /* REVALUATION */
        update ARDEPOS0 set
          FOREX_GAINLOSS = FOREX_GAINLOSS - (OLD.DB-OLD.CR)
        where NUMBER = OLD.DEPOSITNO;
     END

  end
  ELSE
    exception all_doc_status_not_open;
end
^

CREATE TRIGGER ARDEPOS0_JUR_BI FOR ARDEPOS0_JUR
ACTIVE BEFORE INSERT POSITION 0
as

declare variable vSysDate date;
declare variable DEPOSITDATE DATE;
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_DEPT VARCHAR(4);
declare variable GL_COST VARCHAR(4);
begin
  new.status = 'O';
  select arsysdate from fosysparam into :vSysDate;
  if (new.opendate < :vSysDate) then
  /*   exception all_date_error;  */

  select D.CUSTOMER, D.OPENDATE, D.CURRENCY, D.EXCHANGE,
         T.DEPOS_GLACCOUNT, T.DEPOS_GLDEPT, T.DEPOS_GLCOST
  from ARDEPOS0 D
    left join SYSCUSTOMER C ON C.CUSTOMER = D.CUSTOMER
    left join syscustomertype t on T.customertype = C.CUSTTYPE
   where D.NUMBER = NEW.DEPOSITNO
   into NEW.CUSTOMER, :DEPOSITDATE, NEW.CURRENCY, NEW.EXCHANGE,
        GL_ACCOUNT, GL_DEPT, GL_COST;

   IF ((NEW.ACCOUNT = GL_ACCOUNT) AND (NEW.DEPT = GL_DEPT) AND (NEW.COST = GL_COST)) THEN
      EXCEPTION AR_DEPOSIT_JUR_ITSELF;

  if (new.opendate < :DEPOSITDATE ) then
      exception ar_date_less_than_voucher;

  select Max(number) from ardepos0_jur into new.number;
  if (new.number is null) then new.number = 1;
  else new.number = new.number+1;

  new.createdate = 'now';
  /* ---------------------------------------------------------------- */
  /* REVALUATION                                                      */
  /* 26 MARET 2008                                                    */
  /* ---------------------------------------------------------------- */
  IF (NEW.SOURCE <> 'RE') THEN
  BEGIN
     /* ORIGINAL CALCULATION */
     NEW.DB = NEW.FOREX_DB * NEW.EXCHANGE;
     NEW.CR = NEW.FOREX_CR * NEW.EXCHANGE;

     update ARDEPOS0 set
       APPLIED = APPLIED + (NEW.CR - NEW.DB),
       FOREX_APPLIED = FOREX_APPLIED  + (new.forex_cr-new.forex_db)
     where NUMBER = NEW.DEPOSITNO;
   
  END
  ELSE
  BEGIN
     /* REVALUATION */
     NEW.FOREX_DB = 0;
     NEW.FOREX_CR = 0;
     update ARDEPOS0 set
       FOREX_GAINLOSS = FOREX_GAINLOSS + (NEW.DB - NEW.CR)
     where NUMBER = NEW.DEPOSITNO;
  END
end
^

CREATE TRIGGER ARDEPOS0_JUR_BU FOR ARDEPOS0_JUR
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vSysDate date;
declare variable DEPOSITDATE DATE;
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_DEPT VARCHAR(4);
declare variable GL_COST VARCHAR(4);
begin
  IF ((new.status = 'O') and (old.status = 'O')) then
  begin
     select arsysdate from fosysparam into :vSysDate;
     if (new.opendate < :vSysDate) then /* exception all_date_error;   */

     select D.CUSTOMER, D.OPENDATE, D.CURRENCY, D.EXCHANGE,
            T.DEPOS_GLACCOUNT, T.DEPOS_GLDEPT, T.DEPOS_GLCOST
     from ARDEPOS0 D
     left join SYSCUSTOMER C ON C.CUSTOMER = D.CUSTOMER
     left join syscustomertype t on T.customertype = C.CUSTTYPE
     where D.NUMBER = NEW.DEPOSITNO
     into NEW.CUSTOMER, :DEPOSITDATE, NEW.CURRENCY, NEW.EXCHANGE,
          GL_ACCOUNT, GL_DEPT, GL_COST;

     IF ((NEW.ACCOUNT = GL_ACCOUNT) AND (NEW.DEPT = GL_DEPT) AND (NEW.COST = GL_COST)) THEN
        EXCEPTION AR_DEPOSIT_JUR_ITSELF;

     if (new.opendate < :DEPOSITDATE ) then exception ar_date_less_than_voucher;

     new.editdate = 'now';
     /* ---------------------------------------------------------------- */
     /* 26 MARET 2008                                                    */
     /* REVALUATION                                                      */
     /* ---------------------------------------------------------------- */
     IF (NEW.SOURCE <> 'RE') THEN
     BEGIN
        /* ORIGINAL CALCULATION */
        NEW.DB = NEW.FOREX_DB * NEW.EXCHANGE;
        NEW.CR = NEW.FOREX_CR * NEW.EXCHANGE;

        update ARDEPOS0 set
          APPLIED = APPLIED + (NEW.CR - NEW.DB) - (OLD.CR - OLD.DB),
          FOREX_APPLIED = FOREX_APPLIED  + (new.forex_cr-new.forex_db) - (old.forex_cr-old.forex_db)
        where NUMBER = NEW.DEPOSITNO;

     END
     ELSE
     BEGIN
        /* REVALUATION */
        NEW.FOREX_DB = 0;
        NEW.FOREX_CR = 0;

        update ARDEPOS0 set
          FOREX_GAINLOSS = FOREX_GAINLOSS + (NEW.DB - NEW.CR) - (OLD.DB-OLD.CR)
        where NUMBER = NEW.DEPOSITNO;
     END
  end
end
^

CREATE TRIGGER ARDEPOS0_JUR_GL_POST FOR ARDEPOS0_JUR
ACTIVE AFTER UPDATE POSITION 0
as
DECLARE VARIABLE ID INTEGER;
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE NOTE VARCHAR(40);
DECLARE VARIABLE REFF VARCHAR(20);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
DECLARE VARIABLE RELATION_CODE VARCHAR(6);
DECLARE VARIABLE RELATION_DOCTYPE INTEGER;
begin
  /* 28 NOVEMBER 2005 */
  if ((old.status <> 'R') AND (new.status = 'R')) then
  begin
     FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, REF, DEBIT, CREDIT, RELATION_CODE, RELATION_DOCTYPE
         FROM ar_glbuffer_deposit_jur_release(NEW.NUMBER)
         INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
              NOTE, REFF, DB, CR, RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
        values ('AR','DADJ', old.number, :ID, old.opendate,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :NOTE, :REFF,
                :DB, :CR,
                'now', NEW.EDITUSER, :RELATION_CODE, :RELATION_DOCTYPE);
     END
  end
end
^

CREATE TRIGGER ARDEPOS0_POST_GL FOR ARDEPOS0
ACTIVE AFTER UPDATE POSITION 0
as
DECLARE VARIABLE ID INTEGER;
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE NOTE VARCHAR(40);
DECLARE VARIABLE REFF VARCHAR(20);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
DECLARE VARIABLE RELATION_CODE VARCHAR(6);
DECLARE VARIABLE RELATION_DOCTYPE INTEGER;
begin
  /* ---------------------------------------------------------------------- */
  /* STATUS CASH DEPOSIT :                                                  */
  /*  O=(Open)      -> R=(Release)   [Manual]     -> Masuk G/L              */
  /*                    Bank Transient (DB) | A/R (CR)                      */
  /*  R=(Release)   -> L=(Reconcile) [BankBook]                             */
  /*  L=(Reconcile) -> C=(Close)     [End of Day] -> Masuk Bank Book (GL No)*/
  /*                    Bank (DB) | Bank Transient (CR)                     */     
  /* ---------------------------------------------------------------------- */
  if ((old.status = 'O') AND (new.status = 'R')) then
  begin
     FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, REF, DEBIT, CREDIT, RELATION_CODE, RELATION_DOCTYPE
         FROM AR_GLBUFFER_DEPOSIT_RELEASE(NEW.NUMBER)
         INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
              NOTE, REFF, DB, CR, RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
        values ('AR','DEP0', old.number, :ID, old.opendate,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :NOTE, :REFF,
                :DB, :CR,
                'now', NEW.EDITUSER, :RELATION_CODE, :RELATION_DOCTYPE);
     END
  end
  if ((old.status = 'L') AND (new.status = 'C') AND (NEW.BANK <> '')) then /* BUKAN CREDIT CARD*/
  begin  
     select bankname, GL_ACCOUNT_ARPREPARE, GL_DEPT_ARPREPARE, GL_COST_ARPREPARE from sysbank
      where bank = old.bank
       into NOTE, GL_ACCOUNT, GL_DEPT, GL_COST;
     SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = NEW.CUSTOMER INTO :NOTE;
     INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
     VALUES           (0, NEW.BANK, old.RECONCILEDATE, 0, 'T', NEW.CHECK_NUMBER,
                       'AR', :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        0, old.forex_total,
                        :NOTE, NEW.DOCUMENT,
                        OLD.CURRENCY, OLD.EXCHANGE,
                        'AR', 'DREC', NEW.NUMBER,
                        NEW.EDITUSER, 'NOW', NEW.EDITUSER, 'NOW');              
  end
   /* 23 JANUARY 2006
   IF ((NEW.STATUS = 'L') AND (OLD.STATUS <> 'L') AND (NEW.OPENDATE > NEW.RECONCILEDATE )) THEN
      EXCEPTION ALL_DATE_ERROR;  */
end
^

CREATE TRIGGER ARDEPOS1_BDELETE FOR ARDEPOS1
ACTIVE BEFORE DELETE POSITION 0
as
begin
  if (old.status <> 'D') then
  begin
    update ARDEpos0 set applied = applied - old.total,
     forex_applied = forex_applied - old.forex_total,
     forex_gainloss = forex_gainloss + old.vch_gainloss
     where number = old.number;
     
    update ARVCH set deposit = deposit - old.forex_total * old.exchange,
     forex_deposit = forex_deposit - old.forex_total,
     forex_gainloss = forex_gainloss - old.vch_gainloss
     where number = old.voucherno;
  end
end
^

CREATE TRIGGER ARDEPOS1_BINSERT FOR ARDEPOS1
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vVchOpenDate date;
declare variable vVchCurrency VARCHAR(4);
declare variable vDepCurrency VARCHAR(4);
begin

  select opendate, currency,
         EXCHANGE_NOW /* 28 MARET 2008, TADINYA EXCHANGE */
    from ARVCH
   where number = new.voucherno
    into :vVchOpenDate, vVchCurrency, NEW.VCH_EXCHANGE;

  select currency, exchange_now /* 28 MARET 2008, TADINYA EXCHANGE */
  from ardepos0
  where number = new.number
  into :vDepCurrency, new.exchange;
  
  if (vVchCurrency <> vDepCurrency) then 
     exception ar_diffrent_currency;
    
  if (vVchOpenDate > new.AppliedDate) then
     exception ar_date_less_than_voucher;
  new.vch_gainloss = new.forex_total*(new.exchange-new.vch_exchange);
  
  UPDATE ARDEPOS0 SET APPLIED = APPLIED + NEW.TOTAL,
   FOREX_APPLIED = FOREX_APPLIED + NEW.FOREX_TOTAL,
   FOREX_GAINLOSS = FOREX_GAINLOSS - NEW.VCH_GAINLOSS
   WHERE NUMBER = NEW.NUMBER;

    UPDATE ARVCH SET DEPOSIT = DEPOSIT + NEW.FOREX_TOTAL * NEW.EXCHANGE,
     FOREX_DEPOSIT = FOREX_DEPOSIT + NEW.FOREX_TOTAL,
     FOREX_GAINLOSS = FOREX_GAINLOSS + NEW.VCH_GAINLOSS
     WHERE NUMBER = NEW.VOUCHERNO;

  NEW.APPLY_NUMBER = GEN_ID(GEN_ARDEPOS1_APPLY_NUMBER,1);
  
end
^

CREATE TRIGGER ARDEPOS1_BUPDATE FOR ARDEPOS1
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vVchOpenDate date;
declare variable vVchCurrency VARCHAR(4);
declare variable vDepCurrency VARCHAR(4);
begin
  /* RELOAD EXCHANGE RATE */
  IF (NEW.VCH_EXCHANGE <> OLD.VCH_EXCHANGE) THEN /* 25-FEB-2009, ASLINYA NEW.VCH_EXCHANGE <= -1, GAK BILEH DIUBAH KARENA VCH_EXCHANGE SESUAI PADA DAAT DIBUAT*/
  BEGIN
    SELECT EXCHANGE_NOW /* 28 MARET 2008, TADINYA EXCHANGE */
    FROM ARVCH WHERE NUMBER = NEW.VOUCHERNO
    INTO NEW.VCH_EXCHANGE;
    NEW.VCH_EXCHANGE = OLD.VCH_EXCHANGE;
    new.vch_gainloss = new.forex_total*(new.exchange-new.vch_exchange);
  END

  /* RELEASE */
  IF ((old.Status = 'O' and new.status = 'O') OR (NEW.VCH_EXCHANGE <> OLD.VCH_EXCHANGE) /* RECALCULATE 16-DES-2005*/) THEN
  begin
     select opendate, currency
       from  ARVCH
      where number = new.voucherno
     into :vVchOpenDate, vVchCurrency;

     select currency
      from ardepos0
     where number = new.number
     into :vDepCurrency;

     if (vVchCurrency <> vDepCurrency) then
        exception ar_diffrent_currency;
       
    if (vVchOpenDate > new.AppliedDate) then
        exception ar_date_less_than_voucher;

    if (new.number <> old.number) then exception all_detail_number_change;

    NEW.VCH_GAINLOSS = NEW.FOREX_TOTAL*(NEW.EXCHANGE-NEW.VCH_EXCHANGE);

    UPDATE ARDEPOS0 SET APPLIED = APPLIED - OLD.TOTAL + NEW.TOTAL,
     FOREX_APPLIED = FOREX_APPLIED -OLD.FOREX_TOTAL+ NEW.FOREX_TOTAL,
     FOREX_GAINLOSS = FOREX_GAINLOSS + OLD.VCH_GAINLOSS - NEW.VCH_GAINLOSS

     WHERE NUMBER = NEW.NUMBER;

    UPDATE ARVCH SET DEPOSIT = DEPOSIT - OLD.FOREX_TOTAL * OLD.EXCHANGE,
     FOREX_DEPOSIT = FOREX_DEPOSIT - OLD.FOREX_TOTAL,
     FOREX_GAINLOSS = FOREX_GAINLOSS - OLD.VCH_GAINLOSS
     WHERE NUMBER = OLD.VOUCHERNO;

    UPDATE ARVCH SET DEPOSIT = DEPOSIT + NEW.FOREX_TOTAL * NEW.EXCHANGE,
     FOREX_DEPOSIT = FOREX_DEPOSIT + NEW.FOREX_TOTAL,
     FOREX_GAINLOSS = FOREX_GAINLOSS + NEW.VCH_GAINLOSS
     WHERE NUMBER = NEW.VOUCHERNO;


  end
  ELSE
     /* jika "STATUS" bukan "O" -> "R" (release)
                            "R" -> "C" (end of day)
     */
     IF (NEW.EXCHANGE <> OLD.EXCHANGE) THEN
     BEGIN
       if (not ((old.status IN ('C', 'R', 'O')) and (new.status = 'D'))) then
       begin
         IF (NOT ((old.status = 'O' AND new.status = 'R')  OR
                  (old.status = 'O' AND new.status = 'C')  OR
                  (old.status = 'R' AND new.status = 'C'))) THEN
            EXCEPTION DOCUMENT_IS_NOT_OPEN;
       end
     END
     
  IF ((NEW.APPLY_NUMBER IS NULL) OR (NEW.APPLY_NUMBER = 0)) THEN
     NEW.APPLY_NUMBER = GEN_ID(GEN_ARDEPOS1_APPLY_NUMBER,1);     
end
^

