CREATE TRIGGER ARVCH_AI_COMMISSION FOR ARVCH
ACTIVE AFTER INSERT POSITION 0
as
declare variable TOTAL DOUBLE PRECISION;
declare variable CODE VARCHAR(4);
declare variable NAME VARCHAR(40);
declare variable NIGHT_FEE DOUBLE PRECISION;
declare variable STAY_FEE DOUBLE PRECISION;
declare variable ROOMREVENUE_PERCENT NUMERIC(15,4);
declare variable TOTALREVENUE_PERCENT NUMERIC(15,4);
declare variable DATESTART DATE;
declare variable DATEEND DATE;
declare variable FOLIOSTATUS_SHARE CHAR(1);
declare variable FOLIOTYPE CHAR(1);
declare variable NIGHT DOUBLE PRECISION;
BEGIN
  if ((new.source = 'FO') and (new.fo_folio <> 0)) then

  FOR SELECT CODE,
             NAME,
             NIGHT_FEE,
             STAY_FEE,
             ROOMREVENUE_PERCENT,
             TOTALREVENUE_PERCENT
      FROM SYSCUSTOMER_COMMISSION
      WHERE CUSTOMER = NEW.CUSTOMER
/*      AND FLAG_ACTIVE = 1 */
      AND NEW.OPENDATE BETWEEN DATESTART AND DATEEND
      INTO :CODE,
           :NAME,
           :NIGHT_FEE,
           :STAY_FEE,
           :ROOMREVENUE_PERCENT,
           :TOTALREVENUE_PERCENT
  DO BEGIN
     SELECT DATECO-DATECI, FOLIOTYPE, FOLIOSTATUS_SHARE FROM FOGUEST
     WHERE FOLIO = NEW.FO_FOLIO INTO NIGHT, FOLIOTYPE, FOLIOSTATUS_SHARE;

     if ((FOLIOTYPE NOT IN ('G', 'P')) or (FOLIOSTATUS_SHARE <> 'M')) then BEGIN
        NIGHT_FEE = 0;
        STAY_FEE  = 0;     
     END
     ELSE BEGIN
        if (FOLIOSTATUS_SHARE = 'M') then BEGIN
           NIGHT_FEE = NIGHT_FEE * NIGHT;
           STAY_FEE  = STAY_FEE;
           if (ROOMREVENUE_PERCENT <> 0 ) then BEGIN
              SELECT SUM(DEBIT) FROM FOGUEST_JUR JR
              LEFT JOIN focategory CAT ON
                   (CAT.CATEGORY = JR.CATEGORY AND CAT.CLASS = 1)
              WHERE JR.FOLIO = NEW.FO_FOLIO
              INTO :TOTAL;
              if (TOTAL IS NULL) then TOTAL = 0;
              ROOMREVENUE_PERCENT = ROOMREVENUE_PERCENT * TOTAL/100;
           END
           
           if (TOTALREVENUE_PERCENT <> 0 ) then BEGIN
              SELECT SUM(DEBIT) FROM FOGUEST_JUR JR
              LEFT JOIN focategory CAT ON
                   (CAT.CATEGORY = JR.CATEGORY AND CAT.CLASS = 1)
              WHERE JR.FOLIO = NEW.FO_FOLIO
              INTO TOTALREVENUE_PERCENT;
              if (TOTAL IS NULL) then TOTAL = 0;
              TOTALREVENUE_PERCENT = TOTALREVENUE_PERCENT * TOTAL/100;
           END
        END
     END
     TOTAL = NIGHT_FEE + STAY_FEE + ROOMREVENUE_PERCENT + TOTALREVENUE_PERCENT;
     if (TOTAL > 0) then
     INSERT INTO ARVCH_COMMISSION (
               NUMBER,          CODE,       NAME,       TOTAL,  FODATE, STATUS)
     VALUES (  NEW.NUMBER,      :CODE,      :NAME,      :TOTAL, NEW.OPENDATE, 'H');
     
  END
END
^

