CREATE TRIGGER ARVCH_BINSERT FOR ARVCH
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vSysDate date;
DECLARE VARIABLE FLAG_ACTIVE INTEGER;
DECLARE VARIABLE FLAG_CREDITFACILITY INTEGER;
begin
  IF (NOT EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = NEW.CUSTOMER)) THEN
     EXCEPTION E_FOGUEST_COMPANY_NOT_FOUND;

  SELECT FLAG_ACTIVE, CREDITFACILITY
  FROM SYSCUSTOMER WHERE CUSTOMER = NEW.CUSTOMER
  INTO FLAG_ACTIVE, FLAG_CREDITFACILITY;
     
  if (new.fo_pax is null) then new.fo_pax = 1;
  new.forex_gainloss = 0;
  select arsysdate from fosysparam into :vSysDate;
  if ((new.opendate < :vSysDate) and (new.fo_folio = 0)) then /* jika data manual */
  begin
    IF (NEW.FO_FOLIO = 0) THEN new.opendate = :vSysDate;
    new.duedate = :vSysDate + (new.duedate-new.opendate);
  end
  if (new.number = 0) then
  begin
     select Max(number) from ARVCH into new.number;
     if (new.number is null) then new.number = 1;
     else
     new.number = new.number+1;
  end
  new.createdate = 'now';
  if (new.duedate is null) then new.duedate = new.opendate + 14;
  new.flag_merged = 0;
  new.flag_marked = 0;
  /* ---------------------------------------------------------------- */
  /* 28 MARET 2008                                                    */
  /* ---------------------------------------------------------------- */
  NEW.EXCHANGE_NOW = NEW.EXCHANGE;
end
^

CREATE TRIGGER ARVCH_BU_BATCH_UPDATE FOR ARVCH
ACTIVE BEFORE UPDATE POSITION 0
as
DECLARE VARIABLE CURRENCY VARCHAR(4);
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE BATCH_DATE DATE;
begin
  IF (NEW.BATCH_NUMBER <> OLD.BATCH_NUMBER) THEN
  BEGIN
    IF (NEW.BATCH_NUMBER = 0) THEN
    BEGIN
       UPDATE ARVCH_BATCH SET TOTAL = TOTAL - OLD.FOREX_TOTAL - OLD.FOREX_ADJUST
       WHERE NUMBER = OLD.BATCH_NUMBER;
    END
    ELSE
    BEGIN
       IF (EXISTS(SELECT * FROM ARCASH1 WHERE VOUCHERNO = NEW.NUMBER)) THEN
          EXCEPTION E_ARVCH_BATCH_ALREADY_PROCESS;

       IF (NOT EXISTS(SELECT * FROM ARVCH_BATCH WHERE NUMBER = NEW.BATCH_NUMBER)) THEN
          EXCEPTION AR_VCH_BATCH_NOT_EXISTS;
          
       IF (EXISTS(SELECT * FROM ARADJ WHERE VOUCHERNO = NEW.NUMBER AND STATUS = 'O')) THEN
          EXCEPTION AR_ADJUSTMENT_NOT_RELEASE;
          
       IF (EXISTS(SELECT * FROM ARVCH_DETAIL WHERE NUMBER = NEW.NUMBER AND SOURCE = 'A' AND STATUS = 'O')) THEN
          EXCEPTION AR_ADJUSTMENT_NOT_RELEASE;

       SELECT CURRENCY, CUSTOMER, OPENDATE FROM ARVCH_BATCH
       WHERE NUMBER = NEW.BATCH_NUMBER
       INTO CURRENCY, CUSTOMER, BATCH_DATE;
        
       if (CUSTOMER <> NEW.CUSTOMER)  then exception AR_CUSTOMER_NOT_MATCH;
       if (BATCH_DATE < NEW.OPENDATE) then exception AR_DATE_LESS_THAN_VOUCHER;
       if (CURRENCY <> NEW.CURRENCY)  then exception AR_DIFFRENT_CURRENCY;

       UPDATE ARVCH_BATCH SET TOTAL = TOTAL + NEW.FOREX_TOTAL + NEW.FOREX_ADJUST
       WHERE NUMBER = NEW.BATCH_NUMBER;
     END
  END
  IF (((NEW.ADJUST <> OLD.ADJUST) OR (NEW.ADJUST_FO <> OLD.ADJUST_FO)) AND
      (OLD.BATCH_NUMBER <> 0) AND (OLD.BATCH_NUMBER = NEW.BATCH_NUMBER)) THEN
  BEGIN
      EXCEPTION AR_VCH_BATCH_NOT_ZERO;
  END
end
^

