CREATE TRIGGER ARVCH_BU_RECALC FOR ARVCH
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable paidprepare DOUBLE PRECISION;
declare variable forex_paidprepare DOUBLE PRECISION;
declare variable paid DOUBLE PRECISION;
declare variable forex_paid DOUBLE PRECISION;
declare variable adjust DOUBLE PRECISION;
declare variable forex_adjust DOUBLE PRECISION;
DECLARE VARIABLE DOCTYPE INTEGER;
declare variable forex_gainloss DOUBLE PRECISION;
begin
  /* Trigger Text */
  if (NEW.FO_PAX = -1) then
  BEGIN
     NEW.FO_PAX = OLD.FO_PAX;
     SELECT SUM(D.total), SUM(D.forex_total), SUM(D.vch_gainloss) FROM  ARCASH1 D
     LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
     WHERE D.VOUCHERNO = NEW.NUMBER
     AND H.STATUS = 'O'
     INTO paidprepare, forex_paidprepare, forex_gainloss;
     if (paidprepare is null) then
     begin
        paidprepare  = 0;
        forex_paidprepare = 0;
        forex_gainloss = 0;
     end
     new.paidprepare = paidprepare;
     new.forex_paidprepare = forex_paidprepare;
     new.forex_gainloss = forex_gainloss;
     
     SELECT SUM(D.total), SUM(D.forex_total), SUM(D.vch_gainloss) FROM  ARCASH1 D
     LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
     WHERE D.VOUCHERNO = NEW.NUMBER
     AND H.STATUS IN ('R','L','C')
     INTO paid, forex_paid,forex_gainloss;
     
     if (paid is null) then
     begin
        paid = 0;
        forex_paid = 0;
        forex_gainloss = 0;
     end
     
     new.paid = paid;
     new.forex_paid = forex_paid;
     new.forex_gainloss = new.forex_gainloss + forex_gainloss;
     /* ADJUSTMENT */
     SELECT SUM(DB-CR), SUM(FOREX_DB-FOREX_CR)
     FROM ARADJ
     WHERE VOUCHERNO = NEW.NUMBER
     AND SOURCE <> 'RE' /* 28 MARET 2008 */
     INTO NEW.ADJUST, NEW.FOREX_ADJUST;
     
     if (new.adjust is null) then
     begin
        new.adjust = 0;
        new.forex_adjust = 0;
     end
     /* FRONT OFFICE ADJUSTMENT, STATUS STILL OPEN */
     SELECT SUM(DEBIT-CREDIT), SUM(FOREX_DEBIT-FOREX_CREDIT)
     FROM arvch_detail
     WHERE NUMBER = NEW.NUMBER
     AND STATUS = 'O'
     AND SOURCE = 'A'
     INTO NEW.ADJUST_FO, NEW.FOREX_ADJUST_FO;
     
     if (NEW.ADJUST_FO IS NULL) then
     BEGIN
       NEW.ADJUST_FO = 0;
       NEW.FOREX_ADJUST_FO = 0;
     END
     if (NEW.ADJUST_FO <> 0) then NEW.FO_STATUS_CORRECTION = 'O';
     
     /* FRONT OFFICE ADJUSTMENT, STATUS ALREADY CLOSE */
     SELECT SUM(DEBIT-CREDIT), SUM(FOREX_DEBIT-FOREX_CREDIT)
     FROM arvch_detail
     WHERE NUMBER = NEW.NUMBER
     AND STATUS = 'C'
     AND SOURCE = 'A'
     INTO ADJUST, FOREX_ADJUST;
     
     if (ADJUST IS NULL) then
     BEGIN
        ADJUST = 0;
        FOREX_ADJUST = 0;
     END

     NEW.ADJUST = NEW.ADJUST+ADJUST;
     NEW.FOREX_ADJUST = NEW.FOREX_ADJUST + FOREX_ADJUST;
     /* DEPOSIT, 16 JUN 2005 */
     UPDATE ARDEPOS1 SET VCH_EXCHANGE = NEW.EXCHANGE
     WHERE VOUCHERNO = NEW.NUMBER
     AND VCH_EXCHANGE <> NEW.EXCHANGE; /* 16 DES 05*/
     SELECT SUM(TOTAL), SUM(FOREX_TOTAL)
     FROM ARDEPOS1
     WHERE VOUCHERNO = NEW.NUMBER
     INTO NEW.DEPOSIT, NEW.FOREX_DEPOSIT;
     
     IF (NEW.DEPOSIT IS NULL) THEN
     BEGIN
        NEW.DEPOSIT = 0;
        NEW.FOREX_DEPOSIT = 0;
     END
     /* ---------------------------------------------------------------- */
     /* 28 MARET 2008                                                    */
     /* ---------------------------------------------------------------- */
     SELECT SUM(DB-CR)
     FROM ARADJ
     WHERE VOUCHERNO = NEW.NUMBER
     AND SOURCE = 'RE'
     INTO FOREX_GAINLOSS;
     IF (FOREX_GAINLOSS IS NULL) THEN FOREX_GAINLOSS = 0;
     NEW.FOREX_GAINLOSS = NEW.FOREX_GAINLOSS + FOREX_GAINLOSS;
  END
  IF (NEW.DOCUMENT = '?') THEN
  BEGIN
     SELECT RELATION_DOCTYPE FROM SYSCUSTOMER
     WHERE CUSTOMER = NEW.CUSTOMER INTO DOCTYPE;
     IF (DOCTYPE IS NULL) THEN DOCTYPE = 0;
       
     EXECUTE PROCEDURE SP_DOCUMENT_NUMBER('AR','INVC',DOCTYPE, NEW.OPENDATE,1)
     RETURNING_VALUES NEW.DOCUMENT;  
  END  
end
^

CREATE TRIGGER ARVCH_BU_SPLIT FOR ARVCH
ACTIVE BEFORE UPDATE POSITION 1
as
begin
  IF ((NEW.TOTAL < OLD.TOTAL) AND (NEW.GLSTATUS = 'Z') AND (OLD.ADJUST = 0 /* 10/17/2011 tadinya OLD.FO_FOLIO <> 0*/)) THEN
  BEGIN
     NEW.GLSTATUS = OLD.GLSTATUS;
     IF (NEW.TOTAL < NEW.TOTALDUE) THEN
        NEW.TOTAL = OLD.TOTALDUE;
     IF (NEW.TOTAL < OLD.TOTAL) THEN
     BEGIN
        INSERT INTO arvch
          (number,
          document,
          opendate,
          duedate,
          customer, source, 
          total, adjust, paid, paidprepare,
          fo_guestname, fo_arrival, fo_departure,
          fo_room, fo_roomtype, fo_pax, fo_child,
          fo_ratecode, fo_ratediscount, fo_roomrate,
          fo_folio, fo_trans_id, fo_segment, fo_voucher,
          createuser, edituser, createdate, editdate,
          currency, exchange, forex_total, note, glstatus) /* 17 april 2002 */
        VALUES
          (0,
          'Splited from ' || OLD.NUMBER,
          NEW.opendate,
          NEW.duedate,
          NEW.customer, NEW.source, 
          OLD.TOTAL-NEW.total, 0, 0, 0,
          NEW.fo_guestname, NEW.fo_arrival, NEW.fo_departure,
          NEW.fo_room, NEW.fo_roomtype, NEW.fo_pax, NEW.fo_child,
          NEW.fo_ratecode, NEW.fo_ratediscount, NEW.fo_roomrate,
          NEW.fo_folio, NEW.fo_trans_id, NEW.fo_segment, NEW.fo_voucher,
          NEW.edituser, NEW.edituser, 'NOW', 'NOW',
          NEW.currency, NEW.exchange, (OLD.TOTAL-NEW.total)/NEW.EXCHANGE, NEW.NOTE, new.glstatus); /* 17 april 2002 */
     END
  END
  ELSE
  BEGIN
     NEW.TOTAL = OLD.TOTAL;
     NEW.FOREX_TOTAL = NEW.FOREX_TOTAL;
  END
end
^

