CREATE TRIGGER ARVCH_BUPDATE FOR ARVCH
ACTIVE BEFORE UPDATE POSITION 9
AS
declare variable vSysDate date;
/* 26 JUNI 2005 */
DECLARE VARIABLE FLAG_ACTIVE INTEGER;
DECLARE VARIABLE FLAG_CREDITFACILITY INTEGER;
/* 26 JULY 2007 */
DECLARE VARIABLE OLD_GLACCOUNT VARCHAR(20);
DECLARE VARIABLE OLD_GLDEPT VARCHAR(4);
DECLARE VARIABLE OLD_GLCOST VARCHAR(4);
DECLARE VARIABLE NEW_GLACCOUNT VARCHAR(20);
DECLARE VARIABLE NEW_GLDEPT VARCHAR(4);
DECLARE VARIABLE NEW_GLCOST VARCHAR(4);
begin
  /* 26 JUNI 2005 */
  IF (NEW.CUSTOMER <> OLD.CUSTOMER) THEN
  BEGIN
    IF (NOT EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = NEW.CUSTOMER)) THEN
      EXCEPTION E_FOGUEST_COMPANY_NOT_FOUND;

    SELECT FLAG_ACTIVE, CREDITFACILITY
    FROM SYSCUSTOMER WHERE CUSTOMER = NEW.CUSTOMER
    INTO FLAG_ACTIVE, FLAG_CREDITFACILITY;
  
    IF (FLAG_ACTIVE <> 1) THEN EXCEPTION E_FOGUEST_COMPANY_NOT_ACTIVE;
    IF (FLAG_CREDITFACILITY <> 1) THEN EXCEPTION E_JUR_CL_NO_CREDITFACILITY;
    /* ---------------------------------------------------------------- */
    /* 26 JULY 2007                                                     */
    /* ---------------------------------------------------------------- */
    SELECT T.GLACCOUNT, T.GLDEPT, T.GLCOST FROM SYSCUSTOMER C
    LEFT JOIN SYSCUSTOMERTYPE T ON C.CUSTTYPE = T.CUSTOMERTYPE
    WHERE C.CUSTOMER = NEW.CUSTOMER
    INTO NEW_GLACCOUNT, NEW_GLDEPT, NEW_GLCOST;
    
    SELECT T.GLACCOUNT, T.GLDEPT, T.GLCOST FROM SYSCUSTOMER C
    LEFT JOIN SYSCUSTOMERTYPE T ON C.CUSTTYPE = T.CUSTOMERTYPE
    WHERE C.CUSTOMER = OLD.CUSTOMER
    INTO OLD_GLACCOUNT, OLD_GLDEPT, OLD_GLCOST;

    
    IF ((OLD_GLACCOUNT <> NEW_GLACCOUNT) OR
        (OLD_GLDEPT <> NEW_GLDEPT) OR
        (OLD_GLCOST <> NEW_GLCOST))  THEN
    BEGIN
       EXCEPTION E_FOGUEST_COMPANY_NOT_FOUND
                 'Old Customer A/C ("'||OLD_GLACCOUNT||'") not matched with new ("'||NEW_GLACCOUNT||'")';
    END
    /* ---------------------------------------------------------------- */
    /* END OF 26 JULY 2007                                              */
    /* ---------------------------------------------------------------- */
  END
  /* 26 JUNI 2005 */
  IF (NEW.FO_FOLIO <> 0) THEN NEW.OPENDATE = OLD.OPENDATE;
  select arsysdate from fosysparam into :vSysDate;
  
  new.editdate = 'now';
  /* ------------------------------------------------------------------------ */
  /* GANTI EXCHANGE RATE, PLEASE DO NOT MODIFY, ALREADY TESTED                */
  /* ------------------------------------------------------------------------ */
  IF ((OLD.EXCHANGE <> NEW.EXCHANGE) OR (NEW.TOTAL <> OLD.TOTAL)) THEN
     NEW.FOREX_TOTAL = NEW.TOTAL / NEW.EXCHANGE;
  /* ------------------------------------------------------------------------ */
  if ((new.forex_totaldue < 0.01) and (new.forex_totaldue > -0.01)) then begin
     new.paidstatus = 'P';
     new.status = 'C';
  end
  else begin
    new.paidstatus = 'O';
    new.status = 'O';    
  end
  
  if (new.forex_paidprepare <> 0) then
  begin
     new.paidstatus = 'O';
     new.status = 'R';
  end  
  
  IF ((OLD.FO_FOLIO <> 0) AND (NEW.OPENDATE <> OLD.OPENDATE)) THEN NEW.OPENDATE = OLD.OPENDATE;
  IF (NEW.FLAG_MERGED IS NULL) THEN NEW.FLAG_MERGED = 0;
  
  /* ---------------------------------------------------------------- */
  /* 28 MARET 2008                                                    */
  /* ---------------------------------------------------------------- */
  IF (NEW.FOREX_TOTALDUE_PREPARE <> 0) THEN
     NEW.EXCHANGE_NOW = NEW.TOTALDUE_PREPARE/NEW.FOREX_TOTALDUE_PREPARE;
end
^

CREATE TRIGGER ARVCH_DETAIL_BD FOR ARVCH_DETAIL
ACTIVE BEFORE DELETE POSITION 0
as
declare variable vStatus CHAR(1);
begin
  SELECT STATUS FROM ARVCH WHERE NUMBER = OLD.NUMBER INTO :vSTATUS;
  if (vSTATUS <> 'D') then begin
     if (old.status <> 'O') then exception AR_VOUCHER_DETAIL_STATUS;
     if (old.source = 'A') then /* adjustment close */
     begin
        UPDATE ARVCH SET FO_STATUS_CORRECTION = 'O',
               ADJUST_FO = ADJUST_FO -(OLD.DEBIT-OLD.CREDIT),
               FOREX_ADJUST_FO = FOREX_ADJUST_FO -(OLD.FOREX_DEBIT-OLD.FOREX_CREDIT)
        WHERE NUMBER = OLD.NUMBER;
     end
  end
end
^

CREATE TRIGGER ARVCH_DETAIL_BI FOR ARVCH_DETAIL
ACTIVE BEFORE INSERT POSITION 0
as
declare variable currency varchar(4);
declare variable exchange double precision;
declare variable OPENDATE DATE;
begin
  NEW.DETAIL_ID = GEN_ID(GEN_ARVCH_DETAIL_ID,1);
  if (NEW.SOURCE = 'A') then /* adjustment */
  begin
     /* BEGIN 17 APRIL 2002 */
     SELECT OPENDATE, CURRENCY FROM ARVCH WHERE NUMBER = NEW.NUMBER
     INTO :OPENDATE, :CURRENCY;
     
     if (NEW.FODATE < :OPENDATE) then
        EXCEPTION AR_DATE_LESS_THAN_VOUCHER;
     
     SELECT EXCHANGE FROM FOFOREX WHERE CURRENCY = :CURRENCY
     INTO :EXCHANGE;
     
     if (EXCHANGE IS NULL) then EXCHANGE = 1;
     if (EXCHANGE < 0) then EXCHANGE = 1;
     NEW.EXCHANGE = EXCHANGE;
     
     UPDATE ARVCH SET FO_STATUS_CORRECTION = 'O',
            ADJUST_FO = ADJUST_FO + NEW.DEBIT-NEW.CREDIT,
            FOREX_ADJUST_FO = FOREX_ADJUST_FO + NEW.FOREX_DEBIT-NEW.FOREX_CREDIT
     WHERE NUMBER = NEW.NUMBER;
     /* END 17 APRIL 2002 */
  end

end
^

CREATE TRIGGER ARVCH_DETAIL_BU FOR ARVCH_DETAIL
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable folio integer;
declare variable CLTrans_ID INTEGER;
declare variable CLCategory VARCHAR(4);
declare variable V DOUBLE PRECISION;
declare variable CURRENCY VARCHAR(4);
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable VROW INTEGER;
declare variable CUSTOMER VARCHAR(6);
begin
  if (old.status <> 'O') then
     if ((old.fodate<>new.fodate) or
         (new.debit <> old.debit) or
         (new.credit <> old.credit) or
         (old.remark <> new.remark)) then
         exception AR_VOUCHER_DETAIL_STATUS;
  /*
     BACK OFFICE CORRECTION
  */
  
  if (old.source = 'A') then /* adjustment close */
  begin
     if ((old.status = 'O') and (new.status = 'O')) then
         UPDATE ARVCH SET FO_STATUS_CORRECTION = 'O',
                ADJUST_FO = ADJUST_FO + NEW.DEBIT-NEW.CREDIT-(OLD.DEBIT-OLD.CREDIT),
                FOREX_ADJUST_FO = FOREX_ADJUST_FO + /* 17-April-2002 */
                                  NEW.FOREX_DEBIT-NEW.FOREX_CREDIT-
                                  (OLD.FOREX_DEBIT-OLD.FOREX_CREDIT)
         WHERE NUMBER = NEW.NUMBER;
     
     if ((old.status ='O') AND (new.status ='C')) then
     begin
         SELECT CUSTOMER FROM ARVCH WHERE NUMBER = NEW.NUMBER INTO :CUSTOMER;
         
         UPDATE ARVCH SET FO_STATUS_CORRECTION = 'O',
                ADJUST = ADJUST + NEW.DEBIT-NEW.CREDIT,
                ADJUST_FO = ADJUST_FO-(OLD.DEBIT-OLD.CREDIT),
                FOREX_ADJUST = FOREX_ADJUST + NEW.FOREX_DEBIT-NEW.FOREX_CREDIT, /* 17 april 2002 */
                FOREX_ADJUST_FO = FOREX_ADJUST_FO-(OLD.FOREX_DEBIT-OLD.FOREX_CREDIT) /* 17 april 2002 */
         WHERE NUMBER = NEW.NUMBER;
     
        SELECT FO_FOLIO, FO_TRANS_ID, CURRENCY FROM ARVCH WHERE NUMBER = NEW.NUMBER
        INTO :folio, CLTrans_ID, CURRENCY;
        if (FOLIO <> 0) then BEGIN
           SELECT CATEGORY FROM FOGUEST_JUR WHERE TRANS_ID = :CLTrans_ID
           INTO CLCategory;

           NEW.FO_TRANS_ID = GEN_ID(GEN_TRANS_ID,0)+1;
           select fosysdate from fosysparam into new.fodate;
           /* CREATE ADJUSTMENT */
           INSERT INTO FOGUEST_JUR
                  (FOLIO,     FODATE,     CATEGORY,   REMARK,     DEBIT,
                   CREDIT,    JURCODE,    REFERENCE,  USERENTRY,  USEREDIT,
                   USERPOST,  HIDDEN,     CORRECTED,  SOURCE,     SOURCE_ID,
                   TRANS_ID_BATCH,
                   CURRENCY, FOREX) /* 17 APRIL 2002 */
           VALUES (:FOLIO,    NEW.FODATE, NEW.CATEGORY,  NEW.REMARK,     NEW.DEBIT,
                   NEW.CREDIT,    'BO',    '',  NEW.EDITBY,  NEW.EDITBY,
                   '',  2,     0,  'AR',   NEW.NUMBER,
                   NEW.FO_TRANS_ID,
                   :CURRENCY, NEW.EXCHANGE); /* 17 APRIL 2002 */
           /* CORRECTION A/R */
           INSERT INTO FOGUEST_JUR
                  (FOLIO,     FODATE,     CATEGORY,   REMARK,     DEBIT,
                   CREDIT,    JURCODE,    REFERENCE,  USERENTRY,  USEREDIT,
                   USERPOST,  HIDDEN,     CORRECTED,  SOURCE,     SOURCE_ID,
                   TRANS_ID_BATCH,
                   CURRENCY, FOREX) /* 17 APRIL 2002 */                   
           VALUES (:FOLIO,    NEW.FODATE, :CLCategory,  NEW.REMARK,     NEW.CREDIT,
                   NEW.DEBIT,    'BO',    '',  NEW.EDITBY,  NEW.EDITBY,
                   '',  2,     0,  'AR',   NEW.NUMBER,
                   NEW.FO_TRANS_ID,
                   :CURRENCY, NEW.EXCHANGE); /* 17 APRIL 2002 */                   
        END /* FOLIO <> 0 */
        
     end
  end
end
^

CREATE TRIGGER ARVCH_DETAIL_POST_GL FOR ARVCH_DETAIL
ACTIVE AFTER UPDATE POSITION 0
AS
DECLARE VARIABLE ID INTEGER;
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE NOTE VARCHAR(40);
DECLARE VARIABLE REFF VARCHAR(20);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
DECLARE VARIABLE RELATION_CODE VARCHAR(6);
DECLARE VARIABLE RELATION_DOCTYPE INTEGER;
begin
  /* ------------------------------------------------------------------------ */
  /* 25 AGUSTUS 2008                                                          */
  /*          KHUSUS ADJUSTMENT DARI BACK OFFICE                              */
  /*          STATUS ->   Open (O) ==> Close (C)                              */
  /* ------------------------------------------------------------------------ */
  IF ((OLD.SOURCE = 'A') AND (OLD.STATUS = 'O') AND (NEW.STATUS = 'C') AND (NEW.DEBIT+NEW.CREDIT <> 0)) THEN
  BEGIN
     FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, REF, DEBIT, CREDIT, RELATION_CODE, RELATION_DOCTYPE
         FROM AR_GLBUFFER_VCH_EOD_DETAIL(NEW.NUMBER)
         INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
              NOTE, REFF, DB, CR, RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        INSERT INTO GLBUFFER
               (APPLICATION, SOURCE, NUMBER, ID, TRANSDATE,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
        VALUES ('AR','AFO', OLD.NUMBER, :ID, OLD.FODATE,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :NOTE, :REFF,
                :DB, :CR,
                'NOW', NEW.EDITBY, :RELATION_CODE, :RELATION_DOCTYPE);
     END

  END
END
^

CREATE TRIGGER ARVCH_FO_CORRECTION FOR ARVCH
ACTIVE AFTER UPDATE POSITION 0
as
begin
  if ((NEW.FO_STATUS_CORRECTION = 'C') AND
      (OLD.FO_STATUS_CORRECTION = 'O')) then
  begin
     update arvch_detail set
            status = 'C',
            editby = new.edituser,
            editdate='now'
     where number = old.number
     and source = 'A'
     and status = 'O';
  end
end
^

