CREATE TRIGGER FO_CUST_RATE_BI FOR FO_CUST_RATE
ACTIVE BEFORE INSERT POSITION 0
as
declare variable ratetype char(1);
declare variable datestart date;
declare variable dateend   date;
declare variable maxdiscount double precision;
begin
  select g.ratetype, rt.datestart, rt.dateend, maxdiscount
  from forate rt
  left join forate_group g on rt.rategroup = g.rategroup
  where rt.ratecode = new.ratecode
  into :ratetype, :datestart, :dateend, :maxdiscount;
  
  if (ratetype <> 'C') then exception  E_CUST_RATE_CONTRACT_TYPE;
  if ((new.datestart < datestart) or
      (new.datestart > dateend) or
      (new.dateend < datestart) or
      (new.dateend > dateend))  then
     exception E_CUST_RATE_CONTRACT_PERIOD;
  if (new.discount < 0) then new.discount = 0;
  if (new.discount > maxdiscount) then new.discount = maxdiscount;
end
^

