CREATE TRIGGER FOSTAT_LOG_BI_RMS FOR FOSTAT_LOG
ACTIVE BEFORE INSERT POSITION 1
AS
/* 21 MAY 2010 */
DECLARE VARIABLE DATECI TIMESTAMP;
DECLARE VARIABLE DATECREATE TIMESTAMP;
BEGIN
  SELECT DATECI, DATECREATE, DATERESV /* 21 MAY 2010 */
  FROM FOGUEST
  WHERE FOLIO = NEW.FOLIO
  INTO DATECI, DATECREATE, NEW.DATERESV; /* 21 MAY 2010 */
  /* -------------------------------------------------------------------- */
  IF (NEW.DATERESV IS NULL) THEN
     NEW.DATERESV = EXTRACT(DAY FROM DATECREATE) || '.' ||
                    EXTRACT(MONTH FROM DATECREATE) || '.' ||
                    EXTRACT(YEAR FROM DATECREATE);
  NEW.LEAD_DAY = DATECI - NEW.DATERESV;
END
^

