CREATE TRIGGER FOSYSPARAM_AR_EOD FOR FOSYSPARAM
ACTIVE BEFORE UPDATE POSITION 0
AS
declare variable CREDITCARD INTEGER;
declare variable CUSTOMER VARCHAR(6);
declare variable NAME VARCHAR(40);
declare variable CURR NUMERIC(15,4);
declare variable OVER30 NUMERIC(15,4);
declare variable OVER60 NUMERIC(15,4);
declare variable OVER90 NUMERIC(15,4);
declare variable OYEAR INTEGER;
declare variable OMONTH INTEGER;
declare variable NYEAR INTEGER;
declare variable NMONTH INTEGER;
begin
  if (new.arsysdate = old.arsysdate+1) then
  begin
     /* ---------------------------------------------------------------- */
     /* CHECK STATUS NOT RELEASED, INVALID DATE                          */
     /* ---------------------------------------------------------------- */
     if (EXISTS (select * from aradj where opendate < new.arsysdate and status = 'O')) then
        exception AR_ADJUSTMENT_NOT_RELEASE;
     /* 21 april 2006 */
     if (EXISTS (select * from ARDEPOS1 where APPLIEDDATE < new.arsysdate and status = 'O')) then
        EXCEPTION AR_DEPOSIT_NOT_RELEASE;

     if (EXISTS (select * from ARDEPOS0 where OPENDATE < new.arsysdate and status = 'O')) then
        EXCEPTION AR_DEP_APPLY_NOT_RELEASE;

     if (EXISTS (select * from ARCASH0 where DUEDATE < new.arsysdate and status = 'O')) then
        EXCEPTION AR_CASH_DUE_INVALID;
     /* 21 april 2006 */
     /* 20 mei 2006 */
     if (EXISTS (select * from ARDEPOS0_JUR where OPENDATE < new.arsysdate and status = 'O')) then
        EXCEPTION AR_DEP_ADJUST_NOT_RELEASE;
     /* 20 mei 2006 */






     
     /* ---------------------------------------------------------------- */
     /* UPDATE BATCH                                                     */
     /* ---------------------------------------------------------------- */
     IF (NEW.AR_BATCH_INSTALLED<>1) THEN /* 29 AGUSTUS 2005, DAILY UPDATE DARI BATCH */
     UPDATE ARVCH SET GLSTATUS = 'C' WHERE OPENDATE <= OLD.ARSYSDATE AND GLSTATUS = 'O'; /* <=, TADINYA = (14 JUN 2007) */






     /* ---------------------------------------------------------------------- */
     /* ADJUSTMENT                                                             */
     /* ---------------------------------------------------------------------- */
     update aradj set status = 'C' where opendate < new.arsysdate
        and status = 'R';
     /* ---------------------------------------------------------------------- */
     /* STATUS CASH SBB                                                        */
     /*   O=(Prepare)   -> R=(Release)   [MANUAL] -> Masuk ke GL               */
     /*                    Bank Clearance (DB) | A/R (CR)                      */
     /*      -ditagih-       -check diterima-                                  */
     /*   R=(Release)   -> L=(Reconcile) [BankBook]                            */
     /*   L=(Reconcile) -> C=(Close/Paid)[EOD]    -> Masuk Bank Book(GL Enggak)*/
     /*                    Bank (DB) | Bank Clearance (CR)                     */
     /*      -check sudah cair-                                                */
     /* ---------------------------------------------------------------------- */
     update arcash0 set status = 'C'
      where reconciledate < new.arsysdate and status = 'L';
     /* ---------------------------------------------------------------------- */
     /* STATUS CASH DEPOSIT :                                                  */
     /*  O=(Open)      -> R=(Release)   [Manual]     -> Masuk G/L              */
     /*                    Bank Clearance (DB) | A/R (CR)                      */
     /*  R=(Release)   -> L=(Reconcile) [BankBook]                             */
     /*  L=(Reconcile) -> C=(Close)     [End of Day] -> Masuk Bank Book (GL No)*/
     /*                    Bank (DB) | Bank Clearance (CR)                     */
     /* ---------------------------------------------------------------------- */
     update ardepos0 set status = 'C'
      where opendate < new.arsysdate and status = 'L';
          
     update ardepos1 set status = 'C'
      where applieddate < new.arsysdate and status = 'R';
     /* ------------------------------------------------------------------ */
     /* credit card                                                        */
     /* ------------------------------------------------------------------ */     
     update ar_card_batch set status = 'C'
      where pay_date < new.arsysdate and status = 'L';
     /* ---------------------------------------------------------------------- */
     /* DEPOSIT ADJUSTMENT                                                     */
     /* ---------------------------------------------------------------------- */
     update ARDEPOS0_JUR set status = 'C' where opendate < new.arsysdate
        and status = 'R';
      
      
      
      
      
      
      
      
      
      
      
  end /* END OF DATE CHANGE */
end
^

