CREATE TRIGGER PBX_CALL_LOG_BU FOR PBX_CALL_LOG
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable REF VARCHAR(20);
declare variable REMARK VARCHAR(40);
declare variable H INTEGER;
declare variable M INTEGER;
declare variable S INTEGER;
declare variable SEC INTEGER;
declare variable TIME_NAME VARCHAR(10);
declare variable CALL_SAVE INTEGER;
declare variable CAT VARCHAR(4);
declare variable ZONE VARCHAR(6);
declare variable F_CLOSE INTEGER;
declare variable F_STATUS CHAR(1);
begin
  if (((NEW.STATUS = 'P') AND (OLD.STATUS = 'O')) AND
      ((NEW.FO_TRANS_ID = 0) AND (NEW.ERROR_CODE ='')) AND (NEW.HOUSE_USE=OLD.HOUSE_USE))
  then
  BEGIN
     SELECT FLAG_TRANSACTION_CLOSE, FOLIOSTATUS
     FROM foguest WHERE FOLIO = NEW.FOLIO
     INTO F_CLOSE, F_STATUS;
    
     if (F_CLOSE  <>  0 ) then exception e_pbx_transaction_closed;
     if (F_STATUS <> 'I') then exception e_pbx_folio_not_in_house;
    
  
     /* CALCULATION FORMATED DURATION */
     SEC = NEW.DURATION;
     H = CAST(SEC / 3600 -0.5 AS INTEGER);
     SEC = SEC - H * 3600;
     M = CAST(SEC / 60-0.5 AS INTEGER);
     S = SEC - M * 60;
  
     if (H < 10) then TIME_NAME = '0'||H || ':';
     ELSE TIME_NAME = H || ':';

     if (M < 10) then TIME_NAME = TIME_NAME ||'0' || M || ':';
     ELSE TIME_NAME = TIME_NAME || M || ':';

     if (S < 10) then TIME_NAME = TIME_NAME ||'0' || S;
     ELSE TIME_NAME = TIME_NAME || S;
     
     /* FIND CITY FROM SLJJ */
     SELECT PBX_ZONE, CITY FROM pbx_sljj WHERE SLJJ = NEW.SLJJ
     INTO ZONE, REF;
     if (REF IS NULL) then REF = NEW.SLJJ;
     if (REF IS NULL) then REF = '';
     
     SELECT CATEGORY FROM PBX_PRICE
     WHERE ZONE = :ZONE
     INTO :CAT;
     
     if (CAT IS NULL) then CAT = '340';
     
     REMARK = NEW.PHONE ||' (' || TIME_NAME || ')';
     if (REMARK IS NULL) then REMARK = NEW.PHONE ||' (' || NEW.DURATION || ')';

     INSERT INTO FOGUEST_JUR (
        FOLIO,           FODATE,         CATEGORY,       REMARK,
        DEBIT,           CREDIT,
        SYSDATE,         CURRENCY,       FOREX,          JURCODE,
        REFERENCE,       USERENTRY,      USEREDIT,       USERPOST,
        HIDDEN,          ROOM,
        SOURCE,          SOURCE_ID,      AR_CUSTOMER)
     VALUES (
        NEW.FOLIO,   NEW.FODATE,         :CAT,    :REMARK,
        NEW.CHARGE,  0,
        'NOW',           'IDR',          1,      'PBX',
        :REF,    'PBX',          '',   '',
        0,     NEW.ROOM,
        'PX',  NEW.ID, '');
     NEW.FO_TRANS_ID = GEN_ID(GEN_TRANS_ID,0)+1;
  end
end
^

CREATE TRIGGER PBX_CALL_LOG_BU_DURATION_NAME FOR PBX_CALL_LOG
ACTIVE BEFORE UPDATE POSITION 3
AS
DECLARE VARIABLE SEC INTEGER;
DECLARE VARIABLE H INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE S INTEGER;
BEGIN
  IF ((NEW.DURATION_NAME ='') OR (NEW.DURATION_NAME IS NULL)) THEN
  BEGIN
     SEC = NEW.DURATION;
     H = CAST(SEC / 3600 -0.5 AS INTEGER);
     SEC = SEC - H * 3600;
     M = CAST(SEC / 60-0.5 AS INTEGER);
     S = SEC - M * 60;

     if (H < 10) then NEW.DURATION_NAME = '0'||H || ':';
     ELSE NEW.DURATION_NAME = H || ':';

     if (M < 10) then NEW.DURATION_NAME = NEW.DURATION_NAME ||'0' || M || ':';
     ELSE  NEW.DURATION_NAME =  NEW.DURATION_NAME || M || ':';

     if (S < 10) then  NEW.DURATION_NAME =  NEW.DURATION_NAME ||'0' || S;
     ELSE  NEW.DURATION_NAME =  NEW.DURATION_NAME || S;
     WHEN ANY DO
        NEW.DURATION_NAME = NEW.DURATION;
  END
END
^

CREATE TRIGGER PBX_CALL_LOG_BU_MOVE FOR PBX_CALL_LOG
ACTIVE BEFORE UPDATE POSITION 2
as
declare variable REF VARCHAR(20);
declare variable REMARK VARCHAR(40);
declare variable H INTEGER;
declare variable M INTEGER;
declare variable S INTEGER;
declare variable SEC INTEGER;
declare variable TIME_NAME VARCHAR(10);
declare variable CALL_SAVE INTEGER;
declare variable CAT VARCHAR(4);
declare variable ZONE VARCHAR(6);
declare variable F_CLOSE INTEGER;
declare variable F_STATUS CHAR(1);
begin
  if ((NEW.HOUSE_USE=0) AND
      (OLD.HOUSE_USE=1))  then
  BEGIN
     SELECT FLAG_TRANSACTION_CLOSE, FOLIOSTATUS
     FROM foguest WHERE FOLIO = NEW.FOLIO
     INTO F_CLOSE, F_STATUS;
     
     if (F_CLOSE IS NULL) then
     BEGIN
        F_CLOSE = 1;
        F_STATUS = 'C';
     END
    
     if (F_CLOSE  <>  0 ) then exception e_pbx_transaction_closed;
     if (F_STATUS <> 'I') then exception e_pbx_folio_not_in_house;  
  
     /* CALCULATION FORMATED DURATION */
     SEC = NEW.DURATION;
     H = CAST(SEC / 3600 -0.5 AS INTEGER);
     SEC = SEC - H * 3600;
     M = CAST(SEC / 60-0.5 AS INTEGER);
     S = SEC - M * 60;
  
     if (H < 10) then TIME_NAME = '0'||H || ':';
     ELSE TIME_NAME = H || ':';

     if (M < 10) then TIME_NAME = TIME_NAME ||'0' || M || ':';
     ELSE TIME_NAME = TIME_NAME || M || ':';

     if (S < 10) then TIME_NAME = TIME_NAME ||'0' || S;
     ELSE TIME_NAME = TIME_NAME || S;


     /* FIND CITY FROM SLJJ */
     SELECT PBX_ZONE, CITY FROM pbx_sljj WHERE SLJJ = NEW.SLJJ
     INTO ZONE, REF;
     if (REF IS NULL) then REF = NEW.SLJJ;
     if (REF IS NULL) then REF = '';

     SELECT CATEGORY FROM PBX_PRICE
     WHERE ZONE = :ZONE
     INTO :CAT;
     
     if (CAT IS NULL) then CAT = '340';
     
     REMARK = NEW.PHONE ||' (' || TIME_NAME || ')';
     if (REMARK IS NULL) then REMARK = NEW.PHONE ||' (' || NEW.DURATION || ')';

     NEW.FO_TRANS_ID = GEN_ID(GEN_TRANS_ID,0)+1;
     INSERT INTO FOGUEST_JUR (
        FOLIO,           FODATE,         CATEGORY,       REMARK,
        DEBIT,           CREDIT,
        SYSDATE,         CURRENCY,       FOREX,          JURCODE,
        REFERENCE,       USERENTRY,      USEREDIT,       USERPOST,
        HIDDEN,          ROOM,
        SOURCE,          SOURCE_ID,      AR_CUSTOMER)
     VALUES (
        NEW.FOLIO,   NEW.FODATE,         :CAT,    :REMARK,
        NEW.CHARGE,  0,
        'NOW',           'IDR',          1,      'PBX',
        :REF,    'PBX',          '',   '',
        0,     NEW.ROOM,
        'PX',  NEW.ID, '');
     NEW.STATUS = 'P';
  end
end
^

CREATE TRIGGER PBX_CALL_LOG_CALC_CHARGE FOR PBX_CALL_LOG
ACTIVE BEFORE INSERT POSITION 4
as
declare variable vMINIMUM INTEGER;
declare variable vSURCHARGE DOUBLE PRECISION;
declare variable vCHARGE DOUBLE PRECISION;
declare variable vCOST DOUBLE PRECISION;
declare variable vDURATION INTEGER;
declare variable vGRASS INTEGER;
declare variable vPULSE INTEGER;
declare variable vPULSE_COUNT INTEGER;

begin
  if (new.error_code = '') then begin
     select SURCHARGE, MINIMUM_DURATION, GRASS_PERIOD, PULSE_DURATION
     FROM pbx_price
     WHERE ZONE = NEW.PBX_ZONE
     INTO vSURCHARGE, vMINIMUM, vGRASS, vPULSE;
     
     if (vPULSE IS NULL) then vPULSE = 0;
     if (vPULSE <= 0) then
        NEW.ERROR_CODE = 'PULSE_IS_ZERO';
     ELSE
     if ((NEW.DURATION < vGRASS) AND (vPULSE > 0)) then
        NEW.ERROR_CODE = 'LESS_THAN_GRASS';
     ELSE BEGIN
        SELECT COST, PRICE FROM pbx_price_hour
        WHERE ZONE = NEW.PBX_ZONE
        AND PHOUR = NEW.PHOUR
        INTO vCOST, vCHARGE;
        
        if (NEW.DURATION < vMinimum) then
           vPULSE_COUNT = 1;
        ELSE
           vPULSE_COUNT = (NEW.DURATION +0.5*vPULSE)/ vPULSE;
        SELECT HOUSE_USE FROM pbx_extention WHERE EXTENTION = NEW.EXTENTION
        INTO NEW.HOUSE_USE;
        if ((NEW.HOUSE_USE = 1) OR (NEW.DEPT <> '')) then vCHARGE = vCOST;
        if (vCHARGE IS NULL) then BEGIN
           vCOST = 0;
           vCHARGE = 0;
           NEW.ERROR_CODE = 'PRICE_NOT_EXIST';
        END ELSE BEGIN
           NEW.COST = vCOST * vPULSE_COUNT;
           NEW.CHARGE = vSURCHARGE + vCHARGE * vPULSE_COUNT;
        END
     END
  end
  if ((new.error_code = '') and (new.charge = 0)) then
     NEW.ERROR_CODE = 'CHARGE_ZERO';
end
^

CREATE TRIGGER PBX_CALL_LOG_FIND_ROOM FOR PBX_CALL_LOG
ACTIVE BEFORE INSERT POSITION 8
as
declare variable vROOM VARCHAR(8);
declare variable vDEPT VARCHAR(4);
declare variable vFOLIO INTEGER;
declare variable vROW integer;
declare variable F_CLOSE INTEGER;
declare variable F_STATUS CHAR(1);
begin
  if (new.ERROR_CODE = '') then BEGIN
     /* ------------------------------------------------------------------------ */
     /* load extention properties                                                */
     /* ------------------------------------------------------------------------ */
     SELECT ROOM, DEPT, FOLIO, HOUSE_USE FROM pbx_extention
     WHERE EXTENTION = NEW.EXTENTION
     INTO vROOM, vDEPT, vFOLIO, NEW.HOUSE_USE;
     /* ------------------------------------------------------------------------ */
     /* validasi                                                                 */
     /* ------------------------------------------------------------------------ */
     if (NEW.HOUSE_USE IS NULL) then NEW.HOUSE_USE  = 0;
     if (vROOM IS NULL) then vROOM = '';
     if (vDept IS NULL) then vDept = '';
     if (vFolio is NULL) then vFolio = 0;
     /* ------------------------------------------------------------------------ */
     /* tentukan posting-nya kemana                                              */
     /* ------------------------------------------------------------------------ */
     if ((vROOM = '') and (vDept = '') and (vFolio = 0)) then
        NEW.ERROR_CODE = 'EXTENTION_ERROR';
     else begin
        if (vRoom <> '') then begin
           vDept = '';
           vFolio = 0;
           SELECT FOLIO FROM FOGUEST
           WHERE ROOM = :vROOM
           AND FOLIOSTATUS = 'I'
           AND FOLIOSTATUS_SHARE = 'M'
           INTO :vFolio;

           if ((vFolio is Null) or (vFolio <= 0)) then begin
              vFolio = 0;
              NEW.ERROR_CODE = 'FOLIO_NOT_EXIST';
           end
        end
        else if (vDept <> '') then begin
           vRoom = '';
           vFolio = 0;
           NEW.HOUSE_USE = 1;
           SELECT COUNT(*) FROM pbx_dept
           WHERE DEPT = :vDEPT
           INTO vROW;
           if (vROW = 0) then begin
              vDept = '';
              NEW.ERROR_CODE = 'DEPT_NOT_EXIST';
           end
        end else begin
           vRoom = '';
           vDept = '';
           SELECT COUNT(*) FROM FOGUEST
           WHERE FOLIO = :vFOLIO
           INTO :vRow;
           if (vFolio is Null) then begin
              vFolio = 0;
              NEW.ERROR_CODE = 'FOLIO_NOT_EXIST (2)';
           end
        end
     end
     NEW.FOLIO = vFolio;
     NEW.ROOM  = vROOM;
     NEW.DEPT  = vDEPT;
     if (NEW.DEPT <> '') then
     BEGIN
        NEW.CHARGE = NEW.COST; /* KALAU DEPARTMENT MAKA CHARGE = COST */
     END

        
     if (NEW.FOLIO > 0) then BEGIN
        SELECT FLAG_TRANSACTION_CLOSE, FOLIOSTATUS
        FROM foguest WHERE FOLIO = NEW.FOLIO
        INTO F_CLOSE, F_STATUS;
    
        if (F_CLOSE = 1) then
           NEW.ERROR_CODE = 'TRANSACTION_CLOSE';
           
        if (F_STATUS <> 'I') then
           NEW.ERROR_CODE = 'FOLIO_STATUS_' || F_STATUS;
      END
     
  END /* ERROR CODE = '' */
  ELSE BEGIN
    NEW.FOLIO = 0;
    NEW.ROOM  = '';
    NEW.DEPT  = '';
  END
end
^

