CREATE TRIGGER SYSCUSTOMER_AU FOR SYSCUSTOMER
ACTIVE AFTER UPDATE POSITION 0
as
begin
  if (NEW.CUSTOMER <> OLD.CUSTOMER) then
  BEGIN
     UPDATE SYSCUSTOMER
     SET CUSTOMER_MAIN = NEW.CUSTOMER
     WHERE CUSTOMER_MAIN = OLD.CUSTOMER;

     UPDATE FOSTAT_LOG SET COMPANY = NEW.CUSTOMER
     WHERE COMPANY = OLD.CUSTOMER;

     UPDATE FOGUEST SET COMPANY = NEW.CUSTOMER
     WHERE COMPANY = OLD.CUSTOMER;

     UPDATE fo_hist_guest SET COMPANY = NEW.CUSTOMER
     WHERE COMPANY = OLD.CUSTOMER;
  END
end
^

CREATE TRIGGER SYSCUSTOMER_BI FOR SYSCUSTOMER
ACTIVE BEFORE INSERT POSITION 0
as
begin
  SELECT GLACCOUNT, GLDEPT
  FROM SYSCUSTOMERTYPE
  WHERE CUSTOMERTYPE = NEW.CUSTTYPE
  INTO NEW.ACCOUNT, NEW.GL_DEPT;
  if (NEW.CUSTOMER_MAIN IS NULL) then
     NEW.CUSTOMER_MAIN = NEW.CUSTOMER;
     if (NEW.CUSTOMER ='') then EXCEPTION E_CUSTOMER_CODE_BLANK;
end
^

CREATE TRIGGER SYSCUSTOMER_BU FOR SYSCUSTOMER
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  IF (NOT EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = CUSTOMER_MAIN)) THEN
     NEW.CUSTOMER_MAIN = NEW.CUSTOMER;
     
  IF (OLD.CUSTTYPE <> NEW.CUSTTYPE) THEN
  BEGIN
     IF (EXISTS (SELECT * FROM ARVCH WHERE PAIDSTATUS = 'P' AND CUSTOMER = OLD.CUSTOMER)) THEN
     BEGIN
        NEW.CUSTTYPE = OLD.CUSTTYPE;
     END
  END
end
^

CREATE TRIGGER SYSCUSTOMER_BU_GRADE FOR SYSCUSTOMER
ACTIVE BEFORE UPDATE POSITION 1
AS
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE N INTEGER;
DECLARE VARIABLE BOM DATE;
DECLARE VARIABLE DATECI DATE;
DECLARE VARIABLE DATECO DATE;
BEGIN
  /* CREATED ON 3 JANUARY 2006 */
  IF (NEW.NIGHT_AVG < 0) THEN
  BEGIN
     SELECT EXTRACT(YEAR FROM FOSYSDATE),EXTRACT(MONTH FROM FOSYSDATE)
     FROM FOSYSPARAM INTO Y,M;
     M = M - 1;
     IF (M < 1) THEN
     BEGIN
        M = 12;
        Y = Y-1;
     END
     I = 1;
     NEW.NIGHT_AVG = 0;
     WHILE (I <= 3) DO
     BEGIN
        SELECT SUM(NIGHT) FROM FOSTAT
        WHERE PYEAR = :Y AND PMONTH = :M AND DATATYPE = 'COMP' AND DATA = NEW.CUSTOMER
        INTO N;
        IF (N IS NULL) THEN N = 0;
        NEW.NIGHT_AVG = NEW.NIGHT_AVG + N;
        I = I +1;
        M = M - 1;
        IF (M < 1) THEN
        BEGIN
           M = 12;
           Y = Y-1;
        END
     END
     NEW.NIGHT_AVG = NEW.NIGHT_AVG/3;
  END
  
  IF (NEW.NIGHT_FORECAST < 0) THEN
  BEGIN
    SELECT FOSYSDATE FROM FOSYSPARAM INTO BOM;
    EXECUTE PROCEDURE SP_BEGINOFMONTH(BOM) RETURNING_VALUES BOM;
    NEW.NIGHT_FORECAST = 0;
    FOR SELECT DATECI,DATECO FROM FOGUEST
        WHERE COMPANYNAME = NEW.NAME
        AND COMPANY = NEW.CUSTOMER
        AND FOLIOTYPE = 'P'
        AND DATECO >= :BOM
        AND FOLIOSTATUS IN ('O','I','G','C','W','T')
    INTO DATECI,DATECO
    DO
    BEGIN
      IF (DATECI < BOM) THEN DATECI = BOM;
      NEW.NIGHT_FORECAST = NEW.NIGHT_FORECAST + DATECO - DATECI;
    END
  END
  
  IF (OLD.NIGHT_AVG <> NEW.NIGHT_AVG) THEN
  BEGIN
     IF (NOT EXISTS(SELECT * FROM SYSCUSTOMER_GRADE)) THEN
     BEGIN
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (7,'A+ (more than 51)',51,1000,51,10000);
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (6,'A (41-50)',        41,50,41,10000);
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (5,'A-(31-40)',        31,40,31,40);
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (4,'B (21-30)',        21,30,21,30);
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (3,'C (11-20)',        11,20,11,20);
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (2,'D (5-10)',         5,10,5,10);
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (1,'E (1-4)',         1,4,1,4);
       INSERT INTO SYSCUSTOMER_GRADE (GRADE,NAME,NIGHT_AVG_BEGIN,NIGHT_AVG_END,NIGHT_FORECAST_BEGIN,NIGHT_FORECAST_END)
       VALUES (0,'F (Zero)',          0,0,0,0);
     END
     
     SELECT MIN(GRADE) FROM SYSCUSTOMER_GRADE
     WHERE NEW.NIGHT_AVG BETWEEN NIGHT_AVG_BEGIN AND NIGHT_AVG_END
     INTO NEW.GRADE_AVG;
     IF (NEW.GRADE_AVG IS NULL) THEN NEW.GRADE_AVG = 0;
  END

  IF (OLD.NIGHT_FORECAST <> NEW.NIGHT_FORECAST) THEN
  BEGIN
     SELECT MIN(GRADE) FROM SYSCUSTOMER_GRADE
     WHERE NEW.NIGHT_FORECAST BETWEEN NIGHT_FORECAST_BEGIN AND NIGHT_FORECAST_END
     INTO NEW.GRADE_FORECAST;
     IF (NEW.GRADE_FORECAST IS NULL) THEN NEW.GRADE_FORECAST = 0;
  END
END

^

CREATE TRIGGER SYSCUSTOMER_COMMISSION_BI FOR SYSCUSTOMER_COMMISSION
ACTIVE BEFORE INSERT POSITION 0
as
begin
  if (NEW.NIGHT_FEE IS NULL) THEN NEW.NIGHT_FEE = 0;
  if (NEW.STAY_FEE IS NULL) THEN NEW.STAY_FEE = 0;
  if (NEW.ROOMREVENUE_PERCENT IS NULL) THEN NEW.ROOMREVENUE_PERCENT = 0;
  if (NEW.TOTALREVENUE_PERCENT IS NULL) THEN NEW.TOTALREVENUE_PERCENT = 0;
end
