ALTER PROCEDURE ARVCH_CHECK_SPLITDATE(
    PSAVE INTEGER)
RETURNS (
    PYEAR INTEGER,
    PMONTH INTEGER,
    OYEAR INTEGER,
    OMONTH INTEGER,
    DOCUMENT VARCHAR(20),
    FO_FOLIO INTEGER,
    FO_TRANS_ID INTEGER,
    NUMBER INTEGER,
    ODATE DATE,
    OPENDATE DATE,
    CUSTOMER VARCHAR(6),
    TOTAL DOUBLE PRECISION)
AS
DECLARE VARIABLE XDATE DATE;
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE COUNTER INTEGER;
BEGIN
  /* ---------------------------------------------------------------- */
  /* MEMERIKSA OPENDATE YG TIDAK DENGAN ORIGINAL DATE VOUCHER         */
  /* ---------------------------------------------------------------- */
  /* PSAVE = 0 HANYA REPORT SAJA                                      */
  /* PSAVE = 1 OPENDATE DI UPDATE SESUAI ORIGINAL                     */
  /* ---------------------------------------------------------------- */
  FOR
    SELECT FO_FOLIO,FO_TRANS_ID,COUNT(*) FROM ARVCH
    WHERE FO_FOLIO <> 0
    GROUP BY FO_FOLIO,FO_TRANS_ID
    INTO
      :FO_FOLIO,
      :FO_TRANS_ID,
      :COUNTER
  DO
  BEGIN
    IF (COUNTER > 1) THEN
    BEGIN
       I = 0;
       FOR SELECT NUMBER,OPENDATE FROM ARVCH WHERE FO_FOLIO = :FO_FOLIO
       AND FO_TRANS_ID = :FO_TRANS_ID
       ORDER BY NUMBER
       INTO NUMBER,OPENDATE
       DO
       BEGIN
         IF (I = 0) THEN ODATE = OPENDATE;
         IF (I > 0) THEN
         BEGIN
            IF (XDATE <> OPENDATE) THEN
            BEGIN
              FOR SELECT DOCUMENT,FO_FOLIO,FO_TRANS_ID,NUMBER,OPENDATE,
                  TOTAL,CUSTOMER
              FROM ARVCH
              WHERE FO_FOLIO = :FO_FOLIO
              AND FO_TRANS_ID = :FO_TRANS_ID
              ORDER BY NUMBER
              INTO DOCUMENT,FO_FOLIO,FO_TRANS_ID,NUMBER,OPENDATE,TOTAL,
                   CUSTOMER
              DO
              BEGIN
                 PYEAR = EXTRACT(YEAR FROM OPENDATE);
                 PMONTH = EXTRACT(MONTH FROM OPENDATE);

                 OYEAR = EXTRACT(YEAR FROM ODATE);
                 OMONTH = EXTRACT(MONTH FROM ODATE);
                 IF (PSAVE = 1) THEN
                 BEGIN
                    IF (ODATE <> OPENDATE) THEN
                    BEGIN
                       UPDATE ARVCH SET OPENDATE = :ODATE
                       WHERE NUMBER = :NUMBER;
                    END
                 END
                 ELSE
                    SUSPEND;
              END
            END
         END
         XDATE = OPENDATE;
         I = I + 1;
       END
    END
  END
END^


ALTER PROCEDURE AR_AGING(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    FO_FOLIO INTEGER,
    FO_GUESTNAME VARCHAR(80),
    AGE INTEGER,
    CREDITCARD INTEGER,
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40))
AS
declare variable d integer;
declare variable voucher double precision;

declare variable F_voucher double precision;
declare variable vPayDate Date;
declare variable ARDate DATE;
declare variable CREDITLIMIT DOUBLE PRECISION;
begin
  /* Procedure Text */
  if ((SCUSTOMER IS NULL) or (SCUSTOMER || ECUSTOMER = '')) then BEGIN
     SCUSTOMER = '';
     ECUSTOMER = 'zzzzzz';
  END

  if (DETAILFLAG IS NULL) then
      DETAILFLAG = 0;

  if (CURRENCY IS NULL) then CURRENCY = 'All';

  CREDITCARD = 0;

  SELECT ARSYSDATE+1 FROM FOSYSPARAM INTO ARDATE;

  for select CUSTOMER, name, CUSTTYPE, CREDITLIMIT from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE, CREDITLIMIT
  do
  begin
    SELECT NAME FROM SYSCUSTOMERTYPE
    WHERE CUSTOMERTYPE = :CUSTTYPE
    INTO :TYPENAME;
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    fo_folio = 0;
    fo_guestname = '';
    opendate = null;
    duedate = null;
    document = null;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number, totaldue, forex_totaldue,
               opendate, duedate, fo_folio, fo_guestname
          from ARvch
         where PAIDSTATUS = 'O'
           AND CUSTOMER = :CUSTOMER
           and ((totaldue <> 0) or (forex_totaldue <> 0))
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY))
         PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
         into number, voucher, f_voucher, opendate, duedate, fo_folio, fo_guestname
    do
    begin
       if (CURRENCY <> 'All') then
          voucher = f_voucher;
       d = ARDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then
            suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end
  end
  /* ------------------------------------------------------------------------ */
  /* credit card journal                                                      */
  /* ------------------------------------------------------------------------ */
  CUSTTYPE = 'CARD';
  TYPENAME = 'Credit Card';
  if (CURRENCY <> 'All') then exit;
  TOTAL  = 0;
  NUMBER = 0;
  CREDITCARD = 1;
  CREDITLIMIT = 0;
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :eCUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG <> 1) then
    begin
       CURR   = 0;
       OVER30 = 0;
       OVER60 = 0;
       OVER90 = 0;
       for select opendate, sum(total)
             from ar_card_jur
            where CREDITCARD = :CUSTOMER
              and status = 'O'
          group by opendate
            PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS))
             into opendate, voucher
       do begin
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          d = ARDate - opendate;
          if (d <= 30)      then curr   = curr + voucher;
          else if (d <= 60) then over30 = over30 + voucher;
          else if (d <= 90) then over60 = over60 + voucher;
          else over90 = over90 + voucher;
        end
        total = curr + over30 + over60 + over90;
        if (total <> 0) then suspend;
    end /* summary */
    /* ---------------------------------------------------------------------- */
    /* detail                                                                 */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG = 1) then
    begin
       for select number, opendate, total, fo_folio
             from ar_card_jur
            where CREDITCARD = :CUSTOMER
              and status = 'O'
            PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS))
             into number, opendate, voucher, fo_folio
       do begin
          CURR   = 0;
          OVER30 = 0;
          OVER60 = 0;
          OVER90 = 0;
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          AGE = ARDate - opendate;
          if (AGE <= 30)      then curr   = voucher;
          else if (AGE <= 60) then over30 = voucher;
          else if (AGE <= 90) then over60 = voucher;
          else over90 = voucher;
          total = curr + over30 + over60 + over90;
          if (total <> 0) then begin
             SELECT GUESTNAME FROM FO_RPT_HIST_GUESTNAME (:FO_FOLIO)
             INTO FO_GUESTNAME;
             suspend;
          end
       end
    end /* detail  */
  end /* credit card */
end^


ALTER PROCEDURE AR_AGING_OLD(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    REFDATE DATE,
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4),
    PRINT_COMPANY INTEGER,
    PRINT_CREDITCARD INTEGER)
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40),
    CURR DOUBLE PRECISION,
    OVER30 DOUBLE PRECISION,
    OVER60 DOUBLE PRECISION,
    OVER90 DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    CREDITCARD INTEGER)
AS
declare variable ARSYSDATE DATE;
BEGIN
  SELECT ARSYSDATE FROM FOSYSPARAM
  INTO ARSYSDATE;

  if ((SCUSTOMER IS NULL) or (SCUSTOMER || ECUSTOMER = '')) then
  BEGIN
     SCUSTOMER = '';
     ECUSTOMER = 'ZZZZZZ';
     REFDATE  = ARSYSDATE-1;
     DETAILFLAG = 0;
     PRINT_CREDITCARD = 1;
     PRINT_COMPANY = 1;
     CURRENCY = 'All';
  END
  /* JIKA DATE LEBIH BESAR DARI TANGGAL SYSTEM, RECALCULATE */
  if (REFDATE > ARSYSDATE) then
  BEGIN
    FOR select customer, name, CUSTTYPE, TYPENAME, curr, over30, over60, over90, total, CREDITCARD
        from ar_aging_old_calc(:SCUSTOMER,:ECUSTOMER,:REFDATE,0, 'All',:PRINT_COMPANY,:PRINT_CREDITCARD)
        INTO :CUSTOMER, :NAME, CUSTTYPE, TYPENAME, :CURR, :OVER30, :OVER60, :OVER90, :TOTAL, :CREDITCARD
    DO BEGIN
       SUSPEND;
    END
    EXIT;
  END
  /* JIKA TANGGAL LEBIH KECIL DARI TANGGAL SYSTEM AR, BACA DARI DATA */
  if (NOT EXISTS(SELECT * FROM ar_zhist_age WHERE ARDATE = :REFDATE)) THEN
  BEGIN /* SAVE TO HISTORY */
    FOR select customer, name, curr, over30, over60, over90, CREDITCARD, TOTAL
        from ar_aging_old_calc('','zzzzzz',:REFDATE,0, 'All',1,1)
        INTO :CUSTOMER, :NAME, :CURR, :OVER30, :OVER60, :OVER90, :CREDITCARD, :TOTAL
    DO BEGIN
       if ((TOTAL < -0.01) or (TOTAL > 0.01)) then
       BEGIN
          INSERT INTO AR_ZHIST_AGE (ARDATE, CUSTOMER, NAME,
              CURR, OVER30,OVER60, OVER90, CREDITCARD)
          VALUES (:REFDATE, :CUSTOMER, :NAME,
              :CURR, :OVER30, :OVER60, :OVER90, :CREDITCARD);
          SUSPEND;
       END
    END
  END
  /* LOAD AGE FROM TABLE */
  FOR select customer, name, curr, over30, over60, over90, total, CREDITCARD
      from ar_zhist_age
      WHERE ARDATE = :REFDATE
      AND CUSTOMER BETWEEN :SCUSTOMER AND :ECUSTOMER
      INTO :CUSTOMER, :NAME, :CURR, :OVER30, :OVER60, :OVER90, :TOTAL, :CREDITCARD
  DO BEGIN
     if (CREDITCARD = 0) then
     BEGIN
        SELECT CS.CUSTTYPE, TY.NAME FROM syscustomer CS
        LEFT JOIN syscustomertype TY ON TY.CUSTOMERTYPE = CS.CUSTTYPE
        WHERE CS.CUSTOMER = :CUSTOMER
        INTO CUSTTYPE, TYPENAME;
        if (PRINT_COMPANY=1) then SUSPEND;
     END
     ELSE
     BEGIN
       CUSTTYPE = 'CARD';
       TYPENAME = 'Credit Card';
       if (PRINT_CREDITCARD=1) then SUSPEND;
     END
  END  
END^


ALTER PROCEDURE AR_AGING_OLD_CALC(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    REFDATE DATE,
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4),
    PRINT_COMPANY INTEGER,
    PRINT_CREDITCARD INTEGER)
RETURNS (
    ARDATE DATE,
    CUSTOMER VARCHAR(6),
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40),
    BALANCE NUMERIC(15,4),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    CREDITLIMIT NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    FO_FOLIO INTEGER,
    FO_GUESTNAME VARCHAR(80),
    FO_ARRIVAL DATE,
    FO_DEPARTURE DATE,
    AGE INTEGER,
    CREDITCARD INTEGER)
AS
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE CASH DOUBLE PRECISION;
DECLARE VARIABLE ADJUST DOUBLE PRECISION;
DECLARE VARIABLE DEPOS DOUBLE PRECISION;
DECLARE VARIABLE FOADJUST DOUBLE PRECISION;
DECLARE VARIABLE F_VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE F_CASH DOUBLE PRECISION;
DECLARE VARIABLE F_ADJUST DOUBLE PRECISION;
DECLARE VARIABLE F_DEPOS DOUBLE PRECISION;
DECLARE VARIABLE F_FOADJUST DOUBLE PRECISION;
DECLARE VARIABLE VPAYDATE DATE;
DECLARE VARIABLE VBATCH INTEGER;
DECLARE VARIABLE VOUTLET VARCHAR(4);
DECLARE VARIABLE X_NUMBER INTEGER;
DECLARE VARIABLE X_CASH DOUBLE PRECISION;
DECLARE VARIABLE X_F_CASH DOUBLE PRECISION;
DECLARE VARIABLE X_STATUS CHAR(1);
DECLARE VARIABLE X_DATE DATE;
DECLARE VARIABLE VBANK VARCHAR(4);
begin
  /* CALC FROM AR_AGING_OLD */
  if ((SCUSTOMER IS NULL) or (SCUSTOMER || ECUSTOMER = '')) then
  BEGIN
     SCUSTOMER = '';
     ECUSTOMER = 'zzzz';
     REFDATE = '31.8.2005';
     DETAILFLAG = 1;
     PRINT_CREDITCARD = 0;
     PRINT_COMPANY = 1;
  END

  BALANCE = 0;
  if (CURRENCY IS NULL) then CURRENCY = 'All';
  CREDITCARD = 0;

  ARDATE = REFDATE;
  if (PRINT_COMPANY=1) then
  for select CS.CUSTOMER,CS.NAME,CS.CREDITLIMIT,CS.CUSTTYPE,TY.NAME from syscustomer CS
  LEFT JOIN syscustomertype TY ON TY.CUSTOMERTYPE = CS.CUSTTYPE
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER,NAME,CREDITLIMIT,CUSTTYPE,TYPENAME
  do
  begin
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    fo_folio = 0;
    fo_guestname = '';
    opendate = null;
    duedate = null;
    document = null;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number,total,forex_total,opendate,duedate,
               fo_folio,fo_guestname,fo_arrival,fo_departure
          from ARvch
         where CUSTOMER = :CUSTOMER
           and opendate <= :RefDate
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY))
           plan (arvch index (ARVCH_IDX_CUSTOMER_OPENDATE))
         into number,voucher,f_voucher,opendate,duedate,fo_folio,fo_guestname,
         fo_arrival,fo_departure
    do
    begin
       /* ------------------------------------------------------------------- */
       /* select cash payment                                                 */
       /* ------------------------------------------------------------------- */
       cash = 0;
       f_cash = 0;
       for select d.total-d.vch_gainloss,d.forex_total,d.number,h.DUEDATE,h.STATUS
           from ARcash1 d
           left join arcash0 h on h.number = d.number
           where voucherno = :number
       into :x_cash,x_f_cash,x_number,x_date,x_status
       do
       begin
         if ((x_date <= RefDate) and (x_status IN ('C','R','L'))) then
         begin
            cash = cash + x_cash;
            f_cash = f_cash + x_f_cash;
         end
       end
       /* ------------------------------------------------------------------- */
       /* select deposit                                                      */
       /* ------------------------------------------------------------------- */
       select sum(ARdepos1.total),sum(ARdepos1.forex_total) from ARdepos1
        where ARdepos1.voucherno = :number
          and ARdepos1.APplieddate <= :RefDate
          and ARdepos1.status in ('C','R')
         into depos,f_depos;

       /* ------------------------------------------------------------------- */
       /* select adjustment                                                   */
       /* ------------------------------------------------------------------- */
       select sum(db-cr),sum(forex_db-forex_cr)  from ARadj
        where voucherno = :number
          and OpenDate <= :RefDate
         into adjust,f_adjust;

       /* ------------------------------------------------------------------- */
       /* Front Office adjustment                                             */
       /* ------------------------------------------------------------------- */
       select sum(Debit-Credit),sum(forex_Debit-forex_Credit) from arvch_detail
        where Number = :number
        and status = 'C' /* C = Close,sudah di posting ke FO,O=Open */
        and source = 'A' /* A = Adjustment,f= Front Office */
        and FODate <= :RefDate
       PLAN (arvch_detail INDEX (ARVCH_DETAIL_IDX_NO_SOURCE))
       into FOAdjust,f_FOAdjust;

       if (voucher is null) then voucher = 0;
       if (cash    is null) then cash    = 0;
       if (adjust  is null) then adjust  = 0;
       if (FOadjust  is null) then FOadjust  = 0;
       if (depos   is null) then depos   = 0;

       if (f_voucher   is null) then f_voucher = 0;
       if (f_cash      is null) then f_cash    = 0;
       if (f_adjust    is null) then f_adjust  = 0;
       if (f_FOadjust  is null) then f_FOadjust  = 0;
       if (f_depos     is null) then f_depos   = 0;

       if (CURRENCY = 'All') then
          voucher = voucher - cash + adjust - depos + FOAdjust;
       else
          voucher = f_voucher - f_cash + f_adjust - f_depos + f_FOAdjust;
       d = RefDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end
  end
  /* ------------------------------------------------------------------------ */
  /* CREDIT CARD                                                              */
  /* ------------------------------------------------------------------------ */
  TOTAL  = 0;
  NUMBER = 0;
  CREDITCARD = 1;
  BALANCE = 0;
  CUSTTYPE = 'CARD';
  TYPENAME = 'Credit Card';
  if ((CURRENCY = 'All') AND (PRINT_CREDITCARD=1)) then
  FOR SELECT CREDITCARD,NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :eCUSTOMER
      INTO :CUSTOMER,:NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ----------------------------------------------------------------------- */
    if (DETAILFLAG <> 1) then
    begin
       CURR   = 0;
       OVER30 = 0;
       OVER60 = 0;
       OVER90 = 0;
       for select outlet,batch,bank,opendate,total,number,bank
             from ar_card_jur
            where CREDITCARD = :CUSTOMER
              and opendate <= :RefDate
            PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS)) /* FB 2.* No Alias */
              order by number
             into vOutlet,vBatch,vBank,opendate,voucher,number,vbank
       do
       begin


          vPayDate = Null;
          SELECT PAY_DATE FROM AR_CARD_BATCH WHERE BANK = :vBANK AND OUTLET = :vOUTLET AND BATCH = :vBATCH
          INTO vPayDate;
          IF (vPayDate > RefDate) THEN vPayDate = Null;

          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;

          d = RefDate - opendate;

          if (d <= 30)      then curr   = curr + voucher;
          else if (d <= 60) then over30 = over30 + voucher;
          else if (d <= 90) then over60 = over60 + voucher;
          else over90 = over90 + voucher;

        end
        total = curr + over30 + over60 + over90;
        BALANCE = BALANCE + TOTAL;
        if (total <> 0) then suspend;

    end /* summary */
    /* ---------------------------------------------------------------------- */
    /* detail                                                                 */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG = 1) then
    begin
       for select jr.number,jr.opendate,jr.total,jr.fo_folio,jr.batch,jr.outlet,jr.bank
             from ar_card_jur jr
            where CREDITCARD = :CUSTOMER

              and jr.opendate <= :RefDate
             into number,opendate,voucher,fo_folio,vBatch,vOutlet,vBank
       do begin
          CURR   = 0;
          OVER30 = 0;
          OVER60 = 0;
          OVER90 = 0;
          vPayDate = Null;
          SELECT PAY_DATE FROM AR_CARD_BATCH WHERE BANK = :vBANK AND OUTLET = :vOUTLET AND BATCH = :vBATCH
          INTO vPayDate;
          IF (vPayDate > RefDate) THEN vPayDate = Null;

          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          AGE = RefDate - opendate;
          if (AGE <= 30)      then curr   = voucher;
          else if (AGE <= 60) then over30 = voucher;
          else if (AGE <= 90) then over60 = voucher;
          else over90 = voucher;
          total = curr + over30 + over60 + over90;
          if (total <> 0) then begin
             SELECT GUESTNAME FROM FO_RPT_HIST_GUESTNAME (:FO_FOLIO)
             INTO FO_GUESTNAME;
             suspend;
          end
       end
    end /* detail  */
  end /* credit card */

end^


ALTER PROCEDURE AR_AGING_OLD_CALC_90(
    SCUSTOMER VARCHAR(6),
