       select sum(Debit-Credit), sum(forex_Debit-forex_Credit) from arvch_detail
        where Number = :number
        and status = 'C' /* C = Close, sudah di posting ke FO, O=Open */
        and source = 'A' /* A = Adjustment, f= Front Office */        
        and FODate <= :RefDate
       PLAN (arvch_detail INDEX (ARVCH_DETAIL_IDX_NO_SOURCE))
