       for select jr.number, jr.opendate, jr.total, jr.fo_folio, jr.batch, jr.outlet, jr.bank
             from ar_card_jur jr
            where CREDITCARD = :CUSTOMER

              and jr.opendate <= :RefDate                               
             into number, opendate, voucher, fo_folio, vBatch, vOutlet, vBank
       do begin
          CURR   = 0;
          OVER30 = 0;
          OVER60 = 0;
          OVER90 = 0;
          OVER120= 0;
          vPayDate = Null;
          SELECT PAY_DATE FROM AR_CARD_BATCH WHERE BANK = :vBANK AND OUTLET = :vOUTLET AND BATCH = :vBATCH
          INTO vPayDate;
          IF (vPayDate > RefDate) THEN vPayDate = Null;
          
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          AGE = RefDate - opendate;
          if (AGE <= 30)      then curr   = voucher;
          else if (AGE <= 60) then over30 = voucher;
          else if (AGE <= 90) then over60 = voucher;
          else if (AGE <=120) then over90 = voucher;
          else over120 = voucher;
          total = curr + over30 + over60 + over90 + over120;
          if (total <> 0) then begin
             SELECT GUESTNAME FROM FO_RPT_HIST_GUESTNAME (:FO_FOLIO)
             INTO FO_GUESTNAME;
             suspend;
          end
       end
    end /* detail  */
  end /* credit card */  
  
end^


ALTER PROCEDURE AR_AGING_SUMMARY(
    FODATE DATE)
RETURNS (
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40),
    CURRENT_DUE NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4))
AS
BEGIN
  FOR
    SELECT CUSTTYPE, TYPENAME,
           SUM(CURR)CURRENT_DUE,
           SUM(OVER30),
           SUM(OVER60),
           SUM(OVER90)
    FROM AR_AGING('','zzzz',0,'All')
    GROUP BY CUSTTYPE, TYPENAME

    INTO
      :CUSTTYPE,
      :TYPENAME,
      :CURRENT_DUE,
      :OVER30,
      :OVER60,
      :OVER90
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE AR_ANALISYS(
    PYEAR INTEGER,
    RECALCULATE INTEGER)
RETURNS (
    REFDATE DATE,
    PMONTH INTEGER,
    CURR DOUBLE PRECISION,
    OVER30 DOUBLE PRECISION,
    OVER60 DOUBLE PRECISION,
    OVER90 DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    P_CURR DOUBLE PRECISION,
    P_OVER30 DOUBLE PRECISION,
    P_OVER60 DOUBLE PRECISION,
    P_OVER90 DOUBLE PRECISION,
    P_TOTAL DOUBLE PRECISION,
    MUT_OPENING DOUBLE PRECISION,
    MUT_VOUCHER DOUBLE PRECISION,
    MUT_CASH DOUBLE PRECISION,
    MUT_DEPOSIT DOUBLE PRECISION,
    MUT_ADJUST DOUBLE PRECISION,
    MUT_ENDING DOUBLE PRECISION,
    TURN_OVER DOUBLE PRECISION,
    Z_TOTAL DOUBLE PRECISION,
    Z_VOUCHER DOUBLE PRECISION,
    AVG_TOTAL DOUBLE PRECISION,
    AVG_VOUCHER DOUBLE PRECISION,
    AVG_AR DOUBLE PRECISION,
    TOTAL_REVENUE DOUBLE PRECISION,
    COLLECTION_PERIOD DOUBLE PRECISION)
AS
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     SELECT EXTRACT(YEAR FROM ARSYSDATE) FROM FOSYSPARAM INTO PYEAR;
     RECALCULATE = 0;
  END

  PMONTH = 1;
  Z_TOTAL = 0;
  Z_VOUCHER = 0;
  WHILE (PMONTH <= 12) DO
  BEGIN
    REFDATE = '1.'|| PMONTH ||'.'||PYEAR;
    IF (RECALCULATE = 1) THEN
    BEGIN
       DELETE FROM AR_ZHIST_AGE WHERE ARDATE = :REFDATE;
       DELETE FROM AR_ZHIST_MUTATION WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH;
    END
    EXECUTE PROCEDURE SP_ENDOFMONTH(REFDATE) RETURNING_VALUES REFDATE;
    SELECT SUM(CURR), SUM(OVER30), SUM(OVER60), SUM(OVER90)
    FROM AR_AGING_OLD('','zzzz', :REFDATE, 0, 'All',1,1)
    INTO CURR, OVER30, OVER60, OVER90;
    IF (CURR IS NULL) THEN
    BEGIN
      CURR = 0;
      OVER30 = 0;
      OVER60 = 0;
      OVER90 = 0;
    END
    TOTAL = CURR + OVER30 + OVER60 + OVER90;
    IF (TOTAL <> 0) THEN
    BEGIN
      P_CURR = CURR/TOTAL*100;
      P_OVER30 = OVER30/TOTAL*100;
      P_OVER60 = OVER60/TOTAL*100;
      P_OVER90 = OVER90/TOTAL*100;
      P_TOTAL  = 100;
    END
    ELSE
    BEGIN
      P_CURR = 0;
      P_OVER30 = 0;
      P_OVER60 = 0;
      P_OVER90 = 0;
      P_TOTAL = 0;
    END
    SELECT SUM(OPENING), SUM(VOUCHER), SUM(CASH), SUM(ADJUST), SUM(DEPOSIT), SUM(ENDING)
    FROM AR_MUTATION_OLD('','zzzz', :REFDATE)
    INTO MUT_OPENING, MUT_VOUCHER, MUT_CASH, MUT_ADJUST, MUT_DEPOSIT, MUT_ENDING;

    IF (MUT_OPENING IS NULL) THEN
    BEGIN
       MUT_OPENING = 0;
       MUT_VOUCHER = 0;
       MUT_CASH = 0;
       MUT_ADJUST = 0;
       MUT_DEPOSIT = 0;
       MUT_ENDING = 0;
    END
    Z_TOTAL = Z_TOTAL + TOTAL;
    Z_VOUCHER = Z_VOUCHER + MUT_VOUCHER;
    AVG_TOTAL = Z_TOTAL / PMONTH;
    AVG_VOUCHER = Z_VOUCHER / PMONTH;

    SELECT SUM(TOTAL_REVENUE) FROM FOSTAT
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND DATATYPE = 'TYPE'
    INTO TOTAL_REVENUE;
    
    IF (TOTAL_REVENUE IS NULL) THEN TOTAL_REVENUE = 0;

    AVG_AR = (MUT_OPENING + MUT_ENDING)/2;

    IF (AVG_AR <> 0) THEN TURN_OVER = (TOTAL_REVENUE/AVG_AR);
    ELSE TURN_OVER = 1;

    IF (TURN_OVER <> 0) THEN COLLECTION_PERIOD = 30/TURN_OVER;
    ELSE COLLECTION_PERIOD = 30;
    
    SUSPEND;
    PMONTH = PMONTH + 1;
  END
END^


