ALTER PROCEDURE AR_CASHQ(
    SDATE DATE)
RETURNS (
    WK INTEGER,
    WKSDATE DATE,
    WKEDATE DATE,
    VOUCHERDUE NUMERIC(15,4),
    CREDITCARD NUMERIC(15,4),
    CASHDUE NUMERIC(15,4),
    BANKDUE NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
begin
  /* Procedure Text */
  if (sDate is null ) then
     select ARsysdate from fosysparam into :sDate;
     
  execute procedure sp_decodedate(sDate) returning_values y, m, d;
  
  if (y < 2000) then
     execute procedure sp_encodedate(y, m, d) returning_values sDate;

  d = -1;
  while (d <> 5) do
  begin
    execute procedure sp_dayofweek(sDate) returning_values d;
    sDate = sDate-1;
  end
  wk = 0;
  while (wk <= 7) do
  begin
    wksdate = sDate+wk*7;
    wkedate = wksdate+6;
    if (wk = 0 ) then wksdate = wksdate - 3650;
    if (wk = 7)  then wkedate = wkedate + 3650;
    CreditCard = 0;
    if (wk = 0) then begin
       select sum(total) from ar_card_jur
       where status = 'O'
       PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS_CARD))
       into :CreditCard;
    end
    if (CreditCard is Null) then CreditCard = 0;
    
    SELECT SUM(TOTALDUE_PREPARE) FROM ARvch /* invoice due, yang belum di proses */
     WHERE paidstatus = 'O'
     and DUEDATE between :wksdate and :wkedate 
     and forex_totaldue <> 0
     PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))

     into voucherdue;
     
    SELECT SUM(TOTAL) FROM ARcash0 /* prepared check */
     WHERE status = 'O'
     AND DUEDATE between :wksdate and :wkedate
     PLAN (ARCASH0 INDEX (ARCASH0_IDX_STATUS))
      into cashdue;


    SELECT SUM(TOTAL) FROM ARcash0 /* received checks tapi belum di reconcile (status=C) */
                                   /* kalau sudah direconcile masuk ke bank book         */
    WHERE status = 'R'
    AND DUEDATE between :wksdate and :wkedate
    PLAN (ARCASH0 INDEX (ARCASH0_IDX_STATUS))
    INTO bankdue;
     
    if (voucherdue is null) then voucherdue = 0;
    if (cashdue    is null) then cashdue    = 0;
    if (bankdue    is null) then bankdue    = 0;
    total = voucherdue + cashdue + bankdue + creditcard;
    suspend;
    wk = wk+1;
  end
end^


ALTER PROCEDURE AR_CASH_RECONCILE(
    PMONTH INTEGER,
    PYEAR INTEGER,
    FLAG_MTD_ONLY INTEGER,
    FLAG_OUTSTANDING_ONLY INTEGER)
RETURNS (
    DATAINFO VARCHAR(20),
    NUMBER INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    CHECK_NUMBER VARCHAR(40),
    OPENDATE DATE,
    DUEDATE DATE,
    RECONCILEDATE DATE,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    BANK VARCHAR(4),
    BANKNAME VARCHAR(40),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TOTAL_FOREX DOUBLE PRECISION,
    CARD_FEE DOUBLE PRECISION,
    PREV_ISSUED DOUBLE PRECISION,
    PREV_RECONCILED DOUBLE PRECISION,
    MTD_ISSUED DOUBLE PRECISION,
    MTD_RECONCILED DOUBLE PRECISION,
    TOTAL_OUTSTANDING DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE RYEAR INTEGER;
DECLARE VARIABLE RMONTH INTEGER;
DECLARE VARIABLE CTOTAL DOUBLE PRECISION;
BEGIN
  IF ((PYEAR IS NULL) OR (PMONTH = 0)) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 10;
     FLAG_MTD_ONLY = 0;
     FLAG_OUTSTANDING_ONLY = 1;
  END
  EXECUTE PROCEDURE SP_ENCODEDATE(PYEAR,PMONTH,1) RETURNING_VALUES SDATE;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES EDATE;

  IF (FLAG_MTD_ONLY = 0) THEN
     EXECUTE PROCEDURE SP_ENCODEDATE(1980,PMONTH,1) RETURNING_VALUES SDATE;
  /* ---------------------------------------------------------------- */
  /* CASH PAYMENT                                                     */
  /* ---------------------------------------------------------------- */
  DATAINFO = 'Cash Receipt';
  CARD_FEE = 0;
  FOR
    SELECT C.NUMBER,C.STATUS,
           C.DOCUMENT,C.CHECK_NUMBER,C.OPENDATE,C.DUEDATE,C.RECONCILEDATE,/* TAMBAH DUEDATE,22 NOV 2008 */
           C.CUSTOMER,S.NAME,
           C.BANK,B.BANKNAME,
           C.TOTAL,C.CURRENCY,C.EXCHANGE,C.FOREX_TOTAL
    FROM ARCASH0 C
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = C.CUSTOMER
    WHERE C.DUEDATE BETWEEN :SDATE AND :EDATE /* TADINYA OPENDATE 22 NOV 2008 */
    AND C.STATUS IN ('C','R','L')
    AND C.TOTAL <> 0
    ORDER BY C.BANK,C.DUEDATE
    INTO
      :NUMBER,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :OPENDATE,
      :DUEDATE,
      :RECONCILEDATE,
      :CUSTOMER,
      :NAME,
      :BANK,
      :BANKNAME,
      :TOTAL,:CURRENCY,:EXCHANGE,:TOTAL_FOREX
  DO
  BEGIN
    RYEAR  = EXTRACT(YEAR FROM RECONCILEDATE);
    RMONTH = EXTRACT(MONTH FROM RECONCILEDATE);

    IF (STATUS IN ('C','R','L')) THEN MTD_ISSUED = TOTAL;
    ELSE MTD_ISSUED = 0;

    IF (NOT((EXTRACT(YEAR FROM DUEDATE) = PYEAR) AND (EXTRACT(MONTH FROM DUEDATE) = PMONTH))) THEN /* TADINYA OPENDATE,22 NOV 2008 */
    BEGIN
       PREV_ISSUED = MTD_ISSUED;
       MTD_ISSUED = 0;
    END
    ELSE PREV_ISSUED = 0;

    MTD_RECONCILED = 0;
    IF ((STATUS = 'C') AND (RYEAR = PYEAR) AND (RMONTH = PMONTH)) THEN
        MTD_RECONCILED = TOTAL;

    IF (NOT((EXTRACT(YEAR FROM DUEDATE) = PYEAR) AND (EXTRACT(MONTH FROM DUEDATE) = PMONTH))) THEN
    BEGIN
       PREV_RECONCILED = MTD_RECONCILED;
       MTD_RECONCILED = 0;
    END
    ELSE PREV_RECONCILED = 0;

    TOTAL_OUTSTANDING = (MTD_ISSUED + PREV_ISSUED) - (MTD_RECONCILED+PREV_RECONCILED);
    IF (FLAG_OUTSTANDING_ONLY = 1) THEN
    BEGIN
       IF (TOTAL_OUTSTANDING <> 0) THEN
          SUSPEND;
    END
    ELSE SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT                                                          */
  /* ---------------------------------------------------------------- */
  DATAINFO = 'Deposit';
  FOR
    SELECT C.NUMBER,C.STATUS,
           C.DOCUMENT,C.CHECK_NUMBER,C.OPENDATE,C.RECONCILEDATE,
           C.CUSTOMER,S.NAME,
           C.BANK,B.BANKNAME,
           C.TOTAL,C.CURRENCY,C.EXCHANGE,C.FOREX_TOTAL
    FROM ARDEPOS0 C
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = C.CUSTOMER
    WHERE C.OPENDATE BETWEEN :SDATE AND :EDATE /* TADINYA OPENDATE,22 NOV 2008 */
    AND C.STATUS IN ('C','R','L')
    AND C.TOTAL <> 0
    ORDER BY C.BANK,C.OPENDATE
    INTO
      :NUMBER,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :OPENDATE,
      :RECONCILEDATE,
      :CUSTOMER,
      :NAME,
      :BANK,
      :BANKNAME,
      :TOTAL,:CURRENCY,:EXCHANGE,:TOTAL_FOREX
  DO
  BEGIN
    DUEDATE = OPENDATE; /* DITAMBAH,22 NOV 2008 */
    
    RYEAR  = EXTRACT(YEAR FROM RECONCILEDATE);
    RMONTH = EXTRACT(MONTH FROM RECONCILEDATE);

    IF (STATUS IN ('C','R','L')) THEN MTD_ISSUED = TOTAL;
    ELSE MTD_ISSUED = 0;

    IF (NOT((EXTRACT(YEAR FROM DUEDATE) = PYEAR) AND (EXTRACT(MONTH FROM DUEDATE) = PMONTH))) THEN /* TADINYA OPENDATE,22 NOV 2008 */
    BEGIN
       PREV_ISSUED = MTD_ISSUED;
       MTD_ISSUED = 0;
    END
    ELSE PREV_ISSUED = 0;

    MTD_RECONCILED = 0;
    IF ((STATUS = 'C') AND (RYEAR = PYEAR) AND (RMONTH = PMONTH)) THEN
        MTD_RECONCILED = TOTAL;

    IF (NOT((EXTRACT(YEAR FROM DUEDATE) = PYEAR) AND (EXTRACT(MONTH FROM DUEDATE) = PMONTH))) THEN /* TADINYA OPENDATE,22 NOV 2008 */
    BEGIN
       PREV_RECONCILED = MTD_RECONCILED;
       MTD_RECONCILED = 0;
    END
    ELSE PREV_RECONCILED = 0;

    TOTAL_OUTSTANDING = (MTD_ISSUED + PREV_ISSUED) - (MTD_RECONCILED+PREV_RECONCILED);
    IF (FLAG_OUTSTANDING_ONLY = 1) THEN
    BEGIN
       IF (TOTAL_OUTSTANDING <> 0) THEN
          SUSPEND;
    END
    ELSE SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* Credit Card                                                      */
  /* ---------------------------------------------------------------- */
  DATAINFO = 'Credit Card';
  CURRENCY = '';
  EXCHANGE = 1;
  FOR
    SELECT C.NUMBER,C.STATUS,
           C.DOCUMENT,C.REMARK,C.OPENDATE,C.RECONCILEDATE,
           C.BANK,B.BANKNAME,
           C.AMOUNT,C.AMOUNT_FEE,C.CALC_AMOUNT_NET,
           C.OUTLET,O.NAME
    FROM AR_CARD_BATCH C
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    LEFT JOIN AR_CARD_OUTLET O ON O.OUTLET = C.OUTLET
    WHERE C.OPENDATE BETWEEN :SDATE AND :EDATE
    AND C.STATUS IN ('C','R','L')
    AND C.CALC_AMOUNT_NET <> 0
    ORDER BY C.BANK,C.OPENDATE
    INTO
      :NUMBER,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :OPENDATE,
      :RECONCILEDATE,
      :BANK,
      :BANKNAME,
      :TOTAL,CARD_FEE,CTOTAL,
      :CUSTOMER,:NAME
  DO
  BEGIN
    DUEDATE = OPENDATE; /* DITAMBAH,22 NOV 2008 */
    RYEAR  = EXTRACT(YEAR FROM RECONCILEDATE);
    RMONTH = EXTRACT(MONTH FROM RECONCILEDATE);

    IF (STATUS IN ('C','R','L')) THEN MTD_ISSUED = CTOTAL;
    ELSE MTD_ISSUED = 0;

    IF (NOT((EXTRACT(YEAR FROM DUEDATE) = PYEAR) AND (EXTRACT(MONTH FROM DUEDATE) = PMONTH))) THEN
    BEGIN
       PREV_ISSUED = MTD_ISSUED;
       MTD_ISSUED = 0;
    END
    ELSE PREV_ISSUED = 0;

    MTD_RECONCILED = 0;
    IF ((STATUS = 'C') AND (RYEAR = PYEAR) AND (RMONTH = PMONTH)) THEN
        MTD_RECONCILED = CTOTAL;

    IF (NOT((EXTRACT(YEAR FROM DUEDATE) = PYEAR) AND (EXTRACT(MONTH FROM DUEDATE) = PMONTH))) THEN
    BEGIN
       PREV_RECONCILED = MTD_RECONCILED;
       MTD_RECONCILED = 0;
    END
    ELSE PREV_RECONCILED = 0;
    TOTAL_FOREX = TOTAL;
    TOTAL_OUTSTANDING = (MTD_ISSUED + PREV_ISSUED) - (MTD_RECONCILED+PREV_RECONCILED);
    IF (FLAG_OUTSTANDING_ONLY = 1) THEN
    BEGIN
       IF (TOTAL_OUTSTANDING <> 0) THEN
          SUSPEND;
    END
    ELSE SUSPEND;
  END
END^


ALTER PROCEDURE AR_CASH_RECONCILE_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    BANK VARCHAR(4),
    BBDATE DATE,
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    CREATE_BY VARCHAR(8),
    CREATE_DATE DATE)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE CREDITCARD VARCHAR(6);
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE BATCH INTEGER;
DECLARE VARIABLE OUTLET VARCHAR(4);
DECLARE VARIABLE FLAG INTEGER;
BEGIN
  /* ---------------------------------------------------------------- */
  /* PSAVE                                                            */
  /*  0 : DISPLAY ONLY                                                */
  /*  1 : DELETE ALL & RECREATE                                       */
  /*  2 : DISPLAY DISCREPANCY ONLY                                    */
  /*  3 : CREATE DISCREPANCY                                          */
  /* ---------------------------------------------------------------- */

  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.1.2005';
     EDATE = '31.12.2005';
     PSAVE = 2;
  END
  IF (PSAVE = 1) THEN
  BEGIN
     DELETE FROM BBJUR WHERE BBDATE BETWEEN :SDATE AND :EDATE
     AND APPLICATION = 'AR' AND SOURCE IN ('REC','DREC','CREC');
  END
  BBCODE = 'AR';
  APPLICATION = 'AR';
  /* ---------------------------------------------------------------- */
  /* CASH RECONCILIATION                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  FOREX_DB = 0;
  FOR
    SELECT NUMBER,BANK,RECONCILEDATE,DOCUMENT,CUSTOMER,
           FOREX_TOTAL,
           CHECK_NUMBER,
           CURRENCY,EXCHANGE,
           EDITUSER,EDITDATE
    FROM ARCASH0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    PLAN (ARCASH0 INDEX (ARCASH0_IDX_RECONCILEDATE))
    INTO
      :SOURCENUMBER,:BANK,:BBDATE,:DOCUMENT,:CUSTOMER,
      :FOREX_CR,
      :REF,
      :CURRENCY,:EXCHANGE,
      :CREATE_BY,:CREATE_DATE
  DO
  BEGIN
     /* ---------------------------------------------------------------- */
     /* PREVENT DATE WITH TIME                                           */
     /* ---------------------------------------------------------------- */
     EXECUTE PROCEDURE SP_DATEONLY(BBDATE) RETURNING_VALUES BBDATE;
     /* ---------------------------------------------------------------- */
     SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER
     INTO :REMARK;

     SELECT GL_ACCOUNT_ARPREPARE,GL_DEPT_ARPREPARE,GL_COST_ARPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT,GL_DEPT,GL_COST;
     /* ---------------------------------------------------------------- */
     /* CHECK EXISTS                                                     */
     /* ---------------------------------------------------------------- */
     IF (PSAVE >= 2) THEN
     BEGIN
        FLAG = 0;
        IF (EXISTS(SELECT * FROM BBJUR WHERE APPLICATION = :APPLICATION
                   AND SOURCE = :SOURCE AND SOURCENUMBER = :SOURCENUMBER)) THEN
        BEGIN
           FLAG = 1;
        END
     END
     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND; /* DISPLAY ONLY*/
     ELSE
     IF ((PSAVE = 1) OR ((FLAG = 0) AND (PSAVE = 3))) THEN  /* SAVE ALL OR IF NOT EXISTS */
     BEGIN
        INSERT INTO BBJUR (NUMBER,BANK,BBDATE,BBLINE,STATUS,DOCUMENT,
                        BBCODE,ACCOUNT,DEPT,COST,
                        FOREX_DB,FOREX_CR,
                        REMARK,REF,
                        CURRENCY,EXCHANGE,
                        APPLICATION,SOURCE,SOURCENUMBER,SOURCEID,
                        CREATE_BY,CREATE_DATE,EDIT_BY,EDIT_DATE)
        VALUES         (0,:BANK,:BBDATE,0,'O',:DOCUMENT,
                        :BBCODE,:GL_ACCOUNT,:GL_DEPT,:GL_COST,
                        :FOREX_DB,:FOREX_CR,
                        :REMARK,:REF,
                        :CURRENCY,:EXCHANGE,
                        :APPLICATION,:SOURCE,:SOURCENUMBER,0,
                        :CREATE_BY,:CREATE_DATE,:CREATE_BY,:CREATE_DATE);
     END
     ELSE
     IF (PSAVE = 2) THEN /* CHECK FOR DISCREPANCEY */
     BEGIN
        IF (FLAG = 0) THEN SUSPEND;
     END
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT RECONCILIATION                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  FOREX_DB = 0;
  FOR
    SELECT NUMBER,BANK,RECONCILEDATE,DOCUMENT,CUSTOMER,
           FOREX_TOTAL,
           CHECK_NUMBER,
           CURRENCY,EXCHANGE,
           EDITUSER,EDITDATE
    FROM ARDEPOS0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    PLAN (ARDEPOS0 INDEX (ARDEPOS0_IDX_RECONCILE))
    INTO
      :SOURCENUMBER,:BANK,:BBDATE,:DOCUMENT,:CUSTOMER,
      :FOREX_CR,
      :REF,
      :CURRENCY,:EXCHANGE,
      :CREATE_BY,:CREATE_DATE
  DO
  BEGIN
     /* ---------------------------------------------------------------- */
     /* PREVENT DATE WITH TIME                                           */
     /* ---------------------------------------------------------------- */
     EXECUTE PROCEDURE SP_DATEONLY(BBDATE) RETURNING_VALUES BBDATE;
     /* ---------------------------------------------------------------- */

     SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER
     INTO :REMARK;

     SELECT GL_ACCOUNT_ARPREPARE,GL_DEPT_ARPREPARE,GL_COST_ARPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT,GL_DEPT,GL_COST;
     /* ---------------------------------------------------------------- */
     /* CHECK EXISTS                                                     */
     /* ---------------------------------------------------------------- */
     IF (PSAVE >= 2) THEN
     BEGIN
        FLAG = 0;
        IF (EXISTS(SELECT * FROM BBJUR WHERE APPLICATION = :APPLICATION
                   AND SOURCE = :SOURCE AND SOURCENUMBER = :SOURCENUMBER)) THEN
        BEGIN
           FLAG = 1;
        END
     END
     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND; /* DISPLAY ONLY*/
     ELSE
     IF ((PSAVE = 1) OR ((FLAG = 0) AND (PSAVE = 3))) THEN  /* SAVE ALL OR IF NOT EXISTS */
     BEGIN
        INSERT INTO BBJUR (NUMBER,BANK,BBDATE,BBLINE,STATUS,DOCUMENT,
                        BBCODE,ACCOUNT,DEPT,COST,
                        FOREX_DB,FOREX_CR,
                        REMARK,REF,
                        CURRENCY,EXCHANGE,
                        APPLICATION,SOURCE,SOURCENUMBER,SOURCEID,
                        CREATE_BY,CREATE_DATE,EDIT_BY,EDIT_DATE)
        VALUES         (0,:BANK,:BBDATE,0,'O',:DOCUMENT,
                        :BBCODE,:GL_ACCOUNT,:GL_DEPT,:GL_COST,
                        :FOREX_DB,:FOREX_CR,
                        :REMARK,:REF,
                        :CURRENCY,:EXCHANGE,
                        :APPLICATION,:SOURCE,:SOURCENUMBER,0,
                        :CREATE_BY,:CREATE_DATE,:CREATE_BY,:CREATE_DATE);
     END
     ELSE
     IF (PSAVE = 2) THEN /* CHECK FOR DISCREPANCEY */
     BEGIN
        IF (FLAG = 0) THEN SUSPEND;
     END
  END
  /* ---------------------------------------------------------------- */
  /* CREDIT CARD RECONCILIATION                                       */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CREC';
  FOREX_DB = 0;
  /*CURRENCY = 'IDR'; */
  EXCHANGE = 1;
  FOR
    SELECT NUMBER,BANK,RECONCILEDATE,DOCUMENT,
           CALC_AMOUNT_NET,
           PAY_REF,
           EDITUSER,EDITDATE,
           BATCH,OUTLET
    FROM AR_CARD_BATCH
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    PLAN (AR_CARD_BATCH INDEX (AR_CARD_BATCH_IDX_RECONCILE))
    INTO
      :SOURCENUMBER,:BANK,:BBDATE,:DOCUMENT,
      :FOREX_CR,
      :REF,
      :CREATE_BY,:CREATE_DATE,
      :BATCH,:OUTLET
  DO
  BEGIN
     /* ---------------------------------------------------------------- */
     /* PREVENT DATE WITH TIME                                           */
     /* ---------------------------------------------------------------- */
     EXECUTE PROCEDURE SP_DATEONLY(BBDATE) RETURNING_VALUES BBDATE;
     /* ---------------------------------------------------------------- */
     /* GET CREDIT CARD NAME LIST                                        */
     /* ---------------------------------------------------------------- */
     REMARK = '';
     I = 0;
     FOR SELECT CREDITCARD FROM AR_CARD_JUR
         where batch = :batch
         and bank = :bank
         and outlet = :outlet
         GROUP BY CREDITCARD
         INTO CREDITCARD
     DO BEGIN

        IF (I = 0) THEN REMARK = CREDITCARD;
        ELSE IF (I < 5) THEN REMARK = REMARK || ',' || CREDITCARD;
        I = I + 1;
        WHEN ANY
        DO I = I + 1;
     END

     SELECT GL_ACCOUNT_ARPREPARE,GL_DEPT_ARPREPARE,GL_COST_ARPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT,GL_DEPT,GL_COST;
     /* ---------------------------------------------------------------- */
     /* CHECK EXISTS                                                     */
     /* ---------------------------------------------------------------- */
     IF (PSAVE >= 2) THEN
     BEGIN
        FLAG = 0;
        IF (EXISTS(SELECT * FROM BBJUR WHERE APPLICATION = :APPLICATION
                   AND SOURCE = :SOURCE AND SOURCENUMBER = :SOURCENUMBER)) THEN
        BEGIN
           FLAG = 1;
        END
     END
     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND; /* DISPLAY ONLY*/
     ELSE
     IF ((PSAVE = 1) OR ((FLAG = 0) AND (PSAVE = 3))) THEN  /* SAVE ALL OR IF NOT EXISTS */
     BEGIN
        SELECT CURRENCY FROM SYSBANK WHERE BANK = :BANK INTO CURRENCY; /* 8/15/2011 MULTI CURRENCY SUPPORT */
        INSERT INTO BBJUR (NUMBER,BANK,BBDATE,BBLINE,STATUS,DOCUMENT,
                        BBCODE,ACCOUNT,DEPT,COST,
                        FOREX_DB,FOREX_CR,
                        REMARK,REF,
                        CURRENCY,EXCHANGE,
                        APPLICATION,SOURCE,SOURCENUMBER,SOURCEID,
                        CREATE_BY,CREATE_DATE,EDIT_BY,EDIT_DATE)
        VALUES         (0,:BANK,:BBDATE,0,'O',:DOCUMENT,
                        :BBCODE,:GL_ACCOUNT,:GL_DEPT,:GL_COST,
                        :FOREX_DB,:FOREX_CR,
                        :REMARK,:REF,
                        :CURRENCY,:EXCHANGE,
                        :APPLICATION,:SOURCE,:SOURCENUMBER,0,
                        :CREATE_BY,:CREATE_DATE,:CREATE_BY,:CREATE_DATE);
     END
     ELSE
     IF (PSAVE = 2) THEN /* CHECK FOR DISCREPANCEY */
     BEGIN
        IF (FLAG = 0) THEN SUSPEND;
     END
  END
END^


ALTER PROCEDURE AR_CHECK_CC_INCOME_DETAIL(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    DSR_ID INTEGER,
    TEXT VARCHAR(40),
    CATEGORY VARCHAR(4),
    NAME VARCHAR(40),
    CREDITCARD VARCHAR(6),
    DB_ACCOUNT VARCHAR(20),
    DB_DEPT VARCHAR(4),
    DB_COST VARCHAR(4),
    GL_AR_ACCOUNT VARCHAR(20),
    GL_AR_DEPT VARCHAR(4),
    GL_AR_COST VARCHAR(4),
    JR_AMOUNT DOUBLE PRECISION,
    IC_AMOUNT DOUBLE PRECISION)
AS
declare variable xdsr_id integer;
BEGIN
  IF ((SDATE IS NULL) OR (EDATE IS NULL)) THEN
  BEGIN
     SDATE = '1.7.2010';
     EDATE = '30.7.2010';
  END
  XDSR_ID = -1;
  FOR
    SELECT LC.DSR_ID, L.TEXT, LC.CATEGORY, C.NAME, CC.CREDITCARD,
           GL.DB_ACCOUNT, GL.DB_DEPT, GL.DB_COST,
           CC.GL_AR_ACCOUNT, CC.GL_AR_DEPT, CC.GL_AR_COST
    FROM FODSR_LAY_CAT LC
    LEFT JOIN FODSR_LAY L ON L.DSR_ID = LC.DSR_ID
    LEFT JOIN FOCATEGORY C ON C.CATEGORY = LC.CATEGORY
    LEFT JOIN AR_CARD CC ON CC.CREDITCARD = C.CREDITCARD_AR
    LEFT JOIN FODSR_LAY_GL GL ON GL.DSR_ID = LC.DSR_ID
    WHERE C.CREDITCARD_AR <> ''
    ORDER BY LC.DSR_ID
    INTO
      :DSR_ID,
      :TEXT,
      :CATEGORY,
      :NAME,
      :CREDITCARD,
      :DB_ACCOUNT,
      :DB_DEPT,
      :DB_COST,
      :GL_AR_ACCOUNT,
      :GL_AR_DEPT,
      :GL_AR_COST
  DO
  BEGIN
    SELECT SUM(CREDIT-DEBIT) FROM FOGUEST_JUR
    WHERE CATEGORY = :CATEGORY
    AND FODATE BETWEEN :SDATE AND :EDATE
    INTO JR_AMOUNT;
    IF (JR_AMOUNT IS NULL) THEN JR_AMOUNT = 0;
    
    IF (DSR_ID <> XDSR_ID) THEN
    BEGIN
       SELECT SUM(-AMOUNT) FROM FODSR
       WHERE FODATE BETWEEN :SDATE AND :EDATE
       AND DSR_ID = :DSR_ID
       INTO IC_AMOUNT;
       IF (IC_AMOUNT IS NULL) THEN IC_AMOUNT = 0;
    END
    ELSE IC_AMOUNT = 0;
    XDSR_ID = DSR_ID;

    IF (IC_AMOUNT + JR_AMOUNT <> 0) THEN
       SUSPEND;
  END
END^


ALTER PROCEDURE AR_CHECK_CC_INCOME_SUMMARY(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    FODATE DATE,
    JR_AMOUNT DOUBLE PRECISION,
    IC_AMOUNT DOUBLE PRECISION,
    DELTA_JR_IC DOUBLE PRECISION,
    DELTA_JR_AR DOUBLE PRECISION,
    AR_AMOUNT DOUBLE PRECISION,
    AR_AMOUNT_FO DOUBLE PRECISION,
    AR_AMOUNT_MANUAL DOUBLE PRECISION,
    AR_AMOUNT_CASH DOUBLE PRECISION,
    AR_AMOUNT_INVOICE DOUBLE PRECISION,
    AR_AMOUNT_DEPOSIT DOUBLE PRECISION)
AS
declare variable sdate date;
declare variable edate date;
declare variable source varchar(2);
declare variable amount double precision;
BEGIN
  IF ((PMONTH IS NULL) OR (PYEAR IS NULL)) THEN
  BEGIN
     PMONTH = 7;
     PYEAR = 2010;
  END
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES(EDATE);
  FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
  BEGIN
     FOR
       SELECT SUM(JR_AMOUNT) JR_AMOUNT, SUM(IC_AMOUNT) IC_AMOUNT
       FROM AR_CHECK_CC_INCOME_DETAIL(:FODATE, :FODATE)
       INTO
         :JR_AMOUNT,
         :IC_AMOUNT
     DO
     BEGIN
       DELTA_JR_IC = JR_AMOUNT - IC_AMOUNT;
       AR_AMOUNT_FO = 0;
       AR_AMOUNT_MANUAL = 0;
       AR_AMOUNT_CASH = 0;
       AR_AMOUNT_INVOICE = 0;
       AR_AMOUNT_DEPOSIT = 0;
       AR_AMOUNT = 0;
       FOR SELECT SOURCE, SUM(TOTAL) FROM AR_CARD_JUR
           WHERE OPENDATE = :FODATE
           GROUP BY SOURCE
           INTO SOURCE, AMOUNT
       DO
       BEGIN
          AR_AMOUNT = AR_AMOUNT + AMOUNT;
          IF (SOURCE = 'M') THEN AR_AMOUNT_MANUAL = AMOUNT;
          ELSE IF (SOURCE = 'C') THEN AR_AMOUNT_CASH = AMOUNT;
          ELSE IF (SOURCE = 'V') THEN AR_AMOUNT_INVOICE = AMOUNT;
          ELSE IF (SOURCE = 'D') THEN AR_AMOUNT_DEPOSIT = AMOUNT;
          ELSE AR_AMOUNT_FO = AMOUNT;
       END
       DELTA_JR_AR = JR_AMOUNT - AR_AMOUNT;
       SUSPEND;
     END

     FODATE = FODATE + 1;
  END
END^


ALTER PROCEDURE AR_CHECK_CUSTOMER_CODE(
    PSAVE INTEGER)
RETURNS (
    INFO VARCHAR(30) CHARACTER SET NONE,
    CUSTOMER_VOUCHER VARCHAR(6) CHARACTER SET NONE,
    CUSTOMER_CASH_DETAIL VARCHAR(6) CHARACTER SET NONE,
    CUSTOMER_CASH_HEADER VARCHAR(6) CHARACTER SET NONE,
    VOUCHERNO INTEGER,
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    TOTAL DOUBLE PRECISION)
AS
BEGIN
  IF (PSAVE IS NULL) THEN PSAVE = 0;
  INFO = 'Cash Discrepancy';
  FOR
    SELECT V.CUSTOMER CUSTOMER_VOUCHER,
           C.CUSTOMER CUSTOMER_CASH_DETAIL,
           H.CUSTOMER CUSTOMER_CASH_HEADER,
           C.VOUCHERNO, C.NUMBER,
           H.OPENDATE, H.DUEDATE,
           C.TOTAL
    FROM ARCASH1 C
    LEFT JOIN ARVCH V ON V.NUMBER = C.VOUCHERNO
    LEFT JOIN ARCASH0 H ON H.NUMBER = C.NUMBER
    WHERE C.CUSTOMER <> V.CUSTOMER
    OR C.CUSTOMER <> H.CUSTOMER
    OR H.CUSTOMER <> V.CUSTOMER

    INTO
      :CUSTOMER_VOUCHER,
      :CUSTOMER_CASH_DETAIL,
      :CUSTOMER_CASH_HEADER,
      :VOUCHERNO,
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :TOTAL
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
    ELSE
    BEGIN
      IF (EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_VOUCHER)) THEN
      BEGIN
         UPDATE ARCASH0 SET CUSTOMER = :CUSTOMER_VOUCHER
         WHERE NUMBER = :NUMBER AND CUSTOMER <> :CUSTOMER_VOUCHER;
         UPDATE ARCASH1 SET CUSTOMER = :CUSTOMER_VOUCHER
         WHERE NUMBER = :NUMBER AND CUSTOMER <> :CUSTOMER_VOUCHER;
      END
      IF (EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_CASH_HEADER)) THEN
      BEGIN
         UPDATE ARVCH SET CUSTOMER = :CUSTOMER_CASH_HEADER
         WHERE NUMBER = :VOUCHERNO AND CUSTOMER <> :CUSTOMER_CASH_HEADER;
      END
      
      WHEN ANY DO
        NUMBER = :NUMBER;
    END
  END
  /* ---------------------------------------------------------------- */
  /* DELETE ORPHAN CASH PAYMENT                                       */
  /* ---------------------------------------------------------------- */
  INFO = 'Orphan Cash Receipt';
  IF (PSAVE=0) THEN
  BEGIN
    FOR
      SELECT V.CUSTOMER CUSTOMER_VOUCHER,
             C.CUSTOMER CUSTOMER_CASH_DETAIL,
             H.CUSTOMER CUSTOMER_CASH_HEADER,
             C.VOUCHERNO, C.NUMBER,
             H.OPENDATE, H.DUEDATE,
             C.TOTAL
      FROM ARCASH1 C
      LEFT JOIN ARVCH V ON V.NUMBER = C.VOUCHERNO
      LEFT JOIN ARCASH0 H ON H.NUMBER = C.NUMBER
      WHERE NOT (EXISTS(SELECT * FROM ARVCH V WHERE V.NUMBER = C.VOUCHERNO))
    INTO
      :CUSTOMER_VOUCHER,
      :CUSTOMER_CASH_DETAIL,
      :CUSTOMER_CASH_HEADER,
      :VOUCHERNO,
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :TOTAL
    DO
      SUSPEND;
  END
  IF (PSAVE=1) THEN
  BEGIN
      DELETE FROM ARCASH1 D
      WHERE NOT (EXISTS(SELECT * FROM ARVCH V WHERE V.NUMBER = D.VOUCHERNO));
  END
  /* -------------------------------------------------------------------- */
  /* 6/11/2011                                                            */
  /* -------------------------------------------------------------------- */
  INFO = 'Deposit Discrepancy';
  FOR
    SELECT V.CUSTOMER CUSTOMER_VOUCHER,
           C.CUSTOMER CUSTOMER_CASH_DETAIL,
           H.CUSTOMER CUSTOMER_CASH_HEADER,
           C.VOUCHERNO, C.NUMBER,
           H.OPENDATE, H.OPENDATE,
           C.TOTAL
    FROM ARDEPOS1 C
    LEFT JOIN ARVCH V ON V.NUMBER = C.VOUCHERNO
    LEFT JOIN ARDEPOS0 H ON H.NUMBER = C.NUMBER
    WHERE C.CUSTOMER <> V.CUSTOMER
    OR C.CUSTOMER <> H.CUSTOMER
    OR H.CUSTOMER <> V.CUSTOMER

    INTO
      :CUSTOMER_VOUCHER,
      :CUSTOMER_CASH_DETAIL,
      :CUSTOMER_CASH_HEADER,
      :VOUCHERNO,
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :TOTAL
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
    ELSE
    BEGIN
      IF (EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_VOUCHER)) THEN
      BEGIN
         UPDATE ARDEPOS0 SET CUSTOMER = :CUSTOMER_VOUCHER
         WHERE NUMBER = :NUMBER AND CUSTOMER <> :CUSTOMER_VOUCHER;
         UPDATE ARDEPOS1 SET CUSTOMER = :CUSTOMER_VOUCHER
         WHERE NUMBER = :NUMBER AND CUSTOMER <> :CUSTOMER_VOUCHER;
      END
      IF (EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_CASH_HEADER)) THEN
      BEGIN
         UPDATE ARVCH SET CUSTOMER = :CUSTOMER_CASH_HEADER
         WHERE NUMBER = :VOUCHERNO AND CUSTOMER <> :CUSTOMER_CASH_HEADER;
      END

      WHEN ANY DO
        NUMBER = :NUMBER;
    END
  END
  
  /* -------------------------------------------------------------------- */
  /* 6/11/2011                                                            */
  /* -------------------------------------------------------------------- */
  INFO = 'Adjustment Discrepancy';
  FOR
    SELECT V.CUSTOMER CUSTOMER_VOUCHER,
           C.CUSTOMER CUSTOMER_CASH_DETAIL,
           C.CUSTOMER CUSTOMER_CASH_HEADER,
           C.VOUCHERNO, C.NUMBER,
           C.OPENDATE, C.OPENDATE,
           C.DB-C.CR TOTAL
    FROM ARADJ C
    LEFT JOIN ARVCH V ON V.NUMBER = C.VOUCHERNO
    WHERE C.CUSTOMER <> V.CUSTOMER
    OR C.CUSTOMER <> V.CUSTOMER

    INTO
      :CUSTOMER_VOUCHER,
      :CUSTOMER_CASH_DETAIL,
      :CUSTOMER_CASH_HEADER,
      :VOUCHERNO,
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :TOTAL
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
    ELSE
    BEGIN
      IF (EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_VOUCHER)) THEN
      BEGIN
         UPDATE ARDEPOS0 SET CUSTOMER = :CUSTOMER_VOUCHER
         WHERE NUMBER = :NUMBER AND CUSTOMER <> :CUSTOMER_VOUCHER;
         UPDATE ARDEPOS1 SET CUSTOMER = :CUSTOMER_VOUCHER
         WHERE NUMBER = :NUMBER AND CUSTOMER <> :CUSTOMER_VOUCHER;
      END
      IF (EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_CASH_HEADER)) THEN
      BEGIN
         UPDATE ARVCH SET CUSTOMER = :CUSTOMER_CASH_HEADER
         WHERE NUMBER = :VOUCHERNO AND CUSTOMER <> :CUSTOMER_CASH_HEADER;
      END

      WHEN ANY DO
        NUMBER = :NUMBER;
    END
  END
END^


ALTER PROCEDURE AR_CHECK_CUSTOMER_CODE_SLIT(
    PNUMBER INTEGER,
    PCUSTOMER VARCHAR(6),
    USRID VARCHAR(8))
RETURNS (
    NUMBER INTEGER)
AS
DECLARE VARIABLE DOCUMENT VARCHAR (20);
DECLARE VARIABLE CHECK_NUMBER VARCHAR (20);
DECLARE VARIABLE OPENDATE DATE;
DECLARE VARIABLE DUEDATE DATE;
DECLARE VARIABLE BANK VARCHAR (4);
DECLARE VARIABLE BBGIRO_APNO INTEGER;
DECLARE VARIABLE BATCHNO INTEGER;
DECLARE VARIABLE RECONCILEDATE DATE;
DECLARE VARIABLE NOTE BLOB sub_type 0 segment size 8;
DECLARE VARIABLE RECEIVED_DATE DATE;
DECLARE VARIABLE CURRENCY VARCHAR (4);
DECLARE VARIABLE EXCHANGE DOUBLE PRECISION;
DECLARE VARIABLE CREDITCARD VARCHAR (6);
DECLARE VARIABLE CARDNUMBER VARCHAR (40);
DECLARE VARIABLE CARDOUTLET VARCHAR (4);
DECLARE VARIABLE VOUCHERNO INTEGER;
BEGIN
  SELECT MAX(NUMBER) FROM ARCASH0 INTO NUMBER;
  IF (NUMBER IS NULL) THEN NUMBER = 0;
  NUMBER = NUMBER + 1;
  FOR
    SELECT DOCUMENT,
           CHECK_NUMBER,
           OPENDATE,
           DUEDATE,
           BANK,
           BBGIRO_APNO,
           BATCHNO,
           RECONCILEDATE,
           NOTE,
           RECEIVED_DATE,
           CURRENCY,
           EXCHANGE,
           CREDITCARD,
           CARDNUMBER,
           CARDOUTLET
    FROM ARCASH0
    WHERE NUMBER = :PNUMBER
     INTO DOCUMENT,
          CHECK_NUMBER,
          OPENDATE,
          DUEDATE,
          BANK,
          BBGIRO_APNO,
          BATCHNO,
          RECONCILEDATE,
          NOTE,
          RECEIVED_DATE,
          CURRENCY,
          EXCHANGE,
          CREDITCARD,
          CARDNUMBER,
          CARDOUTLET
  DO
  BEGIN
    INSERT INTO ARCASH0
          (NUMBER, DOCUMENT, CHECK_NUMBER, CUSTOMER,
           OPENDATE, DUEDATE, STATUS,
           BANK, BBGIRO_APNO, BATCHNO, RECONCILEDATE,
           NOTE, RECEIVED_DATE, CURRENCY, EXCHANGE,
           CREDITCARD, CARDNUMBER, CARDOUTLET,
           TOTALCASH, TOTAL, FOREX_GAINLOSS,
           CREATEDATE, EDITDATE, CREATEUSER, EDITUSER)
    VALUES
          (:NUMBER, :DOCUMENT, :CHECK_NUMBER, :PCUSTOMER,
           :OPENDATE, :DUEDATE, 'O',
           :BANK, :BBGIRO_APNO, :BATCHNO, :RECONCILEDATE,
           :NOTE, :RECEIVED_DATE, :CURRENCY, :EXCHANGE,
           :CREDITCARD, :CARDNUMBER, :CARDOUTLET,
           0,0,0,
           'NOW', 'NOW', :USRID, :USRID);

    FOR SELECT D.VOUCHERNO FROM ARCASH1 D
        LEFT JOIN ARVCH V ON V.NUMBER = D.VOUCHERNO
        WHERE D.NUMBER = :PNUMBER
        AND V.CUSTOMER = :PCUSTOMER
        INTO VOUCHERNO
    DO
    BEGIN
       UPDATE ARCASH1 SET NUMBER = :NUMBER, CUSTOMER = :PCUSTOMER
       WHERE NUMBER = :PNUMBER
       AND VOUCHERNO = :VOUCHERNO;
    END
  END
  SUSPEND;
END^


ALTER PROCEDURE AR_CHECK_EXPORT(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    FOLIO INTEGER,
    TRANS_ID INTEGER,
    POSTFLAG CHAR(1),
    TOTAL DOUBLE PRECISION,
    ARTOTAL DOUBLE PRECISION,
    VOUCHERNO INTEGER,
    DELTA DOUBLE PRECISION,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    GL_ACCOUNT VARCHAR(20))
AS
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.10.2005';
     EDATE = '31.10.2005';
  END
  DELTA = 0;
  FOR
    SELECT J.FODATE, J.FOLIO, J.POSTFLAG, J.AR_CUSTOMER, T.GLACCOUNT, C.NAME,
           SUM(J.CREDIT-J.DEBIT)
    FROM FOGUEST_JUR J
    LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = J.AR_CUSTOMER
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
    WHERE J.FODATE BETWEEN :SDATE AND :EDATE
    AND J.JURCODE = 'CL'
    GROUP BY J.FODATE, J.FOLIO, J.POSTFLAG, J.AR_CUSTOMER, T.GLACCOUNT, C.NAME
    ORDER BY J.FOLIO
    INTO
      :FODATE,
      :FOLIO,
      :POSTFLAG,
      :CUSTOMER,
      :GL_ACCOUNT,
      :NAME,
      :TOTAL
  DO
  BEGIN
    VOUCHERNO = NULL;
    IF (TOTAL <> 0) THEN
    BEGIN
       ARTOTAL = NULL;
       SELECT SUM(TOTAL) FROM ARVCH WHERE FO_FOLIO = :FOLIO
       AND OPENDATE = :FODATE
       PLAN (ARVCH INDEX (ARVCH_FO_FOLIO))
       INTO ARTOTAL;
       IF (ARTOTAL IS NULL) THEN ARTOTAL =0;
       IF (ARTOTAL-TOTAL <> 0) THEN
       BEGIN
          DELTA = DELTA + TOTAL-ARTOTAL;
          SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE AR_CHECK_PAYMENTDATE(
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    PAYMENT_NUMBER INTEGER,
    PAYMENT_DATE DATE,
    PAYMENT_TOTAL DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT NUMBER, OPENDATE FROM ARVCH

    INTO
      :NUMBER,
      :OPENDATE
  DO
  BEGIN
    FOR SELECT D.NUMBER, H.DUEDATE, D.TOTAL FROM ARCASH1 D
        LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
        WHERE D.VOUCHERNO = :NUMBER
    INTO PAYMENT_NUMBER, PAYMENT_DATE, PAYMENT_TOTAL
    DO
    BEGIN
       IF (PAYMENT_DATE < OPENDATE) THEN
       BEGIN
          IF (PSAVE = 1) THEN
          BEGIN
             UPDATE ARCASH0 SET DUEDATE = :OPENDATE
             WHERE NUMBER = :PAYMENT_NUMBER;
          END
          ELSE
             SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE AR_COMPARE_MUT_AGE(
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    MUT_ENDING DOUBLE PRECISION,
    AGE_ENDING DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE FLAG_COMPANY INTEGER;
BEGIN
  IF (REFDATE IS NULL) THEN
  BEGIN
     SELECT ARSYSDATE FROM FOSYSPARAM WHERE ID = 1 INTO REFDATE;
     EXECUTE PROCEDURE SP_BEGINOFMONTH(REFDATE) RETURNING_VALUES (REFDATE);
     REFDATE = REFDATE - 1;
  END
  FOR
    SELECT CUSTOMER, NAME, ENDING, CREDITCARD
    FROM AR_MUTATION_OLD_CALC('','ZZZZ',:REFDATE)
    INTO
      :CUSTOMER,
      :NAME,
      :MUT_ENDING,
      :CREDITCARD
  DO
  BEGIN
    IF (CREDITCARD = 0) THEN FLAG_COMPANY = 1;
    ELSE FLAG_COMPANY = 0;
    AGE_ENDING = NULL;
    SELECT TOTAL FROM AR_AGING_OLD_CALC(:CUSTOMER, :CUSTOMER, :REFDATE, 0, Null, :FLAG_COMPANY, :CREDITCARD)
    INTO AGE_ENDING;
    IF (AGE_ENDING IS NULL) THEN AGE_ENDING = 0;
    DELTA = MUT_ENDING - AGE_ENDING;
    IF (DELTA NOT BETWEEN -0.5 AND 0.5) THEN SUSPEND;
  END
END^


ALTER PROCEDURE AR_COMPARE_MUT_FORWARD(
    MUTDATE DATE)
RETURNS (
    REFDATE DATE,
    NEXT_DATE DATE,
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    ENDING_CURRENT DOUBLE PRECISION,
    OPENING_NEXT DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
BEGIN
  IF (MUTDATE IS NULL) THEN
  BEGIN
     SELECT ARSYSDATE FROM FOSYSPARAM WHERE ID = 1 INTO MUTDATE;
     EXECUTE PROCEDURE SP_BEGINOFMONTH(REFDATE) RETURNING_VALUES (MUTDATE);
     MUTDATE = MUTDATE - 1;
  END
  EXECUTE PROCEDURE SP_ENDOFMONTH(MUTDATE) RETURNING_VALUES REFDATE;
  NEXT_DATE = REFDATE + 1;
  EXECUTE PROCEDURE SP_ENDOFMONTH(NEXT_DATE) RETURNING_VALUES NEXT_DATE;
  FOR
    SELECT CUSTOMER,NAME,ENDING,CREDITCARD
    FROM AR_MUTATION_OLD_CALC('','ZZZZ',:REFDATE)
    INTO
      :CUSTOMER,
      :NAME,
      :ENDING_CURRENT,
      :CREDITCARD
  DO
  BEGIN

    OPENING_NEXT = 0;

    SELECT OPENING
    FROM AR_MUTATION_OLD_CALC(:CUSTOMER,:CUSTOMER,:NEXT_DATE)
    WHERE CREDITCARD = :CREDITCARD
    INTO OPENING_NEXT;

    DELTA = ENDING_CURRENT - OPENING_NEXT;

    IF (DELTA NOT BETWEEN -0.5 AND 0.5) THEN SUSPEND;
  END
END^


ALTER PROCEDURE AR_DEPOSIT_AGING(
    SDATE DATE)
RETURNS (
    REFDATE DATE,
    PYEAR INTEGER,
    PMONTH INTEGER,
    NUMBER INTEGER,
    OPENDATE DATE,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    TOTAL DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    APPLIED DOUBLE PRECISION,
    ADJUSTMENT DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    AGE INTEGER,
    CURR DOUBLE PRECISION,
    OVER30 DOUBLE PRECISION,
    OVER60 DOUBLE PRECISION,
    OVER90 DOUBLE PRECISION)
AS
BEGIN
  IF (SDATE IS NULL) THEN
      SELECT ARSYSDATE FROM FOSYSPARAM INTO :SDATE;
      
  REFDATE = SDATE;
  PYEAR = EXTRACT(YEAR FROM REFDATE);
  PMONTH = EXTRACT(MONTH FROM REFDATE);
  
  FOR
    SELECT D.NUMBER, D.OPENDATE,  D.CUSTOMER, S.NAME, D.TOTAL,
    T.DEPOS_GLACCOUNT, T.DEPOS_GLDEPT, T.DEPOS_GLCOST, A.NAME
    FROM ARDEPOS0 D
    LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = D.CUSTOMER
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE=S.CUSTTYPE
    LEFT JOIN GLCOA A ON A.ACCOUNT = T.DEPOS_GLACCOUNT
    WHERE D.OPENDATE <= :SDATE
    AND D.STATUS IN ('R','C')
    ORDER BY T.DEPOS_GLACCOUNT, A.NAME
    INTO :NUMBER, OPENDATE, :CUSTOMER, :NAME, :TOTAL,
         :GL_ACCOUNT, :GL_DEPT, :GL_COST, :ACCNAME
  DO
  BEGIN
    SELECT SUM(TOTAL+VCH_GAINLOSS) FROM ARDEPOS1
    WHERE NUMBER = :NUMBER
    AND APPLIEDDATE <= :SDATE
    AND STATUS IN ('R','C')
    INTO APPLIED;
    IF (APPLIED IS NULL) THEN APPLIED = 0;
    
    SELECT SUM(CR-DB) FROM ARDEPOS0_JUR
    WHERE DEPOSITNO = :NUMBER
    AND OPENDATE <= :SDATE
    AND STATUS IN ('R','C')
    INTO ADJUSTMENT;
    IF (ADJUSTMENT IS NULL) THEN ADJUSTMENT = 0;
    
    BALANCE = TOTAL - APPLIED - ADJUSTMENT;
    IF (BALANCE NOT BETWEEN -0.5 AND 0.5) THEN
    BEGIN
       AGE = SDATE - OPENDATE;
       CURR = 0;
       OVER30 = 0;
       OVER60 = 0;
       OVER90 = 0;
       IF (AGE < 30) THEN CURR = BALANCE;
       ELSE IF (AGE < 60) THEN OVER30 = BALANCE;
       ELSE IF (AGE < 90) THEN OVER60 = BALANCE;
       ELSE OVER90 = BALANCE;
       SUSPEND;
    END
  END
END^


ALTER PROCEDURE AR_DEPOSIT_MUTATION(
    MYEAR INTEGER,
    MMONTH INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    PYEAR INTEGER,
    PMONTH INTEGER,
    REFDATE DATE,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40),
    DEPOSIT_OPEN DOUBLE PRECISION,
    DEPOSIT_NEW DOUBLE PRECISION,
    DEPOSIT_APPLY DOUBLE PRECISION,
    DEPOSIT_ADJUSTMENT DOUBLE PRECISION,
    DEPOSIT_ENDING DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40))
AS
DECLARE VARIABLE APPLY DOUBLE PRECISION;
DECLARE VARIABLE ADJUSTMENT DOUBLE PRECISION;
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
BEGIN
  IF ((MYEAR IS NULL) OR (MYEAR = 0)) THEN
  BEGIN
     MYEAR = 2005;
     MMONTH = 10;
  END
  SDATE = '1.'||MMONTH||'.'||MYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES(EDATE);
  REFDATE = EDATE;
  PYEAR = MYEAR;
  PMONTH = MMONTH;
  
  FOR SELECT C.CUSTOMER, C.NAME, C.CUSTTYPE, T.NAME,
             T.DEPOS_GLACCOUNT, T.DEPOS_GLDEPT, T.DEPOS_GLCOST, A.NAME
      FROM SYSCUSTOMER C
      LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
      LEFT JOIN GLCOA A ON A.ACCOUNT = T.DEPOS_GLACCOUNT
      INTO CUSTOMER, NAME, CUSTTYPE, TYPENAME,
           GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME
  DO
  BEGIN
     IF ((CURRENCY IN ('All', 'ALL', '')) OR (CURRENCY IS NULL)) THEN
     BEGIN
        SELECT SUM(TOTAL) FROM ARDEPOS0
        WHERE CUSTOMER = :CUSTOMER
        AND  OPENDATE < :SDATE
        AND STATUS IN ('R','C') /* 9/22/2011 */
        INTO DEPOSIT_OPEN;
     
        SELECT SUM(TOTAL+VCH_GAINLOSS) FROM ARDEPOS1
        WHERE CUSTOMER = :CUSTOMER
        AND APPLIEDDATE < :SDATE
        AND STATUS IN ('R','C')
        INTO APPLY;

        SELECT SUM(CR-DB) FROM ARDEPOS0_JUR
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE < :SDATE
        AND STATUS IN ('R','C')
        INTO ADJUSTMENT;
        
        SELECT SUM(TOTAL) FROM ARDEPOS0
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        AND STATUS IN ('R','C') /* 9/22/2011 */
        INTO DEPOSIT_NEW;
     
        SELECT SUM(TOTAL+VCH_GAINLOSS) FROM ARDEPOS1
        WHERE CUSTOMER = :CUSTOMER
        AND APPLIEDDATE BETWEEN :SDATE AND :EDATE
        AND STATUS IN ('R','C') /* 9/22/2011 */
        INTO DEPOSIT_APPLY;
        
        SELECT SUM(CR-DB) FROM ARDEPOS0_JUR
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        AND STATUS IN ('R','C')
        INTO DEPOSIT_ADJUSTMENT;
     END
     ELSE
     BEGIN
        SELECT SUM(FOREX_TOTAL) FROM ARDEPOS0
        WHERE CUSTOMER = :CUSTOMER
        AND  OPENDATE < :SDATE
        AND CURRENCY = :CURRENCY
        AND STATUS IN ('R','C') /* 9/22/2011 */
        INTO DEPOSIT_OPEN;
        
        SELECT SUM(D.FOREX_TOTAL) FROM ARDEPOS1 D
        LEFT JOIN ARDEPOS0 H ON H.NUMBER = D.NUMBER
        WHERE D.CUSTOMER = :CUSTOMER
        AND D.APPLIEDDATE < :SDATE
        AND D.STATUS IN ('R','C')
        AND H.CURRENCY = :CURRENCY
        INTO APPLY;

        SELECT SUM(CR-DB) FROM ARDEPOS0_JUR
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE < :SDATE
        AND STATUS IN ('R','C')
        AND CURRENCY = :CURRENCY
        INTO ADJUSTMENT;

        SELECT SUM(FOREX_TOTAL) FROM ARDEPOS0
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        AND CURRENCY = :CURRENCY
        AND STATUS IN ('R','C') /* 9/22/2011 */
        INTO DEPOSIT_NEW;
        
        SELECT SUM(D.FOREX_TOTAL) FROM ARDEPOS1 D
        LEFT JOIN ARDEPOS0 H ON H.NUMBER = D.NUMBER
        WHERE D.CUSTOMER = :CUSTOMER
        AND D.APPLIEDDATE BETWEEN :SDATE AND :EDATE
        AND D.STATUS IN ('R','C')
        AND H.CURRENCY = :CURRENCY
        INTO DEPOSIT_APPLY;
        
        SELECT SUM(CR-DB) FROM ARDEPOS0_JUR
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        AND STATUS IN ('R','C')
        AND CURRENCY = :CURRENCY
        INTO DEPOSIT_ADJUSTMENT;
     END
     IF (DEPOSIT_OPEN IS NULL) THEN DEPOSIT_OPEN = 0;
     IF (APPLY IS NULL) THEN APPLY = 0;
     IF (DEPOSIT_NEW IS NULL) THEN DEPOSIT_NEW = 0;
     IF (DEPOSIT_APPLY IS NULL) THEN DEPOSIT_APPLY = 0;
     IF (DEPOSIT_ADJUSTMENT IS NULL) THEN DEPOSIT_ADJUSTMENT = 0;
     IF (ADJUSTMENT IS NULL) THEN ADJUSTMENT = 0;
     DEPOSIT_OPEN = DEPOSIT_OPEN-APPLY-ADJUSTMENT;
     
     DEPOSIT_ENDING = DEPOSIT_OPEN + DEPOSIT_NEW - DEPOSIT_APPLY - DEPOSIT_ADJUSTMENT;
     IF ((DEPOSIT_OPEN <> 0) OR (DEPOSIT_NEW <> 0) OR
         (DEPOSIT_APPLY <> 0) OR (DEPOSIT_ADJUSTMENT <> 0)) THEN
        SUSPEND;
  END
END^


ALTER PROCEDURE AR_DEPOSIT_OUTSTANDING(
    REFDATE DATE)
RETURNS (
    NUMBER INTEGER,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    OPENDATE DATE,
    STATUS CHAR(1),
    TOTAL DOUBLE PRECISION,
    APPLY DOUBLE PRECISION,
    DUE DOUBLE PRECISION,
    BANK VARCHAR(4),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION)
AS
BEGIN
  IF (REFDATE IS NULL) THEN REFDATE = '31.10.2005';
  FOR
    SELECT D.NUMBER, D.CUSTOMER, C.NAME,  D.OPENDATE, D.STATUS,
           D.TOTAL, D.BANK, D.CURRENCY, D.EXCHANGE
    FROM ARDEPOS0 D
    LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = D.CUSTOMER
    WHERE D.OPENDATE <= :REFDATE
    AND D.STATUS IN ('R','C')
    INTO
      :NUMBER,
      :CUSTOMER,
      :NAME,
      :OPENDATE,
      :STATUS,
      :TOTAL,
      :BANK,
      :CURRENCY,
      :EXCHANGE
  DO
  BEGIN
    SELECT SUM(TOTAL) FROM ARDEPOS1
    WHERE NUMBER = :NUMBER
    AND APPLIEDDATE <= :REFDATE
    AND STATUS IN ('R','C')
    INTO APPLY;

    IF (APPLY IS NULL) THEN APPLY = 0;
    DUE = TOTAL - APPLY;
    SUSPEND;
  END
END^


ALTER PROCEDURE AR_DSR_CONTROL(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CL_TYPE VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    NAME VARCHAR(40),
    TOTAL_DSR DOUBLE PRECISION,
    TOTAL_AR DOUBLE PRECISION,
    TOTAL_AR_MANUAL DOUBLE PRECISION,
    TOTAL_DSR_CL DOUBLE PRECISION,
    TOTAL_DSR_ADJUST DOUBLE PRECISION,
    TOTAL_AR_ADJUST DOUBLE PRECISION,
    DSR_ID INTEGER,
    DSR_TEXT VARCHAR(40))
AS
DECLARE VARIABLE FLAG_AR INTEGER;
DECLARE VARIABLE TRANS_ACCOUNT VARCHAR(20);
DECLARE VARIABLE TRANS_DEPT VARCHAR(4);
DECLARE VARIABLE TRANS_COST VARCHAR(4);
DECLARE VARIABLE FACTOR DOUBLE PRECISION;
/* 20 OCTOBER 2006 */
DECLARE VARIABLE LISTINDEX INTEGER;
DECLARE VARIABLE SOURCE CHAR(1); /* 28 OCTOBER 2006 */
DECLARE VARIABLE XTOTAL DOUBLE PRECISION;
DECLARE VARIABLE JURCODE VARCHAR(4);
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.9.2006';
     EXECUTE PROCEDURE sp_endofmonth(SDATE) returning_values(EDATE);
  END

  TOTAL_AR_ADJUST = 0;

  select  CFG.ARVCH_TRANSIENT_ACC,CFG.ARVCH_TRANSIENT_DEPT,
          CFG.ARVCH_TRANSIENT_COST
  from FOSYSPARAM CFG
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.ARVCH_TRANSIENT_ACC
  into TRANS_ACCOUNT,TRANS_DEPT,TRANS_COST;
  TOTAL_AR = 0;
  TOTAL_AR_MANUAL = 0;




  FOR SELECT D.DSR_ID,D.TEXT,SUM(D.AMOUNT+D.ADJUSTMENT) FROM fodsr D
      LEFT JOIN FODSR_LAY L ON D.DSR_ID = L.DSR_ID
      WHERE D.FODATE BETWEEN :SDATE AND :EDATE
      AND L.COMMAND = 'CAT'
      GROUP BY D.DSR_ID,D.TEXT
      INTO DSR_ID,DSR_TEXT,TOTAL_DSR
    DO
    BEGIN
      TOTAL_DSR_CL = 0;
      TOTAL_DSR_ADJUST = 0;

      FOR SELECT LISTINDEX,DB_ACCOUNT,DB_DEPT,DB_COST,FACTOR
          FROM FODSR_LAY_GL WHERE DSR_ID = :DSR_ID
          INTO :LISTINDEX,:GL_ACCOUNT,:GL_DEPT,:GL_COST,:FACTOR
      DO
      BEGIN
         TOTAL_DSR = TOTAL_DSR * FACTOR;
         FLAG_AR = 0;
         CREDITCARD = 0;



         IF (TOTAL_DSR <> 0) THEN
         BEGIN
          CREDITCARD = 0;
          IF (EXISTS(SELECT * FROM syscustomertype WHERE GLACCOUNT = :GL_ACCOUNT
             AND GLDEPT = :GL_DEPT AND GLCOST = :GL_COST)) THEN FLAG_AR = 1;



          IF (FLAG_AR = 0) THEN
          BEGIN
             IF (EXISTS(SELECT * FROM AR_CARD WHERE GL_AR_ACCOUNT = :GL_ACCOUNT
             AND GL_AR_DEPT = :GL_DEPT AND GL_AR_COST = :GL_COST)) THEN FLAG_AR = 1;
             IF (FLAG_AR = 1) THEN CREDITCARD = 1;
          END



          IF (FLAG_AR = 0) THEN
          BEGIN
             IF ((GL_ACCOUNT = TRANS_ACCOUNT) AND (GL_DEPT = TRANS_DEPT) AND (GL_COST = TRANS_COST)) THEN
                FLAG_AR = 1;
          END



          IF (FLAG_AR = 1) THEN
          BEGIN
             SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
             IF (CREDITCARD = 0) THEN CL_TYPE = 'City Ledger';
             ELSE CL_TYPE = 'Credit Card';
             SUSPEND;
          END





        END
      END
  END

  DSR_ID = 0;
  DSR_TEXT = '';

  TOTAL_DSR = 0;
  TOTAL_DSR_CL = 0;
  TOTAL_DSR_ADJUST = 0;
  CREDITCARD = 0;
  CL_TYPE = 'City Ledger';
  FOR SELECT T.GLACCOUNT,T.GLDEPT,T.GLCOST,SUM(V.TOTAL)
      FROM ARVCH V
      LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
      LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
      WHERE V.OPENDATE BETWEEN :SDATE AND :EDATE
      GROUP BY T.GLACCOUNT,T.GLDEPT,T.GLCOST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* AR Back Office Correction                                        */
  /* ---------------------------------------------------------------- */
  TOTAL_AR_ADJUST = 0;
  FOR SELECT T.GLACCOUNT,T.GLDEPT,T.GLCOST,SUM(D.DEBIT-D.CREDIT) FROM ARVCH_DETAIL D
      INNER JOIN ARVCH V ON V.NUMBER = D.NUMBER
      INNER JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
      INNER JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
      WHERE D.SOURCE = 'A'
      AND D.STATUS = 'C'
      AND D.FODATE BETWEEN :SDATE AND :EDATE
      GROUP BY T.GLACCOUNT,T.GLDEPT,T.GLCOST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     TOTAL_AR_ADJUST = TOTAL_AR;
     SUSPEND;
  END
  TOTAL_AR_ADJUST = 0;

  /* credit card */
  CL_TYPE = 'Credit Card';
  CREDITCARD = 1;
  FOR SELECT C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL)
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.SOURCE = 'F' /* 28 OCTPBER 2006,SOURCE = 'F'*/
      GROUP BY C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END




  /* manual credit card dan lainnya */
  TOTAL_AR = 0;
  FOR SELECT C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL),V.SOURCE /* SOURCE 28 OCTOBER 2006 */
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.SOURCE <> 'F' /* 28 OCTPBER 2006,SOURCE = 'F'*/
      GROUP BY C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,V.SOURCE
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR_MANUAL,SOURCE
  DO
  BEGIN
     IF (SOURCE = 'M') THEN
     BEGIN
        CREDITCARD = 2;
        CL_TYPE = 'Credit Card Manual';
     END
     ELSE IF (SOURCE = 'V') THEN
     BEGIN
        CREDITCARD = 3;
        CL_TYPE = 'Credit Card for Invoice';
     END
     ELSE IF (SOURCE = 'D') THEN
     BEGIN
        CREDITCARD = 4;
        CL_TYPE = 'Credit Card for Deposit';
     END
     ELSE
     BEGIN
        CREDITCARD = 9;
        CL_TYPE = 'Credit Card for Others';
     END
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END




END^


ALTER PROCEDURE AR_DSR_CONTROL_DAILY(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    CREDITCARD INTEGER,
    CL_TYPE VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    NAME VARCHAR(40),
    TOTAL_DSR DOUBLE PRECISION,
    TOTAL_AR DOUBLE PRECISION,
    TOTAL_AR_MANUAL DOUBLE PRECISION)
AS
DECLARE VARIABLE FLAG_AR INTEGER;
DECLARE VARIABLE TRANS_ACCOUNT VARCHAR(20);
DECLARE VARIABLE TRANS_DEPT VARCHAR(4);
DECLARE VARIABLE TRANS_COST VARCHAR(4);
DECLARE VARIABLE DSR_ID INTEGER;
DECLARE VARIABLE FACTOR DOUBLE PRECISION;
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.8.2005';
     EXECUTE PROCEDURE sp_endofmonth(SDATE) returning_values(EDATE);
  END

 select  CFG.ARVCH_TRANSIENT_ACC,CFG.ARVCH_TRANSIENT_DEPT,
         CFG.ARVCH_TRANSIENT_COST
 from FOSYSPARAM CFG
 LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.ARVCH_TRANSIENT_ACC
 into TRANS_ACCOUNT,TRANS_DEPT,TRANS_COST;

  TOTAL_AR = 0;
  TOTAL_AR_MANUAL = 0;
  FOR SELECT D.FODATE,D.DSR_ID,SUM(D.AMOUNT+D.ADJUSTMENT) FROM fodsr D
      LEFT JOIN FODSR_LAY L ON D.DSR_ID = L.DSR_ID
      WHERE D.FODATE BETWEEN :SDATE AND :EDATE
      AND L.COMMAND = 'CAT'
      AND L.DSR_ID = 159
      GROUP BY D.FODATE,D.DSR_ID
      INTO FODATE,DSR_ID,TOTAL_DSR
    DO
    BEGIN
      SELECT DB_ACCOUNT,DB_DEPT,DB_COST,FACTOR
      FROM FODSR_LAY_GL WHERE DSR_ID = :DSR_ID
      INTO :GL_ACCOUNT,:GL_DEPT,:GL_COST,:FACTOR;
      TOTAL_DSR = TOTAL_DSR * FACTOR;
      FLAG_AR = 0;
      CREDITCARD = 0;
      IF (TOTAL_DSR <> 0) THEN
      BEGIN
        CREDITCARD = 0;
        IF (EXISTS(SELECT * FROM syscustomertype WHERE GLACCOUNT = :GL_ACCOUNT
           AND GLDEPT = :GL_DEPT AND GLCOST = :GL_COST)) THEN FLAG_AR = 1;
           
        IF (FLAG_AR = 0) THEN
        BEGIN
           IF (EXISTS(SELECT * FROM AR_CARD WHERE GL_AR_ACCOUNT = :GL_ACCOUNT
           AND GL_AR_DEPT = :GL_DEPT AND GL_AR_COST = :GL_COST)) THEN FLAG_AR = 1;
           IF (FLAG_AR = 1) THEN CREDITCARD = 1;
        END
        IF (FLAG_AR = 0) THEN
        BEGIN
           IF ((GL_ACCOUNT = TRANS_ACCOUNT) AND (GL_DEPT = TRANS_DEPT) AND (GL_COST = TRANS_COST)) THEN
              FLAG_AR = 1;
        END
        IF (FLAG_AR = 1) THEN
        BEGIN
           SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
           IF (CREDITCARD = 0) THEN CL_TYPE = 'City Ledger';
           ELSE CL_TYPE = 'Credit Card';
           SUSPEND;
        END
      END
  END
  TOTAL_DSR = 0;
  CREDITCARD = 0;
  CL_TYPE = 'City Ledger';
  FOR SELECT V.OPENDATE,T.GLACCOUNT,T.GLDEPT,T.GLCOST,SUM(V.TOTAL)
      FROM ARVCH V
      LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
      LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      GROUP BY V.OPENDATE,T.GLACCOUNT,T.GLDEPT,T.GLCOST
  INTO FODATE,GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END
  /* credit card */
  CL_TYPE = 'Credit Card';
  CREDITCARD = 1;
  FOR SELECT V.OPENDATE,C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL)
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.FO_FOLIO <> 0
      GROUP BY V.OPENDATE,C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST
  INTO FODATE,GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END
  /* manual credit card */
  TOTAL_AR = 0;
  FOR SELECT V.OPENDATE,C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL)
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.FO_FOLIO = 0
      GROUP BY V.OPENDATE,C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST
  INTO FODATE,GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR_MANUAL
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END
END^


ALTER PROCEDURE AR_DSR_CONTROL_DAILY_1(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    CREDITCARD INTEGER,
    CL_TYPE VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    NAME VARCHAR(40),
    TOTAL_DSR DOUBLE PRECISION,
    TOTAL_AR DOUBLE PRECISION,
    TOTAL_AR_MANUAL DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE FLAG_AR INTEGER;
DECLARE VARIABLE TRANS_ACCOUNT VARCHAR(20);
DECLARE VARIABLE TRANS_DEPT VARCHAR(4);
DECLARE VARIABLE TRANS_COST VARCHAR(4);
DECLARE VARIABLE DSR_ID INTEGER;
DECLARE VARIABLE FACTOR DOUBLE PRECISION;
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.8.2005';
     EXECUTE PROCEDURE sp_endofmonth(SDATE) returning_values(EDATE);
  END

  FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
  BEGIN
     FOR SELECT CREDITCARD,CL_TYPE,GL_ACCOUNT,GL_DEPT,GL_COST,NAME,
                SUM(TOTAL_DSR),SUM(TOTAL_AR),SUM(TOTAL_AR_MANUAL)
         FROM AR_DSR_CONTROL(:FODATE,:FODATE)
         GROUP BY CREDITCARD,CL_TYPE,GL_ACCOUNT,GL_DEPT,GL_COST,NAME
         INTO CREDITCARD,CL_TYPE,GL_ACCOUNT,GL_DEPT,GL_COST,NAME,
              TOTAL_DSR,TOTAL_AR,TOTAL_AR_MANUAL
     DO
     BEGIN
        DELTA = TOTAL_DSR - TOTAL_AR;
        SUSPEND;
     END
     FODATE = FODATE + 1;
  END

END^


ALTER PROCEDURE AR_DSR_CONTROL_DETAIL(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    PDATE DATE,
    CREDITCARD INTEGER,
    CL_TYPE VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    NAME VARCHAR(40),
    TOTAL_DSR DOUBLE PRECISION,
    TOTAL_AR DOUBLE PRECISION,
    TOTAL_AR_MANUAL DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
BEGIN
  WHILE (SDATE <= EDATE) DO
  BEGIN
     PDATE = SDATE;
     FOR
       SELECT CREDITCARD,CL_TYPE,
              GL_ACCOUNT,GL_DEPT,GL_COST,NAME,
              SUM(TOTAL_DSR) TOTAL_DSR,
              SUM(TOTAL_AR) TOTAL_AR,
              SUM(TOTAL_AR_MANUAL) TOTAL_AR_MANUAL,
              SUM(TOTAL_DSR-TOTAL_AR-TOTAL_AR_MANUAL) DELTA
       FROM AR_DSR_CONTROL(:SDATE,:EDATE)
       GROUP BY CREDITCARD,CL_TYPE,GL_ACCOUNT,GL_DEPT,GL_COST,NAME
       INTO
         :CREDITCARD,
         :CL_TYPE,
         :GL_ACCOUNT,
         :GL_DEPT,
         :GL_COST,
         :NAME,
         :TOTAL_DSR,
         :TOTAL_AR,
         :TOTAL_AR_MANUAL,
         :DELTA
     DO
     BEGIN
       SUSPEND;
     END
     SDATE = SDATE + 1;
  END
END^


ALTER PROCEDURE AR_DSR_CONTROL_DISCREPANCY(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    AR_ERROR_CODE VARCHAR(12),
    AR_REMARK VARCHAR(40),
    FODATE DATE,
    APPLICATION VARCHAR(2),
    SOURCE VARCHAR(2),
    AR_COUNTER INTEGER,
    AR_CUSTOMER VARCHAR(6),
    AR_CUSTOMERNAME VARCHAR(40),
    AR_OPENDATE DATE,
    AR_AMOUNT DOUBLE PRECISION,
    AR_NUMBER INTEGER,
    FOLIO INTEGER,
    TRANS_ID INTEGER,
    FULLNAMEF VARCHAR(80),
    COMPANY VARCHAR(6),
    COMPANYNAME VARCHAR(40),
    AMOUNT DOUBLE PRECISION,
    BO_VOUCHERNO INTEGER,
    BO_TRANS_ID INTEGER,
    BO_CATEGORY VARCHAR(4),
    BO_REMARK VARCHAR(40),
    BO_DEBIT DOUBLE PRECISION,
    BO_CREDIT DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4))
AS
/* 29 OCTOBER 2006, MELBEN  */
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE FOSYSDATE DATE;
DECLARE VARIABLE CL_CAT1 VARCHAR(4);
DECLARE VARIABLE CL_CAT2 VARCHAR(4);
DECLARE VARIABLE CL_CAT3 VARCHAR(4);
/* 6 AGUSTUS 2007 */
DECLARE VARIABLE AGL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE AGL_DEPT VARCHAR(4);
DECLARE VARIABLE AGL_COST VARCHAR(4);
/* 7 MARET 2008 */
/* CHECK FOR CREDITCARD AFTER RE-CLOSE MEAL PERIOD */
DECLARE VARIABLE JURCODE VARCHAR(4);
DECLARE VARIABLE CCNO VARCHAR(40);
DECLARE VARIABLE REMARK VARCHAR(40);
DECLARE VARIABLE REF VARCHAR(20);
DECLARE VARIABLE JR_FOSYSDATE DATE;
BEGIN



  IF ((PMONTH = 0) OR (PMONTH IS NULL)) THEN
  BEGIN
     SELECT EXTRACT(MONTH FROM FOSYSDATE), EXTRACT (YEAR FROM FOSYSDATE)
     FROM FOSYSPARAM INTO PMONTH, PYEAR;
  END


  /* ---------------------------------------------------------------- */
  /* CONSTRUCT BEGIN & ENDING DATE                                    */
  /* ---------------------------------------------------------------- */
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES (EDATE);



  /* ---------------------------------------------------------------- */
  /* CHECK FO DATE                                                    */
  /* ---------------------------------------------------------------- */
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;
  IF (EDATE > FOSYSDATE-1) THEN EDATE = FOSYSDATE-1;


  GL_ACCOUNT = '';
  GL_DEPT = '';
  GL_COST = '';

  BO_DEBIT = 0;
  BO_CREDIT = 0;

  FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
  BEGIN
    /* ---------------------------------------------------------------- */
    /* CITY LEDGER                                                      */
    /* ---------------------------------------------------------------- */
    APPLICATION = 'AR';
    SOURCE = 'CL';
    FOR SELECT JR.TRANS_ID, JR.FOLIO, (JR.CREDIT-JR.DEBIT) AMOUNT,
               JR.AR_CUSTOMER
         FROM FOGUEST_JUR JR
         LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY = JR.CATEGORY
         WHERE JR.FODATE = :FODATE
         AND JR.JURCODE = 'CL'
         AND JR.CORRECTED = 0
         AND JR.HIDDEN = 0

         UNION

         SELECT JR.TRANS_ID, JR.FOLIO, (JR.CREDIT-JR.DEBIT) AMOUNT,
               JR.AR_CUSTOMER
         FROM FO_HIST_JUR JR
         LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY = JR.CATEGORY
         WHERE JR.FODATE = :FODATE
         AND JR.JURCODE = 'CL'
         AND JR.CORRECTED = 0
         AND JR.HIDDEN = 0

         INTO TRANS_ID, FOLIO, AMOUNT, COMPANY
    DO
    BEGIN

       SELECT GUESTNAME, COMPANYNAME FROM FO_RPT_HIST_GUESTNAME(:FOLIO)
       INTO FULLNAMEF, COMPANYNAME;

       AR_NUMBER = NULL;
       AR_CUSTOMER = NULL;
       AR_CUSTOMERNAME = NULL;

       SELECT COUNT(*), SUM(V.TOTAL) FROM ARVCH V
       WHERE V.FO_TRANS_ID = :TRANS_ID
       INTO AR_COUNTER, AR_AMOUNT;




       IF (AR_COUNTER = 0) THEN
       BEGIN
          AR_ERROR_CODE = 'NOTFOUND';
          AR_REMARK = 'Not Found';
          SUSPEND;


       END
       ELSE IF (AR_COUNTER > 1) THEN
       BEGIN
          IF (AR_AMOUNT <> AMOUNT) THEN
          BEGIN
             AR_ERROR_CODE = 'DOUBLE';
             AR_REMARK = 'Double Posted';
             SUSPEND;


          END
       END
       ELSE
       BEGIN
          SELECT V.TOTAL, V.OPENDATE, V.NUMBER, V.CUSTOMER, C.NAME
          FROM ARVCH V
          LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
          WHERE V.FO_TRANS_ID = :TRANS_ID
          INTO AR_AMOUNT, AR_OPENDATE, AR_NUMBER, AR_CUSTOMER, AR_CUSTOMERNAME;
          IF (AR_OPENDATE <> FODATE) THEN
          BEGIN
             AR_ERROR_CODE = 'DATE';
             AR_REMARK = 'Open Date Changed';
             SUSPEND;


          END
          ELSE
          IF (AR_AMOUNT - AMOUNT NOT BETWEEN -0.1 AND 01) THEN
          BEGIN
             AR_ERROR_CODE = 'AMOUNT';
             AR_REMARK = 'Amount Changed';
             SUSPEND;


          END
          ELSE
          IF (AR_CUSTOMER <> COMPANY) THEN
          BEGIN
             AR_ERROR_CODE = 'COMPANY';
             AR_REMARK = 'Company Changed';
             SUSPEND;


          END
       END
    END




    /* ---------------------------------------------------------------- */
    /* CREDIT CARD                                                      */
    /* ---------------------------------------------------------------- */
    BO_DEBIT = 0;
    BO_CREDIT = 0;
    APPLICATION = 'AR';
    SOURCE = 'CC';
    FOR SELECT JR.TRANS_ID, JR.FOLIO, (JR.CREDIT-JR.DEBIT) AMOUNT, 
               CAT.CREDITCARD_AR, CC.NAME,
               JR.JURCODE, JR.REMARK, JR.REFERENCE, /* 7 MARET 2008 CHECK FOR CLOSE MEAL */
               JR.FOSYSDATE
        FROM FOGUEST_JUR JR
        INNER JOIN FOCATEGORY CAT ON
             ((CAT.CATEGORY = JR.CATEGORY) AND (CAT.FLAG_CREDITCARD = 1))
        INNER JOIN AR_CARD CC ON (CC.CREDITCARD = CAT.CREDITCARD_AR)
        WHERE JR.FODATE = :FODATE
        AND JR.CORRECTED = 0
        AND JR.HIDDEN = 0

        UNION

        SELECT JR.TRANS_ID, JR.FOLIO, (JR.CREDIT-JR.DEBIT) AMOUNT, 
               CAT.CREDITCARD_AR, CC.NAME,
               JR.JURCODE, JR.REMARK, JR.REFERENCE, /* 7 MARET 2008 CHECK FOR CLOSE MEAL */
               JR.FOSYSDATE
        FROM FO_HIST_JUR JR
        INNER JOIN FOCATEGORY CAT ON
             ((CAT.CATEGORY = JR.CATEGORY) AND (CAT.FLAG_CREDITCARD = 1))
        INNER JOIN AR_CARD CC ON (CC.CREDITCARD = CAT.CREDITCARD_AR)
        WHERE JR.FODATE = :FODATE
        AND JR.CORRECTED = 0
        AND JR.HIDDEN = 0

        INTO TRANS_ID, FOLIO, AMOUNT, 
              COMPANY, COMPANYNAME,
              JURCODE, REMARK, REF, /* 7 MARET 2008 CHECK FOR CLOSE MEAL */
              JR_FOSYSDATE
    DO
    BEGIN
       SELECT GUESTNAME  FROM FO_RPT_HIST_GUESTNAME(:FOLIO)
       INTO FULLNAMEF;

       AR_NUMBER = NULL;
       AR_CUSTOMER = NULL;
       AR_CUSTOMERNAME = NULL;

       SELECT COUNT(*), SUM(V.TOTAL) FROM AR_CARD_JUR V
       WHERE V.FO_TRANS_ID = :TRANS_ID
       INTO AR_COUNTER, AR_AMOUNT;



       IF (AR_COUNTER = 0) THEN
       BEGIN
          IF (JURCODE <> 'FB') THEN /* 7 MARET 2008 CHECK FOR CLOSE MEAL */
          BEGIN
             AR_ERROR_CODE = 'NOTFOUND';
             AR_REMARK = 'Not Found';
             SUSPEND;
          END
          ELSE
          BEGIN
             /* 7 MARET 2008 CHECK FOR CLOSE MEAL */
             CCNO = REMARK;
             IF (CCNO = '') THEN CCNO = REF;
             IF (NOT EXISTS(SELECT * FROM AR_CARD_JUR
                               WHERE FO_FOLIO = :FOLIO
                               AND OPENDATE = :FODATE
                               AND (TOTAL - :AMOUNT BETWEEN -0.05 AND 0.05))) THEN
             BEGIN
                IF (NOT EXISTS(SELECT * FROM AR_CARD_JUR
                                  WHERE FO_FOLIO = :FOLIO
                                  AND CARDNUMBER = :CCNO
                                  AND (TOTAL - :AMOUNT BETWEEN -0.05 AND 0.05))) THEN
                BEGIN
                   AR_CUSTOMERNAME = CCNO;
                   AR_ERROR_CODE = 'NOTFOUND';
                   AR_REMARK = 'Not Found-Reimport Meal Period';
                   SUSPEND;
                END
             END
          END
       END
       ELSE IF (AR_COUNTER > 1) THEN
       BEGIN
          IF (AR_AMOUNT <> AMOUNT) THEN
          BEGIN
             AR_ERROR_CODE = 'DOUBLE';
             AR_REMARK = 'Double Posted';
             SUSPEND;


          END
       END
       ELSE
       BEGIN
          SELECT V.TOTAL, V.OPENDATE, V.NUMBER, V.CREDITCARD, C.NAME
          FROM AR_CARD_JUR V
          LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
          WHERE V.FO_TRANS_ID = :TRANS_ID
          INTO AR_AMOUNT, AR_OPENDATE, AR_NUMBER, AR_CUSTOMER, AR_CUSTOMERNAME;
          IF (AR_OPENDATE <> FODATE) THEN
          BEGIN
             AR_ERROR_CODE = 'DATE';
             AR_REMARK = 'Open Date Changed';
             SUSPEND;


          END
          ELSE
          IF (AR_AMOUNT - AMOUNT NOT BETWEEN -0.1 AND 0.1) THEN
          BEGIN
             AR_ERROR_CODE = 'AMOUNT';
             AR_REMARK = 'Amount Changed';
             SUSPEND;


          END
          ELSE
          IF (AR_CUSTOMER <> COMPANY) THEN
          BEGIN
             AR_ERROR_CODE = 'CREDITCARD';
             AR_REMARK = 'Card Changed';
/*             SUSPEND; */


          END
       END
    END
    /* ---------------------------------------------------------------- */
    /* BACK OFFICE A/R CORRECTION                                       */
    /* ---------------------------------------------------------------- */
    APPLICATION = 'AR';
    SOURCE = 'BO';
    BO_DEBIT = 0;
    BO_CREDIT = 0;
    SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'CITYLEDGER1' INTO CL_CAT1;
    SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'CITYLEDGER2' INTO CL_CAT2;
    SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'CITYLEDGER3' INTO CL_CAT3;

    IF (NOT EXISTS(SELECT * FROM FOCATEGORY WHERE CATEGORY = :CL_CAT2)) THEN CL_CAT2 = CL_CAT1;
    IF (NOT EXISTS(SELECT * FROM FOCATEGORY WHERE CATEGORY = :CL_CAT3)) THEN CL_CAT3 = CL_CAT1;

    FOR SELECT JR.CATEGORY, JR.TRANS_ID, JR.FOLIO, (JR.DEBIT-JR.CREDIT),
               JR.DEBIT, JR.CREDIT, JR.REMARK,
               JR.AR_CUSTOMER, JR.SOURCE_ID, JR.TRANS_ID_BATCH
         FROM FOGUEST_JUR JR
         WHERE JR.FODATE = :FODATE
         AND JR.JURCODE = 'BO'
         AND JR.CORRECTED = 0
         AND JR.HIDDEN = 2
         AND NOT ((JR.CATEGORY = :CL_CAT1) OR (JR.CATEGORY = :CL_CAT2) OR (JR.CATEGORY = :CL_CAT3))

         UNION

         SELECT JR.CATEGORY, JR.TRANS_ID, JR.FOLIO, (JR.DEBIT-JR.CREDIT),
               JR.DEBIT, JR.CREDIT, JR.REMARK,
               JR.AR_CUSTOMER, JR.SOURCE_ID, JR.TRANS_ID_BATCH
         FROM FO_HIST_JUR JR
         WHERE JR.FODATE = :FODATE
         AND JR.JURCODE = 'BO'
         AND JR.CORRECTED = 0
         AND JR.HIDDEN = 2
         AND NOT ((JR.CATEGORY = :CL_CAT1) OR (JR.CATEGORY = :CL_CAT2) OR (JR.CATEGORY = :CL_CAT3))

         INTO BO_CATEGORY, TRANS_ID, FOLIO, AMOUNT, BO_DEBIT, BO_CREDIT, BO_REMARK,
              COMPANY, BO_VOUCHERNO, BO_TRANS_ID
    DO
    BEGIN
       SELECT GUESTNAME, COMPANY, COMPANYNAME FROM FO_RPT_HIST_GUESTNAME(:FOLIO)
       INTO FULLNAMEF, COMPANY, COMPANYNAME;

       AR_NUMBER = NULL;
       AR_CUSTOMER = NULL;
       AR_CUSTOMERNAME = NULL;

       SELECT COUNT(*), SUM(V.DEBIT-V.CREDIT) FROM ARVCH_DETAIL V
       WHERE V.NUMBER = :BO_VOUCHERNO
       AND V.FO_TRANS_ID = :BO_TRANS_ID
       AND V.CATEGORY = :BO_CATEGORY
       INTO AR_COUNTER, AR_AMOUNT;



       IF (AR_COUNTER = 0) THEN
       BEGIN
          AR_ERROR_CODE = 'NOTFOUND';
          AR_REMARK = 'Not Found';
          SUSPEND;
       END
    END
    FODATE = FODATE + 1;
  END

  /* ---------------------------------------------------------------- */
  /* CREDIT CARD UNTUK BAYAR VOUCHER                                  */
  /* 6 AGUSTUS 2007                                                   */
  /* ---------------------------------------------------------------- */
  APPLICATION = 'CC';
  SOURCE = 'VC';
  AR_REMARK = 'Invoice paid by Card';
  AR_AMOUNT = 0;
  AR_OPENDATE = NULL;
  AR_CUSTOMER = '';
  AR_CUSTOMERNAME = '';
  TRANS_ID = 0;
  FOLIO = 0;
  BO_VOUCHERNO = 0;
  BO_TRANS_ID = 0;
  BO_CATEGORY = 0;
  BO_REMARK = 0;
  BO_DEBIT = 0;
  BO_CREDIT = 0;
  FOR SELECT V.NUMBER, V.OPENDATE, V.TOTAL, V.REMARK, V.CREDITCARD, C.NAME,
             C.GL_AR_ACCOUNT, C.GL_AR_DEPT, C.GL_AR_COST
      FROM AR_CARD_JUR V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE V.OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.SOURCE = 'V' /* 6 AGUSTUS 2007 */
      ORDER BY V.NUMBER
  INTO TRANS_ID, FODATE, AMOUNT, FULLNAMEF, COMPANY, COMPANYNAME,
       GL_ACCOUNT, GL_DEPT, GL_COST
  DO
  BEGIN
     IF (NOT EXISTS(SELECT * FROM ARADJ
             WHERE SOURCE = 'CC' AND SOURCENUMBER = :TRANS_ID)) THEN
     BEGIN
        AR_ERROR_CODE = 'NOTFOUND';
        SUSPEND;
     END
     ELSE
     BEGIN
        SELECT NUMBER, VOUCHERNO, OPENDATE, ACCOUNT, DEPT, COST
        FROM ARADJ
        WHERE SOURCE = 'CC' AND SOURCENUMBER = :TRANS_ID
        INTO AR_NUMBER, BO_VOUCHERNO, AR_OPENDATE, AGL_ACCOUNT, AGL_DEPT, AGL_COST;

        IF (AR_OPENDATE <> FODATE) THEN
        BEGIN
           AR_ERROR_CODE = 'DATE';
           AR_REMARK = 'Open Date Changed';
           SUSPEND;
        END

        IF ((AGL_ACCOUNT <> GL_ACCOUNT) OR
            (AGL_DEPT <> GL_DEPT) OR
            (AGL_COST <> GL_COST))  THEN
        BEGIN
           AR_ERROR_CODE = 'DATE';
           AR_REMARK = 'A/C Change';
           SUSPEND;
        END
     END

  END
END^


ALTER PROCEDURE AR_DSR_CONTROL_INVALID_LAYOUT(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    INFO VARCHAR(16),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    GL_ACCNAME VARCHAR(40),
    DSR_ID INTEGER,
    DSR_TEXT VARCHAR(40),
    CATEGORY VARCHAR(4),
    CATEGORY_NAME VARCHAR(40),
    FODATE DATE,
    FOLIO INTEGER,
    TRANS_ID INTEGER,
    JURCODE VARCHAR(4),
    AMOUNT DOUBLE PRECISION,
    GUESTNAME VARCHAR(80))
AS
DECLARE VARIABLE FOSYSDATE DATE;
DECLARE VARIABLE FLAG_CREDITCARD INTEGER;
DECLARE VARIABLE FLAG_CREDITCARD_CAT INTEGER;
BEGIN

  SELECT  CFG.FOSYSDATE FROM FOSYSPARAM CFG INTO FOSYSDATE;
  
  IF (SDATE IS NULL) THEN
  BEGIN
     EDATE = FOSYSDATE-1;
     EXECUTE PROCEDURE SP_BEGINOFMONTH(EDATE) RETURNING_VALUES SDATE;
  END


  FOR SELECT  CFG.ARVCH_TRANSIENT_ACC,CFG.ARVCH_TRANSIENT_DEPT,
              CFG.ARVCH_TRANSIENT_COST,CAST(0 AS INTEGER)
      FROM FOSYSPARAM CFG
      
      UNION
  
      SELECT DISTINCT GLACCOUNT,GLDEPT ,GLCOST,CAST(0 AS INTEGER)
      FROM SYSCUSTOMERTYPE
      WHERE GLACCOUNT IS NOT NULL
      
      UNION
      
      SELECT GL_AR_ACCOUNT,GL_AR_DEPT,GL_AR_COST,CAST(1 AS INTEGER)
      FROM AR_CARD
      
      INTO GL_ACCOUNT,GL_DEPT,GL_COST,FLAG_CREDITCARD
  DO
  BEGIN
      SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT
      INTO GL_ACCNAME;
      
      FOR SELECT GL.DSR_ID,LY.TEXT
          FROM FODSR_LAY_GL GL
          INNER JOIN FODSR_LAY LY ON LY.DSR_ID = GL.DSR_ID AND LY.COMMAND = 'CAT'
          WHERE ((GL.DB_ACCOUNT = :GL_ACCOUNT) AND
                 (GL.DB_DEPT = :GL_DEPT) AND
                 (GL.DB_COST = :GL_COST)) OR

                ((GL.CR_ACCOUNT = :GL_ACCOUNT) AND
                 (GL.CR_DEPT = :GL_DEPT) AND
                 (GL.CR_COST = :GL_COST))

      INTO DSR_ID,DSR_TEXT
      DO
      BEGIN
         FOR SELECT LY.CATEGORY,CAT.NAME,CAT.FLAG_CREDITCARD FROM FODSR_LAY_CAT LY
             LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY = LY.CATEGORY
             WHERE LY.DSR_ID = :DSR_ID
             ORDER BY LY.CATEGORY
             INTO CATEGORY,CATEGORY_NAME,FLAG_CREDITCARD_CAT
         DO
         BEGIN
            /* ---------------------------------------------------------------- */
            /* CL TRANSACTION                                                   */
            /* ACCOUNT BUKAN CREDIT CARD                                        */
            /* ---------------------------------------------------------------- */
            IF (FLAG_CREDITCARD = 0) THEN
            BEGIN

               FOR SELECT JR.FODATE,JR.FOLIO,JR.TRANS_ID,JR.JURCODE,JR.DEBIT-JR.CREDIT
                   FROM FOGUEST_JUR JR
                   WHERE JR.CATEGORY = :CATEGORY
                   AND JR.FODATE BETWEEN :SDATE AND :EDATE
                   AND JR.CORRECTED = 0
                   AND JR.JURCODE <> 'CL'
                   ORDER BY JR.FODATE
                   INTO FODATE,FOLIO,TRANS_ID,JURCODE,AMOUNT
               DO
               BEGIN
                 INFO = 'C/L';
                 SELECT GUESTNAME FROM FO_RPT_HIST_GUESTNAME(:FOLIO)
                 INTO GUESTNAME;
                 SUSPEND;
               END
            END
            /* ---------------------------------------------------------------- */
            /* CREDIT CARD                                                      */
            /* ACCOUNT DARI CREDIT CARD,TAPI CATEGORY BUKAN CREDIT CARD        */
            /* ---------------------------------------------------------------- */
            IF ((FLAG_CREDITCARD = 1) AND (FLAG_CREDITCARD_CAT = 0)) THEN
            BEGIN
               FOR SELECT JR.FODATE,JR.FOLIO,JR.TRANS_ID,JR.JURCODE,JR.DEBIT-JR.CREDIT
                   FROM FOGUEST_JUR JR
                   WHERE JR.CATEGORY = :CATEGORY
                   AND JR.FODATE BETWEEN :SDATE AND :EDATE
                   AND JR.CORRECTED = 0
                   ORDER BY JR.FODATE
                   INTO FODATE,FOLIO,TRANS_ID,JURCODE,AMOUNT
               DO
               BEGIN
                 INFO = 'Credit Card';
                 SELECT GUESTNAME FROM FO_RPT_HIST_GUESTNAME(:FOLIO)
                 INTO GUESTNAME;
                 SUSPEND;
               END
            END
         END
      END
  END
END^


ALTER PROCEDURE AR_DSR_CONTROL_OLD(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CL_TYPE VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    NAME VARCHAR(40),
    TOTAL_DSR DOUBLE PRECISION,
    TOTAL_AR DOUBLE PRECISION,
    TOTAL_AR_MANUAL DOUBLE PRECISION)
AS
DECLARE VARIABLE FLAG_AR INTEGER;
DECLARE VARIABLE TRANS_ACCOUNT VARCHAR(20);
DECLARE VARIABLE TRANS_DEPT VARCHAR(4);
DECLARE VARIABLE TRANS_COST VARCHAR(4);
DECLARE VARIABLE DSR_ID INTEGER;
DECLARE VARIABLE FACTOR DOUBLE PRECISION;
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.8.2005';
     EXECUTE PROCEDURE sp_endofmonth(SDATE) returning_values(EDATE);
  END

 select  CFG.ARVCH_TRANSIENT_ACC,CFG.ARVCH_TRANSIENT_DEPT,
         CFG.ARVCH_TRANSIENT_COST
 from FOSYSPARAM CFG
 LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.ARVCH_TRANSIENT_ACC
 into TRANS_ACCOUNT,TRANS_DEPT,TRANS_COST;

  TOTAL_AR = 0;
  TOTAL_AR_MANUAL = 0;
  FOR SELECT D.DSR_ID,SUM(D.AMOUNT+D.ADJUSTMENT) FROM fodsr D
      LEFT JOIN FODSR_LAY L ON D.DSR_ID = L.DSR_ID
      WHERE D.FODATE BETWEEN :SDATE AND :EDATE
      AND L.COMMAND = 'CAT'
      GROUP BY D.DSR_ID
      INTO DSR_ID,TOTAL_DSR
    DO
    BEGIN
      SELECT DB_ACCOUNT,DB_DEPT,DB_COST,FACTOR
      FROM FODSR_LAY_GL WHERE DSR_ID = :DSR_ID
      INTO :GL_ACCOUNT,:GL_DEPT,:GL_COST,:FACTOR;
      TOTAL_DSR = TOTAL_DSR * FACTOR;
      FLAG_AR = 0;
      CREDITCARD = 0;
      IF (TOTAL_DSR <> 0) THEN
      BEGIN
        CREDITCARD = 0;
        IF (EXISTS(SELECT * FROM syscustomertype WHERE GLACCOUNT = :GL_ACCOUNT
           AND GLDEPT = :GL_DEPT AND GLCOST = :GL_COST)) THEN FLAG_AR = 1;
           
        IF (FLAG_AR = 0) THEN
        BEGIN
           IF (EXISTS(SELECT * FROM AR_CARD WHERE GL_AR_ACCOUNT = :GL_ACCOUNT
           AND GL_AR_DEPT = :GL_DEPT AND GL_AR_COST = :GL_COST)) THEN FLAG_AR = 1;
           IF (FLAG_AR = 1) THEN CREDITCARD = 1;
        END
        IF (FLAG_AR = 0) THEN
        BEGIN
           IF ((GL_ACCOUNT = TRANS_ACCOUNT) AND (GL_DEPT = TRANS_DEPT) AND (GL_COST = TRANS_COST)) THEN
              FLAG_AR = 1;
        END
        IF (FLAG_AR = 1) THEN
        BEGIN
           SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
           IF (CREDITCARD = 0) THEN CL_TYPE = 'City Ledger';
           ELSE CL_TYPE = 'Credit Card';
           SUSPEND;
        END
      END
  END
  TOTAL_DSR = 0;
  CREDITCARD = 0;
  CL_TYPE = 'City Ledger';
  FOR SELECT T.GLACCOUNT,T.GLDEPT,T.GLCOST,SUM(V.TOTAL)
      FROM ARVCH V
      LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
      LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      GROUP BY T.GLACCOUNT,T.GLDEPT,T.GLCOST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END
  /* credit card */
  CL_TYPE = 'Credit Card';
  CREDITCARD = 1;
  FOR SELECT C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL)
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.FO_FOLIO <> 0 AND V.SOURCE = 'F'  /* 28 OCTOBER 2006,SOURCE = 'V'*/
      GROUP BY C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END
  /* manual credit card */
  TOTAL_AR = 0;
  FOR SELECT C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL)
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.FO_FOLIO = 0
      GROUP BY C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR_MANUAL
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END
END^


ALTER PROCEDURE AR_DSR_CONTROL_PGR(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CL_TYPE VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    NAME VARCHAR(40),
    TOTAL_DSR DOUBLE PRECISION,
    TOTAL_AR DOUBLE PRECISION,
    TOTAL_AR_MANUAL DOUBLE PRECISION)
AS
DECLARE VARIABLE FLAG_AR INTEGER;
DECLARE VARIABLE TRANS_ACCOUNT VARCHAR(20);
DECLARE VARIABLE TRANS_DEPT VARCHAR(4);
DECLARE VARIABLE TRANS_COST VARCHAR(4);
DECLARE VARIABLE DSR_ID INTEGER;
DECLARE VARIABLE FACTOR DOUBLE PRECISION;
/* 20 OCTOBER 2006 */
DECLARE VARIABLE LISTINDEX INTEGER;
DECLARE VARIABLE SOURCE CHAR(1); /* 28 OCTOBER 2006 */
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.9.2006';
     EXECUTE PROCEDURE sp_endofmonth(SDATE) returning_values(EDATE);
  END



  select  CFG.ARVCH_TRANSIENT_ACC,CFG.ARVCH_TRANSIENT_DEPT,
          CFG.ARVCH_TRANSIENT_COST
  from FOSYSPARAM CFG
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.ARVCH_TRANSIENT_ACC
  into TRANS_ACCOUNT,TRANS_DEPT,TRANS_COST;
  TOTAL_AR = 0;
  TOTAL_AR_MANUAL = 0;




  FOR SELECT D.DSR_ID,SUM(D.AMOUNT+D.ADJUSTMENT) FROM fodsr D
      LEFT JOIN FODSR_LAY L ON D.DSR_ID = L.DSR_ID
      WHERE D.FODATE BETWEEN :SDATE AND :EDATE
      AND L.COMMAND = 'CAT'
      GROUP BY D.DSR_ID
      INTO DSR_ID,TOTAL_DSR
    DO
    BEGIN



      FOR SELECT LISTINDEX,DB_ACCOUNT,DB_DEPT,DB_COST,FACTOR
          FROM FODSR_LAY_GL WHERE DSR_ID = :DSR_ID
          INTO :LISTINDEX,:GL_ACCOUNT,:GL_DEPT,:GL_COST,:FACTOR
      DO
      BEGIN
         TOTAL_DSR = TOTAL_DSR * FACTOR;
         FLAG_AR = 0;
         CREDITCARD = 0;



         IF (TOTAL_DSR <> 0) THEN
         BEGIN
          CREDITCARD = 0;
          IF (EXISTS(SELECT * FROM syscustomertype WHERE GLACCOUNT = :GL_ACCOUNT
             AND GLDEPT = :GL_DEPT AND GLCOST = :GL_COST)) THEN FLAG_AR = 1;



          IF (FLAG_AR = 0) THEN
          BEGIN
             IF (EXISTS(SELECT * FROM AR_CARD WHERE GL_AR_ACCOUNT = :GL_ACCOUNT
             AND GL_AR_DEPT = :GL_DEPT AND GL_AR_COST = :GL_COST)) THEN FLAG_AR = 1;
             IF (FLAG_AR = 1) THEN CREDITCARD = 1;
          END



          IF (FLAG_AR = 0) THEN
          BEGIN
             IF ((GL_ACCOUNT = TRANS_ACCOUNT) AND (GL_DEPT = TRANS_DEPT) AND (GL_COST = TRANS_COST)) THEN
                FLAG_AR = 1;
          END



          IF (FLAG_AR = 1) THEN
          BEGIN
             SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
             IF (CREDITCARD = 0) THEN CL_TYPE = 'City Ledger';
             ELSE CL_TYPE = 'Credit Card';
             SUSPEND;
          END





        END
      END
  END



  TOTAL_DSR = 0;
  CREDITCARD = 0;
  CL_TYPE = 'City Ledger';
  FOR SELECT T.GLACCOUNT,T.GLDEPT,T.GLCOST,SUM(V.TOTAL)
      FROM ARVCH V
      LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
      LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      GROUP BY T.GLACCOUNT,T.GLDEPT,T.GLCOST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END





  /* credit card */
  CL_TYPE = 'Credit Card';
  CREDITCARD = 1;
  FOR SELECT C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL)
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.SOURCE = 'F' /* 28 OCTPBER 2006,SOURCE = 'F'*/
      GROUP BY C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR
  DO
  BEGIN
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END




  /* manual credit card dan lainnya */
  TOTAL_AR = 0;
  FOR SELECT C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,SUM(V.TOTAL),V.SOURCE /* SOURCE 28 OCTOBER 2006 */
      FROM ar_card_jur V
      LEFT JOIN AR_CARD C ON C.CREDITCARD = V.CREDITCARD
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND V.SOURCE <> 'F' /* 28 OCTPBER 2006,SOURCE = 'F'*/
      GROUP BY C.GL_AR_ACCOUNT,C.GL_AR_DEPT,C.GL_AR_COST,V.SOURCE
  INTO GL_ACCOUNT,GL_DEPT,GL_COST,TOTAL_AR_MANUAL,SOURCE
  DO
  BEGIN
     IF (SOURCE = 'M') THEN
     BEGIN
        CREDITCARD = 2;
        CL_TYPE = 'Credit Card Manual';
     END
     ELSE IF (SOURCE = 'V') THEN
     BEGIN
        CREDITCARD = 3;
        CL_TYPE = 'Credit Card for Invoice';
     END
     ELSE IF (SOURCE = 'D') THEN
     BEGIN
        CREDITCARD = 4;
        CL_TYPE = 'Credit Card for Deposit';
     END
     ELSE
     BEGIN
        CREDITCARD = 9;
        CL_TYPE = 'Credit Card for Others';
     END
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO NAME;
     SUSPEND;
  END




END^


ALTER PROCEDURE AR_EOM_EXCHANGE(
    USR_ID VARCHAR(8),
    PSAVE INTEGER)
RETURNS (
    DOCTYPE VARCHAR(4),
    NUMBER INTEGER,
    OPENDATE DATE,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    CURRENCY VARCHAR(4),
    FOREX_TOTAL DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    V_EXCHANGE DOUBLE PRECISION,
    E_EXCHANGE DOUBLE PRECISION,
    DELTA_EXCHANGE DOUBLE PRECISION,
    GAINLOSS DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    DOCUMENT VARCHAR(20),
    NOTE VARCHAR(80))
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE EOM DATE;
DECLARE VARIABLE ARSYSDATE DATE;
BEGIN
  IF (PSAVE IS NULL) THEN PSAVE = 0;
  IF (PSAVE NOT IN (0, 1, -1)) THEN PSAVE = 0;
  
  SELECT ARSYSDATE,
         EXTRACT(MONTH FROM ARSYSDATE),
         EXTRACT(YEAR FROM ARSYSDATE),
         ARFOREX_GAINLOSS_GLDEPT,
         ARFOREX_GAINLOSS_GLCOST,
         ARFOREX_GAINLOSS_GLACCOUNT
  FROM FOSYSPARAM
  INTO ARSYSDATE, M, Y,
       GL_DEPT, GL_COST, GL_ACCOUNT;
  /* ---------------------------------------------------------------- */
  /* HITUNG AKHIR BULAN                                               */
  /* ---------------------------------------------------------------- */
  EXECUTE PROCEDURE SP_ENDOFMONTH(ARSYSDATE) RETURNING_VALUES EOM;

  /* ---------------------------------------------------------------- */
  /* JIKA BUKAN AKHIR BULAN TIDAK ADA                                 */
  /* ---------------------------------------------------------------- */
  IF (ARSYSDATE <> EOM) THEN EXIT;

  /* ---------------------------------------------------------------- */
  /* DELETE OLD REVALUATION                                           */
  /* ---------------------------------------------------------------- */
  IF (PSAVE = -1) THEN
  BEGIN
     DELETE FROM ARADJ WHERE SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';

     DELETE FROM ARDEPOS0_JUR WHERE SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';
     EXIT;
  END
  /* ---------------------------------------------------------------- */
  /* RECALCULATE                                                      */
  /* ---------------------------------------------------------------- */
  UPDATE ARVCH SET FO_PAX = -1
  WHERE EXCHANGE <> 1
  AND FOREX_TOTALDUE_PREPARE NOT BETWEEN - 0.05 AND 0.05
  AND FLAG_MERGED = 0
  AND OPENDATE <= :EOM;
  /* ---------------------------------------------------------------- */
  /* START PROCESS                                                    */
  /* ---------------------------------------------------------------- */

  DOCTYPE = 'VCH';
  FOR
    SELECT V.NUMBER, V.OPENDATE, V.CURRENCY,
           V.FOREX_TOTALDUE_PREPARE,
           V.TOTALDUE_PREPARE, V.CUSTOMER, C.NAME
    FROM ARVCH V
    LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
    WHERE V.EXCHANGE <> 1
    AND V.FOREX_TOTALDUE_PREPARE NOT BETWEEN - 0.05 AND 0.05
    AND V.FLAG_MERGED = 0
    AND V.OPENDATE <= :EOM
    INTO
      NUMBER, OPENDATE, CURRENCY,
      FOREX_TOTAL,
      TOTAL, CUSTOMER, NAME
  DO
  BEGIN

    V_EXCHANGE = TOTAL/FOREX_TOTAL;

    IF (NOT EXISTS(SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
               WHERE PYEAR = :Y AND PMONTH = :M AND CURRENCY = :CURRENCY)) THEN
    BEGIN
       EXCEPTION AR_GAINLOSS_INVALID 'Currency '|| CURRENCY || ' on period ' || M || '-'||Y|| ' does not exists';
    END
    SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
    WHERE PYEAR = :Y
    AND PMONTH = :M
    AND CURRENCY = :CURRENCY
    INTO E_EXCHANGE;
    
    
    IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN
    BEGIN
       DELTA_EXCHANGE = E_EXCHANGE - V_EXCHANGE;
       GAINLOSS = FOREX_TOTAL * DELTA_EXCHANGE;
       IF (GAINLOSS NOT BETWEEN -0.05 AND 0.05) THEN
       BEGIN
          DOCUMENT = 'RV-RE/'|| Y || '/'||M || '/' || NUMBER;
          NOTE = 'Due= ' || CAST(FOREX_TOTAL AS NUMERIC(8,2)) ||
                 ', Old Ex=' || CAST(:V_EXCHANGE AS NUMERIC(8,2)) ||
                 ', New Ex=' || CAST(:E_EXCHANGE AS NUMERIC(8,2));
          
          IF (PSAVE = 0) THEN
          BEGIN
             IF (NOT EXISTS(SELECT * FROM ARADJ
                     WHERE VOUCHERNO=:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
                SUSPEND; /* JIKA TIDAK DISIMPAN, DI SUSPEND */
          END
          ELSE
          BEGIN /* SAVE = 1 */
             /* ---------------------------------------------------------------- */
             /* DELETE IF STATUS "O"                                             */
             /* ---------------------------------------------------------------- */
             DELETE FROM ARADJ WHERE VOUCHERNO=:NUMBER
                 AND SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';
             /* ---------------------------------------------------------------- */
             /* CREATE NEW ADJUSTMENT                                            */
             /* ---------------------------------------------------------------- */
             IF (NOT EXISTS(SELECT * FROM ARADJ
                     WHERE VOUCHERNO=:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
             BEGIN
                INSERT INTO ARADJ (
                 VOUCHERNO, DOCUMENT, OPENDATE, STATUS, CUSTOMER,
                 ACCOUNT, DEPT, COST, PROJECT,
                 NOTE,
                 CREATEDATE, EDITDATE, CREATEUSER, EDITUSER,
                 FOREX_DB, FOREX_CR,
                 CURRENCY, EXCHANGE,
                 DB, CR,
                 SOURCE, SOURCENUMBER)
                VALUES (
                 :NUMBER,  :DOCUMENT, :EOM,  'O',  :CUSTOMER,
                 :GL_ACCOUNT, :GL_DEPT, :GL_COST, '0000',
                 :NOTE,
                 'NOW', 'NOW', :USR_ID, :USR_ID,
                 0, /* FOREX_DB */
                 0, /* FOREX_CR */
                 :CURRENCY, :E_EXCHANGE,
                 :GAINLOSS, /* DB */
                 0, /* CR */
                 'RE', 0);
                 
                /* RECALCULATE */
                UPDATE ARVCH SET FO_PAX = -1
                WHERE NUMBER = :NUMBER;
                
             END
          END /* SAVE = 1*/
       END /*  IF (DELTA NOT BETWEEN -0.05 AND 0.05) THEN */
    END /* IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN */
    
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSTI                                                          */
  /* ---------------------------------------------------------------- */
  /* RECALCULATE                                                      */
  /* ---------------------------------------------------------------- */
  UPDATE ARDEPOS0  SET FOREX_GAINLOSS = -1
  WHERE EXCHANGE <> 1
  AND FOREX_BALANCE NOT BETWEEN - 0.05 AND 0.05
  AND OPENDATE <= :EOM;
  /* ---------------------------------------------------------------- */
  DOCTYPE = 'DEP';
  FOR
    SELECT V.NUMBER, V.OPENDATE, V.CURRENCY,
           V.FOREX_BALANCE, V.BALANCE,
           V.CUSTOMER, C.NAME
    FROM ARDEPOS0 V
    LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
    WHERE V.EXCHANGE <> 1
    AND V.FOREX_BALANCE NOT BETWEEN - 0.05 AND 0.05
    AND V.OPENDATE <= :EOM
    INTO
      NUMBER, OPENDATE, CURRENCY,
      FOREX_TOTAL, TOTAL,
      CUSTOMER, NAME
  DO
  BEGIN

    V_EXCHANGE = TOTAL/FOREX_TOTAL;

    IF (NOT EXISTS(SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
               WHERE PYEAR = :Y AND PMONTH = :M AND CURRENCY = :CURRENCY)) THEN
    BEGIN
       EXCEPTION AR_GAINLOSS_INVALID 'Currency '|| CURRENCY || ' on period ' || M || '-'||Y|| ' does not exists';
    END
    SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
    WHERE PYEAR = :Y
    AND PMONTH = :M
    AND CURRENCY = :CURRENCY
    INTO E_EXCHANGE;


    IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN
    BEGIN
       DELTA_EXCHANGE = E_EXCHANGE - V_EXCHANGE;
       GAINLOSS = FOREX_TOTAL * DELTA_EXCHANGE;
       IF (GAINLOSS NOT BETWEEN -0.05 AND 0.05) THEN
       BEGIN
          DOCUMENT = 'RD-RE/'|| Y || '/'||M || '/' || NUMBER;
          NOTE = 'Due= ' || CAST(FOREX_TOTAL AS NUMERIC(8,2)) ||
                 ', Old Ex=' || CAST(:V_EXCHANGE AS NUMERIC(8,2)) ||
                 ', New Ex=' || CAST(:E_EXCHANGE AS NUMERIC(8,2));
                

          IF (PSAVE = 0) THEN
          BEGIN
             IF (NOT EXISTS(SELECT * FROM ARDEPOS0_JUR
                     WHERE DEPOSITNO =:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
                SUSPEND; /* JIKA TIDAK DISIMPAN, DI SUSPEND */
          END
          ELSE
          BEGIN /* SAVE = 1 */
             /* ---------------------------------------------------------------- */
             /* DELETE IF STATUS "O"                                             */
             /* ---------------------------------------------------------------- */
             DELETE FROM ARDEPOS0_JUR WHERE DEPOSITNO=:NUMBER
                 AND SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';
             /* ---------------------------------------------------------------- */
             /* CREATE NEW ADJUSTMENT                                            */
             /* ---------------------------------------------------------------- */
             IF (NOT EXISTS(SELECT * FROM ARDEPOS0_JUR
                     WHERE DEPOSITNO=:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
             BEGIN
                INSERT INTO ARDEPOS0_JUR (
                 DEPOSITNO, DOCUMENT, OPENDATE, STATUS, CUSTOMER,
                 ACCOUNT, DEPT, COST, PROJECT,
                 NOTE,
                 CREATEDATE, EDITDATE, CREATEUSER, EDITUSER,
                 FOREX_DB, FOREX_CR,
                 CURRENCY, EXCHANGE,
                 DB, CR,
                 SOURCE, SOURCENUMBER)
                VALUES (
                 :NUMBER,  :DOCUMENT, :EOM,  'O',  :CUSTOMER,
                 :GL_ACCOUNT, :GL_DEPT, :GL_COST, '0000',
                 :NOTE,
                 'NOW', 'NOW', :USR_ID, :USR_ID,
                 0, /* FOREX_DB */
                 0, /* FOREX_CR */
                 :CURRENCY, :E_EXCHANGE,
                 :GAINLOSS, /* DB */
                 0, /* CR */
                 'RE', 0);
             END
             /* RECALULATE AFTER UPDATE */
             UPDATE ARDEPOS0  SET FOREX_GAINLOSS = -1
             WHERE NUMBER = :NUMBER;
             
          END /* SAVE = 1*/
       END /*  IF (DELTA NOT BETWEEN -0.05 AND 0.05) THEN */
    END /* IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN */

  END
END^


ALTER PROCEDURE AR_GLBUFFER_ADJ_RELEASE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
DECLARE VARIABLE VNAME VARCHAR(40);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
DECLARE VARIABLE ADJ_SOURCE VARCHAR(2);
DECLARE VARIABLE ADJ_SOURCENUMBER INTEGER;
DECLARE VARIABLE ADJ_CREDITCARD VARCHAR(6);
DECLARE VARIABLE CC_GL_ACCOUNT VARCHAR (20);
DECLARE VARIABLE CC_GL_DEPT VARCHAR (4);
DECLARE VARIABLE CC_GL_COST VARCHAR (4);
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Clearance from System Parameter                              */
 /*          Credit : A/R From Customer/Customer Type                         */
 /*          Credit : Gain & Loss Currency Exchange JIKA ADA                  */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM ARADJ INTO NUMBER;

 SELECT A.DOCUMENT, V.CUSTOMER, A.OPENDATE, A.DB, A.CR
 FROM ARADJ A
 LEFT JOIN ARVCH V ON V.NUMBER = A.VOUCHERNO
 WHERE A.NUMBER = :NUMBER
 INTO REF, CUSTOMER, TRANSDATE, DB, CR;
 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR                                                        */
 /* ------------------------------------------------------------------- */
 select name, custtype, account, gl_dept, gl_cost, RELATION_DOCTYPE from SYSCUSTOMER
 where CUSTOMER = :CUSTOMER
 into :vname, custtype, GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;
 RELATION_CODE = CUSTOMER;

 select glaccount, gldept, glcost FROM SYSCUSTOMERTYPE
 WHERE CUSTOMERTYPE = :CUSTTYPE
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';
    
 APPLICATION = 'AR';
 SOURCE = 'ADJ';
 INFO = 'Voucher';
 ID = 1;
 NOTE = vName;
 DEBIT = DB;
 CREDIT = CR;
 SETUP_INFO = 'CUSTOMER_TYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* ADJUSTMENT                                        */
 /* ------------------------------------------------------------------- */
 SELECT ACCOUNT, DEPT, COST, VOUCHERNO,
        SOURCENUMBER, SOURCE
 FROM ARADJ WHERE NUMBER = :NUMBER
 into GL_ACCOUNT, GL_DEPT, GL_COST, SETUP_DATA,
      ADJ_SOURCENUMBER, ADJ_SOURCE;
    
 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';

 INFO = 'Adjustment';
 ID = 2;
 /* -------------------------------------------------------------------- */
 /* 25 AUG 2010                                                          */
 /* KALAU DIUBAH TETAP PAKAI CC                                          */
 /* -------------------------------------------------------------------- */
 IF (ADJ_SOURCE = 'CC') THEN
 BEGIN
    INFO = 'Inv.by Credit Card';
    SELECT CREDITCARD FROM AR_CARD_JUR
    WHERE NUMBER = :ADJ_SOURCENUMBER
    INTO ADJ_CREDITCARD;

    SELECT GL_AR_ACCOUNT, GL_AR_DEPT, GL_AR_COST
    FROM AR_CARD
    WHERE CREDITCARD = :ADJ_CREDITCARD
    INTO CC_GL_ACCOUNT, CC_GL_DEPT, CC_GL_COST;
    SETUP_DATA = ADJ_CREDITCARD;
    IF ((CC_GL_ACCOUNT <> GL_ACCOUNT) OR (CC_GL_DEPT <> GL_DEPT) OR (CC_GL_COST <> GL_COST)) THEN
    BEGIN
       ERROR_TEXT = 'Set Account to C/C ' || ADJ_CREDITCARD || ': '|| CC_GL_ACCOUNT||'-'||CC_GL_DEPT||'-'||CC_GL_COST;
       GL_ACCOUNT = CC_GL_ACCOUNT;
       GL_DEPT = CC_GL_DEPT;
       GL_COST = CC_GL_COST;
    END
 END
 /* -------------------------------------------------------------------- */
 DEBIT = CR;
 CREDIT = DB;
 SETUP_INFO = 'ARVCH';
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_BATCH_RELEASE(
    BATCH_NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE NUMBER INTEGER;
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
DECLARE VARIABLE VNAME VARCHAR(40);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT END OF DAY PROCESS                                       */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Account from Customer Type                                   */
 /*          Credit : A/R Transient from Parameter Setup                      */
 /* ------------------------------------------------------------------------- */
 /*  A/R Transient digunakan juga di Income dgn journal                       */
 /*           A/R Transient | Guest Ledger                                    */
 /* ------------------------------------------------------------------------- */
 IF (BATCH_NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM ARVCH_BATCH INTO BATCH_NUMBER;
 
 FOR SELECT NUMBER FROM ARVCH WHERE BATCH_NUMBER = :BATCH_NUMBER
     INTO NUMBER DO
 BEGIN
     FOR SELECT APPLICATION, SOURCE, INFO, TRANSDATE, ID,
                GL_ACCOUNT, GL_DEPT, GL_COST,
                ACCNAME, NOTE, REF,
                DEBIT, CREDIT,
                SETUP_INFO, SETUP_DATA, ERROR_TEXT,
                RELATION_CODE, RELATION_DOCTYPE
          FROM AR_GLBUFFER_VCH_EOD(:NUMBER)
     INTO APPLICATION, SOURCE, INFO, TRANSDATE, ID,
          GL_ACCOUNT, GL_DEPT, GL_COST,
          ACCNAME, NOTE, REF,
          DEBIT, CREDIT,
          SETUP_INFO, SETUP_DATA, ERROR_TEXT,
          RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
       SUSPEND;
     END
  END
end^


ALTER PROCEDURE AR_GLBUFFER_CASH_BANKBOOK(
    PNUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    BANK VARCHAR(4),
    BBDATE DATE,
    BBLINE INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    SOURCEID INTEGER)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
BEGIN
  IF ((PNUMBER IS NULL) OR (PNUMBER = 0)) THEN PNUMBER = 1;
  SELECT CUSTOMER, RECONCILEDATE, BANK, CHECK_NUMBER, FOREX_TOTAL,
         CURRENCY, EXCHANGE
  FROM ARCASH0
  WHERE NUMBER = :PNUMBER
  INTO CUSTOMER, BBDATE, BANK, DOCUMENT, FOREX_CR, CURRENCY, EXCHANGE;
  
  select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare from sysbank
  where bank = :BANK
  into ACCOUNT, DEPT, COST;
       
  SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER
  INTO REMARK;
  
  NUMBER = 0;
  BBLINE = 0;
  STATUS = 'O';
  BBCODE = 'AR';
  APPLICATION = 'AR';
  SOURCE = 'REC';
  SOURCENUMBER = PNUMBER;
  SOURCEID = 0;
  FOREX_DB = 0;
  REF=PNUMBER;
  SUSPEND;
END^


ALTER PROCEDURE AR_GLBUFFER_CASH_RECONCILE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
declare variable CUSTOMER VARCHAR(6);
declare variable BANK VARCHAR(4);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
declare variable vName VARCHAR(40);
declare variable TOTAL DOUBLE PRECISION;
DECLARE VARIABLE GAINLOSS DOUBLE PRECISION;
DECLARE VARIABLE CHECK_NUMBER VARCHAR(20);
DECLARE VARIABLE DOCUMENT VARCHAR(20);
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RECONCILE                          */
 /* ------------------------------------------------------------------------- */
 /*  Debit : BANK                                                             */
 /*          Credit : A/R Clearance                                           */
 /* ------------------------------------------------------------------------- */
 IF ((NUMBER = 0) OR (NUMBER IS NULL)) THEN NUMBER = 4;

 SELECT DOCUMENT, CUSTOMER, RECONCILEDATE, TOTAL, forex_gainloss, BANK, CHECK_NUMBER  FROM
 ARCASH0 WHERE NUMBER = :NUMBER
 INTO DOCUMENT, CUSTOMER, TRANSDATE, TOTAL, GAINLOSS, BANK, CHECK_NUMBER;

 RELATION_CODE = BANK;
     
 select gl_account, gl_dept, gl_cost, RELATION_DOCTYPE
 from sysbank where bank = :bank
 into GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;
 
 SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER INTO :vName;

 APPLICATION = 'AR';
 SOURCE = 'REC';
 INFO = 'Reconcile';
 ID = 1;
 NOTE = vName;
 DEBIT = TOTAL;
 CREDIT = 0;
 SETUP_INFO = 'SYSBANK';
 SETUP_DATA = BANK;
 REF = CHECK_NUMBER;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR CLEARANCE                                              */
 /* ------------------------------------------------------------------- */
 select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare
 from sysbank where bank = :bank
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 APPLICATION = 'AR';
 SOURCE = 'REC';
 INFO = 'Reconcile';
 ID = 1;
 NOTE = vName;
 DEBIT = 0;
 CREDIT = TOTAL;
 SETUP_INFO = 'SYSBANK';
 SETUP_DATA = BANK;
 REF = DOCUMENT;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_CASH_RELEASE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
declare variable CUSTOMER VARCHAR(6);
declare variable BANK VARCHAR(4);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
declare variable vName VARCHAR(40);
declare variable TOTAL DOUBLE PRECISION;
DECLARE VARIABLE GAINLOSS DOUBLE PRECISION;
DECLARE VARIABLE CREDITCARD VARCHAR(6);
/* 9/21/2011 */
DECLARE VARIABLE ADJ_TOTAL DOUBLE PRECISION;
DECLARE VARIABLE ADJ_GL_ACCOUNT VARCHAR (20);
DECLARE VARIABLE ADJ_GL_DEPT VARCHAR (4);
DECLARE VARIABLE ADJ_GL_COST VARCHAR (4);
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Clearance from System Parameter                              */
 /*          Credit : A/R From Customer/Customer Type                         */
 /*          Credit : Gain & Loss Currency Exchange JIKA ADA                  */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN NUMBER = 543;

 APPLICATION = 'AR';
 SOURCE = 'CASH';

 ID = 1;
 SELECT DOCUMENT, CUSTOMER, DUEDATE, TOTAL, forex_gainloss, BANK,
        CREDITCARD, /* 12 aug 2010 */
        ADJ_TOTAL, ADJ_GL_ACCOUNT, ADJ_GL_DEPT, ADJ_GL_COST /* 9/21/2011 */
 FROM ARCASH0 WHERE NUMBER = :NUMBER
 INTO REF, CUSTOMER, TRANSDATE, TOTAL, GAINLOSS, BANK,
      CREDITCARD, /* 12 aug 2010 */
      ADJ_TOTAL, ADJ_GL_ACCOUNT, ADJ_GL_DEPT, ADJ_GL_COST; /* 9/21/2011 */
    
 IF (BANK <> '') THEN
 BEGIN
    select RELATION_DOCTYPE, NAME from SYSCUSTOMER
    where CUSTOMER = :CUSTOMER
    into RELATION_DOCTYPE, vName;
    RELATION_CODE = CUSTOMER;
     
    select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare
    from sysbank where bank = :bank
    into GL_ACCOUNT, GL_DEPT, GL_COST;

    NOTE = vName;
    DEBIT = TOTAL;
    CREDIT = 0;
    SETUP_INFO = 'SYSBANK';
    SETUP_DATA = BANK;
    INFO = 'Clearance';
 END
 ELSE
 BEGIN
    select GL_AR_ACCOUNT, GL_AR_DEPT, GL_AR_COST, NAME
    from AR_CARD where CREDITCARD = :CREDITCARD
    into GL_ACCOUNT, GL_DEPT, GL_COST, vName;

    APPLICATION = 'AR';
    INFO = 'Credit Card';
    ID = 1;
    NOTE = vName;
    DEBIT = TOTAL;
    CREDIT = 0;
    SETUP_INFO = 'AR_CARD';
    SETUP_DATA = CREDITCARD;
 END
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR                                                        */
 /* ------------------------------------------------------------------- */
 select name, custtype, account, gl_dept, gl_cost, RELATION_DOCTYPE from SYSCUSTOMER
 where CUSTOMER = :CUSTOMER
 into :vname, custtype, GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;
 RELATION_CODE = CUSTOMER;

 select glaccount, gldept, glcost FROM SYSCUSTOMERTYPE
 WHERE CUSTOMERTYPE = :CUSTTYPE
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '';
    
 APPLICATION = 'AR';
 SOURCE = 'CASH';
 INFO = 'Voucher';
 ID = 2;
 NOTE = vName;
 DEBIT = 0;
 CREDIT = TOTAL-GAINLOSS-ADJ_TOTAL;
 SETUP_INFO = 'CUSTOMER_TYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;

 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR                                                        */
 /* ------------------------------------------------------------------- */
 /* -------------------------------------------------------------------- */
 /* 9/21/2011                                                            */
 /* OVER RECEIVED                                                        */
 /* -------------------------------------------------------------------- */
 IF (ADJ_TOTAL <> 0) THEN
 BEGIN
     APPLICATION = 'AR';
     SOURCE = 'CASH';
     INFO = 'OverReceived';
     ID = 2;
     NOTE = vName;
     DEBIT = 0;
     CREDIT = ADJ_TOTAL;
     SETUP_INFO = 'ARCASH0';
     SETUP_DATA = NUMBER;
     GL_ACCOUNT = ADJ_GL_ACCOUNT;
     GL_DEPT    = ADJ_GL_DEPT;
     GL_COST    = ADJ_GL_COST;
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
     SUSPEND;
 END
 /* end of 9/21/2011 */
 /* ------------------------------------------------------------------- */
 /* GAIN/LOSS CURRENCY EXCHANGE                                         */
 /* ------------------------------------------------------------------- */
 IF (GAINLOSS <>0) THEN
 BEGIN
    select arforex_gainloss_glaccount, arforex_gainloss_gldept,arforex_gainloss_glcost
    from FOSYSPARAM
    into GL_ACCOUNT, GL_DEPT, GL_COST;
    
    if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
    if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';

    INFO = 'Gain & Loss';
    ID = 3;
    DEBIT = 0;
    CREDIT = GAINLOSS;
    SETUP_INFO = 'SYSPARAM';
    SETUP_DATA = '';
    SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
    SUSPEND;
 END
end^


ALTER PROCEDURE AR_GLBUFFER_CC_BATCH_BANKBOOK(
    PNUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    BANK VARCHAR(4),
    BBDATE DATE,
    BBLINE INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    SOURCEID INTEGER)
AS
DECLARE VARIABLE CREDITCARD VARCHAR(6);
DECLARE VARIABLE I INTEGER;
BEGIN
  IF ((PNUMBER IS NULL) OR (PNUMBER = 0)) THEN PNUMBER = 14;

  REMARK = '';
  I = 0;
  FOR SELECT CREDITCARD FROM AR_CARD_JUR
      where batch_number = :pnumber
      GROUP BY CREDITCARD
      INTO CREDITCARD
  DO BEGIN
     IF (I = 0) THEN REMARK = CREDITCARD;
     ELSE IF (I < 5) THEN REMARK = REMARK || ', ' || CREDITCARD;
     I = I + 1;
  END
  
  SELECT BANK, RECONCILEDATE, PAY_REF, CALC_AMOUNT_NET, PAY_REF
  FROM AR_CARD_BATCH
  WHERE NUMBER = :PNUMBER
  INTO BANK, BBDATE, DOCUMENT, FOREX_CR, REF;
  if (FOREX_CR IS NULL) then EXIT;

  select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare, currency from sysbank
  where bank = :BANK
  into ACCOUNT, DEPT, COST, CURRENCY;

  EXCHANGE = 1;
  NUMBER = 0;
  BBLINE = 0;
  STATUS = 'O';
  BBCODE = 'AR';
  APPLICATION = 'AR';
  SOURCE = 'CREC';
  SOURCENUMBER = PNUMBER;
  SOURCEID = 0;
  FOREX_DB = 0;
  REF=PNUMBER;
  SUSPEND;
END^


ALTER PROCEDURE AR_GLBUFFER_CC_BATCH_RECONCILE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE CREDITCARD VARCHAR(6);
DECLARE VARIABLE I INTEGER;
/* 15 MARET 2007 */
DECLARE VARIABLE BATCH INTEGER;
DECLARE VARIABLE OUTLET VARCHAR(4);
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 /*  Debit : BANK                                                             */
 /*          Credit : A/R Clearance                                           */
 /* ------------------------------------------------------------------------- */
 IF ((NUMBER IS NULL) OR (NUMBER = 0)) THEN NUMBER = 11;

 SELECT DOCUMENT, RECONCILEDATE, CALC_AMOUNT_NET, BANK, PAY_REF, BANK, OUTLET, BATCH
 FROM AR_CARD_BATCH WHERE NUMBER = :NUMBER
 INTO REF, TRANSDATE, TOTAL, BANK, REF, BANK, OUTLET, BATCH;
 IF (TOTAL IS NULL) THEN TOTAL = 0;

 NOTE = '';
 I = 0;
 FOR SELECT CREDITCARD FROM AR_CARD_JUR
/* where BATCH_NUMBER = :NUMBER */
     where BANK = :BANK
     AND OUTLET = :OUTLET
     AND BATCH = :BATCH
     GROUP BY CREDITCARD
     INTO CREDITCARD
 DO BEGIN
    IF (I = 0) THEN NOTE = CREDITCARD;
    ELSE IF (I < 5) THEN NOTE = NOTE || ', ' || CREDITCARD;
    I = I + 1;
 END


 
 select sum(calc_net) from ar_card_jur
/* where BATCH_NUMBER = :NUMBER */
 where BANK = :BANK
 AND OUTLET = :OUTLET
 AND BATCH = :BATCH
 into TOTAL;
 IF (TOTAL IS NULL) THEN TOTAL = 0;
 /* ------------------------------------------------------------------------- */
 /*  Debit : BANK                                                             */
 /* ------------------------------------------------------------------------- */
 select gl_account, gl_dept, gl_cost, RELATION_DOCTYPE
 from sysbank where bank = :bank
 into GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;
 IF (RELATION_DOCTYPE IS NULL) then RELATION_DOCTYPE = 0;

 RELATION_CODE = BANK;
 ERROR_TEXT = '';
 APPLICATION = 'AR';
 SOURCE = 'CREC';
 INFO = 'Bank';
 ID = 1;
 DEBIT = TOTAL;
 CREDIT = 0;
 SETUP_INFO = 'SYSBANK';
 SETUP_DATA = BANK;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;

 /* ------------------------------------------------------------------------- */
 /* Credit : A/R Clearance                                                    */
 /* ------------------------------------------------------------------------- */
 select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare, RELATION_DOCTYPE
 from sysbank where bank = :bank
 into GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;
 IF (RELATION_DOCTYPE IS NULL) then RELATION_DOCTYPE = 0;
 
 RELATION_CODE = BANK;
 ERROR_TEXT = '';
 INFO = 'Clearance';
 ID = 2;
 DEBIT = 0;
 CREDIT = TOTAL;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_CC_BATCH_RELEASE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE VNAME VARCHAR(40);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE VFEE_ACCOUNT VARCHAR(20);
DECLARE VARIABLE VFEE_DEPT VARCHAR(4);
DECLARE VARIABLE VFEE_COST VARCHAR(4);
DECLARE VARIABLE VTOTALNET DOUBLE PRECISION;
DECLARE VARIABLE VTOTALFEE DOUBLE PRECISION;
DECLARE VARIABLE VCREDITCARD VARCHAR(6);
DECLARE VARIABLE BATCH INTEGER;
DECLARE VARIABLE OUTLET VARCHAR(4);
DECLARE VARIABLE LINE INTEGER;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Clearance from System Parameter                              */
 /*          Credit : A/R From Customer/Customer Type                         */
 /*          Credit : Gain & Loss Currency Exchange JIKA ADA                  */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM AR_CARD_BATCH INTO NUMBER;

 SELECT DOCUMENT, PAY_DATE, CALC_AMOUNT_NET, BANK, PAY_REF, BATCH, OUTLET /* 22 NOV 2006, BEFORE OPENDATE */
 FROM AR_CARD_BATCH WHERE NUMBER = :NUMBER
 INTO REF, TRANSDATE, TOTAL, BANK, REF, BATCH, OUTLET;
    
 select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare, BANKNAME, RELATION_DOCTYPE
 from sysbank where bank = :bank
 into GL_ACCOUNT, GL_DEPT, GL_COST, vName, RELATION_DOCTYPE;
 IF (RELATION_DOCTYPE IS NULL) then RELATION_DOCTYPE = 0;
 RELATION_CODE = BANK;
 ERROR_TEXT = '';

 select sum(calc_net) from ar_card_jur
 where batch = :BATCH and bank = :BANK and outlet = :OUTLET
 into TOTAL;
 if (TOTAL IS NULL) then EXIT;
 LINE = 1;
 APPLICATION = 'AR';
 SOURCE = 'CCPY';
 INFO = 'Clearance';
 ID = LINE;
 NOTE = vName;
 DEBIT = TOTAL;
 CREDIT = 0;
 SETUP_INFO = 'SYSBANK';
 SETUP_DATA = BANK;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
 LINE = LINE + 1;
 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR                                                        */
 /* ------------------------------------------------------------------- */
 for select creditcard, sum(calc_net), sum(calc_fee) from ar_card_jur
     where batch = :BATCH
     and bank = :BANK
     and outlet = :OUTLET
     group by creditcard
     into :vCreditCard, :vTotalNet, :vTotalFee
 do begin
    /* ------------------------------------------------------------------ */
    /* CREDIT CARD INFO                                                   */
    /* ------------------------------------------------------------------ */     
    select name, gl_ar_account,  gl_ar_dept,  gl_ar_cost,
                 gl_fee_account, gl_fee_dept, gl_fee_cost
    from ar_card where creditcard = :vCreditcard
    into :vName, GL_ACCOUNT, GL_DEPT, GL_COST,
                 :vFee_Account, :vFee_Dept, :vFee_Cost;
                            
    if ((vFee_Dept is null) or (vFee_Dept = '')) then vFee_Dept = '0000';
    if ((vFee_Cost is null) or (vFee_Cost = '')) then vFee_Cost = '0000';     
    /* ------------------------------------------------------------------ */
    /* DETAIL CREDIT CARD                                                 */
    /* ------------------------------------------------------------------ */
/*
           -------------------------------
           CASH        |
           FEE         |
                       |  A/R CREDIT CARD
*/
    SOURCE = 'CCPY';
    INFO = 'Card';
    ID = LINE;
    NOTE = vName;
    DEBIT = 0;
    CREDIT = :vTotalNet+:vTotalFee;    
    SETUP_INFO = 'AR_CARD';
    SETUP_DATA = vCreditCard;
    SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
    SUSPEND;
    LINE = LINE + 1;
    /* ------------------------------------------------------------------ */
    /* A/R FEE                                                            */
    /* ------------------------------------------------------------------ */
    if (vTotalFee <> 0) then
    BEGIN
      SOURCE = 'CCPY';
      INFO = 'Fee';
      ID = LINE;
      GL_ACCOUNT = vFee_Account;
      GL_DEPT = vFee_Dept;
      GL_COST = vFee_Cost;
      NOTE = vName;
      DEBIT = vTotalFee;
      CREDIT = 0;
      SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
      SUSPEND;
      LINE = LINE + 1;
    END

  END
end^


ALTER PROCEDURE AR_GLBUFFER_CC_MANUAL_RELEASE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE CREDITCARD VARCHAR(6);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE CARDNUMBER VARCHAR(40);
DECLARE VARIABLE CARD_SOURCE VARCHAR(1);
/* 25 AUG 2010 */
DECLARE VARIABLE CARD_SOURCEID INTEGER;
DECLARE VARIABLE CUSTOMER VARCHAR(6);
begin
 /* ------------------------------------------------------------------------- */
 /* 9 OCTOBER 2005                                                            */
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT GLSTATUS AR_CARD_JUR DI RELEASE                          */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Dari Credit Card                                             */
 /*          Credit : A/R Entry                                               */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM AR_CARD_JUR WHERE SOURCE = 'M' INTO NUMBER;

 SELECT OPENDATE, CREDITCARD, TOTAL, CARDNUMBER, GL_ACCOUNT, GL_DEPT, GL_COST,
        SOURCE, FO_FOLIO /* 25 AUG 2010 */
 FROM AR_CARD_JUR WHERE NUMBER = :NUMBER
 INTO TRANSDATE, CREDITCARD, TOTAL, CARDNUMBER, GL_ACCOUNT, GL_DEPT, GL_COST,
      CARD_SOURCE, CARD_SOURCEID; /* 25 AUG 2010 */
 if (TOTAL IS NULL) then EXIT;
 /* ----------------------------------------------------------------*/
 /* suspend creditnya dulu                                          */
 /* ----------------------------------------------------------------*/
 IF (NOTE<> '') THEN
 BEGIN
    REF=NOTE;
    WHEN ANY DO
    BEGIN
       REF=CREDITCARD;
    END
 END
 RELATION_DOCTYPE = 0;
 NOTE = CARDNUMBER;
 APPLICATION = 'AR';
 SOURCE = 'CC';
 NOTE = CREDITCARD;
 RELATION_CODE = CREDITCARD;
 /* -------------------------------------------------------------------- */
 /* 25 AUG 2010                                                          */
 /* -------------------------------------------------------------------- */
 IF (CARD_SOURCE = 'C') THEN
 BEGIN
    INFO = 'Cash';
    NOTE = 'Cash paid by Credit Card';
    SELECT CUSTOMER FROM ARCASH0 WHERE NUMBER = :CARD_SOURCEID
    INTO CUSTOMER;
    RELATION_CODE = CUSTOMER;
    SELECT T.GLACCOUNT, T.GLDEPT, T.GLCOST
    FROM SYSCUSTOMER C
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE=C.CUSTTYPE
    WHERE C.CUSTOMER = :CUSTOMER
    INTO GL_ACCOUNT, GL_DEPT, GL_COST;
 END
 ELSE INFO = 'Manual';
 /* -------------------------------------------------------------------- */
 ERROR_TEXT = '';
 SETUP_DATA = '';

 ID = 2;
 DEBIT = 0;
 CREDIT = TOTAL;
 SETUP_INFO = 'AR_CARD_JUR';
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
 /* ----------------------------------------------------------------*/
 /* suspend debit                                                   */
 /* ----------------------------------------------------------------*/
 
 SELECT GL_AR_ACCOUNT, GL_AR_DEPT, GL_AR_COST, RELATION_DOCTYPE, NAME FROM AR_CARD
 WHERE CREDITCARD = :CREDITCARD
 into GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE, NOTE;

 IF (RELATION_DOCTYPE IS NULL) then RELATION_DOCTYPE = 0;

 ID = 1;
 DEBIT = TOTAL;
 CREDIT = 0;
 SETUP_INFO = 'AR_CARD';
 INFO = 'Credit Card';
 SETUP_DATA = CREDITCARD;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_DEPOSIT_APPLY(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
DECLARE VARIABLE VNAME VARCHAR(40);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE GAINLOSS DOUBLE PRECISION;
DECLARE VARIABLE DEPOSIT_NUMBER INTEGER;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Clearance from System Parameter                              */
 /*          Credit : A/R From Customer/Customer Type                         */
 /*          Credit : Gain & Loss Currency Exchange JIKA ADA                  */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(APPLY_NUMBER) FROM ARDEPOS1 INTO NUMBER;

 SELECT CUSTOMER, TEXT1, APPLIEDDATE, TOTAL, VCH_GAINLOSS, NUMBER
 FROM ARDEPOS1 WHERE APPLY_NUMBER = :NUMBER
 INTO CUSTOMER, NOTE, TRANSDATE, TOTAL, GAINLOSS, DEPOSIT_NUMBER;


 SELECT DOCUMENT, CUSTOMER,  BANK
 FROM ARDEPOS0 WHERE NUMBER = :DEPOSIT_NUMBER
 INTO REF, CUSTOMER, BANK;
 
 IF (DEPOSIT_NUMBER IS NULL) THEN EXIT;
    
 /* ------------------------------------------------------------------- */
 /* DEBIT DEPOSIT                                                       */
 /* ------------------------------------------------------------------- */
 select name, custtype, RELATION_DOCTYPE from SYSCUSTOMER
 where CUSTOMER = :CUSTOMER
 into :vname, custtype, RELATION_DOCTYPE;
 RELATION_CODE = CUSTOMER;
 IF (RELATION_DOCTYPE IS NULL) THEN RELATION_DOCTYPE = 0;
 
 select depos_glaccount, depos_gldept, DEPOS_GLCOST FROM SYSCUSTOMERTYPE
 WHERE CUSTOMERTYPE = :CUSTTYPE
 into GL_ACCOUNT, GL_DEPT, GL_COST;
 
 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';
    
 APPLICATION = 'AR';
 SOURCE = 'DEP1';
 INFO = 'Deposit';
 ID = 1;
 NOTE = vName;
 DEBIT = TOTAL+GAINLOSS;
 CREDIT = 0;
 SETUP_INFO = 'CUSTOMER_TYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;    
 /* ------------------------------------------------------------------- */
 /* CREDIT AR                                                           */
 /* ------------------------------------------------------------------- */    
 select account, gl_dept, gl_cost from SYSCUSTOMER where CUSTOMER = :CUSTOMER
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 /* find customer a/r account */
/* if ((GL_ACCOUNT is Null) or (GL_ACCOUNT = '')) then
 BEGIN*/
    select glaccount, gldept, glcost FROM SYSCUSTOMERTYPE
    WHERE CUSTOMERTYPE = :CUSTTYPE
    into GL_ACCOUNT, GL_DEPT, GL_COST;
/* END*/
 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';

 APPLICATION = 'AR';
 SOURCE = 'DEP1';
 INFO = 'A/R';
 ID = 2;
 NOTE = vName;
 DEBIT = 0;
 CREDIT = TOTAL;
 SETUP_INFO = 'CUSTTYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* CREDIT (LOSS) & GAIN DEPOSIT                                        */
 /* ------------------------------------------------------------------- */
 if (GAINLOSS <> 0) then
 begin
    select arforex_gainloss_glaccount, arforex_gainloss_gldept,
           arforex_gainloss_glcost
    from fosysparam
    into :GL_ACCOUNT, GL_DEPT, GL_COST;
 
    if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
    if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';
    
    INFO = 'Gain & Loss';
    ID = 3;
    DEBIT = 0;
    CREDIT = GAINLOSS;
    SETUP_INFO = 'SYSPARAM';
    SETUP_DATA = '';
    SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
    SUSPEND;
  end       
end^


ALTER PROCEDURE AR_GLBUFFER_DEPOSIT_BANKBOOK(
    PNUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    BANK VARCHAR(4),
    BBDATE DATE,
    BBLINE INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    SOURCEID INTEGER)
AS
BEGIN
  IF ((PNUMBER IS NULL) OR (PNUMBER = 0)) THEN PNUMBER = 125;

  SELECT D.BANK, D.RECONCILEDATE, D.DOCUMENT, D.CURRENCY,
         D.EXCHANGE, D.FOREX_TOTAL, D.DOCUMENT, C.NAME
  FROM ARDEPOS0 D
  LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = D.CUSTOMER
  WHERE D.NUMBER = :PNUMBER
  INTO BANK, BBDATE, DOCUMENT, CURRENCY, EXCHANGE, FOREX_CR, REF, REMARK;


  select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare, currency from sysbank
  where bank = :BANK
  into ACCOUNT, DEPT, COST, CURRENCY;

  NUMBER = 0;
  BBLINE = 0;
  STATUS = 'O';
  BBCODE = 'AR';
  APPLICATION = 'AR';
  SOURCE = 'DREC';
  SOURCENUMBER = PNUMBER;
  SOURCEID = 0;
  FOREX_DB = 0;
  REF=PNUMBER;
  SUSPEND;
END^


ALTER PROCEDURE AR_GLBUFFER_DEPOSIT_JUR_RELEASE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
DECLARE VARIABLE VNAME VARCHAR(40);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM ARDEPOS0_JUR INTO NUMBER;

 SELECT D.DOCUMENT, D.CUSTOMER, D.OPENDATE, D.DB, D.CR FROM ARDEPOS0_JUR D
 WHERE D.NUMBER = :NUMBER
 INTO REF, CUSTOMER, TRANSDATE, DB, CR;
 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR                                                        */
 /* ------------------------------------------------------------------- */
 select name, custtype, account, gl_dept, gl_cost, RELATION_DOCTYPE
 from SYSCUSTOMER
 where CUSTOMER = :CUSTOMER
 into :vname, custtype, GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;
 RELATION_CODE = CUSTOMER;

 select DEPOS_GLACCOUNT, DEPOS_GLDEPT, DEPOS_GLCOST FROM SYSCUSTOMERTYPE
 WHERE CUSTOMERTYPE = :CUSTTYPE
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';
    
 APPLICATION = 'AR';
 SOURCE = 'DADJ';
 INFO = 'Deposit';
 ID = 1;
 NOTE = vName;
 DEBIT = CR;
 CREDIT = DB;
 SETUP_INFO = 'CUSTOMER_TYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* DEPOSIT                                                             */
 /* ------------------------------------------------------------------- */
 SELECT ACCOUNT, DEPT, COST, DEPOSITNO FROM ARDEPOS0_JUR WHERE NUMBER = :NUMBER
 into GL_ACCOUNT, GL_DEPT, GL_COST, SETUP_DATA;
    
 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';

 INFO = 'Journal';
 ID = 2;
 DEBIT = DB;
 CREDIT = CR;
 SETUP_INFO = 'ARDEPOS0_JUR';
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_DEPOSIT_RECONCILE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
declare variable CUSTOMER VARCHAR(6);
declare variable BANK VARCHAR(4);
declare variable TOTAL DOUBLE PRECISION;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 /*  Debit : BANK                                                             */
 /*          Credit : A/R Clearance                                           */
 /* ------------------------------------------------------------------------- */
 IF ((NUMBER IS NULL) OR (NUMBER = 0)) THEN NUMBER = 2;

 SELECT D.DOCUMENT, D.CUSTOMER, D.RECONCILEDATE, D.TOTAL,  D.BANK
 FROM ARDEPOS0 D WHERE D.NUMBER = :NUMBER
 INTO REF, CUSTOMER, TRANSDATE, TOTAL, BANK;
 RELATION_CODE = :CUSTOMER;

 SELECT NAME, RELATION_DOCTYPE FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER
 INTO NOTE, RELATION_DOCTYPE;
 /* --------------------------------------------------------------------------*/
 /* CLEARANCE                                                                 */
 /* --------------------------------------------------------------------------*/
 select gl_account, gl_dept, gl_cost
 from sysbank where bank = :bank
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 APPLICATION = 'AR';
 SOURCE = 'DREC';
 INFO = 'Bank';
 ID = 1;
 DEBIT = TOTAL;
 CREDIT = 0;
 SETUP_INFO = 'SYSBANK';
 SETUP_DATA = BANK;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
 /* --------------------------------------------------------------------------*/
 /* CLEARANCE                                                                 */
 /* --------------------------------------------------------------------------*/
 select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare
 from sysbank where bank = :bank
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 INFO = 'Clearance';
 ID = 2;
 DEBIT = 0;
 CREDIT = TOTAL;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_DEPOSIT_RELEASE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
declare variable CUSTOMER VARCHAR(6);
declare variable BANK VARCHAR(4);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
declare variable vName VARCHAR(40);
declare variable TOTAL DOUBLE PRECISION;
DECLARE VARIABLE CREDITCARD VARCHAR(6);
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Clearance from System Parameter                              */
 /*          Credit : A/R From Customer/Customer Type                         */
 /*          Credit : Gain & Loss Currency Exchange JIKA ADA                  */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM ARDEPOS0 INTO NUMBER;

 SELECT DOCUMENT, CUSTOMER, OPENDATE, TOTAL,  BANK, CREDITCARD
 FROM ARDEPOS0 WHERE NUMBER = :NUMBER
 INTO REF, CUSTOMER, TRANSDATE, TOTAL, BANK, CREDITCARD;
 RELATION_CODE = :CUSTOMER;
 
 SELECT RELATION_DOCTYPE FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER
 INTO RELATION_DOCTYPE;
    
 IF (EXISTS(SELECT * FROM SYSBANK WHERE BANK = :BANK)) THEN
 BEGIN
    select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare, BANKNAME
    from sysbank where bank = :bank
    into GL_ACCOUNT, GL_DEPT, GL_COST, vName;

    APPLICATION = 'AR';
    SOURCE = 'DEP0';
    INFO = 'Clearance';
    ID = 1;
    NOTE = vName;
    DEBIT = TOTAL;
    CREDIT = 0;
    SETUP_INFO = 'SYSBANK';
    SETUP_DATA = BANK;
 END
 ELSE
 BEGIN
    select GL_AR_ACCOUNT, GL_AR_DEPT, GL_AR_COST, NAME
    from AR_CARD where CREDITCARD = :CREDITCARD
    into GL_ACCOUNT, GL_DEPT, GL_COST, vName;
    
    APPLICATION = 'AR';
    SOURCE = 'DEP0';
    INFO = 'Credit Card';
    ID = 1;
    NOTE = vName;
    DEBIT = TOTAL;
    CREDIT = 0;
    SETUP_INFO = 'AR_CARD';
    SETUP_DATA = CREDITCARD;
 END
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR                                                        */
 /* ------------------------------------------------------------------- */
 select name, custtype from SYSCUSTOMER
 where CUSTOMER = :CUSTOMER
 into :vname, custtype;
 /* find customer a/r account */
 select depos_glaccount, depos_gldept, DEPOS_GLCOST FROM SYSCUSTOMERTYPE
 WHERE CUSTOMERTYPE = :CUSTTYPE
 into GL_ACCOUNT, GL_DEPT, GL_COST;

 if ((GL_DEPT is null) or (GL_DEPT = '')) then GL_DEPT = '0000';
 if ((GL_COST is null) or (GL_COST = '')) then GL_COST = '0000';
    
 APPLICATION = 'AR';
 SOURCE = 'DEP0';
 INFO = 'Deposit';
 ID = 2;
 NOTE = vName;
 DEBIT = 0;
 CREDIT = TOTAL;
 SETUP_INFO = 'CUSTOMER_TYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_RECREATE_ALL(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER,
    USERID VARCHAR(8))
RETURNS (
    NUMBER INTEGER,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
/* 21 JULI 2006 */
DECLARE VARIABLE AR_INVOICE_USE_BATCH INTEGER;
/* 11 JULY 2007, FIXED AR_CARD_BATCH DOUBLE NUMBER */
DECLARE VARIABLE COUNTER INTEGER;
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE OUTLET VARCHAR(4);
DECLARE VARIABLE BATCH INTEGER;
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE XNUMBER INTEGER;
begin
  IF (SDATE IS NULL) THEN
  BEGIN
     SELECT ARSYSDATE FROM FOSYSPARAM INTO EDATE;
     SDATE = '1.7.2005'; EDATE = '31.7.2005';
     PSAVE = 0;
  END
  /* ---------------------------------------------------------------- */
  /* 11 JULY 2007                                                     */
  /* FIXED AR_CARD_BATCH DOUBLE NUMBER OR ZERO NUMBER OR NULL         */
  /* ---------------------------------------------------------------- */
  /* ---------------------------------------------------------------- */
  /* BATCH DGN NUMBER SAMA                                            */
  /* ---------------------------------------------------------------- */
  FOR
    SELECT NUMBER, COUNT(*)
           FROM AR_CARD_BATCH
           WHERE OPENDATE BETWEEN :SDATE AND :EDATE
           GROUP BY NUMBER
           HAVING COUNT(*) > 1
    INTO
      :NUMBER,
      :COUNTER
  DO
  BEGIN
    /* ---------------------------------------------------------------- */
    /* CARI PRIMARY KEY NYA                                             */
    /* ---------------------------------------------------------------- */
    I = COUNTER-1;
    FOR SELECT BANK, OUTLET, BATCH FROM AR_CARD_BATCH
        WHERE NUMBER = :NUMBER
        ORDER BY OPENDATE DESC
        INTO BANK, OUTLET, BATCH
    DO
    BEGIN
      /* ---------------------------------------------------------------- */
      /* RENUMBER                                                         */
      /* ---------------------------------------------------------------- */
      IF (I > 0) THEN
      BEGIN
         I = I - 1;
         /* ---------------------------------------------------------------- */
         /* GET NEW MAXIMUM NUMBER                                           */
         /* ---------------------------------------------------------------- */
         SELECT MAX(NUMBER) FROM AR_CARD_BATCH
         INTO XNUMBER;
         IF (XNUMBER IS NULL) THEN XNUMBER = 0;
         XNUMBER = XNUMBER + 1;


         /* ---------------------------------------------------------------- */
         /* UPDATE NEW NUMBER                                                */
         /* ---------------------------------------------------------------- */
         UPDATE AR_CARD_BATCH SET NUMBER=:XNUMBER
         WHERE BANK = :BANK
         AND OUTLET=:OUTLET
         AND BATCH = :BATCH;

      END
    END
  END
  /* ---------------------------------------------------------------- */
  /* FILL NUMBER IF BATCH NUMBER IS NULL OR ZERRO                     */
  /* ---------------------------------------------------------------- */
  FOR SELECT BANK, OUTLET, BATCH FROM AR_CARD_BATCH
      WHERE (NUMBER = 0) OR (NUMBER IS NULL)
      AND OPENDATE BETWEEN :SDATE AND :EDATE
      ORDER BY OPENDATE DESC
      INTO BANK, OUTLET, BATCH
  DO
  BEGIN
    /* ---------------------------------------------------------------- */
    /* RENUMBER                                                         */
    /* ---------------------------------------------------------------- */
    IF (I > 0) THEN
    BEGIN
       I = I - 1;
       /* ---------------------------------------------------------------- */
       /* GET NEW MAXIMUM NUMBER                                           */
       /* ---------------------------------------------------------------- */
       SELECT MAX(NUMBER) FROM AR_CARD_BATCH
       INTO XNUMBER;
       IF (XNUMBER IS NULL) THEN XNUMBER = 0;
       XNUMBER = XNUMBER + 1;

       /* ---------------------------------------------------------------- */
       /* UPDATE NEW NUMBER                                                */
       /* ---------------------------------------------------------------- */
       UPDATE AR_CARD_BATCH SET NUMBER=:XNUMBER
       WHERE BANK = :BANK
       AND OUTLET=:OUTLET
       AND BATCH = :BATCH;
     END
  END
  /* ---------------------------------------------------------------- */
  /* 11 JULY 2007, END                                                */
  /* ---------------------------------------------------------------- */















  /* ---------------------------------------------------------------- */
  /* START ORIGINAL                                                   */
  /* ---------------------------------------------------------------- */
  IF (PSAVE = 1) THEN
  BEGIN
     DELETE FROM GLBUFFER WHERE APPLICATION = 'AR'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
  END
  /* ---------------------------------------------------------------- */
  /* 21 JULI 2006                                                     */
  /* TRANSIENT KALAU PAKAI BATCH TANGGAL TRANSAKSI TIDAK SAMA         */
  /* DENGAN TANGGAL INVOICE DIBUAT                                    */
  /* ---------------------------------------------------------------- */
  SELECT AR_INVOICE_USE_BATCH FROM FOSYSPARAM INTO AR_INVOICE_USE_BATCH;

  IF (AR_INVOICE_USE_BATCH IS NULL) THEN AR_INVOICE_USE_BATCH = 0;
  /* ---------------------------------------------------------------- */
  /* KALAU BATCH ACTIVE TAPI BATCH ISI NYA KOSONG                     */
  /* MAKA DIANGGAP TANPA BATCH                                        */
  /* ---------------------------------------------------------------- */
  IF ((AR_INVOICE_USE_BATCH = 1) AND
      (NOT EXISTS(SELECT * FROM ARVCH_BATCH WHERE OPENDATE BETWEEN :SDATE AND :EDATE))) THEN
  BEGIN
     AR_INVOICE_USE_BATCH = 0;
  END
  /* ------------------------------------------------------------------------ */
  /* VOUCHER - TANPA ADA BATCH, 21 JULI 2006                                  */
  /* ------------------------------------------------------------------------ */
  /*IF (AR_INVOICE_USE_BATCH = 0) THEN*/
  BEGIN
     FOR SELECT NUMBER FROM ARVCH
        WHERE OPENDATE BETWEEN :SDATE AND :EDATE
        AND GLSTATUS IN ('C','R')
        ORDER BY NUMBER
        INTO NUMBER
     DO
     BEGIN
        FOR SELECT APPLICATION, SOURCE, INFO, TRANSDATE, ID,
                  GL_ACCOUNT, GL_DEPT, GL_COST,
                  ACCNAME, NOTE, REF,
                  DEBIT, CREDIT,
                  SETUP_INFO, SETUP_DATA, ERROR_TEXT,
                  RELATION_CODE, RELATION_DOCTYPE
            FROM AR_GLBUFFER_VCH_EOD(:NUMBER)
       INTO APPLICATION, SOURCE, INFO, TRANSDATE, ID,
            GL_ACCOUNT, GL_DEPT, GL_COST,
            ACCNAME, NOTE, REF,
            DEBIT, CREDIT,
            SETUP_INFO, SETUP_DATA, ERROR_TEXT,
            RELATION_CODE, RELATION_DOCTYPE
       DO
       BEGIN
         IF (PSAVE = 1) THEN
         BEGIN
          insert into glbuffer
                 (APPLICATION, SOURCE, NUMBER, ID, transdate,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
          values (:application,:source, :number, :ID, :transdate,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REF,
                  :DEBIT, :CREDIT,
                  'now', :USERID, :RELATION_CODE, :RELATION_DOCTYPE);
         END
         ELSE SUSPEND;
       END
     END
  END /* VOUCHER TANPA BATCH 21 JULI 2006 */
  /* ------------------------------------------------------------------------ */
  /* VOUCHER - DENGAN BATCH NUMBER 21 JULI 2006                               */
  /* ------------------------------------------------------------------------ */
  /*IF (AR_INVOICE_USE_BATCH = 1) THEN
  BEGIN
     FOR SELECT NUMBER FROM ARVCH_BATCH
        WHERE OPENDATE BETWEEN :SDATE AND :EDATE
        AND STATUS IN ('C', 'R')
        ORDER BY NUMBER
        INTO NUMBER
     DO
     BEGIN
        FOR SELECT APPLICATION, SOURCE, INFO, TRANSDATE, ID,
                  GL_ACCOUNT, GL_DEPT, GL_COST,
                  ACCNAME, NOTE, REF,
                  DEBIT, CREDIT,
                  SETUP_INFO, SETUP_DATA, ERROR_TEXT,
                  RELATION_CODE, RELATION_DOCTYPE
              FROM AR_GLBUFFER_BATCH_RELEASE(:NUMBER)
         INTO APPLICATION, SOURCE, INFO, TRANSDATE, ID,
              GL_ACCOUNT, GL_DEPT, GL_COST,
              ACCNAME, NOTE, REF,
              DEBIT, CREDIT,
              SETUP_INFO, SETUP_DATA, ERROR_TEXT,
              RELATION_CODE, RELATION_DOCTYPE
         DO
         BEGIN
           IF (PSAVE = 1) THEN
           BEGIN
            insert into glbuffer
                   (APPLICATION, SOURCE, NUMBER, ID, transdate,
                    ACCOUNT, DEPT, COST, PROJECT,
                    NOTE, REF,
                    DB, CR,
                    EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
            values (:application,:source, :number, :ID, :transdate,
                    :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                    :NOTE, :REF,
                    :DEBIT, :CREDIT,
                    'now', :USERID, :RELATION_CODE, :RELATION_DOCTYPE);
           END
           ELSE SUSPEND;
       END
     END
  END*/ /* VOUCHER WITH BATCH NUMBER, 21 JULI 2006 */
  /* ---------------------------------------------------------------- */
  /* 1 AGUSTUS 2007                                                   */
  /* AR-VCH-DETAIL ADJUSTMENT EOD                                     */
  /* ---------------------------------------------------------------- */
  FOR SELECT FO_TRANS_ID FROM ARVCH_DETAIL
      WHERE FODATE BETWEEN :SDATE AND :EDATE
      AND SOURCE = 'A'
      AND STATUS = 'C'
      ORDER BY FO_TRANS_ID
      INTO NUMBER
   DO
   BEGIN
      FOR SELECT APPLICATION, SOURCE, INFO, TRANSDATE, ID,
                GL_ACCOUNT, GL_DEPT, GL_COST,
                ACCNAME, NOTE, REF,
                DEBIT, CREDIT,
                SETUP_INFO, SETUP_DATA, ERROR_TEXT,
                RELATION_CODE, RELATION_DOCTYPE
          FROM AR_GLBUFFER_VCH_EOD_DETAIL(:NUMBER)
     INTO APPLICATION, SOURCE, INFO, TRANSDATE, ID,
          GL_ACCOUNT, GL_DEPT, GL_COST,
          ACCNAME, NOTE, REF,
          DEBIT, CREDIT,
          SETUP_INFO, SETUP_DATA, ERROR_TEXT,
          RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
       IF (PSAVE = 1) THEN
       BEGIN
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER, RELATION_CODE, RELATION_DOCTYPE)
        values (:application,:source, :number, :ID, :transdate,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :NOTE, :REF,
                :DEBIT, :CREDIT,
                'now', :USERID, :RELATION_CODE, :RELATION_DOCTYPE);
       END
       ELSE SUSPEND;
     END
  END
  /* ---------------------------------------------------------------- */
  /* END OF 1 AGUSTUS 2007                                            */
  /* ---------------------------------------------------------------- */




  /* ------------------------------------------------------------------------ */
  /* ADJUSTMENT                                                               */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM ARADJ
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND STATUS IN ('R','C')
      ORDER BY NUMBER
      INTO NUMBER
  DO
  BEGIN
     FOR SELECT APPLICATION, SOURCE, INFO, TRANSDATE, ID,
                GL_ACCOUNT, GL_DEPT, GL_COST,
                ACCNAME, NOTE, REF,
                DEBIT, CREDIT,
