       END
       ELSE SUSPEND;
     END
  END






  /* ------------------------------------------------------------------------ */
  /* CASH RELEASE                                                             */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM ARCASH0
      WHERE DUEDATE BETWEEN :SDATE AND :EDATE /* TADINYA JADI DUEDATE, 31 OCT 2008, 22 NOV BALIK KE DUEDATE  */
      AND STATUS IN ('R','C','L')
