ALTER PROCEDURE AR_GLBUFFER_RECREATE_BANKBOOK(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER,
    USERID VARCHAR(8))
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    BBDATE DATE,
    NUMBER INTEGER,
    BANK VARCHAR(4),
    BBLINE INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    SOURCEID INTEGER)
AS
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.8.2005'; EDATE = '31.8.2005';
     PSAVE = 1;
  END
  IF (PSAVE = 1) THEN
  BEGIN
     DELETE FROM BBJUR WHERE APPLICATION = 'AR'
     AND BBDATE BETWEEN :SDATE AND :EDATE;
  END
  /* ------------------------------------------------------------------------ */
  /* CASH RECEIPT                                                             */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM ARCASH0
      WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
      AND STATUS = 'C'
      ORDER BY NUMBER
      INTO NUMBER
  DO
  FOR
    SELECT  BANK,
      BBDATE,
      BBLINE,
      STATUS,
      DOCUMENT,
      BBCODE,
      ACCOUNT,
      DEPT,
      COST,
      FOREX_DB,
      FOREX_CR,
      REMARK,
      REF,
      CURRENCY,
      EXCHANGE,
      APPLICATION,
      SOURCE,
      SOURCENUMBER,
      SOURCEID FROM AR_GLBUFFER_CASH_BANKBOOK(:NUMBER)

    INTO BANK,
      BBDATE,
      BBLINE,
      STATUS,
      DOCUMENT,
      BBCODE,
      ACCOUNT,
      DEPT,
      COST,
      FOREX_DB,
      FOREX_CR,
      REMARK,
      REF,
      CURRENCY,
      EXCHANGE,
      APPLICATION,
      SOURCE,
      SOURCENUMBER,
      SOURCEID

  DO
  BEGIN
    IF (PSAVE = 1) THEN
    BEGIN
      INSERT INTO BBJUR (BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
             BBCODE, ACCOUNT, DEPT, COST, FOREX_DB, FOREX_CR,
             REMARK, REF, CURRENCY, EXCHANGE, APPLICATION, SOURCE,
             SOURCENUMBER, SOURCEID)
      VALUES (:BANK, :BBDATE, :BBLINE, :STATUS, :DOCUMENT,
             :BBCODE, :ACCOUNT, :DEPT, :COST, :FOREX_DB, :FOREX_CR,
             :REMARK, :REF, :CURRENCY, :EXCHANGE, :APPLICATION, :SOURCE,
             :SOURCENUMBER, :SOURCEID);
    END
    ELSE SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* DEPOSIT                                                                  */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM ARDEPOS0
      WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
      AND STATUS = 'C'
      ORDER BY NUMBER
      INTO NUMBER
  DO
  FOR
    SELECT  BANK,
      BBDATE,
      BBLINE,
      STATUS,
      DOCUMENT,
      BBCODE,
      ACCOUNT,
      DEPT,
      COST,
      FOREX_DB,
      FOREX_CR,
      REMARK,
      REF,
      CURRENCY,
      EXCHANGE,
      APPLICATION,
      SOURCE,
      SOURCENUMBER,
      SOURCEID FROM AR_GLBUFFER_DEPOSIT_BANKBOOK(:NUMBER)
    INTO BANK,
      BBDATE,
      BBLINE,
      STATUS,
      DOCUMENT,
      BBCODE,
      ACCOUNT,
      DEPT,
      COST,
      FOREX_DB,
      FOREX_CR,
      REMARK,
      REF,
      CURRENCY,
      EXCHANGE,
      APPLICATION,
      SOURCE,
      SOURCENUMBER,
      SOURCEID

  DO
  BEGIN
    IF (PSAVE = 1) THEN
    BEGIN
      INSERT INTO BBJUR (BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
             BBCODE, ACCOUNT, DEPT, COST, FOREX_DB, FOREX_CR,
             REMARK, REF, CURRENCY, EXCHANGE, APPLICATION, SOURCE,
             SOURCENUMBER, SOURCEID)
      VALUES (:BANK, :BBDATE, :BBLINE, :STATUS, :DOCUMENT,
             :BBCODE, :ACCOUNT, :DEPT, :COST, :FOREX_DB, :FOREX_CR,
             :REMARK, :REF, :CURRENCY, :EXCHANGE, :APPLICATION, :SOURCE,
             :SOURCENUMBER, :SOURCEID);
    END
    ELSE SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* CREDIT CARD RECONCILE                                                    */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM AR_CARD_BATCH
      WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
      AND STATUS = 'C'
      ORDER BY NUMBER
      INTO NUMBER
  DO
  FOR
    SELECT  BANK,
      BBDATE,
      BBLINE,
      STATUS,
      DOCUMENT,
      BBCODE,
      ACCOUNT,
      DEPT,
      COST,
      FOREX_DB,
      FOREX_CR,
      REMARK,
      REF,
      CURRENCY,
      EXCHANGE,
      APPLICATION,
      SOURCE,
      SOURCENUMBER,
      SOURCEID FROM AR_GLBUFFER_CC_BATCH_BANKBOOK(:NUMBER)
    INTO BANK,
      BBDATE,
      BBLINE,
      STATUS,
      DOCUMENT,
      BBCODE,
      ACCOUNT,
      DEPT,
      COST,
      FOREX_DB,
      FOREX_CR,
      REMARK,
      REF,
      CURRENCY,
      EXCHANGE,
      APPLICATION,
      SOURCE,
      SOURCENUMBER,
      SOURCEID

  DO
  BEGIN
    IF (PSAVE = 1) THEN
    BEGIN
      INSERT INTO BBJUR (BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
             BBCODE, ACCOUNT, DEPT, COST, FOREX_DB, FOREX_CR,
             REMARK, REF, CURRENCY, EXCHANGE, APPLICATION, SOURCE,
             SOURCENUMBER, SOURCEID)
      VALUES (:BANK, :BBDATE, :BBLINE, :STATUS, :DOCUMENT,
             :BBCODE, :ACCOUNT, :DEPT, :COST, :FOREX_DB, :FOREX_CR,
             :REMARK, :REF, :CURRENCY, :EXCHANGE, :APPLICATION, :SOURCE,
             :SOURCENUMBER, :SOURCEID);
    END
    ELSE SUSPEND;
  END
END^


ALTER PROCEDURE AR_GLBUFFER_VCH_EOD(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
DECLARE VARIABLE VNAME VARCHAR(40);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT END OF DAY PROCESS                                       */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Account from Customer Type                                   */
 /*          Credit : A/R Transient from Parameter Setup                      */
 /* ------------------------------------------------------------------------- */
 /*  A/R Transient digunakan juga di Income dgn journal                       */
 /*           A/R Transient | Guest Ledger                                    */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM ARVCH INTO NUMBER;

 SELECT DOCUMENT, CUSTOMER, OPENDATE, TOTAL FROM ARVCH WHERE NUMBER = :NUMBER
 INTO REF, CUSTOMER, TRANSDATE, TOTAL;
 /* ------------------------------------------------------------------- */
 /* CUSTOMER NAME, ACCOUNT                                              */
 /* ------------------------------------------------------------------- */
 select C.name, C.custtype, C.account, C.gl_dept, C.gl_cost,
        C.relation_doctype, COA.NAME
 from SYSCUSTOMER C
 LEFT JOIN GLCOA COA ON COA.ACCOUNT = C.ACCOUNT    
 where CUSTOMER = :CUSTOMER
 into :vname, custtype, GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE, ACCNAME;
 RELATION_CODE = CUSTOMER;
 IF (RELATION_DOCTYPE IS NULL) THEN RELATION_DOCTYPE = 0;
 /* find customer a/r account */
/* if ((GL_ACCOUNT is Null) or (GL_ACCOUNT = '')) then
 BEGIN*/
    select T.glaccount, T.gldept, T.glcost, COA.NAME
    FROM SYSCUSTOMERTYPE T
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
    WHERE CUSTOMERTYPE = :CUSTTYPE
    into GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
/* END*/
    
 APPLICATION = 'AR';
 SOURCE = 'VCH';
 INFO = 'A/R';
 ID = 1;
 NOTE = vName;
 DEBIT = TOTAL;
 CREDIT = 0;
 SETUP_INFO = 'CUSTOMER_TYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* a/r transient                                                       */
 /* ------------------------------------------------------------------- */
 select  CFG.ARVCH_TRANSIENT_ACC, CFG.ARVCH_TRANSIENT_DEPT,
         CFG.ARVCH_TRANSIENT_COST, COA.NAME
 from FOSYSPARAM CFG
 LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.ARVCH_TRANSIENT_ACC
 into GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
    
 INFO = 'Transient';
 ID = 2;
 DEBIT = 0;
 CREDIT = TOTAL;
 SETUP_INFO = 'SYSPARAM';
 SETUP_DATA = '';
 SUSPEND;
end^


ALTER PROCEDURE AR_GLBUFFER_VCH_EOD_DETAIL(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE CUSTTYPE VARCHAR(4);
DECLARE VARIABLE VNAME VARCHAR(40);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT END OF DAY PROCESS                                       */
 /* ------------------------------------------------------------------------- */
 /*  Debit : A/R Account from Customer Type                                   */
 /*          Credit : A/R Transient from Parameter Setup                      */
 /* ------------------------------------------------------------------------- */
 /*  A/R Transient digunakan juga di Income dgn journal                       */
 /*           A/R Transient | Guest Ledger                                    */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(FO_TRANS_ID) FROM ARVCH_DETAIL INTO NUMBER;
 
 SELECT V.CUSTOMER, D.FODATE, D.DEBIT-D.CREDIT FROM ARVCH_DETAIL D
 LEFT JOIN ARVCH V ON V.NUMBER = D.NUMBER
 WHERE D.FO_TRANS_ID = :NUMBER
 INTO CUSTOMER, TRANSDATE, TOTAL;
 REF = '';

 /* ------------------------------------------------------------------- */
 /* CUSTOMER NAME, ACCOUNT                                              */
 /* ------------------------------------------------------------------- */
 select C.name, C.custtype, C.account, C.gl_dept, C.gl_cost,
        C.relation_doctype, COA.NAME
 from SYSCUSTOMER C
 LEFT JOIN GLCOA COA ON COA.ACCOUNT = C.ACCOUNT    
 where CUSTOMER = :CUSTOMER
 into :vname, custtype, GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE, ACCNAME;
 
 
 RELATION_CODE = CUSTOMER;
 IF (RELATION_DOCTYPE IS NULL) THEN RELATION_DOCTYPE = 0;
 
 
 
 /* find customer a/r account */

    SELECT T.GLACCOUNT, T.GLDEPT, T.GLCOST, COA.NAME
    FROM SYSCUSTOMERTYPE T
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
    WHERE CUSTOMERTYPE = :CUSTTYPE
    INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
    
 APPLICATION = 'AR';
 SOURCE = 'VCHD';
 INFO = 'B/O Adjustment';
 ID = 1;
 NOTE = vName;
 DEBIT = TOTAL;
 CREDIT = 0;
 SETUP_INFO = 'CUSTOMER_TYPE';
 SETUP_DATA = CUSTTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* a/r transient                                                       */
 /* ------------------------------------------------------------------- */
 select  CFG.ARVCH_TRANSIENT_ACC, CFG.ARVCH_TRANSIENT_DEPT,
         CFG.ARVCH_TRANSIENT_COST, COA.NAME
 from FOSYSPARAM CFG
 LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.ARVCH_TRANSIENT_ACC
 into GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
    
 INFO = 'Transient';
 ID = 2;
 DEBIT = 0;
 CREDIT = TOTAL;
 SETUP_INFO = 'SYSPARAM';
 SETUP_DATA = '';
 SUSPEND;
end^


ALTER PROCEDURE AR_JOURNAL(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    SEQUENCE INTEGER,
    NUMBER INTEGER,
    VOUCHERNO INTEGER,
    DOCTYPE VARCHAR(6),
    OPENDATE DATE,
    DOCUMENT VARCHAR(20),
    TEXT1 VARCHAR(30),
    VOUCHER NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
/* 20-SEP-2005 */
DECLARE VARIABLE CALC_NET DOUBLE PRECISION;
DECLARE VARIABLE CALC_FEE DOUBLE PRECISION;
DECLARE VARIABLE PAY_DATE DATE;
DECLARE VARIABLE BATCH_NUMBER INTEGER;
/* 23 - SEP - 2005 */
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE OUTLET VARCHAR(4);
DECLARE VARIABLE BATCH INTEGER;
begin
  if (scustomer is null) then
  begin
     scustomer = 'VS-P';
     ecustomer = 'VS-P';
     sdate = '01.01.2001';
     edate = '30.12.2005';
  end


  FOR SELECT CUSTOMER, NAME FROM SYSCUSTOMER
  WHERE CUSTOMER BETWEEN :SCUSTOMER AND :ECUSTOMER
  INTO :CUSTOMER, :NAME
  do
  begin
    DocType = 'Pre';
    Document = 'Previous Balance';
    OpenDate = sDate;
    sequence = 0;
    Number = 0;
    VoucherNo = 0;
    select sum(total) from ARvch where CUSTOMER = :CUSTOMER and opendate < :sDate
      into :Voucher;
    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER and DueDate < :sDate
      into cash;
    select sum(db-cr) from ARadj where CUSTOMER = :CUSTOMER and opendate < :sDate
      into :Adjust;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    total = voucher - cash - adjust;
    if (voucher + cash + adjust <> 0) then suspend;
  for
    select ARvch.number, (CAST('Vch' AS VARCHAR(6))) DocType,
           ARvch.Number VoucherNo,
           opendate,
           document,
           total voucher,
           cast(0 as numeric(15,4)) cash,
           cast(0 as numeric(15,4)) adjust,
           total
      from ARvch
      where CUSTOMER = :CUSTOMER and opendate between :sDate and :eDate
    union
    select ARcash1.number, CAST('Cash' AS VARCHAR(6)),
           ARcash1.voucherno,
           ARcash0.DueDate,
           ARcash0.document,
           cast(0 as numeric(15,4)) voucher,
           ARcash1.total+ARcash1.VCH_GAINLOSS cash,
           cast(0 as numeric(15,4)) adjust,
           -ARcash1.total+ARcash1.VCH_GAINLOSS total
       from ARcash1
      left join ARcash0 on ARcash0.number = ARcash1.number
       where ARcash0.CUSTOMER = :CUSTOMER and ARcash0.DueDate between :sDate and :eDate
     union
     select number,  CAST('Adj' AS VARCHAR(6)),
            voucherno,
            opendate,
            document,
            cast(0 as numeric(15,4)) voucher,
            cast(0 as numeric(15,4)) cash,
            (db-cr) adjust,
            (db-cr)
        from ARadj
       where CUSTOMER = :CUSTOMER and opendate between :sDate and :eDate
    union
     select number,  CAST('Dep' AS VARCHAR(6)),
            voucherno,
            APPlieddate,
            CAST('' AS VARCHAR(20)),
            -total,
            cast(0 as numeric(15,4)),
            cast(0 as numeric(15,4)),
            -total
        from ARdepos1
       where CUSTOMER = :CUSTOMER and APPlieddate between :sDate and :eDate
    into NUMBER, DOCTYPE, VOUCHERNO, OPENDATE, DOCUMENT, VOUCHER, CASH, ADJUST, TOTAL
    DO
    BEGIN
      SUSPEND;
      sequence = number;
      if (doctype = 'Vch') then sequence = 0;
    END
  end
  /* credit card */
  FOR SELECT CREDITCARD, NAME  FROM AR_CARD
  WHERE CREDITCARD BETWEEN :SCUSTOMER AND :ECUSTOMER
  INTO :CUSTOMER, :NAME
  do
  begin
     DocType = 'Pre';
     Document = 'Previous Balance';
     OpenDate = sDate;
     sequence = 0;
     Number = 0;
     VoucherNo = 0;
     SELECT SUM(TOTAL) FROM AR_CARD_JUR WHERE CREDITCARD = :CUSTOMER AND OPENDATE < :SDATE
       INTO :VOUCHER;
     SELECT SUM(TOTAL) FROM AR_CARD_JUR WHERE CREDITCARD = :CUSTOMER AND PAY_DATE < :SDATE
       AND (PAY_DATE IS NOT NULL)
       INTO CASH;

     IF (VOUCHER IS NULL) THEN VOUCHER = 0;
     IF (CASH    IS NULL) THEN CASH    = 0;
     IF (ADJUST  IS NULL) THEN ADJUST  = 0;
     TOTAL = VOUCHER - CASH - ADJUST;
     IF (VOUCHER + CASH + ADJUST <> 0) THEN SUSPEND;
     FOR
       SELECT AR_CARD_JUR.NUMBER,
           OPENDATE,
           SUBSTR(CARDNUMBER, 1, 20),
           TOTAL,
           CAST(0 AS NUMERIC(15,4)),
           CAST(0 AS NUMERIC(15,4)),
           TOTAL,
           CALC_NET,
           CALC_FEE,
           PAY_DATE,
           BATCH_NUMBER,
           OUTLET, BANK, BATCH
      FROM AR_CARD_JUR
      WHERE CREDITCARD = :CUSTOMER AND OPENDATE BETWEEN :SDATE AND :EDATE
      ORDER BY OPENDATE, NUMBER
     INTO NUMBER, OPENDATE, DOCUMENT, VOUCHER, CASH, ADJUST, TOTAL,
          CALC_NET, CALC_FEE, PAY_DATE, BATCH_NUMBER, OUTLET, BANK, BATCH
     DO
     BEGIN
       DOCTYPE = 'Card';
       VOUCHERNO = NUMBER;
       sequence = 0;
       SUSPEND;
       sequence = 1;
       SELECT PAY_DATE FROM AR_CARD_BATCH WHERE BANK = :BANK AND OUTLET = :OUTLET AND BATCH = :BATCH
       INTO PAY_DATE;
       IF (PAY_DATE IS NOT NULL) THEN
       BEGIN
          IF (PAY_DATE BETWEEN SDATE AND EDATE) THEN
          BEGIN
             DocType = 'Batch';
             VOUCHER = 0;
             CASH = CALC_NET;
             ADJUST = CALC_FEE;
             TOTAL = -TOTAL;
             NUMBER = BATCH_NUMBER;
             OPENDATE = PAY_DATE;
             SUSPEND;
          END
       END
     END
  end
end^


ALTER PROCEDURE AR_JOURNAL_CARD(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    SDATE DATE,
    EDATE DATE,
    FLAG_OPENONLY INTEGER)
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    SEQUENCE INTEGER,
    NUMBER INTEGER,
    VOUCHERNO INTEGER,
    DOCTYPE VARCHAR(6),
    OPENDATE DATE,
    DOCUMENT VARCHAR(20),
    TEXT1 VARCHAR(30),
    VOUCHER NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
/* 20-SEP-2005 */
DECLARE VARIABLE CALC_NET DOUBLE PRECISION;
DECLARE VARIABLE CALC_FEE DOUBLE PRECISION;
DECLARE VARIABLE PAY_DATE DATE;
DECLARE VARIABLE BATCH_NUMBER INTEGER;
begin
   for select CREDITCARD,NAME  from ar_card
   where CREDITCARD between :sCUSTOMER and :eCUSTOMER
   into :CUSTOMER,:name
   do
   begin
     DocType = 'Pre';
     Document = 'Previous Balance';
     OpenDate = sDate;
     sequence = 0;
     Number = 0;
     VoucherNo = 0;
     select sum(total) from AR_CARD_JUR where CREDITCARD = :CUSTOMER and opendate < :sDate
       into :Voucher;
     select sum(total) from AR_CARD_JUR where CREDITCARD = :CUSTOMER and Pay_Date < :sDate
       and (pay_date is not null)
       into cash;
    
     if (voucher is null) then voucher = 0;
     if (cash    is null) then cash    = 0;
     if (adjust  is null) then adjust  = 0;
     total = voucher - cash - adjust;
     if (voucher + cash + adjust <> 0) then suspend;
     for
       select number,(CAST('Card' AS VARCHAR(6))) DocType,
           Number VoucherNo,
           opendate,
           SUBSTR(CARDNUMBER,1,20),
           total,
           cast(0 as numeric(15,4)),
           cast(0 as numeric(15,4)),
           total,
           CALC_NET,
           CALC_FEE,
           PAY_DATE,
           BATCH_NUMBER
      from AR_CARD_JUR
      where CREDITCARD = :CUSTOMER and opendate between :sDate and :eDate
      ORDER BY OPENDATE,NUMBER
     into NUMBER,DOCTYPE,VOUCHERNO,OPENDATE,DOCUMENT,VOUCHER,CASH,ADJUST,TOTAL,
          CALC_NET,CALC_FEE,PAY_DATE,BATCH_NUMBER
     DO
     BEGIN
       SELECT PAY_DATE FROM AR_CARD_BATCH WHERE NUMBER = :BATCH_NUMBER
       INTO PAY_DATE;
       IF (FLAG_OPENONLY = 0) THEN
       BEGIN
          sequence = 0;
          SUSPEND;
          IF (PAY_DATE IS NOT NULL) THEN
          BEGIN
             IF (PAY_DATE BETWEEN SDATE AND EDATE) THEN
             BEGIN
                sequence = 1;
                DocType = 'Batch';
                VOUCHER = 0;
                CASH = CALC_NET;
                ADJUST = CALC_FEE;
                TOTAL = -TOTAL;
                NUMBER = BATCH_NUMBER;
                OPENDATE = PAY_DATE;
                SUSPEND;
             END
          END
       END
       ELSE
       BEGIN
          IF (PAY_DATE IS NULL) THEN
          BEGIN
             sequence = 0;
             SUSPEND;
          END
       END
     END
   end
end^


