end^


ALTER PROCEDURE AR_MUTATION(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6))
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    CUSTTYPE VARCHAR(4))
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE REFDATE DATE;
DECLARE VARIABLE PCASH DOUBLE PRECISION;
DECLARE VARIABLE ADJUST1 DOUBLE PRECISION;
DECLARE VARIABLE XNUMBER INTEGER;
DECLARE VARIABLE XADJUST DOUBLE PRECISION;
DECLARE VARIABLE XBANK VARCHAR(4);
DECLARE VARIABLE XOUTLET VARCHAR(4);
DECLARE VARIABLE XCASH DOUBLE PRECISION;
begin

  CREDITCARD = 0;
  select arsysdate from fosysparam into :REFDATE;

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'ZZZZZZ';
  END
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;

  for select CUSTOMER, name,CUSTTYPE from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung ending                                                          */
    /*========================================================================*/
    select sum(totaldue) from ARvch
     where PAIDSTATUS = 'O'
       AND CUSTOMER = :CUSTOMER
     PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
      into ending;
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    select SUM(TOTAL) from ARvch
     where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
       PLAN (ARVCH INDEX (ARVCH_IDX_OPENDATE))
      into :voucher;
      
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
       AND ARdepos1.STATUS IN ('R','C')
      into deposit;

    select sum(total-ADJ_TOTAL) from ARcash0 where CUSTOMER = :CUSTOMER /* 1/3/2012 over paid*/
       and DueDate between :sDate and :eDate
       and status in ('C', 'R','L')
       PLAN (ARCASH0 INDEX (ARCASH0_IDX_CUST_DUEDATE))
      into :cash;

    select sum(db-cr) from ARadj
      where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
       PLAN (ARADJ INDEX (ARADJ_IDX_OPENDATE))
      into :adjust1;
      
    /* 10-JAN-2003, SPEEDUP */
    adjust = 0;
    FOR SELECT NUMBER FROM arvch
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE >= :sDate 
        PLAN (ARVCH INDEX (ARVCH_IDX_OPENDATE))
    INTO XNUMBER DO
    BEGIN
      select sum(debit-credit) from ARVCH_DETAIL
      where NUMBER = :XNUMBER
      and source = 'A'
      and status = 'C'
      and FODATE between :sDate and :eDate
      PLAN (ARVCH_DETAIL INDEX (ARVCH_DETAIL_IDX_NO_SOURCE))   /* FB 2.1 No Alias */
      into xadjust;
      if (xadjust is not null) then
         adjust = adjust + xadjust;
    END
    /* END OF SPEED UP */

    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1 - deposit;
    opening = ending - voucher + cash - adjust;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;
  end
  adjust = 0;
  CREDITCARD = 1;
  CUSTTYPE = 'CARD';
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :ECUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    opening = 0;
    voucher = 0;
    cash = 0;
    ending = 0;
    /* ending */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and status = 'O'
    PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS))
    into :ending;
    
    /* new transaction */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and opendate between :SDATE and :EDATE
    PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_CUSTOMER))
    into :voucher;        
    
    /* opening */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and opendate < :sdate
    plan (ar_card_jur index (AR_CARD_JUR_IDX_CUSTOMER))
    into :opening;

    /* cash recipt */
    cash = 0;
    FOR SELECT BANK, OUTLET, BATCH
        FROM AR_CARD_BATCH
        WHERE pay_date between :SDATE and :EDATE
        AND ((STATUS = 'C') or (STATUS = 'R'))
        PLAN (ar_card_batch INDEX (AR_CARD_BATCH_IDX_PAYDATE))
        INTO XBANK, XOUTLET, XNUMBER
    DO BEGIN
       select sum(total) from ar_card_jur
       where (batch = :xnumber)
       and (creditcard = :customer)
       and (outlet=:xoutlet)
       and (bank=:xbank)
       PLAN (ar_card_jur INDEX (AR_CARD_JUR_IDX_BATCH)) /* no alias for FB 2.1 */
       into xcash;
       if (xcash is not null) then
          cash = cash + xcash;
    END

    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (deposit is null) then deposit = 0;
    if (pcash is not null) then opening=opening-pcash;    
    adjust = adjust - deposit;
    opening = ending - voucher + cash - adjust;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;    
  end
end^


ALTER PROCEDURE AR_MUTATION_OLD(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTTYPE VARCHAR(4),
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
declare variable xTotal DOUBLE PRECISION;
declare variable xPayDate DATE;
declare variable xOpenDate DATE;
declare variable xSisa DOUBLE PRECISION;

declare variable X DOUBLE PRECISION;
declare variable ARSYSDATE DATE;
declare variable AR_MONTH INTEGER;
declare variable AR_YEAR  INTEGER;

declare variable PMONTH INTEGER;
declare variable PYEAR  INTEGER;
begin
  SELECT ARSYSDATE,
         EXTRACT(MONTH FROM ARSYSDATE), EXTRACT(YEAR FROM ARSYSDATE)
  FROM FOSYSPARAM WHERE ID = 1
  INTO ARSYSDATE, AR_MONTH, AR_YEAR;


  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'ZZZZZZ';
     REFDATE = ARSYSDATE;
  /*   REFDATE = '01.11.2003';*/
  END

  PMONTH = EXTRACT(MONTH FROM REFDATE);
  PYEAR  = EXTRACT(YEAR  FROM REFDATE);

  /*
  Tambahan Agus, 20 January 2006
  Jika periode Bulan dari Refdate < Periode bulan di Current ARDate
  maka ar_zhist_mutation dihapus, Agar Mutation Historynya Otomatis Update
  ===========================================================*/
  /* Begin Update */
  IF ((REFDATE<=ARSYSDATE) and (PMONTH<>AR_MONTH)) Then
     Begin
       DELETE From ar_zhist_mutation
        WHERE PYEAR=PYEAR
          AND PMONTH=PMONTH ;
     END
  /* Ending Update */

  
  if (PYEAR*12+PMONTH >= AR_YEAR*12+AR_MONTH) then
  BEGIN
    FOR SELECT CREDITCARD, CUSTTYPE, CUSTOMER, NAME,
           OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    FROM ar_mutation_old_calc(:SCUSTOMER, :ECUSTOMER, :REFDATE)
    INTO CREDITCARD, CUSTTYPE, CUSTOMER, NAME,
         OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    DO
    BEGIN
      SUSPEND;
    END
    EXIT;
  END
  /* PERIKSA APAKAH ADA DI HISTORY */
  SELECT COUNT(*) FROM ar_zhist_mutation
  WHERE PYEAR  = :PYEAR
    AND PMONTH = :PMONTH
  INTO X;  
  /* JIKA DATA ADA DI HISTORY */
  if (X = 0) then
  BEGIN
    FOR SELECT CREDITCARD, CUSTOMER, NAME,
           OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    FROM ar_mutation_old_calc('', 'ZZZZZZ', :REFDATE)
    INTO CREDITCARD, CUSTOMER, NAME,
         OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    DO
    BEGIN
      INSERT INTO ar_zhist_mutation
        (PYEAR, PMONTH,
         CREDITCARD, CUSTOMER, NAME,
         OPENING, VOUCHER, DEPOSIT, CASH, ADJUST)
      VALUES
        (:PYEAR, :PMONTH,
         :CREDITCARD, :CUSTOMER, :NAME,
         :OPENING, :VOUCHER, :DEPOSIT, :CASH, :ADJUST);
    END
  END
  /* LOAD FROM HISTORY */
  FOR SELECT H.CREDITCARD, C.CUSTTYPE, H.CUSTOMER, H.NAME,
           H.OPENING, H.VOUCHER, H.DEPOSIT, H.CASH, H.ADJUST, H.ENDING
  FROM ar_zhist_mutation H
  LEFT JOIN syscustomer C ON C.CUSTOMER = H.CUSTOMER
  WHERE H.PYEAR = :PYEAR
  AND H.PMONTH = :PMONTH
  AND H.CUSTOMER BETWEEN :SCUSTOMER AND :ECUSTOMER
  INTO CREDITCARD, CUSTTYPE, CUSTOMER, NAME,
       OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
  DO
  BEGIN
     IF (CREDITCARD = 1) THEN CUSTTYPE = 'CARD';
     SUSPEND;
  END

end^


ALTER PROCEDURE AR_MUTATION_OLD_CALC(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    CUSTTYPE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4))
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE ADJUST1 DOUBLE PRECISION;
DECLARE VARIABLE XTOTAL DOUBLE PRECISION;
DECLARE VARIABLE XOPENDATE DATE;
DECLARE VARIABLE XPAYDATE DATE;
DECLARE VARIABLE XSISA DOUBLE PRECISION;
DECLARE VARIABLE BATCH INTEGER;
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE OUTLET VARCHAR(4);
begin

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = 'DINERS';
     eCUSTOMER = 'DINERS';
     REFDATE = '31.07.2005';
  END
  /*
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;
  */
  /* -------------------------------------------------------------------- */
  /* 15 MARET 2011                                                        */
  /* -------------------------------------------------------------------- */
  execute procedure SP_DATE_BOM (refdate) returning_values sDate;
  execute procedure SP_DATE_EOM (refdate) returning_values eDate;
  /*##########################################################################*/
  /* company                                                                  */
  /*##########################################################################*/
  CREDITCARD = 0;
  FOR SELECT C.CUSTOMER, C.NAME, C.CUSTTYPE,
             T.GLACCOUNT, T.GLDEPT, T.GLCOST
  FROM SYSCUSTOMER C
  LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
  WHERE CUSTOMER BETWEEN :SCUSTOMER AND :ECUSTOMER
  INTO :CUSTOMER, NAME, CUSTTYPE, GL_ACCOUNT, GL_DEPT, GL_COST
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung opening                                                         */
    /*========================================================================*/
    SELECT SUM(TOTAL) FROM ARVCH
     WHERE CUSTOMER = :CUSTOMER
       AND OPENDATE < :SDATE
     PLAN (ARVCH INDEX (ARVCH_IDX_CUSTOMER_OPENDATE))
      INTO VOUCHER;

    SELECT SUM(TOTAL-FOREX_GAINLOSS-ADJ_FOREX_TOTAL) FROM ARCASH0 /* 1/3/2012 over paid*/
     WHERE CUSTOMER = :CUSTOMER AND DUEDATE < :SDATE
       AND STATUS IN ('C', 'R', 'L')
      INTO CASH;

    SELECT SUM(ARDEPOS1.TOTAL) FROM ARDEPOS1
     WHERE ARDEPOS1.CUSTOMER = :CUSTOMER AND ARDEPOS1.APPLIEDDATE < :SDATE
       AND ARDEPOS1.STATUS IN ('R','C')
      INTO DEPOSIT;

    SELECT SUM(A.DB-A.CR)
      FROM ARADJ A
     WHERE A.CUSTOMER = :CUSTOMER
       AND A.OPENDATE < :SDATE /* 6/11/2011 TAMBAH STATUS & TIDAK PERLU ARVCH */
       AND STATUS IN ('R','C')
      INTO :ADJUST1;

    SELECT SUM(D.DEBIT-D.CREDIT) FROM ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER AND H.CUSTOMER = :CUSTOMER
    WHERE D.SOURCE = 'A' /* ADJUSTMENT */
      AND D.STATUS = 'C' /* CLOSE, POSTED */
    AND D.FODATE < :SDATE
    INTO ADJUST;

    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;

    opening = voucher - cash + adjust + adjust1 - deposit; /* 6/11/2011 MASUKAN DEPOSIT */
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    voucher = 0;
    cash    = 0;
    adjust  = 0;
    adjust1 = 0;
    deposit = 0;
    select SUM(TOTAL) from ARvch   where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
      into :voucher;

    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
       AND ARdepos1.status IN ('R','C')
      into deposit;

    select sum(total-forex_gainloss-ADJ_FOREX_TOTAL) /* 1/3/2011 over paid */
      from ARcash0 where CUSTOMER = :CUSTOMER
       and DueDate between :sDate and :eDate
       and status in ('C', 'R', 'L')
      into :cash;

    select sum(A.db-A.cr)
      from ARadj A
     where A.CUSTOMER = :CUSTOMER
       and A.OpenDate between :sDate and :eDate
       AND status IN ('R','C') /* 6/11/2011 TAMBAH STATUS & TIDAK PERLU ARVCH */
      into :adjust1;

    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER and H.CUSTOMER = :CUSTOMER
    where D.source = 'A' /* ADJUSTMENT */
    and D.status = 'C' /* CLOSE, POSTED */
    and D.FODATE between :sDate and :eDate
    into adjust;

    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1; /* 6/11/2011 TADINYA ADA DEPOSIT, DIPINDAH */
    ending = opening + voucher - cash + adjust - deposit;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0) or (deposit <> 0)) then /* 6/11/2011 TAMBAH DEPOSIT <> 0 */
       suspend;
  end
  /*##########################################################################*/
  /* credit card                                                              */
  /*##########################################################################*/
  adjust = 0;
  CREDITCARD = 1;
  CUSTTYPE = 'CARD';
  FOR SELECT CREDITCARD, NAME, GL_AR_ACCOUNT, GL_AR_DEPT, GL_AR_COST
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :ECUSTOMER
      INTO :CUSTOMER, :NAME, GL_ACCOUNT, GL_DEPT, GL_COST
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    opening = 0;
    voucher = 0;
    cash = 0;
    ending = 0;
    deposit = 0;
    FOR SELECT OPENDATE, TOTAL, PAY_DATE, BATCH, BANK, OUTLET
        FROM AR_CARD_JUR
        WHERE CREDITCARD = :customer
        AND OPENDATE <= :EDATE
        PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_CUSTOMER))  /* no alias for fb 2.1 */
        INTO xOpenDate, xTotal, xPayDate, BATCH, BANK, OUTLET
        DO BEGIN
           IF (xTotal IS NULL) THEN xTotal = 0;
           xSisa = xTotal;
           if (xOpenDate BETWEEN :SDATE AND :EDATE) then
              Voucher = Voucher + xTotal;
           XPayDate = NULL;
           SELECT PAY_DATE FROM AR_CARD_BATCH WHERE BANK = :BANK AND OUTLET = :OUTLET AND BATCH = :BATCH
           INTO xPayDate;

           IF (xPayDate > EDATE) THEN XPayDate = NULL;
           if (xPayDate is not null) then
           begin
              if (xPayDate BETWEEN :SDATE AND :EDATE) then
                 Cash = Cash + xTotal;
              if (xPayDate <= :edate) then xSisa = 0;
           end
           ending = ending + xSisa;
        END

    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    opening  =  ending - voucher + cash;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;
  end
end^


ALTER PROCEDURE AR_MUTATION_OPENING(
    CUSTOMER VARCHAR(6),
    REFDATE DATE)
RETURNS (
    NUMBER INTEGER,
    DOCUMENT VARCHAR(20),
    OPENDATE DATE,
    DUEDATE DATE,
    STATUS CHAR(1),
    SOURCE VARCHAR(4),
    FO_FOLIO INTEGER,
    FO_GUESTNAME VARCHAR(80),
    TOTAL DOUBLE PRECISION)
AS
DECLARE VARIABLE ADJ DOUBLE PRECISION;
DECLARE VARIABLE PAID DOUBLE PRECISION;
DECLARE VARIABLE DEPOSIT DOUBLE PRECISION;
BEGIN
  /* ---------------------------------------------------------------- */
  /* OPENING INVOICE PER END OF MONTH                                 */
  /* 29 JUN 2007                                                      */
  /* ---------------------------------------------------------------- */
  FOR
    SELECT V.NUMBER,
           V.DOCUMENT,
           V.OPENDATE,
           V.DUEDATE,
           V.STATUS,
           V.SOURCE,
           V.FO_FOLIO,
           V.FO_GUESTNAME,
           V.TOTAL
    FROM ARVCH V
    WHERE V.CUSTOMER = :CUSTOMER
    AND V.OPENDATE <= :REFDATE
    ORDER BY V.OPENDATE
    INTO
      :NUMBER,
      :DOCUMENT,
      :OPENDATE,
      :DUEDATE,
      :STATUS,
      :SOURCE,
      :FO_FOLIO,
      :FO_GUESTNAME,
      :TOTAL
  DO
  BEGIN
    SELECT SUM(DB-CR) FROM ARADJ
    WHERE VOUCHERNO = :NUMBER
    AND OPENDATE <= :REFDATE
    AND STATUS IN ('R','C')
    INTO ADJ;
    IF (ADJ IS NULL) THEN ADJ = 0;
    
    
    SELECT SUM(D.TOTAL) FROM ARCASH1 D
    LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
    WHERE D.VOUCHERNO = :NUMBER
    AND H.DUEDATE <= :REFDATE
    AND H.STATUS IN ('R','C','L')
    INTO PAID;
    IF (PAID IS NULL) THEN PAID = 0;
    
    
    SELECT SUM(D.TOTAL) FROM ARDEPOS1 D
    WHERE D.VOUCHERNO = :NUMBER
    AND D.APPLIEDDATE <= :REFDATE
    AND D.STATUS IN ('R','C')
    INTO DEPOSIT;
    IF (DEPOSIT IS NULL) THEN DEPOSIT = 0;
    
    TOTAL = TOTAL + ADJ - PAID - DEPOSIT;
    IF (TOTAL NOT BETWEEN -0.1 AND 0.1) THEN
       SUSPEND;
  END
END^


ALTER PROCEDURE AR_MUTATION_PERIOD(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    CUSTTYPE VARCHAR(4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
/*declare variable REFDATE DATE;*/
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
begin
/*  SCUSTOMER = 'PAKTA';
  ECUSTOMER = 'PAKTA';
*/
  CREDITCARD = 0;
  if (REFDATE IS NULL) then
  select arsysdate from fosysparam into :REFDATE;

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'zzzzz';
  END
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;

  for select CUSTOMER,name,CUSTTYPE from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER,name,CUSTTYPE

  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung ending                                                          */
    /*========================================================================*/
    select sum(totaldue) from ARvch
     where CUSTOMER = :CUSTOMER 
      into ending;
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    select SUM(TOTALDUE) from ARvch   where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
      into :voucher;
      
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
      into deposit;

    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER
       and DueDate between :sDate and :eDate
       and status in ('C','L','R')
      into :cash;

    select sum(db-cr) from ARadj   where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
      into :adjust1;
    
    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER
    where H.CUSTOMER = :CUSTOMER
    and D.FODATE between :sDate and :eDate
    and D.status = 'C' /* CLOSE,POSTED */
    and D.source = 'A' /* ADJUSTMENT */
    into adjust;
    
    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1 - deposit;
    opening = ending - voucher + cash - adjust;
    if (ending+opening + voucher + cash + adjust <> 0) then
       suspend;
  end
  
  adjust = 0;
  CREDITCARD = 1;
  CUSTTYPE = 'CARD';
  FOR SELECT CREDITCARD,NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :ECUSTOMER
      INTO :CUSTOMER,:NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    opening = 0;
    voucher = 0;
    cash = 0;
    ending = 0;
    /* opening */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and opendate < :sdate
    into :opening;
    
    select sum(j.total) from ar_card_jur j
    inner join AR_CARD_BATCH b on J.batch = B.batch
    where j.creditcard = :customer
    and b.pay_date <:sdate
    and b.status <> 'O'
    into pcash;
    /* open transaction */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and opendate between :SDATE and :EDATE
    into :voucher;    

    /* cash recipt */
    select sum(j.total) from ar_card_jur j
    inner join AR_CARD_BATCH b on b.batch = j.batch
    where j.creditcard = :customer
    and b.status <> 'O'
    and b.pay_date between :SDATE and :EDATE
    into cash;

    
    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (deposit is null) then deposit = 0;
    if (pcash is not null) then opening=opening-pcash;    
    adjust = adjust - deposit;
    ending = opening + voucher - cash + adjust;
    if (opening + voucher + cash + adjust <> 0) then
       suspend;    
  end
end^


ALTER PROCEDURE AR_OVERLIMIT_VIEW
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    LIMIT DOUBLE PRECISION,
    DUE DOUBLE PRECISION,
    OVERDUE DOUBLE PRECISION)
AS
declare variable FOSysDate DATE;
declare variable X INTEGER;
BEGIN
  SELECT FOSysDate FROM FOSYSPARAM WHERE ID = 1
  INTO :FOSysDate;
  
  SELECT COUNT(*) FROM ar_overlimit
  WHERE FODATE = :FOSysDate
  INTO X;
  
  if (X = 0) then
  BEGIN
     DELETE FROM AR_OVERLIMIT;
     FOR SELECT CUSTOMER,NAME,CREDITLIMIT FROM SYSCUSTOMER
         WHERE CREDITLIMIT <> 0
     INTO :CUSTOMER,:NAME,:LIMIT DO
     BEGIN
        select SUM(totaldue)
        from ARvch
        where PAIDSTATUS = 'O'
        AND CUSTOMER = :CUSTOMER
        PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
        into DUE;
        if (DUE IS NULL) then DUE = 0;
        if (DUE > LIMIT) then
        BEGIN
           INSERT INTO AR_OVERLIMIT
           (FODATE,CUSTOMER,NAME,LIMIT,DUE)
           VALUES
           (:FOSysDate,:CUSTOMER,:NAME,:LIMIT,:DUE);
        END
     END
  END
  /*  */
  FOR SELECT CUSTOMER,NAME,LIMIT,DUE,OVERDUE FROM AR_OVERLIMIT
    INTO
      :CUSTOMER,
      :NAME,
      :LIMIT,
      :DUE,
      :OVERDUE
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE AR_RECONCILE_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    BANK VARCHAR(4),
    BBDATE DATE,
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    CREATE_BY VARCHAR(8),
    CREATE_DATE DATE)
AS
DECLARE VARIABLE CUSTOMER VARCHAR(6);
DECLARE VARIABLE CREDITCARD VARCHAR(6);
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE BATCH INTEGER;
DECLARE VARIABLE OUTLET VARCHAR(4);
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.1.2005';
     EDATE = '31.12.2005';
  END

  BBCODE = 'AR';
  APPLICATION = 'AR';
  /* ---------------------------------------------------------------- */
  /* CASH RECONCILIATION                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  FOREX_DB = 0;
  FOR
    SELECT NUMBER, BANK, RECONCILEDATE, DOCUMENT, CUSTOMER,
           FOREX_TOTAL,
           CHECK_NUMBER,
           CURRENCY, EXCHANGE,
           EDITUSER, EDITDATE
    FROM ARCASH0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    INTO
      :SOURCENUMBER, :BANK, :BBDATE, :DOCUMENT, :CUSTOMER,
      :FOREX_CR,
      :REF,
      :CURRENCY,  :EXCHANGE,
      :CREATE_BY, :CREATE_DATE
  DO
  BEGIN
     SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER
     INTO :REMARK;

     SELECT GL_ACCOUNT_ARPREPARE, GL_DEPT_ARPREPARE, GL_COST_ARPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;
     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND;
     ELSE
     BEGIN
        DELETE FROM BBJUR
        WHERE APPLICATION = :APPLICATION
        AND SOURCE = :SOURCE
        AND SOURCENUMBER = :SOURCENUMBER
        AND SOURCEID = 0;
        
        INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
        VALUES         (0, :BANK, :BBDATE, 0, 'O', :DOCUMENT,
                        :BBCODE, :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        :FOREX_DB, :FOREX_CR,
                        :REMARK, :REF,
                        :CURRENCY, :EXCHANGE,
                        :APPLICATION, :SOURCE, :SOURCENUMBER, 0,
                        :CREATE_BY, :CREATE_DATE, :CREATE_BY, :CREATE_DATE);
     END
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT RECONCILIATION                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  FOREX_DB = 0;
  FOR
    SELECT NUMBER, BANK, RECONCILEDATE, DOCUMENT, CUSTOMER,
           FOREX_TOTAL,
           CHECK_NUMBER,
           CURRENCY, EXCHANGE,
           EDITUSER, EDITDATE
    FROM ARDEPOS0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    INTO
      :SOURCENUMBER, :BANK, :BBDATE, :DOCUMENT, :CUSTOMER,
      :FOREX_CR,
      :REF,
      :CURRENCY,  :EXCHANGE,
      :CREATE_BY, :CREATE_DATE
  DO
  BEGIN
     SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER
     INTO :REMARK;

     SELECT GL_ACCOUNT_ARPREPARE, GL_DEPT_ARPREPARE, GL_COST_ARPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;
     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND;
     ELSE
     BEGIN
        INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
        VALUES         (0, :BANK, :BBDATE, 0, 'O', :DOCUMENT,
                        :BBCODE, :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        :FOREX_DB, :FOREX_CR,
                        :REMARK, :REF,
                        :CURRENCY, :EXCHANGE,
                        :APPLICATION, :SOURCE, :SOURCENUMBER, 0,
                        :CREATE_BY, :CREATE_DATE, :CREATE_BY, :CREATE_DATE);
     END
  END
  /* ---------------------------------------------------------------- */
  /* CREDIT CARD RECONCILIATION                                       */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CREC';
  FOREX_DB = 0;
  CURRENCY = 'IDR';
  EXCHANGE = 1;
  FOR
    SELECT NUMBER, BANK, RECONCILEDATE, DOCUMENT,
           CALC_AMOUNT_NET,
           PAY_REF,
           EDITUSER, EDITDATE,
           BATCH, OUTLET
    FROM AR_CARD_BATCH
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    INTO
      :SOURCENUMBER, :BANK, :BBDATE, :DOCUMENT,
      :FOREX_CR,
      :REF,
      :CREATE_BY, :CREATE_DATE,
      :BATCH, :OUTLET
  DO
  BEGIN
     /* ---------------------------------------------------------------- */
     /* GET CREDIT CARD NAME LIST                                        */
     /* ---------------------------------------------------------------- */
     REMARK = '';
     I = 0;
     FOR SELECT CREDITCARD FROM AR_CARD_JUR
         where batch = :batch
         and bank = :bank
         and outlet = :outlet
         GROUP BY CREDITCARD
         INTO CREDITCARD
     DO BEGIN

        IF (I = 0) THEN REMARK = CREDITCARD;
        ELSE IF (I < 5) THEN REMARK = REMARK || ', ' || CREDITCARD;
        I = I + 1;
        WHEN ANY
        DO I = I + 1;
     END

     SELECT GL_ACCOUNT_ARPREPARE, GL_DEPT_ARPREPARE, GL_COST_ARPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;

     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND;
     ELSE
     BEGIN
        DELETE FROM BBJUR
        WHERE APPLICATION = :APPLICATION
        AND SOURCE = :SOURCE
        AND SOURCENUMBER = :SOURCENUMBER
        AND SOURCEID = 0;
        
        INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
        VALUES         (0, :BANK, :BBDATE, 0, 'O', :DOCUMENT,
                        :BBCODE, :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        :FOREX_DB, :FOREX_CR,
                        :REMARK, :REF,
                        :CURRENCY, :EXCHANGE,
                        :APPLICATION, :SOURCE, :SOURCENUMBER, 0,
                        :CREATE_BY, :CREATE_DATE, :CREATE_BY, :CREATE_DATE);
     END
  END
END^


ALTER PROCEDURE AR_RPT_CASH_RECONCILE(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    NAME VARCHAR(40),
    BANKNAME VARCHAR(40),
    NUMBER INTEGER,
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    STATUS CHAR(1),
    CUSTOMER VARCHAR(6),
    CHECK_NUMBER VARCHAR(20),
    OPENDATE DATE,
    DUEDATE DATE,
    RECONCILEDATE DATE,
    BANK VARCHAR(4),
    TOTAL DOUBLE PRECISION,
    TOTAL_RECONCILE DOUBLE PRECISION,
    TOTAL_CLEARANCE DOUBLE PRECISION,
    FOREX_TOTAL DOUBLE PRECISION,
    FOREX_TOTAL_RECONCILE DOUBLE PRECISION,
    FOREX_TOTAL_CLEARANCE DOUBLE PRECISION)
AS
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.7.2005';
     EDATE = '31.7.2005';
  END
  FOR
    SELECT S.NAME, B.BANKNAME, C.NUMBER, C.STATUS, C.CUSTOMER, C.CHECK_NUMBER,
    C.OPENDATE, C.DUEDATE,
     C.RECONCILEDATE, C.TOTAL, C.BANK, C.CURRENCY, C.FOREX_TOTAL, EXCHANGE
    FROM ARCASH0 C
    LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = C.CUSTOMER
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    WHERE C.DUEDATE BETWEEN :SDATE AND :EDATE /* 22 NOV 2008, TADINYA OPENDATE */
    INTO
      :NAME,
      :BANKNAME,
      :NUMBER,
      :STATUS,
      :CUSTOMER,
      :CHECK_NUMBER,
      :OPENDATE,
      :DUEDATE, /* 22 NOV 2008, TAMBAH */
      :RECONCILEDATE,
      :TOTAL,
      :BANK,
      :CURRENCY,
      :FOREX_TOTAL,
      :EXCHANGE
  DO
  BEGIN
    IF (RECONCILEDATE IS NULL) THEN
    BEGIN
       TOTAL_RECONCILE = 0;
       TOTAL_CLEARANCE = TOTAL;
       FOREX_TOTAL_RECONCILE = 0;
       FOREX_TOTAL_CLEARANCE = FOREX_TOTAL;       
    END
    ELSE
    BEGIN
       TOTAL_RECONCILE = TOTAL;
       TOTAL_CLEARANCE = 0;
       FOREX_TOTAL_RECONCILE = FOREX_TOTAL;
       FOREX_TOTAL_CLEARANCE = 0;       
    END
    SUSPEND;
  END
END^


ALTER PROCEDURE AR_RPT_CC_CHECK(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    INFO VARCHAR(8),
    COUNTER INTEGER,
    NUMBER INTEGER,
    CREDITCARD VARCHAR(6),
    OUTLET VARCHAR(4),
    CARDNUMBER VARCHAR(40),
    REMARK VARCHAR(80),
    STATUS CHAR(1),
    TOTAL DOUBLE PRECISION,
    OPENDATE DATE,
    SOURCE CHAR(1),
    CARD_FEE DOUBLE PRECISION,
    CALC_FEE DOUBLE PRECISION,
    CALC_NET DOUBLE PRECISION,
    FO_FOLIO INTEGER,
    FO_TRANS_ID INTEGER)
AS
DECLARE VARIABLE XSOURCE CHAR (1);
DECLARE VARIABLE XFO_FOLIO INTEGER;
DECLARE VARIABLE XFO_TRANS_ID INTEGER;
DECLARE VARIABLE XTOTAL DOUBLE PRECISION;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 11/10/2011                                                           */
  /* -------------------------------------------------------------------- */
  IF (SDATE IS NULL) THEN
  BEGIN
     SELECT ARSYSDATE FROM FOSYSPARAM WHERE ID = 1 INTO SDATE;
     EXECUTE PROCEDURE SP_DATE_BOM(SDATE) RETURNING_VALUES(SDATE); /* 11/10/2011 */
     EXECUTE PROCEDURE SP_DATE_BOM(SDATE) RETURNING_VALUES(EDATE); /* 11/10/2011 */
  END
  /* -------------------------------------------------------------------- */
  /* CREDIT CARD DARI FO YAN GAK ADA DI FOGUEST_JUR                       */
  /* -------------------------------------------------------------------- */
  INFO = 'MISSING';
  COUNTER = 0;
  FOR
    SELECT J.NUMBER,
           J.CREDITCARD,
           J.OUTLET,
           J.CARDNUMBER,
           J.REMARK,
           J.STATUS,
           J.TOTAL,
           J.OPENDATE,
           J.SOURCE,
           J.CARD_FEE,
           J.CALC_FEE,
           J.CALC_NET,
           J.FO_FOLIO,
           J.FO_TRANS_ID
    FROM AR_CARD_JUR J
    WHERE J.OPENDATE BETWEEN :SDATE AND :EDATE
    AND J.SOURCE = 'F'
    AND J.FO_TRANS_ID <> 0
    AND NOT
    ((EXISTS(SELECT * FROM FOGUEST_JUR JR WHERE JR.TRANS_ID=J.FO_TRANS_ID)) OR
    (EXISTS(SELECT * FROM FO_HIST_JUR JR WHERE JR.TRANS_ID=J.FO_TRANS_ID)))
    INTO
       :NUMBER, :CREDITCARD, :OUTLET, :CARDNUMBER, :REMARK,
       :STATUS, :TOTAL, :OPENDATE, :SOURCE, :CARD_FEE,
       :CALC_FEE, :CALC_NET, :FO_FOLIO, :FO_TRANS_ID
  DO
  BEGIN
    SUSPEND;
  END
  /* -------------------------------------------------------------------- */
  /* DEPOSIT                                                              */
  /* -------------------------------------------------------------------- */
  INFO = 'DOUBLE';
  FOR
    SELECT SOURCE, FO_FOLIO, FO_TRANS_ID, TOTAL
    FROM AR_CARD_JUR
    WHERE OPENDATE BETWEEN :SDATE AND :EDATE
    AND SOURCE <> 'M'
    AND FO_FOLIO + FO_TRANS_ID <> 0
    GROUP BY SOURCE, FO_FOLIO, FO_TRANS_ID, TOTAL
    HAVING COUNT(*) > 1
    INTO
      XSOURCE, XFO_FOLIO, XFO_TRANS_ID, XTOTAL
  DO
  BEGIN
      COUNTER = 1;
      FOR
        SELECT J.NUMBER,
               J.CREDITCARD,
               J.OUTLET,
               J.CARDNUMBER,
               J.REMARK,
               J.STATUS,
               J.TOTAL,
               J.OPENDATE,
               J.SOURCE,
               J.CARD_FEE,
               J.CALC_FEE,
               J.CALC_NET,
               J.FO_FOLIO,
               J.FO_TRANS_ID
        FROM AR_CARD_JUR J
        WHERE J.SOURCE = :XSOURCE
        AND J.FO_FOLIO = :XFO_FOLIO
        AND J.FO_TRANS_ID = :XFO_TRANS_ID
        AND ((J.TOTAL=:XTOTAL) OR (J.TOTAL = 0) OR (J.TOTAL IS NULL))
        INTO
          :NUMBER, :CREDITCARD, :OUTLET, :CARDNUMBER, :REMARK,
          :STATUS, :TOTAL, :OPENDATE, :SOURCE, :CARD_FEE,
          :CALC_FEE, :CALC_NET, :FO_FOLIO, :FO_TRANS_ID
      DO
      BEGIN
        SUSPEND;
        COUNTER = COUNTER + 1;
      END
  END
END^


ALTER PROCEDURE AR_RPT_GAINLOSS
RETURNS (
    NUMBER INTEGER,
    CUSTOMER VARCHAR(6),
    OPENDATE DATE,
    DUEDATE DATE,
    NAME VARCHAR(40),
    EXCHANGE DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    FOREX_GAINLOSS DOUBLE PRECISION,
    CURRENCY VARCHAR(4),
    VCH_NUMBER INTEGER,
    VCH_OPENDATE DATE,
    VCH_PAID DOUBLE PRECISION,
    VCH_EXCHANGE DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT C.NUMBER, C.CUSTOMER, C.OPENDATE, C.DUEDATE, S.NAME,
           C.EXCHANGE, C.TOTAL, C.FOREX_GAINLOSS, C.CURRENCY
    FROM ARCASH0 C
    LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = C.CUSTOMER
    WHERE C.EXCHANGE <> 1
    INTO
      :NUMBER,
      :CUSTOMER,
      :OPENDATE,
      :DUEDATE,
      :NAME,
      :EXCHANGE,
      :TOTAL,
      :FOREX_GAINLOSS, CURRENCY
  DO
  BEGIN
    FOR SELECT C.VOUCHERNO, V.OPENDATE, C.FOREX_TOTAL, V.EXCHANGE
        FROM ARCASH1 C
        LEFT JOIN ARVCH V ON V.NUMBER = C.VOUCHERNO
    WHERE C.NUMBER = :NUMBER
    INTO VCH_NUMBER, VCH_OPENDATE, VCH_PAID, VCH_EXCHANGE
    DO
    BEGIN
      SUSPEND;
    END
  END
END^


ALTER PROCEDURE AR_RPT_MUTATION_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    AR_OPEN DOUBLE PRECISION,
    AR_ENDING DOUBLE PRECISION,
    AR_MUTATION DOUBLE PRECISION,
    GL_OPEN DOUBLE PRECISION,
    GL_ENDING DOUBLE PRECISION,
    GL_MUTATION DOUBLE PRECISION,
    ACCNAME VARCHAR(40),
    DELTA_OPEN DOUBLE PRECISION,
    DELTA_ENDING DOUBLE PRECISION,
    DELTA_MUTATION DOUBLE PRECISION,
    DELTA_OPEN_ENDING DOUBLE PRECISION)
AS
DECLARE VARIABLE REFDATE DATE;
BEGIN
  if (PYEAR IS NULL) then
  BEGIN
     SELECT FOSYSDATE FROM FOSYSPARAM INTO REFDATE;
     PYEAR = EXTRACT(YEAR FROM REFDATE);
     PMONTH = EXTRACT(MONTH FROM REFDATE);
  END
  REFDATE = '1.'||PMONTH||'.'||PYEAR;
  FOR
    SELECT T.GLACCOUNT,T.GLDEPT,T.GLCOST,
           SUM(M.OPENING),
           SUM(M.VOUCHER-M.DEPOSIT-M.CASH+M.ADJUST),
           SUM(M.ENDING)
    FROM AR_MUTATION_OLD_CALC('','zzzzzz',:REFDATE) M
    LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = M.CUSTOMER
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = S.CUSTTYPE
    GROUP BY T.GLACCOUNT,T.GLDEPT,T.GLCOST
    INTO
      :GL_ACCOUNT,
      :GL_DEPT,
      :GL_COST,
      :AR_OPEN,
      :AR_ENDING,
      :AR_MUTATION
  DO
  BEGIN
    SELECT NAME FROM GLCOA
    WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;  
    IF (GL_ACCOUNT IS NULL) THEN
    BEGIN
       GL_ACCOUNT = '';
       GL_DEPT = '';
       GL_COST = '';
       ACCNAME = '';
    END

    if (GL_OPEN IS NULL) then
    BEGIN
       GL_OPEN = 0;
       GL_ENDING = 0;
       GL_MUTATION = 0;
    END
    DELTA_OPEN = AR_OPEN - GL_OPEN;
    DELTA_ENDING = AR_ENDING - GL_ENDING;
    DELTA_MUTATION = AR_MUTATION - GL_MUTATION;
    DELTA_OPEN_ENDING = DELTA_OPEN - DELTA_ENDING;
    if ((AR_OPEN<>0) OR (AR_ENDING <>0) OR (AR_MUTATION <>0) OR
        (GL_OPEN<>0)  OR (GL_ENDING <>0)  OR (GL_MUTATION <>0)) THEN
    SUSPEND;
  END
END^


ALTER PROCEDURE AR_VCH_JOURNAL(
    ANUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    REMARK VARCHAR(80),
    DOCNUMBER INTEGER,
    DOCTYPE VARCHAR(12),
    OPENDATE DATE,
    VOUCHER NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    DEPOSIT DOUBLE PRECISION,
    TOTAL NUMERIC(15,4),
    DUE DOUBLE PRECISION)
AS
begin
    NUMBER = ANUMBER;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    DOCTYPE = 'Voucher';
    select total, opendate, fo_guestname, fo_folio
    from ARvch
    where NUMBER = :ANUMBER
    into voucher, opendate, remark, docnumber;
    CASH = 0;
    ADJUST = 0;
    TOTAL = VOUCHER;
    DEPOSIT = 0;
    DUE = TOTAL;
    suspend;
    /* ------------------------------------------------------------------- */
    /* select deposit                                                      */
    /* ------------------------------------------------------------------- */
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;    
    DOCTYPE = 'Deposit';
    for select D.total, D.APPLIEDDATE, D.text1, D.number from ARdepos1 D
        where D.voucherno = :number
        into deposit, opendate, remark, docnumber
    do begin
       TOTAL = -DEPOSIT;
       DUE = DUE + TOTAL;
       suspend;
    end    

    /* ------------------------------------------------------------------- */
    /* select cash payment                                                 */
    /* ------------------------------------------------------------------- */
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;
    DOCTYPE = 'Payment';
    for select D.total, H.DUEDATE, H.CHECK_NUMBER, H.NUMBER from ARcash1 D 
        inner join ARcash0 H on H.number = D.number
        where D.voucherno = :number
        into cash, opendate, remark, docnumber
    do begin
       TOTAL = -CASH;
       DUE = DUE + TOTAL;
       suspend;
     end
    /* ------------------------------------------------------------------- */
    /* select adjustment                                                   */
    /* ------------------------------------------------------------------- */
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;        
    DOCTYPE = 'Adjustment';
    for select (db-cr), opendate, number  from ARadj
        where voucherno = :number
        into adjust, opendate, docnumber
    do begin
       remark = '';
       total = adjust;
       DUE = DUE + TOTAL;
       suspend;
    end
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;        
    /* ------------------------------------------------------------------- */
    /* Front Office adjustment                                             */
    /* ------------------------------------------------------------------- */
    DOCTYPE = 'Correction';
    for select (Debit-Credit), fodate, remark, fo_trans_id from arvch_detail
        where Number = :number
        and status = 'C' /* C = Close, sudah di posting ke FO, O=Open */
        and source = 'A' /* A = Adjustment, f= Front Office */
    into Adjust, opendate, remark, docnumber
    do begin
       total = adjust;    
       DUE = DUE + TOTAL;
       suspend;
    end
end^


ALTER PROCEDURE BB_RPT_RECONCILE_LIST
RETURNS (
    DATAINDEX INTEGER,
    DATAINFO VARCHAR(20),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    RECONCILEDATE DATE,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    CHECK_NUMBER VARCHAR(20),
    CODE VARCHAR(6),
    NAME VARCHAR(40),
    BANK VARCHAR(4),
    BANKNAME VARCHAR(40),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION)
AS
DECLARE VARIABLE CREDITCARD VARCHAR(40);
BEGIN
  CREDIT = 0;
  DATAINDEX = 0;
  DATAINFO = 'Cash Receipt';
  FOR
        SELECT V.NUMBER, V.OPENDATE, V.DUEDATE, V.RECONCILEDATE,
               V.STATUS, V.DOCUMENT, V.CHECK_NUMBER,
               V.CUSTOMER,
               S.NAME,
               V.BANK,
               B.BANKNAME,
               V.TOTAL
        FROM ARCASH0 V
        LEFT JOIN SYSBANK B ON B.BANK = V.BANK
        LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = V.CUSTOMER
        WHERE STATUS IN ('R','L')

    INTO
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :RECONCILEDATE,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :CODE,
      :NAME,
      :BANK,
      :BANKNAME,
      :DEBIT
  DO
  BEGIN
    SUSPEND;
  END
  
  DATAINDEX = 1;
  DATAINFO = 'A/R Deposit';
  FOR
    SELECT D.NUMBER, D.OPENDATE, D.OPENDATE, D.RECONCILEDATE,
           D.STATUS, D.DOCUMENT, D.CHECK_NUMBER,
           D.CUSTOMER,
           S.NAME,
           D.BANK,
           B.BANKNAME,
           D.TOTAL
    FROM ARDEPOS0 D
    LEFT JOIN SYSBANK B ON B.BANK = D.BANK
    LEFT JOIN SYSCUSTOMER S ON S.CUSTOMER = D.CUSTOMER
    WHERE STATUS IN ('R','L')

    INTO
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :RECONCILEDATE,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :CODE,
      :NAME,
      :BANK,
      :BANKNAME,
      :DEBIT
  DO
  BEGIN
    SUSPEND;
  END
  
  DATAINDEX = 2;
  DATAINFO = 'Credit Card';
  CODE = 'CARD';
  FOR
    SELECT D.NUMBER, D.OPENDATE, D.OPENDATE, D.RECONCILEDATE,
           D.STATUS, D.DOCUMENT, D.BATCH,
           D.BANK,
           B.BANKNAME,
           D.CALC_AMOUNT_NET
    FROM AR_CARD_BATCH D
    LEFT JOIN SYSBANK B ON B.BANK = D.BANK
    WHERE STATUS IN ('R','L')

    INTO
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :RECONCILEDATE,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :BANK,
      :BANKNAME,
      :DEBIT
  DO
  BEGIN
    NAME = '';
    FOR SELECT C.NAME FROM AR_CARD_JUR J
        LEFT JOIN AR_CARD C ON C.CREDITCARD = J.CREDITCARD
        WHERE BATCH_NUMBER = :NUMBER
        GROUP BY C.NAME
        INTO CREDITCARD
    DO
    BEGIN
      IF (NAME <> '') THEN NAME = NAME || ', ';
      NAME = NAME || CREDITCARD;
      WHEN ANY DO
      BEGIN
         NAME = NAME;
      END
    END
    SUSPEND;
  END
END^


ALTER PROCEDURE BQ_RPT_AGING(
    REFDATE DATE,
    DETAILFLAG INTEGER)
RETURNS (
    FOLIO INTEGER,
    GUESTNAME VARCHAR(80),
    DEPOSITNO INTEGER,
    AMOUNT DOUBLE PRECISION,
    DATEDUE DATE,
    TERMIN SMALLINT,
    AGE INTEGER,
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable AMT_DEPOSIT NUMERIC(15,2);
BEGIN
   /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    FOLIO = 0 ;
    GUESTNAME ='';
    DATEDUE= NULL ;
    
  FOR
    SELECT FOGUEST_DEPOSIT.FOLIO,
           FOGUEST_DEPOSIT.GUESTNAME,
           FOGUEST_DEPOSIT.DEPOSITNO,
           FOGUEST_DEPOSIT.AMOUNT,
           FOGUEST_DEPOSIT.DATEDUE,
           FOGUEST_DEPOSIT.TERMIN
    FROM FOGUEST_DEPOSIT

    INTO
      :FOLIO,
      :GUESTNAME,
      :DEPOSITNO,
      :AMOUNT,
      :DATEDUE,
      :TERMIN
  DO
  BEGIN
    d = refdate - DATEDUE ;
   /*======================================================================*/
   /* jika aging detail                                                    */
   /*======================================================================*/
   AMT_dEPOSIT = AMOUNT ;
    if (detailflag = 1) then
      begin
         curr = 0;
         over30 = 0;
         over60 = 0;
         over90 = 0;
      end
    if (d<=30) then curr = CURR + AMT_DEPOSIT ;
    ELSE if (D<=60) then OVER30 = OVER30 + AMT_DEPOSIT ;
    ELSE if (D<=90) then OVER60 = OVER60 + AMT_DEPOSIT ;
    ELSE if (D>90) then OVER90 = OVER90+AMT_DEPOSIT  ;
    /* ------------------------------------------------------------------- */
    /* detail aging (ada nomor vouchernya                                  */
    /* ------------------------------------------------------------------- */
    if (detailflag = 1) then
       begin
       age = d;
       total = curr + over30 + over60 + over90;
       if ((total <> 0) AND (AGE>=0)) then
          suspend;
     end
   END
     /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       DEPOSITNO = 0 ;
       if ((total < -0.01) or (total > 0.01)) then
          suspend;
    end
END^


ALTER PROCEDURE BQ_RPT_EO(
    PFOLIO INTEGER,
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FOLIO INTEGER,
    FODATE DATE)
AS
BEGIN
  IF ((PFOLIO IS NULL) OR (PFOLIO = 0)) THEN PFOLIO = 59496;
  FODATE = SDATE;
  FOLIO = :PFOLIO;
  WHILE (FODATE <= EDATE) DO
  BEGIN
     SUSPEND;
     FODATE = FODATE + 1;
  END
END^


ALTER PROCEDURE BQ_RPT_EO_SCHEDULE(
    PFOLIO INTEGER,
    SDATE DATE)
RETURNS (
    FOLIO INTEGER,
    SCHEDULE_TYPE VARCHAR(16),
    FUNC VARCHAR(12),
    ID INTEGER,
    FODATE DATE,
    TIME_NAME VARCHAR(13),
    PERSON_IN_CHARGE VARCHAR(80),
    FUNC_LAYOUT VARCHAR(8),
    REMARK VARCHAR(80),
    NOTE BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    PAX INTEGER,
    PAX_EXPECTED INTEGER,
    FUNCTION_NAME VARCHAR(40),
    LAYOUT_NAME VARCHAR(40))
AS
declare variable datestart date;
declare variable dateend date;
declare variable meal_name varchar(40);
BEGIN
  IF ((PFOLIO IS NULL) OR (PFOLIO = 0)) THEN PFOLIO = 59496;
  FODATE = SDATE;
  /* -------------------------------------------------------------------- */
  /* MEAL ARRANGEMENT                                                     */
  /* -------------------------------------------------------------------- */
  SCHEDULE_TYPE = 'MEAL';
  FOR
    SELECT
    BQ.FOLIO,
    BQ.LOCATION FUNC,
    BQ.ID,
    BQ.TIME_START||' - ' || BQ.TIME_END TIME_NAME,
    BQ.FODATE DATESTART,
    BQ.FODATE DATEEND,
    BQ.PERSON_IN_CHARGE,
    BQ.REMARK,
    BQ.NOTE,
    BQ.PAX,
    BQ.PAX PAX_EXPECTED,
    LC.NAME FUNCTION_NAME,
    MP.NAME
    FROM BQ_MASTER_MEAL BQ
    LEFT JOIN BQ_MEAL_LOCATION LC ON LC.LOCATION=BQ.LOCATION
    LEFT JOIN BQ_MEAL_PERIOD MP ON MP.MEAL = BQ.MEAL_PERIOD
    WHERE BQ.FOLIO=:PFOLIO
    AND BQ.FODATE=:SDATE
    INTO
      :FOLIO,
      :FUNC,
      :ID,
      :TIME_NAME,
      :DATESTART,
      :DATEEND,
      :PERSON_IN_CHARGE,
      :REMARK,
      :NOTE,
      :PAX,
      :PAX_EXPECTED,
      :FUNCTION_NAME,
      :LAYOUT_NAME
  DO
  BEGIN
    SUSPEND;
  END
  /* -------------------------------------------------------------------- */
  /* VENUES / MEETING ARANGEMENT                                          */
  /* -------------------------------------------------------------------- */
  SCHEDULE_TYPE = 'VENUE';
  FOR
    SELECT
    BQ.FOLIO,
    BQ.FUNC,
    BQ.BOOK_ID,
    BQ.TIMESTART||' - ' || BQ.TIMEEND TIME_NAME,
    BQ.DATESTART,
    BQ.DATEEND,
    BQ.PERSON_IN_CHARGE,
    BQ.FUNC_LAYOUT,
    BQ.REMARK,
    BQ.NOTE,
    BQ.PAX,
    BQ.PAX_EXPECTED,
    FC.NAME FUNCTION_NAME,
    LY.NAME LAYOUT_NAME
    FROM BQ_MASTER_FUNC BQ
    LEFT JOIN BQ_FUNC FC ON FC.FUNC=BQ.FUNC
    LEFT JOIN BQ_FUNC_LAYOUT LY ON LY.FUNC=BQ.FUNC AND LY.LAYOUT=BQ.FUNC_LAYOUT
    WHERE BQ.FOLIO=:PFOLIO
    AND :SDATE BETWEEN BQ.DATESTART AND BQ.DATEEND
    INTO
      :FOLIO,
      :FUNC,
      :ID,
      :TIME_NAME,
      :DATESTART,
      :DATEEND,
      :PERSON_IN_CHARGE,
      :FUNC_LAYOUT,
      :REMARK,
      :NOTE,
      :PAX,
      :PAX_EXPECTED,
      :FUNCTION_NAME,
      :LAYOUT_NAME
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE BQ_RPT_EO_SCHEDULE_MEAL(
    PFOLIO INTEGER,
    SDATE DATE)
RETURNS (
    FOLIO INTEGER,
    SCHEDULE_TYPE VARCHAR(16),
    FUNC VARCHAR(12),
