    MENU_COST DOUBLE PRECISION,
    MENU_PRICE DOUBLE PRECISION,
    MENU_TOTAL_COST DOUBLE PRECISION,
    MENU_TOTAL_PRICE DOUBLE PRECISION)
AS
declare variable datestart date;
declare variable dateend date;
declare variable meal_name varchar(40);
BEGIN
  IF ((PFOLIO IS NULL) OR (PFOLIO = 0)) THEN PFOLIO = 59496;
  FODATE = SDATE;
  /* -------------------------------------------------------------------- */
  /* MEAL ARRANGEMENT                                                     */
  /* -------------------------------------------------------------------- */
  SCHEDULE_TYPE = 'MEAL';
  FOR
    SELECT
    BQ.FOLIO,
    BQ.LOCATION FUNC,
    BQ.ID,
    BQ.TIME_START||' - ' || BQ.TIME_END TIME_NAME,
    BQ.FODATE DATESTART,
    BQ.FODATE DATEEND,
    BQ.PERSON_IN_CHARGE,
    BQ.REMARK,
    BQ.NOTE,
    BQ.PAX,
    BQ.PAX PAX_EXPECTED,
    LC.NAME FUNCTION_NAME,
    MP.NAME
    FROM BQ_MASTER_MEAL BQ
    LEFT JOIN BQ_MEAL_LOCATION LC ON LC.LOCATION=BQ.LOCATION
    LEFT JOIN BQ_MEAL_PERIOD MP ON MP.MEAL = BQ.MEAL_PERIOD
    WHERE BQ.FOLIO=:PFOLIO
    AND BQ.FODATE=:SDATE
    INTO
      :FOLIO,
      :FUNC,
      :ID,
      :TIME_NAME,
