      :REMARK,
      :NOTE,
      :PAX,
      :PAX_EXPECTED,
      :FUNCTION_NAME,
      :LAYOUT_NAME
  DO
  BEGIN
    FOR
        SELECT M.MENU_TYPE,
               T.NAME MENU_TYPE_NAME,
               M.NAME MENU_NAME,
               B.QTY QTY,
               B.COST COST,
               B.PRICE PRICE,
               B.CALC_COST TOTAL_COST,
               B.CALC_PRICE TOTAL_PRICE
        FROM BQ_MASTER_MEAL_MENU B
        LEFT JOIN BQ_MENU M ON M.MENU_ID = B.MENU
        LEFT JOIN BQ_MENU_TYPE T ON T.CODE = M.MENU_TYPE
        WHERE B.ID = :ID
        INTO
          :MENU_TYPE,
          :MENU_TYPE_NAME,
          :MENU_NAME,
          :MENU_QTY,
          :MENU_COST,
          :MENU_PRICE,
          :MENU_TOTAL_COST,
          :MENU_TOTAL_PRICE
      DO
      BEGIN
        SUSPEND;
      END
  END
END^


ALTER PROCEDURE BQ_RPT_EO_SCHEDULE_NOTE(
