ALTER PROCEDURE CTRL_VERIFY_CLEARANCE_AR(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NAME VARCHAR(40),
    CASH DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     PYEAR = 2006;
     PMONTH = 2;
  END

  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES(EDATE);
  APPLICATION = 'AP';
  /* ---------------------------------------------------------------- */
  /* cash payment                                                     */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CASH';
  NAME = 'Cash Receipt';

  SELECT SUM(TOTAL) FROM ARCASH0
  WHERE DUEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('L','C','R')
  INTO :CASH;

  IF (CASH IS NULL) THEN CASH = 0;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* cash reconciliation                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  NAME = 'Cash Receipt Reconciliation';

  SELECT SUM(TOTAL) FROM ARCASH0
  WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO :CASH;

  IF (CASH IS NULL) THEN CASH = 0;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* deposit payment                                                  */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DEP0';
  NAME = 'Reservation Deposit';

  SELECT SUM(TOTAL) FROM ARDEPOS0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('L','C','R')
  INTO :CASH;

  IF (CASH IS NULL) THEN CASH = 0;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* deposit reconciliation                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  NAME = 'Reservation Deposit Reconciliation';

  SELECT SUM(TOTAL) FROM ARDEPOS0
  WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO :CASH;

  IF (CASH IS NULL) THEN CASH = 0;
  SUSPEND;
  
  /* ---------------------------------------------------------------- */
  /* credit card settlement                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CCPY';
  NAME = 'Credit Card Settlement';

  SELECT SUM(AMOUNT)
  FROM AR_CARD_BATCH
  WHERE (PAY_DATE BETWEEN :SDATE AND :EDATE)
  AND STATUS IN ('L','R','C')
  INTO CASH;

  IF (CASH IS NULL) THEN CASH = 0;
  SUSPEND;
  
  /* ---------------------------------------------------------------- */
  /* credit card settlement reconciliation                            */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CREC';
  NAME = 'Credit Card Settlement Reconciliation';

  SELECT SUM(CALC_AMOUNT_NET)
  FROM AR_CARD_BATCH
  WHERE (RECONCILEDATE BETWEEN :SDATE AND :EDATE)
  AND STATUS = 'C'
  INTO CASH;

  IF (CASH IS NULL) THEN CASH = 0;
  SUSPEND;
END^


ALTER PROCEDURE CTRL_VERIFY_FO_COMMISSION(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    CODE VARCHAR(16),
    DATECO DATE,
    FOLIO INTEGER,
    GUESTNAME VARCHAR(80),
    AMOUNT DOUBLE PRECISION,
    COUNTER INTEGER,
    FO_AP_FODATE DATE,
    FO_AP_NUMBER INTEGER,
    FO_AP_SUPPLIER VARCHAR(6),
    FO_AP_SUPPLIERNAME VARCHAR(40),
    FO_AP_AMOUNT DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE CAT_COMMISSION VARCHAR(4);
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     PYEAR = 2006;
     PMONTH = 10;
  END


  SDATE = '1.'||PMONTH ||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES(EDATE);
  

  SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'COMMISSION'
  INTO CAT_COMMISSION;
  
  
  FOR
    SELECT FOLIO,FULLNAMEF,DATECO
    FROM FOGUEST 
    WHERE DATECO BETWEEN :SDATE AND :EDATE
    AND FOLIOSTATUS = 'O'
    PLAN (FOGUEST INDEX (FOGUEST_IDX_DATECO))
    INTO :FOLIO,GUESTNAME,DATECO
  DO
  BEGIN
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO = :FOLIO
    AND CATEGORY = :CAT_COMMISSION
    INTO AMOUNT;
    IF (AMOUNT IS NULL) THEN AMOUNT = 0;
    IF (AMOUNT <> 0) THEN
    BEGIN
       SELECT COUNT(*) FROM FO_AP WHERE FO_FOLIO = :FOLIO
       INTO COUNTER;

       FO_AP_NUMBER = NULL;
       FO_AP_FODATE = NULL;
       FO_AP_SUPPLIER = NULL;
       FO_AP_SUPPLIERNAME = NULL;
       FO_AP_AMOUNT = NULL;
       IF (COUNTER = 0) THEN
       BEGIN
          CODE = 'NOTFOUND';
          SUSPEND;
       END
       ELSE
       IF (COUNTER > 2) THEN
       BEGIN
          CODE = 'DOUBLE';
       END
       ELSE
       BEGIN
          SELECT NUMBER,FODATE,SUPPLIER,SUPPLIERNAME,AMOUNT
          FROM FO_AP
          WHERE FO_FOLIO = :FOLIO
          INTO FO_AP_NUMBER,FO_AP_FODATE,FO_AP_SUPPLIER,
               FO_AP_SUPPLIERNAME,FO_AP_AMOUNT;
          IF (FO_AP_FODATE <> DATECO) THEN
          BEGIN
             CODE = 'DATE';
             SUSPEND;
          END
          ELSE
          IF (FO_AP_AMOUNT <> AMOUNT) THEN
          BEGIN
             CODE = 'AMOUNT';
             SUSPEND;
          END
       END
    END
  END
END^


ALTER PROCEDURE CTRL_VERIFY_FO_EXPORT_TO_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(16),
    SOURCE VARCHAR(4),
    TEXT VARCHAR(40),
    FO DOUBLE PRECISION,
    BUFFER DOUBLE PRECISION,
    GL DOUBLE PRECISION,
    STOCK DOUBLE PRECISION,
    DAILY DOUBLE PRECISION,
    DELTA_BUFFER DOUBLE PRECISION,
    DELTA_FO DOUBLE PRECISION)
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
declare variable EOM DATE;
begin
  if ((PYEAR IS NULL) OR (PYEAR = 0)) then
  BEGIN
     PYEAR = 2003;
     PMONTH = 12;
  END
  
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  execute procedure sp_endofmonth SDATE returning_values EDATE;
  execute procedure sp_endofmonth SDATE returning_values EOM;
  /* ------------------------------------------------------------------------ */
  /* ACCOUNT PAYABLE                                                          */
  /* ------------------------------------------------------------------------ */
  APPLICATION = 'A/R';
  TEXT = 'A/R New Voucher';

  SELECT SUM(TOTAL) FROM ARVCH
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND SOURCE IN ('R', 'C')
  PLAN (ARVCH INDEX (ARVCH_IDX_DATE))
  INTO FO;
  if (FO IS NULL) then FO = 0;
  BUFFER = 0;
  STOCK = 0;
  DELTA_BUFFER = 0;
  DELTA_FO = 0;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/R';
  TEXT = 'A/R Debit Note';

  SELECT SUM(TOTAL) FROM ARVCH
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND SOURCE = 'D'
  PLAN (ARVCH INDEX (ARVCH_IDX_DATE))
  INTO FO;
  if (FO IS NULL) then FO = 0;
  BUFFER = 0;
  STOCK = 0;
  DELTA_BUFFER = 0;
  DELTA_FO = 0;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/R';
  TEXT = 'A/R Adjustment';
  SELECT SUM(CR-DB) FROM GLBUFFER
  WHERE APPLICATION = 'AR'
  AND SOURCE = 'ADJ'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  AND EXISTS(SELECT * FROM SYSCUSTOMERTYPE WHERE SYSCUSTOMERTYPE.GLACCOUNT = GLBUFFER.ACCOUNT
      PLAN (SYSCUSTOMERTYPE INDEX (IDX_SYSCUSTOMERTYPE_ACCOUNT)))
  INTO :BUFFER;
  if (BUFFER IS NULL) then BUFFER = 0;
  SOURCE = 'ADJ';
/*
  SELECT SUM(CR-DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'AR'
  AND SOURCE = 'ADJ'
  AND EXISTS(SELECT * FROM SYSCUSTOMERTYPE WHERE SYSCUSTOMERTYPE.GLACCOUNT = GLJUR.ACCOUNT)
  INTO :GL;
*/
  SELECT SUM(CR-DB) FROM ARADJ
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R','C')
  INTO FO;


  if (BUFFER IS NULL) then BUFFER = 0;
  if (FO IS NULL) then FO = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_FO     = FO - BUFFER;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/R';
  TEXT = 'A/R Cash Payment';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'AR'
  AND SOURCE = 'CASH'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  AND EXISTS(SELECT * FROM SYSCUSTOMERTYPE WHERE SYSCUSTOMERTYPE.GLACCOUNT = GLBUFFER.ACCOUNT
      PLAN (SYSCUSTOMERTYPE INDEX (IDX_SYSCUSTOMERTYPE_ACCOUNT)))
  INTO :BUFFER;
  if (BUFFER IS NULL) then BUFFER = 0;
  SOURCE = 'CASH';

/*  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'AR'
  AND SOURCE = 'CASH'
  AND EXISTS(SELECT * FROM syssuppliertype WHERE syssuppliertype.GLACCOUNT = GLJUR.ACCOUNT)
  INTO :GL;
*/
  SELECT SUM(TOTAL-FOREX_GAINLOSS) FROM ARCASH0
  WHERE DUEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R','C')
  INTO FO;

  if (BUFFER IS NULL) then BUFFER = 0;
  if (FO IS NULL) then FO = 0;
  if (GL IS NULL) then GL = 0;
  if (STOCK IS NULL) then STOCK = 0;
  FO = FO + STOCK;
  STOCK = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_FO     = FO - BUFFER;
  suspend;
  /* ------------------------------------------------------------------------ */
  /* AR RECONCILIATION                                                        */
  /* ------------------------------------------------------------------------ */
  SOURCE = 'REC';
/*  APPLICATION = 'A/R';
  TEXT = 'Reconciliation';
  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'AR'
  AND SOURCE = 'REC'
  INTO GL;
*/

  SELECT SUM(DB) FROM BBJUR
  WHERE APPLICATION = 'AR'
  AND SOURCE = 'REC'
  AND BBDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(FOREX_TOTAL*EXCHANGE) FROM ARCASH0
  WHERE DUEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO FO;

  if (BUFFER IS NULL) then BUFFER = 0;
  if (FO IS NULL) then FO = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_FO     = FO - BUFFER;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/R Mutation';
  TEXT = 'Last Month';
  SOURCE = 'MUT';
  SELECT SUM(OPENING), SUM(VOUCHER), SUM(CASH), SUM(ADJUST), SUM(ENDING)
  FROM AR_MUTATION_OLD('','zzzzzz', :SDATE-1)
  INTO FO, BUFFER, GL, DELTA_BUFFER, DELTA_FO;
  SUSPEND;
  TEXT = 'This Month';
  SELECT SUM(OPENING), SUM(VOUCHER), SUM(CASH), SUM(ADJUST), SUM(ENDING)
  FROM AR_MUTATION_OLD('','zzzzzz', :EDATE)
  INTO FO, BUFFER, GL, DELTA_BUFFER, DELTA_FO;
  SUSPEND;

end^


ALTER PROCEDURE ECOS_FORECAST_GUEST_DAILY
RETURNS (
    FOLIO INTEGER,
    FOLIOTYPE VARCHAR(1),
    FODATE DATE,
    GROUPNUMBER INTEGER,
    LEAD_DAY INTEGER,
    FLAG_CI INTEGER,
    FOLIOSTATUS CHAR(1),
    FOLIOSTATUS_SHARE CHAR(1),
    DATECI DATE,
    DATECO DATE,
    ROOMNIGHT INTEGER,
    DATERESV DATE,
    ROOMRATE DOUBLE PRECISION,
    RATECODE VARCHAR(12),
    PAX SMALLINT,
    CHILD SMALLINT,
    ROOMTYPE VARCHAR(4),
    ROOMTYPE_UPGRADE VARCHAR(4),
    ST_RESV_SOURCE VARCHAR(4),
    ST_NATIONALITY VARCHAR(4),
    ST_MARKETSEGMENT VARCHAR(4),
    ST_ORIGINAREA VARCHAR(4),
    ST_DESTINATIONAREA VARCHAR(4),
    ROOMCOUNT INTEGER,
    CHARGE_RATE DOUBLE PRECISION,
    CHARGE_ROOM DOUBLE PRECISION,
    CHARGE_DISCOUNT DOUBLE PRECISION,
    CHARGE_TAX DOUBLE PRECISION,
    CHARGE_PACKAGE DOUBLE PRECISION)
AS
DECLARE VARIABLE DATECREATE DATE;
DECLARE VARIABLE RATE_TAG INTEGER;
DECLARE VARIABLE RATEDISCOUNT DOUBLE PRECISION;
DECLARE VARIABLE GROUP_INHOUSE DATE;
BEGIN
  FOR
    SELECT FOLIO, FOLIOTYPE,
        GROUPNUMBER, GROUP_INHOUSE,
        FOLIOSTATUS,
        FOLIOSTATUS_SHARE,
        DATECI,
        DATECO,
        ROOMNIGHT,
        DATERESV,
        DATECREATE,
        ROOMRATE,
        RATEDISCOUNT,
        RATECODE,
        PAX,
        CHILD,
        ROOMTYPE,
        ROOMTYPE_UPGRADE,
        RATE_TAG,
        ST_RESV_SOURCE,
        ST_NATIONALITY,
        ST_MARKETSEGMENT,
        ST_ORIGINAREA,
        ST_DESTINATIONAREA,
        ROOMCOUNT
    FROM ECOS_FORECAST_GUEST_RAW
    INTO
      :FOLIO, FOLIOTYPE,
      :GROUPNUMBER, GROUP_INHOUSE,
      :FOLIOSTATUS,
      :FOLIOSTATUS_SHARE,
      :DATECI,
      :DATECO,
      :ROOMNIGHT,
      :DATERESV,
      :DATECREATE,
      :ROOMRATE,
      :RATEDISCOUNT,
      :RATECODE,
      :PAX,
      :CHILD,
      :ROOMTYPE,
      :ROOMTYPE_UPGRADE,
      :RATE_TAG,
      :ST_RESV_SOURCE,
      :ST_NATIONALITY,
      :ST_MARKETSEGMENT,
      :ST_ORIGINAREA,
      :ST_DESTINATIONAREA,
      :ROOMCOUNT
  DO
  BEGIN
    IF (FOLIOTYPE = 'G') THEN /* GROUP */
    BEGIN
       FODATE = GROUP_INHOUSE;
       LEAD_DAY = DATECI - DATERESV;
       DATECO = FODATE + 1;
    END
    ELSE /* INDIVIDUAL */
    BEGIN
       FODATE = DATECI;
       LEAD_DAY = DATECI - DATERESV;
       FLAG_CI  = 1;
    END
    /* -------------------------------------------------------------------- */
    WHILE (FODATE < DATECO) DO
    BEGIN
       IF (FODATE = DATECI) THEN FLAG_CI  = 1;
       ELSE FLAG_CI = 0;
       
       BEGIN
          SELECT SUM(debit-credit), SUM(charge_room), SUM(charge_discount),
                 SUM(charge_package), SUM(charge_tax)
          FROM FO_RATE_JUR (:RATECODE, :ROOMTYPE_UPGRADE, :PAX, :CHILD,
                            :DATECI, :FODATE, :FODATE, :RATEDISCOUNT,
                            :FOLIO, 0, :GROUPNUMBER, :RATE_TAG, '','','','')
          INTO CHARGE_RATE, CHARGE_ROOM, CHARGE_DISCOUNT, CHARGE_PACKAGE, CHARGE_TAX;
       WHEN ANY DO
          CHARGE_RATE = NULL;
       END
       IF (CHARGE_RATE IS NULL) THEN
       BEGIN
          CHARGE_RATE = ROOMRATE;
          CHARGE_ROOM = 0;
          CHARGE_DISCOUNT = 0;
          CHARGE_PACKAGE = 0;
          CHARGE_TAX = 0;
       END
       SUSPEND;
       FODATE = FODATE + 1;
    END
  END
END^


ALTER PROCEDURE ECOS_FORECAST_GUEST_RAW
RETURNS (
    FOLIO INTEGER,
    GROUPNUMBER INTEGER,
    FOLIOTYPE VARCHAR(1),
    FOLIOSTATUS CHAR(1),
    FOLIOSTATUS_SHARE CHAR(1),
    DATECI DATE,
    DATECO DATE,
    GROUP_INHOUSE DATE,
    ROOMNIGHT INTEGER,
    DATERESV DATE,
    DATECREATE DATE,
    ROOMRATE DOUBLE PRECISION,
    RATEDISCOUNT DOUBLE PRECISION,
    RATEPACKAGE DOUBLE PRECISION,
    RATECODE VARCHAR(12),
    PAX SMALLINT,
    CHILD SMALLINT,
    ROOMTYPE VARCHAR(4),
    ROOMTYPE_UPGRADE VARCHAR(4),
    RATE_TAG INTEGER,
    ST_RESV_SOURCE VARCHAR(4),
    ST_NATIONALITY VARCHAR(4),
    ST_MARKETSEGMENT VARCHAR(4),
    ST_ORIGINAREA VARCHAR(4),
    ST_DESTINATIONAREA VARCHAR(4),
    ROOMCOUNT INTEGER)
AS
DECLARE VARIABLE FOSYSDATE DATE;
BEGIN
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;
  FOLIOTYPE = 'P';
  ROOMCOUNT = 1;
  RATEPACKAGE = 0;
  GROUP_INHOUSE = NULL;
  FOR
    SELECT FOLIO, GROUPNUMBER, FOLIOSTATUS, FOLIOSTATUS_SHARE,
           DATECI, DATECO, ROOMNIGHT, DATERESV, DATECREATE,
           ROOMRATE, RATEDISCOUNT, RATECODE, PAX, CHILD,
           ROOMTYPE, ROOMTYPE_UPGRADE, RATECODE_GROUP_TAG,
           ST_RESV_SOURCE, ST_NATIONALITY, ST_MARKETSEGMENT,
           ST_ORIGINAREA, ST_DESTINATIONAREA
    FROM FOGUEST
    WHERE listindex <= 1
    AND FOLIOSTATUS_SHARE = 'M'
    AND RATECODE <> 'HU'
    INTO
      :FOLIO,
      :GROUPNUMBER,
      :FOLIOSTATUS,
      :FOLIOSTATUS_SHARE,
      :DATECI,
      :DATECO,
      :ROOMNIGHT,
      :DATERESV,
      :DATECREATE,
      :ROOMRATE,
      :RATEDISCOUNT,
      :RATECODE,
      :PAX,
      :CHILD,
      :ROOMTYPE,
      :ROOMTYPE_UPGRADE,
      :RATE_TAG,
      :ST_RESV_SOURCE,
      :ST_NATIONALITY,
      :ST_MARKETSEGMENT,
      :ST_ORIGINAREA,
      :ST_DESTINATIONAREA
  DO
  BEGIN
    IF (DATERESV IS NULL) THEN
        DATERESV = EXTRACT(DAY FROM DATECREATE) || '.' ||
                   EXTRACT(MONTH FROM DATECREATE) || '.' ||
                   EXTRACT(YEAR FROM DATECREATE);
    IF (DATERESV > DATECI) THEN DATERESV = DATECI-3;
    SUSPEND;
  END
  /* -------------------------------------------------------------------- */
  /* GROUPS' BLOCK NOT PICKED UP                                          */
  /* -------------------------------------------------------------------- */
  FOLIOTYPE = 'G';
  PAX = 2;
  CHILD = 0;
  RATE_TAG = 0;
  RATEDISCOUNT = 0;

  FOR SELECT FOLIO, FODATE, ROOMTYPE, BLOCKED - PICKEDUP,
             TOTALRATE, TOTALPACKAGE
      FROM FORI_GROUP
      WHERE FODATE >= :FOSYSDATE
      AND GROUPSTATUS IN ('T','C','W','G','I')
      AND BLOCKED > PICKEDUP
      INTO FOLIO, GROUP_INHOUSE, ROOMTYPE, ROOMCOUNT, ROOMRATE, RATEPACKAGE
  DO
  BEGIN
    GROUPNUMBER = FOLIO;
    ROOMTYPE_UPGRADE = ROOMTYPE;
    SELECT FOLIOSTATUS, FOLIOSTATUS_SHARE,
           DATECI, DATECO, DATERESV, DATECREATE,
           ROOMRATE, RATEDISCOUNT, RATECODE, 
           ST_RESV_SOURCE, ST_NATIONALITY, ST_MARKETSEGMENT,
           ST_ORIGINAREA, ST_DESTINATIONAREA
    FROM FOGUEST
    WHERE FOLIO = :FOLIO
    INTO
      :FOLIOSTATUS,
      :FOLIOSTATUS_SHARE,
      :DATECI,
      :DATECO,
      :DATERESV,
      :DATECREATE,
      :ROOMRATE,
      :RATEDISCOUNT,
      :RATECODE,
      :ST_RESV_SOURCE,
      :ST_NATIONALITY,
      :ST_MARKETSEGMENT,
      :ST_ORIGINAREA,
      :ST_DESTINATIONAREA;
    BEGIN
       ROOMNIGHT = ROOMCOUNT;
       IF (DATERESV IS NULL) THEN
           DATERESV = EXTRACT(DAY FROM DATECREATE) || '.' ||
                      EXTRACT(MONTH FROM DATECREATE) || '.' ||
                      EXTRACT(YEAR FROM DATECREATE);
       IF (DATERESV > DATECI) THEN DATERESV = DATECI-3;
       SUSPEND;
    END
  END
END^


ALTER PROCEDURE EC_FODSR(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    HOTELID VARCHAR(4),
    FODATE DATE,
    LISTINDEX INTEGER,
    DSR_ID INTEGER,
    TEXT VARCHAR(40),
    AMOUNT DOUBLE PRECISION,
    TODAY DOUBLE PRECISION,
    ADJUSTMENT DOUBLE PRECISION,
    ADJUST_TEXT VARCHAR(80),
    MTD DOUBLE PRECISION,
    YTD DOUBLE PRECISION,
    MTD_BUDGET DOUBLE PRECISION,
    YTD_BUDGET DOUBLE PRECISION,
    MTD_FORECAST DOUBLE PRECISION,
    YTD_FORECAST DOUBLE PRECISION,
    MTD_VARIANCE DOUBLE PRECISION,
    YTD_VARIANCE DOUBLE PRECISION,
    LAST_MTD DOUBLE PRECISION,
    LAST_YTD DOUBLE PRECISION,
    LASTYEAR_MTD DOUBLE PRECISION,
    BOLD INTEGER,
    FONTSIZE INTEGER,
    COMMAND VARCHAR(8),
    POSTED INTEGER,
    BORDER_TOP INTEGER,
    BORDER_BOTTOM INTEGER,
    BLANWHENZERO INTEGER,
    TODAYONLY INTEGER,
    MTD_VAR_PERCENT_BUDGET DOUBLE PRECISION,
    YTD_VAR_PERCENT_BUDGET DOUBLE PRECISION)
AS
BEGIN
   SELECT DATA FROM INIFILE WHERE FILENAME='ECOS' AND IDENTITY='HotelID'
    INTO HOTELID;
    if (HOTELID IS NULL) then HOTELID='?';
    FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
     BEGIN
  FOR
    SELECT FODATE,
         LISTINDEX,
         DSR_ID,
         TEXT,
         AMOUNT,
         TODAY,
         ADJUSTMENT,
         ADJUST_TEXT,
         MTD,
         YTD,
         MTD_BUDGET,
         YTD_BUDGET,
         MTD_FORECAST,
         YTD_FORECAST,
         MTD_VARIANCE,
         YTD_VARIANCE,
         LAST_MTD,
         LAST_YTD,
         LASTYEAR_MTD,
         BOLD,
         FONTSIZE,
         COMMAND,
         POSTED,
         BORDER_TOP,
         BORDER_BOTTOM,
         BLANWHENZERO,
         TODAYONLY,
         MTD_VAR_PERCENT_BUDGET,
         YTD_VAR_PERCENT_BUDGET FROM FO_DSR_VIEW(:FODATE)
    INTO :FODATE,
         :LISTINDEX,
         :DSR_ID,
         :TEXT,
         :AMOUNT,
         :TODAY,
         :ADJUSTMENT,
         :ADJUST_TEXT,
         :MTD,
         :YTD,
         :MTD_BUDGET,
         :YTD_BUDGET,
         :MTD_FORECAST,
         :YTD_FORECAST,
         :MTD_VARIANCE,
         :YTD_VARIANCE,
         :LAST_MTD,
         :LAST_YTD,
         :LASTYEAR_MTD,
         :BOLD,
         :FONTSIZE,
         :COMMAND,
         :POSTED,
         :BORDER_TOP,
         :BORDER_BOTTOM,
         :BLANWHENZERO,
         :TODAYONLY,
         :MTD_VAR_PERCENT_BUDGET,
         :YTD_VAR_PERCENT_BUDGET
         DO
         BEGIN
    SUSPEND;
      FODATE = FODATE + 1;
  END
END
END^


ALTER PROCEDURE EC_FORS(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    HOTELID VARCHAR(4),
    FODATE DATE,
    LISTINDEX INTEGER,
    TEXT VARCHAR(40),
    TODAY DOUBLE PRECISION,
    MTD DOUBLE PRECISION,
    YTD DOUBLE PRECISION,
    L_MTD DOUBLE PRECISION,
    L_YTD DOUBLE PRECISION,
    BUDGET_MTD DOUBLE PRECISION,
    BUDGET_YTD DOUBLE PRECISION,
    FORECAST_MTD DOUBLE PRECISION,
    FORECAST_YTD DOUBLE PRECISION,
    VARIANCE_MTD DOUBLE PRECISION,
    VARIANCE_YTD DOUBLE PRECISION,
    BOLD SMALLINT,
    VISIBLE SMALLINT,
    FORMAT VARCHAR(40),
    INFO VARCHAR(40),
    WEB INTEGER)
AS
BEGIN
    SELECT DATA FROM INIFILE WHERE FILENAME='ECOS' AND IDENTITY='HotelID'
    INTO HOTELID;
    if (HOTELID IS NULL) then HOTELID='?';

    FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
     BEGIN
  FOR
    SELECT LISTINDEX,
         TEXT,
         TODAY,
         MTD,
         YTD,
         L_MTD,
         L_YTD,
         BUDGET_MTD,
         BUDGET_YTD,
         FORECAST_MTD,
         FORECAST_YTD,
         VARIANCE_MTD,
         VARIANCE_YTD,
         BOLD,
         VISIBLE,
         FORMAT,
         INFO,
         WEB FROM FO_RS_VIEW(:FODATE)
    INTO :LISTINDEX,
         :TEXT,
         :TODAY,
         :MTD,
         :YTD,
         :L_MTD,
         :L_YTD,
         :BUDGET_MTD,
         :BUDGET_YTD,
         :FORECAST_MTD,
         :FORECAST_YTD,
         :VARIANCE_MTD,
         :VARIANCE_YTD,
         :BOLD,
         :VISIBLE,
         :FORMAT,
         :INFO,
         :WEB
  DO
  BEGIN
    SUSPEND;

  END
   FODATE = FODATE + 1;
END
END^


