ALTER PROCEDURE FO_COUNT_RTYPE
RETURNS (
    ROOMTYPE VARCHAR(4),
    NAME VARCHAR(40),
    TOTROOM DOUBLE PRECISION,
    PAX DOUBLE PRECISION,
    CHILD DOUBLE PRECISION,
    HU DOUBLE PRECISION,
    COMPL DOUBLE PRECISION)
AS
begin
  FOR SELECT ROOMTYPE, NAME FROM FOROOMTYPE
  INTO : ROOMTYPE, :NAME
  DO BEGIN
     SELECT COUNT(*),SUM(PAX),SUM(CHILD) FROM FOGUEST
     WHERE FOLIOTYPE='P'
     AND FOLIOSTATUS='I'
     AND FOLIOSTATUS_SHARE='M'
     AND ROOMTYPE=:ROOMTYPE
     INTO :TOTROOM,:PAX,:CHILD ;
     if (TOTROOM IS NULL ) then TOTROOM=0 ;
     if (PAX IS NULL) then PAX=0;
     if (CHILD IS NULL) then CHILD=0 ;
     
     SELECT COUNT(RATECODE) FROM FOGUEST
     WHERE FOLIOTYPE='P'
     AND FOLIOSTATUS='I'
     AND FOLIOSTATUS_SHARE='M'
     AND ROOMTYPE=:ROOMTYPE
     AND RATECODE='HU'
     INTO :HU ;
     if (HU IS NULL) then HU=0;

     SELECT COUNT(RATECODE) FROM FOGUEST
     WHERE FOLIOTYPE='P'
     AND FOLIOSTATUS='I'
     AND FOLIOSTATUS_SHARE='M'
     AND ROOMTYPE=:ROOMTYPE
     AND RATECODE='COMPL'
     INTO :COMPL ;
     if (COMPL IS NULL) then COMPL=0;

     if (TOTROOM>0) then suspend;
  END
end^


ALTER PROCEDURE FO_CREDITLIMIT
RETURNS (
    FOLIOTYPE CHAR(1),
    ROOM VARCHAR(8),
    FOLIO INTEGER,
    TYPENAME VARCHAR(30),
    GROUPNUMBER INTEGER,
    FOLIOSTATUS CHAR(1),
    FULLNAMEF VARCHAR(80),
    DATECI DATE,
    DATECO DATE,
    COMPANYNAME VARCHAR(40),
    PAYMENTCODE VARCHAR(4),
    CREDITLIMIT DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    OVER DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT FOLIOTYPE,ROOM,FOLIO,GROUPNUMBER,FOLIOSTATUS,
           FULLNAMEF,DATECI,DATECO,
           COMPANYNAME,PAYMENTCODE,
           CREDITLIMIT,BALANCE
    FROM FOGUEST
    WHERE  CREDITLIMIT<>0
       OR  BALANCE<>0
       OR  (BALANCE-CREDITLIMIT) <>0
    /*WHERE (CREDITLIMIT <> 0)*/
    /*AND (BALANCE > CREDITLIMIT)*/
    ORDER BY FOLIOTYPE DESC,ROOM

    INTO
      :FOLIOTYPE,
      :ROOM,
      :FOLIO,
      :GROUPNUMBER,
      :FOLIOSTATUS,
      :FULLNAMEF,
      :DATECI,
      :DATECO,
      :COMPANYNAME,
      :PAYMENTCODE,
      :CREDITLIMIT,
      :BALANCE

  DO
  BEGIN
    if (:FOLIOTYPE='P') then TYPENAME='Personal';
    else if (:FOLIOTYPE='G') then TYPENAME='Group / Mice';
    else if (:FOLIOTYPE='H') then TYPENAME='House Folio ';
    
    if(:BALANCE>:CREDITLIMIT) then OVER=:BALANCE-CREDITLIMIT ;
    ELSE OVER=0;
    if (:FOLIOSTATUS IN('I','A','S')) then SUSPEND;
  END
END^


