ALTER PROCEDURE FO_GUEST_CHANGE_MICE_MEMBER(
    FOLIO INTEGER,
    NEW_ROOM VARCHAR(8),
    NEW_DATECI DATE,
    NEW_DATECO DATE,
    FLAG_UPDATE_ROOMBLOCKING INTEGER,
    REASON VARCHAR(40),
    USRID VARCHAR(8))
AS
DECLARE VARIABLE GROUPNUMBER INTEGER;
DECLARE VARIABLE OLD_ROOM VARCHAR(8);
DECLARE VARIABLE OLD_ROOMTYPE VARCHAR(4);
DECLARE VARIABLE NEW_ROOMTYPE VARCHAR(4);
DECLARE VARIABLE OLD_DATECI DATE;
DECLARE VARIABLE OLD_DATECO DATE;
DECLARE VARIABLE XDATE DATE;
DECLARE VARIABLE BLOCKED INTEGER;
DECLARE VARIABLE FOSYSDATE DATE;
DECLARE VARIABLE REMARK VARCHAR(80);
DECLARE VARIABLE FOLIOSTATUS CHAR(1);
BEGIN
  /* ----------------------------------------------------------------- */
  /* 19 OCTOBER 2006, MELIA BENOA                                      */
  /* ----------------------------------------------------------------- */
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;
  
  
  
  /* ---------------------------------------------------------------- */
  /* GUEST PROFILE                                                    */
  /* ---------------------------------------------------------------- */
  SELECT GROUPNUMBER, DATECI, DATECO, ROOM, FOLIOSTATUS FROM FOGUEST
  WHERE FOLIO = :FOLIO
  INTO GROUPNUMBER, OLD_DATECI, OLD_DATECO, OLD_ROOM, FOLIOSTATUS;
  
  
  
  /* ---------------------------------------------------------------- */
  /* VALIDATE DATE CHECK IN                                           */
  /* ---------------------------------------------------------------- */
  IF (OLD_DATECI < FOSYSDATE) THEN OLD_DATECI = FOSYSDATE;
  IF (NEW_DATECI < FOSYSDATE) THEN NEW_DATECI = FOSYSDATE;
  
  
  
  /* ---------------------------------------------------------------- */
  /* ROOM TYPE                                                        */
  /* ---------------------------------------------------------------- */
  SELECT ROOMTYPE FROM FOROOM WHERE ROOM = :OLD_ROOM INTO OLD_ROOMTYPE;
  SELECT ROOMTYPE FROM FOROOM WHERE ROOM = :NEW_ROOM INTO NEW_ROOMTYPE;
  
  

  /* ---------------------------------------------------------------- */
  /* TAMBAH BLOCKING UNTUK ROOM TYPE YANG BARU                        */
  /* ---------------------------------------------------------------- */
  IF ((FLAG_UPDATE_ROOMBLOCKING = 1) AND (OLD_ROOMTYPE <> NEW_ROOMTYPE)) THEN
  BEGIN
     XDATE = NEW_DATECI;
     WHILE (XDATE < NEW_DATECO) DO
     BEGIN
        SELECT BLOCKED FROM FORI_GROUP
        WHERE FOLIO = :GROUPNUMBER
        AND ROOMTYPE = :NEW_ROOMTYPE
        AND FODATE = :XDATE
        INTO :BLOCKED;
        
        IF (BLOCKED IS NULL) THEN BLOCKED = 0;
        BLOCKED = BLOCKED + 1;
        REMARK = 'Follio#' ||:FOLIO|| ' move from ' ||
                 :OLD_ROOM || '(' || OLD_ROOMTYPE || ') to ' ||
                 :OLD_ROOM || '(' || NEW_ROOMTYPE || ')';

        SELECT BLOCK FROM FO_RI_SAVE_GROUP(:GROUPNUMBER, :NEW_ROOMTYPE,
                :XDATE, :BLOCKED, :USRID, :REMARK)
        INTO BLOCKED;
                

                
                
                
                
        XDATE = XDATE + 1;
     END
  END
  
  
  
  

  /* ----------------------------------------------------------------- */
  /* UPDATE GUEST PROFILE TO NEW DATA                                  */
  /* ----------------------------------------------------------------- */
  IF (FOLIOSTATUS <> 'I') THEN
     UPDATE FOGUEST SET ROOMTYPE = :NEW_ROOMTYPE, ROOM = :NEW_ROOM,
            DATECI = :NEW_DATECI, DATECO = :NEW_DATECO,
            USEREDIT = :USRID
     WHERE FOLIO = :FOLIO;
  ELSE
     UPDATE FOGUEST SET ROOMTYPE = :NEW_ROOMTYPE, ROOM = :NEW_ROOM,
            DATECO = :NEW_DATECO,
            OLD_ROOM = :OLD_ROOM,
            OLD_ROOM_REASON = :REASON,
            USEREDIT = :USRID
     WHERE FOLIO = :FOLIO;

  
  
  
  /* ---------------------------------------------------------------- */
  /* KURANGI BLOCKING UNTUK ROOM TYPE YANG LAMA                       */
  /* ---------------------------------------------------------------- */
  IF ((FLAG_UPDATE_ROOMBLOCKING = 1) AND (OLD_ROOMTYPE <> NEW_ROOMTYPE)) THEN
  BEGIN
     XDATE = OLD_DATECI;
     WHILE (XDATE < OLD_DATECO) DO
     BEGIN
        SELECT BLOCKED FROM FORI_GROUP
        WHERE FOLIO = :GROUPNUMBER
        AND ROOMTYPE = :OLD_ROOMTYPE
        AND FODATE = :XDATE
        INTO :BLOCKED;

        IF (BLOCKED IS NULL) THEN BLOCKED = 0;
        BLOCKED = BLOCKED - 1;

        REMARK = 'Follio#' ||:FOLIO|| ' move from ' ||
                 :OLD_ROOM || '(' || OLD_ROOMTYPE || ') to ' ||
                 :OLD_ROOM || '(' || NEW_ROOMTYPE || ')';
                 
        EXECUTE PROCEDURE FO_RI_SAVE_GROUP(:GROUPNUMBER, :OLD_ROOMTYPE,
                :XDATE, :BLOCKED, :USRID, :REMARK)
        RETURNING_VALUES :BLOCKED;






        XDATE = XDATE + 1;
     END
  END
END^


