ALTER PROCEDURE FO_INIT_FILL_DEFAULT
AS
begin
  /* ------------------------------------------------------------------------ */
  /* TRANSACTION CODE                                                         */
  /* ------------------------------------------------------------------------ */
  INSERT INTO FOJUR_CODE (JURCODE,NAME,FLAG_CORRECTION,FLAG_TRANSFER,FLAG_TAX,FLAG_SEARCHFOLIO,FLAG_AR_DETAIL,FLAG_CASHIER_LOG)
  VALUES ('BO','Back Office Correction',0,0,0,0,0,0);
  
  INSERT INTO FOJUR_CODE  (JURCODE,NAME,FLAG_CORRECTION,FLAG_TRANSFER,FLAG_TAX,FLAG_SEARCHFOLIO,FLAG_AR_DETAIL,FLAG_CASHIER_LOG)
  VALUES ('CHG','Charge',1,1,1,1,1,1);

