ALTER PROCEDURE FO_MEAL_COUPON_BREAKFAST(
    FOLIO INTEGER)
RETURNS (
    GUESTNAME VARCHAR(80),
    ROOM VARCHAR(8),
    PAX SMALLINT,
    FODATE DATE,
    DATECI DATE,
    DATECO DATE,
    COMPANY VARCHAR(6),
    PAX_REMARK VARCHAR(40),
    COMPANYNAME VARCHAR(40))
AS
declare variable ipax integer;
BEGIN
  select FULLNAMEF,room,pax,folio,dateci,dateco,companyname,company
  from foguest
  where folio = :folio
  INTO :GUESTNAME,:ROOM,:PAX,:FOLIO,:DATECI,:DATECO,:COMPANYNAME,:COMPANY;

  IF (DATECI IS NOT NULL) THEN
  BEGIN
  FODATE = DATECI+1;
  WHILE (FODATE <= DATECO) DO
    BEGIN
      IPAX = 1;
      WHILE (IPAX <= PAX) DO
      BEGIN
        PAX_REMARK = IPAX || ' of ' || PAX;
        SUSPEND;
        IPAX = IPAX + 1;
      END
      FODATE = FODATE + 1;
    END
  END
END^


