ALTER PROCEDURE FO_RPT_FOLIO_HISTORY(
    PFOLIO INTEGER)
RETURNS (
    FOLIO INTEGER,
    FODATE DATE,
    CATEGORY VARCHAR(4),
    NAME VARCHAR(40),
    REMARK VARCHAR(40),
    REFERENCE VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    LINE INTEGER,
    USERID VARCHAR(8),
    JURCODE VARCHAR(3),
    HIDDEN INTEGER,
    SOURCE CHAR(4),
    SOURCE_ID INTEGER,
    TRANS_ID INTEGER)
AS
declare variable FOLIO_ORG INTEGER;
BEGIN

  if (PFOLIO < 0) then /* JIKA STATISTIC */
  BEGIN
     FOLIO     = -PFOLIO;
     FOLIO_ORG = FOLIO;
     PFOLIO    = -1;
  END
  ELSE
  BEGIN
    FOLIO = PFOLIO;
    FOLIO_ORG = -1;
  END
  /* ------------------------------------------------------------------------ */
  /* MENAMPILKAN FOLIO BAIK YANG ADA DI CURRENT TABLE FOGUEST_JUR             */
  /* ATAU DARI TABLE HISTORY FO_HIST_JUR                                      */
  /* ------------------------------------------------------------------------ */  
  BALANCE = 0;
  LINE = 0;
  FOR SELECT JR.FODATE, JR.CATEGORY, CAT.NAME,
             JR.REMARK, JR.REFERENCE,
             JR.DEBIT, JR.CREDIT,
             JR.USERENTRY, JR.JURCODE, JR.HIDDEN, JR.SOURCE, JR.SOURCE_ID,
             JR.TRANS_ID /* 11/8/2011 */
  FROM FOGUEST_JUR JR
  LEFT JOIN focategory CAT ON CAT.CATEGORY = JR.CATEGORY
  WHERE FOLIO = :PFOLIO  /* folio transaction*/
  or (FOLIO_ORIGINAL = :FOLIO_ORG) /* FOLIO STATISTIC */
  ORDER BY JR.FODATE, JR.TRANS_ID
  INTO  :FODATE,   :CATEGORY, :NAME,
        :REMARK,   :REFERENCE,
        :DEBIT,    :CREDIT,
        :USERID,   :JURCODE, :HIDDEN,
        :SOURCE,   :SOURCE_ID,
        :TRANS_ID /* 11/8/2011 */
  DO BEGIN
     BALANCE = BALANCE + DEBIT - CREDIT;
     LINE = LINE + 1;
     SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* FOLIO DARI HISTORY                                                       */
  /* ------------------------------------------------------------------------ */
  FOR SELECT JR.FODATE, JR.CATEGORY, CAT.NAME,
             JR.REMARK, JR.REFERENCE,
             JR.DEBIT, JR.CREDIT,
             JR.USERENTRY, JR.JURCODE, JR.HIDDEN, JR.SOURCE, JR.SOURCE_ID,
             JR.TRANS_ID /* 11/8/2011 */
  FROM FO_HIST_JUR JR
  LEFT JOIN focategory CAT ON CAT.CATEGORY = JR.CATEGORY
  WHERE FOLIO = :PFOLIO /* folio transaction */
  or (FOLIO_ORIGINAL = :FOLIO_ORG) /* FOLIO STATISTIC */
  ORDER BY JR.FODATE, JR.TRANS_ID
  INTO  :FODATE,   :CATEGORY, :NAME,
        :REMARK,   :REFERENCE,
        :DEBIT,    :CREDIT,
        :USERID,   :JURCODE, :HIDDEN,
        :SOURCE,   :SOURCE_ID,
        :TRANS_ID
  DO BEGIN
     BALANCE = BALANCE + DEBIT - CREDIT;
     LINE = LINE + 1;
     SUSPEND;
  END
END^


