ALTER PROCEDURE FO_RPT_MEMBER_VIOLA(
    PFODATE DATE,
    PMEMBERTYPE VARCHAR(4))
RETURNS (
    FOLIO INTEGER,
    MEMBER VARCHAR(20),
    FIRSTNAME VARCHAR(40),
    LASTNAME VARCHAR(40),
    CHECK_IN DATE,
    CHECK_OUT DATE,
    ROOM VARCHAR(8),
    ROOMTYPE VARCHAR(4),
    ADULT SMALLINT,
    CHILD SMALLINT,
    TOTAL_ROOM_SPEND DOUBLE PRECISION,
    TOTAL_MISC_SPEND DOUBLE PRECISION)
AS
DECLARE VARIABLE HISTORY INTEGER;
DECLARE VARIABLE FODATE DATE;
BEGIN
  FOR
    SELECT L.FODATE,L.FOLIO,L.MEMBER,L.ROOM,L.ROOMTYPE,L.PAX,L.CHILD
    FROM FOSTAT_LOG L
    INNER JOIN FOMEMBER M ON M.MEMBER = L.MEMBER
    WHERE L.FODATE = :PFODATE
    AND L.FOLIOSTATUS = 'O'
    AND L.FOLIOSTATUS_SHARE = 'M'
    AND L.MEMBER <> ''
    AND M.MEMBERTYPE = :PMEMBERTYPE
    INTO FODATE,:FOLIO,:MEMBER,:ROOM,:ROOMTYPE,:ADULT,:CHILD
  DO
  BEGIN

     IF (EXISTS(SELECT * FROM FOGUEST WHERE FOLIO=:FOLIO)) THEN
     BEGIN
        SELECT FNAME,LNAME,DATECI,DATECO FROM FOGUEST
        WHERE FOLIO = :FOLIO
        INTO FIRSTNAME,LASTNAME,CHECK_IN,CHECK_OUT;
     END
     ELSE
     BEGIN
        SELECT HISTORY,DATECI,DATECO FROM fo_hist_stay
        WHERE FOLIO = :FOLIO
        INTO :HISTORY,CHECK_IN,CHECK_OUT;

        SELECT FNAME,LNAME
        FROM fo_hist_guest
        WHERE HISTORY = :HISTORY
        INTO FIRSTNAME,LASTNAME;
     END
     IF (FODATE = CHECK_OUT) THEN
     BEGIN
        SELECT SUM(L.CHARGE_CLASS1),SUM(L.TOTAL_REVENUE-L.CHARGE_CLASS2)
        FROM FOSTAT_LOG L
        WHERE FOLIO = :FOLIO
        INTO :TOTAL_ROOM_SPEND,:TOTAL_MISC_SPEND;
        SUSPEND;
     END
  END
END^


ALTER PROCEDURE FO_RPT_MICE_SEGMENT(
    SDATE DATE,
    EDATE DATE,
    PDATATYPE VARCHAR(4))
RETURNS (
    DATATYPE VARCHAR(4),
    COMPANY VARCHAR(6),
    NAME VARCHAR(40),
    NIGHT INTEGER,
    TOTAL_REVENUE DOUBLE PRECISION,
    TOTAL_RATE DOUBLE PRECISION,
    AVG_RATE DOUBLE PRECISION)
AS
BEGIN
  if (SDATE IS NULL) then
  BEGIN
     SDATE = '1.1.2007';
     EDATE = '31.1.2007';
     PDATATYPE = 'CO';
  END
  DATATYPE = 'AL';
  if (PDATATYPE = 'AL') THEN
  FOR
    select L.COMPANY,C.NAME,SUM(NIGHT) NIGHT,
          SUM(CHARGE_CLASS1+CHARGE_CLASS2+CHARGE_CLASS3+ CHARGE_CLASS4+CHARGE_CLASS5+CHARGE_CLASS6+ CHARGE_CLASS7+CHARGE_CLASS8+CHARGE_CLASS9+ CHARGE_CLASS0) TOTAL_REVENUE,
          SUM(RATE_TOTAL) TOTAL_RATE
    from fostat_log L
    INNER JOIN SYSCUSTOMER C ON C.CUSTOMER = L.COMPANY
    WHERE L.FODATE BETWEEN :SDATE AND :EDATE
    AND FOLIOTYPE = 'P'
    AND (L.GROUPNUMBER <> 0)
    GROUP BY L.COMPANY,C.NAME
    INTO
      :COMPANY,
      :NAME,
      :NIGHT,
      :TOTAL_REVENUE,
      :TOTAL_RATE
  DO
  BEGIN
    if (NIGHT <> 0) then
    BEGIN
      AVG_RATE = TOTAL_RATE / NIGHT;
      SUSPEND;
    END
  END
  DATATYPE = 'CO';
  
  if (PDATATYPE = 'CO') THEN
  FOR
    select L.COMPANY,C.NAME,SUM(NIGHT) NIGHT,
          SUM(CHARGE_CLASS1+CHARGE_CLASS2+CHARGE_CLASS3+ CHARGE_CLASS4+CHARGE_CLASS5+CHARGE_CLASS6+ CHARGE_CLASS7+CHARGE_CLASS8+CHARGE_CLASS9+ CHARGE_CLASS0) TOTAL_REVENUE,
          SUM(RATE_TOTAL) TOTAL_RATE
    from fostat_log L
    INNER JOIN SYSCUSTOMER C ON C.CUSTOMER = L.COMPANY
    WHERE L.FODATE BETWEEN :SDATE AND :EDATE
    AND FOLIOTYPE = 'P'
    AND (L.GROUPNUMBER = 0)
    GROUP BY L.COMPANY,C.NAME
    INTO
      :COMPANY,
      :NAME,
      :NIGHT,
      :TOTAL_REVENUE,
      :TOTAL_RATE
  DO
  BEGIN
    if (NIGHT <> 0) then
    BEGIN
      AVG_RATE = TOTAL_RATE / NIGHT;
      SUSPEND;
    END
  END  
END^


