ALTER PROCEDURE FO_RPT_MK_SALES_FIT_SEG(
    PMONTH INTEGER,
    PYEAR INTEGER,
    PSSALESMAN VARCHAR(8),
    PESALESMAN VARCHAR(8))
RETURNS (
    PERIOD DATE,
    COMPANY VARCHAR(6),
    COMPANY_NAME VARCHAR(40),
    SEG VARCHAR(4),
    SEG_NAME VARCHAR(40),
    SALESMAN VARCHAR(8),
    MTD_NIGHT_FIT INTEGER,
    MTD_NIGHT INTEGER,
    MTD_ROOMRATE DOUBLE PRECISION,
    MTD_ROOMRATE_FIT DOUBLE PRECISION,
    MTD_ROOMREVENUE DOUBLE PRECISION,
    MTD_ROOMREVENUE_FIT DOUBLE PRECISION,
    MTD_TOTALREVENUE DOUBLE PRECISION,
    MTD_TOTALREVENUE_FIT DOUBLE PRECISION,
    MTD_PACKAGE DOUBLE PRECISION,
    MTD_PACKAGE_FIT DOUBLE PRECISION,
    MTD_REVENUE_OTHERS DOUBLE PRECISION,
    MTD_AVG_ROOMRATE DOUBLE PRECISION,
    MTD_AVG_ROOMREVENUE DOUBLE PRECISION,
    YTD_NIGHT INTEGER,
    YTD_NIGHT_FIT INTEGER,
    YTD_ROOMRATE DOUBLE PRECISION,
    YTD_ROOMRATE_FIT DOUBLE PRECISION,
    YTD_ROOMREVENUE DOUBLE PRECISION,
    YTD_ROOMREVENUE_FIT DOUBLE PRECISION,
    YTD_TOTALREVENUE DOUBLE PRECISION,
    YTD_TOTALREVENUE_FIT DOUBLE PRECISION,
    YTD_PACKAGE DOUBLE PRECISION,
    YTD_PACKAGE_FIT DOUBLE PRECISION,
    YTD_REVENUE_OTHERS DOUBLE PRECISION,
    YTD_AVG_ROOMRATE DOUBLE PRECISION,
    YTD_AVG_ROOMREVENUE DOUBLE PRECISION)
AS
DECLARE VARIABLE TOT_YTD INTEGER;
DECLARE VARIABLE TOT_MTD INTEGER;
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
    PYEAR = 2006;
    PMONTH = 5;
  END

  PERIOD = '1.'||PMONTH||'.'||PYEAR;

  IF (TOT_MTD IS NULL) THEN TOT_MTD = 0;
  IF (TOT_YTD IS NULL) THEN TOT_MTD = 0;

  FOR SELECT L.ST_MARKETSEGMENT,S.NAME,L.COMPANY,T.NAME,L.SALESMAN,
             SUM(L.NIGHT),
             SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),SUM(L.PACKAGE)
      FROM FOSTAT_LOG L
      INNER JOIN SYSCUSTOMER T ON T.CUSTOMER = L.COMPANY
      INNER JOIN FOST_SEGMENT S ON S.CODE = L.ST_MARKETSEGMENT
      WHERE L.PYEAR = :PYEAR AND L.PMONTH <= :PMONTH
      AND L.RATECODE <> 'HU'
      AND L.SALESMAN BETWEEN :PSSALESMAN AND :PESALESMAN
      AND L.ST_MARKETSEGMENT IN ('FAI','FCO','FEM','FOT','FGV','FSB','FTA')
      GROUP BY L.SALESMAN,L.ST_MARKETSEGMENT,S.NAME,L.COMPANY,T.NAME
  INTO SEG,SEG_NAME,COMPANY,COMPANY_NAME,SALESMAN,YTD_NIGHT,
       YTD_ROOMRATE,YTD_ROOMREVENUE,YTD_PACKAGE
  DO
  BEGIN
    IF (YTD_NIGHT + YTD_ROOMRATE + YTD_ROOMRATE <> 0) THEN
    BEGIN
      /* ---------------------------------------------------------------- */
      /* FIT                                                              */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH = :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT IN ('FAI','FCO','FEM','FOT','FGV','FSB','FTA')
      AND L.RATECODE <> 'HU'
      AND L.SALESMAN = :SALESMAN
      AND L.GROUPNUMBER = 0
      INTO MTD_NIGHT_FIT,MTD_ROOMRATE_FIT,MTD_ROOMREVENUE_FIT,
           MTD_PACKAGE_FIT,MTD_TOTALREVENUE_FIT;


      IF (MTD_NIGHT_FIT IS NULL) THEN
      BEGIN
         MTD_NIGHT_FIT = 0;
         MTD_ROOMRATE_FIT = 0;
         MTD_ROOMREVENUE_FIT = 0;
         MTD_PACKAGE_FIT = 0;
         MTD_TOTALREVENUE_FIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* TOTAL MTD                                                        */
      /* ---------------------------------------------------------------- */
      MTD_NIGHT = MTD_NIGHT_FIT;
      MTD_ROOMRATE = MTD_ROOMRATE_FIT;
      MTD_ROOMREVENUE = MTD_ROOMREVENUE_FIT;
      MTD_PACKAGE = MTD_PACKAGE_FIT;
      MTD_TOTALREVENUE = MTD_TOTALREVENUE_FIT;

      /* ---------------------------------------------------------------- */
      /* YTD FIT                                                          */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH <= :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT IN ('FAI','FCO','FEM','FOT','FGV','FSB','FTA')
      AND L.RATECODE <> 'HU'
      AND L.SALESMAN = :SALESMAN
      AND L.GROUPNUMBER = 0
      INTO YTD_NIGHT_FIT,YTD_ROOMRATE_FIT,YTD_ROOMREVENUE_FIT,
           YTD_PACKAGE_FIT,YTD_TOTALREVENUE_FIT;


      IF (YTD_NIGHT_FIT IS NULL) THEN
      BEGIN
         YTD_NIGHT_FIT = 0;
         YTD_ROOMRATE_FIT = 0;
         YTD_ROOMREVENUE_FIT = 0;
         YTD_PACKAGE_FIT = 0;
         YTD_TOTALREVENUE_FIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* TOTAL YTD                                                        */
      /* ---------------------------------------------------------------- */
      YTD_NIGHT = YTD_NIGHT_FIT;
      YTD_ROOMRATE = YTD_ROOMRATE_FIT;
      YTD_ROOMREVENUE = YTD_ROOMREVENUE_FIT;
      YTD_PACKAGE = YTD_PACKAGE_FIT;
      YTD_TOTALREVENUE = YTD_TOTALREVENUE_FIT;

      /* ---------------------------------------------------------------- */

      IF (YTD_NIGHT <> 0) THEN YTD_AVG_ROOMRATE = YTD_ROOMRATE/YTD_NIGHT;
      ELSE YTD_AVG_ROOMRATE = 0;

      IF (MTD_NIGHT <> 0) THEN MTD_AVG_ROOMRATE = MTD_ROOMRATE/MTD_NIGHT;
      ELSE MTD_AVG_ROOMRATE = 0;

      IF (YTD_NIGHT <> 0) THEN YTD_AVG_ROOMREVENUE = YTD_ROOMREVENUE/YTD_NIGHT;
      ELSE YTD_AVG_ROOMREVENUE = 0;

      IF (MTD_NIGHT <> 0) THEN MTD_AVG_ROOMREVENUE = MTD_ROOMREVENUE/MTD_NIGHT;
      ELSE MTD_AVG_ROOMREVENUE = 0;

      MTD_REVENUE_OTHERS = MTD_TOTALREVENUE - MTD_ROOMREVENUE - MTD_PACKAGE;
      YTD_REVENUE_OTHERS = YTD_TOTALREVENUE - YTD_ROOMREVENUE - YTD_PACKAGE;
      SUSPEND;
    END
  END
END^


ALTER PROCEDURE FO_RPT_MK_SALES_GIT_SEG(
    PMONTH INTEGER,
    PYEAR INTEGER,
    PSSALESMAN VARCHAR(8),
    PESALESMAN VARCHAR(8))
RETURNS (
    PERIOD DATE,
    COMPANY VARCHAR(6),
    COMPANY_NAME VARCHAR(40),
    SEG VARCHAR(4),
    SEG_NAME VARCHAR(40),
    SALESMAN VARCHAR(8),
    MTD_NIGHT_GIT INTEGER,
    MTD_NIGHT INTEGER,
    MTD_ROOMRATE DOUBLE PRECISION,
    MTD_ROOMRATE_GIT DOUBLE PRECISION,
    MTD_ROOMREVENUE DOUBLE PRECISION,
    MTD_ROOMREVENUE_GIT DOUBLE PRECISION,
    MTD_TOTALREVENUE DOUBLE PRECISION,
    MTD_TOTALREVENUE_GIT DOUBLE PRECISION,
    MTD_PACKAGE DOUBLE PRECISION,
    MTD_PACKAGE_GIT DOUBLE PRECISION,
    MTD_REVENUE_OTHERS DOUBLE PRECISION,
    MTD_AVG_ROOMRATE DOUBLE PRECISION,
    MTD_AVG_ROOMREVENUE DOUBLE PRECISION,
    YTD_NIGHT INTEGER,
    YTD_NIGHT_GIT INTEGER,
    YTD_ROOMRATE DOUBLE PRECISION,
    YTD_ROOMRATE_GIT DOUBLE PRECISION,
    YTD_ROOMREVENUE DOUBLE PRECISION,
    YTD_ROOMREVENUE_GIT DOUBLE PRECISION,
    YTD_TOTALREVENUE DOUBLE PRECISION,
    YTD_TOTALREVENUE_GIT DOUBLE PRECISION,
    YTD_PACKAGE DOUBLE PRECISION,
    YTD_PACKAGE_GIT DOUBLE PRECISION,
    YTD_REVENUE_OTHERS DOUBLE PRECISION,
    YTD_AVG_ROOMRATE DOUBLE PRECISION,
    YTD_AVG_ROOMREVENUE DOUBLE PRECISION)
AS
DECLARE VARIABLE TOT_YTD INTEGER;
DECLARE VARIABLE TOT_MTD INTEGER;
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
    PYEAR = 2006;
    PMONTH = 5;
  END

  PERIOD = '1.'||PMONTH||'.'||PYEAR;

  IF (TOT_MTD IS NULL) THEN TOT_MTD = 0;
  IF (TOT_YTD IS NULL) THEN TOT_MTD = 0;

  FOR SELECT L.ST_MARKETSEGMENT,S.NAME,L.COMPANY,T.NAME,L.SALESMAN,
             SUM(L.NIGHT),
             SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),SUM(L.PACKAGE)
      FROM FOSTAT_LOG L
      INNER JOIN SYSCUSTOMER T ON T.CUSTOMER = L.COMPANY
      INNER JOIN FOST_SEGMENT S ON S.CODE = L.ST_MARKETSEGMENT
      WHERE L.PYEAR = :PYEAR AND L.PMONTH <= :PMONTH
      AND L.RATECODE <> 'HU'
      AND L.SALESMAN BETWEEN :PSSALESMAN AND :PESALESMAN
      AND L.ST_MARKETSEGMENT IN ('GCR','GCO','GGV','GTA')
      GROUP BY L.SALESMAN,L.ST_MARKETSEGMENT,S.NAME,L.COMPANY,T.NAME
  INTO SEG,SEG_NAME,COMPANY,COMPANY_NAME,SALESMAN,YTD_NIGHT,
       YTD_ROOMRATE,YTD_ROOMREVENUE,YTD_PACKAGE
  DO
  BEGIN
    IF (YTD_NIGHT + YTD_ROOMRATE + YTD_ROOMRATE <> 0) THEN
    BEGIN
      /* ---------------------------------------------------------------- */
      /* GIT                                                              */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH = :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT IN ('GCR','GCO','GGV','GTA')
      AND L.RATECODE <> 'HU'
      AND L.SALESMAN = :SALESMAN
      AND L.GROUPNUMBER <> 0
      INTO MTD_NIGHT_GIT,MTD_ROOMRATE_GIT,MTD_ROOMREVENUE_GIT,
           MTD_PACKAGE_GIT,MTD_TOTALREVENUE_GIT;


      IF (MTD_NIGHT_GIT IS NULL) THEN
      BEGIN
         MTD_NIGHT_GIT = 0;
         MTD_ROOMRATE_GIT = 0;
         MTD_ROOMREVENUE_GIT = 0;
         MTD_PACKAGE_GIT = 0;
         MTD_TOTALREVENUE_GIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* TOTAL MTD                                                        */
      /* ---------------------------------------------------------------- */
      MTD_NIGHT = MTD_NIGHT_GIT;
      MTD_ROOMRATE = MTD_ROOMRATE_GIT;
      MTD_ROOMREVENUE = MTD_ROOMREVENUE_GIT;
      MTD_PACKAGE = MTD_PACKAGE_GIT;
      MTD_TOTALREVENUE = MTD_TOTALREVENUE_GIT;
      /* ---------------------------------------------------------------- */
      /* YTD GIT                                                          */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH <= :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT IN ('GCR','GCO','GGV','GTA')
      AND L.RATECODE <> 'HU'
      AND L.SALESMAN = :SALESMAN
      AND L.GROUPNUMBER <> 0
      INTO YTD_NIGHT_GIT,YTD_ROOMRATE_GIT,YTD_ROOMREVENUE_GIT,
           YTD_PACKAGE_GIT,YTD_TOTALREVENUE_GIT;


      IF (YTD_NIGHT_GIT IS NULL) THEN
      BEGIN
         YTD_NIGHT_GIT = 0;
         YTD_ROOMRATE_GIT = 0;
         YTD_ROOMREVENUE_GIT = 0;
         YTD_PACKAGE_GIT = 0;
         YTD_TOTALREVENUE_GIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* TOTAL YTD                                                        */
      /* ---------------------------------------------------------------- */
      YTD_NIGHT = YTD_NIGHT_GIT;
      YTD_ROOMRATE = YTD_ROOMRATE_GIT;
      YTD_ROOMREVENUE = YTD_ROOMREVENUE_GIT;
      YTD_PACKAGE = YTD_PACKAGE_GIT;
      YTD_TOTALREVENUE = YTD_TOTALREVENUE_GIT;

      /* ---------------------------------------------------------------- */

      IF (YTD_NIGHT <> 0) THEN YTD_AVG_ROOMRATE = YTD_ROOMRATE/YTD_NIGHT;
      ELSE YTD_AVG_ROOMRATE = 0;

      IF (MTD_NIGHT <> 0) THEN MTD_AVG_ROOMRATE = MTD_ROOMRATE/MTD_NIGHT;
      ELSE MTD_AVG_ROOMRATE = 0;

      IF (YTD_NIGHT <> 0) THEN YTD_AVG_ROOMREVENUE = YTD_ROOMREVENUE/YTD_NIGHT;
      ELSE YTD_AVG_ROOMREVENUE = 0;

      IF (MTD_NIGHT <> 0) THEN MTD_AVG_ROOMREVENUE = MTD_ROOMREVENUE/MTD_NIGHT;
      ELSE MTD_AVG_ROOMREVENUE = 0;

      MTD_REVENUE_OTHERS = MTD_TOTALREVENUE - MTD_ROOMREVENUE - MTD_PACKAGE;
      YTD_REVENUE_OTHERS = YTD_TOTALREVENUE - YTD_ROOMREVENUE - YTD_PACKAGE;
      SUSPEND;
    END
  END
END^


