  IF (TOT_MTD IS NULL) THEN TOT_MTD = 0;
  IF (TOT_YTD IS NULL) THEN TOT_MTD = 0;

  FOR SELECT L.ST_MARKETSEGMENT,S.NAME,L.COMPANY,T.NAME,L.SALESMAN,
             SUM(L.NIGHT),
             SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),SUM(L.PACKAGE)
      FROM FOSTAT_LOG L
      LEFT JOIN SYSCUSTOMER T ON T.CUSTOMER = L.COMPANY
      LEFT JOIN FOST_SEGMENT S ON S.CODE = L.ST_MARKETSEGMENT
      WHERE L.PYEAR = :PYEAR AND L.PMONTH <= :PMONTH
      AND L.SALESMAN BETWEEN :PSSALESMAN AND :PESALESMAN
      AND L.RATECODE <> 'HU'
      GROUP BY L.SALESMAN,L.ST_MARKETSEGMENT,S.NAME,L.COMPANY,T.NAME
  INTO SEG,SEG_NAME,COMPANY,COMPANY_NAME,SALESMAN,YTD_NIGHT,
       YTD_ROOMRATE,YTD_ROOMREVENUE,YTD_PACKAGE
  DO
  BEGIN
    IF (YTD_NIGHT + YTD_ROOMRATE + YTD_ROOMRATE <> 0) THEN
    BEGIN
      /* ---------------------------------------------------------------- */
      /* FIT                                                              */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH = :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT = :SEG
      AND L.SALESMAN = :SALESMAN
      AND L.GROUPNUMBER = 0
      AND L.RATECODE <> 'HU'
      INTO MTD_NIGHT_FIT,MTD_ROOMRATE_FIT,MTD_ROOMREVENUE_FIT,
           MTD_PACKAGE_FIT,MTD_TOTALREVENUE_FIT;


      IF (MTD_NIGHT_FIT IS NULL) THEN
      BEGIN
         MTD_NIGHT_FIT = 0;
         MTD_ROOMRATE_FIT = 0;
         MTD_ROOMREVENUE_FIT = 0;
         MTD_PACKAGE_FIT = 0;
         MTD_TOTALREVENUE_FIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* GIT                                                              */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH = :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT = :SEG
      AND L.SALESMAN = :SALESMAN
      AND L.RATECODE <> 'HU'
      AND L.GROUPNUMBER <> 0
      INTO MTD_NIGHT_GIT,MTD_ROOMRATE_GIT,MTD_ROOMREVENUE_GIT,
           MTD_PACKAGE_GIT,MTD_TOTALREVENUE_GIT;


      IF (MTD_NIGHT_GIT IS NULL) THEN
      BEGIN
         MTD_NIGHT_GIT = 0;
         MTD_ROOMRATE_GIT = 0;
         MTD_ROOMREVENUE_GIT = 0;
         MTD_PACKAGE_GIT = 0;
         MTD_TOTALREVENUE_GIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* TOTAL MTD                                                        */
      /* ---------------------------------------------------------------- */
      MTD_NIGHT = MTD_NIGHT_FIT + MTD_NIGHT_GIT;
      MTD_ROOMRATE = MTD_ROOMRATE_FIT + MTD_ROOMRATE_GIT;
      MTD_ROOMREVENUE = MTD_ROOMREVENUE_FIT + MTD_ROOMREVENUE_GIT;
      MTD_PACKAGE = MTD_PACKAGE_FIT + MTD_PACKAGE_GIT;
      MTD_TOTALREVENUE = MTD_TOTALREVENUE_FIT + MTD_TOTALREVENUE_GIT;

      /* ---------------------------------------------------------------- */
      /* YTD FIT                                                          */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH <= :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT = :SEG
      AND L.SALESMAN = :SALESMAN
      AND L.GROUPNUMBER = 0
      AND L.RATECODE <> 'HU'
      INTO YTD_NIGHT_FIT,YTD_ROOMRATE_FIT,YTD_ROOMREVENUE_FIT,
           YTD_PACKAGE_FIT,YTD_TOTALREVENUE_FIT;


      IF (YTD_NIGHT_FIT IS NULL) THEN
      BEGIN
         YTD_NIGHT_FIT = 0;
         YTD_ROOMRATE_FIT = 0;
         YTD_ROOMREVENUE_FIT = 0;
         YTD_PACKAGE_FIT = 0;
         YTD_TOTALREVENUE_FIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* YTD GIT                                                          */
      /* ---------------------------------------------------------------- */
      SELECT SUM(L.NIGHT),SUM(L.ROOMRATE),SUM(L.RATE_ROOMONLY),
             SUM(L.PACKAGE),SUM(TOTAL_REVENUE)
      FROM FOSTAT_LOG L
      WHERE L.PYEAR = :PYEAR
      AND L.PMONTH <= :PMONTH
      AND L.COMPANY = :COMPANY
      AND L.ST_MARKETSEGMENT = :SEG
      AND L.SALESMAN = :SALESMAN
      AND L.GROUPNUMBER <> 0
      AND L.RATECODE <> 'HU'
      INTO YTD_NIGHT_GIT,YTD_ROOMRATE_GIT,YTD_ROOMREVENUE_GIT,
           YTD_PACKAGE_GIT,YTD_TOTALREVENUE_GIT;


      IF (YTD_NIGHT_GIT IS NULL) THEN
      BEGIN
         YTD_NIGHT_GIT = 0;
         YTD_ROOMRATE_GIT = 0;
         YTD_ROOMREVENUE_GIT = 0;
         YTD_PACKAGE_GIT = 0;
         YTD_TOTALREVENUE_GIT = 0;
      END
      /* ---------------------------------------------------------------- */
      /* TOTAL YTD                                                        */
      /* ---------------------------------------------------------------- */
      YTD_NIGHT = YTD_NIGHT_FIT + YTD_NIGHT_GIT;
      YTD_ROOMRATE = YTD_ROOMRATE_FIT + YTD_ROOMRATE_GIT;
      YTD_ROOMREVENUE = YTD_ROOMREVENUE_FIT + YTD_ROOMREVENUE_GIT;
      YTD_PACKAGE = YTD_PACKAGE_FIT + YTD_PACKAGE_GIT;
      YTD_TOTALREVENUE = YTD_TOTALREVENUE_FIT + YTD_TOTALREVENUE_GIT;

      /* ---------------------------------------------------------------- */

      IF (YTD_NIGHT <> 0) THEN YTD_AVG_ROOMRATE = YTD_ROOMRATE/YTD_NIGHT;
      ELSE YTD_AVG_ROOMRATE = 0;

      IF (MTD_NIGHT <> 0) THEN MTD_AVG_ROOMRATE = MTD_ROOMRATE/MTD_NIGHT;
      ELSE MTD_AVG_ROOMRATE = 0;

      IF (YTD_NIGHT <> 0) THEN YTD_AVG_ROOMREVENUE = YTD_ROOMREVENUE/YTD_NIGHT;
      ELSE YTD_AVG_ROOMREVENUE = 0;

      IF (MTD_NIGHT <> 0) THEN MTD_AVG_ROOMREVENUE = MTD_ROOMREVENUE/MTD_NIGHT;
      ELSE MTD_AVG_ROOMREVENUE = 0;

      MTD_REVENUE_OTHERS = MTD_TOTALREVENUE - MTD_ROOMREVENUE - MTD_PACKAGE;
      YTD_REVENUE_OTHERS = YTD_TOTALREVENUE - YTD_ROOMREVENUE - YTD_PACKAGE;
      SUSPEND;
    END
  END
END^


