ALTER PROCEDURE FO_RPT_MK_SEG_COL(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    FLAG_HISTORY INTEGER,
    OCC INTEGER,
    PAYING INTEGER,
    SALEABLE INTEGER,
    ROOMREV DOUBLE PRECISION,
    ARR DOUBLE PRECISION,
    HU DOUBLE PRECISION,
    PERCENT_PAYING DOUBLE PRECISION,
    PERCENT_OCC DOUBLE PRECISION,
    COMPL DOUBLE PRECISION,
    SEG01 DOUBLE PRECISION,
    SEG02 DOUBLE PRECISION,
    SEG03 DOUBLE PRECISION,
    SEG04 DOUBLE PRECISION,
    SEG05 DOUBLE PRECISION,
    SEG06 DOUBLE PRECISION,
    SEG07 DOUBLE PRECISION,
    SEG08 DOUBLE PRECISION,
    SEG09 DOUBLE PRECISION,
    SEG10 DOUBLE PRECISION,
    SEG11 DOUBLE PRECISION,
    SEG12 DOUBLE PRECISION,
    SEG13 DOUBLE PRECISION,
    SEG14 DOUBLE PRECISION,
    SEG15 DOUBLE PRECISION,
    SEG16 DOUBLE PRECISION,
    SEG17 DOUBLE PRECISION,
    SEG18 DOUBLE PRECISION,
    SEG19 DOUBLE PRECISION,
    SEG20 DOUBLE PRECISION,
    SEG21 DOUBLE PRECISION,
    SEG22 DOUBLE PRECISION,
    SEG23 DOUBLE PRECISION,
    SEG24 DOUBLE PRECISION,
    SEG25 DOUBLE PRECISION,
    SEG26 DOUBLE PRECISION,
    CODE01 VARCHAR(4),
    CODE02 VARCHAR(4),
    CODE03 VARCHAR(4),
    CODE04 VARCHAR(4),
    CODE05 VARCHAR(4),
    CODE06 VARCHAR(4),
    CODE07 VARCHAR(4),
    CODE08 VARCHAR(4),
    CODE09 VARCHAR(4),
    CODE10 VARCHAR(4),
    CODE11 VARCHAR(4),
    CODE12 VARCHAR(4),
    CODE13 VARCHAR(4),
    CODE14 VARCHAR(4),
    CODE15 VARCHAR(4),
    CODE16 VARCHAR(4),
    CODE17 VARCHAR(4),
    CODE18 VARCHAR(4),
    CODE19 VARCHAR(4),
    CODE20 VARCHAR(4),
    CODE21 VARCHAR(4),
    CODE22 VARCHAR(4),
    CODE23 VARCHAR(4),
    CODE24 VARCHAR(4),
    CODE25 VARCHAR(4),
    CODE26 VARCHAR(4))
AS
declare variable FOSYSDATE date;
declare variable CODE varchar(4);
declare variable I integer;
declare variable N integer;
declare variable REV double precision;
BEGIN
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;
  /* -------------------------------------------------------------------- */
  /* BUAT HEADER                                                          */
  /* -------------------------------------------------------------------- */
  I = 1;
  FOR SELECT FIRST 26 CODE FROM FOST_SEGMENT
      ORDER BY LISTINDEX
      INTO CODE
  DO
  BEGIN
     IF      (I = 01) THEN CODE01 = CODE;
     ELSE IF (I = 02) THEN CODE02 = CODE;
     ELSE IF (I = 03) THEN CODE03 = CODE;
     ELSE IF (I = 04) THEN CODE04 = CODE;
     ELSE IF (I = 05) THEN CODE05 = CODE;
     ELSE IF (I = 06) THEN CODE06 = CODE;
     ELSE IF (I = 07) THEN CODE07 = CODE;
     ELSE IF (I = 08) THEN CODE08 = CODE;
     ELSE IF (I = 09) THEN CODE09 = CODE;
     ELSE IF (I = 10) THEN CODE10 = CODE;
     ELSE IF (I = 11) THEN CODE11 = CODE;
     ELSE IF (I = 12) THEN CODE12 = CODE;
     ELSE IF (I = 13) THEN CODE13 = CODE;
     ELSE IF (I = 14) THEN CODE14 = CODE;
     ELSE IF (I = 15) THEN CODE15 = CODE;
     ELSE IF (I = 16) THEN CODE16 = CODE;
     ELSE IF (I = 17) THEN CODE17 = CODE;
     ELSE IF (I = 18) THEN CODE18 = CODE;
     ELSE IF (I = 19) THEN CODE19 = CODE;
     ELSE IF (I = 20) THEN CODE20 = CODE;
     ELSE IF (I = 21) THEN CODE21 = CODE;
     ELSE IF (I = 22) THEN CODE22 = CODE;
     ELSE IF (I = 23) THEN CODE23 = CODE;
     ELSE IF (I = 24) THEN CODE24 = CODE;
     ELSE IF (I = 25) THEN CODE25 = CODE;
     ELSE IF (I = 26) THEN CODE26 = CODE;
     I = I + 1;
  END
  /* -------------------------------------------------------------------- */
  FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
  BEGIN
     IF (FODATE < FOSYSDATE) THEN FLAG_HISTORY = 1;
     ELSE FLAG_HISTORY = 0;
     /* -------------------------------------------------------------------- */
     /* COMPLIMENT & HOUSE USE                                               */
     /* -------------------------------------------------------------------- */
     IF (FLAG_HISTORY = 1) THEN
     BEGIN
        SELECT SUM(NIGHT) FROM FOSTAT_LOG
        WHERE FODATE=:FODATE
        AND RATECODE = 'HU'
        INTO HU;
        /* -------------------------------------------------------------------- */
        SELECT SUM(NIGHT) FROM FOSTAT_LOG
        WHERE FODATE=:FODATE
        AND RATECODE LIKE 'COMPL%'
        INTO HU;
     END
     /* -------------------------------------------------------------------- */
     /* FORECAST COMPLIMENT & HOUSE USE                                      */
     /* -------------------------------------------------------------------- */
     ELSE
     BEGIN
        SELECT SUM(NIGHT) FROM FORI_LOG
        WHERE FODATE=:FODATE
        AND RATECODE = 'HU'
        INTO HU;
        /* -------------------------------------------------------------------- */
        SELECT SUM(NIGHT) FROM FORI_LOG
        WHERE FODATE=:FODATE
        AND RATECODE LIKE 'COMPL%'
        INTO HU;
     END
     IF (HU IS NULL) THEN HU = 0;
     IF (COMPL IS NULL) THEN COMPL = 0;
     /* -------------------------------------------------------------------- */
     I = 1;
     ROOMREV = 0;
     PAYING = 0;
     FOR SELECT FIRST 26 CODE FROM FOST_SEGMENT
         ORDER BY LISTINDEX
         INTO CODE
     DO
     BEGIN
        /* -------------------------------------------------------------------- */
        /* FROM HISTORY                                                         */
        /* -------------------------------------------------------------------- */
        IF (FLAG_HISTORY = 1) THEN
        BEGIN
           SELECT SUM(NIGHT),SUM(CHARGE_CLASS1) FROM FOSTAT_LOG
           WHERE FODATE=:FODATE
           AND ST_MARKETSEGMENT = :CODE
           AND RATECODE <> 'HU'
           AND RATECODE NOT LIKE 'COMPL%'
           INTO N,REV;
           IF (N IS NULL) THEN N = 0;
           IF (REV IS NULL) THEN REV = 0;
           /* -------------------------------------------------------------------- */
           SELECT SALEABLE FROM FO_HIST_ZRS WHERE FODATE = :FODATE
           INTO SALEABLE;
           IF (SALEABLE IS NULL) THEN SALEABLE = 0;
        END
        ELSE
        /* -------------------------------------------------------------------- */
        /* FROM FORECAST                                                        */
        /* -------------------------------------------------------------------- */
        BEGIN
           SELECT SUM(NIGHT),SUM(RATE_ROOMONLY) FROM FORI_LOG
           WHERE FODATE=:FODATE
           AND ST_MARKETSEGMENT = :CODE
           AND RATECODE <> 'HU'
           AND RATECODE NOT LIKE 'COMPL%'
           INTO N,REV;
           IF (N IS NULL) THEN N = 0;
           IF (REV IS NULL) THEN REV = 0;
           /* -------------------------------------------------------------------- */
           SELECT SUM(SALEABLE) FROM FORI WHERE FODATE = :FODATE
           INTO SALEABLE;
           IF (SALEABLE IS NULL) THEN SALEABLE = 0;
        END
        /* -------------------------------------------------------------------- */
        ROOMREV = ROOMREV + REV;
        PAYING = PAYING + N;
        IF      (I = 01) THEN SEG01 = N;
        ELSE IF (I = 02) THEN SEG02 = N;
        ELSE IF (I = 03) THEN SEG03 = N;
        ELSE IF (I = 04) THEN SEG04 = N;
        ELSE IF (I = 05) THEN SEG05 = N;
        ELSE IF (I = 06) THEN SEG06 = N;
        ELSE IF (I = 07) THEN SEG07 = N;
        ELSE IF (I = 08) THEN SEG08 = N;
        ELSE IF (I = 09) THEN SEG09 = N;
        ELSE IF (I = 10) THEN SEG10 = N;
        ELSE IF (I = 11) THEN SEG11 = N;
        ELSE IF (I = 12) THEN SEG12 = N;
        ELSE IF (I = 13) THEN SEG13 = N;
        ELSE IF (I = 14) THEN SEG14 = N;
        ELSE IF (I = 15) THEN SEG15 = N;
        ELSE IF (I = 16) THEN SEG16 = N;
        ELSE IF (I = 17) THEN SEG17 = N;
        ELSE IF (I = 18) THEN SEG18 = N;
        ELSE IF (I = 19) THEN SEG19 = N;
        ELSE IF (I = 20) THEN SEG20 = N;
        ELSE IF (I = 21) THEN SEG21 = N;
        ELSE IF (I = 22) THEN SEG22 = N;
        ELSE IF (I = 23) THEN SEG23 = N;
        ELSE IF (I = 24) THEN SEG24 = N;
        ELSE IF (I = 25) THEN SEG25 = N;
        ELSE IF (I = 26) THEN SEG26 = N;
        I = I + 1;
    END
    OCC = PAYING + HU + COMPL;
    IF (PAYING = 0) THEN ARR = 0;
    ELSE ARR = ROOMREV / PAYING;
    IF (SALEABLE = 0) THEN
    BEGIN
       PERCENT_PAYING = 0;
       PERCENT_OCC = 0;
    END
    ELSE
    BEGIN
       PERCENT_PAYING = PAYING / SALEABLE * 100;
       PERCENT_OCC = OCC / SALEABLE * 100;
    END
    
    SUSPEND;
    FODATE = FODATE + 1;
  END
END^


