ALTER PROCEDURE FO_RPT_PB1(
    SDATE DATE)
RETURNS (
    SYSDATE DATE,
    FOLIO INTEGER,
    TRANS_ID INTEGER,
    CATEGORY VARCHAR(4),
    CATEGORY_NAME VARCHAR(50),
    FLAG_INCL_SERVICE INTEGER,
    FLAG_INCL_PB1 INTEGER,
    FLAG_REPORT INTEGER,
    PB1_CODE VARCHAR(4),
    CHARGE DOUBLE PRECISION,
    NET DOUBLE PRECISION,
    PB1 DOUBLE PRECISION,
    FLAG_PB1 INTEGER,
    JURCODE VARCHAR(4),
    SOURCE_ID INTEGER,
    FOSYSDATE DATE,
    REMARK VARCHAR(40),
    HIDDEN INTEGER,
    MEAL_ALLOWANCE INTEGER)
AS
declare variable flag_ok integer;
declare variable dbcr varchar(1);
declare variable flag_cash integer;
declare variable flag_pos integer;
BEGIN
  if (SDATE IS NULL) then BEGIN
     SELECT MAX(FOSYSDATE) FROM FOSYSPARAM
     INTO :SDATE;
     SDATE = SDATE-3;
  END
  
  FOR SELECT JR.SYSDATE,
             JR.FOLIO,JR.TRANS_ID,
             JR.CATEGORY,CAT.NAME,
             CAT.PB1_CODE,CAT.FLAG_INCL_SERVICE,CAT.FLAG_INCL_PB1,CAT.FLAG_REPORT,
             CAT.DBCR,CAT.FLAG_CASH,
             (JR.DEBIT-JR.CREDIT),
             JR.JURCODE,JR.SOURCE_ID,
             JR.FOSYSDATE,
             JR.REMARK,
             CAT.FLAG_POS,
             CAST (0 AS INTEGER),
             JR.HIDDEN
      FROM FOGUEST_JUR JR
      LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY=JR.CATEGORY
      WHERE JR.FODATE = :SDATE
      AND ((JR.HIDDEN = 0) OR (JR.JURCODE IN ('NA','MRT')))
      AND CAT.PB1_CODE NOT IN ('$PY','$TX','$PK')
      AND ((NOT ((JR.JURCODE='FB') /*AND (JR.HIDDEN = 1) */ AND (JR.SOURCE_ID <> 0))) OR
                ((JR.JURCODE='FB') AND (CAT.DBCR='C')) 
          )
      AND JR.CORRECTED = 0
      UNION
      /* MEAL ALLOWANCE */
      SELECT JR.SYSDATE,
             JR.FOLIO,JR.TRANS_ID,
             JR.CATEGORY,CAT.NAME,
             CAT.PB1_CODE,CAT.FLAG_INCL_SERVICE,CAT.FLAG_INCL_PB1,CAT.FLAG_REPORT,
             CAT.DBCR,CAT.FLAG_CASH,
             (JR.DEBIT-JR.CREDIT),
             JR.JURCODE,JR.SOURCE_ID,
             JR.FOSYSDATE,
             JR.REMARK,
             CAT.FLAG_POS,
             CAST (1 AS INTEGER),
             JR.HIDDEN
      FROM FOGUEST_JUR JR
      LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY=JR.CATEGORY
      WHERE JR.FODATE = :SDATE
      AND ((JR.JURCODE='FB') AND (JR.HIDDEN = 1) AND (JR.SOURCE_ID <> 0)) /* MEAL ALLOWANCE */
      AND (JR.DEBIT-JR.CREDIT) < 0
      AND JR.CORRECTED = 0
      INTO SYSDATE,
           FOLIO,TRANS_ID,
           CATEGORY,CATEGORY_NAME,
           PB1_CODE,FLAG_INCL_SERVICE,FLAG_INCL_PB1,FLAG_REPORT,
           DBCR,FLAG_CASH,
           CHARGE,
           JURCODE,SOURCE_ID,
           FOSYSDATE,REMARK,
           FLAG_POS,
           MEAL_ALLOWANCE,
           HIDDEN
  DO
  BEGIN
     FLAG_OK = 1;
     /*IF ((JURCODE='MRT') AND (HIDDEN=1)) THEN FLAG_OK = 0; /* CORRECTION*/
     /*ELSE*/
     IF ((JURCODE='FB') AND (SOURCE_ID = 0) AND (FLAG_CASH <> 1)) THEN FLAG_OK = 0;
     IF (FLAG_POS = 1) THEN
     BEGIN
        IF ((JURCODE='FB') AND (SOURCE_ID > 0)) THEN FLAG_OK = 0;
        ELSE FLAG_OK = 1;
     END
     IF (FLAG_OK = 1) THEN
     BEGIN
         TRANS_ID = TRANS_ID * 10;
         FLAG_PB1 = FLAG_REPORT;
         IF ((DBCR = 'C') OR ((FLAG_POS = 1) AND (SOURCE_ID=0))) THEN CHARGE = -CHARGE; /* 12/18/2013 */
         NET = CHARGE;
         IF (FLAG_REPORT = 0) THEN /* TIDAK KENA PB1 SAMA SEKALI*/
         BEGIN
            FLAG_PB1 = 0;
            PB1 = 0;
            SUSPEND;
         END
         ELSE
         BEGIN
            /* ------------------------------------------------------------- */
            /* TIDAK TERMASUK PB1 & SERVICE                                  */
            /* ------------------------------------------------------------- */
            IF ((FLAG_INCL_SERVICE = 0) AND (FLAG_INCL_PB1 = 0)) THEN
            BEGIN
               NET = CHARGE;
               PB1 = NET * 0.1;
               SUSPEND;
            END
            ELSE
            IF (FLAG_INCL_SERVICE = 1) THEN
            BEGIN
               NET = CHARGE/1.21;
               PB1 = NET * 0.1;
               SUSPEND;
               TRANS_ID = TRANS_ID + 1;
               CATEGORY_NAME = 'Service '|| CATEGORY_NAME;
               PB1_CODE = 'ATV';
               NET = CHARGE*0.1/1.21;
               PB1 = NET * 0.1;
               SUSPEND;
            END
            ELSE
            IF ((FLAG_INCL_SERVICE = 0) AND (FLAG_INCL_PB1 = 1)) THEN
            BEGIN
               NET = CHARGE/1.1;
               PB1 = NET * 0.1;
               SUSPEND;
            END
         END
     END
  END
END^


ALTER PROCEDURE FO_RPT_PB1_CHECKER(
    FODATE DATE)
RETURNS (
    FOLIO INTEGER,
    NAME VARCHAR(80),
    PB1 DOUBLE PRECISION,
    PB1_JUR DOUBLE PRECISION,
    PB1_JUR_ORI DOUBLE PRECISION,
    POS DOUBLE PRECISION,
    CLOSE_MEAL DOUBLE PRECISION,
    MEAL_ALLOWANCE DOUBLE PRECISION,
    PKG DOUBLE PRECISION,
    DELTA DOUBLE PRECISION,
    RATECODE VARCHAR(16),
    TAXTYPE VARCHAR(1))
AS
declare variable flag_incl_service integer;
declare variable flag_incl_pb1 integer;
declare variable rate_tax varchar(1);
declare variable foliotype varchar(1);
BEGIN
  if (FODATE IS NULL) then BEGIN
     SELECT MAX(FOSYSDATE) FROM FOSYSPARAM
     INTO :FODATE;
     FODATE = FODATE-3;
  END
  FOR
    SELECT FOLIO,SUM(PB1) FROM FO_RPT_PB1(:FODATE)
    GROUP BY FOLIO
    INTO
      :FOLIO,
      :PB1
  DO
  BEGIN
    POS = 0;
    SELECT SUM(JR.DEBIT-JR.CREDIT)
    FROM FOGUEST_JUR JR
    LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY=JR.CATEGORY
    WHERE JR.FOLIO=:FOLIO
    AND JR.FODATE = :FODATE
    AND (NOT ((JR.JURCODE='FB') /* AND (JR.HIDDEN = 1) */ AND (JR.SOURCE_ID <> 0))) /* 1/10/2014 POSTING ALLOWANCE DARI POS */
    /*AND JR.FOSYSDATE = JR.FODATE*/
    AND CAT.PB1_CODE = '$TX'
    INTO PB1_JUR;
    IF (PB1_JUR IS NULL) THEN PB1_JUR = 0;
    NAME = 'PB1';
    PB1_JUR_ORI = PB1_JUR;
    /* ------------------------------------------------------------- */
    SELECT GS.FULLNAMEF,GS.RATECODE,RT.TAXTYPE,GS.FOLIOTYPE
    FROM FOGUEST GS
    LEFT JOIN FORATE RT ON RT.RATECODE=GS.RATECODE
    WHERE GS.FOLIO = :FOLIO
    INTO NAME,RATECODE,TAXTYPE,FOLIOTYPE;

    /* ------------------------------------------------------------- */
    /* KALAU ADA FB                                                  */
    /* ------------------------------------------------------------- */
    IF (FOLIOTYPE <> 'H') THEN
    BEGIN
        SELECT SUM(JR.DEBIT-JR.CREDIT)
        FROM FOGUEST_JUR JR
        WHERE JR.FOLIO=:FOLIO
        AND JR.FODATE = :FODATE
        /*AND JR.FOSYSDATE = JR.FODATE /* BUKAN NEXT DAY POSTING */
        AND JR.JURCODE ='FB'
        AND JR.SOURCE_ID <> 0
        AND JR.HIDDEN = 0
        INTO POS;

        IF (POS IS NULL) THEN POS = 0;

        /*PB1_JUR = PB1_JUR - POS * (11/121); */
    END
    /* ------------------------------------------------------------- */
    /* MEAL ALLOWANCE                                                */
    /* ------------------------------------------------------------- */
    SELECT SUM(JR.DEBIT-JR.CREDIT)
    FROM FOGUEST_JUR JR
    LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY=JR.CATEGORY
    WHERE JR.FOLIO=:FOLIO
    AND JR.FODATE = :FODATE
    AND ((JR.JURCODE='FB') AND (JR.HIDDEN = 1) AND (JR.SOURCE_ID <> 0)) /* MEAL ALLOWANCE */
    AND CAT.PB1_CODE = '$TX'
    INTO MEAL_ALLOWANCE;
    IF (MEAL_ALLOWANCE IS NULL) THEN MEAL_ALLOWANCE = 0;
    PB1_JUR = PB1_JUR + MEAL_ALLOWANCE;
    /* ------------------------------------------------------------- */
    /* PENJUALAN DI POS YG CASH/CREDIT CARD                          */
    /* ------------------------------------------------------------- */
    
    
    
    SELECT SUM(JR.CREDIT-JR.DEBIT)
    FROM FOGUEST_JUR JR
    LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY=JR.CATEGORY
    WHERE JR.FOLIO=:FOLIO
    /*AND JR.FODATE = :FODATE*/
    AND JR.HIDDEN = 0
    AND JR.JURCODE = 'FB'
    AND JR.MEAL_PERIOD IN ('BF','LC','DN','SF','ALL') /* CLOSE MEAL PERIOD */
    AND CAT.PB1_CODE = '$PY'
    INTO CLOSE_MEAL;
    IF (CLOSE_MEAL IS NULL) THEN CLOSE_MEAL = 0;

    PB1_JUR = PB1_JUR + CLOSE_MEAL * (11/121);
    
    
    DELTA = PB1-PB1_JUR;
    SUSPEND;
  END
END^


