ALTER PROCEDURE FO_RPT_RI_7DAY_AGUS(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    PDAY INTEGER,
    FODATE DATE,
    IH INTEGER,
    CO INTEGER,
    CI INTEGER,
    IH_PAX INTEGER,
    CO_PAX INTEGER,
    CI_PAX INTEGER,
    BLOCK_NP INTEGER,
    GROUP_TENT INTEGER,
    GROUP_NP INTEGER,
    ONHAND INTEGER,
    ONHAND_PAX INTEGER,
    SALEABLE INTEGER,
    OCCUPANCY DOUBLE PRECISION,
    TOTALRATE DOUBLE PRECISION,
    TOTALDISCOUNT DOUBLE PRECISION,
    TOTALPACKAGE DOUBLE PRECISION,
    TOTALREVENUE_NETT DOUBLE PRECISION)
AS
declare variable VDATE DATE;
declare variable VROW INTEGER;
declare variable ROOMTYPE VARCHAR(4);
BEGIN
  if (SDATE IS NULL) then BEGIN
     SELECT FOSYSDATE FROM FOSYSPARAM INTO :SDATE;
     EDATE = SDATE + 30;
  END
  FODATE = SDATE;
  PDAY = 0;
  WHILE (FODATE <= EDATE) DO
  BEGIN
   if (PDAY =0) then
    BEGIN
     SELECT COUNT(*),SUM(PAX)
       FROM FOGUEST
       WHERE FOLIOTYPE = 'P'
       AND FOLIOSTATUS = 'I'
       AND FOLIOSTATUS_SHARE = 'M'
       AND (NOT ((RATECODE = 'HU') or (RATECODE LIKE 'COMPL%')))
       INTO :IH,IH_PAX;
       if (IH IS NULL) then IH = 0;
    END
    /* check in */
    SELECT COUNT(*),SUM(PAX)
    FROM FOGUEST
    WHERE FOLIOTYPE = 'P'
    AND FOLIOSTATUS IN ('I','C','T','G')
    AND FOLIOSTATUS_SHARE = 'M'
    AND (NOT ((RATECODE = 'HU') or (RATECODE LIKE 'COMPL%')))
    AND DATECI = :FODATE
    INTO :CI,CI_PAX;
    if (CI IS NULL) then CI = 0;
    if (CI_PAX IS NULL) then CI_PAX = 0;
    
    /* check out */
    SELECT COUNT(*),SUM(PAX)
    FROM FOGUEST
    WHERE FOLIOTYPE = 'P'
    AND FOLIOSTATUS IN ('I','C','T','G')
    AND FOLIOSTATUS_SHARE = 'M'
    AND (NOT ((RATECODE = 'HU') or (RATECODE LIKE 'COMPL%')))
    AND DATECO = :FODATE
    INTO :CO,:CO_PAX;
    if (CO IS NULL) THEN CO = 0;
    if (CO_PAX IS NULL) then CO_PAX = 0;
    
    SELECT SUM(B_TOTAL) BLOCK_NP,
           SUM(G_CFRM)  GROUP_NP,
           SUM(G_TENT)  GROUP_TENT,
           SUM(SALEABLE) SALEABLE,
           SUM(TOTALRATE) TOTALRATE,
           SUM(TOTALDISCOUNT) TOTALDISCOUNT,
           SUM(TOTALPACKAGE)  TOTALPACKAGE,
           SUM(TOTALREVENUE_NETT) TOTALREVENUE_NETT
    FROM FORI RI
    WHERE FODATE = :FODATE
    INTO
      :BLOCK_NP,
      :GROUP_NP,
      :GROUP_TENT,
      :SALEABLE,
      :TOTALRATE,
      :TOTALDISCOUNT,
      :TOTALPACKAGE,
      :TOTALREVENUE_NETT;
    if (BLOCK_NP IS NULL) then
    BEGIN
      BLOCK_NP = 0;
      GROUP_NP = 0;
      GROUP_TENT = 0;
      SALEABLE = 0;
      TOTALRATE = 0;
      TOTALDISCOUNT = 0;
      TOTALPACKAGE = 0;
      TOTALREVENUE_NETT =0;
    END
    
    if (SALEABLE = 0) then
    BEGIN
       SELECT SUM(ROOMCOUNT) FROM FOROOMTYPE
       WHERE STATISTIC_INCLUDED = 1
       INTO :SALEABLE;
       
    END
       
    ONHAND = IH - CI + CO + GROUP_NP ;
    ONHAND_PAX = IH_PAX + CI_PAX - CO_PAX;
    OCCUPANCY = 0;
    if (SALEABLE <> 0) then OCCUPANCY = ONHAND/SALEABLE*100;
    SUSPEND;
    PDAY = PDAY + 1;    
    IH = ONHAND;
    IH_PAX = ONHAND_PAX;
    FODATE = FODATE + 1;
  END
END^


ALTER PROCEDURE FO_RPT_RI_7DAY_MGR(
    FODATE DATE,
    EDATE DATE,
    TENT VARCHAR(2))
RETURNS (
    PDAY INTEGER,
    FOSYSDATE DATE,
    IH INTEGER,
    CO INTEGER,
    RSV INTEGER,
    CI INTEGER,
    IH_PAX INTEGER,
    CO_PAX INTEGER,
    RSV_PAX INTEGER,
    CI_PAX INTEGER,
    BLOCK_NP INTEGER,
    GROUP_TENT INTEGER,
    GROUP_NP INTEGER,
    ONHAND INTEGER,
    ONHAND_PAX INTEGER,
    SALEABLE INTEGER,
    OCCUPANCY DOUBLE PRECISION,
    TOTALRATE DOUBLE PRECISION,
    TOTALDISCOUNT DOUBLE PRECISION,
    TOTALPACKAGE DOUBLE PRECISION,
    TOTALREVENUE_NETT DOUBLE PRECISION,
    VDEBUG INTEGER)
AS
declare variable VDATE DATE;
declare variable VROW INTEGER;
declare variable ROOMTYPE VARCHAR(4);
BEGIN
  if (FODATE IS NULL) then BEGIN
     SELECT FOSYSDATE FROM FOSYSPARAM INTO :FODATE;
     EDATE = FODATE + 30;
  END
  FOSYSDATE = FODATE;
  PDAY = 0;
  WHILE (FODATE <= EDATE) DO
  BEGIN
    if (PDAY =0) then
    BEGIN
       SELECT COUNT(*),SUM(PAX)
       FROM FOGUEST
       WHERE FOLIOTYPE = 'P'
       AND FOLIOSTATUS = 'I'
       AND FOLIOSTATUS_SHARE = 'M'
       AND (NOT (RATECODE = 'HU'))
/*       AND (NOT ((RATECODE = 'HU') or (RATECODE LIKE 'COMPL%')))*/
       INTO :IH,IH_PAX;
       if (IH IS NULL) then IH = 0;
    END
    /* check in */
    SELECT COUNT(*),SUM(PAX)
    FROM FOGUEST
    WHERE FOLIOTYPE = 'P'
    AND FOLIOSTATUS IN ('I','C','T','G')
    AND FOLIOSTATUS_SHARE = 'M'
    AND (NOT ((RATECODE = 'HU') or (RATECODE LIKE 'COMPL%')))
    AND DATECI = :FOSYSDATE
    INTO :CI,CI_PAX;
    if (CI IS NULL) then CI = 0;
    if (CI_PAX IS NULL) then CI_PAX = 0;
    
    /* check out */
        SELECT COUNT(*),SUM(PAX)
        FROM FOGUEST
        WHERE FOLIOTYPE = 'P'
        AND FOLIOSTATUS IN ('I','C','T','G')
        AND FOLIOSTATUS_SHARE = 'M'
        AND (NOT (RATECODE = 'HU'))
        /*AND (NOT ((RATECODE = 'HU') or (RATECODE LIKE 'COMPL%')))*/
        AND DATECO = :FOSYSDATE
        INTO :CO,:CO_PAX;
        if (CO IS NULL) THEN CO = 0;
        if (CO_PAX IS NULL) then CO_PAX = 0;

    /* HITUNG RESERVASI ( 'G','T','C') */
        SELECT COUNT(*),SUM(PAX)
        FROM FOGUEST
        WHERE FOLIOTYPE = 'P'
        AND FOLIOSTATUS IN ('C','T','G')
        AND FOLIOSTATUS_SHARE = 'M'
        AND (NOT (RATECODE = 'HU'))
        /*    AND (NOT ((RATECODE = 'HU') or (RATECODE LIKE 'COMPL%')))*/
        AND DATECI = :FOSYSDATE
        INTO :RSV,:RSV_PAX;
        if (RSV IS NULL) THEN RSV = 0;
        if (RSV_PAX IS NULL) then RSV_PAX = 0;
     
    SELECT SUM(B_TOTAL) BLOCK_NP,
           SUM(G_CFRM)  GROUP_NP,
           SUM(G_TENT)  GROUP_TENT,
           SUM(SALEABLE) SALEABLE,
           SUM(TOTALRATE) TOTALRATE,
           SUM(TOTALDISCOUNT) TOTALDISCOUNT,
           SUM(TOTALPACKAGE)  TOTALPACKAGE,
           SUM(TOTALREVENUE_NETT) TOTALREVENUE_NETT
    FROM FORI RI
    WHERE FODATE = :FOSYSDATE
    INTO
      :BLOCK_NP,
      :GROUP_NP,
      :GROUP_TENT,
      :SALEABLE,
      :TOTALRATE,
      :TOTALDISCOUNT,
      :TOTALPACKAGE,
      :TOTALREVENUE_NETT;
    if (BLOCK_NP IS NULL) then
    BEGIN
      BLOCK_NP = 0;
      GROUP_NP = 0;
      GROUP_TENT = 0;
      SALEABLE = 0;
      TOTALRATE = 0;
      TOTALDISCOUNT = 0;
      TOTALPACKAGE = 0;
      TOTALREVENUE_NETT =0;
    END
    
    if (SALEABLE = 0) then
    BEGIN
       SELECT SUM(ROOMCOUNT) FROM FOROOMTYPE
       WHERE STATISTIC_INCLUDED = 1
       INTO :SALEABLE;
       
    END
       
/*    ONHAND = IH - CI + CO + GROUP_NP ;
    ONHAND_PAX = IH_PAX + CI_PAX - CO_PAX;
*/
    if (TENT =1) then
       BEGIN
       ONHAND = IH + RSV + GROUP_NP ;
       ONHAND_PAX = IH_PAX + RSV_PAX ;
       END
       ELSE
       BEGIN
       ONHAND = IH + RSV  ;
       ONHAND_PAX = IH_PAX + RSV_PAX ;
       END
    OCCUPANCY = 0;
    if (SALEABLE <> 0) then OCCUPANCY = ONHAND/SALEABLE*100;
    SUSPEND;
    PDAY = PDAY + 1;    
    IH = ONHAND;
    IH_PAX = ONHAND_PAX;
    FOSYSDATE = FOSYSDATE + 1;
  END
END^


