ALTER PROCEDURE FO_RPT_RI_OLD(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    OH_01 INTEGER,
    OH_02 INTEGER,
    OH_03 INTEGER,
    OH_04 INTEGER,
    OH_05 INTEGER,
    OH_06 INTEGER,
    OH_07 INTEGER,
    OH_08 INTEGER,
    OH_09 INTEGER,
    OH_10 INTEGER,
    AVI_01 INTEGER,
    AVI_02 INTEGER,
    AVI_03 INTEGER,
    AVI_04 INTEGER,
    AVI_05 INTEGER,
    AVI_06 INTEGER,
    AVI_07 INTEGER,
    AVI_08 INTEGER,
    AVI_09 INTEGER,
    AVI_10 INTEGER,
    SALEABLE INTEGER,
    TOTAL_OH INTEGER,
    TOTAL_AVI INTEGER,
    OCCUPANCY DOUBLE PRECISION,
    RATE DOUBLE PRECISION,
    DISCOUNT DOUBLE PRECISION,
    PACKAGE DOUBLE PRECISION,
    NETT_RATE DOUBLE PRECISION,
    TOTAL_CI INTEGER,
    TOTAL_CO INTEGER,
    AVG_RATE DOUBLE PRECISION,
    AVG_RATE_NETT DOUBLE PRECISION)
AS
declare variable ROOMTYPE VARCHAR(4);
declare variable OH INTEGER;
declare variable AVI INTEGER;
declare variable VROW INTEGER;
declare variable IDX INTEGER;
BEGIN
  if (SDATE IS NULL) then BEGIN
     SELECT FOSYSDATE FROM FOSYSPARAM INTO :SDATE;
     EDATE = SDATE + 60;
  END
  OH_01 = 0; OH_02 = 0; OH_03 = 0; OH_04 = 0; OH_05 = 0;
  OH_06 = 0; OH_07 = 0; OH_08 = 0; OH_09 = 0; OH_10 = 0;
    
  AVI_01 = 0; AVI_02 = 0; AVI_03 = 0; AVI_04 = 0; AVI_05 = 0;
  AVI_06 = 0; AVI_07 = 0; AVI_08 = 0; AVI_09 = 0; AVI_10 = 0;
    
  FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
  BEGIN
     IDX = 1;
     EXECUTE PROCEDURE FO_RI_CREATE(:FODATE); /* create blank ri */
     
     FOR SELECT ROOMTYPE FROM FOROOMTYPE INTO :ROOMTYPE
     DO
     BEGIN
           
        SELECT ONHAND,AVAILABLE FROM FORI 
        WHERE ROOMTYPE = :ROOMTYPE AND FODATE = :FODATE
        INTO  :OH,:AVI;

        if (IDX =  1) then BEGIN OH_01 = OH; AVI_01 = AVI; END
        if (IDX =  2) then BEGIN OH_02 = OH; AVI_02 = AVI; END
        if (IDX =  3) then BEGIN OH_03 = OH; AVI_03 = AVI; END
        if (IDX =  4) then BEGIN OH_04 = OH; AVI_04 = AVI; END
        if (IDX =  5) then BEGIN OH_05 = OH; AVI_05 = AVI; END
        if (IDX =  6) then BEGIN OH_06 = OH; AVI_06 = AVI; END
        if (IDX =  7) then BEGIN OH_07 = OH; AVI_07 = AVI; END
        if (IDX =  8) then BEGIN OH_08 = OH; AVI_08 = AVI; END
        if (IDX =  9) then BEGIN OH_09 = OH; AVI_09 = AVI; END
        if (IDX = 10) then BEGIN OH_10 = OH; AVI_10 = AVI; END
        IDX = IDX + 1;
     END
     SELECT SUM(RI.SALEABLE),SUM(RI.T_CI-T_CI_ALREADY),SUM(T_CO),
            SUM(RI.ONHAND),SUM(RI.AVAILABLE),
            SUM(TOTALRATE),SUM(TOTALDISCOUNT),SUM(TOTALPACKAGE),
            SUM(TOTALREVENUE_NETT)
     FROM FORI RI
     WHERE FODATE = :FODATE
     INTO SALEABLE,TOTAL_CI,TOTAL_CO,TOTAL_OH,TOTAL_AVI,
          RATE,DISCOUNT,PACKAGE,NETT_RATE;
     
     if (SALEABLE = 0) then OCCUPANCY = 0;
     ELSE OCCUPANCY = TOTAL_OH / SALEABLE * 100;

     if (TOTAL_OH = 0) then BEGIN
        AVG_RATE = 0;
        AVG_RATE_NETT = 0;
     END
     ELSE BEGIN
        AVG_RATE      = RATE / TOTAL_OH;
        AVG_RATE_NETT = NETT_RATE / TOTAL_OH;
     END
     SUSPEND;
     FODATE = FODATE + 1;
  END

END^


