ALTER PROCEDURE FO_RPT_ROOMSPECIAL
RETURNS (
    TITLE VARCHAR(40),
    ROOM VARCHAR(8),
    FOLIO INTEGER,
    DESCRIPTION VARCHAR(80),
    REMARK1 VARCHAR(20),
    REMARK2 VARCHAR(40),
    DISCOUNT DOUBLE PRECISION,
    DATESTART DATE,
    DATEEND DATE)
AS
BEGIN
  /* ------------------------------------------------------------------------ */
  /* UPDGRATE                                                                 */
  /* ------------------------------------------------------------------------ */  
  DISCOUNT = 0;
  TITLE = 'Upgraded Room';
  FOR
    SELECT ROOM, FOLIO, FULLNAMEF, RATECODE,
           'From ' || ROOMTYPE || ' to ' || ROOMTYPE_UPGRADE,
           DATECI, DATECO
    FROM FOGUEST
    WHERE (FOLIOSTATUS = 'I')
    AND (FOLIOSTATUS_SHARE = 'M')
    AND (FOLIOTYPE = 'P')
    AND (ROOMTYPE <> ROOMTYPE_UPGRADE)
    ORDER BY ROOM
    INTO
      :ROOM, FOLIO,
      :DESCRIPTION,
      :REMARK1,
      :REMARK2,
      :DATESTART,
      :DATEEND
  DO
  BEGIN
    SUSPEND;
  END
  DISCOUNT = 0;
  /* ------------------------------------------------------------------------ */
  /* DISCOUNT                                                                 */
  /* ------------------------------------------------------------------------ */  
  TITLE = 'Discount';
  FOR
    SELECT ROOM, FOLIO, FULLNAMEF, RATECODE, COMPANYNAME, DATECI, DATECO, RATEDISCOUNT
    FROM FOGUEST
    WHERE (FOLIOSTATUS = 'I')
    AND (FOLIOSTATUS_SHARE = 'M')
    AND (FOLIOTYPE = 'P')
    AND (RATEDISCOUNT <> 0)
    ORDER BY ROOM
    INTO
      :ROOM, FOLIO,
      :DESCRIPTION,
      :REMARK1,
      :REMARK2,
      :DATESTART,
      :DATEEND,
      :DISCOUNT
  DO
  BEGIN
    SUSPEND;
  END
  DISCOUNT = 0;
  /* ------------------------------------------------------------------------ */
  /* COMPLIMENT                                                               */
  /* ------------------------------------------------------------------------ */   
  TITLE = 'Compliment';
  FOR
    SELECT ROOM, FOLIO, FULLNAMEF, RATECODE, COMPANYNAME, DATECI, DATECO
    FROM FOGUEST
    WHERE (FOLIOSTATUS = 'I')
    AND (FOLIOSTATUS_SHARE = 'M')
    AND (FOLIOTYPE = 'P')
    AND (RATECODE LIKE 'COMPL%')
    ORDER BY ROOM
    INTO
      :ROOM, FOLIO,
      :DESCRIPTION,
      :REMARK1,
      :REMARK2,
      :DATESTART,
      :DATEEND
  DO
  BEGIN
    SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* HOUSE USE                                                                */
  /* ------------------------------------------------------------------------ */ 
  TITLE = 'House Use';
  FOR
    SELECT ROOM, FOLIO, FULLNAMEF, RATECODE, COMPANYNAME, DATECI, DATECO
    FROM FOGUEST
    WHERE (FOLIOSTATUS = 'I')
    AND (FOLIOSTATUS_SHARE = 'M')
    AND (FOLIOTYPE = 'P')
    AND (RATECODE = 'HU')
    ORDER BY ROOM
    INTO
      :ROOM, FOLIO,
      :DESCRIPTION,
      :REMARK1,
      :REMARK2,
      :DATESTART,
      :DATEEND
  DO
  BEGIN
    SUSPEND;
  END  
  /* ------------------------------------------------------------------------ */
  /* out of inventory and out of order                                        */
  /* ------------------------------------------------------------------------ */  
  Title = 'Out of Order and Out of Inventory';
  FOR SELECT RI.ROOM, (RI.MAINTENANCE_NUMBER + RI.OUTOFINVENTORY_NUMBER) 
        FROM fori_assign RI, FOSYSPARAM CFG
       WHERE ((RI.MAINTENANCE_NUMBER <> 0) OR
              (RI.OUTOFINVENTORY_NUMBER <> 0))
         AND RI.FODATE = CFG.FOSYSDATE
       ORDER BY ROOM
  INTO :ROOM, :FOLIO
  DO
  BEGIN
    SELECT DATESTART, DATEEND, MAINTENANCE_TYPE FROM foroom_maintenance
    WHERE NUMBER = :FOLIO
    INTO DATESTART, DATEEND, :REMARK1;
    if (REMARK1 = 'I') then DESCRIPTION = 'Out of Inventory';
    else if (REMARK1 = 'O') then DESCRIPTION = 'Out of Order';
    REMARK2 = DATESTART || ' to ' || DATEEND;
    SUSPEND;
  END
END^


