ALTER PROCEDURE FO_RPT_SHIFT_AUDIT_ROBY(
    FODATE DATE,
    SUSERENTRY VARCHAR(14),
    EUSERENTRY VARCHAR(14))
RETURNS (
    FOLIO INTEGER,
    FOLIOSTATUS CHAR(1),
    FOLIOSTATUS_SHARE CHAR(1),
    FOLIOTYPE CHAR(1),
    PAX INTEGER,
    CHILD INTEGER,
    RATECODE VARCHAR(12),
    USERCHECKOUT VARCHAR(8),
    DISCOUNT DOUBLE PRECISION,
    NUMBER_CHECKOUT INTEGER,
    ROOM VARCHAR(8),
    DATECI DATE,
    DATECO DATE,
    GUESTNAME VARCHAR(80),
    COMPANY VARCHAR(6),
    ST_NATIONALITY VARCHAR(40),
    COMPANYNAME VARCHAR(40),
    FLAG_WALKIN INTEGER,
    RELATION_DOCTYPE INTEGER,
    PRE_PAYMENT DOUBLE PRECISION,
    CHARGE DOUBLE PRECISION,
    DEPOSIT DOUBLE PRECISION,
    CASH DOUBLE PRECISION,
    CREDITCARD DOUBLE PRECISION,
    COST DOUBLE PRECISION,
    CITYLEDGER DOUBLE PRECISION,
    ADDITIONAL DOUBLE PRECISION,
    OTHERS DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    PAYMENT_REMARK VARCHAR(120),
    FOLIOTYPE_NAME VARCHAR(20),
    FOLIOSTATUS_NAME VARCHAR(16))
AS
declare variable category varchar(4);
declare variable credit double precision;
declare variable flag_creditcard integer;
declare variable flag_cash integer;
declare variable cl1 varchar(4);
declare variable cl2 varchar(4);
declare variable cl3 varchar(4);
declare variable xfolio integer;
declare variable catname varchar(40);
BEGIN
  IF (FODATE IS NULL) THEN
  BEGIN
     SELECT FOSYSDATE FROM FOSYSPARAM INTO FODATE;
     SUSERENTRY = 'ADMIN';
     EUSERENTRY = 'ADMIN';
  END
  SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'CITYLEDGER1' INTO CL1;
  SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'CITYLEDGER2' INTO CL2;
  SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'CITYLEDGER3' INTO CL3;
  XFOLIO = 0;
  FOR
    SELECT FOLIO  FROM FOGUEST_JUR
    WHERE FODATE = :FODATE
    AND USERENTRY BETWEEN :SUSERENTRY AND :EUSERENTRY
    AND JURCODE IN ('CR','CL','DEP','CO','FB','TRF')
    GROUP BY FOLIO
    INTO :FOLIO
  DO
  BEGIN
    DEPOSIT = 0;
    CASH = 0;
    CREDITCARD = 0;
    CITYLEDGER = 0;
    OTHERS = 0;
    COST = 0;
    ADDITIONAL = 0;
    TOTAL = 0;
    PAYMENT_REMARK = '';
    FOLIOSTATUS = NULL;
    
    SELECT FOLIOSTATUS,FOLIOSTATUS_SHARE,FOLIOTYPE,ST_NATIONALITY,NUMBER_CHECKOUT,USERCHECKOUT,RATECODE,RATEDISCOUNT,
           PAX,CHILD
    FROM FOGUEST WHERE FOLIO = :FOLIO
    INTO FOLIOSTATUS,FOLIOSTATUS_SHARE,FOLIOTYPE,ST_NATIONALITY,NUMBER_CHECKOUT,USERCHECKOUT,RATECODE,DISCOUNT,
           PAX,CHILD;

    IF (NUMBER_CHECKOUT IS NULL) THEN NUMBER_CHECKOUT = 0;

    IF (FOLIOSTATUS IS NULL) THEN
       SELECT FOLIOSTATUS,FOLIOTYPE,ST_NATIONALITY,RATECODE,RATEDISCOUNT,PAX,CHILD
       FROM FOSTAT_LOG
       WHERE FOLIO = :FOLIO AND FODATE = :FODATE
       INTO FOLIOSTATUS,FOLIOTYPE,RATECODE,ST_NATIONALITY,DISCOUNT,PAX,CHILD;

    IF (FOLIOTYPE = 'P') THEN FOLIOTYPE_NAME = 'Individual';
    ELSE IF (FOLIOTYPE = 'H') THEN FOLIOTYPE_NAME = 'House Folio';
    ELSE FOLIOTYPE_NAME = 'MICE';

    IF (FOLIOSTATUS = 'I') THEN FOLIOSTATUS_NAME = 'In House';
    ELSE IF (FOLIOSTATUS = 'O') THEN FOLIOSTATUS_NAME = 'Check Out';
    ELSE IF (FOLIOSTATUS = 'G') THEN FOLIOSTATUS_NAME = 'Guarantee';
    ELSE IF (FOLIOSTATUS = 'C') THEN FOLIOSTATUS_NAME = 'Confirmed';
    ELSE IF (FOLIOSTATUS = 'G') THEN FOLIOSTATUS_NAME = 'Status '||FOLIOSTATUS;



    SELECT ROOM,GUESTNAME,COMPANYNAME,DATECI,DATECO,WALKIN,COMPANY,RELATION_DOCTYPE FROM fo_rpt_hist_guestname(:FOLIO)
    INTO ROOM,:GUESTNAME,:COMPANYNAME,:DATECI,:DATECO,FLAG_WALKIN,COMPANY,RELATION_DOCTYPE;
    
    FOR SELECT CATEGORY,SUM(CREDIT) FROM FOGUEST_JUR
        WHERE FOLIO = :FOLIO
        AND FODATE = :FODATE
        AND USERENTRY BETWEEN :SUSERENTRY AND :EUSERENTRY
        AND (CREDIT <> 0)
        AND JURCODE IN ('CR','CL','DEP','CO','FB','TRF')
        GROUP BY CATEGORY
        INTO :CATEGORY,:CREDIT
    DO
    BEGIN
       SELECT NAME,FLAG_CREDITCARD,FLAG_CASH FROM FOCATEGORY
       WHERE CATEGORY = :CATEGORY
       INTO :CATNAME,:FLAG_CREDITCARD,FLAG_CASH;

       IF (PAYMENT_REMARK = '') THEN PAYMENT_REMARK = CATNAME;
       ELSE PAYMENT_REMARK = PAYMENT_REMARK || ',' || CATNAME;

       IF (FLAG_CREDITCARD = 1) THEN CREDITCARD = CREDITCARD + CREDIT;
       ELSE IF (FLAG_CASH = 1) THEN
       BEGIN
          IF (FOLIOSTATUS = 'O') THEN CASH = CASH ;
          ELSE DEPOSIT = DEPOSIT + CREDIT;
       END
       ELSE IF ((CATEGORY = CL1) OR (CATEGORY = CL2) OR (CATEGORY = CL3)) THEN CITYLEDGER = CITYLEDGER + CREDIT;
       ELSE OTHERS = OTHERS + CREDIT;
       TOTAL = TOTAL + CREDIT;
    END
     CASH = NULL;
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
        WHERE FOLIO = :FOLIO
        AND JURCODE NOT IN ( 'CR' ,'DEP' ,'CO')
        INTO :CASH;
    IF (CASH IS NULL) THEN CASH = 0;
    
    PRE_PAYMENT = NULL;
    SELECT SUM(CREDIT) FROM FOGUEST_JUR
        WHERE FOLIO = :FOLIO
        AND FODATE < :FODATE
        AND (CREDIT <> 0)
        AND JURCODE IN ('CR' ,'DEP','CO')
        INTO :PRE_PAYMENT;
    IF (PRE_PAYMENT IS NULL) THEN PRE_PAYMENT = 0;
    
    CHARGE = NULL;
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
        WHERE FOLIO = :FOLIO
        AND JURCODE NOT IN ( 'CR' ,'CL','DEP','CO','TRF')
        INTO :CHARGE;
    IF (CHARGE IS NULL) THEN CHARGE = 0;
    SUSPEND;
  END
  
END^


