ALTER PROCEDURE FO_RPT_WELCOMEDRINK(
    PFOLIO INTEGER)
RETURNS (
    COUNTER INTEGER,
    IDX INTEGER,
    CODE VARCHAR(6),
    FOLIO INTEGER,
    GUESTNAME VARCHAR(80),
    FNAME VARCHAR(80),
    LNAME VARCHAR(80),
    RATECODE VARCHAR(12),
    DATECI DATE,
    DATECO DATE,
    PAX INTEGER,
    CHILD INTEGER,
    ROOM VARCHAR(8),
    ROOMTYPE VARCHAR(4))
AS
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE FLAG_EXIST SMALLINT;
DECLARE VARIABLE X INTEGER;
BEGIN
  COUNTER = 1;
  SELECT FOLIO,FULLNAMEF,FNAME,LNAME,DATECI,DATECO,ROOM,
         ROOMTYPE,PAX,CHILD,RATECODE
  FROM FOGUEST WHERE FOLIO = :PFOLIO
  INTO FOLIO,GUESTNAME,FNAME,LNAME,DATECI,DATECO,ROOM,
         ROOMTYPE,PAX,CHILD,RATECODE;


  BEGIN
    IF (PAX > 0) THEN
    BEGIN
       IDX = 1;
       WHILE (IDX <= PAX) DO
       BEGIN
          CODE = 'P'||IDX;
          IDX = IDX +1;
          COUNTER = COUNTER+1 ;
             SUSPEND;
       END
    END
     END
    END^


