ALTER PROCEDURE GLCOA_USED_INFO
RETURNS (
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    NAME VARCHAR(40),
    SETUP_TITLE VARCHAR(40),
    SETUP_INFO VARCHAR(16),
    SETUP_CODE VARCHAR(8),
    SETUP_NAME VARCHAR(40),
    SETUP_TEXT VARCHAR(40),
    SUBMODULE VARCHAR(40),
    GROUPINFO VARCHAR(40))
AS
DECLARE VARIABLE FLAG_PRODUCTION INTEGER;
BEGIN
  /* ---------------------------------------------------------------- */
  /* CUSTOMER TYPE                                                    */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Customer Account Receivable';
  SETUP_INFO  = 'SYSCUSTOMERTYPE';
  SUBMODULE   = 'AR';
  GROUPINFO   = 'Receivable';
  FOR SELECT T.GLACCOUNT,T.GLDEPT,T.GLCOST,
             COA.NAME,T.CUSTOMERTYPE,T.NAME
      FROM SYSCUSTOMERTYPE T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END

  SETUP_TITLE = 'Customer Reservation Deposit';
  SETUP_INFO  = 'SYSCUSTOMERTYPE';
  SUBMODULE   = 'AP';
  GROUPINFO   = 'Deposit';
  FOR SELECT T.DEPOS_GLACCOUNT,T.DEPOS_GLDEPT,T.DEPOS_GLCOST,
             COA.NAME,T.CUSTOMERTYPE,T.NAME
      FROM SYSCUSTOMERTYPE T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* CREDIT CARD                                                      */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Credit Card';
  SETUP_INFO  = 'SYSCUSTOMERTYPE';
  SUBMODULE   = 'AR';
  GROUPINFO   = 'Credit Card';
  FOR SELECT T.GL_AR_ACCOUNT,T.GL_AR_DEPT,T.GL_AR_COST,
             COA.NAME,T.CREDITCARD,T.NAME
      FROM AR_CARD T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GL_AR_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  
  /* ---------------------------------------------------------------- */
  /* CREDIT CARD FEE                                                  */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Credit Card Fee';
  SETUP_INFO  = 'SYSCUSTOMERTYPE';
  SUBMODULE   = 'AR';
  GROUPINFO   = 'Card Fee';
  FOR SELECT T.GL_FEE_ACCOUNT,T.GL_FEE_DEPT,T.GL_FEE_COST,
             COA.NAME,T.CREDITCARD,T.NAME
      FROM AR_CARD T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GL_AR_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* PHONE EXPENSES CROSSING ACCOUNT                                  */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Phone Expenses - Crossing';
  SETUP_INFO  = 'PBX_PARAM';
  SUBMODULE   = 'Phone';
  GROUPINFO   = 'Crossing';
  SETUP_CODE  = '1';
  SETUP_NAME  = 'System Parameter';
  FOR SELECT T.AR_PBX_GL_ACCOUNT,T.AR_PBX_GL_DEPT,
             T.AR_PBX_GL_COST,COA.NAME
      FROM PBX_PARAM T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.AR_PBX_GL_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* LOCAL - PHONE CALL EXPENSES                                      */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Phone Expenses - Local';
  SETUP_INFO  = 'PBX_DEPT';
  SUBMODULE   = 'Phone';
  GROUPINFO   = 'Phone Expenses';
  FOR SELECT T.GL_ACCOUNT,T.GL_DEPT,T.GL_COST,
             COA.NAME,T.DEPT,T.NAME
      FROM PBX_DEPT T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GL_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* DOMESTIC - PHONE CALL EXPENSES                                   */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Phone Expenses - Domestic';
  SETUP_INFO  = 'PBX_DEPT';
  SUBMODULE   = 'Phone';
  GROUPINFO   = 'Phone Expenses';
  FOR SELECT T.DOMESTIC_GL_ACCOUNT,T.DOMESTIC_GL_DEPT,T.DOMESTIC_GL_COST,
             COA.NAME,T.DEPT,T.NAME
      FROM PBX_DEPT T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.DOMESTIC_GL_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* INTERNATIONAL - PHONE CALL EXPENSES                              */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Phone Expenses - International';
  SETUP_INFO  = 'PBX_DEPT';
  SUBMODULE   = 'PABX';
  GROUPINFO   = 'Phone Expenses';
  FOR SELECT T.INTER_GL_ACCOUNT,T.INTER_GL_DEPT,T.INTER_GL_COST,
             COA.NAME,T.DEPT,T.NAME
      FROM PBX_DEPT T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.INTER_GL_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* MOBILE - PHONE CALL EXPENSES                                     */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Phone Expenses - Mobile';
  SETUP_INFO  = 'PBX_DEPT';
  SUBMODULE   = 'Phone';
  GROUPINFO   = 'Phone Expenses';
  FOR SELECT T.MOBILE_GL_ACCOUNT,T.MOBILE_GL_DEPT,T.MOBILE_GL_COST,
             COA.NAME,T.DEPT,T.NAME
      FROM PBX_DEPT T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.MOBILE_GL_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* DAILY SALES REPORT                                               */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Daily Sales';
  SETUP_INFO  = 'FODSR_LAY_GL';
  SUBMODULE   = 'FO';
  GROUPINFO   = 'Debit';
  FOR SELECT T.DB_ACCOUNT,T.DB_DEPT,T.DB_COST,
             COA.NAME,T.LISTINDEX,T.TEXT
      FROM FODSR_LAY_GL T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.DB_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  
  SETUP_TITLE = 'Daily Sales';
  SETUP_INFO  = 'FODSR_LAY_GL';
  SUBMODULE   = 'FO';
  GROUPINFO   = 'Credit';
  FOR SELECT T.CR_ACCOUNT,T.CR_DEPT,T.CR_COST,
             COA.NAME,T.LISTINDEX,T.TEXT
      FROM FODSR_LAY_GL T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.CR_ACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME,SETUP_CODE,SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* Loss & gain currency dari AR                                     */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Gain & Loss Forex';
  SETUP_INFO  = 'FOSYSPARAM';
  SUBMODULE   = 'AR';
  GROUPINFO   = 'Gain & Loss Forex';
  SETUP_CODE  = '1';
  SETUP_NAME  = 'System Parameter';
  FOR SELECT T.ARFOREX_GAINLOSS_GLACCOUNT,T.ARFOREX_GAINLOSS_GLDEPT,
             T.ARFOREX_GAINLOSS_GLCOST,COA.NAME
      FROM FOSYSPARAM T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.ARFOREX_GAINLOSS_GLACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* Loss & gain currency dari AR                                     */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'A/R Transient';
  SETUP_INFO  = 'FOSYSPARAM';
  SUBMODULE   = 'AR';
  GROUPINFO   = 'Transient';
  SETUP_CODE  = '1';
  SETUP_NAME  = 'System Parameter';
  FOR SELECT T.ARVCH_TRANSIENT_ACC,T.ARVCH_TRANSIENT_DEPT,
             T.ARVCH_TRANSIENT_COST,COA.NAME
      FROM FOSYSPARAM T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.ARFOREX_GAINLOSS_GLACCOUNT
  INTO ACCOUNT,DEPT,COST,NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
END^


ALTER PROCEDURE HCS_AR_REMINDER(
    SCUSTOMER VARCHAR(6))
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    ADDRESS1 VARCHAR(40),
    ADDRESS2 VARCHAR(40),
    ADDRESS3 VARCHAR(40),
    PHONE VARCHAR(40),
    FAX VARCHAR(40),
    FODATE DATE,
    REF VARCHAR(40),
    INVOICE_TOTAL_30 DOUBLE PRECISION,
    INVOICE_TOTAL_60 DOUBLE PRECISION,
    INVOICE_TOTAL_90 DOUBLE PRECISION,
    INVOICE_LIST_30 VARCHAR(255),
    INVOICE_LIST_60 VARCHAR(255),
    INVOICE_LIST_90 VARCHAR(255))
AS
declare variable over30 double precision;
declare variable over60 double precision;
declare variable over90 double precision;
declare variable total double precision;
declare variable number integer;
declare variable m integer;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYSCUSTOMER WHERE CUSTOMER = :SCUSTOMER)) THEN EXIT;
  /*
  181210/AHL/eks/kn/XII/10
  */
  SELECT ADDRESS1,ADDRESS2,ADDRESS3,PHONE,FAX FROM SYSCUSTOMER WHERE CUSTOMER = :SCUSTOMER
  INTO ADDRESS1,ADDRESS2,ADDRESS3,PHONE,FAX;
  
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FODATE;
  REF = EXTRACT(DAY FROM FODATE) ||
        EXTRACT(MONTH FROM FODATE) ||
        SUBSTR(EXTRACT(YEAR FROM FODATE),3,5) ||
        '/AHL/eks/kn/';
  M = EXTRACT(MONTH FROM FODATE);
  IF (M = 1) THEN REF = REF || 'I';
  ELSE IF (M = 2) THEN REF = REF || 'II';
  ELSE IF (M = 3) THEN REF = REF || 'III';
  ELSE IF (M = 4) THEN REF = REF || 'IV';
  ELSE IF (M = 5) THEN REF = REF || 'V';
  ELSE IF (M = 6) THEN REF = REF || 'VI';
  ELSE IF (M = 7) THEN REF = REF || 'VII';
  ELSE IF (M = 8) THEN REF = REF || 'VIII';
  ELSE IF (M = 9) THEN REF = REF || 'IX';
  ELSE IF (M = 10) THEN REF = REF || 'X';
  ELSE IF (M = 11) THEN REF = REF || 'XI';
  ELSE IF (M = 12) THEN REF = REF || 'XII';
  REF = REF || '/' || SUBSTR(EXTRACT(YEAR FROM FODATE),3,5);


  INVOICE_TOTAL_30 = 0;
  INVOICE_TOTAL_60 = 0;
  INVOICE_TOTAL_90 = 0;
  INVOICE_LIST_30 = '';
  INVOICE_LIST_60 = '';
  INVOICE_LIST_90 = '';

  FOR
    SELECT CUSTOMER,NAME,OVER30,
           OVER60,OVER90,TOTAL,NUMBER
    FROM AR_AGING(:SCUSTOMER,:SCUSTOMER,1,'All')
    INTO
      :CUSTOMER,
      :NAME,
      :OVER30,
      :OVER60,
      :OVER90,
      :TOTAL,
      :NUMBER
  DO
  BEGIN
    IF (EXISTS(SELECT * FROM ARVCH WHERE NUMBER = :NUMBER AND FLAG_MERGED = 0)) THEN
    BEGIN
        INVOICE_TOTAL_30 = INVOICE_TOTAL_30 + OVER30;
        INVOICE_TOTAL_60 = INVOICE_TOTAL_60 + OVER60;
        INVOICE_TOTAL_90 = INVOICE_TOTAL_90 + OVER90;
        IF (OVER30 <> 0) THEN
        BEGIN
           IF (INVOICE_LIST_30 <> '') THEN
              INVOICE_LIST_30 = INVOICE_LIST_30 || ',';
           INVOICE_LIST_30 = INVOICE_LIST_30 || NUMBER;
        END
        IF (OVER60 <> 0) THEN
        BEGIN
           IF (INVOICE_LIST_60 <> '') THEN
              INVOICE_LIST_60 = INVOICE_LIST_60 || ',';
           INVOICE_LIST_60 = INVOICE_LIST_60 || NUMBER;
        END
        IF (OVER90 <> 0) THEN
        BEGIN
           IF (INVOICE_LIST_90 <> '') THEN
              INVOICE_LIST_90 = INVOICE_LIST_90 || ',';
           INVOICE_LIST_90 = INVOICE_LIST_90 || NUMBER;
        END
    END
  END
  IF (INVOICE_LIST_30 <> '') THEN INVOICE_LIST_30 = INVOICE_LIST_30 || ' has 30 days overdue.';
  IF (INVOICE_LIST_60 <> '') THEN INVOICE_LIST_60 = INVOICE_LIST_60 || ' has 60 days overdue.';
  IF (INVOICE_LIST_90 <> '') THEN INVOICE_LIST_90 = INVOICE_LIST_90 || ' has 90 days overdue.';
  
  SUSPEND;
END^


ALTER PROCEDURE IF_PHONE_CALC_RATE(
    APHONE VARCHAR(40),
    ADURATION INTEGER,
    AHOUR INTEGER)
RETURNS (
    RZONE VARCHAR(6),
    RSLJJ VARCHAR(30),
    RSLJJ_CITY VARCHAR(40),
    RCHARGE DOUBLE PRECISION,
    RCOST DOUBLE PRECISION,
    RERROR_CODE INTEGER,
    RERROR_MESSAGE VARCHAR(80))
AS
DECLARE VARIABLE I INTEGER;
DECLARE VARIABLE VSURCHARGE INTEGER;
DECLARE VARIABLE VMINIMUM INTEGER;
DECLARE VARIABLE VGRASS INTEGER;
DECLARE VARIABLE VPULSE_DURATION INTEGER;
DECLARE VARIABLE VPULSE_COUNT INTEGER;
DECLARE VARIABLE VPULSE_COST DOUBLE PRECISION;
DECLARE VARIABLE VPULSE_CHARGE DOUBLE PRECISION;
BEGIN
  RZONE = '';
  RSLJJ = '';
  RSLJJ_CITY = '';
  RCHARGE = 0;
  RCOST = 0;
  RERROR_MESSAGE = '';
  RERROR_CODE = 0;
  /* ---------------------------------------------------------------- */
  /* CALC SLJJ CODE & ZONE                                            */
  /* ---------------------------------------------------------------- */
  RZONE = NULL;
  I = 24;
  WHILE ((I > 0) AND (RZONE IS NULL)) DO
  BEGIN
     RSLJJ = SUBSTR(APHONE, 1, I);
     SELECT PBX_ZONE, CITY FROM PBX_SLJJ WHERE SLJJ = :RSLJJ INTO RZONE, RSLJJ_CITY;
     I = I - 1;
  END
  IF (RZONE IS NULL) THEN
  BEGIN
     RSLJJ = '';
     RSLJJ_CITY = '';
     RZONE = '';
  END
  IF (RZONE = '') THEN
  BEGIN
     RERROR_CODE = -1;
     RERROR_MESSAGE = 'Long distance code does not exist';
     SUSPEND;
     EXIT;
  END
  /* ---------------------------------------------------------------- */
  /* CALC PHONE RATE                                                  */
  /* ---------------------------------------------------------------- */
  SELECT SURCHARGE, MINIMUM_DURATION, GRASS_PERIOD, PULSE_DURATION
  FROM PBX_PRICE
  WHERE ZONE = :RZONE
  INTO VSURCHARGE, VMINIMUM, VGRASS, VPULSE_DURATION;

  IF (VPULSE_DURATION IS NULL) THEN VPULSE_DURATION = 0;
  IF (VPULSE_DURATION <= 0) THEN
  BEGIN
     RERROR_CODE = -2;
     RERROR_MESSAGE = 'Zone Setup error: Pulse is zero';
     SUSPEND;
     EXIT;
  END

  IF ((ADURATION < VGRASS) AND (VPULSE_DURATION > 0)) THEN
  BEGIN
     RERROR_CODE = -3;
     RERROR_MESSAGE = 'Duration ('|| ADURATION || ') is less then Grass Period ('||VGRASS||')';
     SUSPEND;
     EXIT;
  END
  /* ---------------------------------------------------------------- */
  /* CALC PULSE BASE ON MINIMUM DURATION & PULSE WIDTH/DIRATION       */
  /* ---------------------------------------------------------------- */
  IF (ADURATION < VMINIMUM) THEN
     VPULSE_COUNT = 1;
  ELSE
     VPULSE_COUNT = (ADURATION +0.5*VPULSE_DURATION)/ VPULSE_DURATION;

  /* ---------------------------------------------------------------- */
  /* GET CHARGE BASE ON HOUR                                          */
  /* ---------------------------------------------------------------- */
  SELECT COST, PRICE FROM PBX_PRICE_HOUR WHERE ZONE = :RZONE AND PHOUR = :AHOUR
  INTO VPULSE_COST, VPULSE_CHARGE;

  IF (RCHARGE IS NULL) THEN
  BEGIN
     RCOST = 0;
     RCHARGE = 0;
     RERROR_CODE = -4;
     RERROR_MESSAGE = 'Price does not exits or Zero';
     SUSPEND;
     EXIT;
  END

  RCOST = VPULSE_COST * VPULSE_COUNT;
  RCHARGE = VSURCHARGE + VPULSE_CHARGE * VPULSE_COUNT;
  SUSPEND;
END^


ALTER PROCEDURE LIST_CUSTOMER
RETURNS (
    ACCOUNT VARCHAR(20),
    ADDRESS1 VARCHAR(40),
    CONTACT VARCHAR(40),
    CONTACTTITLE VARCHAR(40),
    CREDITFACILITY VARCHAR(10),
    CREDITLIMIT DOUBLE PRECISION,
    CUSTAREA VARCHAR(4),
    CUSTOMER VARCHAR(6),
    PHONE VARCHAR(40),
    CUSTTYPE VARCHAR(4),
    NAMECUST VARCHAR(40),
    DUE VARCHAR(2),
    NAMETYPE VARCHAR(40))
AS
BEGIN
  FOR
    SELECT A.ACCOUNT,A.ADDRESS1,A.CONTACT,
           A.CONTACTTITLE,A.CREDITFACILITY,A.CREDITLIMIT,
           A.CUSTAREA,A.CUSTOMER,A.PHONE,A.CUSTTYPE,A.NAME NAMECUST,A.DUE,
           B.NAME NAMETYPE FROM SYSCUSTOMER A
    LEFT JOIN SYSCUSTOMERTYPE B ON B.CUSTOMERTYPE =A.CUSTTYPE
    WHERE FLAG_ACTIVE ='1'
    ORDER BY A.CUSTTYPE,A.NAME
    
    
    
    

    INTO
      :ACCOUNT,
      :ADDRESS1,
      :CONTACT,
      :CONTACTTITLE,
      :CREDITFACILITY,
      :CREDITLIMIT,
      :CUSTAREA,
      :CUSTOMER,
      :PHONE,
      :CUSTTYPE,
      :NAMECUST,
      :DUE,
      :NAMETYPE
  DO
  BEGIN
  IF (CREDITFACILITY='1') THEN CREDITFACILITY='CREDIT';
  IF (CREDITFACILITY='0') THEN CREDITFACILITY='CASH';
    SUSPEND;
  END
END^


