ALTER PROCEDURE PBX_SAVE_CALL_RECORD(
    PTIME VARCHAR(5),
    PHOUR SMALLINT,
    EXTENTION VARCHAR(8),
    PHONE VARCHAR(30),
    DURATION INTEGER,
    TRUNK VARCHAR(6),
    USER_ID VARCHAR(6))
RETURNS (
    ID INTEGER,
    FODATE DATE,
    ROOM VARCHAR(8),
    CHARGE DOUBLE PRECISION,
    COST DOUBLE PRECISION,
    FOLIO INTEGER,
    DEPT VARCHAR(4),
    ERROR_CODE VARCHAR(20),
    SLJJ VARCHAR(12),
    CITY VARCHAR(40),
    REMARK VARCHAR(80),
    STATUS CHAR(1),
    PBX_ZONE CHAR(6),
    HOUSE_USE INTEGER)
AS
BEGIN
  SELECT FOSYSDATE FROM FOSYSPARAM /* 3 AGUSTUS 04 */
  WHERE ID = 1
  INTO :FODATE;

  if (EXTENTION IS NULL) then
  BEGIN
     SUSPEND;
     EXIT;
  END
  
  if (USER_ID IS NULL) then USER_ID = '';
  if (USER_ID <> '') then
  BEGIN
    if (NOT EXISTS(SELECT * FROM pbx_password WHERE USER_ID = :USER_ID)) then
    BEGIN
       INSERT INTO pbx_password
         (USER_ID, NAME, EXTENTION_ALIAS, CREATEDATE, EDITDATE)
       VALUES
         (:USER_ID, 'Auto create', :EXTENTION, 'NOW', 'NOW');
    END
  END
  if (NOT EXISTS(SELECT * FROM pbx_extention WHERE EXTENTION = :EXTENTION)) then
  BEGIN
     INSERT INTO PBX_EXTENTION
       (EXTENTION, NAME, ROOM, DEPT, FOLIO, HOUSE_USE, CREATEDATE, EDITDATE)
     VALUES
       (:EXTENTION, 'Auto create', :EXTENTION, '',0,0, 'NOW', 'NOW');
  END
  /* 3 AGUSTUS 04 */
  if (PTIME IS NOT NULL) then
  BEGIN
    INSERT INTO PBX_CALL_LOG
    (PTIME, PHOUR, EXTENTION, PHONE, DURATION, TRUNK, USERID)
    VALUES
    (:PTIME,:PHOUR,:EXTENTION,:PHONE,:DURATION,:TRUNK,:USER_ID); /* 3 AGUSTUS 04 */
  END
  
  
  ID = GEN_ID(GEN_PBX_CALL_LOG_ID,0);
  SELECT ROOM, CHARGE, COST, FOLIO, DEPT, ERROR_CODE, SLJJ, STATUS, PBX_ZONE, HOUSE_USE
  FROM PBX_CALL_LOG
  WHERE ID = :ID
  INTO ROOM, CHARGE, COST, FOLIO, DEPT, ERROR_CODE, SLJJ, STATUS, PBX_ZONE, HOUSE_USE;
  
  
  SELECT CITY FROM pbx_sljj WHERE SLJJ = :SLJJ
  INTO CITY;
     
  
  if (ERROR_CODE = '') then
  BEGIN
     if ((ROOM <> '') or (FOLIO <> 0)) then BEGIN
         SELECT FULLNAMEF FROM FOGUEST WHERE FOLIO = :FOLIO
         INTO :REMARK;
     END
     ELSE
     BEGIN
         SELECT NAME FROM pbx_dept
         WHERE DEPT = :DEPT
         INTO :REMARK;
     END
  END
  ELSE REMARK = ERROR_CODE;
       
  SUSPEND;
  
END^


