ALTER PROCEDURE PPIC_SAVE_ALERT(
    EVENT_NAME VARCHAR(40),
    CMD VARCHAR(40),
    CMD_NAME VARCHAR(80),
    PARAM1 VARCHAR(80),
    PARAM2 VARCHAR(80),
    PARAM3 VARCHAR(80),
    PARAM4 VARCHAR(80),
    ROOM VARCHAR(6),
    FOLIO INTEGER)
RETURNS (
    COUNTER INTEGER)
AS
DECLARE VARIABLE ID VARCHAR(4);
DECLARE VARIABLE EXTENTION VARCHAR(8);
DECLARE VARIABLE OEXTENTION VARCHAR(8);
DECLARE VARIABLE FLAG_CONVERT_RE_TO_GC INTEGER;
DECLARE VARIABLE XEVENT_NAME VARCHAR(40);
BEGIN
  /* ---------------------------------------------------------------- */
  /* post event for MyIFC                                             */
  /* 11 desember 2007                                                 */
  /* ---------------------------------------------------------------- */
  IF ((EVENT_NAME = '') OR (EVENT_NAME IS NULL)) THEN
  BEGIN
     EVENT_NAME = 'CI';
  END

  COUNTER = 0;


  IF (FOLIO IS NULL) THEN FOLIO = 0;
  IF (ROOM IS NULL) THEN ROOM = '';
  IF ((FOLIO = 0) AND (ROOM ='')) THEN EXIT;
  IF (ROOM = '') THEN 
     SELECT ROOM FROM FOGUEST WHERE FOLIO = :FOLIO INTO :ROOM;
  IF (ROOM IS NULL) THEN ROOM = '';
  FOR SELECT E.ID, I.FLAG_CONVERT_RE_TO_GC FROM PPIC_EVENT_REGISTERED E
      LEFT JOIN PPIC_INTERFACE I ON I.ID = E.ID
      WHERE E.EVENT_NAME = :EVENT_NAME
      AND I.FLAG_ACTIVE = 1
      INTO ID, FLAG_CONVERT_RE_TO_GC
  DO
  BEGIN
     /* -------------------------------------------------------------------- */
     /* 8/11/2011                                                            */
     /* -------------------------------------------------------------------- */
     XEVENT_NAME = EVENT_NAME;
     IF ((FLAG_CONVERT_RE_TO_GC=1) AND (XEVENT_NAME='RE')) THEN
        XEVENT_NAME = 'GC';
     /* -------------------------------------------------------------------- */
     IF (ID IN ('PB','CA')) THEN
     BEGIN
        IF (ROOM <> '') THEN
        BEGIN
           FOR SELECT EXTENTION FROM PBX_EXTENTION WHERE ROOM = :ROOM
               INTO EXTENTION
           DO
           BEGIN
              IF (CMD = 'ROOMCHANGE') THEN
              BEGIN
                 FOR SELECT EXTENTION FROM PBX_EXTENTION WHERE ROOM = :PARAM1 /* OLD ROOM */
                     INTO OEXTENTION
                 DO
                 BEGIN
                    INSERT INTO PPIC_EVENT_QUEUE(ID, EVENT_NAME, RETRY, CMD, CMD_NAME, PARAM1, SYSDATE, SENT, ROOM, FOLIO)
                    VALUES (:ID, :XEVENT_NAME, 0, :CMD, :CMD_NAME, :OEXTENTION, 'NOW', 0, :EXTENTION, :FOLIO);
                    COUNTER = COUNTER + 1;
                 END
              END
              ELSE
              BEGIN
                 INSERT INTO PPIC_EVENT_QUEUE(ID, EVENT_NAME, RETRY, CMD, CMD_NAME, PARAM1, SYSDATE, SENT, ROOM, FOLIO)
                 VALUES (:ID, :XEVENT_NAME, 0, :CMD, :CMD_NAME, :PARAM1, 'NOW', 0, :EXTENTION, :FOLIO);
                 COUNTER = COUNTER + 1;
              END
           END
        END
     END
     ELSE
     BEGIN
        INSERT INTO PPIC_EVENT_QUEUE(ID, EVENT_NAME, RETRY, CMD, CMD_NAME, PARAM1, SYSDATE, SENT, ROOM, FOLIO)
        VALUES (:ID, :XEVENT_NAME, 0, :CMD, :CMD_NAME, :PARAM1, 'NOW', 0, :ROOM, :FOLIO);
        COUNTER = COUNTER + 1;
     END
     
     UPDATE PPIC_EVENT_REGISTERED SET COUNTER = COUNTER + :COUNTER
     WHERE ID = :ID AND EVENT_NAME = :EVENT_NAME;

     WHEN ANY
     DO
     BEGIN
        ID = ID;
     END

  END
  SUSPEND;
END^


ALTER PROCEDURE RPT_HCS_INHOUSE_FB
RETURNS (
    FOLIO INTEGER,
    GROUPNUMBER INTEGER,
    GUESTNAME VARCHAR(80),
    ROOM VARCHAR(8),
    ROOMTYPE VARCHAR(10),
    FOLIOTYPE VARCHAR(1),
    DATECI DATE,
    DATECO DATE,
    PAX INTEGER,
    RATECODE VARCHAR(16),
    ST_NATIONALITY VARCHAR(4),
    COMPANYNAME VARCHAR(40),
    TOTAL_REVENUE DOUBLE PRECISION,
    TOTAL_ROOMNIGHT DOUBLE PRECISION,
    TOTAL_STAY DOUBLE PRECISION,
    MEAL_PKG DOUBLE PRECISION)
AS
DECLARE VARIABLE FOSYSDATE DATE;
begin
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;
  FOR SELECT GS.FOLIO,GS.GROUPNUMBER,GS.ROOM,GS.ROOMTYPE,GS.FULLNAMEF,GS.FOLIOTYPE,GS.DATECI,GS.DATECO,GS.PAX,
       GS.ST_NATIONALITY,GS.COMPANYNAME,H.TOTAL_REVENUE,
       H.TOTAL_ROOMNIGHT,H.TOTAL_STAY,GS.RATECODE
  FROM FOGUEST GS
   LEFT JOIN FO_HIST_GUEST H ON H.HISTORY = GS.HISTORY
   WHERE GS.FOLIOTYPE = 'P'
   AND GS.FOLIOSTATUS = 'I'
   AND GS.FOLIOSTATUS_SHARE = 'M'
   ORDER BY GS.ROOM
  INTO FOLIO,GROUPNUMBER,ROOM,ROOMTYPE,GUESTNAME,FOLIOTYPE,DATECI,DATECO,PAX,
       ST_NATIONALITY,COMPANYNAME,TOTAL_REVENUE,TOTAL_ROOMNIGHT,
       TOTAL_STAY,RATECODE
  DO
  BEGIN
     IF (TOTAL_REVENUE IS NULL) THEN
     BEGIN
        TOTAL_REVENUE = 0;
        TOTAL_ROOMNIGHT = 0;
        TOTAL_STAY = 0;
     END
     
     /* POSTING DILAKUKAN KEMARIN   ELSE   */

     IF (EXISTS(SELECT * FROM FOGUEST_JUR WHERE FOLIO_ORIGINAL = :FOLIO AND FODATE = :FOSYSDATE-1 AND JURCODE = 'NA')) THEN
     BEGIN
        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        LEFT JOIN FOPACKAGE P ON P.PACKAGE = JR.package_code
        WHERE JR.FOLIO_ORIGINAL = :FOLIO
        AND JR.FODATE = :FOSYSDATE-1
        AND JR.PACKAGE_ALLOWANCE = 1
        AND P.PACKAGE_TYPE = 'MBF'
        INTO MEAL_PKG;
     END
     ELSE
     /* ROOM RATE SUDAH DIPOSTING HARI INI   */
     IF (EXISTS(SELECT * FROM FOGUEST_JUR WHERE FOLIO_ORIGINAL = :FOLIO AND FODATE = :FOSYSDATE AND JURCODE = 'NA')) THEN
     BEGIN
        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        LEFT JOIN FOPACKAGE P ON P.PACKAGE = JR.package_code
        WHERE JR.FOLIO_ORIGINAL = :FOLIO
        AND JR.FODATE = :FOSYSDATE
        AND JR.PACKAGE_ALLOWANCE = 1
        AND P.PACKAGE_TYPE = 'MBF'
        INTO MEAL_PKG;
     END
         /* bELUM pOSTING SaMA SEKALI */
           ELSE
     BEGIN
        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FO_RATE_FOLIO(:FOLIO) JR
        LEFT JOIN FOPACKAGE P ON P.PACKAGE = JR.package_code
        WHERE JR.PACKAGE_ALLOWANCE = 1
        AND JR.TRANSDATE = :FOSYSDATE
        AND P.PACKAGE_TYPE = 'MBF'
        INTO MEAL_PKG;

     END
     IF (MEAL_PKG IS NULL) THEN MEAL_PKG = 0;

     suspend;
  END
end^


ALTER PROCEDURE RPT_HCS_INHOUSE_PKG_ALLOWANCE(
    PACKAGE_TYPE VARCHAR(4))
RETURNS (
    FOLIO INTEGER,
    GUESTNAME VARCHAR(80),
    ROOM VARCHAR(8),
    ROOMTYPE VARCHAR(8),
    FOLIOTYPE VARCHAR(1),
    DATECI DATE,
    DATECO DATE,
    PAX INTEGER,
    RATECODE VARCHAR(16),
    ST_NATIONALITY VARCHAR(4),
    COMPANYNAME VARCHAR(40),
    TOTAL_REVENUE DOUBLE PRECISION,
    TOTAL_ROOMNIGHT DOUBLE PRECISION,
    TOTAL_STAY DOUBLE PRECISION,
    TOTAL_RATE DOUBLE PRECISION,
    ROOM_REVENUE DOUBLE PRECISION,
    PKG_ALLOWANCE DOUBLE PRECISION,
    DATA_SOURCE VARCHAR(8))
AS
DECLARE VARIABLE FOSYSDATE DATE;
begin
  IF ((PACKAGE_TYPE IS NULL) OR (PACKAGE_TYPE = '')) THEN PACKAGE_TYPE = 'MBF';
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;
  FOR SELECT GS.FOLIO,GS.ROOM,GS.ROOMTYPE,GS.FULLNAMEF,GS.FOLIOTYPE,GS.DATECI,GS.DATECO,GS.PAX,
       GS.ST_NATIONALITY,GS.COMPANYNAME,H.TOTAL_REVENUE,
       H.TOTAL_ROOMNIGHT,H.TOTAL_STAY,GS.RATECODE
  FROM FOGUEST GS
   LEFT JOIN FO_HIST_GUEST H ON H.HISTORY = GS.HISTORY
   WHERE GS.FOLIOTYPE = 'P'
   AND GS.FOLIOSTATUS = 'I'
   AND GS.FOLIOSTATUS_SHARE = 'M'
   ORDER BY GS.ROOM
  INTO FOLIO,ROOM,ROOMTYPE,GUESTNAME,FOLIOTYPE,DATECI,DATECO,PAX,
       ST_NATIONALITY,COMPANYNAME,TOTAL_REVENUE,TOTAL_ROOMNIGHT,
       TOTAL_STAY,RATECODE
  DO
  BEGIN
     PKG_ALLOWANCE = 0;
     TOTAL_RATE = 0;
     ROOM_REVENUE = 0;
     /* ROOM RATE SUDAH DIPOSTING HARI INI */
     IF (EXISTS(SELECT * FROM FOGUEST_JUR WHERE FOLIO = :FOLIO AND FODATE = :FOSYSDATE AND JURCODE = 'NA')) THEN
     BEGIN
        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        LEFT JOIN FOPACKAGE P ON P.PACKAGE = JR.package_code
        WHERE JR.FOLIO = :FOLIO
        AND JR.FODATE = :FOSYSDATE
        AND JR.PACKAGE_ALLOWANCE = 1
        AND JR.JURCODE = 'NA'
        AND P.PACKAGE_TYPE = :PACKAGE_TYPE
        INTO PKG_ALLOWANCE;

        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        WHERE JR.FOLIO = :FOLIO
        AND JR.FODATE = :FOSYSDATE
        AND JR.JURCODE = 'NA'
        INTO TOTAL_RATE;


        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY = JR.CATEGORY
        WHERE JR.FOLIO = :FOLIO
        AND JR.FODATE = :FOSYSDATE
        AND JR.JURCODE = 'NA'
        AND CAT.CLASS = 1
        INTO ROOM_REVENUE;

        DATA_SOURCE = 'TODAY';
     END
     /* POSTING DILAKUKAN KEMARIN */
     ELSE
     IF (EXISTS(SELECT * FROM FOGUEST_JUR WHERE FOLIO = :FOLIO AND FODATE = :FOSYSDATE-1 AND JURCODE = 'NA')) THEN
     BEGIN
        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        LEFT JOIN FOPACKAGE P ON P.PACKAGE = JR.package_code
        WHERE JR.FOLIO = :FOLIO
        AND JR.FODATE = :FOSYSDATE-1
        AND JR.PACKAGE_ALLOWANCE = 1
        AND P.PACKAGE_TYPE = :PACKAGE_TYPE
        AND JR.JURCODE = 'NA'
        INTO PKG_ALLOWANCE;

        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        WHERE JR.FOLIO = :FOLIO
        AND JR.FODATE = :FOSYSDATE-1
        AND JR.JURCODE = 'NA'
        INTO TOTAL_RATE;


        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FOGUEST_JUR JR
        LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY = JR.CATEGORY
        WHERE JR.FOLIO = :FOLIO
        AND JR.FODATE = :FOSYSDATE-1
        AND JR.JURCODE = 'NA'
        AND CAT.CLASS = 1
        INTO ROOM_REVENUE;

        DATA_SOURCE = 'YESTDY';
     END
     /* SAMA SEKALI BELUM DIPOSTING */
     ELSE
     BEGIN
        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FO_RATE_FOLIO(:FOLIO) JR
        LEFT JOIN FOPACKAGE P ON P.PACKAGE = JR.package_code
        WHERE JR.TRANSDATE = :FOSYSDATE
        AND JR.PACKAGE_ALLOWANCE = 1
        AND P.PACKAGE_TYPE = :PACKAGE_TYPE
        INTO PKG_ALLOWANCE;

        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FO_RATE_FOLIO(:FOLIO) JR
        WHERE TRANSDATE = :FOSYSDATE
        INTO TOTAL_RATE;


        SELECT SUM(JR.DEBIT-JR.CREDIT) FROM FO_RATE_FOLIO(:FOLIO) JR
        LEFT JOIN FOCATEGORY CAT ON CAT.CATEGORY = JR.CATEGORY
        WHERE TRANSDATE = :FOSYSDATE
        AND CAT.CLASS = 1
        INTO ROOM_REVENUE;

        DATA_SOURCE = 'RATE';
     END
     IF (PKG_ALLOWANCE IS NULL) THEN PKG_ALLOWANCE = 0;
     IF (TOTAL_RATE IS NULL) THEN TOTAL_RATE = 0;
     IF (ROOM_REVENUE IS NULL) THEN ROOM_REVENUE = 0;
     suspend;
  END
end^


ALTER PROCEDURE SBMB_FO_RS_VIEW(
    FODATE DATE)
RETURNS (
    STATDATE DATE,
    LISTINDEX INTEGER,
    TEXT VARCHAR(40),
    TODAY DOUBLE PRECISION,
    MTD DOUBLE PRECISION,
    YTD DOUBLE PRECISION,
    L_MTD DOUBLE PRECISION,
    L_YTD DOUBLE PRECISION,
    TODAY_BUDGET DOUBLE PRECISION,
    DAILY_MTD_BUDGET DOUBLE PRECISION,
    DAILY_YTD_BUDGET DOUBLE PRECISION,
    BUDGET_MTD DOUBLE PRECISION,
    BUDGET_YTD DOUBLE PRECISION,
    FORECAST_MTD DOUBLE PRECISION,
    FORECAST_YTD DOUBLE PRECISION,
    VARIANCE_TODAY DOUBLE PRECISION,
    VARIANCE_MTD DOUBLE PRECISION,
    VARIANCE_DAILY_MTD DOUBLE PRECISION,
    VARIANCE_DAILY_YTD DOUBLE PRECISION,
    VARIANCE_YTD DOUBLE PRECISION,
    BOLD SMALLINT,
    VISIBLE SMALLINT,
    FONTSIZE SMALLINT,
    FORMAT VARCHAR(40),
    INFO VARCHAR(40),
    WEB INTEGER)
AS
DECLARE VARIABLE FOSYSDATE DATE;
DECLARE VARIABLE BOM DATE;
DECLARE VARIABLE EOM DATE;
DECLARE VARIABLE BOY DATE;
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
DECLARE VARIABLE PDAY INTEGER;
DECLARE VARIABLE PDAYOFMONTH INTEGER;
DECLARE VARIABLE PFACTOR DOUBLE PRECISION;
DECLARE VARIABLE FODATE_LYEAR DATE;
DECLARE VARIABLE FODATE_LMONTH DATE;
DECLARE VARIABLE BOY_LYEAR DATE;
DECLARE VARIABLE BOM_LMONTH DATE;
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE X INTEGER;
DECLARE VARIABLE XSALE INTEGER;
DECLARE VARIABLE XTOT INTEGER;
DECLARE VARIABLE XRR DOUBLE PRECISION;
DECLARE VARIABLE XOCC INTEGER;
DECLARE VARIABLE XPAX INTEGER;
DECLARE VARIABLE XWI INTEGER;
DECLARE VARIABLE YSALE INTEGER;
DECLARE VARIABLE YRR DOUBLE PRECISION;
DECLARE VARIABLE YOCC DOUBLE PRECISION;
DECLARE VARIABLE YPAX INTEGER;
DECLARE VARIABLE YWI INTEGER;
DECLARE VARIABLE ZSALE INTEGER;
DECLARE VARIABLE ZRR DOUBLE PRECISION;
DECLARE VARIABLE ZOCC DOUBLE PRECISION;
DECLARE VARIABLE ZPAX INTEGER;
DECLARE VARIABLE ZWI INTEGER;
BEGIN
  SELECT FOSYSDATE FROM FOSYSPARAM WHERE ID = 1 INTO :FOSYSDATE;
  if ((FODATE IS NULL) or (FODATE > FOSYSDATE)) then FODATE = :FOSYSDATE;
   EXECUTE PROCEDURE SP_DATE_BOM(:FODATE) RETURNING_VALUES BOM;
    EXECUTE PROCEDURE SP_DATE_BOY(:FODATE) RETURNING_VALUES BOY;
    EXECUTE PROCEDURE SP_DAYOFYEAR (:FODATE) RETURNING_VALUES PDAY;
  SELECT COUNT(*) FROM FOSTAT_RS
  WHERE FODATE = :FODATE
  INTO X;
    STATDATE=:FODATE;

  if (X = 0) then
  BEGIN
    FOR SELECT TODAY,
             LISTINDEX,
             TEXT,
             MTD,
             YTD,
             L_MTD,
             L_YTD,
             BUDGET_MTD,
             BUDGET_YTD,
             FORECAST_MTD,
             FORECAST_YTD,
             VARIANCE_MTD,
             VARIANCE_YTD,
             BOLD,
             VISIBLE,
             FONTSIZE,
             FORMAT,
             INFO,
             WEB
      FROM fo_rs_view_calculate(:FODATE)
      INTO :TODAY,
           :LISTINDEX,
           :TEXT,
           :MTD,
           :YTD,
           :L_MTD,
           :L_YTD,
           :BUDGET_MTD,
           :BUDGET_YTD,
           :FORECAST_MTD,
           :FORECAST_YTD,
           :VARIANCE_MTD,
           :VARIANCE_YTD,
           :BOLD,
           :VISIBLE,
           :FONTSIZE,
           :FORMAT,
           :INFO,
           :WEB
    DO
    BEGIN
    /* TODAY BUDGET
        SELECT OCCUPIED from FO_HIST_ZRS_DAILY WHERE FODATE=:FODATE
        INTO TODAY_BUDGET;                    */
       if (BUDGET_MTD IS NULL) then BUDGET_MTD = 0;
       if (BUDGET_YTD IS NULL) then BUDGET_YTD = 0;
       
       if (FORECAST_MTD IS NULL) then FORECAST_MTD = 0;
       if (FORECAST_YTD IS NULL) then FORECAST_YTD = 0;
       
       INSERT INTO FOSTAT_RS
              (FODATE,LISTINDEX,TEXT,TODAY,MTD,YTD,L_MTD,L_YTD,
               BUDGET_MTD,BUDGET_YTD,FORECAST_MTD,FORECAST_YTD)
       VALUES (:FODATE,:LISTINDEX,:TEXT,:TODAY,:MTD,:YTD,:L_MTD,:L_YTD,
               :BUDGET_MTD,:BUDGET_YTD,:FORECAST_MTD,:FORECAST_YTD);

      SUSPEND;
    END
    EXIT;
  END

  /* JIKA DATA SUDAH ADA DI TABLE */
  FOR SELECT RS.TODAY,
             RS.LISTINDEX,
             RS.TEXT,
             RS.MTD,
             RS.YTD,
             RS.L_MTD,
             RS.L_YTD,
             RS.BUDGET_MTD,
             RS.BUDGET_YTD,
             RS.FORECAST_MTD,
             RS.FORECAST_YTD,
             LY.BOLD,
             LY.VISIBLE,
             LY.FONTSIZE,
             LY.DATA_FORMAT,
             LY.INFO,
             LY.WEB
      FROM FOSTAT_RS RS
      LEFT JOIN FO_HIST_ZRS_LAYOUT LY ON LY.LISTINDEX = RS.LISTINDEX
      WHERE RS.FODATE = :FODATE
      INTO :TODAY,
           :LISTINDEX,
           :TEXT,
           :MTD,
           :YTD,
           :L_MTD,
           :L_YTD,
           :BUDGET_MTD,
           :BUDGET_YTD,
           :FORECAST_MTD,
           :FORECAST_YTD,
           :BOLD,
           :VISIBLE,
           :FONTSIZE,
           :FORMAT,
           :INFO,
           :WEB

  DO
  BEGIN
    VARIANCE_MTD = MTD-BUDGET_MTD;
    VARIANCE_YTD = YTD-BUDGET_YTD;  
     SUSPEND;
  END
END^


ALTER PROCEDURE SBMB_INFO_DESKTOP
RETURNS (
    INFOTYPE VARCHAR(8),
    TEXT VARCHAR(40),
    DATA1 INTEGER)
AS
DECLARE VARIABLE FODATE DATE;
DECLARE VARIABLE TOTAL INTEGER;
DECLARE VARIABLE OOO INTEGER;
DECLARE VARIABLE OINV INTEGER;
DECLARE VARIABLE HU INTEGER;
DECLARE VARIABLE SALEABLE INTEGER;
BEGIN
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FODATE;
   /* ---------------------------------------------------------------- */
  /* GUEST VIP                                               */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM FOGUEST
  WHERE FOLIOTYPE = 'P'
  AND VIPLEVEL >0
  AND FOLIOSTATUS='I'
  INTO DATA1;
  INFOTYPE = 'VIP';
  TEXT = '   Guest VIP';

  IF (DATA1 IS NULL) THEN DATA1 = 0;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* EXPECTED MICE-ARRIVAL                                               */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM FOGUEST
  WHERE FOLIOTYPE = 'G'
  AND DATECI = :FODATE
  AND FOLIOSTATUS IN ('T','G','C')
  INTO DATA1;
  INFOTYPE = 'MICE-CI';
  TEXT = '   Expected Arrival MICE';

  IF (DATA1 IS NULL) THEN DATA1 = 0;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* EXPECTED MICE-DEPARTURE                                                 */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM FOGUEST
  WHERE FOLIOTYPE = 'G'
  AND DATECO = :FODATE
  AND FOLIOSTATUS='I'
  INTO DATA1;
  INFOTYPE = 'MICE-CO';
  TEXT = '   Expected Departure MICE';

  IF (DATA1 IS NULL) THEN DATA1 = 0;
  SUSPEND;
   /* ---------------------------------------------------------------- */
  /* GUEST BIRTHDAY                                                */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM FOGUEST
  WHERE FOLIOTYPE = 'P'
  AND EXTRACT(DAY FROM BIRTHDAY)=EXTRACT(DAY FROM :FODATE)
  AND EXTRACT(MONTH FROM BIRTHDAY)=EXTRACT(MONTH FROM :FODATE)
  AND FOLIOSTATUS='I'
  AND FOLIOSTATUS_SHARE='M'
  INTO DATA1;
  INFOTYPE = 'BIRTHDAY';
  TEXT = '   Guest Birthday';

  IF (DATA1 IS NULL) THEN DATA1 = 0;
  SUSPEND;
   /* ---------------------------------------------------------------- */
  /* Repeater                                               */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM FOGUEST
  WHERE FOLIOTYPE = 'P'
  AND DATECI = :FODATE
  AND FOLIOSTATUS='I'
  AND FOLIOSTATUS_SHARE='M'
  AND HISTORY <>'0'
  INTO DATA1;
  INFOTYPE = 'REPEAT';
  TEXT = '   Repeater Guest ';

  IF (DATA1 IS NULL) THEN DATA1 = 0;
  SUSPEND;
    /* ---------------------------------------------------------------- */
  /* Long Stay                                              */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM FOGUEST
  WHERE FOLIOTYPE = 'P'
  AND ROOMNIGHT >= 14
  AND FOLIOSTATUS='I'
  AND FOLIOSTATUS_SHARE='M'
  AND RATECODE NOT IN ('HU','COMPL')
  INTO DATA1;
  INFOTYPE = 'LONGSTAY';
  TEXT = '   Long Stay Guest';

  IF (DATA1 IS NULL) THEN DATA1 = 0;
  SUSPEND;

END^


ALTER PROCEDURE SMS_REQUEST(
    AREQUEST VARCHAR(16))
RETURNS (
    RDATATYPE VARCHAR(8),
    RTEXT VARCHAR(40),
    RAMOUNT DOUBLE PRECISION,
    RDATE DATE,
    RFORMAT VARCHAR(40),
    RFACTOR DOUBLE PRECISION)
AS
declare variable OPENING NUMERIC(15,4);
declare variable VOUCHER NUMERIC(15,4);
declare variable DEPOSIT NUMERIC(15,4);
declare variable CASH NUMERIC(15,4);
declare variable ADJUST NUMERIC(15,4);
declare variable ENDING NUMERIC(15,4);
declare variable XDATE DATE;

declare variable I INTEGER;
declare variable DATA_FIELD_INDEX VARCHAR(16);
begin
  if (AREQUEST IS NULL) then AREQUEST = 'IA';
  if (AREQUEST = 'AR') then
  BEGIN
     SELECT ARSYSDATE FROM FOSYSPARAM WHERE ID = 1
     INTO RDATE;
     RTEXT = 'AR-Date';
     RDATATYPE = 'DATE';
     SUSPEND;
     
     SELECT SUM(OPENING),SUM(VOUCHER),
            SUM(CASH),SUM(ADJUST),SUM(ENDING)
     FROM ar_mutation(NULL,NULL)
     WHERE CREDITCARD = 0
     INTO OPENING,VOUCHER,CASH,ADJUST,ENDING;
     RFACTOR = 1;
     RDATE = NULL;
     RDATATYPE = '$';
     RFORMAT   = '#,##0.00;(#,##0.00);';

     RTEXT = 'Opn:';
     RAMOUNT = OPENING;
     SUSPEND;
     
     RTEXT = 'Vch:';
     RAMOUNT = VOUCHER;
     SUSPEND;     
     
     RTEXT = 'Csh:';
     RAMOUNT = CASH;
     SUSPEND;          
     
     if (ADJUST <> 0) then
     BEGIN
       RTEXT = 'Adj:';
       RAMOUNT = ADJUST;
       SUSPEND;
     END
     
     RTEXT = 'End:';
     RAMOUNT = ENDING;
     SUSPEND;          
  END
  if (AREQUEST = 'IA') then
  BEGIN
     SELECT FOSYSDATE-1 FROM FOSYSPARAM WHERE ID = 1
     INTO RDATE;
     RTEXT = 'FO-Date';
     RDATATYPE = 'DATE';
     SUSPEND;  
     FOR SELECT TEXT,DATA_FIELD,DATA_FORMAT,DATA_FACTOR,DATA_TYPE,DATA_FIELD_INDEX FROM sms_info
         WHERE REQUEST = 'IA'
         AND DATA_TABLE = 'FODSR'
         ORDER BY LISTINDEX
         INTO RTEXT,I,RFORMAT,RFACTOR,RDATATYPE,DATA_FIELD_INDEX
     DO
     BEGIN
        if (DATA_FIELD_INDEX IS NULL) then DATA_FIELD_INDEX = '';
        if (DATA_FIELD_INDEX = '') then
        BEGIN
          SELECT AMOUNT+ADJUSTMENT FROM FODSR
          WHERE FODATE = :RDATE
          AND DSR_ID = :I
          INTO RAMOUNT;
        END
        if (DATA_FIELD_INDEX = 'MTD') then
        BEGIN
          SELECT MTD FROM FODSR
          WHERE FODATE = :RDATE
          AND DSR_ID = :I
          INTO RAMOUNT;
        END        
        if (DATA_FIELD_INDEX = 'YTD') then
        BEGIN
          SELECT YTD FROM FODSR
          WHERE FODATE = :RDATE
          AND DSR_ID = :I
          INTO RAMOUNT;
        END                
        SUSPEND;
        RAMOUNT = 0;
     END
  END
end^


