/*  INFO='MEAL';
  NAME = 'Meal Pondokan ' ;
  SELECT REV_MEAL_OUTSIDE FROM sp_bq_sales_list (:SFOLIO)
  INTO :CHARGE ;
  CHARGE=0 ;
  SUSPEND ;

