ALTER PROCEDURE SP_BQ_CHARGE(
    PFOLIO INTEGER)
RETURNS (
    FODATE DATE,
    CATEGORY VARCHAR(4),
    NAME VARCHAR(40),
    REMARK VARCHAR(40),
    REFERENCE VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SOURCE VARCHAR(4),
    SOURCE_ID INTEGER,
    SOURCE_STATUS CHAR(1),
    FLAG_TAX INTEGER)
AS
declare variable CODE VARCHAR(8);
declare variable TAXID INTEGER;
declare variable TAX_INCLUDED INTEGER;
declare variable PERCENT DOUBLE PRECISION;
declare variable DB DOUBLE PRECISION;
begin
  if (PFOLIO IS NULL) then
     PFOLIO = 2121;

  SOURCE = 'MEAL';
  FOR SELECT FODATE, CATEGORY, TOTAL_CHARGE, ID, MEAL_PERIOD, STATUS
      FROM BQ_MASTER_MEAL
      WHERE FOLIO = :PFOLIO
      AND TOTAL_CHARGE <> 0
      AND POST_TO_FOLIO = 1
      INTO FODATE, CATEGORY, DEBIT, SOURCE_ID, CODE, SOURCE_STATUS
  DO
  BEGIN
     SELECT NAME, TAXID, FLAG_INCLUDEDTAX FROM FOCATEGORY
     WHERE CATEGORY = :CATEGORY
     INTO NAME, TAXID, TAX_INCLUDED;
     
     SELECT NAME FROM BQ_MEAL_PERIOD
     WHERE MEAL = :CODE
     INTO :REMARK;
     
     REFERENCE = '#' || SOURCE_ID;
     CREDIT = 0;
     FLAG_TAX  = 0;
     SUSPEND;
     /* TAX  */
     if (TAX_INCLUDED = 0) then
     BEGIN
        FLAG_TAX = 1;
        DB = DEBIT;
        FOR SELECT CATEGORY, PERCENT, FOLIOTEXT FROM fotax_cat
        WHERE TAXID = :TAXID
        ORDER BY LISTINDEX
        INTO :CATEGORY, PERCENT, REMARK
        DO
        BEGIN
           DEBIT = DB * PERCENT / 100;
           SUSPEND;
        END
     END     
  END
  
  SOURCE_ID = 0;
  SOURCE = 'EQ';
  FOR SELECT FODATE, EQUIPMENT, CHARGE, STATUS
      FROM bq_master_equipt
      WHERE FOLIO = :PFOLIO
      AND CHARGE <> 0
      INTO FODATE, REFERENCE, DEBIT, SOURCE_STATUS
  DO
  BEGIN
     SELECT CATEGORY, NAME FROM bq_equiptment
     WHERE EQUIPMENT = :REFERENCE
     INTO :CATEGORY, REMARK;

     SELECT NAME, TAXID, FLAG_INCLUDEDTAX FROM FOCATEGORY
     WHERE CATEGORY = :CATEGORY
     INTO NAME, TAXID, TAX_INCLUDED;
     
     CREDIT = 0;
     FLAG_TAX = 0;
     SUSPEND;
     /* TAX  */
     if (TAX_INCLUDED = 0) then
     BEGIN
        DB = DEBIT;
        FLAG_TAX = 1;
        FOR SELECT CATEGORY, PERCENT, FOLIOTEXT FROM fotax_cat
        WHERE TAXID = :TAXID
        ORDER BY LISTINDEX
        INTO :CATEGORY, PERCENT, REMARK
        DO
        BEGIN
           DEBIT = DB * PERCENT / 100;
           SUSPEND;
        END
     END     
  END
  
  
END^


ALTER PROCEDURE SP_BQ_CHARGE_SAVE(
    PFOLIO INTEGER,
    USERID VARCHAR(8))
AS
declare variable FODATE DATE;
declare variable CATEGORY VARCHAR(4);
declare variable REMARK VARCHAR(40);
declare variable REFERENCE VARCHAR(20);
declare variable DEBIT DOUBLE PRECISION;
declare variable CREDIT DOUBLE PRECISION;
declare variable SOURCE VARCHAR(4);
declare variable SOURCE_ID INTEGER;
declare variable FOSHIFT CHAR(1);
declare variable TRANS_ID INTEGER;
BEGIN
  SELECT FOSHIFT, FOSYSDATE FROM FOSYSPARAM
  WHERE ID = 1
  INTO FOSHIFT, FODATE;
  
  TRANS_ID = GEN_ID(GEN_TRANS_ID,0)+1;
  
  FOR
    SELECT CATEGORY, REMARK, REFERENCE, DEBIT, CREDIT, SOURCE, SOURCE_ID
    FROM SP_BQ_CHARGE(:PFOLIO)
    WHERE FODATE = :FODATE
    AND SOURCE_STATUS = 'O'
    AND FLAG_TAX = 0
    INTO
      :CATEGORY,
      :REMARK,
      :REFERENCE,
      :DEBIT,
      :CREDIT,
      :SOURCE,
      :SOURCE_ID
  DO
  BEGIN
    INSERT INTO FOGUEST_JUR (
       FOLIO,           FODATE,         CATEGORY,       REMARK,
       DEBIT,           CREDIT,         
       SYSDATE,         CURRENCY,       FOREX,          JURCODE,
       REFERENCE,       USERENTRY,      USEREDIT,       USERPOST,
       POSTFLAG,        HIDDEN,         FOSHIFT,        ROOM,AR_CUSTOMER,
       TRANS_ID_BATCH,  FOLIO_ORIGINAL, FLAG_TAX,
       SOURCE, SOURCE_ID)
    VALUES (
       :PFOLIO,   :FODATE,:CATEGORY,    :REMARK,
       :DEBIT,    :CREDIT,
       'NOW',     'IDR',  1,      'BQ',
       :REFERENCE, :USERID,  :USERID,   '',
       'O',    0,  :FOSHIFT,    '', '',
       :TRANS_ID,  :PFOLIO, 0,
       :SOURCE,    :SOURCE_ID);
  END
  UPDATE bq_master_meal SET STATUS = 'P'
  WHERE FOLIO = :PFOLIO
  AND FODATE = :FODATE;
  
  UPDATE bq_master_equipt SET STATUS = 'P'
  WHERE FOLIO = :PFOLIO
  AND FODATE = :FODATE;  
END^


ALTER PROCEDURE SP_BQ_EQUIPT_CHECK(
    FOLIO INTEGER,
    EQUIPMENT VARCHAR(8),
    SDATE DATE,
    TIME_ID INTEGER)
RETURNS (
    BLOCKED INTEGER)
AS
declare variable CFGDate date;
begin
  if (EQUIPMENT is null) then EQUIPMENT = '';
  if (EQUIPMENT = '') then exit;
  if (time_id = 0 ) then /* jika sepanjang hari */
     select count(*) from bq_ri_equipt
     where EQUIPMENT = :EQUIPMENT
     and   FOLIO <> :FOLIO
     and   FODATE = :sdate  
     into :BLOCKED;
  else                  /* jika periode tertentu */
     select count(*) from bq_ri_equipt
     where EQUIPMENT  = :EQUIPMENT
     and   FODATE = :sdate  
     and   ((time_id = :time_id) or (time_id = 0))
     and   FOLIO <> :FOLIO
     into :BLOCKED;
  suspend;
end^


ALTER PROCEDURE SP_BQ_EQUIPT_SAVE(
    FOLIO INTEGER,
    EQUIPMENT VARCHAR(8),
    SDATE DATE,
    TIME_ID INTEGER,
    QTY INTEGER)
AS
declare variable vRow  INTEGER;
declare variable vDate DATE;
declare variable vTime INTEGER;
declare variable no_check integer;
begin

  select no_check from bq_equiptment
  where EQUIPMENT = :EQUIPMENT
  into no_check;

  if ((no_check =0) and (Qty > 0)) then begin
     select BLOCKED from SP_BQ_EQUIPT_CHECK(:FOLIO, :EQUIPMENT, :sdate, :time_id)
     into vRow;

     if (vRow > 0) then exception BQ_EQUIPMENT_ALREADY_BLOCKED;
  end

  vDate = SDATE;
  if (Qty < 0) then begin
     delete from bq_ri_equipt
     where EQUIPMENT = :EQUIPMENT
     and   FODATE = :vdate
     and   time_id = :vTime;
  end
  else if (Qty > 0) then begin
     insert into bq_ri_equipt
     (EQUIPMENT, FODATE, TIME_ID,FOLIO)
     values
     (:EQUIPMENT, :VDATE, :TIME_ID,:FOLIO);
  end
end^


ALTER PROCEDURE SP_BQ_FUNC_CHECK(
    FUNC VARCHAR(12),
    SDATE DATE,
    EDATE DATE,
    STIME VARCHAR(10),
    ETIME VARCHAR(10))
RETURNS (
    BLOCKED INTEGER)
AS
DECLARE VARIABLE CFGDATE DATE;
begin
  if (func is null) then func = '';
  if (func = '') then exit;
     select count(*) from bq_master_func ri
     where FUNC = :FUNC
     and   DATESTART =:SDATE
     AND   DATEEND  =:EDATE
     and  cast(timestart as varchar(5))=:stime
     and cast(timeend  as varchar(5))=:etime
     and   (foliostatus not IN('X','W'))
     into :BLOCKED;
  suspend;
end^


