    FOLIO INTEGER)
RETURNS (
    NOTE01 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE02 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE03 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE04 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE05 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE06 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE07 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE08 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE09 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE10 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE11 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE12 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE13 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE14 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE15 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE16 BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    TITLE01 VARCHAR(40),
    TITLE02 VARCHAR(40),
    TITLE03 VARCHAR(40),
    TITLE04 VARCHAR(40),
    TITLE05 VARCHAR(40),
    TITLE06 VARCHAR(40),
    TITLE07 VARCHAR(40),
    TITLE08 VARCHAR(40),
    TITLE09 VARCHAR(40),
    TITLE10 VARCHAR(40),
    TITLE11 VARCHAR(40),
    TITLE12 VARCHAR(40),
    TITLE13 VARCHAR(40),
    TITLE14 VARCHAR(40),
    TITLE15 VARCHAR(40),
    TITLE16 VARCHAR(40))
AS
declare variable ID INTEGER;
declare variable NOTE BLOB;
DECLARE VARIABLE NAME VARCHAR(40);
begin
  FOR SELECT NOTE_ID, NAME FROM bq_note_id
  ORDER BY NOTE_ID
  INTO ID, NAME
  DO
  BEGIN
    SELECT NOTE FROM bq_master_note
    WHERE FOLIO = :FOLIO
    AND ID = :ID
    INTO :NOTE;
    
    if (ID = 0)      then BEGIN NOTE01 = NOTE; TITLE01 = NAME; END
    ELSE if (ID = 1) then BEGIN NOTE02 = NOTE; TITLE02 = NAME; END
    ELSE if (ID = 2) then BEGIN NOTE03 = NOTE; TITLE03 = NAME; END
    ELSE if (ID = 3) then BEGIN NOTE04 = NOTE; TITLE04 = NAME; END
    ELSE if (ID = 4) then BEGIN NOTE05 = NOTE; TITLE05 = NAME; END
    ELSE if (ID = 5) then BEGIN NOTE06 = NOTE; TITLE06 = NAME; END
    ELSE if (ID = 6) then BEGIN NOTE07 = NOTE; TITLE07 = NAME; END
    ELSE if (ID = 7) then BEGIN NOTE08 = NOTE; TITLE08 = NAME; END
    ELSE if (ID = 8) then BEGIN NOTE09 = NOTE; TITLE09 = NAME; END
    ELSE if (ID = 9) then BEGIN NOTE10 = NOTE; TITLE10 = NAME; END
    ELSE if (ID =10) then BEGIN NOTE11 = NOTE; TITLE11 = NAME; END
    ELSE if (ID =11) then BEGIN NOTE12 = NOTE; TITLE12 = NAME; END
    ELSE if (ID =12) then BEGIN NOTE13 = NOTE; TITLE13 = NAME; END
    ELSE if (ID =13) then BEGIN NOTE14 = NOTE; TITLE14 = NAME; END
    ELSE if (ID =14) then BEGIN NOTE15 = NOTE; TITLE16 = NAME; END
    ELSE if (ID =15) then BEGIN NOTE16 = NOTE; TITLE16 = NAME; END
  END
  suspend;
end^


