ALTER PROCEDURE SP_BQ_PONDOKAN(
    SFOLIO INTEGER)
RETURNS (
    FOLIO INTEGER,
    NAME VARCHAR(80),
    ID INTEGER,
    MENU INTEGER,
    QTY DOUBLE PRECISION,
    COST DOUBLE PRECISION,
    PRICE DOUBLE PRECISION,
    CALC_COST DOUBLE PRECISION,
    CALC_PRICE DOUBLE PRECISION,
    REMARK VARCHAR(80))
AS
declare variable vrow integer;
BEGIN
  IF (NOT EXISTS(SELECT B.FOLIO FROM BQ_MASTER_MEAL_MENU B
                   LEFT JOIN BQ_MENU M ON (B.MENU = M.MENU_ID)
                  WHERE (FOLIO=:SFOLIO)
                    AND (M.MENU_TYPE = 'PNDK'))) THEN
      BEGIN
       FOLIO=:SFOLIO;
       ID=0;
       MENU=0;
       QTY=0;
       COST=0;
       PRICE=0;
       CALC_COST=0;
       CALC_PRICE=0;
       NAME='  ';
       SUSPEND ;
      END

  FOR
    SELECT
      B.ID,
      B.MENU,
      B.QTY,
      B.COST,
      B.PRICE,
      B.CALC_COST,
      B.CALC_PRICE,
      B.REMARK,
      M.NAME
    FROM
      BQ_MASTER_MEAL_MENU B
      LEFT JOIN BQ_MENU M ON (B.MENU = M.MENU_ID)
    WHERE
      (B.FOLIO = :SFOLIO) AND
      (M.MENU_TYPE = 'PNDK')
    ORDER BY
      M.NAME
    INTO
      :ID,
      :MENU,
      :QTY,
      :COST,
      :PRICE,
      :CALC_COST,
      :CALC_PRICE,
      :REMARK,:NAME
  DO
  BEGIN
    SUSPEND;
  END
END^


