ALTER PROCEDURE SP_BQ_ROOM_CHECK(
    FOLIO INTEGER,
    FUNC VARCHAR(12),
    SDATE DATE,
    EDATE DATE,
    TIME_ID INTEGER)
RETURNS (
    BLOCKED INTEGER)
AS
declare variable CFGDate date;
begin
  if (func is null) then func = '';
  if (func = '') then exit;
  if (time_id = 0 ) then /* jika sepanjang hari */
     select count(*) from bq_ri ri
     left join foguest gs on gs.folio = ri.folio
     where ri.FUNC = :FUNC
     and   ri.FOLIO <> :FOLIO
     and   ri.FODATE between :sdate  and :edate
     and   (gs.foliostatus <> 'W')
     into :BLOCKED;
  else                  /* jika periode tertentu */
     select count(*) from bq_ri ri
     left join foguest gs on gs.folio = ri.folio     
     where RI.FUNC  = :FUNC
     and   RI.FODATE between :sdate  and :edate
     and   ((RI.time_id = :time_id) or (RI.time_id = 0))
     and   RI.FOLIO <> :FOLIO
     and   (gs.foliostatus <> 'W')
     into :BLOCKED;
  suspend;
end^


ALTER PROCEDURE SP_BQ_ROOM_SAVE(
    FOLIO INTEGER,
    FUNC VARCHAR(12),
    SDATE DATE,
    EDATE DATE,
    TIME_ID INTEGER,
    BOOK_ID INTEGER,
    QTY INTEGER)
AS
declare variable vRow  INTEGER;
declare variable vDate DATE;
declare variable vTime INTEGER;
declare variable CFGDate date;
declare variable outside integer;
declare variable FOLIOSTATUS CHAR;
begin

  SELECT FOLIOSTATUS FROM FOGUEST WHERE FOLIO = :FOLIO INTO FOLIOSTATUS;
  
  select outside from bq_func
  where func = :func
  into outside;

  if (FOLIOSTATUS <> 'W') then
  if ((outside =0) and (Qty > 0)) then begin
     select BLOCKED from sp_bq_room_check(:FOLIO, :FUNC, :sdate, :edate, :time_id)
     into vRow;
     if (vRow > 0) then exception BQ_ROOM_ALREADY_BLOCKED;
  end

  vDate = SDATE;
  WHILE (vDate <= EDATE) DO BEGIN
     if (Qty < 0) then begin
        delete from BQ_RI
        where FUNC = :FUNC
        and   FODATE = :vdate
        and   time_id = :vTime;
     end
     else if (Qty > 0) then begin
        insert into BQ_RI
        (FUNC, FODATE, TIME_ID,FOLIO, BOOK_ID)
        values
        (:FUNC, :VDATE, :TIME_ID,:FOLIO, :BOOK_ID);
     end
     vDate = vDate + 1;
  end
end^


ALTER PROCEDURE SP_BQ_RPT_LIST(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FOLIO INTEGER,
    GUESTNAME VARCHAR(40),
    PHONE VARCHAR(40),
    FUNC VARCHAR(12),
    BOOK_ID INTEGER,
    FOLIOSTATUS CHAR(1),
    TIME_PERIOD VARCHAR(13),
    DATESTART DATE,
    DATEEND DATE,
    DATERESV DATE,
    GRP_DROP_DATE DATE,
    TIMEID SMALLINT,
    PERSON_IN_CHARGE VARCHAR(80),
    FUNC_LAYOUT VARCHAR(8),
    REMARK VARCHAR(80),
    PAX INTEGER,
    STATUS CHAR(1),
    DATE_CONFIRM DATE,
    TYPE_NAME VARCHAR(40),
    SOURCE_NAME VARCHAR(40),
    REV_TOTAL DOUBLE PRECISION,
    REV_MTD DOUBLE PRECISION,
    REV_YTD DOUBLE PRECISION,
    REV_LYTD DOUBLE PRECISION,
    REV_VARIANCE DOUBLE PRECISION,
    CREATEDBY VARCHAR(10),
    CREATEDDATE DATE)
AS
declare variable TYPE_CODE VARCHAR(4);
declare variable SOURCE VARCHAR(4);
BEGIN
if (SDATE IS NULL) then SDATE='01.06.2004';
EDATE='30.06.2004';
  FOR
    SELECT FC.FOLIO,
           FC.FUNC,
           FC.BOOK_ID,
           GS.FOLIOSTATUS,
           FC.DATESTART,
           FC.DATEEND,
           GS.GRP_DROP_DATE,
           FC.TIMEID,
           FC.PERSON_IN_CHARGE,
           FC.FUNC_LAYOUT,
           FC.REMARK,
           FC.PAX,
           FC.STATUS,
           FC.DATE_CONFIRM,
           FC.CREATEUSER ,
           FC.CREATEDATE,
           TM.PERIOD,
           GS.FNAME,
           GS.RESV_PHONE,
           GS.ST_CODE1,
           GS.ST_RESV_SOURCE,
           GS.DATERESV

    FROM BQ_MASTER_FUNC FC
    LEFT JOIN FOGUEST GS ON GS.FOLIO = FC.FOLIO
    LEFT JOIN bq_time_id TM ON TM.TIME_ID = FC.TIMEID
    WHERE GS.DATECI BETWEEN :SDATE AND :EDATE
    INTO
      :FOLIO,
      :FUNC,
      :BOOK_ID,
      :FOLIOSTATUS,
      :DATESTART,
      :DATEEND,
      :GRP_DROP_DATE,
      :TIMEID,
      :PERSON_IN_CHARGE,
      :FUNC_LAYOUT,
      :REMARK,
      :PAX,
      :STATUS,
      :DATE_CONFIRM,
      :CREATEDBY,
      :CREATEDDATE,
      :TIME_PERIOD,
      :GUESTNAME,
      :PHONE,
      :TYPE_CODE,
      :SOURCE,
      :DATERESV
  DO
  BEGIN
    SELECT NAME FROM BQ_TYPE
    WHERE CODE = :TYPE_CODE
    INTO TYPE_NAME;
    
    SELECT NAME FROM fost_source
    WHERE CODE = :SOURCE
    INTO SOURCE_NAME;

    SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
    WHERE FOLIO=:FOLIO
    INTO :REV_TOTAL ;
    SUSPEND;
  END
END^


ALTER PROCEDURE SP_BQ_SALES_LIST(
    SFOLIO INTEGER)
RETURNS (
    FOLIO INTEGER,
    NAME VARCHAR(40),
    ADDRESS VARCHAR(50),
    PHONE VARCHAR(40),
    FUNC VARCHAR(12),
    BOOK_ID INTEGER,
    FOLIOSTATUS CHAR(1),
    TIME_PERIOD VARCHAR(13),
    DATESTART DATE,
    DATEEND DATE,
    DATERESV DATE,
    TIMEID SMALLINT,
    PERSON_IN_CHARGE VARCHAR(80),
    FUNC_LAYOUT VARCHAR(8),
    REMARK VARCHAR(80),
    PAX INTEGER,
    STATUS CHAR(1),
    DATE_CONFIRM DATE,
    TYPE_NAME VARCHAR(40),
    SOURCE_NAME VARCHAR(40),
    REV_MEAL DOUBLE PRECISION,
    REV_MEAL_OUTSIDE DOUBLE PRECISION,
    REV_ROOM_RENTAL DOUBLE PRECISION,
    REV_OTHER DOUBLE PRECISION,
    REV_ADDITIONAL DOUBLE PRECISION,
    REV_SUBTOTAL DOUBLE PRECISION,
    DISCOUNT DOUBLE PRECISION,
    DEPOSIT DOUBLE PRECISION,
    PACKAGE VARCHAR(30))
AS
DECLARE VARIABLE TYPE_CODE VARCHAR(4);
DECLARE VARIABLE SOURCE VARCHAR(4);
BEGIN
  FOR
    SELECT FC.FOLIO,
           FC.FUNC,
           FC.BOOK_ID,
           GS.FOLIOSTATUS,
           FC.DATESTART,
           FC.DATEEND,
           FC.TIMEID,
           FC.PERSON_IN_CHARGE,
           FC.FUNC_LAYOUT,
           FC.REMARK,
           FC.PAX,
           FC.STATUS,
           FC.DATE_CONFIRM,
           TM.PERIOD,
           GS.FNAME,
           GS.RESV_PHONE,
           GS.ST_CODE1,
           GS.ST_RESV_SOURCE,
           GS.DATERESV
    FROM BQ_MASTER_FUNC FC
    LEFT JOIN FOGUEST GS ON GS.FOLIO = FC.FOLIO
    LEFT JOIN bq_time_id TM ON TM.TIME_ID = FC.TIMEID
    WHERE GS.FOLIO =:SFOLIO 
    INTO
      :FOLIO,
      :FUNC,
      :BOOK_ID,
      :FOLIOSTATUS,
      :DATESTART,
      :DATEEND,
      :TIMEID,
      :PERSON_IN_CHARGE,
      :FUNC_LAYOUT,
      :REMARK,
      :PAX,
      :STATUS,
      :DATE_CONFIRM,
      :TIME_PERIOD,
      :NAME,
      :PHONE,
      :TYPE_CODE,
      :SOURCE,
      :DATERESV 
      
  DO
  BEGIN
    SELECT P.NAME FROM BQ_MASTER_MEAL M
    LEFT JOIN BQ_PACKAGE P ON M.MENU_PACKAGE = P.PACKAGE
    WHERE FOLIO =:FOLIO
    INTO :PACKAGE ;
    
    SELECT NAME FROM BQ_TYPE
    WHERE CODE = :TYPE_CODE
    INTO TYPE_NAME;
    
    SELECT NAME FROM fost_source
    WHERE CODE = :SOURCE
    INTO SOURCE_NAME;
    
    SELECT SUM(AMOUNT) FROM FOGUEST_DEPOSIT
    WHERE FOLIO = :FOLIO
    AND STATUS = 'R'
    INTO DEPOSIT;
    
    if (DEPOSIT IS NULL) then DEPOSIT = 0;
    
    
    SELECT SUM(PAX*CHARGE), SUM(CHARGE_OUTSIDE), SUM(ROOM_RENTAL), SUM(SURCHARGE) FROM bq_master_meal
    WHERE FOLIO = :FOLIO
    INTO REV_MEAL, REV_MEAL_OUTSIDE, REV_ROOM_RENTAL,REV_OTHER ;
    IF (REV_MEAL_OUTSIDE IS NULL) THEN REV_MEAL_OUTSIDE= 0 ;
    IF (REV_ROOM_RENTAL IS null ) THEN REV_ROOM_RENTAL= 0 ;
    IF (REV_OTHER IS NULL ) THEN REV_OTHER = 0 ;

    SELECT SUM(CHARGE) FROM BQ_MASTER_EQUIPT
    WHERE FOLIO = :FOLIO
    INTO :REV_ADDITIONAL ;
    IF (REV_ADDITIONAL IS NULL ) then REV_ADDITIONAL = 0 ;

    DISCOUNT=0 ;
    REV_SUBTOTAL = REV_MEAL + REV_MEAL_OUTSIDE + REV_ADDITIONAL ;

    if (REV_MEAL IS NULL) then
    BEGIN
       REV_MEAL = 0;
       REV_MEAL_OUTSIDE = 0;
       REV_ROOM_RENTAL = 0;
       REV_OTHER = 0;
       DISCOUNT  = 0 ;
    END
    ELSE DISCOUNT= 0 ;
    SUSPEND;
  END
END^


