ALTER PROCEDURE SP_BQ_WEEKLY_FORECAST(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FOLIO INTEGER,
    GUESTNAME VARCHAR(40),
    PHONE VARCHAR(40),
    FUNC VARCHAR(12),
    BOOK_ID INTEGER,
    FOLIOSTATUS CHAR(1),
    TIME_PERIOD VARCHAR(13),
    DATESTART DATE,
    DATEEND DATE,
    DATERESV DATE,
    GRP_DROP_DATE DATE,
    TIMEID SMALLINT,
    PERSON_IN_CHARGE VARCHAR(80),
    FUNC_LAYOUT VARCHAR(8),
    REMARK VARCHAR(80),
    PAX INTEGER,
    STATUS CHAR(1),
    DATE_CONFIRM DATE,
    TYPE_NAME VARCHAR(40),
    SOURCE_NAME VARCHAR(40),
    REV_ROOM DOUBLE PRECISION,
    REV_BFAST DOUBLE PRECISION,
    REV_LUNCH DOUBLE PRECISION,
    REV_DINNER DOUBLE PRECISION,
    REV_CB_I DOUBLE PRECISION,
    REV_CB_II DOUBLE PRECISION,
    REV_OTHERS DOUBLE PRECISION,
    REV_TOTAL DOUBLE PRECISION,
    REV_LOCATION1 DOUBLE PRECISION,
    REV_LOCATION2 DOUBLE PRECISION,
    REV_LOCATION3 DOUBLE PRECISION,
    REV_LOCATION4 DOUBLE PRECISION,
    VAR_FSDATE DATE,
    VAR_FEDATE DATE,
    STATUSNAME VARCHAR(20),
    CREATEDBY VARCHAR(10),
    CREATEDDATE DATE)
AS
declare variable type_code varchar(4);
declare variable source varchar(4);
declare variable d integer;
declare variable ed integer;
declare variable fd integer;
declare variable gd integer;
declare variable m integer;
declare variable y integer;
declare variable vdebug integer;
declare variable meal_period varchar(6);
BEGIN
    VAR_FSDATE = :SDATE ;
    VAR_FEDATE = :EDATE ;
    FOR
    SELECT FC.FOLIO,
           FC.FUNC,
           FC.BOOK_ID,
           GS.FOLIOSTATUS,
           FC.DATESTART,
           FC.DATEEND,
           GS.GRP_DROP_DATE,
           FC.TIMEID,
           FC.PERSON_IN_CHARGE,
           FC.FUNC_LAYOUT,
           FC.REMARK,
           FC.PAX,
           FC.STATUS,
           FC.DATE_CONFIRM,
           FC.CREATEUSER ,
           FC.CREATEDATE,
           TM.PERIOD,
           GS.FNAME,
           GS.RESV_PHONE,
           GS.ST_CODE1,
           GS.ST_RESV_SOURCE,
           GS.DATERESV

    FROM BQ_MASTER_FUNC FC
    LEFT JOIN FOGUEST GS ON GS.FOLIO = FC.FOLIO
    LEFT JOIN bq_time_id TM ON TM.TIME_ID = FC.TIMEID
/*    WHERE GS.DATECI BETWEEN :F_SDATE AND :F_EDATE*/
    WHERE GS.DATECI BETWEEN :SDATE AND :EDATE
    AND GS.FOLIOSTATUS IN('T','W','C')
    ORDER BY GS.DATECI ASC
    INTO
      :FOLIO,
      :FUNC,
      :BOOK_ID,
      :FOLIOSTATUS,
      :DATESTART,
      :DATEEND,
      :GRP_DROP_DATE,
      :TIMEID,
      :PERSON_IN_CHARGE,
      :FUNC_LAYOUT,
      :REMARK,
      :PAX,
      :STATUS,
      :DATE_CONFIRM,
      :CREATEDBY,
      :CREATEDDATE,
      :TIME_PERIOD,
      :GUESTNAME,
      :PHONE,
      :TYPE_CODE,
      :SOURCE,
      :DATERESV
  DO
  BEGIN
    if (FOLIOSTATUS='I') then STATUSNAME='In house';
    if (FOLIOSTATUS='T') then STATUSNAME='Tentative';
    if (FOLIOSTATUS='C') then STATUSNAME='Confirm';
    if (FOLIOSTATUS='X') then STATUSNAME='Canceled';
    if (FOLIOSTATUS='W') then STATUSNAME='Waiting List';

    SELECT NAME FROM BQ_TYPE
    WHERE CODE = :TYPE_CODE
    INTO TYPE_NAME;
    
    SELECT NAME FROM fost_source
    WHERE CODE = :SOURCE
    INTO SOURCE_NAME;
    
    /*    SELECT SUM(AMOUNT) FROM FOGUEST_DEPOSIT
        WHERE FOLIO = :FOLIO
        AND STATUS = 'R'
        INTO DEPOSIT;
    
        if (DEPOSIT IS NULL) then DEPOSIT = 0; */
    
    /* Hitung Total meal per periode */

   /* Hitung meal BREAKFAST */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD ='BF'
   INTO  :REV_BFAST ;
   if (REV_BFAST IS NULL) then REV_BFAST = 0 ;

   /* Hitung meal Lunch */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD ='LN'
   INTO  :REV_LUNCH ;
   if (REV_LUNCH IS NULL) then REV_LUNCH = 0 ;

   /* Hitung meal DINNER */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD='DN'
    INTO :REV_DINNER ;
   if (REV_DINNER IS NULL) then REV_DINNER = 0 ;


   /* Hitung meal COFFEE BREAK I */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD='CB1'
    INTO :REV_CB_I ;
   if (REV_CB_I IS NULL) then REV_CB_I = 0 ;
    
   /* Hitung meal COFFEE BREAK I */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD='CB2'
    INTO :REV_CB_II ;
   if (REV_CB_II IS NULL) then REV_CB_II = 0 ;
    
   /* Hitung Transaksi selain meal -> Equipment masuk kedalam Others */
   SELECT SUM(CHARGE) FROM BQ_MASTER_EQUIPT
   WHERE FOLIO = :FOLIO
    INTO :REV_OTHERS ;
   if (REV_OTHERS IS NULL) then REV_OTHERS = 0 ;

   /* Hitung Transaksi total ditambah dengan transaksi Equipment  */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD IN('CB2','CB1','DN','BF','LN')
    INTO :REV_TOTAL ;
   if (REV_TOTAL IS NULL) then REV_TOTAL = 0 ;

   if (REV_tOTAL <> 0 ) then REV_TOTAL = REV_TOTAL + REV_OTHERS ;
   /*
   */
   /* Hitung Revenue Room Rental */
   /*=====================================================
   */
   SELECT SUM(ROOM_RENTAL) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
    INTO :REV_ROOM ;
   if (REV_ROOM IS NULL) then REV_ROOM = 0 ;
   /* */
   /*
   */
   /*
   */
   /* Hitung Alocated Revenue to Outlet */
   /*====================================
   */
   /*
   */
   /* Hitung Alokasi revenue untuk Pasundan Room */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='PR'
    INTO :REV_LOCATION1 ;
   if (REV_LOCATION1 IS NULL) then REV_LOCATION1 = 0 ;

   /* Hitung Alokasi revenue untuk Tangkuban Parahu */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='TPR'
    INTO :REV_LOCATION2 ;
   if (REV_LOCATION2 IS NULL) then REV_LOCATION2 = 0 ;
   
   /* Hitung Alokasi revenue untuk Patuha Room */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='PTR'
    INTO :REV_LOCATION3 ;
   if (REV_LOCATION3 IS NULL) then REV_LOCATION3 = 0 ;
   
   /* Hitung Alokasi revenue untuk Pasteur */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION NOT IN('PR','TPR','PTR','CS')
    INTO :REV_LOCATION4 ;
   if (REV_LOCATION4 IS NULL) then REV_LOCATION4 = 0 ;
   
    SUSPEND;
  END
END^


ALTER PROCEDURE SP_BQ_WEEKLY_FORECAST_SPORTCLUB(
    VDATE DATE)
RETURNS (
    FOLIO INTEGER,
    GUESTNAME VARCHAR(40),
    PHONE VARCHAR(40),
    FUNC VARCHAR(12),
    BOOK_ID INTEGER,
    FOLIOSTATUS CHAR(1),
    TIME_PERIOD VARCHAR(13),
    DATESTART DATE,
    DATEEND DATE,
    DATERESV DATE,
    GRP_DROP_DATE DATE,
    TIMEID SMALLINT,
    PERSON_IN_CHARGE VARCHAR(80),
    FUNC_LAYOUT VARCHAR(8),
    REMARK VARCHAR(80),
    PAX INTEGER,
    STATUS CHAR(1),
    DATE_CONFIRM DATE,
    TYPE_NAME VARCHAR(40),
    SOURCE_NAME VARCHAR(40),
    REV_PACKAGE DOUBLE PRECISION,
    REV_ADDPACKAGE DOUBLE PRECISION,
    REV_OUTSIDE DOUBLE PRECISION,
    REV_OTHERS DOUBLE PRECISION,
    REV_TOTAL DOUBLE PRECISION,
    REV_LOCATION1 DOUBLE PRECISION,
    REV_LOCATION2 DOUBLE PRECISION,
    REV_LOCATION3 DOUBLE PRECISION,
    REV_LOCATION4 DOUBLE PRECISION,
    DISCOUNT DOUBLE PRECISION,
    VAR_FSDATE DATE,
    VAR_FEDATE DATE,
    STATUSNAME VARCHAR(20),
    CREATEDBY VARCHAR(10),
    CREATEDDATE DATE)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE TYPE_CODE VARCHAR(4);
DECLARE VARIABLE SOURCE VARCHAR(4);
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE ED INTEGER;
DECLARE VARIABLE FD INTEGER;
DECLARE VARIABLE GD INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE VDEBUG INTEGER;
DECLARE VARIABLE MEAL_PERIOD VARCHAR(6);
declare variable XID  INTEGER ;
BEGIN
    SDATE=  VDATE ;
    EDATE = SDATE + 14 ;
    VAR_FSDATE = :SDATE ;
    VAR_FEDATE = :EDATE ;
    FOR
    SELECT FC.FOLIO,
           FC.FUNC,
           FC.BOOK_ID,
           GS.FOLIOSTATUS,
           FC.DATESTART,
           FC.DATEEND,
           GS.GRP_DROP_DATE,
           FC.TIMEID,
           FC.PERSON_IN_CHARGE,
           FC.FUNC_LAYOUT,
           FC.REMARK,
           FC.PAX,
           FC.STATUS,
           FC.DATE_CONFIRM,
           FC.CREATEUSER ,
           FC.CREATEDATE,
           TM.PERIOD,
           GS.FNAME,
           GS.RESV_PHONE,
           GS.ST_CODE1,
           GS.ST_RESV_SOURCE,
           GS.DATERESV

    FROM BQ_MASTER_FUNC FC
    LEFT JOIN FOGUEST GS ON GS.FOLIO = FC.FOLIO
    LEFT JOIN bq_time_id TM ON TM.TIME_ID = FC.TIMEID
    WHERE GS.DATECI BETWEEN :SDATE AND :EDATE
      AND GS.FOLIOSTATUS IN('T','W','C')
      ORDER BY GS.DATECI ASC
    INTO
      :FOLIO,
      :FUNC,
      :BOOK_ID,
      :FOLIOSTATUS,
      :DATESTART,
      :DATEEND,
      :GRP_DROP_DATE,
      :TIMEID,
      :PERSON_IN_CHARGE,
      :FUNC_LAYOUT,
      :REMARK,
      :PAX,
      :STATUS,
      :DATE_CONFIRM,
      :CREATEDBY,
      :CREATEDDATE,
      :TIME_PERIOD,
      :GUESTNAME,
      :PHONE,
      :TYPE_CODE,
      :SOURCE,
      :DATERESV
  DO
  BEGIN
    if (FOLIOSTATUS='I') then STATUSNAME='In house';
    if (FOLIOSTATUS='T') then STATUSNAME='Tentative';
    if (FOLIOSTATUS='C') then STATUSNAME='Confirm';
    if (FOLIOSTATUS='X') then STATUSNAME='Canceled';
    if (FOLIOSTATUS='W') then STATUSNAME='Waiting List';

    SELECT NAME FROM BQ_TYPE
    WHERE CODE = :TYPE_CODE
    INTO TYPE_NAME;
    
    SELECT NAME FROM fost_source
    WHERE CODE = :SOURCE
    INTO SOURCE_NAME;
    
   /* Hitung meal PACKAGE*/
   SELECT SUM(SURCHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
   INTO  :REV_PACKAGE ;
   if (REV_PACKAGE IS NULL) then REV_PACKAGE = 0 ;

   /* Hitung meal OUTSIDE */
   SELECT SUM(CHARGE_OUTSIDE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
   INTO  :REV_OUTSIDE ;
   if (REV_OUTSIDE IS NULL) then REV_OUTSIDE = 0 ;

   /* Hitung meal DISCOUNT  */
   SELECT SUM(DISCOUNT) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
   INTO  :DISCOUNT ;
   if (DISCOUNT IS NULL) then DISCOUNT = 0 ;
   


   /* Hitung Transaksi total ditambah dengan transaksi Equipment  */

    SELECT ID FROM BQ_MASTER_MEAL
    WHERE FOLIO=:FOLIO
    INTO :XID ;

    SELECT SUM(MM.QTY*MM.PRICE)FROM BQ_MASTER_MEAL_MENU MM
       LEFT JOIN BQ_MENU M ON MM.MENU=M.MENU_ID
       WHERE ID = :XID
         AND M.MENU_TYPE ='EQP'
      INTO :REV_OTHERS ;
    IF (REV_OTHERS IS NULL ) then REV_OTHERS = 0 ;

   /*================*/
   
   /*Hitung Total Transaksi */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
    INTO :REV_TOTAL ;
   if (REV_TOTAL IS NULL) then REV_TOTAL = 0 ;
   REV_TOTAL = :REV_TOTAL +REV_PACKAGE + REV_OUTSIDE + REV_OTHERS ;
   /*
   */
   /* Hitung Alocated Revenue to Outlet */
   /*====================================
   */
   /*
   */
   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Coffe Sh'
    INTO :REV_LOCATION1 ;
   if (REV_LOCATION1 IS NULL) then REV_LOCATION1 = 0 ;

   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Paparazz'
    INTO :REV_LOCATION2 ;
   if (REV_LOCATION2 IS NULL) then REV_LOCATION2 = 0 ;
   
   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Dragon 2'
    INTO :REV_LOCATION3 ;
   if (REV_LOCATION3 IS NULL) then REV_LOCATION3 = 0 ;
   
   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
    INTO :REV_LOCATION4 ;
   if (REV_LOCATION4 IS NULL) then REV_LOCATION4 = 0 ;*/
   SUSPEND;
  END
END^


ALTER PROCEDURE SP_BQ_WEEKLY_SALES(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FOLIO INTEGER,
    GUESTNAME VARCHAR(40),
    PHONE VARCHAR(40),
    FUNC VARCHAR(12),
    BOOK_ID INTEGER,
    FOLIOSTATUS CHAR(1),
    TIME_PERIOD VARCHAR(13),
    DATESTART DATE,
    DATEEND DATE,
    DATERESV DATE,
    GRP_DROP_DATE DATE,
    TIMEID SMALLINT,
    PERSON_IN_CHARGE VARCHAR(80),
    FUNC_LAYOUT VARCHAR(8),
    REMARK VARCHAR(80),
    PAX INTEGER,
    STATUS CHAR(1),
    DATE_CONFIRM DATE,
    TYPE_NAME VARCHAR(40),
    SOURCE_NAME VARCHAR(40),
    REV_ROOM DOUBLE PRECISION,
    REV_BFAST DOUBLE PRECISION,
    REV_LUNCH DOUBLE PRECISION,
    REV_DINNER DOUBLE PRECISION,
    REV_CB_I DOUBLE PRECISION,
    REV_CB_II DOUBLE PRECISION,
    REV_OTHERS DOUBLE PRECISION,
    REV_TOTAL DOUBLE PRECISION,
    REV_LOCATION1 DOUBLE PRECISION,
    REV_LOCATION2 DOUBLE PRECISION,
    REV_LOCATION3 DOUBLE PRECISION,
    REV_LOCATION4 DOUBLE PRECISION,
    VAR_DATEEND DATE,
    VAR_DATESTART DATE,
    STATUSNAME VARCHAR(20),
    CREATEDBY VARCHAR(10),
    CREATEDDATE DATE)
AS
DECLARE VARIABLE TYPE_CODE VARCHAR(4);
DECLARE VARIABLE SOURCE VARCHAR(4);
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE ED INTEGER;
DECLARE VARIABLE FD INTEGER;
DECLARE VARIABLE GD INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE F_SDATE DATE;
DECLARE VARIABLE F_EDATE DATE;
DECLARE VARIABLE VDEBUG INTEGER;
DECLARE VARIABLE MEAL_PERIOD VARCHAR(6);
BEGIN
/*   if (VDATE IS NULL) then VDATE='01.06.2004';

   SDATE = VDATE - 6 ;
   EDATE = VDATE ;*/
   VAR_DATESTART  = SDATE ;
   VAR_DATEEND    = EDATE ;
    FOR
    SELECT FC.FOLIO,
           FC.FUNC,
           FC.BOOK_ID,
           GS.FOLIOSTATUS,
           FC.DATESTART,
           FC.DATEEND,
           GS.GRP_DROP_DATE,
           FC.TIMEID,
           FC.PERSON_IN_CHARGE,
           FC.FUNC_LAYOUT,
           FC.REMARK,
           FC.PAX,
           FC.STATUS,
           FC.DATE_CONFIRM,
           FC.CREATEUSER ,
           FC.CREATEDATE,
           TM.PERIOD,
           GS.FNAME,
           GS.RESV_PHONE,
           GS.ST_CODE1,
           GS.ST_RESV_SOURCE,
           GS.DATERESV

    FROM BQ_MASTER_FUNC FC
    LEFT JOIN FOGUEST GS ON GS.FOLIO = FC.FOLIO
    LEFT JOIN bq_time_id TM ON TM.TIME_ID = FC.TIMEID
    WHERE GS.DATECI BETWEEN :SDATE AND :EDATE
    AND FOLIOSTATUS IN('I','O')
    ORDER BY GS.DATECI desc
    
    INTO
      :FOLIO,
      :FUNC,
      :BOOK_ID,
      :FOLIOSTATUS,
      :DATESTART,
      :DATEEND,
      :GRP_DROP_DATE,
      :TIMEID,
      :PERSON_IN_CHARGE,
      :FUNC_LAYOUT,
      :REMARK,
      :PAX,
      :STATUS,
      :DATE_CONFIRM,
      :CREATEDBY,
      :CREATEDDATE,
      :TIME_PERIOD,
      :GUESTNAME,
      :PHONE,
      :TYPE_CODE,
      :SOURCE,
      :DATERESV
  DO
  BEGIN
    if (FOLIOSTATUS='I') then STATUSNAME='In house';
    if (FOLIOSTATUS='O') then STATUSNAME='Check Out';
    /*if (FOLIOSTATUS='T') then STATUSNAME='Tentative';
    if (FOLIOSTATUS='C') then STATUSNAME='Confirm';
    if (FOLIOSTATUS='X') then STATUSNAME='Canceled';
    if (FOLIOSTATUS='W') then STATUSNAME='Waiting List ';*/
    SELECT NAME FROM BQ_TYPE
    WHERE CODE = :TYPE_CODE
    INTO TYPE_NAME;
    
    SELECT NAME FROM fost_source
    WHERE CODE = :SOURCE
    INTO SOURCE_NAME;
    
    /*    SELECT SUM(AMOUNT) FROM FOGUEST_DEPOSIT
        WHERE FOLIO = :FOLIO
        AND STATUS = 'R'
        INTO DEPOSIT;
    
        if (DEPOSIT IS NULL) then DEPOSIT = 0; */
    
    /* Hitung Total meal per periode */

   /* Hitung meal BREAKFAST */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD ='BF'
   INTO  :REV_BFAST ;
   if (REV_BFAST IS NULL) then REV_BFAST = 0 ;

   /* Hitung meal Lunch */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD ='LN'
   INTO  :REV_LUNCH ;
   if (REV_LUNCH IS NULL) then REV_LUNCH = 0 ;

   /* Hitung meal DINNER */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD='DN'
    INTO :REV_DINNER ;
   if (REV_DINNER IS NULL) then REV_DINNER = 0 ;

   /* Hitung meal COFFEE BREAK I */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD='CB1'
    INTO :REV_CB_I ;
   if (REV_CB_I IS NULL) then REV_CB_I = 0 ;
    
   /* Hitung meal COFFEE BREAK I */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD='CB2'
    INTO :REV_CB_II ;
   if (REV_CB_II IS NULL) then REV_CB_II = 0 ;
    
   /* Hitung Transaksi selain meal -> Equipment masuk kedalam Others */
   SELECT SUM(CHARGE) FROM BQ_MASTER_EQUIPT
   WHERE FOLIO = :FOLIO
    INTO :REV_OTHERS ;
   if (REV_OTHERS IS NULL) then REV_OTHERS = 0 ;

   /* Hitung Transaksi total ditambah dengan transaksi Equipment  */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND MEAL_PERIOD IN('CB2','CB1','DN','BF','LN')
    INTO :REV_TOTAL ;
   if (REV_TOTAL IS NULL) then REV_TOTAL = 0 ;

   if (REV_tOTAL <> 0 ) then REV_TOTAL = REV_TOTAL + REV_OTHERS ;
   /*
   */
   /* Hitung Revenue Room Rental */
   /*=====================================================
   */
   SELECT SUM(ROOM_RENTAL) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
    INTO :REV_ROOM ;
   if (REV_ROOM IS NULL) then REV_ROOM = 0 ;
   /* */
   /*
   */
   /*
   */
   /* Hitung Alocated Revenue to Outlet */
   /*====================================
   */
   /*
   */
   /* Hitung Alokasi revenue untuk Pasteur */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Coffe Sh'
    INTO :REV_LOCATION1 ;
   if (REV_LOCATION1 IS NULL) then REV_LOCATION1 = 0 ;

   /* Hitung Alokasi revenue untuk Pasteur */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Paparazz'
    INTO :REV_LOCATION2 ;
   if (REV_LOCATION2 IS NULL) then REV_LOCATION2 = 0 ;
   
   /* Hitung Alokasi revenue untuk Pasteur */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Dragon 2'
    INTO :REV_LOCATION3 ;
   if (REV_LOCATION3 IS NULL) then REV_LOCATION3 = 0 ;
   
   /* Hitung Alokasi revenue untuk Pasteur */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION NOT IN('Coffe Sh','Paparazz','Coffe Sh','Dragon 2')
    INTO :REV_LOCATION4 ;
   if (REV_LOCATION4 IS NULL) then REV_LOCATION4 = 0 ;
   

    
/*    SELECT SUM(PAX*CHARGE), SUM(CHARGE_OUTSIDE), SUM(ROOM_RENTAL), SUM(SURCHARGE) FROM bq_master_meal
    WHERE FOLIO = :FOLIO
    INTO REV_MEAL, REV_MEAL_OUTSIDE, REV_ROOM_RENTAL,REV_OTHER ;
    
    SELECT SUM(CHARGE) FROM BQ_MASTER_EQUIPT
