       REV_MEAL_OUTSIDE = 0;
       REV_ROOM_RENTAL = 0;
       REV_OTHER = 0;
    END*/
    SUSPEND;
  END
END^


ALTER PROCEDURE SP_BQ_WEEKLY_SALES_SPORTCLUB(
    VDATE DATE)
RETURNS (
    FOLIO INTEGER,
    GUESTNAME VARCHAR(40),
    PHONE VARCHAR(40),
    FUNC VARCHAR(12),
    FUNC_INDEX INTEGER,
    BOOK_ID INTEGER,
    FOLIOSTATUS CHAR(1),
    TIME_PERIOD VARCHAR(13),
    DATESTART DATE,
    DATEEND DATE,
    DATERESV DATE,
    GRP_DROP_DATE DATE,
    TIMEID SMALLINT,
    PERSON_IN_CHARGE VARCHAR(80),
    FUNC_LAYOUT VARCHAR(8),
    REMARK VARCHAR(80),
    PAX INTEGER,
    STATUS CHAR(1),
    DATE_CONFIRM DATE,
    TYPE_NAME VARCHAR(40),
    SOURCE_NAME VARCHAR(40),
    REV_PACKAGE DOUBLE PRECISION,
    REV_ADDPACKAGE DOUBLE PRECISION,
    REV_OUTSIDE DOUBLE PRECISION,
    REV_OTHERS DOUBLE PRECISION,
    REV_TOTAL DOUBLE PRECISION,
    REV_LOCATION1 DOUBLE PRECISION,
    REV_LOCATION2 DOUBLE PRECISION,
    REV_LOCATION3 DOUBLE PRECISION,
    REV_LOCATION4 DOUBLE PRECISION,
    DISCOUNT DOUBLE PRECISION,
    VAR_DATEEND DATE,
    VAR_DATESTART DATE,
    STATUSNAME VARCHAR(20),
    CREATEDBY VARCHAR(10),
    CREATEDDATE DATE)
AS
DECLARE VARIABLE TYPE_CODE VARCHAR(4);
DECLARE VARIABLE SOURCE VARCHAR(4);
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE ED INTEGER;
DECLARE VARIABLE FD INTEGER;
DECLARE VARIABLE GD INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE F_SDATE DATE;
DECLARE VARIABLE F_EDATE DATE;
DECLARE VARIABLE VDEBUG INTEGER;
DECLARE VARIABLE MEAL_PERIOD VARCHAR(6);
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
declare variable XID  INTEGER ;
BEGIN
    if (VDATE IS NULL) then VDATE='01.06.2004';

   SDATE = VDATE - 7 ;
   EDATE = VDATE ;
   VAR_DATESTART  = SDATE ;
   VAR_DATEEND    = EDATE ;
    FOR
    SELECT FC.FOLIO,
           FC.FUNC,
           BF.LISTINDEX,
           FC.BOOK_ID,
           GS.FOLIOSTATUS,
           FC.DATESTART,
           FC.DATEEND,
           GS.GRP_DROP_DATE,
           FC.TIMEID,
           FC.PERSON_IN_CHARGE,
           FC.FUNC_LAYOUT,
           FC.REMARK,
           FC.PAX,
           FC.STATUS,
           FC.DATE_CONFIRM,
           FC.CREATEUSER ,
           FC.CREATEDATE,
           TM.PERIOD,
           GS.FNAME,
           GS.RESV_PHONE,
           GS.ST_CODE1,
           GS.ST_RESV_SOURCE,
           GS.DATERESV

    FROM BQ_MASTER_FUNC FC
    LEFT JOIN BQ_FUNC BF ON FC.FUNC = BF.FUNC
    LEFT JOIN FOGUEST GS ON GS.FOLIO = FC.FOLIO
    LEFT JOIN bq_time_id TM ON TM.TIME_ID = FC.TIMEID
    WHERE GS.DATECI BETWEEN :SDATE AND :EDATE
    AND FOLIOSTATUS IN('I','O','X')
    ORDER BY GS.DATECI ASC
    INTO
      :FOLIO,
      :FUNC,
      :FUNC_INDEX,
      :BOOK_ID,
      :FOLIOSTATUS,
      :DATESTART,
      :DATEEND,
      :GRP_DROP_DATE,
      :TIMEID,
      :PERSON_IN_CHARGE,
      :FUNC_LAYOUT,
      :REMARK,
      :PAX,
      :STATUS,
      :DATE_CONFIRM,
      :CREATEDBY,
      :CREATEDDATE,
      :TIME_PERIOD,
      :GUESTNAME,
      :PHONE,
      :TYPE_CODE,
      :SOURCE,
      :DATERESV
  DO
  BEGIN
    if (FOLIOSTATUS='I') then STATUSNAME='In house';
    if (FOLIOSTATUS='O') then STATUSNAME='Check Out';
    if (FOLIOSTATUS='T') then STATUSNAME='Tentative';
    if (FOLIOSTATUS='C') then STATUSNAME='Confirm';
    if (FOLIOSTATUS='X') then STATUSNAME='Canceled';
    if (FOLIOSTATUS='W') then STATUSNAME='Waiting List ';
    SELECT NAME FROM BQ_TYPE
    WHERE CODE = :TYPE_CODE
    INTO TYPE_NAME;
    
    SELECT NAME FROM fost_source
    WHERE CODE = :SOURCE
    INTO SOURCE_NAME;

   /* Hitung meal PACKAGE*/
   SELECT SUM(SURCHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
   INTO  :REV_PACKAGE ;
   if (REV_PACKAGE IS NULL) then REV_PACKAGE = 0 ;

   /* Hitung meal OUTSIDE */
   SELECT SUM(CHARGE_OUTSIDE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
   INTO  :REV_OUTSIDE ;
   if (REV_OUTSIDE IS NULL) then REV_OUTSIDE = 0 ;

   /* Hitung meal DISCOUNT  */
   SELECT SUM(DISCOUNT) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
   INTO  :DISCOUNT ;
   if (DISCOUNT IS NULL) then DISCOUNT = 0 ;
   


   /* Hitung Transaksi total ditambah dengan transaksi Equipment  */

    SELECT ID FROM BQ_MASTER_MEAL
    WHERE FOLIO=:FOLIO
    INTO :XID ;

    SELECT SUM(MM.QTY*MM.PRICE)FROM BQ_MASTER_MEAL_MENU MM
       LEFT JOIN BQ_MENU M ON MM.MENU=M.MENU_ID
       WHERE ID = :XID
         AND M.MENU_TYPE ='EQP'
      INTO :REV_OTHERS ;
    IF (REV_OTHERS IS NULL ) then REV_OTHERS = 0 ;

   /*================*/
   
   /*Hitung Total Transaksi */
   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
    INTO :REV_TOTAL ;
   if (REV_TOTAL IS NULL) then REV_TOTAL = 0 ;
   REV_TOTAL = :REV_TOTAL + REV_OTHERS ;
   /*
   */
   /* Hitung Alocated Revenue to Outlet */
   /*====================================
   */
   /*
   */
   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Coffe Sh'
    INTO :REV_LOCATION1 ;
   if (REV_LOCATION1 IS NULL) then REV_LOCATION1 = 0 ;

   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Paparazz'
    INTO :REV_LOCATION2 ;
   if (REV_LOCATION2 IS NULL) then REV_LOCATION2 = 0 ;
   
   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
     AND LOCATION ='Dragon 2'
    INTO :REV_LOCATION3 ;
   if (REV_LOCATION3 IS NULL) then REV_LOCATION3 = 0 ;
   
   /* Hitung Alokasi revenue untuk Pasteur */
/*   SELECT SUM(TOTAL_CHARGE) FROM BQ_MASTER_MEAL
   WHERE FOLIO = :FOLIO
    INTO :REV_LOCATION4 ;
   if (REV_LOCATION4 IS NULL) then REV_LOCATION4 = 0 ;*/
   SUSPEND;
  END
END^


ALTER PROCEDURE SP_DATEONLY(
    ADATE DATE)
RETURNS (
    RDATE DATE)
AS
DECLARE VARIABLE AYear     INTEGER;
DECLARE VARIABLE AMonth    INTEGER;
DECLARE VARIABLE ADay      INTEGER;
BEGIN
  EXECUTE PROCEDURE SP_DecodeDate(ADate) RETURNING_VALUES(AYear, AMonth, ADay);
  EXECUTE PROCEDURE SP_EncodeDate(AYear, AMonth, ADay) RETURNING_VALUES(RDATE);
END^


ALTER PROCEDURE SP_DATE_BOM(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
     RESULT = '1.' || EXTRACT(MONTH FROM ADATE)|| '.' || EXTRACT(YEAR FROM ADATE);
  END
  ELSE
  BEGIN
    SELECT SDATE FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE INTO RESULT;
  END
END^


ALTER PROCEDURE SP_DATE_BOM_MONTHYEAR(
    AMONTH INTEGER,
    AYEAR INTEGER)
RETURNS (
    RESULT DATE)
AS
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE PYEAR=:AYEAR AND PMONTH=:AMONTH)) THEN
  BEGIN
     RESULT = '1.'|| AMONTH || '.' || AYEAR;
  END
  ELSE
  BEGIN
    SELECT SDATE FROM SYS_PERIOD WHERE PYEAR=:AYEAR AND PMONTH=:AMONTH INTO RESULT;
  END

END^


ALTER PROCEDURE SP_DATE_BOY(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE AYEAR INTEGER;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
     RESULT = '1.1.' || EXTRACT(YEAR FROM ADATE);
  END
  ELSE
  BEGIN
    SELECT PYEAR FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE
    INTO AYEAR;
    SELECT SDATE FROM SYS_PERIOD WHERE PYEAR=:AYEAR AND PMONTH=1 INTO RESULT;
  END
END^


ALTER PROCEDURE SP_DATE_DAYOFMONTH(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE BOM DATE;
DECLARE VARIABLE EOM DATE;
BEGIN
  EXECUTE PROCEDURE SP_DATE_BOM(ADATE) RETURNING_VALUES(BOM);
  EXECUTE PROCEDURE SP_DATE_EOM(ADATE) RETURNING_VALUES(EOM);
  RESULT = EOM-BOM+1;
END^


ALTER PROCEDURE SP_DATE_DECODE(
    ADATE DATE)
RETURNS (
    Y INTEGER,
    M INTEGER,
    D INTEGER)
AS
DECLARE VARIABLE SDATE DATE;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
     Y = EXTRACT(YEAR FROM ADATE);
     M = EXTRACT(MONTH FROM ADATE);
     D = EXTRACT(DAY FROM ADATE);
  END
  ELSE
  BEGIN
    SELECT PYEAR, PMONTH, SDATE
    FROM SYS_PERIOD
    WHERE :ADATE BETWEEN SDATE AND EDATE
    INTO Y, M, SDATE;
    D = ADATE - SDATE +1; /* HARI KE BERAPA DALAM PERIOD TSB */
  END
END^


ALTER PROCEDURE SP_DATE_EOM(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE WorkYear   INTEGER;
DECLARE VARIABLE WorkMonth  INTEGER;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
    WorkYear = EXTRACT(YEAR FROM ADATE);
    WorkMonth = EXTRACT(MONTH FROM ADATE);

    WorkMonth = WorkMonth+1;
    if (WorkMonth > 12) then
    begin
    WorkMonth = 1;
    WorkYear  = WorkYear + 1;
    end
    EXECUTE PROCEDURE sp_encodedate(WorkYear, WorkMonth, 1)  RETURNING_VALUES(Result);
    Result = Result - 1;
  END
  ELSE
  BEGIN
    SELECT EDATE FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE INTO RESULT;
  END
END^


ALTER PROCEDURE SP_DATE_EXTRACT_MONTHYEAR(
    ADATE DATE)
RETURNS (
    M INTEGER,
    Y INTEGER)
AS
DECLARE VARIABLE D INTEGER;
BEGIN
   EXECUTE PROCEDURE SP_DATE_DECODE(ADATE) RETURNING_VALUES(Y, M, D);
END^


ALTER PROCEDURE SP_DATE_IS_BOM(
    ADATE DATE)
RETURNS (
    ARESULT INTEGER)
AS
DECLARE VARIABLE SDATE DATE;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
      EXECUTE PROCEDURE SP_BEGINOFMONTH(ADATE) RETURNING_VALUES(SDATE);
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
  ELSE
  BEGIN
      SELECT SDATE FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE INTO SDATE;
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
END^


ALTER PROCEDURE SP_DATE_IS_BOY(
    ADATE DATE)
RETURNS (
    ARESULT INTEGER)
AS
DECLARE VARIABLE SDATE DATE;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
      EXECUTE PROCEDURE SP_BEGINOFYEAR(ADATE) RETURNING_VALUES(SDATE);
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
  ELSE
  BEGIN
      EXECUTE PROCEDURE SP_DATE_BOY(ADATE) RETURNING_VALUES(SDATE);
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
END^


ALTER PROCEDURE SP_DATE_LASTMONTH(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE DCOUNT INTEGER;
DECLARE VARIABLE BOM DATE;
BEGIN
  EXECUTE PROCEDURE SP_DECODEDATE(ADATE) RETURNING_VALUES(Y, M, D);
  M = M - 1;
  IF (M < 1) THEN
  BEGIN
     M = 12;
     Y = Y - 1;
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(M, Y) RETURNING_VALUES(BOM);
  EXECUTE PROCEDURE SP_DATE_DAYOFMONTH(BOM) RETURNING_VALUES(DCOUNT);
  RESULT = BOM + D - 1; /* TGL BULAN LALU AWAL BULAN + TGL HARI INI KURANG 1 HARI */
  D = RESULT - BOM + 1;
  IF (D > DCOUNT) THEN /* KALAU HARI LEBIH BESAR DARI AKHIR BULAN, MAKA DIANGGAP AKHIR BULAN */
     EXECUTE PROCEDURE SP_DATE_EOM(BOM) RETURNING_VALUES(RESULT);
END^


ALTER PROCEDURE SP_DATE_LASTYEAR(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE DCOUNT INTEGER;
DECLARE VARIABLE BOM DATE;
BEGIN
  EXECUTE PROCEDURE SP_DECODEDATE(ADATE) RETURNING_VALUES(Y, M, D);
  Y = Y - 1;
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(M, Y) RETURNING_VALUES(BOM);
  EXECUTE PROCEDURE SP_DATE_DAYOFMONTH(BOM) RETURNING_VALUES(DCOUNT);
  
  if ((M = 2) AND (D > DCOUNT)) then D = DCOUNT;

  EXECUTE PROCEDURE SP_ENCODEDATE(Y, M, D) RETURNING_VALUES(RESULT);
END^


ALTER PROCEDURE SP_DATE_MONTH(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
