  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
     RESULT = EXTRACT(MONTH FROM ADATE);
  END
  ELSE
  BEGIN
    SELECT PMONTH FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE INTO RESULT;
  END
  
END^


ALTER PROCEDURE SP_DATE_YEAR(
