  SUSPEND;
END^


ALTER PROCEDURE SP_DECODEDATE(
    ADATE DATE)
RETURNS (
    Y INTEGER,
    M INTEGER,
    D INTEGER)
AS
BEGIN
   EXECUTE PROCEDURE SP_YEAR   ADATE RETURNING_VALUES :Y;
   EXECUTE PROCEDURE SP_MONTH  ADATE RETURNING_VALUES :M;
   EXECUTE PROCEDURE SP_DAY    ADATE RETURNING_VALUES :D;
END^


ALTER PROCEDURE SP_DOCUMENT_NUMBER(
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    DOCTYPE INTEGER,
    OPENDATE DATE,
    INCREMENT INTEGER)
RETURNS (
    DOCUMENT VARCHAR(20))
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
DECLARE VARIABLE NUMBER INTEGER;
DECLARE VARIABLE XYEAR INTEGER;
DECLARE VARIABLE SYEAR CHAR(2);
DECLARE VARIABLE SMONTH CHAR(2);
DECLARE VARIABLE SNUMBER CHAR(5);
begin
  IF (APPLICATION IS NULL) THEN
  BEGIN
     APPLICATION = 'AP';
     SOURCE = 'VCH';
     DOCTYPE = 0;
     OPENDATE = '1.9.2005';
     INCREMENT = 1;
  END
  PYEAR  = EXTRACT(YEAR  FROM OPENDATE);
  PMONTH = EXTRACT(MONTH FROM OPENDATE);
  
  IF (NOT EXISTS(SELECT * FROM SYSDOCUMENT_NUMBER
            WHERE APPLICATION = :APPLICATION AND SOURCE = :SOURCE
            AND DOCTYPE = :DOCTYPE AND PYEAR = :PYEAR AND PMONTH = :PMONTH)) THEN
  BEGIN
     INSERT INTO SYSDOCUMENT_NUMBER (APPLICATION, SOURCE, DOCTYPE, PYEAR, PMONTH, NUMBER)
     VALUES (:APPLICATION, :SOURCE, :DOCTYPE, :PYEAR, :PMONTH, 0);
  END
  SELECT NUMBER FROM SYSDOCUMENT_NUMBER
  WHERE APPLICATION = :APPLICATION AND SOURCE = :SOURCE
  AND DOCTYPE = :DOCTYPE AND PYEAR = :PYEAR AND PMONTH = :PMONTH
  INTO NUMBER;

  IF (NUMBER IS NULL) THEN NUMBER = 0;
  NUMBER = NUMBER + 1;
  
  XYEAR = PYEAR - 2000;
  IF (XYEAR < 10) THEN SYEAR = '0' || XYEAR;
  ELSE SYEAR = XYEAR;
  
  IF (PMONTH < 10) THEN SMONTH = '0' || PMONTH;
  ELSE SMONTH = PMONTH;
  
  SNUMBER = NUMBER;
  IF (NUMBER < 10) THEN SNUMBER = '0000'||SNUMBER;
  ELSE IF (NUMBER < 100) THEN SNUMBER = '000'||SNUMBER;
  ELSE IF (NUMBER < 1000) THEN SNUMBER = '00'||SNUMBER;
  ELSE IF (NUMBER < 10000) THEN SNUMBER = '0'||SNUMBER;
  
  DOCUMENT = SOURCE || DOCTYPE || '/'||
             SYEAR || SMONTH || '/' || SNUMBER;

  IF (INCREMENT <> 0) THEN
     UPDATE SYSDOCUMENT_NUMBER SET NUMBER = NUMBER + 1
     WHERE APPLICATION = :APPLICATION AND SOURCE = :SOURCE
     AND DOCTYPE = :DOCTYPE AND PYEAR = :PYEAR AND PMONTH = :PMONTH;
     
  suspend;
end^


