DECLARE VARIABLE WorkMonth  INTEGER;
BEGIN
  EXECUTE PROCEDURE SP_Year(ADate)  RETURNING_VALUES(WorkYear);
  EXECUTE PROCEDURE sp_encodedate(WorkYear, 12, 1)  RETURNING_VALUES(Result);
END^


ALTER PROCEDURE SP_FOGUEST_FIELDS
RETURNS (
    TABLENAME VARCHAR(40),
    FIELDNAME CHAR(31),
    FIELDTYPE SMALLINT,
    FIELDLENGTH SMALLINT,
    FIELDTYPENAME CHAR(31),
    FLAG_FO_HIST_GUEST CHAR(1),
    FLAG_FO_HIST_STAY CHAR(1))
AS
BEGIN
  TABLENAME = 'FOGUEST';
  FOR
    select F.RDB$FIELD_NAME FIELDNAME,
    D.RDB$FIELD_TYPE FIELDTYPE,
    D.RDB$FIELD_LENGTH FIELDLENGTH,
    T.RDB$TYPE_NAME FIELDTYPENAME
    from RDB$RELATION_FIELDS F
    LEFT JOIN RDB$FIELDS D ON F.RDB$FIELD_SOURCE=D.RDB$FIELD_NAME
    LEFT JOIN RDB$TYPES T ON T.RDB$TYPE=D.RDB$FIELD_TYPE AND T.RDB$FIELD_NAME = 'RDB$FIELD_TYPE'
    WHERE F.RDB$RELATION_NAME='FOGUEST'
    ORDER BY RDB$RELATION_NAME,RDB$FIELD_POSITION

    INTO
      :FIELDNAME,
      :FIELDTYPE,
      :FIELDLENGTH,
      :FIELDTYPENAME
  DO
  BEGIN
    IF (EXISTS(SELECT * FROM RDB$RELATION_FIELDS F WHERE F.RDB$RELATION_NAME='FO_HIST_GUEST'
               AND F.RDB$FIELD_NAME = :FIELDNAME)) THEN
       FLAG_FO_HIST_GUEST = '1';
    ELSE FLAG_FO_HIST_GUEST = ' ';
    IF (EXISTS(SELECT * FROM RDB$RELATION_FIELDS F WHERE F.RDB$RELATION_NAME='FO_HIST_STAY'
               AND F.RDB$FIELD_NAME = :FIELDNAME)) THEN
       FLAG_FO_HIST_STAY = '1';
    ELSE FLAG_FO_HIST_STAY = ' ';
    IF ((FLAG_FO_HIST_STAY=' ') AND (FLAG_FO_HIST_GUEST=' ')) THEN
       SUSPEND;
  END
  /* FOGUEST_JUR */
  TABLENAME = 'FOGUEST_JUR';
  FLAG_FO_HIST_STAY = ' ';
  FOR
    select F.RDB$FIELD_NAME FIELDNAME,
    D.RDB$FIELD_TYPE FIELDTYPE,
    D.RDB$FIELD_LENGTH FIELDLENGTH,
    T.RDB$TYPE_NAME FIELDTYPENAME
    from RDB$RELATION_FIELDS F
    LEFT JOIN RDB$FIELDS D ON F.RDB$FIELD_SOURCE=D.RDB$FIELD_NAME
    LEFT JOIN RDB$TYPES T ON T.RDB$TYPE=D.RDB$FIELD_TYPE AND T.RDB$FIELD_NAME = 'RDB$FIELD_TYPE'
    WHERE F.RDB$RELATION_NAME='FOGUEST_JUR'
    ORDER BY RDB$RELATION_NAME,RDB$FIELD_POSITION

    INTO
      :FIELDNAME,
      :FIELDTYPE,
      :FIELDLENGTH,
      :FIELDTYPENAME
  DO
  BEGIN
    IF (EXISTS(SELECT * FROM RDB$RELATION_FIELDS F WHERE F.RDB$RELATION_NAME='FO_HIST_JUR'
               AND F.RDB$FIELD_NAME = :FIELDNAME)) THEN
       FLAG_FO_HIST_GUEST = '1';
    ELSE FLAG_FO_HIST_GUEST = ' ';
    IF (FLAG_FO_HIST_GUEST=' ') THEN
    SUSPEND;
  END
END^


ALTER PROCEDURE SP_MODULUS(
    DIVIDEND INTEGER,
    DIVISOR INTEGER)
RETURNS (
    RESULT INTEGER)
AS
BEGIN
  /* This procedure calculates the modulus of two number */
  IF(Dividend = 0) THEN Result = 0;
  ELSE
    Result = Dividend-(CAST((Dividend / Divisor)-0.5 AS INTEGER)*Divisor);
END^


ALTER PROCEDURE SP_MONTH(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE WorkDate DATE;
DECLARE VARIABLE WorkDay  INTEGER;
BEGIN
  WorkDate = ADate;
  Result = 1;
  WHILE(CAST(WorkDate AS VARCHAR(5)) <> '1-JAN') DO
  BEGIN
    EXECUTE PROCEDURE SP_Day(WorkDate) RETURNING_VALUES WorkDay;
    IF(WorkDay = 1) THEN Result = Result+1;
    WorkDate = WorkDate-1;
  END
END^


ALTER PROCEDURE SP_NUMBER_TO_TEXT(
    ALANGUAGE CHAR(1),
    AVALUE DOUBLE PRECISION)
RETURNS (
    TEXT VARCHAR(512))
AS
declare variable frac double precision;
declare variable ivalue integer;
declare variable thousand double precision;
declare variable million double precision;
declare variable billion double precision;
declare variable trillion double precision;
declare variable tdigit varchar(80);
declare variable x integer;
BEGIN
  IF ((ALANGUAGE IS NULL) OR (ALANGUAGE NOT IN ('E','I'))) THEN
     ALANGUAGE = 'E';

  IF (AVALUE IS NULL) THEN
  BEGIN
     AVALUE = 0;
  END
  IF (AVALUE < 0) THEN AVALUE = -AVALUE;
  TEXT = '';
  /* ---------------------------------------------------------------- */
  /* hitung dibelakang koma                                           */
  /* ---------------------------------------------------------------- */
  IVALUE = AVALUE-0.5;
  FRAC = AVALUE - IVALUE;
  /* ---------------------------------------------------------------- */
  /* KALAU DI BELAKANG KOMA > 0.99, MAKA DIANGGAP 1                   */
  /* ---------------------------------------------------------------- */
  IF (FRAC > 0.99) THEN
  BEGIN
     AVALUE = IVALUE + 1;
     FRAC = 0;
  END

  IF (AVALUE = 0) THEN
  BEGIN
     IF (ALANGUAGE = 'E') THEN TEXT = 'zero';
     ELSE TEXT = 'Nol';
     SUSPEND;
     EXIT;
  END
  TEXT = ALANGUAGE;

  TEXT = '';
  Thousand = 1000;
  Million  = 1000000;
  Billion  = 1000000000;
  Trillion = 1000000000000;
  /* ---------------------------------------------------------------- */
  /* TRILLION                                                         */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Trillion) THEN
  BEGIN
     IVALUE = (AVALUE / Trillion - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);

     TEXT = TEXT || TDIGIT;
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' trillion';
     ELSE TEXT = TEXT || ' triliun';
     AVALUE = AVALUE - IVALUE * Trillion;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END
  /* ---------------------------------------------------------------- */
  /* BILLION                                                          */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Billion) THEN
  BEGIN
     IVALUE = (AVALUE / Billion - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);

     TEXT = TEXT || TDIGIT;
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' billion';
     ELSE TEXT = TEXT || ' milyar';
     
     AVALUE = AVALUE - IVALUE * Billion;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END

  /* ---------------------------------------------------------------- */
  /* MILLION                                                          */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Million) THEN
  BEGIN
     IVALUE = (AVALUE / Million - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);

     TEXT = TEXT || TDIGIT;
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' million';
     ELSE TEXT = TEXT || ' juta';

     AVALUE = AVALUE - IVALUE * Million;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END

  /* ---------------------------------------------------------------- */
  /* THOUSAND                                                         */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Thousand) THEN
  BEGIN
     IVALUE = (AVALUE / Thousand - 0.5);
     IF (IVALUE = 1) THEN
     BEGIN
        IF (ALANGUAGE = 'E') THEN TEXT = TEXT || 'one thousand';
        ELSE TEXT = TEXT || 'seribu';
     END
     ELSE
     BEGIN
        EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
           RETURNING_VALUES(TDIGIT);

        TEXT = TEXT || TDIGIT;
        IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' thousand';
        ELSE TEXT = TEXT || ' ribu';
     END
     AVALUE = AVALUE - IVALUE * Thousand;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END

  /* ---------------------------------------------------------------- */
  /* LESS THEN ONE THOUSAND                                           */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >=1) THEN
  BEGIN
     IVALUE = (AVALUE - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);
     TEXT = TEXT || TDIGIT;
  END
  /* ---------------------------------------------------------------- */
  /* DECIMAL                                                          */
  /* ---------------------------------------------------------------- */
  FRAC = (FRAC+0.005) * 100;
  IVALUE = FRAC-0.5;
  IF (IVALUE > 0) THEN
  BEGIN
     /*
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' and ' || IVALUE || '/100';
     ELSE TEXT = TEXT || ' dan ' || IVALUE || '/100';
     */
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);
        
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' and ' || TDIGIT || ' cents';
     ELSE TEXT = TEXT || ' dan ' || TDIGIT || ' sen';
  END
  SUSPEND;
END^


ALTER PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(
    ALANGUAGE CHAR(1),
    I INTEGER)
RETURNS (
    TEXT VARCHAR(80))
AS
DECLARE VARIABLE Hundred VARCHAR(14);
DECLARE VARIABLE One     VARCHAR(14);
DECLARE VARIABLE Two     VARCHAR(14);
DECLARE VARIABLE Three   VARCHAR(14);
DECLARE VARIABLE Four    VARCHAR(14);
DECLARE VARIABLE Five    VARCHAR(14);
DECLARE VARIABLE Six     VARCHAR(14);
DECLARE VARIABLE Seven   VARCHAR(14);
DECLARE VARIABLE Eight   VARCHAR(14);
DECLARE VARIABLE Nine    VARCHAR(14);
DECLARE VARIABLE T10     VARCHAR(14);
DECLARE VARIABLE T11     VARCHAR(14);
DECLARE VARIABLE T12     VARCHAR(14);
DECLARE VARIABLE T13     VARCHAR(14);
DECLARE VARIABLE T14     VARCHAR(14);
DECLARE VARIABLE T15     VARCHAR(14);
DECLARE VARIABLE T16     VARCHAR(14);
DECLARE VARIABLE T17     VARCHAR(14);
DECLARE VARIABLE T18     VARCHAR(14);
DECLARE VARIABLE T19     VARCHAR(14);
DECLARE VARIABLE T20     VARCHAR(14);
DECLARE VARIABLE T30     VARCHAR(14);
DECLARE VARIABLE T40     VARCHAR(14);
DECLARE VARIABLE T50     VARCHAR(14);
DECLARE VARIABLE T60     VARCHAR(14);
DECLARE VARIABLE T70     VARCHAR(14);
DECLARE VARIABLE T80     VARCHAR(14);
DECLARE VARIABLE T90     VARCHAR(14);

DECLARE VARIABLE FLAG INTEGER;
DECLARE VARIABLE IVALUE INTEGER;
BEGIN
  IF (ALANGUAGE <> 'E') THEN
  BEGIN
     Hundred = ' ratus';
     One     = 'satu';
     Two     = 'dua';
     Three   = 'tiga';
     Four    = 'empat';
     Five    = 'lima';
     Six     = 'enam';
     Seven   = 'tujuh';
     Eight   = 'delapan';
     Nine    = 'sembilan';
     T10     = 'sepuluh';
     T11     = 'sebelas';
     T12     = 'dua belas';
     T13     = 'tiga belas';
     T14     = 'empat belas';
     T15     = 'lima belas';
     T16     = 'enam belas';
     T17     = 'tujuh belas';
     T18     = 'delapan belas';
     T19     = 'sebilan belas';
     T20     = 'dua puluh';
     T30     = 'tiga puluh';
     T40     = 'empat puluh';
     T50     = 'lima puluh';
     T60     = 'enam puluh';
     T70     = 'tujuh puluh';
     T80     = 'delapan puluh';
     T90     = 'sembilan puluh';
  END
  ELSE
  BEGIN
     Hundred = ' hundred';
     One     = 'one';
     Two     = 'two';
     Three   = 'three';
     Four    = 'four';
     Five    = 'five';
     Six     = 'six';
     Seven   = 'seven';
     Eight   = 'eight';
     Nine    = 'nine';
     T10     = 'ten';
     T11     = 'eleven';
     T12     = 'twelve';
     T13     = 'thirteen';
     T14     = 'fourteen';
     T15     = 'fifteen';
     T16     = 'sixteen';
     T17     = 'seventeen';
     T18     = 'eighteen';
     T19     = 'nineteen';
     T20     = 'twenty';
     T30     = 'thirty';
     T40     = 'forty';
     T50     = 'fifty';
     T60     = 'sixty';
     T70     = 'seventy';
     T80     = 'eighty';
     T90     = 'ninety';
  END
  FLAG = 0;
  IVALUE = (I / 100 - 0.5);

  IF (IVALUE <> 0) THEN FLAG = 1;
  IF (IVALUE = 0) THEN TEXT = '';
  ELSE IF (IVALUE = 1) THEN
  BEGIN
     IF (ALANGUAGE = 'E') THEN TEXT = One || Hundred;
     ELSE TEXT = 'seratus';
  END
  ELSE IF (IVALUE = 2) THEN TEXT = Two   || Hundred;
  ELSE IF (IVALUE = 3) THEN TEXT = Three || Hundred;
  ELSE IF (IVALUE = 4) THEN TEXT = Four  || Hundred;
  ELSE IF (IVALUE = 5) THEN TEXT = Five  || Hundred;
  ELSE IF (IVALUE = 6) THEN TEXT = Six   || Hundred;
  ELSE IF (IVALUE = 7) THEN TEXT = Seven || Hundred;
  ELSE IF (IVALUE = 8) THEN TEXT = Eight || Hundred;
  ELSE IF (IVALUE = 9) THEN TEXT = Nine  || Hundred;
  
  IF (FLAG = 1) THEN
     I = I - IVALUE * 100;

  IF (I > 0) THEN TEXT = TEXT || ' ';
  ELSE
  BEGIN
     SUSPEND;
     EXIT;
  END

  /* ---------------------------------------------------------------- */
  /* PULUHAN                                                          */
  /* ---------------------------------------------------------------- */
  FLAG = 1;
  IVALUE = (I / 10 - 0.5);
  IF ((IVALUE = 0) OR (IVALUE = 1)) THEN
  BEGIN
     FLAG = 0;
  END
  ELSE IF (IVALUE = 2) THEN TEXT = TEXT || T20;
  ELSE IF (IVALUE = 3) THEN TEXT = TEXT || T30;
  ELSE IF (IVALUE = 4) THEN TEXT = TEXT || T40;
  ELSE IF (IVALUE = 5) THEN TEXT = TEXT || T50;
  ELSE IF (IVALUE = 6) THEN TEXT = TEXT || T60;
  ELSE IF (IVALUE = 7) THEN TEXT = TEXT || T70;
  ELSE IF (IVALUE = 8) THEN TEXT = TEXT || T80;
  ELSE IF (IVALUE = 9) THEN TEXT = TEXT || T90;

  IF (FLAG = 1) THEN
     I = I - IVALUE * 10;

  IF (I > 0) THEN TEXT = TEXT || ' ';
  ELSE
  BEGIN
     SUSPEND;
     EXIT;
  END
  
  IF (I = 1) THEN TEXT = TEXT || ONE;
  ELSE IF (I = 2) THEN TEXT = TEXT || Two;
  ELSE IF (I = 3) THEN TEXT = TEXT || Three;
  ELSE IF (I = 4) THEN TEXT = TEXT || Four;
  ELSE IF (I = 5) THEN TEXT = TEXT || Five;
  ELSE IF (I = 6) THEN TEXT = TEXT || Six;
  ELSE IF (I = 7) THEN TEXT = TEXT || Seven;
  ELSE IF (I = 8) THEN TEXT = TEXT || Eight;
  ELSE IF (I = 9) THEN TEXT = TEXT || Nine;
  ELSE IF (I =10) THEN TEXT = TEXT || T10;
  ELSE IF (I =11) THEN TEXT = TEXT || T11;
  ELSE IF (I =12) THEN TEXT = TEXT || T12;
  ELSE IF (I =13) THEN TEXT = TEXT || T13;
  ELSE IF (I =14) THEN TEXT = TEXT || T14;
  ELSE IF (I =15) THEN TEXT = TEXT || T15;
  ELSE IF (I =16) THEN TEXT = TEXT || T16;
  ELSE IF (I =17) THEN TEXT = TEXT || T17;
  ELSE IF (I =18) THEN TEXT = TEXT || T18;
  ELSE IF (I =19) THEN TEXT = TEXT || T19;
  SUSPEND;
END^


