ALTER PROCEDURE SP_SAVE_LOG(
    TABLENAME VARCHAR(40),
    ID INTEGER,
    VALUEKEY VARCHAR(20),
    FIELDNAME VARCHAR(40),
    DBACTION CHAR(1),
    VALUENEW VARCHAR(100),
    VALUEOLD VARCHAR(100),
    USRID VARCHAR(8))
AS
DECLARE VARIABLE FOSYSDATE DATE;
BEGIN
  /* ---------------------------------------------------------------- */
  /* 1 NOVEMBER 2008                                                  */
  /* EVENT GUEST CHANGED                                              */
  /* ---------------------------------------------------------------- */
  IF ((TABLENAME = 'FOGUEST') AND (DBACTION = 'U')) THEN
     POST_EVENT 'FOGUEST_' || VALUEKEY;
  /* ---------------------------------------------------------------- */
  /* EVENT GUEST CHANGED                                              */
  /* ---------------------------------------------------------------- */
  
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;
  DELETE FROM SYSLOG WHERE FODATE <= :FOSYSDATE - 7;
  
  INSERT INTO SYSLOG (
    TABLENAME,
    VALUEKEY,
    SYSLOG_ID,
    FIELDNAME,
    DBACTION,
    VALUENEW,
    VALUEOLD,
    USEID,
    SYSDATE)
  VALUES (
    :TABLENAME,
    :VALUEKEY,
    :ID,    
    :FIELDNAME,
    :DBACTION,
    :VALUENEW,
    :VALUEOLD,
    :USRID,
    'NOW');
  WHEN ANY DO BEGIN
    USRID = '';
  END


END^


