ALTER PROCEDURE SP_YEAR(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE ElapsedDays  INTEGER;
DECLARE VARIABLE ElapsedYears INTEGER;
BEGIN
  /* Lets go to the begin of the year */
  WHILE(CAST(ADate AS VARCHAR(5)) <> '1-JAN') DO
    ADate = ADate -1;
  ElapsedDays = ADate -'1.1.1901';
  Result = (ElapsedDays *400 /146097)+1901;
END^


ALTER PROCEDURE SP_YEARMONTH(
    ADAY INTEGER)
RETURNS (
    YEARMONTH VARCHAR(6))
AS
declare variable Y INTEGER;
declare variable M INTEGER;
declare variable sy char(2);
declare variable sm char(2);
begin
  Y = CAST((ADAY / 365)-0.5 AS INTEGER);
  M = ADAY - Y * 365;
  M = M / 30;
  SY = Y;
  if (Y < 10) then SY = ' ' || SY;
  SM = M;
  if (M < 10) then SM = ' ' || SM;
  YEARMONTH = SY || 'y' || SM || 'm';
  suspend;
end^


