ALTER PROCEDURE UPDATE_DATERESV(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    COUNTER INTEGER)
AS
declare variable DATERESV TIMESTAMP;
declare variable FOLIO INTEGER;
begin
  COUNTER = 0;
  FOR SELECT L.DATERESV, L.FOLIO
      FROM FOGUEST L
      WHERE FOLIOSTATUS_SHARE ='M'
      AND FOLIOTYPE ='P'
      INTO :DATERESV,:FOLIO

  DO
    BEGIN
        UPDATE FOSTAT_LOG SET DATERESV =:DATERESV
        WHERE FOLIO = :FOLIO
        AND FODATE BETWEEN :SDATE AND :EDATE
        AND DATERESV IS NULL;

        COUNTER = COUNTER+1;

        BEGIN
            suspend;
        END
    END
end^


ALTER PROCEDURE WOTA_DESKTOP_STATISTIC
RETURNS (
    TEXT VARCHAR(40),
    FORMAT VARCHAR(40),
    CTODAY DOUBLE PRECISION,
    CMTD DOUBLE PRECISION,
    CYTD DOUBLE PRECISION,
    FLAG_ERROR INTEGER)
AS
DECLARE VARIABLE FTODAY DATE;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE FBOM DATE;
DECLARE VARIABLE FBOY DATE;
DECLARE VARIABLE FTOD_COUNT INTEGER;
DECLARE VARIABLE FTOD_ROOM  INTEGER;
DECLARE VARIABLE FTOD_NIGHT INTEGER;
DECLARE VARIABLE FTOD_ADULT INTEGER;
DECLARE VARIABLE FTOD_REV   DOUBLE PRECISION;

DECLARE VARIABLE FMTD_COUNT INTEGER;
DECLARE VARIABLE FMTD_ROOM  INTEGER;
DECLARE VARIABLE FMTD_NIGHT INTEGER;
DECLARE VARIABLE FMTD_ADULT INTEGER;
DECLARE VARIABLE FMTD_REV   DOUBLE PRECISION;

DECLARE VARIABLE FYTD_COUNT INTEGER;
DECLARE VARIABLE FYTD_ROOM  INTEGER;
DECLARE VARIABLE FYTD_NIGHT INTEGER;
DECLARE VARIABLE FYTD_ADULT INTEGER;
DECLARE VARIABLE FYTD_REV   DOUBLE PRECISION;
BEGIN
  FORMAT = '#,##0;(#,##0);-';
  
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FTODAY;
  
  /* ---------------------------------------------------------------- */
  /* IMPORT STATUS                                                    */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM WOTA_GET_RESV WHERE IMPORT_STATUS = 'O' INTO CTODAY;
  IF (CTODAY <> 0) THEN
  BEGIN
     TEXT = 'Reservation not saved';
     CMTD = 0;
     CYTD = 0;
     FLAG_ERROR = 1;
     SUSPEND;
     FLAG_ERROR = 0;
     FORMAT = '&nbsp;';
     CTODAY = 0;
     TEXT = '';
     SUSPEND;
     FORMAT = '#,##0;(#,##0);-';
  END
  /* ---------------------------------------------------------------- */
  /* STATISTIC                                                        */
  /* ---------------------------------------------------------------- */

  EXECUTE PROCEDURE SP_DECODEDATE(FTODAY) RETURNING_VALUES(Y,M,D);
  
  FTODAY = D || '.' || M || '.' || Y;
  FBOM   = '1.' || M || '.' || Y;
  FBOY   = '1.1.' || Y;
  
  SELECT COUNT(*),SUM(TOTAL_ROOM),SUM(TOTAL_NIGHT),SUM(GUEST_COUNT_ADULT),SUM(TOTAL_AMOUT_AFTER_TAX)
  FROM WOTA_GET_RESV
  WHERE IMPORT_FODATE = :FTODAY
  INTO FTOD_COUNT,FTOD_ROOM,FTOD_NIGHT,FTOD_ADULT,FTOD_REV;
  
  IF (FTOD_COUNT = 0) THEN
  BEGIN
     FTOD_ROOM = 0;
     FTOD_NIGHT = 0;
     FTOD_ADULT = 0;
     FTOD_REV = 0;
  END
  
  SELECT COUNT(*),SUM(TOTAL_ROOM),SUM(TOTAL_NIGHT),SUM(GUEST_COUNT_ADULT),SUM(TOTAL_AMOUT_AFTER_TAX)
  FROM WOTA_GET_RESV
  WHERE IMPORT_FODATE BETWEEN :FBOM AND :FTODAY
  INTO FMTD_COUNT,FMTD_ROOM,FMTD_NIGHT,FMTD_ADULT,FMTD_REV;

  IF (FMTD_COUNT = 0) THEN
  BEGIN
     FMTD_ROOM = 0;
     FMTD_NIGHT = 0;
     FMTD_ADULT = 0;
     FMTD_REV = 0;
  END

  SELECT COUNT(*),SUM(TOTAL_ROOM),SUM(TOTAL_NIGHT),SUM(GUEST_COUNT_ADULT),SUM(TOTAL_AMOUT_AFTER_TAX)
  FROM WOTA_GET_RESV
  WHERE IMPORT_FODATE BETWEEN :FBOM AND :FTODAY
  INTO FYTD_COUNT,FYTD_ROOM,FYTD_NIGHT,FYTD_ADULT,FYTD_REV;

  IF (FYTD_COUNT = 0) THEN
  BEGIN
     FYTD_ROOM = 0;
     FYTD_NIGHT = 0;
     FYTD_ADULT = 0;
     FYTD_REV = 0;
  END
  
  TEXT = 'No of Reservations';
  CTODAY = FTOD_COUNT;
  CMTD   = FMTD_COUNT;
  CYTD   = FMTD_COUNT;
  SUSPEND;
  
  TEXT = 'No of Rooms';
  CTODAY = FTOD_ROOM;
  CMTD   = FMTD_ROOM;
  CYTD   = FMTD_ROOM;
  SUSPEND;
  
  TEXT = 'No of Nights';
  CTODAY = FTOD_NIGHT;
  CMTD   = FMTD_NIGHT;
  CYTD   = FMTD_NIGHT;
  SUSPEND;

  TEXT = 'No of Adult';
  CTODAY = FTOD_ADULT;
  CMTD   = FMTD_ADULT;
  CYTD   = FMTD_ADULT;
  SUSPEND;
  
  TEXT = 'Potential Revenue';
  CTODAY = FTOD_REV;
  CMTD   = FMTD_REV;
  CYTD   = FMTD_REV;
  SUSPEND;
  
  FORMAT = '&nbsp;';
  CTODAY = 0;
  CMTD   = 0;
  CYTD   = 0;
  TEXT = '';
  SUSPEND;
  FORMAT = '#,##0;(#,##0);-';
  TEXT = 'Average Revenue';
  IF (FTOD_NIGHT <> 0) THEN CTODAY = FTOD_REV / FTOD_NIGHT;
  IF (FMTD_NIGHT <> 0) THEN CMTD   = FMTD_REV / FMTD_NIGHT;
  IF (FYTD_NIGHT <> 0) THEN CYTD   = FYTD_REV / FYTD_NIGHT;
  SUSPEND;
  
  FORMAT = '#,##0.00;(#,##0.00);-';
  TEXT = 'Length Of Stay';
  CTODAY = 0;
  CMTD   = 0;
  CYTD   = 0;
  IF (FTOD_ROOM <> 0) THEN CTODAY = FTOD_NIGHT / FTOD_ROOM;
  IF (FMTD_ROOM <> 0) THEN CMTD   = FMTD_NIGHT / FMTD_ROOM;
  IF (FYTD_ROOM <> 0) THEN CYTD   = FYTD_NIGHT / FYTD_ROOM;
  SUSPEND;
  
  FORMAT = '#,##0.## %;(#,##0.## %);-';
  TEXT = '% Double Occupancy';
  CTODAY = 0;
  CMTD   = 0;
  CYTD   = 0;
  IF (FTOD_ROOM <> 0) THEN CTODAY = (FTOD_ADULT-FTOD_ROOM) / FTOD_ROOM * 100;
  IF (FMTD_ROOM <> 0) THEN CMTD   = (FMTD_ADULT-FMTD_ROOM) / FMTD_ROOM * 100;
  IF (FYTD_ROOM <> 0) THEN CYTD   = (FYTD_ADULT-FYTD_ROOM) / FYTD_ROOM * 100;
  SUSPEND;
END^


ALTER PROCEDURE WOTA_SAVE_RESV(
    PLOG_ID INTEGER,
    PUNIQUEID_ID VARCHAR(40),
    PSAVE INTEGER,
    USRID VARCHAR(8))
RETURNS (
    FOLIO INTEGER,
    IDX INTEGER,
    ROOMRATE_CODE VARCHAR(12),
    ROOMTYPE_CODE VARCHAR(12),
    LOG_ID INTEGER,
    RESSTATUS VARCHAR(12),
    UNIQUEID_ID VARCHAR(40),
    UNIQUEID_TYPE VARCHAR(4),
    SOURCE_REQUESTORID VARCHAR(40),
    SOURCE_TYPE VARCHAR(4),
    SORUCE_COMPANY_CODE VARCHAR(12),
    SOURCE_COMPANY_NAME VARCHAR(40),
    GUEST_COUNT_ADULT INTEGER,
    GUEST_COUNT_CHILD INTEGER,
    GUEST_COUNT_INFANT INTEGER,
    COMMENT_TEXT BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    TIMESPAN_START DATE,
    TIMESPAN_END DATE,
    TOTAL_AMOUT_AFTER_TAX DOUBLE PRECISION,
    TOTAL_ROOM DOUBLE PRECISION,
    PROFILE_GIVENAME VARCHAR(40),
    PROFILE_SURNAME VARCHAR(40),
    PROFILE_PHONE VARCHAR(40),
    PROFILE_EMAIL VARCHAR(80),
    PROFILE_ADDRESS1 VARCHAR(40),
    PROFILE_ADDRESS2 VARCHAR(40),
    PROFILE_CITY VARCHAR(40),
    PROFILE_POSTAL VARCHAR(12),
    PROFILE_STATE VARCHAR(40),
    IMPORT_STATUS CHAR(1),
    IMPORT_FODATE DATE,
    IMPORT_SYSDATE DATE,
    IMPORT_SAVE_FOLIO INTEGER)
AS
declare variable title varchar(6);
declare variable ratecode varchar(12);
declare variable guest_line integer;
declare variable fname varchar(40);
declare variable lname varchar(40);
declare variable roomtype varchar(4);
declare variable suniqueid_id varchar(40);
declare variable euniqueid_id varchar(40);
declare variable folio_master integer;
declare variable foliostatus_share char(1);
declare variable defa_st_resv_source varchar(4);
declare variable defa_st_nationality varchar(4);
declare variable defa_st_marketsegment varchar(4);
declare variable defa_st_originarea varchar(4);
declare variable defa_st_destinationarea varchar(4);
declare variable defa_currency varchar(4);
declare variable defa_paymentcode varchar(4);
declare variable defa_creditlimit double precision;
declare variable defa_company varchar(6);
declare variable defa_cancellation_code varchar(4);
declare variable defa_cancel_code_for_modified varchar(4);
declare variable exchange double precision;
declare variable note_arrival varchar(255);
declare variable note_departure varchar(255);
declare variable note_payment varchar(255);
declare variable note_address varchar(255);
declare variable eol varchar(2);
declare variable fosysdate date;
declare variable rfodate date;
declare variable rcharge double precision;
declare variable fo_company varchar(6);
declare variable fo_ratecode varchar(12);
declare variable ppkg_code varchar(12);
declare variable ppkg_nextday integer;
declare variable ppkg_charge_adult double precision;
declare variable ppkg_charge_flat double precision;
declare variable ppkg_charge_child double precision;
declare variable rate_currency varchar(4);
BEGIN
  IF ((PUNIQUEID_ID IS NULL) OR (PUNIQUEID_ID='')) THEN
  BEGIN
     SUNIQUEID_ID = '';
     EUNIQUEID_ID = 'ZZZZZZ';
  END
  ELSE
  BEGIN
     SUNIQUEID_ID = PUNIQUEID_ID;
     EUNIQUEID_ID = PUNIQUEID_ID;
  END
  SELECT FOSYSDATE FROM FOSYSPARAM INTO FOSYSDATE;

  /* ---------------------------------------------------------------- */
  /* DEFAULT FIELD                                                    */
  /* ---------------------------------------------------------------- */

  SELECT DEFA_ST_RESV_SOURCE,DEFA_ST_NATIONALITY,DEFA_ST_MARKETSEGMENT,
    DEFA_ST_ORIGINAREA,DEFA_ST_DESTINATIONAREA,
    DEFA_CURRENCY,DEFA_PAYMENTCODE,DEFA_CREDITLIMIT,DEFA_COMPANY,
    DEFA_CANCELLATION_CODE,DEFA_CANCEL_CODE_FOR_MODIFIED,EOL_CODE
  FROM WOTA_CONFIG
  WHERE ID = 1
  INTO DEFA_ST_RESV_SOURCE,DEFA_ST_NATIONALITY,DEFA_ST_MARKETSEGMENT,
    DEFA_ST_ORIGINAREA,DEFA_ST_DESTINATIONAREA,
    DEFA_CURRENCY,DEFA_PAYMENTCODE,DEFA_CREDITLIMIT,DEFA_COMPANY,
    DEFA_CANCELLATION_CODE,DEFA_CANCEL_CODE_FOR_MODIFIED,EOL;
  /* -------------------------------------------------------------------- */
  /* 10/29/2012                                                           */
  /* -------------------------------------------------------------------- */
  UPDATE WOTA_GET_RESV SET IMPORT_STATUS='E'
  WHERE IMPORT_STATUS = 'O'
  AND TIMESPAN_START < :FOSYSDATE;

  /* -------------------------------------------------------------------- */
  /* CHECK COMPANY CODE                                                   */
  /* -------------------------------------------------------------------- */
  FOR SELECT SORUCE_COMPANY_CODE,SOURCE_COMPANY_NAME
    FROM WOTA_GET_RESV
    WHERE IMPORT_STATUS = 'O'
    AND SORUCE_COMPANY_CODE IS NOT NULL
    AND SORUCE_COMPANY_CODE <> ''
    INTO :SORUCE_COMPANY_CODE,:SOURCE_COMPANY_NAME
  DO

  BEGIN
    IF (NOT EXISTS(SELECT * FROM WOTA_CONVERSION WHERE FIELDNAME='COMPANY'  AND DATA_WEB = :SORUCE_COMPANY_CODE)) THEN
    BEGIN
       INSERT INTO WOTA_CONVERSION (FIELDNAME,DATA_WEB,DATA_FO,DATA_CODE1)
       VALUES ('COMPANY',:SORUCE_COMPANY_CODE,'?',:SOURCE_COMPANY_NAME);
    END
  END


  /* ----------------------------------------------------------- */
  /* check reservation                                           */
  /* ----------------------------------------------------------- */
  FOR
    SELECT LOG_ID,
      RESSTATUS,
      UNIQUEID_ID,
      UNIQUEID_TYPE,
      SOURCE_REQUESTORID,
      SOURCE_TYPE,
      SORUCE_COMPANY_CODE,
      SOURCE_COMPANY_NAME,
      GUEST_COUNT_ADULT,
      GUEST_COUNT_CHILD,
      GUEST_COUNT_INFANT,
      COMMENT_TEXT,
      TIMESPAN_START,
      TIMESPAN_END,
      TOTAL_AMOUT_AFTER_TAX,
      TOTAL_ROOM,
      PROFILE_GIVENAME,
      PROFILE_SURNAME,
      PROFILE_PHONE,
      PROFILE_EMAIL,
      PROFILE_ADDRESS1,
      PROFILE_ADDRESS2,
      PROFILE_CITY,
      PROFILE_POSTAL,
      PROFILE_STATE,
      IMPORT_STATUS,
      IMPORT_FODATE,
      IMPORT_SYSDATE,
      IMPORT_SAVE_FOLIO
    FROM WOTA_GET_RESV
    WHERE LOG_ID = :PLOG_ID
    AND UNIQUEID_ID BETWEEN :SUNIQUEID_ID AND :EUNIQUEID_ID
    AND IMPORT_STATUS = 'O'
    INTO
      :LOG_ID,
      :RESSTATUS,
      :UNIQUEID_ID,
      :UNIQUEID_TYPE,
      :SOURCE_REQUESTORID,
      :SOURCE_TYPE,
      :SORUCE_COMPANY_CODE,
      :SOURCE_COMPANY_NAME,
      :GUEST_COUNT_ADULT,
      :GUEST_COUNT_CHILD,
      :GUEST_COUNT_INFANT,
      :COMMENT_TEXT,
      :TIMESPAN_START,
      :TIMESPAN_END,
      :TOTAL_AMOUT_AFTER_TAX,
      :total_room,
      :PROFILE_GIVENAME,
      :PROFILE_SURNAME,
      :PROFILE_PHONE,
      :PROFILE_EMAIL,
      :PROFILE_ADDRESS1,
      :PROFILE_ADDRESS2,
      :PROFILE_CITY,
      :PROFILE_POSTAL,
      :PROFILE_STATE,
      :IMPORT_STATUS,
      :IMPORT_FODATE,
      :IMPORT_SYSDATE,
      :IMPORT_SAVE_FOLIO
  DO

  BEGIN
    IF (PSAVE = 1) THEN
    BEGIN
       /* -------------------------------------------------------------------- */
       IF (EXISTS(SELECT * FROM WOTA_CONVERSION WHERE FIELDNAME='COMPANY'  AND DATA_WEB = :SORUCE_COMPANY_CODE)) THEN
       BEGIN
          SELECT DATA_FO,
                 DATA_CODE1 /* 9/28/2012 */
          FROM WOTA_CONVERSION
          WHERE FIELDNAME='COMPANY'  AND DATA_WEB = :SORUCE_COMPANY_CODE
          INTO FO_COMPANY,
               FO_RATECODE; /* 9/28/2012 */
       END
       IF ((FO_COMPANY IS NULL) OR (FO_COMPANY IS NULL)) THEN FO_COMPANY = DEFA_COMPANY;
       IF ((FO_COMPANY IS NULL) OR (FO_COMPANY IS NULL)) THEN FO_COMPANY = '';
       FO_COMPANY = SUBSTR(FO_COMPANY,1,6);
       /* -------------------------------------------------------------------- */
       IF (RESSTATUS = 'Cancelled') THEN
       BEGIN
          EXIT;
       END
       IF (RESSTATUS = 'Modified') THEN
       BEGIN
          EXIT;
       END
    END

    /* ---------------------------------------------------------------- */
    /* CREATE RESERVATION FOR "New" Status or "Modified" Status         */
    /* ---------------------------------------------------------------- */
    FOR SELECT IDX,ROOMTYPE,RATECODE,AMOUNT_CURRENCY FROM WOTA_GET_RESV_RATE
    WHERE LOG_ID = :LOG_ID
    AND UNIQUEID_ID = :UNIQUEID_ID
    GROUP BY IDX,ROOMTYPE,RATECODE,AMOUNT_CURRENCY
    INTO IDX,ROOMTYPE_CODE,ROOMRATE_CODE,RATE_CURRENCY
    DO

    BEGIN
       IF (NOT EXISTS(SELECT * FROM WOTA_CONVERSION WHERE FIELDNAME='ROOMTYPE'  AND DATA_WEB = :ROOMTYPE_CODE)) THEN
       BEGIN
          INSERT INTO WOTA_CONVERSION (FIELDNAME,DATA_WEB,DATA_FO)
          VALUES ('ROOMTYPE',:ROOMTYPE_CODE,'?');
       END

       SELECT DATA_FO FROM WOTA_CONVERSION
       WHERE FIELDNAME = 'ROOMTYPE'
       AND DATA_WEB = :ROOMTYPE_CODE
       INTO ROOMTYPE;

       /* -------------------------------------------------------------------- */
       IF (NOT EXISTS(SELECT * FROM WOTA_CONVERSION WHERE FIELDNAME='ROOMRATE'  AND DATA_WEB = :ROOMRATE_CODE)) THEN
       BEGIN
          INSERT INTO WOTA_CONVERSION (FIELDNAME,DATA_WEB,DATA_FO)
          VALUES ('ROOMRATE',:ROOMRATE_CODE,'?');
       END
       /* -------------------------------------------------------------------- */
       SELECT DATA_FO FROM WOTA_CONVERSION
       WHERE FIELDNAME = 'ROOMRATE'
       AND DATA_WEB = :ROOMRATE_CODE
       INTO RATECODE;
       
       
       /* -------------------------------------------------------------------- */
       /* 9/28/2012                                                            */
       /* KALAU ADA KOVERSI DARI RATE DI SETUP OTA,UNTUK COMPANY              */
       /* -------------------------------------------------------------------- */
       IF (EXISTS(SELECT * FROM FORATE WHERE RATECODE=:FO_RATECODE)) THEN
          RATECODE = FO_RATECODE;
          
       IF (NOT EXISTS(SELECT * FROM FOFOREX WHERE CURRENCY=:RATE_CURRENCY)) THEN
          RATE_CURRENCY = DEFA_CURRENCY;
       /* ----------------------------------------------------------- */
       SELECT EXCHANGE FROM FOFOREX WHERE CURRENCY = :RATE_CURRENCY
       INTO EXCHANGE;
       /* ----------------------------------------------------------- */
       /* TEMPORARY RATE JUST FOR VALIDATION                          */
       /* ----------------------------------------------------------- */
       IF (RATECODE IS NULL) THEN
          RATECODE = 'HU';
       /* ----------------------------------------------------------- */
       TITLE = 'Mr.';
       GUEST_LINE = 1;
       FOR SELECT PROFILE_GIVENAME,PROFILE_SURNAME FROM WOTA_GET_RESV
           WHERE LOG_ID = :LOG_ID
           AND UNIQUEID_ID = :UNIQUEID_ID
           INTO FNAME,LNAME
       DO
       BEGIN
         FOLIO = GEN_ID(GEN_FOLIO,0)+1;
         IF (GUEST_LINE = 1) THEN
         BEGIN
            FOLIO_MASTER = FOLIO;
            FOLIOSTATUS_SHARE = 'M';
         END
         ELSE FOLIOSTATUS_SHARE = 'A';
         /* -------------------------------------------------------------------- */
         IF (PSAVE = 1) THEN
         BEGIN
            NOTE_ARRIVAL = '';
            NOTE_DEPARTURE = '';
            NOTE_PAYMENT = '';
            NOTE_ADDRESS = '';
            /* -------------------------------------------------------------------- */
            IF (PROFILE_ADDRESS1 IS NOT NULL) THEN NOTE_ADDRESS = PROFILE_ADDRESS1;
            IF (PROFILE_ADDRESS2 IS NOT NULL) THEN NOTE_ADDRESS = NOTE_ADDRESS || EOL || PROFILE_ADDRESS2;
            IF (PROFILE_STATE IS NOT NULL) THEN NOTE_ADDRESS = NOTE_ADDRESS || EOL || 'State: ' || PROFILE_STATE;
            IF (PROFILE_POSTAL IS NOT NULL) THEN NOTE_ADDRESS = NOTE_ADDRESS || ' / Zip:' || PROFILE_POSTAL;
            /* -------------------------------------------------------------------- */
            IF (TOTAL_AMOUT_AFTER_TAX IS NOT NULL) THEN NOTE_PAYMENT ='Amount: '|| CAST(TOTAL_AMOUT_AFTER_TAX AS NUMERIC(8,2));
            /* -------------------------------------------------------------------- */
            FOLIO = GEN_ID(GEN_FOLIO,0)+1;
            INSERT INTO FOGUEST
            (FOLIO,FOLIO_MASTER,FOLIOTYPE,FOLIOSTATUS,FOLIOSTATUS_SHARE,
             FNAME,LNAME,TITLE,PAX,CHILD,
             /* RESERVATION PROFILE */
             DATECI,DATECO,ROOMTYPE,RATECODE,
             /* COMPANY PROFILE */
             COMPANY,COMPANYNAME,
             /* ADDRESS & CONTACT */
             ADDRESS,RESV_CONTACT,RESV_PHONE,RESV_EMAIL,
             /* WEB CONFIRMATION ID */
             WEB_CONFIRMATIONID,VOUCHERNO,
             /* NOTE PICKUP,DROP,PREFER & SPECIAL REQUEST */
             NOTE_PICKUP,NOTE_DROP,NOTE_CHECKIN,NOTE_CASHIER,
             /* DEFAULT FIELD */
             ST_RESV_SOURCE,ST_NATIONALITY,ST_MARKETSEGMENT,
             ST_ORIGINAREA,ST_DESTINATIONAREA,
             CURRENCY,PAYMENTCODE,CREDITLIMIT)
            VALUES
            (:FOLIO,:FOLIO_MASTER,'P','G',:FOLIOSTATUS_SHARE,
             :FNAME,:LNAME,:TITLE,:GUEST_COUNT_ADULT/:TOTAL_ROOM,:GUEST_COUNT_CHILD+:GUEST_COUNT_INFANT,
             /* RESERVATION PROFILE */
             :TIMESPAN_START,:TIMESPAN_END,:ROOMTYPE,:RATECODE,
             /* COMPANY PROFILE */
             :FO_COMPANY,:SOURCE_COMPANY_NAME,
             /* ADDRESS & CONTACT */
             :NOTE_ADDRESS,:FNAME,:PROFILE_PHONE,:PROFILE_EMAIL,
             /* WEB CONFIRMATION ID */
             :UNIQUEID_ID,:UNIQUEID_ID,
             /* NOTE PICKUP,DROP,PREFER & SPECIAL REQUEST */
             :NOTE_ARRIVAL,:NOTE_DEPARTURE,:COMMENT_TEXT,:NOTE_PAYMENT,
             /* DEFAULT FIELD */
             :DEFA_ST_RESV_SOURCE,:DEFA_ST_NATIONALITY,:DEFA_ST_MARKETSEGMENT,
             :DEFA_ST_ORIGINAREA,:DEFA_ST_DESTINATIONAREA,
             :RATE_CURRENCY,:DEFA_PAYMENTCODE,:DEFA_CREDITLIMIT);
            /* -------------------------------------------------------------------- */
            IF (FOLIOSTATUS_SHARE = 'M') THEN
               SUSPEND;
            /* ----------------------------------------------------------- */
            /* LOAD ADHOC RATE                                             */
            /* ----------------------------------------------------------- */
            IF (FOLIOSTATUS_SHARE = 'M') THEN
            BEGIN

                FOR SELECT DATE_EFECTIVE,AMOUNT_AFTER_TAX FROM WOTA_GET_RESV_RATE
                    WHERE LOG_ID = :LOG_ID
                    AND UNIQUEID_ID = :UNIQUEID_ID
                    AND IDX = :IDX
                INTO RFODATE,RCHARGE
                DO
                BEGIN
                   /* ----------------------------------------------------------- */

                   INSERT INTO FOGROUP_RATE
                   (FOLIO,FODATE,ROOMTYPE,CURRENCY,EXCHANGE,
                    RATE1,RATE2,RATE3,RATE4,ADULT,CHILD,
                    TAXTYPE,TAXID,
                    CREATEDATE,EDITDATE,CREATEUSER,EDITUSER,TAG)
                   VALUES
                   (:FOLIO,:RFODATE,:ROOMTYPE,:RATE_CURRENCY,:EXCHANGE,
                   :RCHARGE,:RCHARGE,:RCHARGE,:RCHARGE,0,0,
                   'H',0,
                   'NOW','NOW',:USRID,:USRID,0);
                   /* ----------------------------------------------------------- */
                END

                UPDATE FOGUEST SET RATECODE = '(ADDHOC)' WHERE FOLIO = :FOLIO;
               /* ----------------------------------------------------------- */
               /* 9/26/2012                                                   */
               /* LOAD PACKAGE FROM ATTACHED PACKAGE                          */
               /* ----------------------------------------------------------- */
               FOR SELECT PACKAGE,NEXTDAY,CHARGE_ADULT,CHARGE_FLAT,CHARGE_CHILD
                   FROM FORATE_PACKAGE RT
                   LEFT JOIN FOPACKAGE PKG ON PKG.PACKAGE = RT.PACKAGE
                   WHERE RATECODE = :RATECODE
                   INTO PPKG_CODE,PPKG_NEXTDAY,
                        PPKG_CHARGE_ADULT,PPKG_CHARGE_FLAT,PPKG_CHARGE_CHILD
               DO
               BEGIN
                  /* -------------------------------------------------------------------- */
                  RFODATE = TIMESPAN_START;
                  WHILE (RFODATE < TIMESPAN_END) DO
                  BEGIN
                     IF (NOT EXISTS(SELECT * FROM FOGROUP_RATE_PACKAGE_DAILY
                         WHERE FOLIO = :FOLIO
                         AND TAG = 0
                         AND FODATE = :RFODATE
                         AND PACKAGE = :PPKG_CODE)) THEN
                     BEGIN
                        INSERT INTO FOGROUP_RATE_PACKAGE_DAILY
                        (FOLIO,ROOMTYPE,FODATE,PACKAGE,PACKAGE_ACTIVE,
                         CHARGE_FLAT,CHARGE_ADULT,CHARGE_CHILD,
                         CREATEDATE,EDITDATE,CREATEUSER,EDITUSER,
                         NEXTDAY,TAG)
                        VALUES
                         (:FOLIO,'',:RFODATE,:PPKG_CODE,1,
                          :PPKG_CHARGE_FLAT,:PPKG_CHARGE_ADULT,:PPKG_CHARGE_CHILD,
                          'NOW','NOW',:USRID,:USRID,:PPKG_NEXTDAY,0);
                     END
                     RFODATE = RFODATE + 1;
                  END /* END OF (RFODATE < TIMESPAN_END) */
               END /* END OF FOR SELECT PACKAGE  */
               /* -------------------------------------------------------------------- */
               /* END OF 9/26/2012                                                     */
               /* -------------------------------------------------------------------- */
            END /* IF (FOLIOSTATUS_SHARE = 'M') THEN */
         END /* SAVE */
         ELSE /* NOT SAVE */
           SUSPEND;
       END /* FOR SELECT FIRSTNAME,LASTNAME,TITLE,GUEST_LINEID FROM WRES_GET_RESV_ROOM_GUEST */
    END /* FOR SELECT .. FROM FROM WRES_GET_RESV_ROOM */


    IF (PSAVE=1) THEN
    BEGIN
       UPDATE WOTA_GET_RESV SET IMPORT_STATUS = 'R',IMPORT_SAVE_DATE = 'NOW',
              IMPORT_SAVE_USER = :USRID,IMPORT_SAVE_FOLIO = :FOLIO_MASTER
       WHERE LOG_ID = :LOG_ID
       AND UNIQUEID_ID = :UNIQUEID_ID;
    END
  END /* for select reservation profile */
END^


ALTER PROCEDURE WOTA_UPLOAD_LENGTHOFSTAY
RETURNS (
    RATECODE_WEB VARCHAR(12),
    RATECODE VARCHAR(12),
    MIN_LOS INTEGER,
    DATE_START DATE,
    DATE_END DATE,
    AVAILABLE_ROOMTYPE VARCHAR(4),
    ROOMTYPE_WEB VARCHAR(12),
    ROOMTYPE VARCHAR(4))
AS
/* */
declare variable FTODAY date;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 1/22/2013 yg di upload hanya rate yang di setujui,                  */
  /*           setup ada di WOTA_CONVERSION_RATE_ALLOTMENT                */
  /*           field FLAG_UPLOAD                                          */
  /* -------------------------------------------------------------------- */
  /* -------------------------------------------------------------------- */
  /* 5/22/2012 LENGTH OF STAY                                             */
  /* -------------------------------------------------------------------- */
  FTODAY = 'NOW';
  EXECUTE PROCEDURE SP_DATEONLY(FTODAY) RETURNING_VALUES(FTODAY);

  FOR SELECT DATA_WEB,DATA_FO
      FROM WOTA_CONVERSION
      WHERE FIELDNAME = 'ROOMRATE'
      INTO RATECODE_WEB,RATECODE
  DO
  BEGIN
     FOR SELECT DATESTART,DATEEND,RATE_STATUS,ROOMTYPE
         FROM FORATE_AVAILABLE
         WHERE RATECODE = :RATECODE
         ORDER BY PRIORITY
         INTO DATE_START,DATE_END,MIN_LOS,AVAILABLE_ROOMTYPE
     DO
     BEGIN
        /* -------------------------------------------------------------------- */
        /* KALAU TANGGAL SYSTEM LBH BESAR,MAKA AMBIL TODAY                    */
        /* -------------------------------------------------------------------- */
        IF(DATE_START <  FTODAY) THEN  DATE_START=:FTODAY;
        /* -------------------------------------------------------------------- */
        /* KALAU SEMUA ROOMTYPE KOSONG,MAKA SEMUA ROOM TYPE                    */
        /* -------------------------------------------------------------------- */
        IF (NOT EXISTS(SELECT * FROM FOROOMTYPE WHERE ROOMTYPE = :AVAILABLE_ROOMTYPE)) THEN
        BEGIN
           FOR SELECT C.DATA_WEB,C.DATA_FO
               FROM WOTA_CONVERSION C
               WHERE C.FIELDNAME = 'ROOMTYPE'
               AND (EXISTS(SELECT * FROM WOTA_CONVERSION_RATE_ALLOTMENT A /* 1/22/2013 */
                               WHERE A.RATECODE=:RATECODE
                               AND A.ROOMTYPE =SUBSTR(C.DATA_FO,1,4)
                               AND A.FLAG_UPLOAD = 1))
               INTO ROOMTYPE_WEB,ROOMTYPE
           DO
           BEGIN
              SUSPEND;
           END
        END
        ELSE
        BEGIN
           FOR SELECT C.DATA_WEB,C.DATA_FO
               FROM WOTA_CONVERSION C
               WHERE C.FIELDNAME = 'ROOMTYPE'
               AND C.DATA_FO = :AVAILABLE_ROOMTYPE
               AND (EXISTS(SELECT * FROM WOTA_CONVERSION_RATE_ALLOTMENT A /* 1/22/2013 */
                               WHERE A.RATECODE=:RATECODE
                               AND A.ROOMTYPE =SUBSTR(C.DATA_FO,1,4)
                               AND A.FLAG_UPLOAD = 1))
               INTO ROOMTYPE_WEB,ROOMTYPE
           DO
           BEGIN
              SUSPEND;
           END
        END
     END
  END
END^


ALTER PROCEDURE WOTA_UPLOAD_RATE
RETURNS (
    RATECODE_WEB VARCHAR(12),
    RATECODE VARCHAR(12),
    CURRENCY VARCHAR(4),
    DATE_START DATE,
    DATE_END DATE,
    PRIORITY INTEGER,
    MIN_LOS INTEGER,
    ROOMTYPE_WEB VARCHAR(12),
    ROOMTYPE VARCHAR(4),
    RATE1 DOUBLE PRECISION,
    RATE2 DOUBLE PRECISION,
    RATE3 DOUBLE PRECISION,
    RATE4 DOUBLE PRECISION,
    ADULT DOUBLE PRECISION,
    CHILD DOUBLE PRECISION,
    TEXT VARCHAR(40))
AS
/* */
declare variable sdate date;
declare variable edate date;
declare variable ftoday date;
declare variable fodate date;
declare variable new_priority integer;
declare variable old_priority integer;
declare variable day_count integer;
declare variable new_min_los integer;
declare variable old_min_los integer;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 1/22/2013 yg di upload hanya rate yang di setujui,                  */
  /*           setup ada di WOTA_CONVERSION_RATE_ALLOTMENT                */
  /*           field FLAG_UPLOAD                                          */
  /* -------------------------------------------------------------------- */
  SELECT UPLOAD_RI_DAYS FROM WOTA_CONFIG WHERE ID = 1
  INTO DAY_COUNT;

  FTODAY = 'NOW';
  EXECUTE PROCEDURE SP_DATEONLY(FTODAY) RETURNING_VALUES(FTODAY);
  SDATE = FTODAY;
  EDATE = SDATE + DAY_COUNT;
  /* -------------------------------------------------------------------- */

  /* -------------------------------------------------------------------- */
  /* GET RATECODE                                                         */
  /* -------------------------------------------------------------------- */
  FOR SELECT SUBSTR(DATA_WEB,1,12),SUBSTR(DATA_FO,1,12)
      FROM WOTA_CONVERSION
      WHERE FIELDNAME = 'ROOMRATE'
      INTO RATECODE_WEB,RATECODE
      DO
  BEGIN
      SELECT CURRENCY,NAME FROM FORATE
      WHERE RATECODE = :RATECODE
      INTO CURRENCY,TEXT;
      /* -------------------------------------------------------------------- */
      FODATE = SDATE;
      OLD_PRIORITY = -1;
      /* -------------------------------------------------------------------- */
      /* CALCULATE DATE RATE                                                  */
      /* -------------------------------------------------------------------- */
      WHILE (FODATE < EDATE) DO
      BEGIN
        /* -------------------------------------------------------------------- */
        /* GET RATE STATUS MINIMUM LENGTH OF STAY                               */
        /* -------------------------------------------------------------------- */
        SELECT RATESTATUS FROM FO_RATE_GETSTATUS(:RATECODE,:FODATE)
        INTO NEW_MIN_LOS;
        IF (NEW_MIN_LOS < 0) THEN NEW_MIN_LOS = 0;
        /* -------------------------------------------------------------------- */
        /* GET SURCHARGE RATE PRIORITY                                          */
        /* -------------------------------------------------------------------- */
        SELECT PRIORITY
        FROM FO_RATE_JUR_GET_SURCHARGE (:RATECODE,:FODATE,0,:FODATE,'')
        INTO NEW_PRIORITY;
        /* -------------------------------------------------------------------- */
        IF ((OLD_PRIORITY <> NEW_PRIORITY) OR (OLD_MIN_LOS <> NEW_MIN_LOS)) THEN
        BEGIN
           /* -------------------------------------------------------------------- */
           /* IF PRIORITY CHANGED                                                  */
           /* -------------------------------------------------------------------- */
           IF (OLD_PRIORITY <> -1) THEN
           BEGIN
              MIN_LOS = NEW_MIN_LOS;
              PRIORITY = OLD_PRIORITY;
              DATE_END = FODATE-1;
              /* -------------------------------------------------------------------- */
              /* LOAD SURCHARGE FROM CONVERSION                                       */
              /* -------------------------------------------------------------------- */
              FOR SELECT SUBSTR(C.DATA_WEB,1,12),SUBSTR(C.DATA_FO,1,4)
                  FROM WOTA_CONVERSION C
                  WHERE C.FIELDNAME='ROOMTYPE'
                  AND (EXISTS(SELECT * FROM WOTA_CONVERSION_RATE_ALLOTMENT A /* 1/22/2013 */
                               WHERE A.RATECODE=:RATECODE
                               AND A.ROOMTYPE =SUBSTR(C.DATA_FO,1,4)
                               AND A.FLAG_UPLOAD = 1))
                  INTO ROOMTYPE_WEB,ROOMTYPE
              DO
              BEGIN
                  IF (MIN_LOS <= 0) THEN /* CLOSE OR NOT AVAILABLE */
                  BEGIN
                     RATE1 = -1;
                     RATE2 = -1;
                     RATE3 = -1;
                     RATE4 = -1;
                     ADULT = -1;
                     CHILD = -1;
                  END
                  ELSE /* GET RATE */
                  BEGIN
                     SELECT RATE1,RATE2,RATE3,RATE4,ADULT,CHILD
                     FROM FORATE_DETAIL
                     WHERE RATECODE = :RATECODE
                     AND PRIORITY = :PRIORITY
                     AND ROOMTYPE = :ROOMTYPE
                     INTO RATE1,RATE2,RATE3,RATE4,ADULT,CHILD;
                  END
                  SUSPEND;
              END
              /* -------------------------------------------------------------------- */
           END
           DATE_START = FODATE;
        END
        OLD_PRIORITY = NEW_PRIORITY;
        OLD_MIN_LOS  = NEW_MIN_LOS;
        FODATE = FODATE + 1;
      END
      /* -------------------------------------------------------------------- */
      /* LAST RANGE DATE                                                      */
      /* -------------------------------------------------------------------- */
      IF (OLD_PRIORITY <> -1) THEN
      BEGIN
          MIN_LOS = OLD_MIN_LOS;
          PRIORITY = OLD_PRIORITY;
          DATE_END = FODATE;
          /* -------------------------------------------------------------------- */
          /* LOAD SURCHARGE FROM CONVERSION                                       */
          /* -------------------------------------------------------------------- */
          FOR SELECT SUBSTR(C.DATA_WEB,1,12),SUBSTR(C.DATA_FO,1,4)
             FROM WOTA_CONVERSION C
             WHERE FIELDNAME='ROOMTYPE'
             AND (EXISTS(SELECT * FROM WOTA_CONVERSION_RATE_ALLOTMENT A /* 1/22/2013 */
                               WHERE A.RATECODE=:RATECODE
                               AND A.ROOMTYPE =SUBSTR(C.DATA_FO,1,4)
                               AND A.FLAG_UPLOAD = 1))
             INTO ROOMTYPE_WEB,ROOMTYPE
          DO
          BEGIN
              IF (MIN_LOS <= 0) THEN /* CLOSE OR NOT AVAILABLE */
              BEGIN
                 RATE1 = -1;
                 RATE2 = -1;
                 RATE3 = -1;
                 RATE4 = -1;
                 ADULT = -1;
                 CHILD = -1;
              END
              ELSE /* GET RATE */
              BEGIN
                 SELECT RATE1,RATE2,RATE3,RATE4,ADULT,CHILD
                 FROM FORATE_DETAIL
                 WHERE RATECODE = :RATECODE
                 AND PRIORITY = :PRIORITY
                 AND ROOMTYPE = :ROOMTYPE
                 INTO RATE1,RATE2,RATE3,RATE4,ADULT,CHILD;
              END
              SUSPEND;
          END
          /* -------------------------------------------------------------------- */
      END
  END
END^


ALTER PROCEDURE WOTA_UPLOAD_RI
RETURNS (
    RATECODE_WEB VARCHAR(12),
    RATECODE VARCHAR(12),
    MIN_LOS INTEGER,
    DATE_START DATE,
    DATE_END DATE,
    ROOMTYPE_WEB VARCHAR(12),
    ROOMTYPE VARCHAR(4),
    FLAG_CLOSE INTEGER,
    BOOKING_LIMIT INTEGER)
AS
/* */
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE FTODAY DATE;
DECLARE VARIABLE FODATE DATE;
DECLARE VARIABLE PRIORITY INTEGER;
DECLARE VARIABLE RATE2 INTEGER;
DECLARE VARIABLE OLD_BOOKING_LIMIT INTEGER;
DECLARE VARIABLE NEW_BOOKING_LIMIT INTEGER;
DECLARE VARIABLE NEW_FLAG_CLOSE INTEGER;
DECLARE VARIABLE OLD_FLAG_CLOSE INTEGER;
DECLARE VARIABLE NEW_MIN_LOS INTEGER;
DECLARE VARIABLE OLD_MIN_LOS INTEGER;
/* -------------------------------------------------------------------- */
DECLARE VARIABLE ALLOTMENT_PERCENT DOUBLE PRECISION;
DECLARE VARIABLE ALLOTMENT_COUNT_MIN INTEGER;
DECLARE VARIABLE ALLOTMENT_COUNT_MAX INTEGER;
DECLARE VARIABLE FLAG_ACTIVE_IF_AVAILABLE_GE INTEGER;
DECLARE VARIABLE DAY_COUNT INTEGER;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 1/22/2013 yg di upload hanya rate yang di setujui,                  */
  /*           setup ada di WOTA_CONVERSION_RATE_ALLOTMENT                */
  /*           field FLAG_UPLOAD                                          */
  /* -------------------------------------------------------------------- */
  SELECT UPLOAD_RI_DAYS FROM WOTA_CONFIG WHERE ID = 1
  INTO DAY_COUNT;
  
  FTODAY = 'NOW';
  EXECUTE PROCEDURE SP_DATEONLY(FTODAY) RETURNING_VALUES(FTODAY);
  SDATE = FTODAY;
  EDATE = SDATE + DAY_COUNT;

  FOR SELECT SUBSTR(DATA_WEB,1,12),SUBSTR(DATA_FO,1,12)
      FROM WOTA_CONVERSION
      WHERE FIELDNAME = 'ROOMRATE'
      INTO RATECODE_WEB,RATECODE
  DO
  BEGIN
    FOR SELECT SUBSTR(C.DATA_WEB,1,12),SUBSTR(C.DATA_FO,1,4)
        FROM WOTA_CONVERSION C
        WHERE C.FIELDNAME='ROOMTYPE'
        AND (EXISTS(SELECT * FROM WOTA_CONVERSION_RATE_ALLOTMENT A /* 1/22/2013 */
                               WHERE A.RATECODE=:RATECODE
                               AND A.ROOMTYPE =SUBSTR(C.DATA_FO,1,4)
                               AND A.FLAG_UPLOAD = 1))
        INTO ROOMTYPE_WEB,ROOMTYPE
    DO
    BEGIN
       OLD_BOOKING_LIMIT = -1;
       FODATE = SDATE;
       DATE_START = FODATE;
       
       SELECT ALLOTMENT_PERCENT,ALLOTMENT_COUNT_MIN,
              ALLOTMENT_COUNT_MAX,FLAG_ACTIVE_IF_AVAILABLE_GE
       FROM WOTA_CONVERSION_RATE_ALLOTMENT
       WHERE RATECODE = :RATECODE
       AND ROOMTYPE = :ROOMTYPE
       AND FLAG_UPLOAD = 1
       INTO ALLOTMENT_PERCENT,ALLOTMENT_COUNT_MIN,
            ALLOTMENT_COUNT_MAX,FLAG_ACTIVE_IF_AVAILABLE_GE;
    
       WHILE (FODATE < EDATE) DO
       BEGIN
           /* -------------------------------------------------------------------- */
           /* GET RATE STATUS MINIMUM LENGTH OF STAY                               */
           /* -------------------------------------------------------------------- */
           SELECT RATESTATUS FROM FO_RATE_GETSTATUS(:RATECODE,:FODATE)
           INTO NEW_MIN_LOS;
           IF (NEW_MIN_LOS < 0) THEN NEW_MIN_LOS = 0;
           ELSE NEW_MIN_LOS = 1; /* 5/22/2012 SELALU 1,KARENA ADA UPLOAD TERPISAH */
           /* -------------------------------------------------------------------- */
           /* GET RATE SURCHARGE PRIORITY                                          */
           /* -------------------------------------------------------------------- */
           SELECT PRIORITY FROM FO_RATE_JUR_GET_SURCHARGE (:RATECODE,:FODATE,0,:FODATE,'')
           INTO PRIORITY;
           /* -------------------------------------------------------------------- */
           SELECT RATE2 FROM FORATE_DETAIL
           WHERE RATECODE = :RATECODE
           AND PRIORITY = :PRIORITY
           AND ROOMTYPE = :ROOMTYPE
           INTO RATE2;
           
           IF (RATE2 <= 0) THEN NEW_FLAG_CLOSE = 1;
           ELSE NEW_FLAG_CLOSE = 0;
           
           IF (NEW_FLAG_CLOSE = 1) THEN NEW_BOOKING_LIMIT = 0;
           ELSE
           BEGIN
              SELECT AVAILABLE FROM FORI
              WHERE FODATE=:FODATE
              AND ROOMTYPE=:ROOMTYPE
              INTO NEW_BOOKING_LIMIT;
           END
           /* -------------------------------------------------------------------- */
           /* CALCULATE CONDITION BASE ON SETUP                                    */
           /* -------------------------------------------------------------------- */
           IF (NEW_BOOKING_LIMIT < FLAG_ACTIVE_IF_AVAILABLE_GE) THEN NEW_BOOKING_LIMIT = 0;
           ELSE
           BEGIN
               NEW_BOOKING_LIMIT = NEW_BOOKING_LIMIT * ALLOTMENT_PERCENT / 100;
               IF (NEW_BOOKING_LIMIT > ALLOTMENT_COUNT_MAX) THEN
                  NEW_BOOKING_LIMIT = ALLOTMENT_COUNT_MAX;
                  
               IF (NEW_BOOKING_LIMIT < ALLOTMENT_COUNT_MIN) THEN
                  NEW_BOOKING_LIMIT = 0;
           END
           /* -------------------------------------------------------------------- */
           /* IF MINIMUM LENGTH OF STAY (LOS) < 0                                  */
           /* -------------------------------------------------------------------- */
           IF (NEW_MIN_LOS <= 0) THEN NEW_BOOKING_LIMIT = 0;
           /* -------------------------------------------------------------------- */
           IF ((OLD_BOOKING_LIMIT <> NEW_BOOKING_LIMIT) OR (OLD_MIN_LOS <> NEW_MIN_LOS)) THEN
           BEGIN
              /* -------------------------------------------------------------------- */
              /* IF AVAILABLE CHANGED                                                 */
              /* -------------------------------------------------------------------- */
              IF (OLD_BOOKING_LIMIT <> -1) THEN
              BEGIN
                 FLAG_CLOSE = OLD_FLAG_CLOSE;
                 BOOKING_LIMIT = OLD_BOOKING_LIMIT;
                 DATE_END = FODATE-1;
                 MIN_LOS = OLD_MIN_LOS;
                 SUSPEND;
              END
              DATE_START = FODATE;
           END
           OLD_FLAG_CLOSE    = NEW_FLAG_CLOSE;
           OLD_BOOKING_LIMIT = NEW_BOOKING_LIMIT;
           OLD_MIN_LOS       = NEW_MIN_LOS;
           FODATE = FODATE + 1;
        END /* WHILE (FODATE < EDATE) DO */
        /* -------------------------------------------------------------------- */
        FLAG_CLOSE = OLD_FLAG_CLOSE;
        BOOKING_LIMIT = OLD_BOOKING_LIMIT;
        MIN_LOS = OLD_MIN_LOS;
        DATE_END = FODATE;
        SUSPEND;
        /* -------------------------------------------------------------------- */
    END /* ROOMTYPE */
  END /* RATE */
END^


ALTER PROCEDURE XAR_MUTATION_OLD_CALC(
    SCUSTOMER VARCHAR(6),
    ECUSTOMER VARCHAR(6),
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    OPENING DOUBLE PRECISION,
    VOUCHER DOUBLE PRECISION,
    DEPOSIT DOUBLE PRECISION,
    CASH DOUBLE PRECISION,
    ADJUST DOUBLE PRECISION,
    ENDING DOUBLE PRECISION,
    CUSTTYPE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4))
AS
declare variable sdate date;
declare variable edate date;
declare variable adjust1 double precision;
declare variable xtotal double precision;
declare variable xopendate date;
declare variable xpaydate date;
declare variable xsisa double precision;
declare variable batch integer;
declare variable bank varchar(4);
declare variable outlet varchar(4);
begin

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = 'DINERS';
     eCUSTOMER = 'DINERS';
     REFDATE = '31.07.2005';
  END
  /*
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;
  */
  /* -------------------------------------------------------------------- */
  /* 15 MARET 2011                                                        */
  /* -------------------------------------------------------------------- */
  execute procedure SP_DATE_BOM (refdate) returning_values sDate;
  execute procedure SP_DATE_EOM (refdate) returning_values eDate;
  /*##########################################################################*/
  /* company                                                                  */
  /*##########################################################################*/
  CREDITCARD = 0;
  FOR SELECT C.CUSTOMER, C.NAME, C.CUSTTYPE,
             T.GLACCOUNT, T.GLDEPT, T.GLCOST
  FROM SYSCUSTOMER C
  LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
  WHERE CUSTOMER BETWEEN :SCUSTOMER AND :ECUSTOMER
  INTO :CUSTOMER, NAME, CUSTTYPE, GL_ACCOUNT, GL_DEPT, GL_COST
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung opening                                                         */
    /*========================================================================*/
    SELECT SUM(TOTAL) FROM ARVCH
     WHERE CUSTOMER = :CUSTOMER
       AND OPENDATE < :SDATE
     PLAN (ARVCH INDEX (ARVCH_IDX_CUSTOMER_OPENDATE))
      INTO VOUCHER;

    SELECT SUM(TOTAL-FOREX_GAINLOSS-ADJ_FOREX_TOTAL) FROM ARCASH0 /* 1/3/2012 over paid*/
     WHERE CUSTOMER = :CUSTOMER AND DUEDATE < :SDATE
       AND STATUS IN ('C', 'R', 'L')
      INTO CASH;

    SELECT SUM(ARDEPOS1.TOTAL) FROM ARDEPOS1
     WHERE ARDEPOS1.CUSTOMER = :CUSTOMER AND ARDEPOS1.APPLIEDDATE < :SDATE
       AND ARDEPOS1.STATUS IN ('R','C')
      INTO DEPOSIT;

    SELECT SUM(A.DB-A.CR)
      FROM ARADJ A
     WHERE A.CUSTOMER = :CUSTOMER
       AND A.OPENDATE < :SDATE /* 6/11/2011 TAMBAH STATUS & TIDAK PERLU ARVCH */
       AND STATUS IN ('R','C')
      INTO :ADJUST1;

    SELECT SUM(D.DEBIT-D.CREDIT) FROM ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER AND H.CUSTOMER = :CUSTOMER
    WHERE D.SOURCE = 'A' /* ADJUSTMENT */
      AND D.STATUS = 'C' /* CLOSE, POSTED */
    AND D.FODATE < :SDATE
    INTO ADJUST;

    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;

    opening = voucher - cash + adjust + adjust1 - deposit; /* 6/11/2011 MASUKAN DEPOSIT */
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    voucher = 0;
    cash    = 0;
    adjust  = 0;
    adjust1 = 0;
    deposit = 0;
    select SUM(TOTAL) from ARvch   where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
      into :voucher;

    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
       AND ARdepos1.status IN ('R','C')
      into deposit;

    select sum(total-forex_gainloss-ADJ_FOREX_TOTAL) /* 1/3/2011 over paid */
      from ARcash0 where CUSTOMER = :CUSTOMER
       and DueDate between :sDate and :eDate
       and status in ('C', 'R', 'L')
      into :cash;

    select sum(A.db-A.cr)
      from ARadj A
     where A.CUSTOMER = :CUSTOMER
       and A.OpenDate between :sDate and :eDate
       AND status IN ('R','C') /* 6/11/2011 TAMBAH STATUS & TIDAK PERLU ARVCH */
      into :adjust1;

    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER and H.CUSTOMER = :CUSTOMER
    where D.source = 'A' /* ADJUSTMENT */
    and D.status = 'C' /* CLOSE, POSTED */
    and D.FODATE between :sDate and :eDate
    into adjust;

    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1; /* 6/11/2011 TADINYA ADA DEPOSIT, DIPINDAH */
    ending = opening + voucher - cash; /* + adjust - deposit; */
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0) or (deposit <> 0)) then /* 6/11/2011 TAMBAH DEPOSIT <> 0 */
       suspend;
  end
  /*##########################################################################*/
  /* credit card                                                              */
  /*##########################################################################*/
  adjust = 0;
  CREDITCARD = 1;
  CUSTTYPE = 'CARD';
  FOR SELECT CREDITCARD, NAME, GL_AR_ACCOUNT, GL_AR_DEPT, GL_AR_COST
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :ECUSTOMER
      INTO :CUSTOMER, :NAME, GL_ACCOUNT, GL_DEPT, GL_COST
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    opening = 0;
    voucher = 0;
    cash = 0;
    ending = 0;
    deposit = 0;
    FOR SELECT OPENDATE, TOTAL, PAY_DATE, BATCH, BANK, OUTLET
        FROM AR_CARD_JUR
        WHERE CREDITCARD = :customer
        AND OPENDATE <= :EDATE
        PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_CUSTOMER))  /* no alias for fb 2.1 */
        INTO xOpenDate, xTotal, xPayDate, BATCH, BANK, OUTLET
        DO BEGIN
           IF (xTotal IS NULL) THEN xTotal = 0;
           xSisa = xTotal;
           if (xOpenDate BETWEEN :SDATE AND :EDATE) then
              Voucher = Voucher + xTotal;
           XPayDate = NULL;
           SELECT PAY_DATE FROM AR_CARD_BATCH WHERE BANK = :BANK AND OUTLET = :OUTLET AND BATCH = :BATCH
           INTO xPayDate;

           IF (xPayDate > EDATE) THEN XPayDate = NULL;
           if (xPayDate is not null) then
           begin
              if (xPayDate BETWEEN :SDATE AND :EDATE) then
                 Cash = Cash + xTotal;
              if (xPayDate <= :edate) then xSisa = 0;
           end
           ending = ending + xSisa;
        END

    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    opening  =  ending - voucher + cash;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;
  end
end^


ALTER PROCEDURE XFO_RPT_GETPACKAGE_CHG(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CATEGORY VARCHAR(6),
    NAME VARCHAR(40),
    PAX INTEGER,
    PACKAGE DOUBLE PRECISION)
AS
BEGIN
  /* -------------------------------------------------------------------- */
  /* GET CHARGE MANUAL PACKAGE                                            */
  /* -------------------------------------------------------------------- */
    FOR
        SELECT
            JR.CATEGORY,
            CT.NAME,
            COUNT(*),
            SUM(JR.DEBIT)
            FROM FOGUEST_JUR JR
            LEFT JOIN FOCATEGORY CT ON CT.CATEGORY =JR.CATEGORY
            WHERE JR.JURCODE = 'CHG' AND JR.HIDDEN=2 AND CT.CLASS=3
            AND JR.FODATE BETWEEN :SDATE AND :EDATE
            GROUP BY JR.CATEGORY, CT.NAME

      UNION

        SELECT
            JR.CATEGORY,
            CT.NAME,
            COUNT(*),
            SUM(JR.DEBIT)
            FROM FO_HIST_JUR JR
            LEFT JOIN FOCATEGORY CT ON CT.CATEGORY =JR.CATEGORY
            WHERE JR.JURCODE = 'CHG' AND JR.HIDDEN=2 AND CT.CLASS=3
            AND JR.FODATE BETWEEN :SDATE AND :EDATE
            GROUP BY JR.CATEGORY, CT.NAME

      INTO
            :CATEGORY,
            :NAME,
            :PAX,
            :PACKAGE
    DO
    BEGIN
        IF (CATEGORY IS NULL) THEN CATEGORY = '';
        IF (NAME IS NULL) THEN NAME = '';
        IF (PAX IS NULL) THEN PAX = 0;
        IF (PACKAGE IS NULL) THEN PACKAGE = 0;
        SUSPEND;
    END
END^


ALTER PROCEDURE XFO_RPT_GETPACKAGE_NA(
    SDATE DATE,
    EDATE DATE,
    CATEGORY VARCHAR(6))
RETURNS (
    PAX INTEGER,
    PACKAGE DOUBLE PRECISION)
AS
BEGIN
  /* -------------------------------------------------------------------- */
  /* GET NA ONLY PACKAGE ALLOWANCE                                        */
  /* -------------------------------------------------------------------- */
    FOR
        SELECT
            SUM(GS.PAX),
            SUM(JR.DEBIT/1.21)
            FROM FOGUEST_JUR JR
            LEFT JOIN FOCATEGORY CT ON CT.CATEGORY =JR.CATEGORY
            LEFT JOIN FOPACKAGE PK ON PK.PACKAGE =JR.PACKAGE_CODE
            LEFT JOIN FOGUEST GS ON GS.FOLIO = JR.FOLIO_ORIGINAL
            WHERE JR.PACKAGE_CODE NOT IN ('RATE','ATAX','COM-','COM+','')
            AND JR.JURCODE IN ('NA','MRT') AND JR.PACKAGE_ALLOWANCE ='1'
            AND JR.FODATE BETWEEN :SDATE AND :EDATE
            AND JR.CATEGORY=:CATEGORY

        UNION

        SELECT
            SUM(GS.PAX),
            SUM(JR.DEBIT/1.21)
            FROM FO_HIST_JUR JR
            LEFT JOIN FOCATEGORY CT ON CT.CATEGORY =JR.CATEGORY
            LEFT JOIN FOPACKAGE PK ON PK.PACKAGE =JR.PACKAGE_CODE
            LEFT JOIN FOGUEST GS ON GS.FOLIO = JR.FOLIO_ORIGINAL
            WHERE JR.PACKAGE_CODE NOT IN ('RATE','ATAX','COM-','COM+','')
            AND JR.JURCODE IN ('NA','MRT') AND JR.PACKAGE_ALLOWANCE ='1'
            AND JR.FODATE BETWEEN :SDATE AND :EDATE
            AND JR.CATEGORY=:CATEGORY
            GROUP BY GS.PAX

        INTO
            :PAX,
            :PACKAGE
    DO
    BEGIN
        IF (PAX IS NULL) THEN PAX = 0;
        IF (PACKAGE IS NULL) THEN PACKAGE = 0;
        SUSPEND;
    END
END^


ALTER PROCEDURE XFO_RPT_GETPACKAGE_TODAY(
    FODATE DATE)
RETURNS (
    CATEGORY VARCHAR(6),
    NAME VARCHAR(40),
    TDY_PAX INTEGER,
    TDY_PACKAGE DOUBLE PRECISION,
    MTD_PAX INTEGER,
    MTD_PACKAGE DOUBLE PRECISION,
    YTD_PAX INTEGER,
    YTD_PACKAGE DOUBLE PRECISION)
AS
declare variable BOM date;
declare variable BOY date;
BEGIN
  IF (FODATE IS NULL) THEN
  SELECT FOSYSDATE-1 FROM FOSYSPARAM INTO :FODATE;

  EXECUTE PROCEDURE SP_BEGINOFMONTH(FODATE) RETURNING_VALUES (:BOM);
  EXECUTE PROCEDURE SP_BEGINOFYEAR(FODATE) RETURNING_VALUES (:BOY);

  FOR
    SELECT CT.CATEGORY, CT.NAME FROM FOPACKAGE PK
        LEFT JOIN FOCATEGORY CT ON CT.CATEGORY =PK.CATEGORY
        WHERE PK.PACKAGE_TYPE IN ('MBF','MLC','MDN','MSP','MCB')
        GROUP BY CT.CATEGORY, CT.NAME
        ORDER BY CT.CATEGORY
    INTO
      :CATEGORY,
      :NAME
  DO
  BEGIN
    /* ------------------------------------------------------------------ */
    /* GET TODAY, MTD, YTD NA PACKAGE                                     */
    /* ------------------------------------------------------------------ */
    EXECUTE PROCEDURE
    XFO_RPT_GETPACKAGE_NA(:FODATE, :FODATE, :CATEGORY)
    RETURNING_VALUES (:TDY_PAX, :TDY_PACKAGE);

    EXECUTE PROCEDURE
    XFO_RPT_GETPACKAGE_NA(:BOM, :FODATE, :CATEGORY)
    RETURNING_VALUES (:MTD_PAX, :MTD_PACKAGE);

    EXECUTE PROCEDURE
    XFO_RPT_GETPACKAGE_NA(:BOY, :FODATE, :CATEGORY)
    RETURNING_VALUES (:YTD_PAX, :YTD_PACKAGE);

    SUSPEND;
  END

    /* ------------------------------------------------------------------ */
    /* GET TODAY, MTD, YTD MANUAL PACKAGE                                 */
    /* ------------------------------------------------------------------ */
    EXECUTE PROCEDURE
    XFO_RPT_GETPACKAGE_CHG(:FODATE, :FODATE)
    RETURNING_VALUES (:CATEGORY, :NAME, :TDY_PAX, :TDY_PACKAGE);

    EXECUTE PROCEDURE
    XFO_RPT_GETPACKAGE_CHG(:BOM, :FODATE)
    RETURNING_VALUES (:CATEGORY, :NAME, :MTD_PAX, :MTD_PACKAGE);

    EXECUTE PROCEDURE
    XFO_RPT_GETPACKAGE_CHG(:BOY, :FODATE)
    RETURNING_VALUES (:CATEGORY, :NAME, :YTD_PAX, :YTD_PACKAGE);

    BEGIN
        SUSPEND;
    END
        IF (CATEGORY IS NULL) THEN
        begin
             CATEGORY = '';
        end

END^


ALTER PROCEDURE XFO_RPT_HIST_INHOUSE(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FOLIO INTEGER,
    DATECI DATE,
    DATECO DATE,
    GUESTNAME VARCHAR(80),
    COMPANY VARCHAR(6),
    COMPANYNAME VARCHAR(40),
    FOLIO_MASTER INTEGER,
    GROUPNUMBER INTEGER,
    FOLIOTYPE CHAR(1),
    FOLIOSTATUS CHAR(1),
    FOLIOSTATUS_SHARE CHAR(1),
    ROOMTYPE VARCHAR(4),
    RATECODE VARCHAR(12),
    RATEDISCOUNT NUMERIC(15,4),
    ROOMRATE DOUBLE PRECISION,
    HISTORY INTEGER,
    ST_RESV_SOURCE VARCHAR(4),
    ST_NATIONALITY VARCHAR(4),
    ST_MARKETSEGMENT VARCHAR(4),
    ST_ORIGINAREA VARCHAR(4),
    ROOMNIGHT INTEGER,
    PAX SMALLINT,
    CHILD SMALLINT,
    ROOM VARCHAR(8),
    PACKAGE DOUBLE PRECISION,
    RATE_DISCOUNT DOUBLE PRECISION,
    ROOMREVENUE DOUBLE PRECISION,
    DAYUSE_REVENUE DOUBLE PRECISION,
    RACKRATE DOUBLE PRECISION,
    DATECI_ACTUAL DATE,
    DATECO_ACTUAL DATE,
    HOUR_CI INTEGER,
    HOUR_CO INTEGER,
    FLAG_WALKIN INTEGER,
    RELATION_DOCTYPE INTEGER,
    HIST_NO_STAY INTEGER,
    HIST_NO_NIGHT INTEGER,
    PAYING_TYPE INTEGER,
    PAYING_NAME VARCHAR(20),
    HIST_DATE_FIRSTCI DATE,
    HIST_DATE_LASTCO DATE,
    HIST_TOTAL_REVENUE DOUBLE PRECISION,
    HIST_TOTAL_REVENUE_ROOM DOUBLE PRECISION)
AS
BEGIN
  if (SDATE IS NULL) then
     SELECT FOSYSDATE-2 FROM FOSYSPARAM INTO :SDATE;
  FOR
    SELECT LOG.FOLIO,
           LOG.FOLIO_MASTER,
           LOG.GROUPNUMBER,
           LOG.FOLIOTYPE,
           LOG.FOLIOSTATUS,
           LOG.FOLIOSTATUS_SHARE,
           LOG.ROOMTYPE,
           LOG.RATECODE,
           LOG.RATEDISCOUNT,
           LOG.ROOMRATE,
           LOG.HISTORY,
           LOG.ST_RESV_SOURCE,
           LOG.ST_NATIONALITY,
           LOG.ST_MARKETSEGMENT,
           LOG.ST_ORIGINAREA,
           LOG.PAX,
           LOG.CHILD,
           LOG.ROOM,
           LOG.PACKAGE,
           LOG.RATE_DISCOUNT,
           LOG.ROOMREVENUE,
           LOG.DAYUSE_REVENUE1 + LOG.DAYUSE_REVENUE2,
           LOG.RACKRATE
    FROM FOSTAT_LOG LOG
    WHERE LOG.FOLIOTYPE = 'P'
    AND LOG.FOLIOSTATUS = 'I'
    AND LOG.FODATE BETWEEN :SDATE and :EDATE
    ORDER BY LOG.ROOM
    INTO
      :FOLIO,
      :FOLIO_MASTER,
      :GROUPNUMBER,
      :FOLIOTYPE,
      :FOLIOSTATUS,
      :FOLIOSTATUS_SHARE,
      :ROOMTYPE,
      :RATECODE,
      :RATEDISCOUNT,
      :ROOMRATE,
      :HISTORY,
      :ST_RESV_SOURCE,
      :ST_NATIONALITY,
      :ST_MARKETSEGMENT,
      :ST_ORIGINAREA,
      :PAX,
      :CHILD,
      :ROOM,
      :PACKAGE,
      :RATE_DISCOUNT,
      :ROOMREVENUE,
      :DAYUSE_REVENUE,
      :RACKRATE
  DO
  BEGIN
    SELECT GUESTNAME, COMPANYNAME, DATECI, DATECO, WALKIN, COMPANY, RELATION_DOCTYPE FROM fo_rpt_hist_guestname(:FOLIO)
    INTO :GUESTNAME, :COMPANYNAME, :DATECI, :DATECO, FLAG_WALKIN, COMPANY, RELATION_DOCTYPE;
    
    DATECO_ACTUAL = NULL;
    DATECI_ACTUAL = NULL;
    
    SELECT DATECI_ACTUAL, DATECO_ACTUAL FROM FOGUEST WHERE FOLIO = :FOLIO
    INTO DATECI_ACTUAL, DATECO_ACTUAL;

    if (DATECI_ACTUAL IS NULL) then
       SELECT DATECI_ACTUAL, DATECO_ACTUAL FROM FO_HIST_STAY WHERE FOLIO = :FOLIO
       INTO DATECI_ACTUAL, DATECO_ACTUAL;
       
    HOUR_CI = EXTRACT(HOUR FROM DATECI_ACTUAL);
    HOUR_CO = EXTRACT(HOUR FROM DATECO_ACTUAL);
        
    ROOMNIGHT = DATECO-DATECI;

    /* ---------------------------------------------------------------- */
    /* 10 JUN 2008                                                      */
    /* ---------------------------------------------------------------- */
    IF (EXISTS(SELECT * FROM FO_HIST_GUEST WHERE HISTORY = :HISTORY)) THEN
    BEGIN
       /* -------------------------------------------------------------------- */
       /* 25 JUN 2010                                                          */
       /* -------------------------------------------------------------------- */
       SELECT DATE_FIRSTCI, DATE_LASTCO,
              TOTAL_REVENUE, TOTAL_REVENUE_ROOM FROM FO_HIST_GUEST
       WHERE HISTORY = :HISTORY
       INTO HIST_DATE_FIRSTCI,  HIST_DATE_LASTCO, HIST_TOTAL_REVENUE, HIST_TOTAL_REVENUE_ROOM;
       
       /* -------------------------------------------------------------------- */

       SELECT COUNT(*),  SUM(ROOMNIGHT) FROM FO_HIST_STAY
       WHERE HISTORY = :HISTORY
       AND DATECO <= :HIST_DATE_LASTCO
       INTO HIST_NO_STAY,  HIST_NO_NIGHT;
       IF (HIST_NO_STAY = 0) THEN HIST_NO_NIGHT = 0;
    END
    ELSE
    BEGIN
       HIST_TOTAL_REVENUE = 0;
       HIST_TOTAL_REVENUE_ROOM = 0;
       HIST_NO_STAY = 0;
       HIST_NO_NIGHT = 0;
       HIST_DATE_FIRSTCI = NULL;
       HIST_DATE_LASTCO = NULL;
    END
    /* ---------------------------------------------------------------- */
    /* END OF 10 JUN 2008                                               */
    /* ---------------------------------------------------------------- */
    /* 14 NOV 2008                                                      */
    /* ---------------------------------------------------------------- */
    IF (RATECODE = 'HU') THEN
    BEGIN
       PAYING_TYPE = 2;
       PAYING_NAME = 'House Use';
    END
    ELSE IF (RATECODE LIKE 'COMPL%') THEN
    BEGIN
       PAYING_TYPE = 1;
       PAYING_NAME = 'Compliment';
    END
    ELSE
    BEGIN
       PAYING_TYPE = 0;
       PAYING_NAME = 'Paying Room';
    END
    /* ---------------------------------------------------------------- */
    /* END OF 14 NOV 2008                                               */
    /* ---------------------------------------------------------------- */
    
    SUSPEND;
  END
END^


ALTER PROCEDURE XFO_STAT_TODAY_SEGMENT_SIMPLE(
    FODATE DATE)
RETURNS (
    PERIOD DATE,
    LISTINDEX INTEGER,
    ST_MARKETSEGMENT VARCHAR(4),
    NAME VARCHAR(40),
    GRPSEGMENT VARCHAR(2),
    GROUPNAME VARCHAR(40),
    NIGHT INTEGER,
    NIGHT_PERCENT DOUBLE PRECISION,
    COMPLIMENT INTEGER,
    PAYING INTEGER,
    PAYING_PERCENT DOUBLE PRECISION,
    PAX INTEGER,
    DAYUSE INTEGER,
    ROOMRATE DOUBLE PRECISION,
    AVG_ROOMRATE DOUBLE PRECISION,
    ROOMREVENUE DOUBLE PRECISION,
    AVG_ROOMREVENUE DOUBLE PRECISION,
    MTD_NIGHT INTEGER,
    MTD_NIGHT_PERCENT DOUBLE PRECISION,
    MTD_COMPLIMENT INTEGER,
    MTD_PAYING INTEGER,
    MTD_PAYING_PERCENT DOUBLE PRECISION,
    MTD_PAX INTEGER,
    MTD_DAYUSE INTEGER,
    MTD_ROOMRATE DOUBLE PRECISION,
    MTD_AVG_ROOMRATE DOUBLE PRECISION,
    MTD_ROOMREVENUE DOUBLE PRECISION,
    MTD_AVG_ROOMREVENUE DOUBLE PRECISION,
    YTD_NIGHT INTEGER,
    YTD_NIGHT_PERCENT DOUBLE PRECISION,
    YTD_COMPLIMENT INTEGER,
    YTD_PAYING INTEGER,
    YTD_PAYING_PERCENT DOUBLE PRECISION,
    YTD_DAYUSE INTEGER,
    YTD_PAX INTEGER,
    YTD_ROOMRATE DOUBLE PRECISION,
    YTD_AVG_ROOMRATE DOUBLE PRECISION,
    YTD_ROOMREVENUE DOUBLE PRECISION,
    YTD_AVG_ROOMREVENUE DOUBLE PRECISION,
    TOTAL_AVG_ROOMREVENUE DOUBLE PRECISION,
    TOTAL_AVG_ROOMREVENUE_MTD DOUBLE PRECISION,
    TOTAL_AVG_ROOMREVENUE_YTD DOUBLE PRECISION)
AS
declare variable BOM date;
declare variable EOM date;
declare variable BOY date;
declare variable TOT_TODAY integer;
declare variable TOT_MTD integer;
declare variable TOT_YTD integer;
declare variable TOT_PAYING_TODAY integer;
declare variable TOT_PAYING_MTD integer;
declare variable TOT_PAYING_YTD integer;
declare variable REV_TOTAL double precision;
declare variable REV_TOTAL_MTD double precision;
declare variable REV_TOTAL_YTD double precision;
BEGIN
  if (FODATE IS NULL) then
     SELECT FOSYSDATE-1 FROM FOSYSPARAM INTO :FODATE;

  EXECUTE procedure sp_beginofmonth(FODATE) returning_values (:BOM);
  EXECUTE procedure SP_ENDOFMONTH(FODATE) returning_values (:EOM);
  EXECUTE procedure sp_beginofyear(FODATE) returning_values (:BOY);

  PERIOD = FODATE;


  /* ---------------------------------------------------------------- */
  /* CALCULATE TOTAL                                                  */
  /* ---------------------------------------------------------------- */
  SELECT SUM(FLAG_NO_HU*NIGHT), SUM(CHARGE_CLASS1) FROM fostat_log ST
  WHERE ST.FODATE = :FODATE
  INTO TOT_TODAY, REV_TOTAL;

  SELECT SUM(FLAG_NO_HU*NIGHT), SUM(CHARGE_CLASS1) FROM fostat_log ST
  WHERE FODATE BETWEEN :BOM AND :FODATE
  INTO TOT_MTD, REV_TOTAL_MTD;


  SELECT SUM(FLAG_NO_HU*NIGHT), SUM(CHARGE_CLASS1) FROM fostat_log ST
  WHERE ST.FODATE BETWEEN :BOY AND :FODATE
  INTO TOT_YTD, REV_TOTAL_YTD;

  IF (TOT_TODAY IS NULL) THEN
  BEGIN
     TOT_TODAY = 0;
     REV_TOTAL = 0;
  END
  IF (TOT_MTD IS NULL)   THEN
  BEGIN
     TOT_MTD = 0;
     REV_TOTAL_MTD = 0;
  END
  IF (TOT_YTD IS NULL)   THEN
  BEGIN
     TOT_YTD = 0;
     REV_TOTAL_YTD = 0;
  END



  /* ---------------------------------------------------------------- */
  /* PAYING ROOM                                                      */
  /* ---------------------------------------------------------------- */
  SELECT SUM(FLAG_NO_HU*NIGHT) FROM fostat_log ST
  WHERE ST.FODATE = :FODATE
  AND (ST.RATECODE NOT LIKE 'COMPL%')
  INTO TOT_PAYING_TODAY;

  SELECT SUM(FLAG_NO_HU*NIGHT) FROM fostat_log ST
  WHERE FODATE BETWEEN :BOM AND :FODATE
  AND (ST.RATECODE NOT LIKE 'COMPL%')
  INTO TOT_PAYING_MTD;


  SELECT SUM(FLAG_NO_HU*NIGHT) FROM fostat_log ST
  WHERE ST.FODATE BETWEEN :BOY AND :FODATE
  AND (ST.RATECODE NOT LIKE 'COMPL%')
  INTO TOT_PAYING_YTD;

  IF (TOT_PAYING_TODAY IS NULL) THEN TOT_PAYING_TODAY = 0;
  IF (TOT_PAYING_MTD IS NULL)   THEN TOT_PAYING_MTD = 0;
  IF (TOT_PAYING_YTD IS NULL)   THEN TOT_PAYING_YTD = 0;



  /* ---------------------------------------------------------------- */
  /* AVERAGE ROOM RATE                                                */
  /* ---------------------------------------------------------------- */

  IF (TOT_PAYING_TODAY = 0) THEN TOTAL_AVG_ROOMREVENUE = 0;
  ELSE TOTAL_AVG_ROOMREVENUE = REV_TOTAL/TOT_PAYING_TODAY;


  IF (TOT_PAYING_MTD = 0) THEN TOTAL_AVG_ROOMREVENUE_MTD = 0;
  ELSE TOTAL_AVG_ROOMREVENUE_MTD = REV_TOTAL_MTD/TOT_PAYING_MTD;

  IF (TOT_PAYING_YTD = 0) THEN TOTAL_AVG_ROOMREVENUE_YTD = 0;
  ELSE TOTAL_AVG_ROOMREVENUE_YTD = REV_TOTAL_YTD/TOT_PAYING_YTD;




  /* ---------------------------------------------------------------- */
  /* TODAY                                                            */
  /* ---------------------------------------------------------------- */
  FOR SELECT SEG.LISTINDEX, SEG.CODE, SEG.NAME, G.GRPSEGMENT, G.NAME
    FROM fost_segment SEG
    LEFT JOIN fost_segmentgrp G ON G.GRPSEGMENT = SEG.GRPSEGMENT
    ORDER BY G.GRPSEGMENT, SEG.LISTINDEX
    INTO
      :LISTINDEX,
      :ST_MARKETSEGMENT,    :NAME,
      :GRPSEGMENT,          :GROUPNAME
  DO
  BEGIN
    NIGHT = NULL;
    SELECT SUM(FLAG_NO_HU*NIGHT), SUM(FLAG_NO_HU*PAX), SUM(ROOMRATE), SUM(CHARGE_CLASS1)
    FROM fostat_log ST
    WHERE ST.ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND ST.FODATE = :FODATE
    AND ST.FOLIOSTATUS NOT IN ('X','N','O')
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO :NIGHT, :PAX, :ROOMRATE, ROOMREVENUE;

    IF (NIGHT IS NULL) THEN
    BEGIN
      NIGHT         = 0;
      PAX           = 0;
      ROOMRATE      = 0;
      ROOMREVENUE   = 0;
    END

    SELECT SUM(FLAG_NO_HU*NIGHT)
    FROM fostat_log ST
    WHERE ST.ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND ST.FODATE = :FODATE
    AND (ST.RATECODE LIKE 'COMPL%')
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO COMPLIMENT;

    select sum(flag_dayuse) from fostat_log ST
    WHERE ST.ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND ST.FODATE = :FODATE
    and flag_dayuse ='1'
    and ST.foliotype ='P'
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO DAYUSE;
    IF (COMPLIMENT IS NULL) THEN COMPLIMENT = 0;
    IF (DAYUSE IS NULL) THEN DAYUSE = 0;

    PAYING = NIGHT - COMPLIMENT + DAYUSE;


    IF (PAYING = 0) THEN AVG_ROOMRATE = 0;
    ELSE AVG_ROOMRATE = ROOMRATE/PAYING;

    IF (PAYING = 0) THEN AVG_ROOMREVENUE = 0;
    ELSE AVG_ROOMREVENUE = ROOMREVENUE/PAYING;

    IF (TOT_TODAY = 0) THEN NIGHT_PERCENT = 0;
    ELSE NIGHT_PERCENT = NIGHT/TOT_TODAY * 100;

    IF (TOT_PAYING_TODAY = 0) THEN PAYING_PERCENT = 0;
    ELSE PAYING_PERCENT = PAYING/TOT_PAYING_TODAY * 100;
    /* ---------------------------------------------------------------- */
    /* MONTH TO DATE                                                    */
    /* ---------------------------------------------------------------- */

    SELECT SUM(FLAG_NO_HU*NIGHT), SUM(FLAG_NO_HU*PAX), SUM(ROOMRATE), SUM(CHARGE_CLASS1)
    FROM FOSTAT_LOG ST
    WHERE ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND FODATE BETWEEN :BOM AND :FODATE
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO MTD_NIGHT, MTD_PAX, MTD_ROOMRATE, MTD_ROOMREVENUE;

    IF (MTD_NIGHT is NULL) THEN
    BEGIN
      MTD_NIGHT         = 0;
      MTD_PAX           = 0;
      MTD_ROOMRATE      = 0;
      MTD_ROOMREVENUE   = 0;
    END

    SELECT SUM(FLAG_NO_HU*NIGHT)
    FROM fostat_log ST
    WHERE ST.ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND FODATE BETWEEN :BOM AND :FODATE
    AND (ST.RATECODE LIKE 'COMPL%')
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO MTD_COMPLIMENT;

    select sum(flag_dayuse)
    from fostat_log ST
    WHERE ST.ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND ST.FODATE = :FODATE
    and flag_dayuse ='1'
    and ST.foliotype ='P'
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO MTD_DAYUSE;

    IF (MTD_COMPLIMENT IS NULL) THEN MTD_COMPLIMENT = 0;
    IF (MTD_DAYUSE IS NULL) THEN MTD_DAYUSE = 0;

    MTD_PAYING = MTD_NIGHT - MTD_COMPLIMENT + MTD_DAYUSE;

    IF (MTD_PAYING = 0) THEN MTD_AVG_ROOMRATE = 0;
    ELSE MTD_AVG_ROOMRATE = MTD_ROOMRATE/MTD_PAYING;

    IF (MTD_PAYING = 0) THEN MTD_AVG_ROOMREVENUE = 0;
    ELSE MTD_AVG_ROOMREVENUE = MTD_ROOMREVENUE/MTD_PAYING;

    IF (TOT_MTD = 0) THEN MTD_NIGHT_PERCENT = 0;
    ELSE MTD_NIGHT_PERCENT = MTD_NIGHT/TOT_MTD * 100;

    IF (TOT_PAYING_MTD = 0) THEN MTD_PAYING_PERCENT = 0;
    ELSE MTD_PAYING_PERCENT = PAYING/TOT_PAYING_MTD * 100;
    /* ---------------------------------------------------------------- */
    /* YEAR TO DATE                                                     */
    /* ---------------------------------------------------------------- */

    SELECT SUM(FLAG_NO_HU*NIGHT), SUM(FLAG_NO_HU*PAX), SUM(ROOMRATE), SUM(CHARGE_CLASS1)
    FROM FOSTAT_LOG ST
    WHERE ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND FODATE BETWEEN :BOY AND :FODATE
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO YTD_NIGHT, YTD_PAX, YTD_ROOMRATE, YTD_ROOMREVENUE;


    IF (YTD_NIGHT is NULL) THEN
    BEGIN
      YTD_NIGHT         = 0;
      YTD_PAX           = 0;
      YTD_ROOMRATE      = 0;
      YTD_ROOMREVENUE   = 0;
    END

    SELECT SUM(FLAG_NO_HU*NIGHT)
    FROM fostat_log ST
    WHERE ST.ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND FODATE BETWEEN :BOY AND :FODATE
    AND (ST.RATECODE LIKE 'COMPL%')
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO YTD_COMPLIMENT;

    select sum(flag_dayuse) from fostat_log ST
    WHERE ST.ST_MARKETSEGMENT = :ST_MARKETSEGMENT
    AND ST.FODATE = :FODATE
    and flag_dayuse ='1'
    and ST.foliotype ='P'
    PLAN (ST INDEX (FOSTAT_LOG_IDX_SEGMENT))
    INTO YTD_DAYUSE;

    IF (YTD_COMPLIMENT IS NULL) THEN YTD_COMPLIMENT = 0;
    IF (YTD_DAYUSE IS NULL) THEN YTD_DAYUSE = 0;

    YTD_PAYING = YTD_NIGHT - YTD_COMPLIMENT + YTD_DAYUSE;

    IF (YTD_PAYING = 0) THEN YTD_AVG_ROOMRATE = 0;
    ELSE YTD_AVG_ROOMRATE = YTD_ROOMRATE/YTD_PAYING;

    IF (YTD_PAYING = 0) THEN YTD_AVG_ROOMREVENUE = 0;
    ELSE YTD_AVG_ROOMREVENUE = YTD_ROOMREVENUE/YTD_PAYING;

    IF (TOT_YTD = 0) THEN YTD_NIGHT_PERCENT = 0;
    ELSE YTD_NIGHT_PERCENT = YTD_NIGHT/TOT_YTD * 100;


    IF (TOT_PAYING_YTD = 0) THEN YTD_PAYING_PERCENT = 0;
    ELSE YTD_PAYING_PERCENT = PAYING/TOT_PAYING_YTD * 100;
    SUSPEND;
  END
END^


ALTER PROCEDURE XRPT_FO_NA_PREPOSTING(
    SDATE DATE)
RETURNS (
    GUESTNAME VARCHAR(80),
    COMPANYNAME VARCHAR(40),
    GROUPNUMBER INTEGER,
    TRANS_ID INTEGER,
    FOLIO INTEGER,
    FOLIO_ORIGINAL INTEGER,
    ROOM VARCHAR(8),
    RATECODE VARCHAR(12),
    ROOMTYPE VARCHAR(4),
    PAX INTEGER,
    CHILD INTEGER,
    DATECI DATE,
    DATECO DATE,
    FODATE DATE,
    CATEGORY VARCHAR(4),
    CATEGORYNAME VARCHAR(40),
    REMARK VARCHAR(40),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    NETT DOUBLE PRECISION,
    CURRENCY VARCHAR(4),
    FOREX DOUBLE PRECISION,
    JURCODE VARCHAR(3),
    REFERENCE VARCHAR(20),
    HIDDEN SMALLINT,
    LISTINDEX INTEGER,
    ROOM_COUNTER INTEGER)
AS
declare variable AFOLIO integer;
declare variable COUNTER integer;
BEGIN

  LISTINDEX = 1;

  FOR SELECT GS.FOLIO, GS.COMPANYNAME, GS.GUESTNAME, GS.ROOMTYPE, GS.RATECODE,
             GS.PAX, GS.CHILD, GS.ROOM, GS.DATECI, GS.DATECO, GS.GROUPNUMBER
      FROM FO_RPT_HIST_INHOUSE(:SDATE) GS
      WHERE FOLIOTYPE = 'P'
      AND FOLIOSTATUS = 'I'
      AND FOLIOSTATUS_SHARE = 'M'
      ORDER BY GS.ROOM
      INTO :AFOLIO, :COMPANYNAME, :GUESTNAME, :ROOMTYPE, :RATECODE, :PAX,
           :CHILD,:ROOM, :DATECI, :DATECO, :GROUPNUMBER

  DO BEGIN
     COUNTER = 0;
     FOR
        SELECT TRANS_ID, HIDDEN, CATEGORY, FOLIO, FODATE,  REMARK, DEBIT, CREDIT, CURRENCY,
               FOREX, JURCODE, REFERENCE, FOLIO_ORIGINAL
          FROM FOGUEST_JUR
          WHERE FOLIO_ORIGINAL = :AFOLIO
          AND FODATE = :SDATE
          AND JURCODE IN ('MRT','NA')

          UNION

          SELECT TRANS_ID, HIDDEN, CATEGORY, FOLIO, FODATE, REMARK, DEBIT, CREDIT, CURRENCY,
                 FOREX, JURCODE, REFERENCE, FOLIO_ORIGINAL
          FROM FO_HIST_JUR
          WHERE FOLIO_ORIGINAL = :AFOLIO
          AND FODATE = :SDATE
          AND JURCODE IN ('MRT','NA')

          INTO TRANS_ID, HIDDEN, CATEGORY, FOLIO, FODATE, REMARK, DEBIT, CREDIT, CURRENCY,
               FOREX, JURCODE, REFERENCE, FOLIO_ORIGINAL
          
      DO
      BEGIN
         SELECT NAME FROM FOCATEGORY WHERE CATEGORY = :CATEGORY
         INTO :CATEGORYNAME;
         NETT = DEBIT-CREDIT;
         ROOM_COUNTER = 1;
         IF (COUNTER <> 0) THEN
         BEGIN
            ROOM_COUNTER = 0;
            PAX = 0;
         END
         COUNTER = COUNTER + 1;
         SUSPEND;
         
      END /* END JOURNAL */

      IF (COUNTER = 0) THEN /* TIDAK ADA POSTING, UNTUK HU & COMPLIMENT*/
      BEGIN
         DEBIT  = 0;
         CREDIT = 0;
         NETT   = 0;
         SELECT FOLIO, GUESTNAME, ROOM, RATECODE,  ROOMTYPE,
                DATECI, DATECO, PAX
         FROM FO_RPT_HIST_INHOUSE(:SDATE)
         WHERE FOLIO = :AFOLIO
         AND FOLIOTYPE ='P'
         AND FOLIOSTATUS ='I'
         AND FOLIOSTATUS_SHARE = 'M'
         INTO FOLIO, GUESTNAME, ROOM, RATECODE,  ROOMTYPE,
              DATECI, DATECO, PAX;

         HIDDEN         = 0;
         ROOM_COUNTER   = 1;
         CATEGORYNAME   = '';
         REFERENCE      = 'No Transaction';
         CATEGORY       = '';
         REMARK         = '';
         FOLIO_ORIGINAL = FOLIO ;
         SUSPEND;
      END
      LISTINDEX = LISTINDEX + 1;
  END /* GUEST */

END^


ALTER PROCEDURE XRPT_IH_RBF_RO
RETURNS (
    SFOLIO INTEGER,
    RESV_EMAIL VARCHAR(80),
    ST_NATIONALITY VARCHAR(4),
    GUESTNAME VARCHAR(80),
    FIRSTNAME VARCHAR(40),
    LASTNAME VARCHAR(40),
    TITLE VARCHAR(6),
    DATECI DATE,
    DATECO DATE,
    NIGHTS INTEGER,
    NO_OF_PERSON INTEGER,
    NO_OF_CHILD INTEGER,
    ROOMTYPE VARCHAR(6),
    ROOMTYPE_NAME VARCHAR(40),
    COMPANYNAME VARCHAR(40),
    NOTE_PREFER BLOB SUB_TYPE 0 SEGMENT SIZE 512,
    RATE_PACKAGE_INFO VARCHAR(150),
    FLAG_BREAKFAST INTEGER,
    RATECODE VARCHAR(12),
    ROOM VARCHAR(8))
AS
declare variable XNAME varchar(40);
declare variable XPKG_TYPE varchar(4);
declare variable XPKG varchar(6);
declare variable FOSYSDATE date;
begin

  SELECT FOSYSDATE FROM FOSYSPARAM
  WHERE ID = 1
  INTO FOSYSDATE;

  FOR
  SELECT
    GS.FOLIO,
    GS.RESV_EMAIL,
    GS.ST_NATIONALITY,
    GS.FNAME || ' ' || GS.LNAME GUESTNAME,
    GS.FNAME FIRSTNAME,
    GS.LNAME LASTNAME,
    GS.TITLE,
    GS.DATECI,
    GS.DATECO,
    CAST(GS.DATECO-GS.DATECI AS INTEGER) NIGHTS,
    GS.PAX NO_OF_PERSON,
    GS.CHILD NO_OF_CHILD,
    GS.ROOMTYPE,
    TY.NAME ROOMTYPE_NAME,
    GS.COMPANYNAME,
    GS.NOTE_PREFER,
    GS.RATECODE,
    GS.ROOM
    FROM FOGUEST GS
    LEFT JOIN FOROOMTYPE TY ON TY.ROOMTYPE=GS.ROOMTYPE
    WHERE GS.FOLIOSTATUS ='I'
    AND GS.FOLIOSTATUS_SHARE ='M'
    AND GS.FOLIOTYPE ='P'

    INTO SFOLIO, RESV_EMAIL, ST_NATIONALITY, GUESTNAME, FIRSTNAME, LASTNAME, TITLE,
    DATECI, DATECO, NIGHTS, NO_OF_PERSON, NO_OF_CHILD, ROOMTYPE, ROOMTYPE_NAME,
    COMPANYNAME, NOTE_PREFER, RATECODE, ROOM

    DO BEGIN

     RATE_PACKAGE_INFO = '';

     FOR SELECT RT.PACKAGE_CODE, PKG.NAME, PKG.PACKAGE_TYPE
         FROM FOGUEST_JUR RT
         LEFT JOIN FOPACKAGE PKG ON PKG.PACKAGE = RT.PACKAGE_CODE
         WHERE RT.PACKAGE_CODE NOT IN('ATAX','RATE','COM+','COM-','DISC')
         AND RT.FOLIO_ORIGINAL = :SFOLIO
         AND FODATE = :FOSYSDATE -1
         GROUP BY RT.PACKAGE_CODE, PKG.NAME, PKG.PACKAGE_TYPE
         INTO XPKG, XNAME, XPKG_TYPE

            DO
            BEGIN
                IF (XPKG_TYPE = 'MBF') THEN
                FLAG_BREAKFAST = 1;
                IF (XPKG_TYPE IS NULL) THEN
                FLAG_BREAKFAST = 0;
                RATE_PACKAGE_INFO = RATE_PACKAGE_INFO ||XPKG||', ';
            END

            IF (RATECODE ='COMPL') THEN FLAG_BREAKFAST = 1;
            IF (RATECODE ='HU') THEN FLAG_BREAKFAST = 1;

    SUSPEND;
  END
END^


ALTER PROCEDURE XSBMB_DAILY_FORECAST(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    TOTAL_ROOM INTEGER,
    TOTAL_OINV INTEGER,
    AVAILABLE INTEGER,
    NIGHTS INTEGER,
    FIT_NIGHT INTEGER,
    GIT_NIGHT INTEGER,
    HU INTEGER,
    COMPL INTEGER,
    PAX INTEGER,
    CHILD INTEGER,
    ROOMRATE DOUBLE PRECISION,
    ROOMREVENUE DOUBLE PRECISION,
    OCCUPIED INTEGER,
    PAYING INTEGER,
    AVG_RATE DOUBLE PRECISION,
    AVG_ROOMREVENUE DOUBLE PRECISION)
AS
BEGIN
  SELECT SUM(ROOMCOUNT) FROM FOROOMTYPE
  INTO TOTAL_ROOM;
   SELECT COUNT(ROOM) FROM foroom WHERE STATUS_HK='X'
   INTO TOTAL_OINV;
  FODATE = SDATE;
  WHILE (FODATE <= EDATE) DO
  BEGIN
    SELECT SUM(NIGHT),SUM(ROOMRATE),SUM(RATE_ROOMONLY),SUM(PAX),SUM(CHILD)
    FROM FORI_LOG L
    LEFT JOIN FOROOMTYPE T ON T.ROOMTYPE = L.ROOMTYPE
    WHERE L.FODATE = :FODATE
    AND L.RATECODE <> 'HU'
    INTO  :NIGHTS,ROOMRATE,ROOMREVENUE,PAX,CHILD;

    /*FIT-ROOMNIGHT */
    SELECT SUM(NIGHT) FROM FORI_LOG   L
    LEFT JOIN FOROOMTYPE T ON T.ROOMTYPE = L.ROOMTYPE
    WHERE L.FODATE = :FODATE
    AND L.RATECODE <> 'HU'
    AND L.GROUPNUMBER ='0'
    INTO  :FIT_NIGHT;
    IF (FIT_NIGHT IS NULL) THEN
    BEGIN
       FIT_NIGHT = 0;
    END
    /*GIT-ROOMNIGHT */
    SELECT SUM(NIGHT) FROM FORI_LOG   L
    LEFT JOIN FOROOMTYPE T ON T.ROOMTYPE = L.ROOMTYPE
    WHERE L.FODATE = :FODATE
    AND L.RATECODE <> 'HU'
    AND L.GROUPNUMBER <>'0'
    INTO  :GIT_NIGHT;
    IF (GIT_NIGHT IS NULL) THEN
    BEGIN
       GIT_NIGHT = 0;
    END

      /* HU */
    SELECT SUM(NIGHT) FROM FORI_LOG   L
    LEFT JOIN FOROOMTYPE T ON T.ROOMTYPE = L.ROOMTYPE
    WHERE L.FODATE = :FODATE
    AND L.RATECODE = 'HU'
    INTO  :HU;
    IF (HU IS NULL) THEN
    BEGIN
    HU = 0;
    END
    /* COMPL */
    SELECT SUM(NIGHT) FROM FORI_LOG   L
    LEFT JOIN FOROOMTYPE T ON T.ROOMTYPE = L.ROOMTYPE
    WHERE L.FODATE = :FODATE
    AND L.RATECODE = 'COMPL'
    INTO  :COMPL;
    IF (COMPL IS NULL) THEN
    BEGIN
    COMPL = 0;
    END

    IF (NIGHTS IS NULL) THEN
    BEGIN
       NIGHTS = 0;
       ROOMREVENUE = 0;
    END
    IF (NIGHTS <> 0) THEN
    BEGIN
      AVG_RATE = ROOMRATE/NIGHTS;
      AVG_ROOMREVENUE = ROOMREVENUE/NIGHTS;
    END
    ELSE
    BEGIN
      AVG_RATE = 0;
      AVG_ROOMREVENUE = 0;
    END
      AVAILABLE   =    TOTAL_ROOM-TOTAL_OINV-HU;
    OCCUPIED    = NIGHTS+HU  ;
   PAYING =  NIGHTS-COMPL;
    SUSPEND;
    FODATE = FODATE + 1;
  END

END^


ALTER PROCEDURE XSBMB_GUEST_SPECIAL
RETURNS (
    INFO_INDEX INTEGER,
    INFO_NAME VARCHAR(50),
    FOLIO INTEGER,
    ROOM VARCHAR(8),
    FULLNAMEF VARCHAR(80),
    DATECI DATE,
    DATECO DATE,
    COMPANYNAME VARCHAR(40),
    CHECKIN_BY VARCHAR(16),
    DATECI_TIME VARCHAR(5),
    REMARK VARCHAR(40),
    NOTE_CHECKIN BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    NOTE_CASHIER BLOB SUB_TYPE 0 SEGMENT SIZE 80)
AS
DECLARE VARIABLE FODATE DATE;
DECLARE VARIABLE XDATA VARCHAR(30);
DECLARE VARIABLE N0 INTEGER;
DECLARE VARIABLE N1 INTEGER;
DECLARE VARIABLE N2 INTEGER;
DECLARE VARIABLE HONEYMOONER INTEGER;
BEGIN
  SELECT FOSYSDATE FROM FOSYSPARAM WHERE ID = 1 INTO FODATE;
  /*
    VIP ARRIVAL GUEST
  */
  INFO_INDEX = 0;
  INFO_NAME  = 'VIP-Expected Arrival';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,GS.NOTE_CASHIER,GS.NOTE_CHECKIN,GS.VIPLEVEL,
           GS.FLAG_HONEYMOONER
    FROM FOGUEST GS
    WHERE GS.DATECI = :FODATE + 1
    AND GS.FOLIOTYPE = 'P'
    AND GS.FOLIOSTATUS IN ('G','C','T','W')
    AND GS.FOLIOSTATUS_SHARE = 'M'
    AND GS.VIPLEVEL <> 0
    AND GS.RATECODE <> 'HU' /* 13 MAY 200 7 */
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,:XDATA,honeymooner
  DO
  BEGIN
    if (honeymooner = 1) then REMARK = 'Honeymooer';
    ELSE REMARK = 'VIP'||:XDATA;
    SUSPEND;
  END
  /*
    VIP IN HOUSE
  */
  INFO_INDEX = 1;
  INFO_NAME  = 'VIP-In House';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,GS.VIPLEVEL,
           GS.FLAG_HONEYMOONER
    FROM FOGUEST GS
    WHERE GS.FOLIOTYPE = 'P'
    AND GS.FOLIOSTATUS = 'I'
    AND GS.FOLIOSTATUS_SHARE = 'M'
    AND GS.VIPLEVEL <> 0
    AND GS.RATECODE <> 'HU' /* 13 MAY 200 7 */
    ORDER BY GS.DATECI
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,:XDATA,honeymooner
  DO
  BEGIN
    if (honeymooner = 1) then REMARK = 'Honeymooer';
    ELSE REMARK = 'VIP'||:XDATA;
    SUSPEND;
  END  
  /*
    REPEATER GUEST
  */
  INFO_INDEX = 2;
  INFO_NAME  = 'Repeater Guest';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,GS.HISTORY,
           H.TOTAL_STAY,H.TOTAL_ROOMNIGHT /* 11 desember 2008 */
    FROM FOGUEST GS
    LEFT JOIN FO_HIST_GUEST H ON H.HISTORY = GS.HISTORY /* 11 desember 2008 */
    WHERE GS.FOLIOTYPE = 'P'
    AND GS.FOLIOSTATUS = 'I'
    AND GS.FOLIOSTATUS_SHARE = 'M'
    AND GS.HISTORY <> 0
    AND GS.RATECODE <> 'HU' /* 13 MAY 2007 */
    AND H.TOTAL_STAY > 0 /* 11 desember 2008 */
    ORDER BY GS.DATECI    
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,:N0,
         :N1,N2 /* 11 desember 2008 */
  DO
  BEGIN
    REMARK = '#Stay '||N1|| ' #Nights '||N2;
    SUSPEND;
  END    
  /*
    LONG STAY GUEST IN HOUSE
  */
  /* ---------------------------------------------------------------- */
  /* 14 MAY 2007                                                      */
  /* GET LONG STAY INFO                                               */
  /* ---------------------------------------------------------------- */
  N1 = 0;
  BEGIN
     SELECT DATA FROM INIFILE
     WHERE FILENAME = 'FO'
     AND SECTION = 'Guest'
     AND IDENTITY = 'LONG_STAY_DAY'
     INTO N1;
     WHEN ANY DO N1 = 6;
  END
  IF (N1 IS NULL) THEN N1 = 6;
  IF (N1 < 3) THEN N1 = 3;
  /* ---------------------------------------------------------------- */
  /* END OF 14 MAY 2007                                               */
  /* ---------------------------------------------------------------- */
  INFO_INDEX = 3;
  INFO_NAME  = 'Long Staying Guest (min. '|| N1 || ' nights)';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,GS.ROOMNIGHT
    FROM FOGUEST GS
    WHERE GS.FOLIOTYPE = 'P'
    AND GS.FOLIOSTATUS = 'I'
    AND GS.FOLIOSTATUS_SHARE = 'M'
    AND GS.ROOMNIGHT >= :N1
    AND GS.RATECODE <> 'HU' /* 13 MAY 2007 */
    AND GS.RATECODE NOT LIKE 'COMPL%' /* 13 MAY 2007 */
    ORDER BY GS.DATECI    
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,N1
  DO
  BEGIN
    REMARK = N1 || ' nights';
    SUSPEND;
  END    
  /*
    Birthday
  */
  INFO_INDEX = 4;
  INFO_NAME  = 'Birthday';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,GS.ROOMNIGHT
    FROM FOGUEST GS
    WHERE GS.FOLIOTYPE = 'P'
    AND GS.FOLIOSTATUS = 'I'
    AND GS.FOLIOSTATUS_SHARE = 'M'
    AND GS.BIRTHDAY='NOW'
    ORDER BY GS.DATECI    
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,:N1
  DO
  BEGIN
    REMARK = N1 ||' nights ';
    SUSPEND;
  END    
  /*
    HOUSE USE

  INFO_INDEX = 5;
  INFO_NAME  = 'House Use';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,GS.ROOMNIGHT
    FROM FOGUEST GS
    WHERE GS.FOLIOTYPE = 'P'
    AND GS.FOLIOSTATUS = 'I'
    AND GS.FOLIOSTATUS_SHARE = 'M'
    AND GS.RATECODE = 'HU'
    ORDER BY GS.DATECI    
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,:N1
  DO
  BEGIN
    REMARK = N1 ||' nights ';
    SUSPEND;
  END
  */
  /*
    MICE IN HOUSE

  INFO_INDEX = 6;
  INFO_NAME  = 'In House MICE';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,
           GS.GRP_ROOMCOUNT,GS.GRP_ROOMNIGHT
    FROM FOGUEST GS
    WHERE GS.FOLIOTYPE = 'G'
    AND GS.FOLIOSTATUS = 'I'
    ORDER BY GS.DATECI    
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,N0,N1
  DO
  BEGIN
    SELECT SUM(PAX) FROM FOGUEST WHERE GROUPNUMBER = :FOLIO
    AND FOLIOTYPE = 'P'
    AND FOLIOSTATUS IN ('I','G','T','C','W')
    INTO N2;  
    if (N2 IS NULL) then N2 = 0;
    REMARK = N0 || ' rooms,' || N1 || ' nights,' || N2 || ' pax';
    SUSPEND;
  END
              */
  /*
    MICE ARRIVAL

  INFO_INDEX = 7;
  INFO_NAME  = 'MICE-Expected Arrival';
  FOR
    SELECT GS.FOLIO,GS.ROOM,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.COMPANYNAME,
           GS.CHECKIN_BY,GS.DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,
           GS.GRP_ROOMCOUNT,GS.GRP_ROOMNIGHT
    FROM FOGUEST GS
    WHERE GS.DATECI = :FODATE+1
    AND GS.FOLIOTYPE = 'G'
    INTO :FOLIO,:ROOM,:FULLNAMEF,:DATECI,:DATECO,:COMPANYNAME,
         :CHECKIN_BY,DATECI_TIME,NOTE_CASHIER,NOTE_CHECKIN,N0,N1
  DO
  BEGIN
    SELECT SUM(PAX) FROM FOGUEST WHERE GROUPNUMBER = :FOLIO
    AND FOLIOTYPE = 'P'
    AND FOLIOSTATUS IN ('I','G','T','C','W')
    INTO N2;
    if (N2 IS NULL) then N2 = 0;
    REMARK = N0 || ' rooms,' || N1 || ' nights,'|| N2 || ' pax';
    SUSPEND;
  END       
   */
END^


ALTER PROCEDURE XXFO_COUNTHK_WORKSHEET(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CODE VARCHAR(8),
    NAME VARCHAR(40),
    LISTINDEX INTEGER,
    FLAG_ACTIVE INTEGER,
    ITEM_PAGE VARCHAR(20),
    COST DOUBLE PRECISION,
    DATA_IN INTEGER,
    DATA_OUT INTEGER)
AS
begin
  FOR SELECT CODE,NAME,LISTINDEX,FLAG_ACTIVE,ITEM_PAGE,PARTNO_COST FROM FOHK_ITEM
  INTO : CODE,:NAME,:LISTINDEX,:FLAG_ACTIVE,:ITEM_PAGE,:COST
  DO BEGIN
     SELECT SUM(DATA_IN),SUM(DATA_OUT)
        FROM FOHK_DATA
        WHERE ITEM = :CODE
        AND FODATE BETWEEN :SDATE AND :EDATE
        INTO DATA_IN,DATA_OUT;
        IF (DATA_IN IS NULL) THEN
        BEGIN
           DATA_IN = 0;
           DATA_OUT = 0;
           /*CREATE BY ADIT 22/02/2016*/
       END
     SUSPEND;
  END
END^


ALTER PROCEDURE XXFO_GUEST_CHECK_MASTER_FOLIO
RETURNS (
    FOLIO INTEGER,
    FOLIOTYPE CHAR(1),
    FOLIOSTATUS CHAR(1),
    FOLIOSTATUS_SHARE CHAR(1),
    FOLIO_MASTER INTEGER,
    FULLNAMEF VARCHAR(80))
AS
BEGIN
  FOR
    SELECT GS.FOLIO,GS.FOLIOTYPE,GS.FOLIOSTATUS,
    GS.FOLIOSTATUS_SHARE,GS.FOLIO_MASTER,GS.FULLNAMEF
    FROM FOGUEST GS
    WHERE NOT (EXISTS(SELECT * FROM FOGUEST M WHERE M.FOLIO=GS.FOLIO_MASTER))
    INTO
      :FOLIO,
      :FOLIOTYPE,
      :FOLIOSTATUS,
      :FOLIOSTATUS_SHARE,
      :FOLIO_MASTER,
      :FULLNAMEF
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE XXFO_STAT_RECALC_FOSTAT(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    COUNTER INTEGER)
AS
declare variable DATATYPE varchar(4);
declare variable DATA varchar(30);
declare variable RATEDISCOUNT double precision;
declare variable NIGHT integer;
declare variable ROOMCOUNT integer;
declare variable PERSON integer;
declare variable PAX smallint;
declare variable CHILD smallint;
declare variable DEBIT double precision;
declare variable CREDIT double precision;
declare variable RATE_ROOMONLY double precision;
declare variable RATE_TOTAL double precision;
declare variable RATE_DISCOUNT double precision;
declare variable PACKAGE double precision;
declare variable CHARGE_CLASS0 double precision;
declare variable CHARGE_CLASS1 double precision;
declare variable CHARGE_CLASS2 double precision;
declare variable CHARGE_CLASS3 double precision;
declare variable CHARGE_CLASS4 double precision;
declare variable CHARGE_CLASS5 double precision;
declare variable CHARGE_CLASS6 double precision;
declare variable CHARGE_CLASS7 double precision;
declare variable CHARGE_CLASS8 double precision;
declare variable CHARGE_CLASS9 double precision;
declare variable ROOMRATE double precision;
declare variable RACKRATE double precision;
declare variable DAYUSE integer;
declare variable DAYUSE_REVENUE double precision;
declare variable REVENUE_BQ double precision;
declare variable REVENUE_FOOD double precision;
declare variable REVENUE_BEVERAGE double precision;
declare variable REVENUE_CONDOTEL double precision;
declare variable POS_FOOD double precision;
declare variable POS_BEVERAGE double precision;
declare variable POS_MERCHANDISE double precision;
declare variable POS_OTHER double precision;
declare variable POS_TAX double precision;
declare variable POS_BILL integer;
declare variable POS_COVER integer;
declare variable POS_COVER_BEV integer;
begin
  if (PYEAR IS NULL) then
  BEGIN
     SELECT EXTRACT(YEAR FROM FOSYSDATE),
            EXTRACT(MONTH FROM FOSYSDATE) FROM FOSYSPARAM
     INTO :PYEAR,:PMONTH;
     PYEAR = 2003;
     PMONTH = 10;
  END
  COUNTER = 0;
  /* ------------------------------------------------------------------------ */
  /* RESET ALL STATISTIC ACCUMULATION                                         */
  /* ------------------------------------------------------------------------ */
  DELETE FROM FOSTAT
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH;
  /* ------------------------------------------------------------------------ */
  /* INSERT TO STATISTIC                                                      */
  /* ------------------------------------------------------------------------ */
  /* 10-JAN 2004, UNTUK SPEEDUP */
  FOR  SELECT DATATYPE,
      DATA,
      SUM(ROOMRATE),
      SUM(ROOMCOUNT),
      SUM(NIGHT),
      SUM(PERSON),
      SUM(PAX),
      SUM(CHILD),
      SUM(DEBIT),
      SUM(CREDIT),
      SUM(RATE_ROOMONLY),
      SUM(RATE_TOTAL),
      SUM(RATE_DISCOUNT),
      SUM(PACKAGE),
      SUM(CHARGE_CLASS1),
      SUM(CHARGE_CLASS2),
      SUM(CHARGE_CLASS0),
      SUM(CHARGE_CLASS3),
      SUM(CHARGE_CLASS4),
      SUM(CHARGE_CLASS5),
      SUM(CHARGE_CLASS6),
      SUM(CHARGE_CLASS7),
      SUM(CHARGE_CLASS8),
      SUM(CHARGE_CLASS9),
      SUM(RACKRATE),
      SUM(DAYUSE),
      SUM(DAYUSE_REVENUE),
      SUM(REVENUE_BQ), /* 6 OCT 2010*/
      SUM(REVENUE_FOOD), /* 6 OCT 2010*/
      SUM(REVENUE_BEVERAGE), /* 6 OCT 2010*/
      SUM(REVENUE_CONDOTEL)
  FROM FO_STAT_RECALC_LOG(:PYEAR, :PMONTH)
  GROUP BY DATATYPE, DATA
  INTO
      :DATATYPE,
      :DATA,
      :ROOMRATE,
      :ROOMCOUNT,
      :NIGHT,
      :PERSON,
      :PAX,
      :CHILD,
      :DEBIT,
      :CREDIT,
      :RATE_ROOMONLY,
      :RATE_TOTAL,
      :RATE_DISCOUNT,
      :PACKAGE,
      :CHARGE_CLASS1,
      :CHARGE_CLASS2,
      :CHARGE_CLASS0,
      :CHARGE_CLASS3,
      :CHARGE_CLASS4,
      :CHARGE_CLASS5,
      :CHARGE_CLASS6,
      :CHARGE_CLASS7,
      :CHARGE_CLASS8,
      :CHARGE_CLASS9,
      :RACKRATE,
      :DAYUSE,
      :DAYUSE_REVENUE,
      :REVENUE_BQ,
      :REVENUE_FOOD,
      :REVENUE_BEVERAGE,
      :REVENUE_CONDOTEL
  DO
  BEGIN
  INSERT INTO FOSTAT (
    PYEAR,
    PMONTH,
    DATATYPE,
    DATA,
    ROOMRATE,
    ROOMCOUNT,
    NIGHT,
    PERSON,
    PAX,
    CHILD,
    DEBIT,
    CREDIT,
    RATE_ROOMONLY,
    RATE_TOTAL,
    RATE_DISCOUNT,
    PACKAGE,
    CHARGE_CLASS1,
    CHARGE_CLASS2,
    CHARGE_CLASS0,
    CHARGE_CLASS3,
    CHARGE_CLASS4,
    CHARGE_CLASS5,
    CHARGE_CLASS6,
    CHARGE_CLASS7,
    CHARGE_CLASS8,
    CHARGE_CLASS9,
    DAYUSE1,
    DAYUSE_REVENUE1,
    RACKRATE,
    REVENUE_BQ, /* 6 OCT 2010*/
    REVENUE_FOOD, /* 6 OCT 2010*/
    REVENUE_BEVERAGE, /* 6 OCT 2010*/
    REVENUE_CONDOTEL)
  VALUES (
    :PYEAR,
    :PMONTH,
    :DATATYPE,
    :DATA,
    :ROOMRATE,
    :ROOMCOUNT,
    :NIGHT,
    :PERSON,
    :PAX,
    :CHILD,
    :DEBIT,
    :CREDIT,
    :RATE_ROOMONLY,
    :RATE_TOTAL,
    :RATE_DISCOUNT,
    :PACKAGE,
    :CHARGE_CLASS1,
    :CHARGE_CLASS2,
    :CHARGE_CLASS0,
    :CHARGE_CLASS3,
    :CHARGE_CLASS4,
    :CHARGE_CLASS5,
    :CHARGE_CLASS6,
    :CHARGE_CLASS7,
    :CHARGE_CLASS8,
    :CHARGE_CLASS9,
    :DAYUSE,
    :DAYUSE_REVENUE,
    :RACKRATE,
    :REVENUE_BQ, /* 6 OCT 2010*/
    :REVENUE_FOOD, /* 6 OCT 2010*/
    :REVENUE_BEVERAGE, /* 6 OCT 2010*/
    :REVENUE_CONDOTEL);
    UPDATE FOSTAT
    SET LASTUPDATE = 'NOW'
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND DATATYPE = :DATATYPE
    AND DATA = :DATA;
    
    COUNTER = COUNTER + 1;
  END
  SUSPEND;
end^


ALTER PROCEDURE XXXMELBEN_RS
RETURNS (
    FODATE DATE,
    REVENUE DOUBLE PRECISION,
    STAT DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE D INTEGER;
BEGIN
  D = 0;
  FODATE = '1.10.2006';
  WHILE (D <= 31) DO
  BEGIN
     EXECUTE PROCEDURE FO_RS_GET_DATA('ROOMREVENUE',
     :FODATE,:FODATE)
     RETURNING_VALUES REVENUE;
     SELECT SUM(CHARGE_CLASS1) FROM FOSTAT_LOG
     WHERE FODATE = :FODATE
     INTO STAT;
     DELTA = STAT - REVENUE;
     SUSPEND;
     FODATE = FODATE + 1;
     D = D + 1;
  END
END^


ALTER PROCEDURE XXX_CHECK_AR
RETURNS (
    FODATE DATE,
    FOLIO INTEGER,
    TRANS_ID INTEGER,
    POSTFLAG CHAR(1),
    TOTAL DOUBLE PRECISION,
    ARTOTAL DOUBLE PRECISION,
    VOUCHERNO INTEGER,
    DELTA DOUBLE PRECISION,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    GL_ACCOUNT VARCHAR(20))
AS
BEGIN
  DELTA = 0;
  FOR
    SELECT J.FODATE,J.FOLIO,J.POSTFLAG,J.AR_CUSTOMER,T.GLACCOUNT,C.NAME,
           SUM(J.CREDIT-J.DEBIT)
    FROM FOGUEST_JUR J
    LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = J.AR_CUSTOMER
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
    WHERE J.FODATE BETWEEN '1.8.2005' AND '31.8.2005'
    AND J.JURCODE = 'CL'
    GROUP BY J.FODATE,J.FOLIO,J.POSTFLAG,J.AR_CUSTOMER,T.GLACCOUNT,C.NAME
    ORDER BY J.FOLIO
    INTO
      :FODATE,
      :FOLIO,
      :POSTFLAG,
      :CUSTOMER,
      :GL_ACCOUNT,
      :NAME,
      :TOTAL
  DO
  BEGIN
    VOUCHERNO = NULL;
    IF (TOTAL <> 0) THEN
    BEGIN
       ARTOTAL = NULL;
       SELECT SUM(TOTAL) FROM ARVCH WHERE FO_FOLIO = :FOLIO
       AND OPENDATE = :FODATE
       PLAN (ARVCH INDEX (ARVCH_FO_FOLIO))
       INTO ARTOTAL;
       IF (ARTOTAL IS NULL) THEN ARTOTAL =0;
       IF (ARTOTAL-TOTAL <> 0) THEN
       BEGIN
          DELTA = DELTA + TOTAL-ARTOTAL;
          SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE XXX_CHECK_AR_TOTAL(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    TOTAL DOUBLE PRECISION,
    COUNTER INTEGER,
    ARTOTAL DOUBLE PRECISION,
    ARCOUNTER INTEGER,
    DELTA DOUBLE PRECISION,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40))
AS
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.8.2005';
     EDATE = '31.8.2005';
  END
  DELTA = 0;
  FOR
    SELECT J.AR_CUSTOMER,C.NAME,SUM(J.CREDIT-J.DEBIT),COUNT(*)
    FROM FOGUEST_JUR J
    LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = J.AR_CUSTOMER
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
    WHERE J.FODATE BETWEEN :SDATE AND :EDATE
    AND J.JURCODE = 'CL'
    GROUP BY J.AR_CUSTOMER,C.NAME
    INTO
      :CUSTOMER,
      :NAME,
      :TOTAL,COUNTER
  DO
  BEGIN
    IF (TOTAL <> 0) THEN
    BEGIN
       ARTOTAL = NULL;
       SELECT SUM(TOTAL),COUNT(*) FROM ARVCH
       WHERE CUSTOMER = :CUSTOMER
       AND OPENDATE BETWEEN :SDATE AND :EDATE
       INTO ARTOTAL,ARCOUNTER;
       IF (ARTOTAL IS NULL) THEN ARTOTAL =0;
       IF (NOT (ARTOTAL-TOTAL BETWEEN -0.1 AND 0.1)) THEN
       BEGIN
          DELTA = DELTA + TOTAL-ARTOTAL;
          SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE XXX_CHECK_AR_TOTAL_DETAIL(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FOLIO INTEGER,
    TOTAL DOUBLE PRECISION,
    ARVOUCHER INTEGER,
    ARTOTAL DOUBLE PRECISION,
    DELTA DOUBLE PRECISION,
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40))
AS
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.8.2005';
     EDATE = '31.8.2005';
  END
  DELTA = 0;
  ARVOUCHER = 0;
  ARTOTAL = 0;
  FOR
    SELECT J.FOLIO,C.NAME,(J.CREDIT-J.DEBIT),J.AR_CUSTOMER
    FROM FOGUEST_JUR J
    LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = J.AR_CUSTOMER
    LEFT JOIN SYSCUSTOMERTYPE T ON T.CUSTOMERTYPE = C.CUSTTYPE
    WHERE J.FODATE BETWEEN :SDATE AND :EDATE
    AND J.JURCODE = 'CL'
    INTO
      :FOLIO,
      :NAME,
      :TOTAL,
      :CUSTOMER
  DO
  BEGIN
    SUSPEND;
  END
  FOLIO = 0;
  TOTAL = 0;
  FOR SELECT V.CUSTOMER,C.NAME,V.NUMBER,V.FO_FOLIO,V.TOTAL FROM ARVCH V
      LEFT JOIN SYSCUSTOMER C ON C.CUSTOMER = V.CUSTOMER
       WHERE OPENDATE BETWEEN :SDATE AND :EDATE
       INTO CUSTOMER,NAME,ARVOUCHER,FOLIO,ARTOTAL
  DO
  BEGIN
     SUSPEND;
  END
END^


ALTER PROCEDURE XXX_CHECK_AR_TOTAL_DETAIL_OK(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    FOLIO INTEGER,
    TOTAL_FO DOUBLE PRECISION,
    TOTAL_VCH DOUBLE PRECISION,
    DELTA DOUBLE PRECISION,
    TOTAL_DELTA DOUBLE PRECISION)
AS
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.10.2005';
     EDATE = '31.10.2005';
  END
  TOTAL_DELTA = 0;
  FOR
    SELECT CUSTOMER,NAME,FOLIO,
           SUM(TOTAL),
           SUM(ARTOTAL)
    FROM XXX_CHECK_AR_TOTAL_DETAIL (:SDATE,:EDATE)
    GROUP BY FOLIO,CUSTOMER,NAME
    INTO
      :CUSTOMER,NAME,
      :FOLIO,
      :TOTAL_FO,
      :TOTAL_VCH
  DO
  BEGIN
    DELTA = TOTAL_FO - TOTAL_VCH;
    TOTAL_DELTA = TOTAL_DELTA + DELTA;
    IF (NOT (DELTA BETWEEN -0.1 AND 0.1)) THEN
       SUSPEND;
  END
END^


ALTER PROCEDURE XXX_CL_CHECK_EXPORT(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    AR_CUSTOMER VARCHAR(6),
    FOLIO INTEGER,
    TRANS_ID INTEGER,
    TOTAL_FO DOUBLE PRECISION,
    VOUCHER_NO INTEGER,
    VOUCHER_CUSTOMER VARCHAR(6))
AS
BEGIN
  SDATE = '1.8.2005';
  EDATE = '31.8.2005';
  
  FOR
    select FODATE,AR_CUSTOMER,FOLIO,TRANS_ID,(CREDIT-DEBIT) TOTAL_FO
    from foguest_jur
    where FODATE BETWEEN :SDATE AND :EDATE
    AND jurcode = 'CL'

    INTO
      :FODATE,
      :AR_CUSTOMER,
      :FOLIO,
      :TRANS_ID,
      :TOTAL_FO
  DO
  BEGIN
    VOUCHER_NO = 0;
    VOUCHER_CUSTOMER = '';
    SELECT NUMBER,CUSTOMER FROM ARVCH
    WHERE FO_FOLIO = :FOLIO
    AND FO_TRANS_ID = :TRANS_ID
    INTO :VOUCHER_NO,VOUCHER_CUSTOMER;
    SUSPEND;
  END
END^


ALTER PROCEDURE XXX_CL_CHECK_EXPORT_XX(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    TOTAL_DELTA DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    AR_CUSTOMER VARCHAR(6),
    FOLIO INTEGER,
    TRANS_ID INTEGER,
    TOTAL_AR DOUBLE PRECISION,
    TOTAL_FO DOUBLE PRECISION,
    VOUCHER_NO INTEGER,
    VOUCHER_CUSTOMER VARCHAR(6))
AS
BEGIN
  SDATE = '27.8.2005';
  EDATE = '27.8.2005';
  TOTAL_DELTA = 0;
  TOTAL = 0;
  FOR SELECT NUMBER,CUSTOMER,FO_TRANS_ID,TOTAL FROM ARVCH
       WHERE OPENDATE BETWEEN :SDATE AND :EDATE
       AND FO_FOLIO <> 0
       ORDER BY FO_FOLIO
       INTO :VOUCHER_NO,VOUCHER_CUSTOMER,TRANS_ID,TOTAL_AR
  DO
  BEGIN
    TOTAL_FO = 0;
    FOLIO = 0;
    select AR_CUSTOMER,FOLIO,CREDIT-DEBIT from foguest_jur
    where TRANS_ID = :TRANS_ID
    INTO
      :AR_CUSTOMER,
      :FOLIO,
      :TOTAL_FO;
    TOTAL_DELTA = TOTAL_FO - TOTAL_AR;
    TOTAL = TOTAL + TOTAL_FO;
    SUSPEND;
  END
END^


ALTER PROCEDURE XXX_RECONS_REPORT
RETURNS (
    BANK VARCHAR(4),
    OUTLET VARCHAR(4),
    BATCH INTEGER,
    OPENDATE DATE,
    REMARK VARCHAR(40),
    AMOUNT DOUBLE PRECISION,
    STATUS CHAR(1),
    PAY_REF VARCHAR(20),
    PAY_DATE DATE,
    PAY_FEE DOUBLE PRECISION,
    PAY_TOTAL DOUBLE PRECISION,
    CREATEUSER VARCHAR(8),
    CREATEDATE DATE,
    EDITUSER VARCHAR(8),
    EDITDATE DATE,
    AMOUNT_FEE DOUBLE PRECISION,
    CALC_AMOUNT_NET DOUBLE PRECISION,
    NUMBER INTEGER,
    RECONCILEDATE DATE,
    DOCUMENT VARCHAR(20))
AS
BEGIN
  FOR
    select * from AR_CARD_BATCH WHERE STATUS ='R'
    AND OPENDATE =:OPENDATE

    INTO
      :BANK,
      :OUTLET,
      :BATCH,
      :OPENDATE,
      :REMARK,
      :AMOUNT,
      :STATUS,
      :PAY_REF,
      :PAY_DATE,
      :PAY_FEE,
      :PAY_TOTAL,
      :CREATEUSER,
      :CREATEDATE,
      :EDITUSER,
      :EDITDATE,
      :AMOUNT_FEE,
      :CALC_AMOUNT_NET,
      :NUMBER,
      :RECONCILEDATE,
      :DOCUMENT
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_AIP(
    SDATE DATE)
RETURNS (
    FODATE DATE,
    DEBIT DOUBLE PRECISION,
    CHARGE DOUBLE PRECISION,
    PACKAGE_CODE VARCHAR(6),
    PACKAGE_NAME VARCHAR(40),
    PAX SMALLINT,
    CHILD SMALLINT,
    FOLIO INTEGER)
AS
BEGIN
  FOR
    SELECT JR.FODATE,JR.DEBIT,(PK.CHARGE_ADULT*GS.PAX),JR.PACKAGE_CODE,PK.NAME,GS.PAX,GS.CHILD ,GS.FOLIO
          FROM FOGUEST_JUR JR
          LEFT JOIN FOGUEST GS ON GS.FOLIO=JR.FOLIO
          LEFT JOIN FOPACKAGE PK ON PK.PACKAGE=JR.PACKAGE_CODE
          WHERE JR.FODATE =:SDATE
          AND GS.FOLIOTYPE='P'
            AND GS.foliostatus_share='M'
             /*  AND JR.CATEGORY IN ('2101','2102','2103','2104','2105') */
          AND JR.PACKAGE_ALLOWANCE = '1'

    INTO
      :FODATE,
      :DEBIT,
      :CHARGE,
      :PACKAGE_CODE,
      :PACKAGE_NAME,
      :PAX,
      :CHILD,
      :FOLIO
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_AR_1
RETURNS (
    ACCOUNT VARCHAR(20),
    GL DOUBLE PRECISION)
AS
DECLARE variable NUMBER INTEGER ;
BEGIN
  FOR
    SELECT 
      ARADJ.NUMBER
    FROM
      ARADJ
    WHERE OPENDATE BETWEEN '01.10.2005' AND '31.10.2005'
    GROUP BY NUMBER
    ORDER BY ARADJ.NUMBER
    INTO
      :NUMBER
  DO
  BEGIN
    SELECT GL_ACCOUNT,SUM(DEBIT) FROM AR_GLBUFFER_ADJ_RELEASE(:NUMBER)
    GROUP BY GL_ACCOUNT
    INTO :ACCOUNT,:GL ;
  END
  SUSPEND;
END^


ALTER PROCEDURE XX_AR_BATCH_CHANGE_PAY_DATE(
    P_SAVE INTEGER)
RETURNS (
    BANK VARCHAR(4),
    OUTLET VARCHAR(4),
    BATCH INTEGER,
    OPENDATE DATE,
    PAY_DATE DATE,
    COUNT_DETAIL INTEGER)
AS
BEGIN
  FOR
    SELECT 
      AR_CARD_BATCH.BANK,
      AR_CARD_BATCH.OUTLET,
      AR_CARD_BATCH.BATCH,
      AR_CARD_BATCH.OPENDATE,
      AR_CARD_BATCH.PAY_DATE
    FROM
      AR_CARD_BATCH
    WHERE AR_CARD_BATCH.PAY_DATE < AR_CARD_BATCH.OPENDATE
    ORDER BY BATCH
    INTO
      :BANK,
      :OUTLET,
      :BATCH,
      :OPENDATE,
      :PAY_DATE
  DO
  BEGIN
    SELECT COUNT(BATCH) FROM AR_CARD_JUR J
    WHERE J.BANK=:BANK
       AND J.OUTLET=:OUTLET
       AND J.BATCH=:BATCH
      INTO :COUNT_DETAIL;

  IF (P_SAVE=1) THEN
    BEGIN
    UPDATE AR_CARD_BATCH
    SET OPENDATE= :PAY_DATE 
    WHERE BANK=:BANK
      AND OUTLET=:OUTLET
      AND BATCH=:BATCH ;

    UPDATE AR_CARD_JUR
    SET PAY_DATE=:PAY_dATE
    WHERE BANK=:BANK
      AND BATCH=:BATCH ;
    END
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_AR_GLBUFFER_RECREATE_ALL(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER,
    USERID VARCHAR(8))
RETURNS (
    TDB DOUBLE PRECISION,
    TDELTA DOUBLE PRECISION,
    NUMBER INTEGER,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE NET DOUBLE PRECISION;
DECLARE VARIABLE TNET DOUBLE PRECISION;
begin
  SDATE = '1.10.2005'; EDATE = '31.10.2005';
  PSAVE = 0;
  /* ------------------------------------------------------------------------ */
  /* CREDIT CARD BATCH RECONCILE HANYA DISPLAY TIDAK DI PERNAH DI SAVE        */
  /* ------------------------------------------------------------------------ */
  TNET = 0;
  TDB = 0;
  IF (PSAVE = 0) THEN
  BEGIN
    FOR SELECT CALC_AMOUNT_NET,NUMBER FROM AR_CARD_BATCH
        WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
        AND STATUS = 'C'
        ORDER BY NUMBER
        INTO NET,NUMBER
    DO
    BEGIN
       TNET = TNET + NET;
       FOR SELECT APPLICATION,SOURCE,INFO,TRANSDATE,ID,
                  GL_ACCOUNT,GL_DEPT,GL_COST,
                  ACCNAME,NOTE,REF,
                  DEBIT,CREDIT,
                  SETUP_INFO,SETUP_DATA,ERROR_TEXT,
                  RELATION_CODE,RELATION_DOCTYPE
            FROM AR_GLBUFFER_CC_BATCH_RECONCILE(:NUMBER)
       INTO APPLICATION,SOURCE,INFO,TRANSDATE,ID,
            GL_ACCOUNT,GL_DEPT,GL_COST,
            ACCNAME,NOTE,REF,
            DEBIT,CREDIT,
            SETUP_INFO,SETUP_DATA,ERROR_TEXT,
            RELATION_CODE,RELATION_DOCTYPE
       DO
       BEGIN
         TDB = TDB + DEBIT;
         TDELTA = TDB - TNET;
         SUSPEND;
       END
     END
  END
  DEBIT = TNET;
  CREDIT = TNET;
  SUSPEND;
END^


