                :GL_ACCOUNT,:GL_DEPT,:GL_COST,'',
                :NOTE,:REF,
                :DEBIT,:CREDIT,
                'now',:USERID,:RELATION_CODE,:RELATION_DOCTYPE);
       END
       ELSE SUSPEND;
     END
  END*/
end^


ALTER PROCEDURE XX_AR_RECREATE_VOUCHER(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER,
    USERID VARCHAR(8))
RETURNS (
    NUMBER INTEGER,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
begin
  IF (SDATE IS NULL) THEN
  BEGIN
     SELECT ARSYSDATE FROM FOSYSPARAM INTO EDATE;
     SDATE = '1.7.2005'; EDATE = '31.7.2005';
     PSAVE = 0;
  END
  IF (PSAVE = 1) THEN
  BEGIN
     DELETE FROM GLBUFFER WHERE APPLICATION = 'AR'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
  END
  /* ------------------------------------------------------------------------ */
  /* VOUCHER                                                                  */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM ARVCH
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND GLSTATUS = 'C'
      ORDER BY NUMBER
      INTO NUMBER
  DO
  BEGIN
     FOR SELECT APPLICATION,SOURCE,INFO,TRANSDATE,ID,
                GL_ACCOUNT,GL_DEPT,GL_COST,
                ACCNAME,NOTE,REF,
                DEBIT,CREDIT,
                SETUP_INFO,SETUP_DATA,ERROR_TEXT,
                RELATION_CODE,RELATION_DOCTYPE
          FROM AR_GLBUFFER_VCH_EOD(:NUMBER)
     INTO APPLICATION,SOURCE,INFO,TRANSDATE,ID,
          GL_ACCOUNT,GL_DEPT,GL_COST,
          ACCNAME,NOTE,REF,
          DEBIT,CREDIT,
          SETUP_INFO,SETUP_DATA,ERROR_TEXT,
          RELATION_CODE,RELATION_DOCTYPE
     DO
     BEGIN
       IF (PSAVE = 1) THEN
       BEGIN
        insert into glbuffer
               (APPLICATION,SOURCE,NUMBER,ID,transdate,
                ACCOUNT,DEPT,COST,PROJECT,
                NOTE,REF,
                DB,CR,
                EXPORTDATE,EXPORTUSER,RELATION_CODE,RELATION_DOCTYPE)
        values (:application,:source,:number,:ID,:transdate,
                :GL_ACCOUNT,:GL_DEPT,:GL_COST,'',
                :NOTE,:REF,
                :DEBIT,:CREDIT,
                'now',:USERID,:RELATION_CODE,:RELATION_DOCTYPE);
       END
       ELSE SUSPEND;
     END
  END
  /* ------------------------------------------------------------------------ */
  /* ADJUSTMENT                                                               */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM ARADJ
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND STATUS IN ('R','C')
      ORDER BY NUMBER
      INTO NUMBER
  DO
  BEGIN
     FOR SELECT APPLICATION,SOURCE,INFO,TRANSDATE,ID,
                GL_ACCOUNT,GL_DEPT,GL_COST,
                ACCNAME,NOTE,REF,
                DEBIT,CREDIT,
                SETUP_INFO,SETUP_DATA,ERROR_TEXT,
                RELATION_CODE,RELATION_DOCTYPE
          FROM AR_GLBUFFER_ADJ_RELEASE(:NUMBER)
     INTO APPLICATION,SOURCE,INFO,TRANSDATE,ID,
          GL_ACCOUNT,GL_DEPT,GL_COST,
          ACCNAME,NOTE,REF,
          DEBIT,CREDIT,
          SETUP_INFO,SETUP_DATA,ERROR_TEXT,
          RELATION_CODE,RELATION_DOCTYPE
     DO
     BEGIN
       IF (PSAVE = 1) THEN
       BEGIN
        insert into glbuffer
               (APPLICATION,SOURCE,NUMBER,ID,transdate,
                ACCOUNT,DEPT,COST,PROJECT,
                NOTE,REF,
                DB,CR,
                EXPORTDATE,EXPORTUSER,RELATION_CODE,RELATION_DOCTYPE)
        values (:application,:source,:number,:ID,:transdate,
                :GL_ACCOUNT,:GL_DEPT,:GL_COST,'',
                :NOTE,:REF,
                :DEBIT,:CREDIT,
                'now',:USERID,:RELATION_CODE,:RELATION_DOCTYPE);
       END
       ELSE SUSPEND;
     END
  END
end^


ALTER PROCEDURE XX_AR_VALIDATE_AR
RETURNS (
    DOCTYPE VARCHAR(6),
    NUMBER INTEGER,
    VOUCHERNO INTEGER,
    CUSTOMER VARCHAR(6),
    D_CUSTOMER VARCHAR(6),
    V_CUSTOMER VARCHAR(6),
    TOTAL DOUBLE PRECISION)
AS
declare variable X INTEGER;
BEGIN
  X = 0;
  FOR
    select number,customer,total from arcash0
    INTO
      :NUMBER,
      :CUSTOMER,
      :TOTAL
  DO
  BEGIN
    for SELECT D.CUSTOMER,V.CUSTOMER FROM ARCASH1 D
        LEFT JOIN ARVCH V ON V.NUMBER = D.VOUCHERNO
        WHERE D.NUMBER = :NUMBER
        /*GROUP BY D.CUSTOMER,V.CUSTOMER*/
        INTO :D_CUSTOMER,:V_CUSTOMER
    DO
    BEGIN
      if (V_CUSTOMER <> CUSTOMER) then
      BEGIN
         SUSPEND;
/*         UPDATE ARCASH0 SET CUSTOMER = :V_CUSTOMER
         WHERE NUMBER = :NUMBER;*/
         X = X + 1;
      END  
    END
  END
  TOTAL = X;
END^


ALTER PROCEDURE XX_BALANCE(
    PSAVE INTEGER)
RETURNS (
    PFOLIO INTEGER,
    NAME VARCHAR(80),
    BALANCE DOUBLE PRECISION,
    ROOM VARCHAR(4),
    RTYPE VARCHAR(4))
AS
declare variable VDEBUG INTEGER ;

declare variable FODATE DATE ;
declare variable CAT_DB CHAR(4);
declare variable RF VARCHAR(20);
declare variable REMARK VARCHAR(40);
declare variable DB_BALANCE DOUBLE PRECISION;
declare variable CR_BALANCE DOUBLE PRECISION;
declare variable FOLIONAME VARCHAR(10);
BEGIN
      SELECT FOSYSDATE FROM fosysparam INTO :FODATE;
          SELECT CATEGORY FROM fosys_category
           WHERE CAT_ID = 'TRANSFER_DB' INTO :CAT_DB;
  FOR
        SELECT ZBALANCE.NAME,
               ZBALANCE.BALANCE,
               ZBALANCE.ROOM,
               ZBALANCE.RTYPE
        FROM ZBALANCE
        WHERE ROOM=''
    INTO
      :NAME,
      :BALANCE,
      :ROOM,
      :RTYPE
  DO
  BEGIN
    pfolio=0;
    if (:ROOM<>'') then
      BEGIN
       FOLIONAME=' ROOM ';
       SELECT FOLIO FROM FOGUEST
       WHERE ROOM=:ROOM
         AND FOLIOSTATUS='I'
         AND FOLIOTYPE ='P'
         AND FOLIOSTATUS_SHARE IN('M')
         INTO :PFOLIO ;
      END
      ELSE
    /* cHECK HOUSE FOLIO */
     if (:ROOM='') then
      BEGIN
       SELECT FOLIO FROM FOGUEST
        WHERE FNAME=:NAME
          AND FOLIOSTATUS='I'
          AND FOLIOTYPE ='H'
          AND FOLIOSTATUS_SHARE='M'
         INTO :PFOLIO ;
      END

   /* INSER TO FOGUEST  */
   if (PFOLIO=0) then
    BEGIN
      INSERT INTO FOGUEST(
          FOLIO,
          FNAME,
          DATECI,
          DATECO,
          ST_RESV_SOURCE ,
          ST_NATIONALITY ,
          ST_MARKETSEGMENT,
          ST_ORIGINAREA ,
          ST_DESTINATIONAREA ,
          FOLIOSTATUS,
          FOLIOTYPE,
          FOLIOSTATUS_SHARE)
        VALUES (
          0,
          :NAME,
          :FODATE,
          :FODATE+1,
          'PH',
          'INA',
          'FT',
          'JKT',
          'JKT',
          'I',
          'H',
          'M');
    END

   if (PSAVE=1) then
     BEGIN
          INSERT INTO FOGUEST_JUR (
            FOLIO,
            FODATE,
            CATEGORY,
            REMARK,
            DEBIT,
            CREDIT,
            CURRENCY,
            FOREX,
            JURCODE,
            REFERENCE,
            USERENTRY,
            HIDDEN,
            ROOM)
          VALUES (
            :PFOLIO,
            :FODATE,
            :CAT_DB,
            'Forward Balance',
            :BALANCE,
            0,
            'IDR',
            1,
            'TRF',
            'SUM PER-'||:FODATE,
            'ADMIN',
            0,
            :ROOM);
     END
   else SUSPEND;
  END
END^


ALTER PROCEDURE XX_CARD_1
RETURNS (
    CREDITCARD VARCHAR(6),
    TOTAL DOUBLE PRECISION,
    BATCH_AMT DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT 
      AR_CARD.CREDITCARD
    FROM
      AR_CARD

    INTO
      :CREDITCARD
  DO
  BEGIN
    SELECT SUM(TOTAL) FROM AR_CARD_JUR
    WHERE CREDITCARD=:CREDITCARD
/*      AND OPENDATE BETWEEN '1.10.2005' AND '31.10.2005'*/
      AND BATCH_NUMBER<>0
    INTO :TOTAL ;
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_CARD_AR
RETURNS (
    TEXT VARCHAR(50),
    DATA DOUBLE PRECISION)
AS
declare variable BANK VARCHAR(4);
declare variable OUTLET VARCHAR(4);
declare variable BATCH INTEGER;
declare variable PAYDATE DATE;
BEGIN
  FOR
    SELECT BANK,OUTLET,BATCH,PAY_DATE FROM AR_CARD_BATCH
    WHERE STATUS IN ('R','C')
    INTO
      :BANK,
      :OUTLET,
      :BATCH,
      :PAYDATE
  DO
  BEGIN
/*    TEXT = 'OUTLET ' || OUTLET || ' BATCH ';
    DATA  = BATCH;
    SUSPEND;*/
    UPDATE AR_CARD_JUR SET
    PAY_DATE = :PAYDATE,
    STATUS = 'C'
    WHERE OUTLET = :OUTLET
    AND BATCH = :BATCH;
  END

  FOR
    SELECT BANK,OUTLET,BATCH FROM AR_CARD_BATCH
    WHERE STATUS = 'O'
    INTO
      :BANK,
      :OUTLET,
      :BATCH
  DO
  BEGIN
    UPDATE AR_CARD_JUR SET STATUS = 'O'
    WHERE OUTLET = :OUTLET
    AND BANK = :BANK
    AND BATCH = :BATCH
    AND STATUS IN  ('R','C');
  END

END^


ALTER PROCEDURE XX_CHECK_ADJ_DATE(
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    DOCUMENT VARCHAR(20),
    OPENDATE DATE,
    CUSTOMER VARCHAR(6),
    STATUS CHAR(1),
    ADJNUMBER INTEGER,
    ADJOPENDATE DATE,
    FLAG_DELTA INTEGER)
AS
BEGIN
  FOR
    SELECT 
      ARVCH.NUMBER,
      ARVCH.DOCUMENT,
      ARVCH.OPENDATE,
      ARVCH.CUSTOMER,
      ARVCH.STATUS,
      ARADJ.NUMBER ADJNUMBER,
      ARADJ.OPENDATE ADJOPENDATE
    FROM
      ARVCH
      INNER JOIN ARADJ ON (ARVCH.NUMBER = ARADJ.VOUCHERNO)
    WHERE
      (ARVCH.OPENDATE < '31.12.2005')
    ORDER BY
      ARVCH.NUMBER

    INTO
      :NUMBER,
      :DOCUMENT,
      :OPENDATE,
      :CUSTOMER,
      :STATUS,
      :ADJNUMBER,
      :ADJOPENDATE
  DO
  BEGIN
   IF (OPENDATE<>:ADJOPENDATE) THEN FLAG_DELTA=1;
      ELSE FLAG_DELTA=0 ;
    IF (PSAVE=1) THEN
      BEGIN
        IF (FLAG_DELTA=1) THEN
          BEGIN
       /* Jika Delta maka Opendate Adj diganti dengan
          Opendate dari Voucher */
            UPDATE ARADJ SET OPENDATE=:OPENDATE
            WHERE VOUCHERNO=:NUMBER;
          END
      END
   SUSPEND;
  END
END^


ALTER PROCEDURE XX_CHECK_CUST
RETURNS (
    CUSTOMER VARCHAR(6),
    CUSTYPE VARCHAR(4),
    CURROMM CHAR(1))
AS
declare variable VCREDIT INTEGER;
BEGIN
  FOR
    SELECT * FROM ZCUST
    ORDER BY CUSTOMER ASC

    INTO
      :CUSTOMER,
      :CUSTYPE,
      :CURROMM
  DO
  BEGIN
     if (:CURROMM='Y') then VCREDIT=1 ; ELSE VCREDIT=0;
     if (:CUSTOMER IS NULL) then CUSTOMER='';
     UPDATE SYSCUSTOMER
     SET CUSTTYPE=:CUSTYPE,CREDITFACILITY=:VCREDIT 
     WHERE CUSTOMER=:CUSTOMER ;
  END
END^


ALTER PROCEDURE XX_CHECK_DSR_ID(
    FODATE DATE,
    PSAVE INTEGER)
RETURNS (
    LISTINDEX INTEGER,
    DSR_ID INTEGER,
    TEXT VARCHAR(40),
    AMOUNT DOUBLE PRECISION,
    AMT_DETAIL DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE IROW INTEGER ;
BEGIN
  FOR
    SELECT 
      FODSR_LAY.LISTINDEX,
      FODSR_LAY.DSR_ID,
      FODSR_LAY.TEXT
    FROM
      FODSR_LAY
    WHERE LISTINDEX IN(601,690)
    INTO
      :LISTINDEX,
      :DSR_ID,
      :TEXT
  DO
  BEGIN
    SELECT COUNT(*) FROM FODSR
    WHERE FODATE=:FODATE
      AND DSR_ID =:DSR_ID
      AND LISTINDEX=:LISTINDEX
   INTO: IROW ;
   IF (IROW=0) THEN
   BEGIN
     INSERT INTO FODSR(FODATE,LISTINDEX,DSR_ID,TEXT,AMOUNT)
     VALUES (:FODATE,:LISTINDEX,:DSR_ID,:TEXT,0);
   END

   /*Calculate From FO_DSR_LOAD_DETAIL  */
   SELECT SUM(NET) FROM FO_DSR_LOAD_DETAIL(:FODATE,:DSR_ID)
    INTO :AMT_DETAIL ;
   IF (AMT_DETAIL IS NULL) THEN AMT_dETAIL=0;
     SELECT AMOUNT FROM FODSR
     WHERE FODATE=:FODATE
       AND DSR_ID=:DSR_ID
       AND LISTINDEX=:LISTINDEX
    INTO :AMOUNT ;
    DELTA=:AMOUNT-AMT_DETAIL ;
    
    IF ((DELTA<>0) AND (PSAVE=1)) THEN
    BEGIN
        UPDATE FODSR SET AMOUNT=:AMT_DETAIL
         WHERE FODATE=:FODATE
        AND DSR_ID=:DSR_ID
        AND LISTINDEX=:LISTINDEX;
    END
  IF (DELTA<>0) THEN SUSPEND;
 END
END^


ALTER PROCEDURE XX_CHECK_PHONE_BOOK
RETURNS (
    PHONE VARCHAR(30),
    COUNTER INTEGER,
    NAME VARCHAR(120))
AS
DECLARE VARIABLE X INTEGER;
DECLARE VARIABLE S CHAR(4);
BEGIN
  FOR
    SELECT PHONE,COUNT(*) FROM PBX_CALL_LOG
    WHERE PHONE NOT IN ('00','001','108','147')
    AND DEPT <> ''
    GROUP BY PHONE

    INTO
      :PHONE,
      :COUNTER
  DO
  BEGIN
    IF (COUNTER > 2) THEN
    BEGIN
       X = 0;
       S = SUBSTR(PHONE,1,4);
       FOR SELECT DATA FROM FO_INFO_PHONE_LIST
           WHERE DATA LIKE '%'||:PHONE||'%'
           INTO NAME
       DO
       BEGIN
         IF (X = 0) THEN
         BEGIN
            IF (S = '0817') THEN
            BEGIN
               IF (NOT EXISTS(SELECT * FROM PBX_SLJJ WHERE SLJJ = :PHONE)) THEN
               BEGIN
                  INSERT INTO PBX_SLJJ (SLJJ,CITY,PBX_ZONE)
                  VALUES
                  (:PHONE,SUBSTR(:NAME,1,19),'7');
               END
            END
            SUSPEND;
         END
         X = X + 1;
       END
       IF (X =0) THEN
       BEGIN
          NAME = '';
          SUSPEND;
       END
    END
  END
END^


