      INNER JOIN SYSCUSTOMER ON (SYSCUSTOMERTYPE.CUSTOMERTYPE = SYSCUSTOMER.CUSTTYPE)
      WHERE CUSTOMERTYPE = :CUSTOMERTYPE1
      ORDER BY NAME,CUSTOMER

    INTO
      :CUSTAREA,
      :ADDRESS1,
      :CUSTTYPE,
      :ADDRESS2,
      :ADDRESS3,
      :ADDRESS4,
      :ADDRESS5,
      :PHONE,
      :FAX,
      :EMAIL,
      :PRICETYPE,
      :LASTORDER,
      :DUE,
      :CONTACT,
      :CONTACTTITLE,
      :TOTALAR,
      :ACCOUNT,
      :CREDITLIMIT,
      :CREDITFACILITY,
      :GL_DEPT,
      :GL_COST,
      :CREDITLIMIT_INVOICE,
      :COMPANYDEPT,
      :NOTE,
      :FLAG_ACTIVE,
      :CREATEUSER,
      :CREATEDATE,
      :EDITUSER,
      :EDITDATE,
      :SALESMAN,
      :INVOICE_CONTACT,
      :INVOICE_CONTACT_TITLE,
      :INVOICE_PHONE,
      :INVOICE_FAX,
      :INVOICE_EMAIL,
      :INVOICE_FORMAT,
      :MARKED,
      :ZIP,
      :CUSTOMER_MAIN,
      :CUSTOMER_RETAILER,
      :RELATION_DOCTYPE,
      :NIGHT_AVG,
      :NIGHT_FORECAST,
      :GRADE_AVG,
      :GRADE_FORECAST,
      :PROFILE_TYPE,
      :NAME,
      :CUSTOMERTYPE,
      :CUSTOMER
  DO
  BEGIN
  if (CREDITFACILITY = '0') then CREDITFACILITY = 'NO';
  if (CREDITFACILITY = '1') then CREDITFACILITY = 'YES';
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_COMPARE_CARD_AND_BUFFER(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CREDITCARD VARCHAR(6),
    BATCH INTEGER,
    TOTAL DOUBLE PRECISION,
    BUFF_TOTAL DOUBLE PRECISION,
    DELTA_BUFFER DOUBLE PRECISION)
AS
DECLARE VARIABLE OPENDATE DATE;
BEGIN
 IF (SDATE IS NULL) THEN
   BEGIN
    SDATE='1.11.2005';
    EDATE='30.11.2005';
   END
  FOR
     SELECT
        AR_CARD_JUR.CREDITCARD,
        AR_CARD_JUR.BATCH,
        sum(AR_CARD_JUR.TOTAL) total
     FROM   AR_CARD_JUR
     LEFT JOIN AR_CARD_BATCH ON AR_CARD_JUR.batch_number=AR_CARD_BATCH.batch
          WHERE AR_CARD_BATCH.OPENDATE BETWEEN '1.11.2005' AND '30.11.2005'
     GROUP by
       AR_CARD_JUR.CREDITCARD,
       AR_CARD_JUR.BATCH
     ORDER BY AR_CARD_JUR.CREDITCARD,AR_CARD_JUR.BATCH
    INTO
      :CREDITCARD,
      :BATCH,
      :TOTAL
  DO
  BEGIN
    SELECT SUM(CR) FROM GLBUFFER
    WHERE APPLICATION='AR'
      AND SOURCE='CCPY'
      AND NUMBER=:BATCH
    INTO :BUFF_TOTAL ;
    DELTA_BUFFER=TOTAL-BUFF_TOTAL ;
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_COMPARE_INCOME_AR(
    SDATE DATE)
RETURNS (
    TRANSDATE DATE,
    INCOME DOUBLE PRECISION,
    INCOME_BUFFER DOUBLE PRECISION,
    AR DOUBLE PRECISION,
    AR_BUFFER DOUBLE PRECISION)
AS
declare variable EDATE DATE ;
begin
  /* Procedure Text */
  if (SDATE IS NULL) then SDATE='1.10.2005';
  INCOME =0;
  INCOME_BUFFER =0;
  AR_BUFFER=0;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES EDATE  ;
  WHILE (SDATE<EDATE) DO
   BEGIN
    TRANSDATE=SDATE ;
    SELECT SUM(AMOUNT+ADJUSTMENT) FROM FODSR
    WHERE FODATE=:SDATE
      AND LISTINDEX IN(690,700)
      AND DSR_ID IN(690,700)
    INTO :INCOME ;
    
    SELECT SUM(TOTAL) FROM ARVCH
    WHERE OPENDATE=:SDATE
    INTO :AR ;
    if (AR IS NULL) then AR=0;

    SUSPEND;
    SDATE=SDATE+1;
   END
end^


ALTER PROCEDURE XX_DEPOSIT_CHECK
RETURNS (
    CUSTOMER VARCHAR(6),
    NAME VARCHAR(40),
    DEPOSIT_ENDING DOUBLE PRECISION,
    AGING DOUBLE PRECISION)
AS
BEGIN
  AGING = 0;
  FOR
    SELECT CUSTOMER,NAME,DEPOSIT_ENDING
    FROM AR_DEPOSIT_MUTATION(2006,4,'')

    INTO
      :CUSTOMER,
      :NAME,
      :DEPOSIT_ENDING
  DO
  BEGIN
    SUSPEND;
  END
  DEPOSIT_ENDING = 0;
  FOR
    SELECT CUSTOMER,NAME,SUM(BALANCE)
    FROM AR_DEPOSIT_AGING('30.4.2006')
    GROUP BY CUSTOMER,NAME

    INTO
      :CUSTOMER,
      :NAME,
      :AGING
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_FILL_REG_AUDIT
AS
declare variable FOLIO INTEGER;
declare variable FODATE DATE;
declare variable FOLIOSTATUS CHAR(1);
declare variable FOLIOSTATUS_SHARE CHAR(1);
declare variable FOLIOTYPE CHAR(1);
declare variable dateci date;
declare variable dateco date;
declare variable COMPANYNAME VARCHAR(40);
begin
  /*
     6-juni-2003
     untuk ada penambahan field di fo_hist_zregaudit
       * dateci
       * dateco
       * companyname
       * foliotype
       * foliostatus
       * foliostatus_share

     procedure ini digunakan untuk mengisi field-field di atas
     dijalankan cukup sekali saja
  */
  FOR SELECT FODATE,FOLIO FROM fo_hist_zregaudit
  ORDER BY FODATE,FOLIO
  INTO :FODATE,:FOLIO
  DO BEGIN
     FOLIOTYPE = Null;
     SELECT FOLIOTYPE,FOLIOSTATUS,FOLIOSTATUS_SHARE
     FROM FOSTAT_LOG
     WHERE FODATE = :FODATE
     AND FOLIO = :FOLIO
     INTO FOLIOTYPE,FOLIOSTATUS,FOLIOSTATUS_SHARE;
     
     if (FOLIOTYPE IS NULL) then
     BEGIN
        SELECT FOLIOTYPE,FOLIOSTATUS_SHARE
        FROM FOGUEST
        WHERE FOLIO = :FOLIO
        INTO FOLIOTYPE,FOLIOSTATUS_SHARE;
     END     
     
     if (FOLIOTYPE IS NULL) then
     BEGIN
        FOLIOTYPE = 'P';
        FOLIOSTATUS = 'G';
        FOLIOSTATUS_SHARE = 'M';
     END          
     
     SELECT DATECI,DATECO,COMPANYNAME FROM FO_RPT_HIST_GUESTNAME(:FOLIO)
     INTO DATECI,DATECO,COMPANYNAME;
     
     if (FOLIOTYPE IS NOT NULL) then
     BEGIN
        UPDATE fo_hist_zregaudit SET
        FOLIOTYPE = :FOLIOTYPE,
        FOLIOSTATUS = :FOLIOSTATUS,
        FOLIOSTATUS_SHARE = :FOLIOSTATUS_SHARE,
        DATECI = :DATECI,
        DATECO = :DATECO,
        COMPANYNAME = :COMPANYNAME
        WHERE FODATE = :FODATE AND FOLIO = :FOLIO;
     END
  END
end^


ALTER PROCEDURE XX_GLBUFFER_RECREATE_CREDITCARD(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER,
    USERID VARCHAR(8))
RETURNS (
    NUMBER INTEGER,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
begin
  IF (SDATE IS NULL) THEN
  BEGIN
     SELECT ARSYSDATE FROM FOSYSPARAM INTO EDATE;
     SDATE = '6.12.2005'; EDATE = '6.12.2005';
     PSAVE = 0;
  END
  IF (PSAVE = 1) THEN
  BEGIN
     DELETE FROM GLBUFFER WHERE APPLICATION = 'AR' AND SOURCE='CCPY'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
  END
  /* ------------------------------------------------------------------------ */
  /* CREDIT CARD BATCH RELEASE                                                */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM AR_CARD_BATCH
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND STATUS IN ('R','C','L')
      INTO NUMBER
  DO
  BEGIN
     FOR SELECT APPLICATION,SOURCE,INFO,TRANSDATE,ID,
                GL_ACCOUNT,GL_DEPT,GL_COST,
                ACCNAME,NOTE,REF,
                DEBIT,CREDIT,
                SETUP_INFO,SETUP_DATA,ERROR_TEXT,
                RELATION_CODE,RELATION_DOCTYPE
          FROM AR_GLBUFFER_CC_BATCH_RELEASE(:NUMBER)
     INTO APPLICATION,SOURCE,INFO,TRANSDATE,ID,
          GL_ACCOUNT,GL_DEPT,GL_COST,
          ACCNAME,NOTE,REF,
          DEBIT,CREDIT,
          SETUP_INFO,SETUP_DATA,ERROR_TEXT,
          RELATION_CODE,RELATION_DOCTYPE
     DO
     BEGIN
       IF (PSAVE = 1) THEN
       BEGIN
        insert into glbuffer
               (APPLICATION,SOURCE,NUMBER,ID,transdate,
                ACCOUNT,DEPT,COST,PROJECT,
                NOTE,REF,
                DB,CR,
                EXPORTDATE,EXPORTUSER,RELATION_CODE,RELATION_DOCTYPE)
        values (:application,:source,:number,:ID,:transdate,
                :GL_ACCOUNT,:GL_DEPT,:GL_COST,'',
                :NOTE,:REF,
                :DEBIT,:CREDIT,
                'now',:USERID,:RELATION_CODE,:RELATION_DOCTYPE);
       END
       ELSE SUSPEND;
     END
  END  
  /* ------------------------------------------------------------------------ */
  /* CREDIT CARD BATCH RECONCILE HANYA DISPLAY TIDAK DI PERNAH DI SAVE        */
  /* ------------------------------------------------------------------------ */
  IF (PSAVE = 0) THEN
  BEGIN
    FOR SELECT NUMBER FROM AR_CARD_BATCH
        WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
        AND STATUS = 'C'
        ORDER BY NUMBER
        INTO NUMBER
    DO
    BEGIN
       FOR SELECT APPLICATION,SOURCE,INFO,TRANSDATE,ID,
                  GL_ACCOUNT,GL_DEPT,GL_COST,
                  ACCNAME,NOTE,REF,
                  DEBIT,CREDIT,
                  SETUP_INFO,SETUP_DATA,ERROR_TEXT,
                  RELATION_CODE,RELATION_DOCTYPE
            FROM AR_GLBUFFER_CC_BATCH_RECONCILE(:NUMBER)
       INTO APPLICATION,SOURCE,INFO,TRANSDATE,ID,
            GL_ACCOUNT,GL_DEPT,GL_COST,
            ACCNAME,NOTE,REF,
            DEBIT,CREDIT,
            SETUP_INFO,SETUP_DATA,ERROR_TEXT,
            RELATION_CODE,RELATION_DOCTYPE
       DO
       BEGIN
         SUSPEND;
       END
     END
  END
  /* ------------------------------------------------------------------------ */
  /* CREDIT CARD MANUAL RELEASE                                               */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER FROM AR_CARD_JUR
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND GLSTATUS IN ('R','C')
      INTO NUMBER
  DO
  BEGIN
     FOR SELECT APPLICATION,SOURCE,INFO,TRANSDATE,ID,
                GL_ACCOUNT,GL_DEPT,GL_COST,
                ACCNAME,NOTE,REF,
                DEBIT,CREDIT,
                SETUP_INFO,SETUP_DATA,ERROR_TEXT,
                RELATION_CODE,RELATION_DOCTYPE
          FROM AR_GLBUFFER_CC_MANUAL_RELEASE(:NUMBER)
          ORDER BY ID
     INTO APPLICATION,SOURCE,INFO,TRANSDATE,ID,
          GL_ACCOUNT,GL_DEPT,GL_COST,
          ACCNAME,NOTE,REF,
          DEBIT,CREDIT,
          SETUP_INFO,SETUP_DATA,ERROR_TEXT,
          RELATION_CODE,RELATION_DOCTYPE
     DO
     BEGIN
       IF (PSAVE = 1) THEN
       BEGIN
        insert into glbuffer
               (APPLICATION,SOURCE,NUMBER,ID,transdate,
                ACCOUNT,DEPT,COST,PROJECT,
                NOTE,REF,
                DB,CR,
                EXPORTDATE,EXPORTUSER,RELATION_CODE,RELATION_DOCTYPE)
        values (:application,:source,:number,:ID,:transdate,
                :GL_ACCOUNT,:GL_DEPT,:GL_COST,'',
                :NOTE,:REF,
                :DEBIT,:CREDIT,
                'now',:USERID,:RELATION_CODE,:RELATION_DOCTYPE);
       END
       ELSE SUSPEND;
     END
  END
end^


ALTER PROCEDURE XX_HCS_UPDATE_INVALID_DAYUSE(
    PSAVE INTEGER)
RETURNS (
    FOLIO INTEGER,
    FODATE DATE,
    DATECI DATE,
    DATECO DATE,
    FOLIOTYPE CHAR(1),
    FOLIOSTATUS CHAR(1))
AS
BEGIN
  FOR
    SELECT L.FOLIO,L.FODATE,GS.DATECI,GS.DATECO,GS.FOLIOTYPE,
           GS.FOLIOSTATUS
    FROM FOSTAT_LOG L
    LEFT JOIN FOGUEST GS ON GS.FOLIO = L.FOLIO
    WHERE L.FOLIOTYPE = 'P'
    AND L.FOLIOSTATUS = 'O'
    AND L.FLAG_DAYUSE=1
    AND (GS.DATECI = GS.DATECO)
    AND (GS.DATECI <> L.FODATE)

    INTO
      :FOLIO,
      :FODATE,
      :DATECI,
      :DATECO,
      :FOLIOTYPE,
      :FOLIOSTATUS
  DO
  BEGIN
    IF (PSAVE = 1) THEN
       UPDATE FOSTAT_LOG SET FLAG_DAYUSE = 0 WHERE FOLIO = :FOLIO AND FODATE = :FODATE;
    ELSE SUSPEND;
  END
END^


ALTER PROCEDURE XX_INHOUSE_BOOKER
RETURNS (
    FOLIO INTEGER,
