    RATEDISCOUNT DOUBLE PRECISION,
    ROOMRATE DOUBLE PRECISION,
    COMPANY SMALLINT,
    COMPANYNAME VARCHAR(40),
    RESV_CONTACT VARCHAR(40),
    MEMBER VARCHAR(20),
    ST_MARKETSEGMENT VARCHAR(4),
    NOTE_CHECKIN BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    CREDITLIMIT DOUBLE PRECISION,
    FOLIOSTATUS_SHARE CHAR(1),
    FOLIO_MASTER INTEGER,
    ST_NATIONALITY VARCHAR(4),
    ST_NATIONALITY1 VARCHAR(4),
    ST_ORIGINAREA VARCHAR(4),
    FNAME VARCHAR(40),
    ST_RESV_SOURCE VARCHAR(4),
