    ROOMTYPE_UPGRADE VARCHAR(4),
    GROUPNUMBER INTEGER,
    PAX1 SMALLINT,
    VIPLEVEL SMALLINT)
AS
DECLARE VARIABLE FODATE DATE;
BEGIN

  SELECT FOSYSDATE FROM FOSYSPARAM WHERE ID = 1 INTO FODATE;
  
  FOR
    SELECT FOLIO,
               ROOM, ROOMTYPE,FULLNAMEF,
               DATECI,DATECO,ROOMNIGHT,PAX,
               RATECODE,RATEDISCOUNT,ROOMRATE,RATE_XBED
               COMPANY,COMPANYNAME,RESV_CONTACT,
               MEMBER, ST_MARKETSEGMENT,NOTE_CHECKIN,
               CREDITLIMIT,FOLIOSTATUS_SHARE,FOLIO_MASTER,ST_NATIONALITY,
               ST_NATIONALITY,ST_ORIGINAREA,FNAME,
               ST_RESV_SOURCE,BIRTHDAY,BLOCK,CHILD,RATE_XBED,ROOMTYPE_UPGRADE,
               GROUPNUMBER,PAX,VIPLEVEL
        FROM FOGUEST
        WHERE FOLIOTYPE = 'P'
        AND FOLIOSTATUS = 'I'
        AND FOLIOSTATUS_SHARE = 'M'
        AND DATECO > :FODATE
        ORDER BY ROOM

    INTO
      :FOLIO,
