      :ROOMTYPE,
      :FULLNAMEF,
      :DATECI,
      :DATECO,
      :ROOMNIGHT,
      :PAX,
      :RATECODE,
      :RATEDISCOUNT,
      :ROOMRATE,
      :COMPANY,
      :COMPANYNAME,
      :RESV_CONTACT,
      :MEMBER,
      :ST_MARKETSEGMENT,
      :NOTE_CHECKIN,
      :CREDITLIMIT,
      :FOLIOSTATUS_SHARE,
      :FOLIO_MASTER,
      :ST_NATIONALITY,
      :ST_NATIONALITY1,
      :ST_ORIGINAREA,
      :FNAME,
      :ST_RESV_SOURCE,
      :BIRTHDAY,
      :BLOCK,
      :CHILD,
      :RATE_XBED,
      :ROOMTYPE_UPGRADE,
      :GROUPNUMBER,
      :PAX1,
      :VIPLEVEL
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_INHOUSE_COMP(
    COMPANY VARCHAR(10))
RETURNS (
    FOLIO INTEGER,
    ROOM VARCHAR(8),
    ROOMTYPE VARCHAR(4),
    FULLNAMEF VARCHAR(80),
    DATECI DATE,
    DATECO DATE,
    ROOMNIGHT INTEGER,
    HISTORY INTEGER,
    PAX SMALLINT,
    RATECODE VARCHAR(12),
    RATEDISCOUNT DOUBLE PRECISION,
    ROOMRATE DOUBLE PRECISION,
    RATE_XBED SMALLINT,
    COMPANYNAME VARCHAR(40),
    MEMBER VARCHAR(20),
    ST_MARKETSEGMENT VARCHAR(4),
    NOTE_CHECKIN BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    CREDITLIMIT DOUBLE PRECISION,
    FOLIOSTATUS_SHARE CHAR(1),
    FOLIO_MASTER INTEGER,
    ST_NATIONALITY VARCHAR(4),
    ST_NATIONALITY1 VARCHAR(4),
    ST_ORIGINAREA VARCHAR(4),
    FNAME VARCHAR(40),
    ST_RESV_SOURCE VARCHAR(4),
    BIRTHDAY DATE,
    BLOCK VARCHAR(12),
    CHILD SMALLINT,
    RATE_XBED1 SMALLINT,
    ROOMTYPE_UPGRADE VARCHAR(4),
    GROUPNUMBER INTEGER,
    PAX1 SMALLINT,
    VIPLEVEL VARCHAR(8),
    SALES_GROUP_INDEX INTEGER,
    SALES_GROUP_NAME VARCHAR(40))
AS
declare variable FOSYSDATE DATE;
BEGIN
  SELECT FOSYSDATE FROM FOSYSPARAM INTO :FOSYSDATE;
  
  SALES_GROUP_INDEX = 0;
  SALES_GROUP_NAME = 'Paying Rooms';
  
  FOR
    SELECT GS.FOLIO,GS.ROOM, GS.ROOMTYPE,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.ROOMNIGHT,GS.HISTORY,GS.PAX,GS.RATECODE,GS.RATEDISCOUNT,GS.ROOMRATE,GS.RATE_XBED,GS.COMPANY,GS.COMPANYNAME,GS.MEMBER, GS.ST_MARKETSEGMENT,GS.NOTE_CHECKIN,GS.CREDITLIMIT,GS.FOLIOSTATUS_SHARE,GS.FOLIO_MASTER,GS.ST_NATIONALITY,GS.ST_NATIONALITY,GS.ST_ORIGINAREA,FNAME,GS.ST_RESV_SOURCE,GS.BIRTHDAY,GS.BLOCK,GS.CHILD,GS.RATE_XBED,GS.ROOMTYPE_UPGRADE,GS.GROUPNUMBER,GS.PAX,GS.VIPLEVEL
        FROM FOGUEST GS
        LEFT JOIN SYSCUSTOMER SC ON SC.CUSTOMER = GS.COMPANY
        WHERE GS.COMPANY = :COMPANY
        AND GS.FOLIOTYPE = 'P'
        AND GS.FOLIOSTATUS = 'I'
        AND GS.FOLIOSTATUS_SHARE = 'M'
        AND GS.RATECODE <> 'HU'
        AND GS.RATECODE NOT LIKE 'COMPL%'
        ORDER BY ROOM

    INTO
      :FOLIO,
      :ROOM,
      :ROOMTYPE,
      :FULLNAMEF,
      :DATECI,
      :DATECO,
      :ROOMNIGHT,
      :HISTORY,
      :PAX,
      :RATECODE,
      :RATEDISCOUNT,
      :ROOMRATE,
      :RATE_XBED,
      :COMPANY,
      :COMPANYNAME,
      :MEMBER,
      :ST_MARKETSEGMENT,
      :NOTE_CHECKIN,
      :CREDITLIMIT,
      :FOLIOSTATUS_SHARE,
      :FOLIO_MASTER,
      :ST_NATIONALITY,
      :ST_NATIONALITY1,
      :ST_ORIGINAREA,
      :FNAME,
      :ST_RESV_SOURCE,
      :BIRTHDAY,
      :BLOCK,
      :CHILD,
      :RATE_XBED1,
      :ROOMTYPE_UPGRADE,
      :GROUPNUMBER,
      :PAX1,
      :VIPLEVEL
  DO
  BEGIN
  if ( VIPLEVEL = '0') then VIPLEVEL = '-';
  if ( VIPLEVEL = '1') then VIPLEVEL = 'VIP1';
  if ( VIPLEVEL = '2') then VIPLEVEL = 'VIP2';
  if ( VIPLEVEL = '3') then VIPLEVEL = 'VIP3';
    SUSPEND;
  END
  
  SALES_GROUP_INDEX = 1;
  SALES_GROUP_NAME = 'COMPLIMENT & HOUSE USE';

  FOR
    SELECT GS.FOLIO,GS.ROOM, GS.ROOMTYPE,GS.FULLNAMEF,GS.DATECI,GS.DATECO,GS.ROOMNIGHT,GS.HISTORY,GS.PAX,GS.RATECODE,GS.RATEDISCOUNT,GS.ROOMRATE,GS.RATE_XBED,GS.COMPANY,GS.COMPANYNAME,GS.MEMBER, GS.ST_MARKETSEGMENT,GS.NOTE_CHECKIN,GS.CREDITLIMIT,GS.FOLIOSTATUS_SHARE,GS.FOLIO_MASTER,GS.ST_NATIONALITY,GS.ST_NATIONALITY,GS.ST_ORIGINAREA,FNAME,GS.ST_RESV_SOURCE,GS.BIRTHDAY,GS.BLOCK,GS.CHILD,GS.RATE_XBED,GS.ROOMTYPE_UPGRADE,GS.GROUPNUMBER,GS.PAX,GS.VIPLEVEL
        FROM FOGUEST GS
        LEFT JOIN SYSCUSTOMER SC ON SC.CUSTOMER = GS.COMPANY
        WHERE GS.COMPANY = :COMPANY
        AND GS.FOLIOTYPE = 'P'
        AND GS.FOLIOSTATUS = 'I'
        AND GS.FOLIOSTATUS_SHARE = 'M'
        AND ((RATECODE = 'HU') OR (RATECODE LIKE 'COMPL%'))
        ORDER BY ROOM

    INTO
      :FOLIO,
      :ROOM,
      :ROOMTYPE,
      :FULLNAMEF,
      :DATECI,
      :DATECO,
      :ROOMNIGHT,
      :HISTORY,
      :PAX,
      :RATECODE,
      :RATEDISCOUNT,
      :ROOMRATE,
      :RATE_XBED,
      :COMPANY,
      :COMPANYNAME,
      :MEMBER,
      :ST_MARKETSEGMENT,
      :NOTE_CHECKIN,
      :CREDITLIMIT,
      :FOLIOSTATUS_SHARE,
      :FOLIO_MASTER,
      :ST_NATIONALITY,
      :ST_NATIONALITY1,
      :ST_ORIGINAREA,
      :FNAME,
      :ST_RESV_SOURCE,
      :BIRTHDAY,
      :BLOCK,
      :CHILD,
      :RATE_XBED1,
      :ROOMTYPE_UPGRADE,
      :GROUPNUMBER,
      :PAX1,
      :VIPLEVEL
  DO
  BEGIN
  if ( VIPLEVEL = '0') then VIPLEVEL = '-';
  if ( VIPLEVEL = '1') then VIPLEVEL = 'VIP1';
  if ( VIPLEVEL = '2') then VIPLEVEL = 'VIP2';
  if ( VIPLEVEL = '3') then VIPLEVEL = 'VIP3';
    SUSPEND;
  END
END^


