    FROM FOGUEST
        WHERE FOLIOTYPE = 'P'
        AND FOLIOSTATUS = 'I'
        AND FOLIOSTATUS_SHARE = 'M'
        AND ((RATECODE = 'HU') OR (RATECODE LIKE 'COMPL%'))
        ORDER BY ROOM

    INTO
      :ROOM,
      :FULLNAMEF,
      :ROOMTYPE,
      :FOLIO,
      :PAX,
      :DATECI,
      :DATECO,
      :NOTE_CHECKIN,
      :ROOMNIGHT,
      :ST_NATIONALITY,
      :ST_ORIGINAREA,
      :VIPLEVEL
  DO
  BEGIN
  if ( VIPLEVEL = '0') then VIPLEVEL = '-';
  if ( VIPLEVEL = '1') then VIPLEVEL = 'VIP1';
  if ( VIPLEVEL = '2') then VIPLEVEL = 'VIP2';
  if ( VIPLEVEL = '3') then VIPLEVEL = 'VIP3';
    SUSPEND;

  END
END^


