ALTER PROCEDURE XX_LOAD_DSR(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    TANGGAL DATE,
    LINE INTEGER,
    XTYPE CHAR(1),
    TODAY DOUBLE PRECISION,
    CASH DOUBLE PRECISION,
    ADJUST DOUBLE PRECISION,
    MTD DOUBLE PRECISION,
    YTD DOUBLE PRECISION)
AS
DECLARE VARIABLE VCOUNT INTEGER;
DECLARE VARIABLE VTEXT VARCHAR(40);
DECLARE VARIABLE VDSRID INTEGER;
BEGIN
  if (SDATE IS NULL) then
     BEGIN
       SDATE='8.2.2005';
       EDATE='28.2.2005';
     END
  FOR
    SELECT XDSR.TANGGAL,
           XDSR.LINE,
           XDSR.XTYPE,
           XDSR.TODAY,
           XDSR.CASH,
           XDSR.ADJUST,
           XDSR.MTD,
           XDSR.YTD
    FROM XDSR
    WHERE TANGGAL BETWEEN :SDATE AND :EDATE
    ORDER BY XDSR.LINE
    INTO
      :TANGGAL,
      :LINE,
      :XTYPE,
      :TODAY,
      :CASH,
      :ADJUST,
      :MTD,
      :YTD
  DO
  BEGIN
     if (EXISTS(SELECT * FROM FODSR_LAY WHERE LISTINDEX=:LINE )) then
        BEGIN 
         SELECT TEXT,DSR_ID FROM FODSR_LAY WHERE LISTINDEX=:LINE INTO :VTEXT,:VDSRID ;
         IF (NOT EXISTS(SELECT * FROM FODSR WHERE FODATE BETWEEN :SDATE AND :EDATE)) THEN
           BEGIN
               INSERT INTO FODSR(FODATE,LISTINDEX,DSR_ID,TEXT,AMOUNT,ADJUSTMENT,MTD,YTD)
                VALUES (:TANGGAL,:LINE,:VDSRID,:VTEXT,:TODAY,:ADJUST,:MTD,:YTD);
           END
/*        ELSE
           BEGIN*/
             UPDATE FODSR SET AMOUNT=:TODAY,ADJUSTMENT=:ADJUST,MTD=:MTD,YTD=:YTD
             WHERE LISTINDEX=:LINE
             AND FODATE =:TANGGAL;
/*         END*/
         SUSPEND;
       END
  END
END^


