ALTER PROCEDURE XX_REKANAN(
    XFOLIO INTEGER)
RETURNS (
    FOLIO INTEGER,
    NAME VARCHAR(80),
    NAMEREMARK VARCHAR(161),
    ID INTEGER,
    MENU INTEGER,
    QTY DOUBLE PRECISION,
    COST DOUBLE PRECISION,
    PRICE DOUBLE PRECISION,
    CALC_COST DOUBLE PRECISION,
    CALC_PRICE DOUBLE PRECISION,
    REMARK VARCHAR(80))
AS
BEGIN
    FOLIO=0;
    NAME='';
    NAMEREMARK='';
    ID=0;
    MENU=0;
    QTY=0;
    COST=0;
    PRICE=0;
    CALC_COST=0;
    CALC_PRICE=0;
    REMARK='';
  SUSPEND ;
  FOR
    SELECT 
      B.ID,
      B.MENU,
      B.QTY,
      B.COST,
      B.PRICE,
      B.CALC_COST,
      B.CALC_PRICE,
      B.REMARK,
      M.NAME
    FROM
      BQ_MASTER_MEAL_MENU B
      LEFT JOIN BQ_MENU M ON (B.MENU = M.MENU_ID)
    WHERE
      (B.FOLIO = :XFOLIO) AND
      (M.MENU_TYPE = 'PDKR')
    ORDER BY
      M.NAME
    INTO
      :ID,
      :MENU,
      :QTY,
      :COST,
      :PRICE,
      :CALC_COST,
      :CALC_PRICE,
      :REMARK,:NAME
  DO
  BEGIN
   SELECT ML.FOLIO FROM BQ_MASTER_MEAL ML WHERE ID=:ID INTO :FOLIO ;
    NAMEREMARK = SUBSTR(:NAME,1,25) || ' ' ||SUBSTR(REMARK,1,15);
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_ROOMSTATISTIC_ADJUST
AS
declare variable FODATE DATE;
declare variable PFOLIO integer;
declare variable AMOUNT DOUBLE PRECISION;
declare variable HAMOUNT DOUBLE PRECISION;
declare variable CAT_ADJ_ROOM VARCHAR(4);
declare variable CAT_ADJ_ROOMTAX VARCHAR(4);
begin
  /* ------------------------------------------------------------------------ */
  /* ROOM ADJUSTMENT CATEGORY                                                 */
  /* ------------------------------------------------------------------------ */
  SELECT CATEGORY FROM fosys_category
  WHERE CAT_ID = 'ADJUSTROOMONLY'
  INTO CAT_ADJ_ROOM;
  
  SELECT CATEGORY FROM fosys_category
  WHERE CAT_ID = 'ADJUSTROOMTAX'
  INTO CAT_ADJ_ROOMTAX;  
  
  if (CAT_ADJ_ROOM IS NULL) then CAT_ADJ_ROOM = '?';
  if (CAT_ADJ_ROOMTAX IS NULL) then CAT_ADJ_ROOMTAX = '?';

  /* ------------------------------------------------------------------------ */
  /* PACKAGE ADJUSTMENT                                                       */
  /* ------------------------------------------------------------------------ */  
  AMOUNT = 0;
  FOR SELECT FODATE FROM fo_hist_zrs
  INTO :FODATE
  DO
  BEGIN
     SELECT SUM(JR.DEBIT-JR.CREDIT) FROM foguest_jur JR
     WHERE JR.FODATE = :FODATE
     AND ((JR.CATEGORY = :CAT_ADJ_ROOM) or (JR.CATEGORY =:CAT_ADJ_ROOMTAX))
     INTO :AMOUNT;
     if (AMOUNT IS NULL) then AMOUNT = 0;

     SELECT SUM(JR.DEBIT-JR.CREDIT) FROM fo_hist_jur JR
     WHERE JR.FODATE = :FODATE
     AND ((JR.CATEGORY = :CAT_ADJ_ROOM) or (JR.CATEGORY =:CAT_ADJ_ROOMTAX))
     INTO :HAMOUNT;
     if (HAMOUNT IS NULL) then HAMOUNT = 0;
     
     UPDATE fo_hist_zrs SET ROOMADJUST_PACKAGE = :AMOUNT+:HAMOUNT WHERE FODATE = :FODATE;
  END
  
  
  
  FOR SELECT FOLIO,FODATE FROM fostat_log
  INTO :PFOLIO,:FODATE
  DO
  BEGIN
     SELECT SUM(JR.DEBIT-JR.CREDIT) FROM foguest_jur JR
     WHERE (JR.FOLIO_ORIGINAL = :PFOLIO)
     AND JR.FODATE = :FODATE
     AND ((JR.CATEGORY = :CAT_ADJ_ROOM) or (JR.CATEGORY =:CAT_ADJ_ROOMTAX))
     INTO :AMOUNT;
     if (AMOUNT IS NULL) then AMOUNT = 0;

     SELECT SUM(JR.DEBIT-JR.CREDIT) FROM fo_hist_jur JR
     WHERE (JR.FOLIO_ORIGINAL = :PFOLIO)
     AND JR.FODATE = :FODATE
     AND ((JR.CATEGORY = :CAT_ADJ_ROOM) or (JR.CATEGORY =:CAT_ADJ_ROOMTAX))
     INTO :HAMOUNT;
     if (HAMOUNT IS NULL) then HAMOUNT = 0;
     
     UPDATE fostat_log SET ROOMADJUST_PACKAGE = :AMOUNT+:HAMOUNT
     WHERE FOLIO = :PFOLIO AND FODATE = :FODATE;
  END  
END^


ALTER PROCEDURE XX_RPT(
    SCUST VARCHAR(6),
    ECUST VARCHAR(6))
RETURNS (
    ACCOUNT VARCHAR(20),
    ADDRESS1 VARCHAR(40),
    ADDRESS2 VARCHAR(40),
    CONTACT VARCHAR(40),
    CONTACTTITLE VARCHAR(40),
    CUSTAREA VARCHAR(4),
    CUSTOMER VARCHAR(6),
    CUSTTYPE VARCHAR(4),
    FAX VARCHAR(40),
    NAME VARCHAR(40),
    PHONE VARCHAR(40),
    SALESMAN VARCHAR(8),
    ZIP VARCHAR(6),
    RATECODE VARCHAR(12),
    RNIGHT DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT ACCOUNT,ADDRESS1,ADDRESS2,
           CONTACT,CONTACTTITLE,CUSTAREA,
           CUSTOMER,CUSTTYPE,FAX,
           NAME,PHONE,SALESMAN,
           ZIP,C.RATECODE
    FROM SYSCUSTOMER S
    LEFT JOIN FO_CUST_RATE C ON S.CUSTOMER = C.CUSTOMER
    WHERE CUSTOMER BETWEEN :SCUST AND :ECUST
    ORDER BY CUSTOMER

    INTO
      :ACCOUNT,
      :ADDRESS1,
      :ADDRESS2,
      :CONTACT,
      :CONTACTTITLE,
      :CUSTAREA,
      :CUSTOMER,
      :CUSTTYPE,
      :FAX,
      :NAME,
      :PHONE,
      :SALESMAN,
      :ZIP,
      :RATECODE
  DO
  BEGIN
    SELECT SUM(NIGHT) FROM FOSTAT_LOG
    WHERE PYEAR='2004'
      AND PMONTH='1'
      AND COMPANY = :CUSTOMER
      PLAN (FOSTAT_LOG INDEX (FOSTAT_LOG_IDX_PMCOMPANY))
    INTO :RNIGHT ;
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_RPT_HIST_INHOUSE(
    SDATE DATE)
RETURNS (
    FOLIO INTEGER,
    DATECI DATE,
    DATECO DATE,
    GUESTNAME VARCHAR(80),
    COMPANY VARCHAR(6),
    COMPANYNAME VARCHAR(40),
    FOLIO_MASTER INTEGER,
    GROUPNUMBER INTEGER,
    FOLIOTYPE CHAR(1),
    FOLIOSTATUS CHAR(1),
    FOLIOSTATUS_SHARE CHAR(1),
    ROOMTYPE VARCHAR(4),
    RATECODE VARCHAR(12),
    RATEDISCOUNT NUMERIC(15,4),
    ROOMRATE DOUBLE PRECISION,
    HISTORY INTEGER,
    ST_RESV_SOURCE VARCHAR(4),
    ST_NATIONALITY VARCHAR(4),
    ST_MARKETSEGMENT VARCHAR(4),
    ST_ORIGINAREA VARCHAR(4),
    ROOMNIGHT INTEGER,
    PAX SMALLINT,
    CHILD SMALLINT,
    ROOM VARCHAR(8),
    PACKAGE DOUBLE PRECISION,
    RATE_DISCOUNT DOUBLE PRECISION,
    ROOMREVENUE DOUBLE PRECISION,
    DAYUSE_REVENUE DOUBLE PRECISION,
    RACKRATE DOUBLE PRECISION,
    DATECI_ACTUAL DATE,
    DATECO_ACTUAL DATE,
    RATE_XBED DOUBLE PRECISION,
    HOUR_CI INTEGER,
    HOUR_CO INTEGER,
    FLAG_WALKIN INTEGER,
    RELATION_DOCTYPE INTEGER,
    HIST_NO_STAY INTEGER,
    HIST_NO_NIGHT INTEGER,
    PAYING_TYPE INTEGER,
    PAYING_NAME VARCHAR(20))
AS
BEGIN
  if (SDATE IS NULL) then
     SELECT FOSYSDATE-2 FROM FOSYSPARAM INTO :SDATE;
  FOR
    SELECT LOG.FOLIO,
           LOG.FOLIO_MASTER,
           LOG.GROUPNUMBER,
           LOG.FOLIOTYPE,
           LOG.FOLIOSTATUS,
           LOG.FOLIOSTATUS_SHARE,
           LOG.ROOMTYPE,
           LOG.RATECODE,
           LOG.RATEDISCOUNT,
           LOG.ROOMRATE,
           LOG.HISTORY,
           LOG.ST_RESV_SOURCE,
           LOG.ST_NATIONALITY,
           LOG.ST_MARKETSEGMENT,
           LOG.ST_ORIGINAREA,
           LOG.PAX,
           LOG.CHILD,
           LOG.ROOM,
           LOG.PACKAGE,
           LOG.RATE_DISCOUNT,
           LOG.ROOMREVENUE,
           LOG.DAYUSE_REVENUE1 + LOG.DAYUSE_REVENUE2,
           LOG.RACKRATE
    FROM FOSTAT_LOG LOG
    WHERE LOG.FOLIOTYPE = 'P'
    AND LOG.FOLIOSTATUS = 'I'
    AND LOG.FODATE = :SDATE
    ORDER BY LOG.ROOM
    INTO
      :FOLIO,
      :FOLIO_MASTER,
      :GROUPNUMBER,
      :FOLIOTYPE,
      :FOLIOSTATUS,
      :FOLIOSTATUS_SHARE,
      :ROOMTYPE,
      :RATECODE,
      :RATEDISCOUNT,
      :ROOMRATE,
      :HISTORY,
      :ST_RESV_SOURCE,
      :ST_NATIONALITY,
      :ST_MARKETSEGMENT,
      :ST_ORIGINAREA,
      :PAX,
      :CHILD,
      :ROOM,
      :PACKAGE,
      :RATE_DISCOUNT,
      :ROOMREVENUE,
      :DAYUSE_REVENUE,
      :RACKRATE
  DO
  BEGIN
    SELECT GUESTNAME,COMPANYNAME,DATECI,DATECO,WALKIN,COMPANY,RELATION_DOCTYPE FROM fo_rpt_hist_guestname(:FOLIO)
    INTO :GUESTNAME,:COMPANYNAME,:DATECI,:DATECO,FLAG_WALKIN,COMPANY,RELATION_DOCTYPE;

    DATECO_ACTUAL = NULL;
    DATECI_ACTUAL = NULL;

    SELECT DATECI_ACTUAL,DATECO_ACTUAL,RATE_XBED FROM FOGUEST WHERE FOLIO = :FOLIO
    INTO DATECI_ACTUAL,DATECO_ACTUAL,RATE_XBED;

    if (DATECI_ACTUAL IS NULL) then
       SELECT DATECI_ACTUAL,DATECO_ACTUAL,RATE_XBED FROM FO_HIST_STAY WHERE FOLIO = :FOLIO
       INTO DATECI_ACTUAL,DATECO_ACTUAL,RATE_XBED;

    HOUR_CI = EXTRACT(HOUR FROM DATECI_ACTUAL);
    HOUR_CO = EXTRACT(HOUR FROM DATECO_ACTUAL);

    ROOMNIGHT = DATECO-DATECI;

    /* ---------------------------------------------------------------- */
    /* 10 JUN 2008                                                      */
    /* ---------------------------------------------------------------- */
    IF (EXISTS(SELECT * FROM FO_HIST_GUEST WHERE HISTORY = :HISTORY)) THEN
    BEGIN
       SELECT TOTAL_STAY,TOTAL_ROOMNIGHT FROM FO_HIST_GUEST
       WHERE HISTORY = :HISTORY
       INTO HIST_NO_STAY,HIST_NO_NIGHT;
    END
    ELSE
    BEGIN
       HIST_NO_STAY = 0;
       HIST_NO_NIGHT = 0;
    END
    /* ---------------------------------------------------------------- */
    /* END OF 10 JUN 2008                                               */
    /* ---------------------------------------------------------------- */
    /* 14 NOV 2008                                                      */
    /* ---------------------------------------------------------------- */
    IF (RATECODE = 'HU') THEN
    BEGIN
       PAYING_TYPE = 2;
       PAYING_NAME = 'House Use';
    END
    ELSE IF (RATECODE LIKE 'COMPL%') THEN
    BEGIN
       PAYING_TYPE = 1;
       PAYING_NAME = 'Compliment';
    END
    ELSE
    BEGIN
       PAYING_TYPE = 0;
       PAYING_NAME = 'Paying Room';
    END
    /* ---------------------------------------------------------------- */
    /* END OF 14 NOV 2008                                               */
    /* ---------------------------------------------------------------- */

    SUSPEND;
  END
END^


ALTER PROCEDURE XX_RPT_ROOM_CHARGE(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    FODATE DATE,
    FOLIO INTEGER,
    DATECI DATE,
    DATECO DATE,
    GUESTNAME VARCHAR(80),
    COMPANY VARCHAR(6),
    COMPANYNAME VARCHAR(40),
    ROOM VARCHAR(6),
    ROOMTYPE VARCHAR(4),
    PAX INTEGER,
    CHILD INTEGER,
    RATE DOUBLE PRECISION,
    DISCOUNT DOUBLE PRECISION,
    EXTRABED DOUBLE PRECISION,
    EXCLUDED DOUBLE PRECISION)
AS
DECLARE VARIABLE CAT_EXTRABED VARCHAR(4);
BEGIN
  SDATE = SDATE;
  EDATE = EDATE;
  
  SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'EXTRABED'
  INTO CAT_EXTRABED;

  FOR
    SELECT FOLIO FROM FOSTAT_LOG
    WHERE FODATE BETWEEN :SDATE AND :EDATE
    AND FOLIOTYPE = 'P'
    AND FOLIOSTATUS = 'I'
    AND FOLIOSTATUS_SHARE = 'M'
    GROUP BY FOLIO
    INTO
      :FOLIO
  DO
  BEGIN
    SELECT GUESTNAME,COMPANYNAME,DATECI,DATECO,COMPANY,ROOM,
           ROOMTYPE,PAX,CHILD
    FROM fo_rpt_hist_guestname (:FOLIO)
    INTO GUESTNAME,:COMPANYNAME,:DATECI,:DATECO,COMPANY,ROOM,
         ROOMTYPE,PAX,CHILD;

    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE BETWEEN :SDATE AND :EDATE
    AND JURCODE = 'NA'
    AND PACKAGE_CODE = 'RATE'
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO RATE;
    IF (RATE IS NULL) THEN RATE = 0;
    
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE BETWEEN :SDATE AND :EDATE
    AND JURCODE = 'NA'
    AND (REMARK LIKE 'Discount%')
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO DISCOUNT;
    IF (DISCOUNT IS NULL) THEN DISCOUNT = 0;
    
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE BETWEEN :SDATE AND :EDATE
    AND JURCODE = 'NA'
    AND CATEGORY = :CAT_EXTRABED
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO EXTRABED;
    IF (EXTRABED IS NULL) THEN EXTRABED = 0;
    
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE BETWEEN :SDATE AND :EDATE
    AND JURCODE = 'NA'
    AND HIDDEN = 0
    AND PACKAGE_CODE <> 'RATE'
    AND (REMARK NOT LIKE 'Discount%')
    AND CATEGORY <> :CAT_EXTRABED
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO EXCLUDED;
    IF (EXCLUDED IS NULL) THEN EXCLUDED = 0;
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_RPT_ROOM_CHARGE_PER_DAY(
    SDATE DATE)
RETURNS (
    FOLIO INTEGER,
    DATECI DATE,
    DATECO DATE,
    GUESTNAME VARCHAR(80),
    COMPANY VARCHAR(6),
    COMPANYNAME VARCHAR(40),
    ROOM VARCHAR(6),
    ROOMTYPE VARCHAR(4),
    PAX INTEGER,
    CHILD INTEGER,
    RATE DOUBLE PRECISION,
    DISCOUNT DOUBLE PRECISION,
    EXTRABED DOUBLE PRECISION,
    EXCLUDED DOUBLE PRECISION)
AS
DECLARE VARIABLE CAT_EXTRABED VARCHAR(4);
BEGIN
  SDATE = SDATE;
  
  SELECT CATEGORY FROM FOSYS_CATEGORY WHERE CAT_ID = 'EXTRABED'
  INTO CAT_EXTRABED;

  FOR
    SELECT FOLIO FROM FOSTAT_LOG
    WHERE FODATE = :SDATE
    AND FOLIOTYPE = 'P'
    AND FOLIOSTATUS = 'I'
    AND FOLIOSTATUS_SHARE = 'M'
    GROUP BY FOLIO
    INTO
      :FOLIO
  DO
  BEGIN
    SELECT GUESTNAME,COMPANYNAME,DATECI,DATECO,COMPANY,ROOM,
           ROOMTYPE,PAX,CHILD
    FROM fo_rpt_hist_guestname(:FOLIO)
    INTO GUESTNAME,:COMPANYNAME,:DATECI,:DATECO,COMPANY,ROOM,
         ROOMTYPE,PAX,CHILD;

    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE = :SDATE
    AND JURCODE = 'NA'
    AND PACKAGE_CODE = 'RATE'
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO RATE;
    IF (RATE IS NULL) THEN RATE = 0;
    
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE = :SDATE
    AND JURCODE = 'NA'
    AND (REMARK LIKE 'Discount%')
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO DISCOUNT;
    IF (DISCOUNT IS NULL) THEN DISCOUNT = 0;
    
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE = :SDATE
    AND JURCODE = 'NA'
    AND CATEGORY = :CAT_EXTRABED
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO EXTRABED;
    IF (EXTRABED IS NULL) THEN EXTRABED = 0;
    
    SELECT SUM(DEBIT-CREDIT) FROM FOGUEST_JUR
    WHERE FOLIO_ORIGINAL = :FOLIO
    AND FODATE = :SDATE
    AND JURCODE = 'NA'
    AND HIDDEN = 0
    AND PACKAGE_CODE <> 'RATE'
    AND (REMARK NOT LIKE 'Discount%')
    AND CATEGORY <> :CAT_EXTRABED
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_FOLIO_ORIGINAL))
    INTO EXCLUDED;
    IF (EXCLUDED IS NULL) THEN EXCLUDED = 0;
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_RPT_TODAY_RESV_CI
RETURNS (
    ST_NATIONALITY VARCHAR(4),
    FOLIO INTEGER,
    FULLNAMEF VARCHAR(80),
    ROOM VARCHAR(8),
    ROOMTYPE VARCHAR(4),
    DATECI DATE,
    DATECO DATE,
    DATERESV DATE,
    DATECI_ACTUAL DATE,
    ROOMNIGHT INTEGER,
    PAX SMALLINT,
    COMPANY VARCHAR(6),
    COMPANYNAME VARCHAR(40),
    ST_MARKETSEGMENT VARCHAR(4),
    FOLIOSTATUS_SHARE CHAR(1),
    FOLIO_MASTER INTEGER,
    NOTE_CASHIER BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    ST_ORIGINAREA VARCHAR(4),
    BIRTHDAY DATE,
    ADDRESS BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    IDNUMBER VARCHAR(40),
    RATECODE VARCHAR(12))
AS
DECLARE VARIABLE FOSYSDATE DATE;
BEGIN

SELECT FOSYSDATE FROM FOSYSPARAM INTO :FOSYSDATE;

  FOR
    SELECT ST_NATIONALITY,
           FOLIO,FULLNAMEF,
           ROOM, ROOMTYPE,
           DATECI,DATECO,DATERESV,DATECI_ACTUAL,ROOMNIGHT,PAX,
           COMPANY,COMPANYNAME,
           ST_MARKETSEGMENT,
           FOLIOSTATUS_SHARE,FOLIO_MASTER,NOTE_CASHIER,
           ST_ORIGINAREA,
           BIRTHDAY,ADDRESS,
           IDNUMBER,RATECODE
    FROM FOGUEST
    WHERE FOLIOTYPE = 'P'
    AND FOLIOSTATUS IN ('I','C','T','G')
    AND FOLIOSTATUS_SHARE ='M'
    AND DATECI = :FOSYSDATE
    AND (EXTRACT (DAY FROM DATERESV) = EXTRACT (DAY FROM DATECI_ACTUAL))
    AND (EXTRACT (MONTH FROM DATERESV) = EXTRACT (MONTH FROM DATECI_ACTUAL))
    AND (EXTRACT (YEAR FROM DATERESV) = EXTRACT (YEAR FROM DATECI_ACTUAL))
    ORDER BY ST_NATIONALITY,FULLNAMEF

    INTO
      :ST_NATIONALITY,
      :FOLIO,
      :FULLNAMEF,
      :ROOM,
      :ROOMTYPE,
      :DATECI,
      :DATECO,
      :DATERESV,
      :DATECI_ACTUAL,
      :ROOMNIGHT,
      :PAX,
      :COMPANY,
      :COMPANYNAME,
      :ST_MARKETSEGMENT,
      :FOLIOSTATUS_SHARE,
      :FOLIO_MASTER,
      :NOTE_CASHIER,
      :ST_ORIGINAREA,
      :BIRTHDAY,
      :ADDRESS,
      :IDNUMBER,
      :RATECODE
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_UPDATE_AR_ADJ_ACCOUNT(
    PSAVE INTEGER,
    SNUMBER INTEGER,
    ENUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    CUSTOMER VARCHAR(20),
    ACCOUNT VARCHAR(20),
    CUSTTYPE VARCHAR(10),
    TYPEACCOUNT VARCHAR(40))
AS
BEGIN
  FOR
    SELECT A.NUMBER,A.CUSTOMER,A.ACCOUNT,S.custtype FROM ARADJ A
    LEFT JOIN SYSCUSTOMER S ON A.CUSTOMER=S.CUSTOMER
    WHERE A.NUMBER BETWEEN :SNUMBER AND :ENUMBER
    INTO
      :NUMBER,
      :CUSTOMER,
      :ACCOUNT,
      :CUSTTYPE
  DO
  BEGIN
    SELECT GLACCOUNT FROM syscustomertype
    WHERE CUSTOMERTYPE=:CUSTTYPE
    INTO:TYPEACCOUNT;
    
   IF (PSAVE=1) THEN
     BEGIN
       IF (TYPEACCOUNT<>:ACCOUNT) THEN
        BEGIN
          UPDATE ARADJ SET ACCOUNT=:TYPEACCOUNT
           WHERE NUMBER=:NUMBER ;
        END
     END
    SUSPEND;
  END
END^


ALTER PROCEDURE XX_UPDATE_DATERESV
RETURNS (
    DATECI DATE,
    DATECO DATE,
    DATERESV DATE,
    DATECREATE DATE,
    FOLIO INTEGER,
    GROUPNUMBER INTEGER)
AS
BEGIN
  FOR
    SELECT DATECI,DATECO,DATERESV,DATECREATE,FOLIO,GROUPNUMBER
    FROM FOGUEST WHERE FOLIOTYPE = 'P'
    AND FOLIOSTATUS_SHARE = 'M'
    AND FOLIOSTATUS IN ('I','C','G','W','T')
    INTO
      :DATECI,
      :DATECO,
      :DATERESV,
      :DATECREATE,
      :FOLIO,
      :GROUPNUMBER
  DO
  BEGIN
    DATECREATE = EXTRACT(DAY FROM DATECREATE) || '.' ||
                 EXTRACT(MONTH FROM DATECREATE) || '.' ||
                 EXTRACT(YEAR FROM DATECREATE);
    IF (DATECREATE <> DATERESV) THEN
    BEGIN
       UPDATE FOGUEST SET DATERESV = DATECREATE WHERE FOLIO = :FOLIO;
       /*SUSPEND; */
    END
  END
END^


ALTER PROCEDURE XX_ZSA
RETURNS (
    FODATE DATE,
    CATEGORY VARCHAR(4),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    JUR_DB DOUBLE PRECISION,
    JUR_CR DOUBLE PRECISION,
    HIS_DB DOUBLE PRECISION,
    HIS_CR DOUBLE PRECISION,
    DELTA_DB DOUBLE PRECISION,
    DELTA_CR DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT FODATE,CATEGORY,SUM(DEBIT) DB,SUM(CREDIT) CR FROM FO_HIST_ZSA
    WHERE CODE = '1'
    GROUP BY FODATE,CATEGORY

    INTO
      :FODATE,
      :CATEGORY,
      :DB,
      :CR
  DO
  BEGIN
    SELECT SUM(DEBIT),SUM(CREDIT) FROM FOGUEST_JUR
    WHERE CATEGORY = :CATEGORY AND FODATE = :FODATE
    PLAN (FOGUEST_JUR INDEX (FOGUEST_JUR_IDX_CAT))
    INTO JUR_DB,JUR_CR;
    
    SELECT SUM(DEBIT),SUM(CREDIT) FROM FO_HIST_JUR
    WHERE CATEGORY = :CATEGORY AND FODATE = :FODATE
    PLAN (FO_HIST_JUR INDEX (FO_HIST_JUR_IDX_CAT))
    INTO HIS_DB,HIS_CR;
    
    if (JUR_DB IS NULL) then
    BEGIN
       JUR_DB = 0;
       JUR_CR = 0;
    END
    
    if (HIS_DB IS NULL) then
    BEGIN
       HIS_DB = 0;
       HIS_CR = 0;
    END
    DELTA_DB = DB - JUR_DB - HIS_DB;
    DELTA_CR = CR - JUR_CR - HIS_CR;
    if ((DELTA_DB <> 0) or (DELTA_CR <> 0)) then
       SUSPEND;
  END
END^


ALTER PROCEDURE ZZ_EXT_UPDATE
RETURNS (
    EXTENTION VARCHAR(8),
    ROOM VARCHAR(8),
    DEPT VARCHAR(4))
AS
BEGIN
  FOR
    SELECT * FROM ZZ_EXT

    INTO
      :EXTENTION,
      :ROOM,
      :DEPT
  DO
  BEGIN
    IF (ROOM IS NULL) THEN ROOM = '';
       UPDATE PBX_EXTENTION SET ROOM = :ROOM
       WHERE EXTENTION = :EXTENTION;

  END
END^


ALTER PROCEDURE ZZ_TEST
RETURNS (
    CODE VARCHAR(4),
    NAME VARCHAR(40),
    COUNTER INTEGER)
AS
BEGIN
  FOR
    SELECT MR.CODE,CD.NAME,COUNT(*) COUNTER
    FROM FOSYS_MR MR
    LEFT JOIN FOSYS_MR_CODE CD ON MR.CODE = CD.CODE
    WHERE MR.FODATE BETWEEN '13.10.2005' AND '13.11.2005'
    AND MR.STATUS <> 'X'
    GROUP BY MR.CODE,CD.NAME

    INTO
      :CODE,
      :NAME,
      :COUNTER
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE ZZ_TEST_CATEGORY
RETURNS (
    CATEGORY VARCHAR(4),
    NAME VARCHAR(40),
    TAXID SMALLINT,
    TAX_CAT VARCHAR(4),
    TAX_NAME VARCHAR(40),
    TAX_TAXID INTEGER,
    TEXT VARCHAR(20))
AS
declare variable DISTRIBUTION INTEGER;
BEGIN
  FOR
    SELECT CATEGORY,NAME,TAXID FROM FOCATEGORY

    INTO
      :CATEGORY,
      :NAME,
      :TAXID
  DO
  BEGIN
    SELECT FLAG_DISTRIBUTION FROM FOTAX
    WHERE TAXID = :TAXID INTO DISTRIBUTION;

  END
END^


ALTER PROCEDURE ZZ_UPDATE_ADJUSTMENT
RETURNS (
    FOLIO INTEGER,
    SEG VARCHAR(4),
    CAT VARCHAR(4),
    TRANS_ID INTEGER,
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION)
AS
DECLARE VARIABLE FODATE DATE;
BEGIN
  FODATE = '30.5.2005';
  FOR
    SELECT FOLIO,ST_MARKETSEGMENT
      FROM FOSTAT_LOG
    WHERE FODATE = :FODATE
    INTO
      :FOLIO,SEG
  DO
  BEGIN
    SELECT CAT_ROOMADJ FROM fost_segment
    WHERE CODE = :SEG
    INTO CAT;
    
    UPDATE FOGUEST_JUR SET CATEGORY = :CAT,MEAL_PERIOD = '1'
    WHERE FOLIO = :FOLIO
    AND FODATE = :FODATE
/*    AND JURCODE = 'NA' */
    AND CATEGORY = 'ADJ1';
/*    SUSPEND; */
  END
END^


ALTER PROCEDURE ZZ_UPDATE_PACKAGE
RETURNS (
    CATEGORY VARCHAR(4),
    FOLIO INTEGER,
    AMOUNT DOUBLE PRECISION,
    SEG VARCHAR(4),
    SEG_CAT VARCHAR(4),
    NET_PACKAGE DOUBLE PRECISION,
    ROOM_ADJ DOUBLE PRECISION)
AS
declare variable fodate date;
BEGIN
  FODATE = '26.5.2005';
  FOR
    SELECT CATEGORY,FOLIO,DEBIT-CREDIT FROM FOGUEST_JUR J
    WHERE J.CATEGORY = 'PKBF'
    AND J.FODATE = :FODATE
    INTO
      :CATEGORY,
      :FOLIO,
      :AMOUNT
  DO
  BEGIN
    SELECT ST_MARKETSEGMENT FROM FOGUEST
    WHERE FOLIO = :FOLIO
    INTO :SEG;
    SELECT CAT_ROOMADJ FROM FOST_SEGMENT
    WHERE CODE = :SEG
    INTO :SEG_CAT;
    NET_PACKAGE = AMOUNT / 1.21;
    ROOM_ADJ    = AMOUNT * 0.21/1.21;
    SUSPEND;
  END
END^


